local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:718"] = {n="饥肠辘辘",s="为了尽快逃离奥达曼挖掘场，西格鲁·铁斧一行人丢下了马车和箱子。来自柯什营地的食人魔抢走了装有他们所有武器的货车，从那以后，这群人就断粮了。",h="为了尽快逃离奥达曼挖掘场，西格鲁·铁斧一行人丢下了马车和箱子。来自柯什营地的食人魔抢走了装有他们所有武器的货车，从那以后，这群人就断粮了。",kw={"荒芜之地","柯什营地","挖掘场","海市蜃楼","食人魔","西格鲁·铁斧","补给箱","奥达曼"},ang={["faction:Alliance"]="西格鲁·铁斧正在寻求联盟的帮助。"},sec={{t="荒芜之地的饥饿",b="在仓促撤离奥达曼挖掘场时，西格鲁·铁斧和同伴们丢下了许多马车和补给箱。来自柯什营地的食人魔像秃鹫一样搜刮着这些遗弃的物资。他们抢走了装有这群人所有武器的货车，从那以后，他们就再也没吃过东西了。西格鲁承认这非常尴尬，并请求你帮她找回那个补给箱。"},{t="当你回来时",b="当你回来时，西格鲁承认在你离开的时候她吞了一口沙子。西格鲁迅速转移了话题，说他们今晚会出去寻找食物，并且要像国王一样饱餐一顿。"}},faq={{q="西格鲁·铁斧是谁？",a="西格鲁·铁斧是一行人的成员，他们仓促离开了奥达曼挖掘场，现在在荒芜之地陷入了断粮的困境。",al={"西格鲁·铁斧","谁发布海市蜃楼任务","西格鲁是谁"}},{q="为什么西格鲁一行人在挨饿？",a="食人魔抢走了装有他们所有武器和物资的货车，从那以后他们就再也没法弄到食物了。",al={"他们为什么挨饿","为什么没有食物","西格鲁的食物问题"}},{q="谁抢走了被遗弃的补给？",a="当地柯什营地的食人魔，他们一直在搜刮被丢弃的设备。",al={"谁偷了补给箱","柯什营地食人魔","谁抢走了武器"}},{q="西格鲁希望拿回什么？",a="补给箱，那是他们在仓促撤离挖掘场时丢下的。",al={"补给箱","为西格鲁取回什么"}}},fp="7,88,22.360.0,14.186.1,22.116.0,31.97.0,32.73.0,34.94.0"}
P.entries["quest:719"] = {n="矮人的工具",s="勘察员雷杜尔警告说，看起来像是黑铁矮人暗炉氏族的敌人到处都是。他们刚刚袭击了雷杜尔工作的挖掘场，雷杜尔想要回他的幸运矿镐。",h="勘察员雷杜尔警告说，看起来像是黑铁矮人暗炉氏族的敌人到处都是。他们刚刚袭击了雷杜尔工作的挖掘场，雷杜尔想要回他的幸运矿镐。",kw={"荒芜之地","黑铁矮人","挖掘","哈默托","幸运矿镐","雷杜尔","暗炉"},sec={{t="挖掘场袭击者",b="据勘察员雷杜尔所述，黑铁矮人暗炉氏族袭击了他工作的挖掘场。他们杀死了几乎所有人，包括雷杜尔的老板哈默托，而雷杜尔死里逃生。该挖掘场位于雷杜尔所处位置的北面。"},{t="一把幸运矿镐",b="雷杜尔正在想办法夺回一些遗失的货物，尤其是他的幸运矿镐。一定是某个黑铁矮人拿走了它，虽然具体是谁还不确定。雷杜尔希望你能帮忙，他正在哈默托挖掘场南面等着。"}},faq={{q="勘察员雷杜尔是谁？",a="雷杜尔曾在黑铁矮人袭击的挖掘场工作。他死里逃生，现在正在哈默托挖掘场南面等待。",al={"雷杜尔是谁","勘察员雷杜尔","谁发布了矮人和他的工具"}},{q="是谁袭击了挖掘营地？",a="看起来像是暗炉氏族的黑铁矮人。",al={"谁袭击了挖掘场","谁袭击了哈默托","什么袭击了营地"}},{q="哈默托怎么了？",a="哈默托是雷杜尔的老板，在这次袭击中丧生了。",al={"哈默托是谁","哈默托还活着吗","老板哈默托怎么了"}},{q="幸运矿镐在哪里？",a="雷杜尔认为某个黑铁矮人身上带着它，虽然可能是他们中的任何一个。",al={"雷杜尔的幸运矿镐在哪里","如何找到矿镐","谁拿走了雷杜尔的矿镐"}}},fp="21,147,18.228.0,12.234.0,25.140.0,33.79.0,27.69.0,32.99.0"}
P.entries["quest:72"] = {n="斯塔文的传说",s="这段调查将搜索者引向暴风城的运河，管理员弗索姆在那里照看着破败的弗林特里奇家族遗留下的财产。为了寻找关于神秘的斯塔文·密斯曼托的答案，冒险者们必须翻找装箱的遗产，同时还要面对与过去那场大屠杀有关的、不安的灵魂。",h="这段调查将搜索者引向暴风城的运河，管理员弗索姆在那里照看着破败的弗林特里奇家族遗留下的财产。为了寻找关于神秘的斯塔文·密斯曼托的答案，冒险者们必须翻找装箱的遗产，同时还要面对与过去那场大屠杀有关的、不安的灵魂。",kw={"运河","管理员弗索姆","暮色森林","弗林特里奇","弃灵","斯塔文的传说","大屠杀","密封的箱子","暴风城","蒂洛亚"},ang={["class:Priest"]="在城市运河中面对哭泣的弃灵，揭示了那些在生前被谋杀的无辜灵魂挥之不去的痛苦，她们渴望圣光的平静。",["faction:Alliance"]="弗林特里奇家族的静默悲剧就在王国的首都上演，揭示了即使是暴风城最受庇护的贵族血脉也可能被暴力毁灭。"},sec={{t="大屠杀的回响",b="追踪斯塔文的动向将人从暮色森林阴暗的树林中引向暴风城中心。在城市运河旁，管理员弗索姆照看着弗林特里奇家族仅存的这点家当。据弗索姆所言，他的父亲曾在该庄园供职，并承担了清理那场恐怖家族大屠杀后血迹的骇人任务——那是一场以某种方式与斯塔文这个名字联系在一起的悲剧。"},{t="没落家族的拍卖会",b="由于弗林特里奇家族的信托基金已彻底枯竭，且王国税收的秃鹫盘旋不去，该家族幸存的传家宝和打包好的财物已被列入拍卖名单。在流血事件中幸存下来的纪念品和文件被堆放在运河岸边的运输箱里。要揭开斯塔文的线索，就必须在这些庄园遗留的世俗财物被王国各地的收藏家瓜分之前，撬开这些密封的箱子。"},{t="不安的阴影",b="惊动死者的箱子不会不被察觉。谋杀带来的创伤依然附着在这些被抢救出来的财物上，化身为一个复仇的弃灵，攻击任何搜查这些家族遗物的人。这个哭泣的幽影被认为是年轻的蒂洛亚·弗林特里奇的幻影，她依然强烈地依附于她那被突然夺走的生命所留下的实物遗迹上。"}},faq={{q="我在哪里可以找到管理员弗索姆？",a="管理员弗索姆驻扎在暴风城的运河边，站在水道旁的一堆废弃的运输箱和家什附近。",al={"管理员弗索姆位置","弗索姆在哪里","管理员弗索姆在暴风城的什么地方"}},{q="弗林特里奇家族发生了什么事？",a="弗林特里奇一家是一个富裕的家庭，被一场突如其来的残暴大屠杀拆散。正如管理员的传闻所揭示的那样，那场血腥屠杀规模之大，以至于弗索姆的父亲不得不负责清理庄园。谁是罪魁祸首尚不清楚。",al={"弗林特里奇大屠杀","大屠杀是什么","谁杀了弗林特里奇一家"}},{q="为什么家族的财物被打包放在运河边的箱子里？",a="悲剧发生后，弗林特里奇家族的信托基金彻底枯竭。面对王国税务官的压力，庄园幸存的财物被装箱并放置在运河边，等待拍卖清算。",al={"为什么要拍卖弗林特里奇的物品","为什么箱子在运河里","弗林特里奇信托基金"}},{q="为什么打开箱子时会有灵魂发动攻击？",a="大屠杀带来的暴力创伤使受害者的灵魂被束缚在他们生前的财物上。现身保护这些箱子的弃灵被普遍认为是蒂洛亚·弗林特里奇，即遇害儿童之一的幽影。",al={"暴风城的弃灵","弃灵是谁","为什么运河里有鬼魂"}},{q="这与暮色森林有什么联系？",a="调查始于夜色镇，是对斯塔文·密斯曼托的失踪人口查询。追溯他的历史，发现他曾是艾尔文和暴风城弗林特里奇家族的家庭教师。",al={"斯塔文与暮色森林的联系","为什么暮色森林的任务要把我们带到暴风城","斯塔文传说与城市的联系"}},{q="在密封的箱子里能找到什么？",a="翻找打包的家具和个人物品会发现发霉的传家宝，而在底部附近，有一页斯塔文日记的残页，它成为了下一条线索。",al={"箱子里有什么","密封的箱子线索","弗林特里奇的箱内物品"}}},fp="21,200,20.302.0,29.320.0,16.262.1,34.133.0,39.167.0,66.167.0,50.210.0,39.167.0,41.155.0"}
P.entries["quest:720"] = {n="一线希望",s="一张揉皱的地图上潦草地写着几个字：铁趾向雷杜尔发出的求救信号，说他们要把铁趾带去奥达曼，并请求援助。勘察员雷杜尔应该知道铁趾格雷兹还活着。",h="一张揉皱的地图上潦草地写着几个字：铁趾向雷杜尔发出的求救信号，说他们要把铁趾带去奥达曼，并请求援助。勘察员雷杜尔应该知道铁趾格雷兹还活着。",kw={"希望的信号","荒芜之地","粉笔字条","揉皱的地图","铁趾格雷兹","勘察员雷杜尔","奥达曼"},sec={{t="粉笔字迹",b="在这张揉皱的地图上，用粉笔潦草地写着一张落款为铁趾的短条。它写给雷杜尔，内容仅提到他们要把铁趾带去奥达曼，并需要帮助。要带给勘察员雷杜尔的消息是：铁趾格雷兹还活着。"}},faq={{q="揉皱的地图上写着什么？",a="一张用粉笔写的字条，收件人是雷杜尔，署名是铁趾。上面写着他们要把铁趾带去奥达曼，并请求帮助。",al={"字条上写了什么","地图上的粉笔留言","揉皱的地图文本"}},{q="勘察员雷杜尔是谁？",a="这张字条的收件人。你应该去寻找勘察员雷杜尔，并告诉他铁趾格雷兹还活着。",al={"雷杜尔是谁","把揉皱的地图带到哪里"}},{q="字条上说铁趾格雷兹被带到哪里去了？",a="奥达曼。",al={"铁趾被带到了哪里","格雷兹被带到了哪里"}}},fp="14,141,14.188.0,36.110.0,25.97.0,57.58.0"}
P.entries["quest:723"] = {n="铁趾的遗愿",s="铁趾格雷兹在处理伤口的同时，让你带着护符去贫瘠之地找勘察员雷杜尔。雷杜尔知道铁趾在寻找什么，也知道绝不能让黑铁氏族找到它。",h="铁趾格雷兹在处理伤口的同时，让你带着护符去贫瘠之地找勘察员雷杜尔。雷杜尔知道铁趾在寻找什么，也知道绝不能让黑铁氏族找到它。",kw={"希望的征兆","荒芜之地","铁趾格雷兹","铁趾的护符","起源","勘察员雷杜尔","黑铁"},sec={{t="雷杜尔的护符",b="铁趾格雷兹捂着伤口，停下来稳住身形，然后请求你找到雷杜尔并把护符交给他。铁趾确信雷杜尔知道该怎么做。雷杜尔知道铁趾一直在寻找他们族人的起源，而且铁趾也意在挫败黑铁氏族，绝不能让他们得到这些卷轴。"},{t="雷杜尔的接手",b="雷杜尔在收到铁趾的护符后说，当人们以为铁趾已死时，士气反而更高，因为确切的死讯只会让痛苦加剧。雷杜尔称这个护符是铁趾毕生的心血，并誓言他的死不会毫无意义。"}},faq={{q="谁是勘察员雷杜尔？",a="勘察员雷杜尔就是你要将铁趾的护符送去的人，他在荒芜之地。雷杜尔知道铁趾在寻找什么。",al={"勘察员雷杜尔","谁是雷杜尔","雷杜尔在哪里"}},{q="铁趾格雷兹想要阻止什么？",a="铁趾想要阻止黑铁氏族，绝不能让他们得到那些卷轴。",al={"铁趾的目标","黑铁卷轴","为什么要阻止黑铁"}},{q="铁趾格雷兹在寻找什么？",a="据铁趾所言，他在寻找他们族人的起源。",al={"铁趾起源","铁趾在寻找什么"}},{q="这一步属于哪个任务线？",a="这属于以“希望的征兆”为开端的任务线。",al={"信仰的征兆任务线","希望的征兆任务线"}}},fp="17,194,20.238.0,17.232.1,25.121.0,38.87.0,32.50.0,33.62.0"}
P.entries["quest:724"] = {n="铁趾的遗愿",s="勘察员雷杜尔让你带着铁趾的护符前往铁炉堡。史学家卡尼克和铁趾曾经合作寻找奥达曼失落的文物，雷杜尔猜测暗炉部族发现他们知道的信息比表现出来的要多。",h="勘察员雷杜尔让你带着铁趾的护符前往铁炉堡。史学家卡尼克和铁趾曾经合作寻找奥达曼失落的文物，雷杜尔猜测暗炉部族发现他们知道的信息比表现出来的要多。",kw={"荒芜之地","铁趾","铁趾的护符","史学家卡尼克","铁炉堡","信念的展望","勘察员雷杜尔","暗炉部族","奥达曼"},sec={{t="致铁炉堡的消息",b="雷杜尔斟酌着谁可能知道下一步该做什么，最终决定是身在铁炉堡的史学家卡尼克。你要告诉卡尼克铁趾身上发生了什么，并把护符交到这位史学家手中。卡尼克会告知接下来该做什么。"},{t="卡尼克的欢迎",b="卡尼克起初只把你当作另一个来浪费他时间的旅行者，直到你出示了护符。这时卡尼克才认真对待此事，将对铁趾的哀悼暂且搁置，并召唤出铁趾的灵魂向你展示为什么这个护符如此重要。"}},faq={{q="谁开启了这个任务？",a="位于荒芜之地的勘察员雷杜尔让你带着铁趾的护符前往铁炉堡。",al={"谁给予信念的展望","信念的展望任务发布者","哪里开始信念的展望"}},{q="史学家卡尼克在哪里？",a="史学家卡尼克在铁炉堡。",al={"卡尼克在哪里","史学家卡尼克位置","卡尼克铁炉堡"}},{q="为什么要选择史学家卡尼克？",a="卡尼克和铁趾曾经合作寻找奥达曼失落的文物，所以雷杜尔相信卡尼克知道该怎么做。",al={"为什么要将护符送给卡尼克","卡尼克关联"}},{q="这个任务之后是什么？",a="卡尼克的故事线在“传递威胁的消息”中继续。",al={"信念的展望后的下一个任务","信念的展望后续"}}},fp="17,228,23.171.0,16.190.1,22.81.0,34.33.0,32.111.0,28.55.0"}
P.entries["quest:725"] = {n="亡者的警告",s="史学家卡尼克交给你一封给顾问贝尔格拉姆的密封信函。你必须告诉贝尔格拉姆你所目击的一切，并询问他打算如何处理，与此同时，卡尼克将就荒芜之地的黑铁矮人一事向铁趾的灵魂寻求指引。",h="史学家卡尼克交给你一封给顾问贝尔格拉姆的密封信函。你必须告诉贝尔格拉姆你所目击的一切，并询问他打算如何处理，与此同时，卡尼克将就荒芜之地的黑铁矮人一事向铁趾的灵魂寻求指引。",kw={"顾问贝尔格拉姆","荒芜之地","铁趾","史学家卡尼克","铁炉堡","传递威胁的消息","黑铁矮人"},sec={{t="给顾问贝尔格拉姆的口信",b="卡尼克希望你尽快找到顾问贝尔格拉姆，告诉他你所看到的一切，并询问他打算如何处理。信中解释了更多细节。与此同时，卡尼克将与铁趾的灵魂交谈，希望铁趾知道能阻止黑铁矮人在荒芜之地的所作所为的方法，他只能祈祷事实确实如此。"}},faq={{q="是谁派你去找顾问贝尔格拉姆的？",a="史学家卡尼克交给你一封密封的信函，并让你尽快找到顾问贝尔格拉姆。",al={"谁开启了传递威胁的消息","谁给予了传递威胁的消息","卡尼克任务"}},{q="卡尼克希望顾问贝尔格拉姆做些什么？",a="卡尼克希望你将目击的情况告知贝尔格拉姆，并询问他打算如何处理。信中解释了更多情况。",al={"为什么拜访贝尔格拉姆","贝尔格拉姆信函的目的","为什么要发送这封信"}},{q="当你去送信时，史学家卡尼克在做什么？",a="卡尼克打算花时间与铁趾的灵魂交谈，希望能获悉一些有助于阻止荒芜之地黑铁矮人的线索。",al={"卡尼克在做什么","卡尼克的计划","史学家卡尼克荒芜之地"}},{q="“传递威胁的消息”的前置任务是什么？",a="它接续“信仰的前景”任务，在那一步中，你将铁趾的护符带给了铁炉堡的卡尼克。",al={"传递威胁的消息前置条件","传递威胁的消息的上一个任务","前序任务"}}},fp="24,162,24.336.0,33.100.0,43.108.0,58.124.0,49.109.0"}
P.entries["quest:726"] = {n="亡者的警告",s="顾问贝尔格拉姆阅读了史学家卡尼克的字条，并以国王的名义让你带话回去给卡尼克：根据已知情报迅速果断地采取行动，阻止暗炉氏族在荒芜之地的所作所为。",h="顾问贝尔格拉姆阅读了史学家卡尼克的字条，并以国王的名义让你带话回去给卡尼克：根据已知情报迅速果断地采取行动，阻止暗炉氏族在荒芜之地的所作所为。",kw={"苦痛堡垒","荒芜之地","贝尔格拉姆","卡尼克","暗炉氏族","奥达曼"},sec={{t="贝尔格拉姆的答复",b="贝尔格拉姆读完了字条，双眼圆睁，称这是个坏消息。他让你返回卡尼克那里，并以国王的名义传达指示：必须迅速果断地根据这些情报采取行动。暗炉氏族在荒芜之地的活动必须停止。"},{t="卡尼克的回复",b="卡尼克将此视为国王本人的急令，并已准备好了一个计划：通过打击苦痛堡垒来迟滞奥达曼内暗炉氏族的行动，那里正是他们进行运作的大本营。"}},faq={{q="谁让你返回卡尼克那里？",a="顾问贝尔格拉姆，在读过卡尼克的字条后。你带着国王的命令，要求迅速果断地采取行动。",al={"谁下达了命令","贝尔格拉姆的命令","荒芜之地王室权威"}},{q="贝尔格拉姆想怎么处理暗炉氏族？",a="贝尔格拉姆希望卡尼克迅速而坚定地采取行动，并结束暗炉氏族在荒芜之地的所作所为。",al={"贝尔格拉姆想要什么","荒芜之地暗炉氏族指令"}},{q="此前的任务是什么？",a="你在之前的“传递威胁的消息”中将卡尼克的密封字条带给了顾问贝尔格拉姆，该任务是在“信仰的前景”步骤之后进行的。",al={"上一步骤","传递威胁的消息之前的任务","荒芜之地引导任务"}}},fp="24,113,16.229.0,14.154.1,29.119.0,50.99.0,22.127.0"}
P.entries["quest:727"] = {n="远赴铁炉堡",s="迷失者塞尔杜林派遣你去铁炉堡，并带上徽章。在荒弃的洞穴的一家商店里，葛利·硬骨会把你误认为是塞尔杜林躲避的那些人中的一员，你需要向葛利索要雅格因的笔记。",h="迷失者塞尔杜林派遣你去铁炉堡，并带上徽章。在荒弃的洞穴的一家商店里，葛利·硬骨会把你误认为是塞尔杜林躲避的那些人中的一员，你需要向葛利索要雅格因的笔记。",kw={"荒芜之地","荒弃的洞穴","葛利·硬骨","铁炉堡","战锤徽章","迷失者塞尔杜林","雅格因的笔记"},sec={{t="一本古老的书",b="石板告诉了塞尔杜林很多信息，但还远远不够。雅格因在很久以前写下了一本笔记，而塞尔杜林躲避的那些人在许多地方都保留着副本，并由他们最有学识的人进行研读。塞尔杜林认为其中蕴含着可以提供保护的博大知识，并希望将其取回。"},{t="荒弃的洞穴的商店",b="葛利·硬骨在铁炉堡的荒弃的洞穴经营着一家商店。塞尔杜林交给你战锤徽章并让你展示给葛利看，这样你就会被误认为是他们的一员，然后你就可以索要雅格因的笔记了。"},{t="葛利的问候",b="葛利警告你要小心店内触碰的东西，因为知识可能是致命的。当你出示徽章时，葛利会以兄弟或姐妹的身份欢迎你，并赞美地底的居民。"}},faq={{q="为什么塞尔杜林需要雅格因的笔记？",a="石板告诉了塞尔杜林很多信息，但还不够。这本笔记由雅格因在很久以前写成，其中蕴含着可以提供保护的博大知识，塞尔杜林希望能将其取回。",al={"为什么需要雅格因的笔记","雅格因的笔记是什么","雅格因的笔记用途"}},{q="葛利·硬骨在哪里？",a="葛利·硬骨在铁炉堡的荒弃的洞穴里经营着一家商店。",al={"葛利·硬骨在哪里","葛利·硬骨位置","葛利是谁"}},{q="战锤徽章是用来做什么的？",a="塞尔杜林把它交给你是为了展示给葛利·硬骨看，这样葛利就会认为你是塞尔杜林躲避的那群人中的一员。",al={"徽章有什么用","战锤徽章的用途","为什么要使用徽章"}},{q="这个任务在任务链中处于什么位置？",a="它紧接在迷失者塞尔杜林的“毁灭的解决方案”任务之后，并会继续进行任务链的下一步。",al={"去铁炉堡寻找雅格因的笔记之前是什么任务","雅格因任务链顺序"}}},fp="32,203,23.272.0,30.214.0,17.185.1,40.186.0,25.53.0,41.134.0,33.92.0"}
P.entries["quest:728"] = {n="远赴幽暗城",s="迷失者塞尔杜林让你带着一枚徽章前往洛丹伦的幽暗城。你需要让看守者贝尔杜加把你误认为是塞尔杜林所逃避的那些人中的一员，并向这位看守者索要《雅格因的笔记》。",h="迷失者塞尔杜林让你带着一枚徽章前往洛丹伦的幽暗城。你需要让看守者贝尔杜加把你误认为是塞尔杜林所逃避的那些人中的一员，并向这位看守者索要《雅格因的笔记》。",kw={"荒芜之地","贝尔杜加","笔记","战锤","徽章","塞尔杜林","幽暗城","雅格因"},sec={{t="一本写于久远之前的书",b="这块石板告诉了塞尔杜林很多信息，但还远远不够。雅格因在很久以前写下了一本笔记，而塞尔杜林所逃避的那些人在许多地方都保留着副本，并由他们中最博学的人进行研读。塞尔杜林相信其中蕴含着巨大的知识，能够保护他们，因此想要把它找回来。"},{t="幽暗城的看守者",b="看守者贝尔杜加就在洛丹伦的幽暗城。塞尔杜林给了你战锤徽章，让你出示给看守者看，这样你就会被误认为是他们的一员，从而向他索要这本笔记。"},{t="警告之言",b="贝尔杜加把你当作一个热切的收藏追求者来迎接，并警告说知识能让强者更强，却会令弱者疯狂。一旦出示了徽章，贝尔杜加就叮嘱你要谨慎对待这样的标志。有些人并不相信他们的誓言是正义的，还有些人如果知道了他们的存在，就会想方设法让他们失败。那些共同守誓的人必须时刻保持小心、警惕和耐心。"}},faq={{q="是谁派你前往幽暗城的？",a="迷失者塞尔杜林派你带着战锤徽章去寻找看守者贝尔杜加。",al={"谁发布了这个任务","谁给予前往幽暗城寻找雅格因的笔记的任务","任务发布者"}},{q="战锤徽章有什么用？",a="塞尔杜林把它交给你，让你出示给看守者贝尔杜加看，这样看守者就会以为你是塞尔杜林所逃避的那些人中的一员。",al={"战锤徽章的用途","为什么我需要这枚徽章","这枚徽章有什么作用"}},{q="什么是《雅格因的笔记》？",a="这是雅格因在久远年代之前写下的一本书。塞尔杜林说它蕴含着巨大的知识，并由塞尔杜林所逃避的那些人中最博学的一群人进行研读。",al={"什么是雅格因的笔记","雅格因是谁","雅格因之书"}},{q="看守者贝尔杜加在哪里？",a="看守者贝尔杜加待在洛丹伦的幽暗城，你可以在那里找到他。",al={"看守者贝尔杜加的位置","在哪里找到看守者贝尔杜加","贝尔杜加 幽暗城"}},{q="在此之前发生了什么？",a="这是紧接在“毁灭的解决之道”之后的任务。",al={"前置任务","在此之前有什么任务","毁灭的解决之道关联"}}},fp="36,197,23.281.0,27.197.0,17.375.1,31.101.0,36.135.0,24.142.0,26.50.0,22.34.0"}
P.entries["quest:729"] = {n="健忘的勘察员",s="考古学家霍莉在黑海岸南部的一处发掘现场被敌对的石元素攻占后，逃到了奥伯丁。她为她的资深同事感到担忧，请求旅行者火速南下，拯救勘察员雷姆塔维尔。这位受人尊敬的矮人学者在沉迷研究时，对致命的危险常常视而不见。",h="考古学家霍莉在黑海岸南部的一处发掘现场被敌对的石元素攻占后，逃到了奥伯丁。她为她的资深同事感到担忧，请求旅行者火速南下，拯救勘察员雷姆塔维尔。这位受人尊敬的矮人学者在沉迷研究时，对致命的危险常常视而不见。",kw={"奥伯丁","黑海岸","探险者协会","化石","石元素","灰须","霍莉","雷姆塔维尔"},ang={["faction:Alliance"]="这个任务凸显了铁炉堡研究员的合作，他们试图在卡利姆多研究其暗夜精灵盟友那些陌生而古老的土地。",["race:Dwarf"]="对矮人而言，雷姆塔维尔体现了探险者协会那种痴迷的好奇心和狭隘的专注，为了一个未被编目的化石，甚至不惜冒生命危险。"},sec={{t="危险的挖掘",b="考古学家霍莉受探险者协会派遣，在灰须大师的命令下跨海而来，并为能成为勘察员雷姆塔维尔的学徒感到激动不已。雷姆塔维尔因其开创性的发现而在铁炉堡的学术界享有盛誉，他受命调查黑海岸蛮荒海岸线上的古代遗迹。然而，在发掘看似一个古代伟大文明遗迹的过程中，暴躁的石元素从地底喷涌而出，迅速占领了发掘现场。"},{t="无视厄运",b="当霍莉惊慌失措地逃往暗夜精灵的港口奥伯丁寻求帮助时，雷姆塔维尔却几乎连眼皮都没抬一下。这位年迈的勘察员完全沉浸在自己发掘出的遗物中，依然深陷废墟之中，对环绕在营地周围的笨重构造体毫不在意。任何在奥伯丁南部找到他的人，都会发现他并非在恐惧中畏缩，而是在抱怨丢失的石刷和找不见的化石。"}},faq={{q="勘察员雷姆塔维尔是谁？",a="勘察员雷姆塔维尔是隶属于铁炉堡探险者协会的著名矮人研究员。他在矮人学院中以其里程碑式的发现而闻名，同时也因每当贵重遗物在侧时极度缺乏对周围环境的感知而臭名昭著。",al={"雷姆塔维尔","勘察员雷姆塔维尔背景故事","勘察员是谁"}},{q="为什么考古学家霍莉会在奥伯丁？",a="霍莉是由灰须大师指派给雷姆塔维尔担任助手的。当危险的石元素从发掘现场的地面下钻出时，她向北逃往奥伯丁寻求增援，以组织营救。",al={"考古学家霍莉","霍莉 奥伯丁","霍莉为何逃跑"}},{q="矮人们在黑海岸发掘什么？",a="这次探险队发现了黑海岸地下埋藏着一个古代先进社会的证据。在发掘现场被地下的构造体占领之前，雷姆塔维尔发现了一块神秘的化石和各种石制文物。",al={"雷姆塔维尔在挖掘什么","黑海岸挖掘点","雷姆塔维尔 化石"}},{q="在哪里可以找到勘察员雷姆塔维尔？",a="雷姆塔维尔位于黑海岸南部，栖身于奥伯丁以南的古代遗迹中，周围环绕着危险的石元素，他仍在执着地寻找他的石刷和化石。",al={"雷姆塔维尔在哪里","雷姆塔维尔位置","寻找勘察员雷姆塔维尔"}},{q="是谁派出了这支前往黑海岸的探险队？",a="这次探险由铁炉堡的探险者协会组织，并由灰须大师直接指派，他委派霍莉协助雷姆塔维尔对该地区的古代奇观进行编目。",al={"谁派出的霍莉","灰须大师","探险者协会 黑海岸"}},{q="雷姆塔维尔真的有危险吗？",a="是的。敌对的石元素在他周围的废墟中游荡。雷姆塔维尔对迫在眉睫的威胁毫无察觉，完全专注于记录他的发现，并纳闷他的工具和助手都跑到哪儿去了。",al={"雷姆塔维尔死了吗","雷姆塔维尔存活","帮助雷姆塔维尔"}}},fp="28,221,14.427.0,17.354.0,28.215.0,41.166.0,46.205.0,40.191.0,38.186.0,30.178.0"}
P.entries["quest:730"] = {n="黑海岸的麻烦事",s="“黑海岸的麻烦？”是一个联盟入门任务，由达纳苏斯的首席考古学家杜瑟·灰须提供。由于派往海对岸的挖掘队已经失联数周，他感到非常担忧，于是请求旅行者前往奥伯丁调查他们的失踪情况。该任务将矮人的学术考察队与黑海岸那片荒凉而阴暗的海岸连接了起来。",h="“黑海岸的麻烦？”是一个联盟入门任务，由达纳苏斯的首席考古学家杜瑟·灰须提供。由于派往海对岸的挖掘队已经失联数周，他感到非常担忧，于是请求旅行者前往奥伯丁调查他们的失踪情况。该任务将矮人的学术考察队与黑海岸那片荒凉而阴暗...",kw={"考古学家","奥伯丁","黑海岸","达纳苏斯","探险者协会","杜瑟·灰须","霍莉","黑海岸的麻烦"},ang={["faction:Alliance"]="这项任务展示了铁炉堡与达纳苏斯之间日益加强的合作，将泰达希尔与卡利姆多大陆的旅行者联系在一起。",["race:Dwarf"]="对于矮人来说，这个任务涉及探险者协会在各大陆挖掘泰坦传说和古代历史的传统。",["race:NightElf"]="暗夜精灵可能会以审慎的消遣或安静的担忧，来看待这些挥舞着镐头的矮人挖掘者出现在他们祖先的海岸遗迹中。"},sec={{t="沉寂的考察队",b="在宏伟的暗夜精灵主城达纳苏斯，来自铁炉堡的矮人研究员们正在探索卡利姆多的古老谜团。首席考古学家杜瑟·灰须派遣了一支挖掘队跨过海峡前往黑海岸，试图发掘古代文物。然而数周过去了，挖掘队没有发回任何信件或进度报告，这让杜瑟·灰须感到忧心忡忡，担心他的考察队员遇到了他们单枪匹马无法应付的危险。"},{t="未被掩埋的威胁",b="杜瑟·灰须感叹道，许多联盟成员都认为矮人的考古学不过是一种古怪的爱好。然而，在卡兹莫丹的发现让他的同事们相信，一股古老而恐怖的力量正在威胁着从洛丹伦到卡利姆多的整个艾泽拉斯。在黑海岸的遗迹中挖掘不仅仅是一项学术工作，更是一次了解历史大灾变以及埋藏在古代土壤之下的深层威胁的尝试。"},{t="奥伯丁的联络人",b="在从泰达希尔乘船穿过海峡到达奥伯丁的海岸港口后，旅行者会发现考古学家霍莉正在镇上等待。由于首席考古学家派来了援手，她感到如释重负，并向旅行者透露考察队确实陷入了困境，他们在沿海岸向下搜索古代遗物时遇到了麻烦。"}},faq={{q="谁发布了“黑海岸的麻烦？”这个任务？",a="在暗夜精灵主城达纳苏斯，首席考古学家杜瑟·灰须发布了这个任务，他正在寻找勇敢的冒险者去查看失踪队员的情况。",al={"谁发布了黑海岸的麻烦","黑海岸的麻烦任务发布者","在哪接黑海岸的麻烦任务"}},{q="我需要去哪里完成这个任务？",a="你需要从达纳苏斯渡海前往黑海岸的港口城镇奥伯丁，在那里你会找到考古学家霍莉。",al={"我该去哪","交付地点","找谁交付任务"}},{q="为什么矮人考古学家会出现在达纳苏斯和黑海岸？",a="继在卡兹莫丹的近期发现之后，矮人研究员开始调查卡利姆多各处的古代遗址，以发掘关于威胁艾泽拉斯的古老力量的线索。",al={"为什么矮人在达纳苏斯","在黑海岸的矮人","矮人考古卡利姆多"}},{q="找到考古学家霍莉后会发生什么？",a="与奥伯丁的考古学家霍莉交谈后，可以直接开启“健忘的勘察员”任务，要求你深入黑海岸的荒野，寻找勘察员雷姆塔维尔。",al={"接下来是什么","后续任务","下一个任务"}},{q="为什么挖掘队没有发回报告？",a="团队在黑海岸的实地考察中遇到了意想不到的危险和挫折，导致队员们分散开来，无法与达纳苏斯取得联系。",al={"挖掘队发生了什么","为什么他们失踪了","队员失踪"}},{q="杜瑟·灰须提到的隐忧是什么？",a="杜瑟·灰须提到了在卡兹莫丹出土的发现，这些发现暗示着在艾泽拉斯的古老遗迹深处，正沉睡着一种古老且无处不在的危险。",al={"什么古老威胁","杜瑟·灰须的警告","卡兹莫丹的威胁"}}},fp="21,205,19.359.0,16.403.0,20.286.1,42.110.0,45.102.0,58.154.0,48.175.0,45.147.0,48.134.0"}
P.entries["quest:731"] = {n="健忘的勘察员",s="在黑海岸南部的废墟深处，勘察员雷姆塔维尔拒绝离开他的挖掘场，因为他没有带回任何成果向探险者协会交差。尽管他极其健忘，而且还有敌对的穴居人出没，但他坚持要找到一块神秘的化石才肯撤退。确保这位矮人研究员在反常的搜寻中幸存下来，可以让他的安全消息传回奥伯丁的助手那里。",h="在黑海岸南部的废墟深处，勘察员雷姆塔维尔拒绝离开他的挖掘场，因为他没有带回任何成果向探险者协会交差。尽管他极其健忘，而且还有敌对的穴居人出没，但他坚持要找到一块神秘的化石才肯撤退。确保这位矮人研究员在反常的搜寻中幸存下来...",kw={"奥伯丁","黑海岸","护送","挖掘","探险者协会","化石","霍莉","雷姆塔维尔","穴居人"},ang={["faction:Alliance"]="确保雷姆塔维尔及其发现的安全，维持了矮人探险者协会与泰达希尔暗夜精灵之间至关重要的外交与学术合作。",["race:Dwarf"]="对于矮人来说，雷姆塔维尔体现了探险者协会无情的激情和危险的固执，展现了对古代泰坦知识的奉献如何使学者对迫在眉睫的危险视而不见。",["race:NightElf"]="卡多雷通常以警惕的态度看待黑海岸的矮人挖掘活动；雷姆塔维尔挖掘出成群的暴力穴居人证实了他们对于在神圣土地上过度挖掘的担忧。"},sec={{t="危险的挖掘",b="雷姆塔维尔的挖掘场位于黑海岸南部，坐落在本应隐藏着被遗忘秘密的古代废墟之中。然而，矮人挖掘者意外地挖出了大群凶猛的穴居人，工人被驱赶走，营地也被围困。虽然大多数人会立即逃往奥伯丁，但勘察员雷姆塔维尔却执着于挽救他的发现。他不愿空手而归，因此冒险深入险境，试图寻回一块难以捉摸的化石，以便向探险者协会证明此次探险的成本是合理的。"},{t="混乱的记忆与穴居人的伏击",b="保护雷姆塔维尔的过程既令人沮丧又充满危险。他那丢三落四的本性使他在挖掘场四处乱转，把刷子错当成化石，跌跌撞撞地越过脚手架和废弃的帐篷。每一次停留都会吸引潜伏在采石场阴暗角落里的凶猛穴居人的注意。在护送者消灭了一波又一波地底野兽之后，这位学者终于记起他的奖品在哪里：他已经把化石交给霍莉了，于是他高高兴兴地回去工作了。"}},faq={{q="勘察员雷姆塔维尔是谁？",a="勘察员雷姆塔维尔是矮人探险者协会的一名资深实地研究员。他驻扎在黑海岸，负责挖掘沿海的古代废墟，但他极度的健忘经常使他陷入危及生命的境地。",al={"雷姆塔维尔","勘察员是谁","健忘的勘察员"}},{q="为什么雷姆塔维尔还待在挖掘场？",a="尽管挖掘场被穴居人占领，但雷姆塔维尔在没有带回切实的工作成果前，拒绝返回达纳苏斯。他坚持要找到一块神秘的化石交给探险者协会，才考虑放弃营地。",al={"为什么待在挖掘场","雷姆塔维尔为什么在那里","为什么他没有逃走"}},{q="穴居人是从哪里来的？",a="和许多矮人挖掘活动一样，雷姆塔维尔的团队向地底深处挖掘，无意中打通了穴居人居住的地底洞穴。这些原始生物成群结队地涌出地面，暴力地摧毁了机械、帐篷和工人。",al={"黑海岸为什么有穴居人","黑海岸穴居人","挖掘场穴居人"}},{q="考古学家霍莉是谁？",a="考古学家霍莉是雷姆塔维尔的同事兼助手，驻扎在沿海城镇奥伯丁。她对导师长时间的缺席感到心烦意乱，并且非常了解他健忘的习惯，因此她招募旅行者去寻找他，以确保他能安全返回。",al={"霍莉","考古学家霍莉","雷姆塔维尔的助手"}},{q="找到化石后会发生什么？",a="在帮助雷姆塔维尔搜寻完挖掘场后，向奥伯丁的考古学家霍莉报告他的安全情况。",al={"任务后续","接下来做什么","护送雷姆塔维尔之后"}}},fp="28,251,21.333.0,35.415.1,28.223.0,39.180.0,31.175.0,28.213.0,38.98.1"}
P.entries["quest:732"] = {n="大地的震颤",s="加瑞克听西格鲁说了你帮了多少忙，现在轮到他请求你的帮助了。加瑞克的导师，肯瑞托的Krasus，派遣加瑞克来阻止莱瑟罗峡谷中正在酝酿的一切，首先必须找到被窃的大地印章。",h="加瑞克听西格鲁说了你帮了多少忙，现在轮到他请求你的帮助了。加瑞克的导师，肯瑞托的Krasus，派遣加瑞克来阻止莱瑟罗峡谷中正在酝酿的一切，首先必须找到被窃的大地印章。",kw={"苦痛堡垒","博夫营地","黑铁矮人","死亡之翼","加瑞克","肯瑞托","克拉苏斯","莱瑟罗峡谷","大地印章"},sec={{t="严守的秘密",b="加瑞克的导师，肯瑞托的Krasus，派遣他前往荒芜之地，阻止莱瑟罗峡谷中正在酝酿的麻烦。具体任务内容不能透露，只能告诉你此事关系重大。一群流浪食人魔经常在博夫营地附近出没，他们拿走了大地印章，加瑞克需要它。把它带回来，你就能了解更多情况。"},{t="游荡的食人魔",b="食人魔在荒芜之地各处的营地间移动，炎热的温度和盘旋的风沙让它们的踪迹难以追踪。加瑞克听说它们有时会经过博夫营地，如果你找不到它们了，那里是个不错的搜寻地点。"},{t="加瑞克的解释",b="当你带着印章回来时，加瑞克告诉你，苦痛堡垒的黑铁矮人制作了它，目的是为了束缚死亡之翼的双子副官，冷酷的布莱克拉什和赫玛图斯。"}},faq={{q="加瑞克为谁效力？",a="加瑞克的导师是肯瑞托的克拉苏斯，他派遣加瑞克前往荒芜之地，以阻止莱瑟罗峡谷中正在酝酿的麻烦。",al={"谁派遣了加瑞克","加瑞克的导师","克拉苏斯与荒芜之地"}},{q="大地印章是什么？",a="游荡的食人魔偷走了它，加瑞克需要找回它。等你把它带回来，加瑞克会告诉你更多信息。",al={"大地印章","大地印章是什么","大地印章背景"}},{q="在哪里可以找到游荡的食人魔？",a="它们在荒芜之地各处的营地之间游荡，加瑞克听说它们有时会经过博夫营地。",al={"食人魔在哪里","食人魔与博夫营地","大地印章在哪里"}},{q="为什么加瑞克要保密任务内容？",a="加瑞克不愿透露任务内容或所需工作，只说它至关重要。",al={"为什么要保密","加瑞克的秘密任务"}}},fp="20,219,19.300.0,19.211.0,14.168.1,25.115.0,30.98.0,39.104.0,42.100.0"}
P.entries["quest:7321"] = {n="海龟汤",s="舒心龟肉浓汤是塔伦米尔的克里斯托弗·杰弗寇特提供的一项烹饪任务。这位被遗忘者厨师旨在通过制作这种用当地咬鳖肉熬制的浓汤，来驳斥亡灵缺乏烹饪天赋的说法。玩家必须在希尔斯布莱德丘陵的水域和洛丹米尔湖的湖岸边狩猎淡水龟，以掌握他珍视的食谱。",h="舒心龟肉浓汤是塔伦米尔的克里斯托弗·杰弗寇特提供的一项烹饪任务。这位被遗忘者厨师旨在通过制作这种用当地咬鳖肉熬制的浓汤，来驳斥亡灵缺乏烹饪天赋的说法。玩家必须在希尔斯布莱德丘陵的水域和洛丹米尔湖的湖岸边狩猎淡水龟，以掌握...",kw={"克里斯托弗·杰弗寇特","烹饪","希尔斯布莱德丘陵","洛丹米尔湖","咬鳖","舒心龟肉浓汤","塔伦米尔","龟肉"},ang={["faction:Horde"]="支持塔伦米尔的驻军不仅仅涉及保卫其边界；保持供应充足和士气高昂有助于巩固部落在饱受争夺的希尔斯布莱德的立足点。",["profession:Cooking"]="这项任务允许厨师掌握舒心龟肉浓汤，将洛丹米尔湖和希尔斯布莱德河流中的凶猛爬行动物变成一道恢复元气的餐点。",["race:Undead"]="克里斯托弗·杰弗寇特代表了被遗忘者更为轻松、注重技艺的一面，坚持认为死亡并没有磨灭他对烹饪的热情。"},sec={{t="被遗忘者的烹饪艺术",b="人们普遍认为被遗忘者已经完全抛弃了生活的舒适，包括享受美食的艺术。驻扎在塔伦米尔的克里斯托弗·杰弗寇特强烈反对这种假设。杰弗寇特夸口说他的浓郁、舒心的龟肉浓汤美味到足以将灵魂从坟墓中唤回，他试图证明即便是在这片被瘟疫和战争玷污的土地上，亡灵的手也能做出精致、暖心的工艺品。"},{t="猎杀咬鳖",b="通常情况下，杰弗寇特会亲自从希尔斯布莱德丘陵的水域以及邻近奥特兰克的洛丹米尔湖东岸采集原料。然而，塔伦米尔的任务和步步紧逼的联盟部队让他脱不开身。他只能依靠过往的部落厨师来猎杀咬鳖，采集肉块并带回来，好让这项烹饪传统得以延续。"}},faq={{q="为什么被遗忘者厨师会关心制作热浓汤？",a="虽然被遗忘者不需要像活着的凡人那样维持生计，但像克里斯托弗·杰弗寇特这样的人对他们的手艺感到非常自豪。杰弗寇特旨在驳斥亡灵缺乏精细技巧的偏见，并开玩笑说他的招牌浓汤美味到足以让逝者复活。",al={"亡灵烹饪","为什么要制作浓汤","亡灵进食"}},{q="在这个食谱中，可以在哪里找到龟肉？",a="龟肉是从居住在希尔斯布莱德丘陵和奥特兰克流经的河流沿岸，以及洛丹米尔湖岸边的凶猛咬鳖身上采集的。",al={"海龟在哪里","海龟位置","咬鳖位置"}},{q="为什么克里斯托弗·杰弗寇特不能亲自采集原料？",a="杰弗寇特声称他被塔伦米尔的职责缠身。他还对附近步步紧逼的联盟部队表示恼火，这使得个人的狩猎远足变得更加危险。",al={"为什么克里斯托弗不去","杰弗寇特困在镇子里"}},{q="接受这个任务需要烹饪知识吗？",a="是的。克里斯托弗·杰弗寇特只会与烹饪专业的同行分享他的技艺和食谱，尽管开始时并不需要任何高级的掌握程度。",al={"我需要烹饪吗","烹饪专业要求"}},{q="塔伦米尔对希尔斯布莱德的部落来说有多重要？",a="塔伦米尔是希尔斯布莱德丘陵主要的部落据点。它曾经是一个人类村庄，现在作为被遗忘者及其盟友的防御基地，经常面临与南海镇和当地联盟势力的冲突。",al={"什么是塔伦米尔","塔伦米尔背景故事"}},{q="龟肉浓汤是部落独有的吗？",a="联盟的厨师可以从南海镇当地也会利用当地龟类资源的人类厨师那里获得食谱，但克里斯托弗·杰弗寇特的个人任务和视角是部落独有的。",al={"联盟版本","联盟可以获得龟肉浓汤吗"}}},fp="22,190,19.346.0,20.316.0,54.207.0,47.127.0,56.123.0,49.100.0,59.215.0,37.178.0"}
P.entries["quest:733"] = {n="搜集行动",s="西格鲁·铁斧需要材料来为营地建造防御工事及其他必需品，并注意到附近的食人魔携带着大量的废金属。西格鲁想要七块废金属。",h="西格鲁·铁斧需要材料来为营地建造防御工事及其他必需品，并注意到附近的食人魔携带着大量的废金属。西格鲁想要七块废金属。",kw={"荒芜之地","火山洞穴","探险者协会","铁炉堡","食人魔","废金属","搜刮废料","西格鲁·铁斧"},sec={{t="营地材料短缺",b="西格鲁发现没有材料来建造防御工事和其他必需品十分困难，探矿者也一直担心这个小营地的状况。西格鲁想尽快开始工作，因此需要废金属。"},{t="食人魔的废料",b="该地区的食人魔似乎有充足的废金属储备，这让西格鲁认为关于荒芜之地有攻城机器的传言可能并非空穴来风。它们的主要营地是位于西格鲁营地以西长途跋涉之处的火山洞穴。"}},faq={{q="谁在索要废金属？",a="西格鲁·铁斧，她想要这些材料来为营地建造防御工事及其他必需品。",al={"任务发布者","谁发布了“搜刮废料”","西格鲁"}},{q="为什么营地需要废金属？",a="西格鲁缺少建造防御工事和其他必需品的材料，而且探矿者一直担心这个营地的状况。",al={"为什么需要废金属","废金属的用途","防御工事"}},{q="在哪里可以找到废金属？",a="该地区的食人魔携带这些东西。它们的主要营地是位于西格鲁营地以西长途跋涉之处的火山洞穴。",al={"废金属位置","去哪里获取废金属","食人魔营地"}},{q="这之前有什么任务？",a="它紧接在“海市蜃楼”之后。",al={"前置任务","“搜刮废料”的前提条件"}}},fp="10,123,25.189.0,16.162.0,34.71.0,35.98.0,35.106.0,23.19.0"}
P.entries["quest:734"] = {n="不祥的感觉",s="鲁特维尔·沃拉图斯正忙于处理一副镣铐，他让你去荒芜之地找卢希恩·枪穗谈谈。鲁特维尔需要一个5号齿轮，并要求你把它带回来。",h="鲁特维尔·沃拉图斯正忙于处理一副镣铐，他让你去荒芜之地找卢希恩·枪穗谈谈。鲁特维尔需要一个5号齿轮，并要求你把它带回来。",kw={"荒芜之地","5号齿轮","鲁特维尔·沃拉图斯","卢希恩·枪穗","镣铐"},sec={{t="5号齿轮",b="鲁特维尔抬头瞥了你一眼，随即又弯下腰继续处理那副镣铐。你要去和卢希恩·枪穗谈谈，因为鲁特维尔需要一个5号齿轮，并让你把它带回来。"},{t="卢希恩的裁决",b="一提到5号齿轮，卢希恩·枪穗对事情的结果感到不太乐观。"}},faq={{q="这个任务是谁给的？",a="鲁特维尔·沃拉图斯，他正在荒芜之地制作一副镣铐。",al={"谁发布此任务","鲁特维尔·沃拉图斯任务","任务发布者"}},{q="鲁特维尔需要什么？",a="一个5号齿轮，鲁特维尔让你在和卢希恩·枪穗谈过之后把它带回来。",al={"鲁特维尔想要什么","哪个齿轮","5号齿轮"}},{q="关于齿轮我应该和谁谈？",a="鲁特维尔让你去荒芜之地找卢希恩·枪穗。",al={"哪里寻找5号齿轮","卢希恩是谁","卢希恩·枪穗"}}},fp="24,111,15.147.0,16.86.1,21.76.0,22.92.0,32.56.0"}
P.entries["quest:735"] = {n="星，手，心",s="铁炉堡的葛利·硬骨有一本多余的《雅格因的笔记》，并愿意用三件充满力量的物品来交换。葛利不愿大声说出这些物品的名字，而是把它们写在了一张纸条上。",h="铁炉堡的葛利·硬骨有一本多余的《雅格因的笔记》，并愿意用三件充满力量的物品来交换。葛利不愿大声说出这些物品的名字，而是把它们写在了一张纸条上。",kw={"硬骨的纸条","葛利·硬骨","达古恩之手","铁炉堡","传承之心","希尔耶之星","雅格因的笔记"},sec={{t="闭口不言的交易",b="葛利听出你在打听《雅格因的笔记》，不禁好奇你是不是要在什么地方开启他们教团的新篇章，但他随即觉得这不该由他来过问。葛利手头正好有一本多余的笔记，并认为教团成员之间理应互相帮助。作为交换，你必须带来三件充满力量的物品。这些物品的名字不能宣之于口，以免隔墙有耳，所以葛利把它们写了下来。"},{t="这三件物品",b="纸条上写着希尔耶之星、达古恩之手和传承之心。这些就是他在交出笔记之前索要的东西。"},{t="葛利的评价",b="一旦你把这些圣物交到他手中，葛利会夸赞你足智多谋，并相信如果创建教团新篇章的任务确实由你负责，你一定能将其经营得很好。"}},faq={{q="是谁索要这三件物品？",a="铁炉堡的葛利·硬骨，他有一本多余的《雅格因的笔记》可以用来交换。",al={"任务发布者","谁开启了星、手与心任务","葛利·硬骨任务"}},{q="葛利·硬骨需要哪三件物品？",a="葛利·硬骨的纸条上要求三样东西：希尔耶之星、达古恩之手和传承之心。",al={"所需物品","他需要哪些圣物","硬骨纸条上的物品"}},{q="为什么葛利要把这些物品写下来而不是说出来？",a="葛利不愿说出它们的名字是因为担心隔墙有耳。",al={"为什么要写下来","为什么要用秘密纸条","硬骨低语"}},{q="这个任务链的前序任务是什么？",a="此任务紧接“为了雅格因的笔记前往铁炉堡”，在那里，迷失者塞尔杜林指引你去找葛利。",al={"前置任务","上一个任务"}}},fp="32,154,30.392.0,15.140.0,16.158.1,29.104.0,43.89.0,60.62.0,35.89.0"}
P.entries["quest:736"] = {n="星，手，心",s="“星辰、手与心”是一项幽暗城的任务，看守者贝尔杜加会在此考验一位寻求建立新分会的有志领袖。为了获得至关重要的雅格因的笔记，请求者必须追踪到三件力量之物，而贝尔杜加不敢大声说出它们的名字。",h="“星辰、手与心”是一项幽暗城的任务，看守者贝尔杜加会在此考验一位寻求建立新分会的有志领袖。为了获得至关重要的雅格因的笔记，请求者必须追踪到三件力量之物，而贝尔杜加不敢大声说出它们的名字。",kw={"贝尔杜加的便条","看守者贝尔杜加","组织","星辰、手与心","三件力量之物","幽暗城","雅格因的笔记"},ang={["class:Warlock"]="获取雅格因的笔记以建立一个新的群体，是扩展你黑暗组织的影响力和神秘掌控力的关键一步。",["race:Undead"]="看守者贝尔杜加在幽暗城运作，引导着那些寻求在城市阴影尖塔下深入钻研禁忌仪式的被遗忘者从业者。"},sec={{t="兄弟会的考验",b="在幽暗城阴影笼罩的走廊深处，有野心的从业者如果想要领导自己的圈子，就会向看守者贝尔杜加寻求帮助。为了建立一个新的群体并开启分会，有志领袖需要得到雅格因的笔记，这是一本由看守者守护的仪式知识权威典籍。贝尔杜加随时准备支持他的兄弟，但在交出这种权力之前，他要求对方证明自己的价值。"},{t="不可言说的圣物",b="看守者贝尔杜加不会轻易交出雅格因的笔记。他需要三件独特的力量之物来完成交换。这些圣物具有极度危险或神圣的意义，以至于它们的名字甚至无法大声说出；贝尔杜加将它们写在了一张私人便条上。只有有能力追踪并找回这三件不可言说的圣物的从业者，才证明自己有资格建立自己的分会。"}},faq={{q="看守者贝尔杜加是谁？",a="看守者贝尔杜加是幽暗城的一位神秘人物，他会协助其黑暗兄弟会的成员。他守护着强大的知识，并要求候选人在委托给他们神圣典籍之前证明自己的能力。",al={"看守者贝尔杜加是谁","贝尔杜加的角色","贝尔杜加幽暗城"}},{q="什么是雅格因的笔记？",a="雅格因的笔记是一本专门的教学文本，对于在秘密的神秘组织内建立和领导一个新的分会或聚集一个新群体来说是必不可少的。",al={"什么是雅格因的笔记","雅格因的笔记用途","雅格因的笔记书籍"}},{q="看守者贝尔杜加要求获得什么物品？",a="贝尔杜加需要三件特定的力量之物。由于它们的名字太过禁忌或危险而无法大声说出，他将它们悄悄写在一张便条上，供请求者去回收。",al={"贝尔杜加需要什么物品","贝尔杜加的便条物品","三件力量之物"}},{q="为什么请求的物品名字不能大声说出来？",a="看守者贝尔杜加明确指出，他无法大声说出这三件圣物的名字，这表明它们拥有黑暗、神圣或不稳定的力量，需要格外谨慎。",al={"为什么贝尔杜加不能说出物品名称","无法说出名字","不可言说的物品名称"}},{q="聚集另一个群体意味着什么？",a="聚集群体是指招募追随者并建立一个功能独立的兄弟会分会，证明一个人已准备好指导其他从业者。",al={"聚集群体意味着什么","开启分会","我们的组织分会"}},{q="这项任务的核心地点在哪里？",a="这项任务以看守者贝尔杜加为中心，他驻扎在被遗忘者地下的首都——幽暗城内。",al={"这项任务发生在哪里","贝尔杜加的位置","任务交付地点"}}},fp="32,178,21.311.0,19.280.0,24.186.0,24.123.0,41.118.0,58.118.0,42.136.0,29.90.0"}
P.entries["quest:737"] = {n="禁断的知识",s="雅格因的笔记被交给了你，并告诫你要妥善保管，切勿落入不友善之手。你需要把它交给迷失者塞尔杜林。",h="雅格因的笔记被交给了你，并告诫你要妥善保管，切勿落入不友善之手。你需要把它交给迷失者塞尔杜林。",kw={"荒芜之地","禁忌的知识","星、手与心","迷失者塞尔杜林","雅格因的笔记"},sec={{t="一本会灼伤人的书",b="铁炉堡的葛利·硬骨或幽暗城的看守者贝尔杜加会把这份笔记交给你。他们告诫你要妥善保管，切勿落入不友善之手，因为它承载了许多真理，而真理往往会灼伤人。把它交给迷失者塞尔杜林。"},{t="塞尔杜林的希望",b="塞尔杜林呼喊着希望的微光，并说你的努力或许能拯救所有人，让人们为你立碑、建龛，并让你的名字被后世世代传颂。但这一切的前提是，不能让“它们”重见天日并来到地表，否则，塞尔杜林说，所有人都会成为蠕虫的食物。"}},faq={{q="需要交付什么物品？",a="雅格因的笔记，一本承载了许多真理的书。它必须被严加保管，切勿落入不友善之手。",al={"这是什么书","什么是雅格因的笔记","我要带什么东西"}},{q="谁来接收这份笔记？",a="这份笔记是交给迷失者塞尔杜林的。",al={"谁会收到这本书","我要把它交给谁","笔记要送到哪里"}},{q="此任务之前发生了什么？",a="在此之前，你需要集齐三件物品来换取这份笔记。",al={"前置任务","什么任务引出这个任务","禁忌的知识之前的任务是什么"}}},fp="19,93,17.215.0,16.268.1,32.99.0,24.49.0,22.82.0"}
P.entries["quest:738"] = {n="寻找阿戈莫德",s="勘察员基恩萨·铁环已经几周没有阿戈莫德的消息了。阿戈莫德负责荒芜之地的挖掘场，铁环希望能找到他，以便收集报告。",h="勘察员基恩萨·铁环已经几周没有阿戈莫德的消息了。阿戈莫德负责荒芜之地的挖掘场，铁环希望能找到他，以便收集报告。",kw={"阿戈莫德","苦痛堡垒","荒芜之地","铁炉堡","勘察员基恩萨·铁环"},sec={{t="沉默的勘察员",b="阿戈莫德负责西南方向荒芜之地的挖掘工作。铁环特意用了“负责”这个词，因为阿戈莫德已经几周音讯全无了。铁环想要找到阿戈莫德，并拿回他手中的报告。人们最后一次得到阿戈莫德的消息是在荒芜之地最南端的挖掘场，那是一个位于苦痛堡垒之外的小型营地，搜寻工作应该从那里开始。"},{t="线索终点",b="在搜寻的终点，你发现了一具骸骨，这一定就是阿戈莫德的遗骸。尸体破碎不堪，骨头已经被啃食殆尽。"}},faq={{q="谁是勘察员阿戈莫德？",a="阿戈莫德负责勘察员基恩萨·铁环西南方向荒芜之地的挖掘工作。",al={"谁是阿戈莫德","阿戈莫德是谁","阿戈莫德背景故事"}},{q="为什么勘察员基恩萨·铁环要寻找阿戈莫德？",a="铁环已经几周没有阿戈莫德的消息了，他想要拿到阿戈莫德的报告。",al={"为什么要寻找阿戈莫德","铁环寻找阿戈莫德"}},{q="勘察员阿戈莫德最后出现在哪里？",a="在荒芜之地最南端的挖掘场，一个位于苦痛堡垒之外的小型营地。",al={"阿戈莫德位置","阿戈莫德挖掘场在哪里","阿戈莫德最后在哪里"}},{q="在这个任务链中，上一步是什么？",a="它是“铁环需要你！”的任务后续。",al={"上一个任务","寻找阿戈莫德的前置任务"}}},fp="11,151,19.307.0,20.154.1,25.92.0,46.80.0,45.98.0,36.30.0"}
P.entries["quest:739"] = {n="莫达洛克",s="阿格蒙德的残骸躺在荒芜之地，死者手边的砂岩上潦草地写着一个名字：穆达洛克。必须除掉阿格蒙德的凶手，并将消息带回洛克莫丹交给勘察员基恩萨·铁环。",h="阿格蒙德的残骸躺在荒芜之地，死者手边的砂岩上潦草地写着一个名字：穆达洛克。必须除掉阿格蒙德的凶手，并将消息带回洛克莫丹交给勘察员基恩萨·铁环。",kw={"阿格蒙德","荒芜之地","洛克莫丹","穆达洛克","勘察员基恩萨·铁环","石库食骨者","穴居人"},sec={{t="砂岩上的名字",b="阿格蒙德的足迹从西边延伸而来，石头和沙子上涂抹的血迹诉说着这位矮人在死前挣扎了多远。在毫无生气的遗体旁，荒芜之地的砂岩上刻着一个词：穆达洛克。必须杀死阿格蒙德的凶手，还要解决掉一些石库食骨者，并将消息带给洛克莫丹的勘察员基恩萨·铁环。"},{t="铁环的回信",b="铁环严肃地接受了消息，他记得阿格蒙德是个臂力过人、挥锤凶猛且性格固执的矮人。铁环说阿格蒙德是被受诅咒的穴居人杀死的，并确信他在临死前也解决了不少敌人。"}},faq={{q="阿格蒙德是谁？",a="阿格蒙德是一名矮人，负责为勘察员基恩萨·铁环管理荒芜之地的挖掘场。你对阿格蒙德的搜寻最终在一具骸骨处结束了。",al={"阿格蒙德是谁","阿格蒙德背景故事"}},{q="穆达洛克是谁？",a="穆达洛克是刻在阿格蒙德遗体旁砂岩上的名字。你需要杀死阿格蒙德的凶手，穆达洛克。",al={"穆达洛克是什么","穆达洛克背景故事"}},{q="报告需要送到哪里？",a="送到洛克莫丹的勘察员基恩萨·铁环那里。",al={"我该向谁汇报穆达洛克的事","铁环在哪里"}}},fp="8,162,23.321.0,16.245.1,15.133.0,16.108.0,33.54.0"}
P.entries["quest:74"] = {n="斯塔文的传说",s="调查的这一步骤将把你引向暴风城运河旁遗留的一只旧箱子，里面装满了弗林特里奇家族的传家宝。在布满灰尘的遗物中仔细搜寻，你会发现一张被撕破的日记书页，这为斯塔文·密斯特曼托的过去生活提供了关键的手写线索，并引导你前往艾尔文森林寻找哈格德警官。",h="调查的这一步骤将把你引向暴风城运河旁遗留的一只旧箱子，里面装满了弗林特里奇家族的传家宝。在布满灰尘的遗物中仔细搜寻，你会发现一张被撕破的日记书页，这为斯塔文·密斯特曼托的过去生活提供了关键的手写线索，并引导你前往艾尔文森...",kw={"暮色森林","艾尔文森林","弃灵","哈格德警官","密斯特曼托","密封的箱子","斯塔文","一张被撕破的日记书页"},ang={["faction:Alliance"]="调查艾尔文森林中心的一些旧悬案揭示了那些个人的恐怖往事是如何在暴风城警官的眼皮底下被遗漏的。",["race:Human"]="哈格德警官代表了暴风城年迈的退伍军人一代，保留着第一次和第二次战争将家庭拆散之前关于王国的宝贵记忆。"},sec={{t="发掘过去",b="当调查员在翻找一只装满陈旧传家宝、古老狩猎战利品和家族肖像的密封的箱子时，在一只陶瓷花瓶下发现了一张被撕破的日记书页。这篇文字是斯塔文·密斯特曼托亲笔所写，让人们得以窥见这位隐居学者在悲剧发生前那段深藏心底的思绪。"},{t="警官日益模糊的视力",b="哈格德警官如今已上了年纪，且深受视力衰退的困扰，很难看清那张破损羊皮纸上的字迹。即便如此，那独特的笔迹仍让他感到一丝不安，让他回想起了黑暗降临、夺去他的视力之前，那些往年的文档与事件。"}},faq={{q="密封的箱子在哪里？",a="密封的箱子位于暴风城运河旁，就在管理员弗索姆的身后，夹杂在弗林特里奇家族打包好的行李中。在那里找到的书页随后会被送往艾尔文森林东南部的哈格德警官手中。",al={"箱子位置","箱子在哪里","哈格德的箱子"}},{q="密封的箱子里有什么？",a="箱子里装有满是灰尘的传家宝、一幅家族肖像、旧书、狩猎战利品和一个陶瓷花瓶，在花瓶下放着一张从斯塔文日记中撕下的书页。",al={"箱子内容物","箱子里有什么","被撕破的书页箱子"}},{q="哈格德警官是谁？",a="哈格德警官是一位年迈的暴风城退休官员，独自居住在艾尔文森林南部。尽管他视力衰退且身体虚弱，但他对旧时记录和旅行者的记忆使他成为了解过去事件的关键证人。",al={"谁是哈格德","哈格德警官背景故事","艾尔文森林的老警官"}},{q="为什么这张日记书页很重要？",a="这张被撕破的日记书页是斯塔文·密斯特曼托亲笔写下的直接证据。其独特的笔迹和残留的思绪有助于将暮色森林和艾尔文森林各处零散的记录与他个人的堕落联系起来。",al={"为什么被撕破的书页很重要","日记书页线索","斯塔文的日记"}},{q="打开箱子会发生什么？",a="惊扰斯塔文往事的残留物会唤醒不安的亡灵，导致一个充满复仇之心的弃灵现身，并攻击那些试图揭开这场悲剧真相的人。",al={"弃灵刷新","箱子后的鬼魂","为什么鬼魂攻击我"}},{q="接下来的调查方向是什么？",a="在将这张被撕破的书页交给哈格德警官后，他对笔迹的回忆将引导调查继续深入，去寻找更多幸存的斯塔文历史碎片。",al={"下一步","被撕破的书页之后","接下来要去哪里"}}},fp="21,171,19.265.0,24.200.1,34.215.0,32.158.0,23.226.0,35.183.0,38.152.0,39.152.0"}
P.entries["quest:741"] = {n="健忘的勘察员",s="这项差事将一件从黑海岸荒野海滩上发现的奇异石化标本送往达纳苏斯的探险者协会前哨站。考古学家霍莉拒绝抛下她那心不在焉的同事，转而委托一名路过的冒险者来运输这份标本。这份化石抵达暗夜精灵首都后，立刻引起了首席考古学家杜瑟·灰须的浓厚兴趣。",h="这项差事将一件从黑海岸荒野海滩上发现的奇异石化标本送往达纳苏斯的探险者协会前哨站。考古学家霍莉拒绝抛下她那心不在焉的同事，转而委托一名路过的冒险者来运输这份标本。这份化石抵达暗夜精灵首都后，立刻引起了首席考古学家杜瑟·灰...",kw={"考古学家","黑海岸","达纳苏斯","探险者协会","化石","杜瑟·灰须","霍莉","雷姆塔维尔"},ang={["faction:Alliance"]="这项任务展示了联盟成员之间在后勤方面的相互依赖，因为矮人研究员需要依靠旅行冒险者来安全地连接黑海岸偏远的海岸和达纳苏斯的高地。",["race:Dwarf"]="运送雷姆塔维尔的化石履行了探险者协会的首要使命：发掘世界深处的过去，并证明矮人坚持不懈的无限价值。",["race:NightElf"]="看着矮人挖掘者从黑海岸的神圣土地中挖出远古遗迹可能会让人感到不安，但与协会合作有助于维护联盟的纽带。"},sec={{t="前往首都的信使",b="勘察员雷姆塔维尔在黑海岸雾气缭绕的海岸沿线发掘出了一块奇特的化石，对他来说，深入挖掘比遵守规章制度更重要。考古学家霍莉不愿将这位游荡的勘察员独自留在海岸边危险的野兽和充满敌意的邪教徒之中，因此留下来看护他。为了记录下这一发现，她需要一名联盟旅者将标本送往达纳苏斯，探险者协会在那里设有学术代表团。"},{t="矮人在卡利姆多的利益",b="来自铁炉堡的矮人们在探险者协会的旗帜下大举跨越了无尽之海，渴望发掘卡利姆多土地下埋藏的远古遗物和失落的历史。首席考古学家杜瑟·灰须在暗夜精灵首都接收了这件文物，迫不及待地赞叹雷姆塔维尔发掘远古宝藏的天赋。暗夜精灵将他们的森林视为神圣的庇护所，而探险者协会则将这片古老的土地视为等待解读的巨大考古发掘场。"}},faq={{q="什么是神秘的化石？",a="这是勘察员雷姆塔维尔在黑海岸沿岸发掘出的一件未鉴定的石化标本。它古老的年代和奇异的特质使其成为驻扎在达纳苏斯的探险者协会学者们的珍贵发现。",al={"神秘的化石","这是什么化石","雷姆塔维尔的化石"}},{q="为什么霍莉留在黑海岸？",a="考古学家霍莉觉得有义务看护勘察员雷姆塔维尔。他在发掘时总是习惯四处游荡并忽视危险，所以她拒绝在他将发现物送往达纳苏斯时把他独自留在野外。",al={"为什么霍莉不去","霍莉留下来","为什么霍莉留下来"}},{q="首席考古学家杜瑟·灰须是谁？",a="杜瑟·灰须是铁炉堡探险者协会的高级代表，负责监督卡利姆多北部的考古事业。他在达纳苏斯开展工作，研究矮人挖掘者从野外带回的遗物。",al={"杜瑟·灰须","杜瑟·灰须是谁","首席考古学家杜瑟·灰须"}},{q="为什么探险者协会要在达纳苏斯开展活动？",a="国王麦格尼·铜须委任探险者协会发掘矮人种族的起源以及艾泽拉斯各地的远古历史。与暗夜精灵的友好外交关系使得矮人学者们能够以达纳苏斯为基地，开展远征以研究卡利姆多被遗忘的土地。",al={"达纳苏斯的矮人","达纳苏斯的探险者协会","矮人为什么在这里"}},{q="这块化石在达纳苏斯之后会被送到哪里？",a="首席考古学家杜瑟·灰须会在达纳苏斯检查该发现，但这种规模的发现通常会被编入目录，或者通过协会渠道进一步转运，最终送回铁炉堡的大博物馆。",al={"化石去哪了","化石的后续"}},{q="雷姆塔维尔是在哪里发现该标本的？",a="雷姆塔维尔是在黑海岸的荒野海岸线上发现该标本的，该地区遍布沉船、古代遗迹以及可追溯到大分裂之前的化石化的海洋生物。",al={"在哪里发现化石","雷姆塔维尔的发掘地点"}}},fp="28,180,24.315.0,29.381.0,30.181.0,41.202.0,39.222.0,52.261.0,46.181.0,38.151.0"}
P.entries["quest:742"] = {n="灰谷狩猎",s="“灰谷狩猎”是下达给造访雷霆崖的年轻部落勇士的一道征召令，催促他们向北前往灰谷那茂密的树冠之下。这道召集令由城中的传令官送达，指引旅行者向碎木岗哨的塞娜尼·雷心报到，参加一场试炼狩猎。",h="“灰谷狩猎”是下达给造访雷霆崖的年轻部落勇士的一道征召令，催促他们向北前往灰谷那茂密的树冠之下。这道召集令由城中的传令官送达，指引旅行者向碎木岗哨的塞娜尼·雷心报到，参加一场试炼狩猎。",kw={"灰谷","狩猎","塞娜尼","碎木","雷霆崖","雷心","斯塔德尔","佐拉姆海岸"},ang={["class:Hunter"]="灰谷中未被驯服的潜行者为猎人们提供了一个在茂密林地中磨练追踪技巧的机会，这与南方干燥开阔的稀树草原截然不同。",["faction:Horde"]="碎木岗哨和佐拉姆海岸是部落北方补给线的关键中转站，依靠新兵来阻挡野兽和敌对原住民的侵袭。",["race:Tauren"]="对于那些试炼都在莫高雷广阔平原上进行的牛头人来说，灰谷那茂密而阴郁的树冠在像塞娜尼这样的族人注视下，是一项陌生而神圣的挑战。"},sec={{t="来自高地居所的征召",b="在雷霆崖宁静的高地上，信使们向不断壮大的部落通报着莫高雷边界之外的机遇。雷霆崖信使斯塔德尔带着一封公开邀请函，旨在寻找那些寻求更大挑战的资深冒险者。随着部落在贫瘠之地北部的古老森林中建立立足点，年轻的战士们被召集起来，以巩固那些前哨站，并在更加严酷的环境中磨练他们的生存技巧。"},{t="北方前线",b="对于部落而言，灰谷既蕴含着丰富的资源，也充满了致命的危险。两个显眼的营地支撑着部落在该地区的势力：位于主干道旁的碎木岗哨，以及西海岸上的一座遥远哨所——佐拉姆海岸。抵达碎木岗哨后，新兵将直接归于塞娜尼·雷心的麾下，这位经验丰富的户外生存专家正在组织一场大规模的狩猎，旨在驯服这片荒野，并为部落赢取荣耀。"}},faq={{q="谁在雷霆崖提供这个任务？",a="雷霆崖信使斯塔德尔向路过的冒险者提供这项任务。他的职责是告知有能力的战士关于部落扩张工作的进展，并指引他们前往需要援助的偏远哨所。",al={"谁开启灰谷狩猎","灰谷狩猎任务给予者","雷霆崖信使斯塔德尔"}},{q="碎木岗哨位于何处？",a="碎木岗哨是部落在灰谷东部的一处防御要塞。要到达那里，请穿过贫瘠之地的边界直接向北进入灰谷，然后沿着东部的森林小径深入林地。",al={"碎木岗哨位置","如何到达碎木岗哨","碎木在哪里"}},{q="塞娜尼·雷心是谁？",a="塞娜尼·雷心是一位驻扎在碎木岗哨的资深牛头人追踪者。她负责协调灰谷的狩猎工作，考验部落新兵在当地掠食者面前的实力与耐心。",al={"塞娜尼·雷心","谁是塞娜尼","雷心非玩家角色"}},{q="为什么部落要在灰谷进行狩猎？",a="部落一直在向灰谷积极扩张，以收集木材并确保战略领地的安全。狩猎活动本身旨在清除那些威胁营地的危险野兽，同时让年轻的冒险者在陌生的地形中证明自己的实力。",al={"为什么在灰谷狩猎","灰谷狩猎目的","部落灰谷目标"}},{q="简报中提到的佐拉姆海岸是什么？",a="佐拉姆海岸是部落在灰谷最西端面向大海的沿海营地。它作为第二个海军立足点，也是抵御纳迦和敌对森林住民的堡垒。",al={"什么是佐拉姆海岸","佐拉姆海岸哨所","佐拉姆哨所"}},{q="向塞娜尼报到后会发生什么？",a="一旦你向塞娜尼·雷心报到，她会欢迎你加入岗哨，并立即引导你参与更广泛的狩猎任务，指引你去追踪并征服灰谷中最凶猛的野兽。",al={"灰谷狩猎之后是什么","塞娜尼之后的下一个任务","狩猎继续"}}},fp="18,197,28.293.0,21.333.0,39.191.0,35.171.0,27.166.0,38.189.0,51.173.0,39.171.0"}
P.entries["quest:743"] = {n="风怒鹰身人",s="“风怒的威胁”是卢尔·鹰爪在血蹄村提供的一项武备试炼。年轻的牛头人和部落冒险者们被指派去对抗筑巢于莫高雷东南悬崖上的凶残风怒鹰身人。在离开部族家园远行之前，狩猎这些凶猛的掠食者是检验技巧与生存能力的必要测试。",h="“风怒的威胁”是卢尔·鹰爪在血蹄村提供的一项武备试炼。年轻的牛头人和部落冒险者们被指派去对抗筑巢于莫高雷东南悬崖上的凶残风怒鹰身人。在离开部族家园远行之前，狩猎这些凶猛的掠食者是检验技巧与生存能力的必要测试。",kw={"血蹄村","风怒的威胁","鹰身人","莫高雷","卢尔·鹰爪","牛头人试炼","风怒","风怒鹰爪"},ang={["class:Warrior"]="对于有抱负的战士来说，卢尔·鹰爪的挑战意义非凡，他们必须学会格挡迅捷的俯冲打击，并以扎实的纪律压制这些凶残的空中伏击者。",["faction:Horde"]="参与卢尔试炼的牛头人盟友们证明了他们捍卫部落家园的决心，同时也赢得了血蹄村长久的尊敬。",["race:Tauren"]="对于年轻的牛头人来说，清理风怒巢穴既是捍卫平原的行动，也是在村中长者注视下迈向成年认同的神圣仪式。"},sec={{t="导师的评估",b="在血蹄村，老练的战士卢尔·鹰爪观察着每一位穿行于莫高雷中心的旅者。对于那些即将成年或是寻求证明自己已做好准备去迎接更广阔冒险的人，卢尔要求他们拿出战斗本能的切实证据。在莫高雷受庇护的峡谷之外生存，需要对付那些咄咄逼人的狡猾敌人，而卢尔正是利用这片土地上最凶猛的本土掠食者来衡量年轻人的勇气。"},{t="风怒的威胁",b="风怒鹰身人盘踞在莫高雷东南部的山区边缘，它们远离人迹罕至的道路，但始终对漫游的野生动物和落单的旅者构成威胁。这些鸟身怪凶残成性，渴望新鲜血肉，依靠迅捷的俯冲和锋利的爪子发动攻击。击败它们并夺取它们的爪子，不仅证明了拥有战胜顽固威胁的力量，也证明了能够反制空中袭击者的敏捷身手。"}},faq={{q="卢尔·鹰爪是谁？",a="卢尔·鹰爪是常驻于血蹄村的一位经验丰富的牛头人战士和导师。他指导年轻的冒险者，通过提供试炼来确保他们在动身前往卡利姆多更广阔、更危险的角落之前，具备所需的实力、反应能力和坚韧意志。",al={"卢尔·鹰爪","谁发布风怒的威胁任务","卢尔"}},{q="风怒鹰身人在莫高雷的什么地方？",a="风怒鹰身人栖息在莫高雷的东南部山区。它们将简陋的巢穴筑在岩架和山麓的高处，远离穿越峡谷的主路。",al={"风怒鹰身人位置","风怒鹰身人在哪里","风怒巢穴位置"}},{q="为什么风怒鹰身人被视为牛头人的天敌？",a="鹰身人是众所周知的极具攻击性、领地意识极强的食腐动物，它们会攻击任何擅闯其巢穴附近的人。在莫高雷，风怒族群以对新鲜血肉的贪婪渴望和对旅者及食草动物的不断侵扰而闻名，这使它们成为了平原上挥之不去的威胁。",al={"为什么牛头人要对抗鹰身人","莫高雷的鹰身人威胁","风怒背景知识"}},{q="卢尔·鹰爪要求从狩猎中获得什么证明？",a="卢尔要求冒险者从被击杀的鹰身人身上取回八只风怒鹰爪。割下并带回这些爪子，证明了冒险者能够制服这些鹰身人最主要的天然武器。",al={"风怒的威胁任务证明","为卢尔收集什么","风怒任务目标"}},{q="为什么冒险者在离开莫高雷之前必须通过这项试炼？",a="卢尔将凶猛的风怒鹰身人视为检验武备状况的理想标杆。如果一名冒险者无法应对鹰身人的速度、凶残和利爪，那么面对莫高雷防线之外那些潜伏着的更致命危险时，他们几乎毫无胜算。",al={"试炼的目的","为什么要做风怒的威胁任务","卢尔的测试"}},{q="血蹄村在哪里？",a="血蹄村位于莫高雷中心地带，靠近石牛湖，在大门和雷霆崖以南。它是牛头人旅者穿行平原时的文化、贸易和训练的主要枢纽。",al={"血蹄村位置","血蹄村在哪里","卢尔的位置"}}},fp="23,183,22.325.0,19.354.0,23.162.0,48.176.0,70.210.0,53.112.0,63.172.0,35.163.0"}
P.entries["quest:744"] = {n="准备典礼",s="仪式准备是牛头人的一种传统，重点在于为准备面见凯恩·血蹄大酋长的人制作仪式头饰。为了完成这套传统服饰，必须从雷霆崖外筑巢的危险鹰身人那里收集色彩鲜艳的羽毛，同时准备好皮革带。",h="仪式准备是牛头人的一种传统，重点在于为准备面见凯恩·血蹄大酋长的人制作仪式头饰。为了完成这套传统服饰，必须从雷霆崖外筑巢的危险鹰身人那里收集色彩鲜艳的羽毛，同时准备好皮革带。",kw={"凯恩·血蹄","仪式","羽毛","鹰身人","头饰","莫高雷","仪式准备","牛头人","雷霆崖"},ang={["faction:Horde"]="帮助部落的同胞完成他们传统的仪式职责，是对雷霆崖高原上牛头人盟友习俗的尊重。",["race:Tauren"]="用天然材料制作的头饰与牛头人的荣誉以及在大酋长面前的成人礼紧密相连。帮助制作此类礼服反映了莫高雷各部落的社区精神和自豪感。"},sec={{t="向大酋长致敬",b="在牛头人文化中，站在凯恩·血蹄大酋长面前是一件令人倍感自豪和崇敬的事情。这样的里程碑时刻需要得体的仪式服饰，尤其是用处理过的皮革和具有象征意义的羽毛精心制作的传统头饰。制作这套礼服被家族成员视为一种荣耀，他们会格外小心，以确保每一部分都能在联合部落的首领面前体现出尊严与尊重。"},{t="峭壁之羽",b="制作仪式头饰既需要技巧，也需要特定的材料。在将柔软的皮带鞣制成底带的同时，还必须找到长而原始的羽毛来装饰冠部。在雷霆崖北部和西北部的崎岖山丘上筑巢的鹰身人能提供所需尺寸和色泽完全吻合的羽毛，这就需要旅行者冒险进入充满敌意的巢穴去取回它们。"}},faq={{q="正在准备什么仪式？",a="这项仪式标志着一位牛头人即将面见凯恩·血蹄大酋长。为了纪念这一光荣的时刻，他的兄弟正在用鞣制的皮革和鲜艳的羽毛制作一种特殊的仪式头饰。",al={"这是什么仪式","仪式是什么","谁站在血蹄面前"}},{q="血蹄大酋长是谁？",a="凯恩·血蹄大酋长是受人尊敬的大酋长，也是联合牛头人部落的领袖，在雷霆崖的高原上进行统治。对他而言，站在他面前对任何牛头人来说都是一种特殊的荣誉。",al={"血蹄大酋长是谁","凯恩·血蹄","血蹄是谁"}},{q="为什么制作头饰需要鹰身人的羽毛？",a="仪式头饰需要特定尺寸和引人注目的羽毛——特别是天蓝色和青铜色的羽毛——以便在鞣制皮带的同时完成传统设计。",al={"为什么需要鹰身人羽毛","为什么是鹰身人羽毛","为什么要羽毛"}},{q="鹰身人在哪里？",a="那些产出羽毛的鹰身人栖息在莫高雷雷霆崖以北和西北方向很远的崎岖土地上。",al={"鹰身人住在哪里","去哪里找鹰身人","天蓝色和青铜色羽毛在哪里"}},{q="鹰身人在莫高雷扮演什么角色？",a="鹰身人是栖息在莫高雷周围岩石峭壁上的凶残的鸟人生物。除了对旅行者和部落构成威胁外，它们巨大而多彩的羽毛也使它们成为了仪式装饰品的主要来源。",al={"为什么要猎杀鹰身人","什么是鹰身人"}},{q="谁在制作仪式头饰？",a="艾安·鹰爪（伊恩·鹰爪）正在鞣制皮带并制作头饰，以纪念他的兄弟准备在大酋长面前亮相。",al={"谁制作头饰","谁来制作头饰"}}},fp="24,212,22.307.0,21.314.0,36.161.0,23.121.0,48.143.0,30.82.0,37.203.0,41.130.0"}
P.entries["quest:745"] = {n="土地之争",s="由血蹄村的贝恩·血蹄指派，这项任务派遣年轻的部落冒险者去遏制当地白鬃豺狼人的破坏性偷猎行为。通过猎杀他们的制皮师、剥皮师和偷猎者，你保护了莫高雷的野生动物，并学习了牛头人与大地母亲和谐共处的哲学。",h="由血蹄村的贝恩·血蹄指派，这项任务派遣年轻的部落冒险者去遏制当地白鬃豺狼人的破坏性偷猎行为。通过猎杀他们的制皮师、剥皮师和偷猎者，你保护了莫高雷的野生动物，并学习了牛头人与大地母亲和谐共处的哲学。",kw={"贝恩·血蹄","血蹄村","豺狼人","莫高雷","白鬃","偷猎者","共享这片土地","剥皮师","制皮师"},ang={["class:Druid"]="德鲁伊们认识到，无节制的偷猎会破坏平原的灵魂，需要立即干预以修复土地的和谐。",["class:Hunter"]="白鬃剥皮师和偷猎者代表了真正猎人的对立面，他们残忍而浪费地屠杀野生生物，而非怀着敬意。",["faction:Horde"]="协助贝恩·血蹄加强了新部落冒险者与初生的牛头人国度领导层之间的纽带。",["race:Tauren"]="对于年轻的牛头人来说，响应贝恩的召唤是学习保卫莫高雷和尊崇大地母亲的平衡这一神圣职责的重要一步。"},sec={{t="失衡的土地",b="牛头人对自然世界怀有深深的敬意，只取生存之必要，在万事万物中尊崇大地母亲。白鬃豺狼人在血蹄村以南和西面的一处洞穴中定居，却毫无这种敬意。他们并未适度狩猎，而是在平原上疯狂屠戮野生动物，留下被剥皮的尸体和遭到破坏的生态系统。对于一个努力在莫高雷建立和平家园的种族来说，这种肆无忌惮的屠杀是无法容忍的。"},{t="当言语失效时",b="贝恩·血蹄起初希望能和平解决此事，试图与这些入侵的豺狼人展开对话。但白鬃豺狼人拒绝了所有的提议，以敌意和持续的破坏回应了外交努力。眼见谈判徒劳无功，贝恩转而使用武力。年轻的勇士们被直接派往他们的狩猎营地，在草原遭受永久性破坏之前铲除那些偷猎者、制皮师和剥皮师。"},{t="生与死的轮回",b="这项任务对成长中的勇士来说是一场成年礼和道德课。在完成猎杀任务归来后，贝恩提醒冒险者，夺取生命绝不能出于恶意，而必须是为了维持和谐的必要之举。生与死是一个相互关联的轮回，缺一不可，这是每一位莫高雷的守护者必须铭记在心的根本真理。"}},faq={{q="谁提供这个任务？",a="大酋长凯恩·血蹄之子，贝恩·血蹄，在莫高雷中部的血蹄村提供这项任务。",al={"任务发布者","谁开启共享这片土地","贝恩的任务"}},{q="为什么牛头人要针对白鬃豺狼人？",a="白鬃豺狼人疯狂地狩猎莫高雷的野生动物，在不尊重自然平衡的情况下消耗兽群数量。他们还拒绝了牛头人所有和平沟通的尝试。",al={"为什么要猎杀豺狼人","白鬃豺狼人问题","豺狼人做了什么"}},{q="这些豺狼人位于何处？",a="白鬃豺狼人在血蹄村以南设有营地，并居住在西面的白鬃石洞穴系统中。",al={"豺狼人位置","白鬃豺狼人营地","在哪里找到白鬃豺狼人"}},{q="牛头人是否先尝试过和平解决？",a="是的。贝恩指出，牛头人曾多次尝试沟通并共享这片土地，但豺狼人不仅不尊重，还拒绝了每一个和平的提议。",al={"牛头人是否与豺狼人沟通过","白鬃外交"}},{q="贝恩试图传达什么课程？",a="贝恩希望年轻的保卫者们理解，死亡与生命是一个不可分割的轮回。虽然为了捍卫平衡有时必须夺取生命，但必须始终怀着对大地母亲的深深敬意去行事。",al={"贝恩的教导","共享这片土地的含义"}},{q="白鬃豺狼人是谁？",a="他们是一个莫高雷本土的原始鬣狗类部族，以苍白的皮毛、领地侵略性和对平原和谐的完全无视而闻名。",al={"谁是白鬃豺狼人","白鬃部族"}}},fp="16,178,21.364.0,15.287.0,28.197.0,21.117.0,49.139.0,31.100.0,39.141.0,42.194.0,28.170.0"}
P.entries["quest:746"] = {n="矮人的挖掘场",s="“矮人的挖掘”是莫高雷的一个任务，由血蹄村的贝恩·血蹄发布。贝恩担心矮人的挖掘会激怒当地的野兽并亵渎神圣的土地，于是指派年轻的部落保卫者去没收并砸碎他们的十字镐，以破坏他们的挖掘工作。",h="“矮人的挖掘”是莫高雷的一个任务，由血蹄村的贝恩·血蹄发布。贝恩担心矮人的挖掘会激怒当地的野兽并亵渎神圣的土地，于是指派年轻的部落保卫者去没收并砸碎他们的十字镐，以破坏他们的挖掘工作。",kw={"贝恩·血蹄","血蹄村","矮人","熔炉","科多兽","莫高雷","十字镐","勘探员"},ang={["class:Shaman"]="萨满们明白，通过粗心的挖掘扰动基岩会打破元素平衡，并激起这片土地的灵魂和生物的不安。",["faction:Horde"]="这些蚕食部落腹地的联盟矮人破坏了第三次战争后建立的脆弱和平，公然无视部落的边界。",["profession:Mining"]="虽然矿工尊崇隐藏在石头中的财富，但矮人在莫高雷的手段绕过了尊重与和谐，选择了鲁莽的破坏。",["race:Tauren"]="大地母亲的身体是神圣的，看到外来的入侵者在莫高雷连绵的草原上钻探，这是一种必须立即予以坚决回应的冒犯。"},sec={{t="山丘上的入侵者",b="在血蹄村的西北方，矮人勘探员已经开始在莫高雷连绵的山丘中圈地挖掘。探险者协会及其挖掘队在整个卡利姆多搜寻泰坦圣物和大地秘密，但他们的行动很少尊重原住民的土地或习俗。对牛头人来说，大地是需要敬畏的活着的母亲，而不是为了石头和金属而被剥削和掏空的躯壳。"},{t="保卫神圣的大地",b="贝恩·血蹄认识到矮人的机械和无休止的爆破威胁到了平原脆弱的和谐。除了物理破坏之外，骚乱还激怒了当地的野生动物，导致平原上的科多兽陷入狂暴。通过在矮人自己的熔炉处砸碎勘探员的工具，牛头人希望传达一个直截了当的信息，并在造成持久伤害之前阻止这种蚕食行为。"}},faq={{q="为什么矮人在莫高雷挖掘？",a="矮人勘探员认为卡利姆多中部的大地深处隐藏着秘密和文物。然而，他们无视部落领地并使用暴力的采矿方法，这使他们与牛头人产生了直接冲突。",al={"莫高雷的矮人","勘探员为什么在这里","矮人挖掘莫高雷"}},{q="是谁发布了“矮人的挖掘”任务？",a="该任务由高阶酋长凯恩·血蹄的年轻儿子贝恩·血蹄发布，他位于莫高雷中部的血蹄村。",al={"矮人的挖掘任务发布者","谁开启矮人的挖掘"}},{q="为什么贝恩要求砸碎他们的工具，而不是仅仅偷走它们？",a="贝恩希望使这些设备彻底报废，以立即停止挖掘工作。在熔炉处摧毁工具传达了一个明确的象征性和实际意义：这片土地不会通过蛮力和亵渎来交出它的秘密。",al={"为什么要砸碎十字镐","砸碎矮人工具"}},{q="这种挖掘对莫高雷的野生动物有什么影响？",a="大声的挖掘和对地表的严重破坏极大地激怒了当地的生物，特别是漫游在山丘上的巨大科多兽，使原本平静的兽群变得焦躁且具有攻击性。",al={"愤怒的科多兽","为什么野兽会发狂"}},{q="在哪里可以砸碎十字镐？",a="十字镐可以在任何功能性的熔炉处被锤成废铁。玩家可以使用位于矮人挖掘营地内的熔炉，或者把它们带到雷霆崖的铁匠那里。",al={"熔炉在哪里","在熔炉砸碎勘探员十字镐"}},{q="这个任务与探险者协会在卡利姆多更广泛的活动有关联吗？",a="是的。来自铁炉堡的矮人远征队在整个卡利姆多建立了前哨站，包括莫高雷、贫瘠之地和卡利姆多南部，他们经常因领土主权和神圣土地问题与部落种族发生冲突。",al={"莫高雷探险者协会","卡利姆多的铁炉堡"}}},fp="15,187,24.365.0,26.324.0,35.185.0,36.130.0,63.159.0,52.156.0,31.131.0,75.217.0"}
P.entries["quest:747"] = {n="开始狩猎",s="“狩猎开始”是纳拉其营地红云台地年轻冒险者的一项基础试炼。在格鲁尔·鹰风的指派下，新兵们被派去猎杀当地的平原陆行鸟，为村庄提供肉和羽毛。完成这项任务是赢得鹰风酋长尊重并最终进入雷霆崖的第一步。",h="“狩猎开始”是纳拉其营地红云台地年轻冒险者的一项基础试炼。在格鲁尔·鹰风的指派下，新兵们被派去猎杀当地的平原陆行鸟，为村庄提供肉和羽毛。完成这项任务是赢得鹰风酋长尊重并最终进入雷霆崖的第一步。",kw={"纳拉其营地","鹰风酋长","羽毛","格鲁尔·鹰风","狩猎开始","莫高雷","平原陆行鸟","红云台地"},ang={["class:Hunter"]="追踪红云台地迅捷的平原陆行鸟，是射击、追踪和尊重那些供养你的野兽的最早实践练习。",["race:Tauren"]="对于年轻的舒哈鲁来说，猎杀你的第一只台地平原陆行鸟是一项必不可少的成年仪式，它确认了你与这片土地的羁绊，以及你供养纳拉其营地的职责。"},sec={{t="部落的补给",b="在红云台地的高处，生存与传统交织在一起。牛头人狩猎不仅是为了维持族人的温饱，也将跟踪和追捕视作一种磨练纪律和运动能力的重要考验。当纳拉其营地的储备不足时，社区便会指望年轻一代去收集新鲜的平原陆行鸟肉供烹饪使用，并获取结实的羽毛用于制作部落服饰。"},{t="获得认可",b="没有哪个有抱负的英雄能在不证明自己价值的情况下，就直接走出红云台地，踏入莫高雷更广阔的天地。格鲁尔·鹰风是新人们性格的主要评判者，他坚持要求新兵必须先证明自己的能力，然后才能去见他的父亲——鹰风酋长。完成一次干净利落的狩猎，不仅展现了独立生存的能力，也体现了对部落的奉献。"}},faq={{q="谁发布了这个任务？",a="格鲁尔·鹰风在纳拉其营地发布了这项任务。他是村庄领袖鹰风酋长的儿子，也是红云台地上年轻猎人和冒险者的早期导师。",al={"任务发布者","谁开启了狩猎开始","格鲁尔·鹰风"}},{q="为什么猎杀平原陆行鸟而不是其他野兽？",a="平原陆行鸟在台地上随处可见，不仅能提供充足的肉类来补充日益减少的食物储备，其结实的羽毛还可用于牛头人的传统服饰和装饰品。",al={"为什么选择平原陆行鸟","平原陆行鸟肉和羽毛","狩猎平原陆行鸟"}},{q="为什么我必须先证明自己才能见到鹰风酋长？",a="牛头人社会非常重视实际贡献和狩猎本领。格鲁尔·鹰风要求新兵在获得酋长的接见并承担更重要的职责之前，先展示其基本的生存技能和对村庄的忠诚。",al={"为什么要向鹰风酋长证明自己","鹰风酋长的认可","为什么要先狩猎"}},{q="在红云台地进行这些试炼的更宏大的目标是什么？",a="台地是一个试炼场。一旦年轻的牛头人向鹰风酋长和纳拉其营地的长者证明了自己的能力，他们就被认为做好了准备，可以下山进入莫高雷的广阔平原，并进入主城雷霆崖。",al={"台地试炼的目的","为什么我在红云台地","离开红云台地"}},{q="这次狩猎之后是什么？",a="成功带回肉和羽毛能赢得格鲁尔的认可，随后将直接进行“狩猎继续”，新兵们将在台地上追踪更大型、更难以捉摸的猎物。",al={"下一个任务","后续任务","狩猎开始之后是什么"}},{q="牛头人只为了生存而狩猎吗？",a="虽然维持生计以及获取皮革、骨骼和羽毛等资源至关重要，但牛头人也将狩猎作为一种体育运动和精神交流，这能磨练他们的直觉，使部落时刻保持警惕和强大。",al={"牛头人的狩猎哲学","为了运动而狩猎","牛头人为什么要狩猎"}}},fp="15,195,20.251.0,19.245.0,21.116.0,53.151.0,59.149.0,59.122.0,27.139.0,33.193.0"}
P.entries["quest:748"] = {n="毒水",s="“毒水”任务开启了牛头人清除莫高雷圣井污染的行动。在血蹄村的穆尔·雷角委托下，年轻的部落保卫者们从平原上收集天然材料，以制作恢复性的仪式图腾。",h="“毒水”任务开启了牛头人清除莫高雷圣井污染的行动。在血蹄村的穆尔·雷角委托下，年轻的部落保卫者们从平原上收集天然材料，以制作恢复性的仪式图腾。",kw={"血蹄村","净化图腾","莫高雷","穆尔·雷角","陆行鸟","毒水","草原狼","冰蹄水井"},ang={["class:Druid"]="地精污染淡水泉是对自然平衡的直接攻击，必须立即采取行动以保护莫高雷脆弱的动植物群。",["class:Shaman"]="通过野兽力量强化的图腾来恢复受污染的水源，阐释了牛头人萨满之道的基础：与当地野生动物并肩协作，以修复元素紊乱。",["race:Tauren"]="对淡水的亵渎打击了大地母亲馈赠的核心，这使得净化仪式成为任何在莫高雷成年的牛头人的基本职责。"},sec={{t="遭亵渎的土地",b="莫高雷的青草平原对于牛头人而言是圣地，但阴险的势力已经开始威胁到他们的生命之源。驻扎在血蹄村的长者穆尔·雷角发现，地精入侵者及其爪牙污染了维持部落和当地野生动物生存的珍贵水井。这种污染直接打击了这群刚定居于此的游牧民族的精神核心。"},{t="收集自然精华",b="为了对抗工业污染物，穆尔不依靠粗糙的手段，而是依循传统的牛头人萨满之道。净化冰蹄水井需要制作一种强大的仪式图腾，并注入莫高雷本土掠食者的生命力。他派遣猎人前往西南平原追踪草原狼以获取它们的爪子，并寻找成熟的陆行鸟获取它们的利爪，借用大地的力量来治愈它自身的创伤。"}},faq={{q="是谁污染了莫高雷的水井？",a="地精入侵者及其雇佣兵应对玷污莫高雷各地的圣洁水潭负责。他们破坏性的工业作业和对自然平衡的漠视，威胁着牛头人部落和当地的野生动物。",al={"谁污染了水井","谁毒害了莫高雷","谁污染了水源"}},{q="穆尔·雷角为什么需要狼爪和陆行鸟利爪？",a="穆尔利用从莫高雷本土野兽身上收集的部分来制作传统的净化图腾。通过驾驭平原掠食者与生俱来的灵魂与力量，他创造出了一种足够强大的媒介，用于进行净化水源的仪式。",al={"为什么要狼爪","为什么要陆行鸟利爪","图腾材料"}},{q="这个任务准备净化哪口水井？",a="此项任务收集的材料专用于制作冰蹄水井的净化图腾，这是首个需要仪式净化的受污染水井。",al={"这是为了哪口井","哪口水井"}},{q="穆尔·雷角在哪里？",a="穆尔·雷角居住在血蹄村，这是位于莫高雷中部，环绕石牛湖水域的主要牛头人定居点。",al={"穆尔·雷角位置","穆尔在哪里","毒水任务交付地点"}},{q="在哪里可以找到所需的狼和陆行鸟？",a="草原狼和成年陆行鸟在血蹄村西南方的草海平原上游荡。",al={"哪里可以找到草原狼","陆行鸟位置","狩猎场"}},{q="穆尔收到爪子和利爪后会发生什么？",a="穆尔将收集到的材料绑定制成冰蹄之井净化图腾，并委派你将其直接带往冰蹄水井以执行净化仪式。",al={"毒水之后的下一个任务","接下来要做什么"}}},fp="12,192,17.320.0,26.311.0,40.142.0,65.130.0,46.77.0,34.109.0,58.86.0,53.143.0"}
P.entries["quest:749"] = {n="被破坏的货车",s="摩林·云行者指引旅行者去调查石牛湖北岸附近被伏击的荆棘谷地精货车的残骸。虽然牛头人为了报复失去的同伴而焚毁了这支车队，但地精打捞者却回来回收完好的货物。调查幸存下来的补给箱，揭示了荆棘谷地精在莫高雷工业行动的真实规模。",h="摩林·云行者指引旅行者去调查石牛湖北岸附近被伏击的荆棘谷地精货车的残骸。虽然牛头人为了报复失去的同伴而焚毁了这支车队，但地精打捞者却回来回收完好的货物。调查幸存下来的补给箱，揭示了荆棘谷地精在莫高雷工业行动的真实规模。",kw={"摩林·云行者","莫高雷","被破坏的货车","石牛湖","补给箱","荆棘谷地精"},ang={["faction:Horde"]="荆棘谷地精在莫高雷肆无忌惮的企业扩张威胁到了雷霆崖的稳定，需要部落斥候去破坏荆棘谷地精的后勤。",["profession:Mining"]="这些坚固的板条箱和后勤记录证明了荆棘谷地精正在莫高雷全境进行积极的矿物勘探和开采活动。",["race:Tauren"]="荆棘谷地精的机器和伐木行动对平原造成的破坏直接打击了你的祖居之地，因此回收并摧毁他们的物资对于保卫莫高雷至关重要。"},sec={{t="湖畔的报复",b="石牛湖北岸那些焦黑的遗迹是牛头人迅速打击的结果。因为在之前的一次冲突中失去了两名同伴，摩林·云行者和他的战士们悲愤之下伏击了一支武装的荆棘谷地精补给车队。牛头人意图彻底摧毁入侵者的心血，便烧毁了货车，并离开了这片冒烟的废墟，认为大火会吞噬地精们试图运走的一切。"},{t="未竟之事",b="牛头人很快注意到有荆棘谷地精的打捞者在搜寻焦黑的残骸，这表明他们的大火没能摧毁最关键的货物。摩林不愿盲目冒险折损人手，便派遣斥候去检查残骸。在沾满煤烟的废墟中，放着标有荆棘谷地精采矿部门徽记的完好箱子，它们被打包好，正准备运往中央处理设施。"}},faq={{q="为什么这辆货车会被摧毁？",a="在之前与荆棘谷地精的冲突中失去了两名斥候后，摩林·云行者和他的牛头人战士为了报复，伏击并烧毁了这辆货车。",al={"谁摧毁了货车","为什么货车会被烧毁","袭击货车"}},{q="被破坏的货车位于何处？",a="烧毁的货车位于石牛湖北岸，莫高雷血蹄村的东面。",al={"货车位置","货车在哪里","被破坏的货车地点"}},{q="为什么地精会回到残骸现场？",a="因为大火没能摧毁所有的货物，荆棘谷地精派出了打捞者。他们试图取回那些盖有印章、准备运往其中央处理机构的耐用补给箱。",al={"为什么打捞者会在这里","荆棘谷地精打捞者","地精想要什么"}},{q="补给箱里有什么？",a="这些箱子上带有荆棘谷地精采矿部门的徽记，里面装有标明将运往其主要工业工厂进行精炼和处理的矿物资源。",al={"补给箱内容","补给箱里有什么","密封的补给箱"}},{q="摩林·云行者是谁？",a="摩林·云行者是一位驻扎在血蹄村东面的牛头人斥候兼追踪者，负责监视莫高雷中部发生的敌对入侵，尤其是来自荆棘谷地精的威胁。",al={"摩林是谁","摩林·云行者的职责"}},{q="这辆货车揭示了关于荆棘谷地精的什么信息？",a="它表明荆棘谷地精在莫高雷的存在不仅仅是一个勘探队，而是一个拥有武装补给线和集中式精炼网络的有组织的工业开采行动。",al={"荆棘谷地精在莫高雷的活动","为什么地精在莫高雷"}}},fp="19,223,23.315.0,19.356.0,30.176.0,37.100.0,46.185.0,33.171.0,26.185.0,56.206.0"}
P.entries["quest:7493"] = {n="一切才刚刚开始",s="“旅程才刚刚开始”是部落的一项任务，由奥格瑞玛提供给击败奥妮克希亚后的制皮大师。伦萨克大王认可了英雄的技艺，并传授了从这位龙族巢母的鳞片中制作防护披风所需的稀有技法。这项至关重要的工艺为部落应对黑石塔内致命的烈焰做好了准备。",h="“旅程才刚刚开始”是部落的一项任务，由奥格瑞玛提供给击败奥妮克希亚后的制皮大师。伦萨克大王认可了英雄的技艺，并传授了从这位龙族巢母的鳞片中制作防护披风所需的稀有技法。这项至关重要的工艺为部落应对黑石塔内致命的烈焰做好了准...",kw={"黑石","巢母","披风","制皮","伦萨克","奈法利安","奥妮克希亚","鳞片"},ang={["faction:Horde"]="对于部落而言，利用从敌人的尸骸上铸造的防护装备，对于保护部队免遭巨龙进一步的蹂躏至关重要。"},sec={{t="巢母的遗产",b="奥妮克希亚的陨落是部落的一大胜利，但这并不意味着黑龙军团带来的威胁已经结束。巢母鳞片的表皮对于龙炎具有显著的抗性。部落领袖不希望这些材料被浪费，因此正在寻找能够将巨龙遗骸转化为防御性护甲的工匠。"},{t="暗影烈焰之盾",b="伦萨克大王教导有天赋的制皮师如何缝制奥妮克希亚鳞片披风。这些知识不仅仅是为了炫耀或地位。在黑石山的深处，奥妮克希亚的兄弟奈法利安正挥舞着毁灭性的烈焰吐息。如果没有这件由巢母鳞片制成的附魔披风所提供的保护，任何直面黑石领主的先遣部队都会化为灰烬。"}},faq={{q="谁提供这项任务，他们在哪里？",a="这项任务由奥格瑞玛的伦萨克大王提供。他认可了那些精通制皮技艺并参与了奥妮克希亚讨伐战的部落勇士。",al={"伦萨克任务提供者","伦萨克大王在哪里","任务起始"}},{q="接受这项任务需要什么条件？",a="这项任务仅提供给那些精通制皮术，且完成了奥妮克希亚战后相关任务的勇士，例如“部落的胜利”或“最令人困惑的情况”。",al={"制皮要求","如何获得任务","前置条件"}},{q="伦萨克大王传授什么？",a="伦萨克大王指导制皮师使用从已故巢母身上采集的鳞片来制作奥妮克希亚鳞片披风的技法。",al={"任务奖励配方","奥妮克希亚披风图纸","我学到了什么"}},{q="为什么奥妮克希亚鳞片披风很重要？",a="这件披风能保护佩戴者免受黑石领主奈法利安致命烈焰吐息的伤害。如果没有其独特的防护属性，直面这位龙族主人将是致命的。",al={"为什么要制作披风","披风的作用","奈法利安披风"}},{q="谁是黑石领主？",a="黑石领主是奈法利安，一条强大的黑龙，也是奥妮克希亚的兄弟。他正盘踞在黑石山之巅，策划着统治凡人种族的阴谋。",al={"谁是黑石领主","奈法利安身份","黑石领主"}},{q="为什么任务说旅程才刚刚开始？",a="尽管奥妮克希亚已被击杀，但针对黑龙军团的全面战争以及奈法利安在黑石山内的阴谋才刚刚升级。",al={"标题的含义","为什么说旅程才刚刚开始"}}},fp="26,199,22.250.0,27.344.1,49.139.0,49.183.0,33.118.0,40.147.0,29.158.0,57.142.0"}
P.entries["quest:7497"] = {n="一切才刚刚开始",s="此任务代表了在击败奥妮克希亚后，一位经验丰富的工匠所获得的来之不易的认可。玛丁雷少校传授了制作奥妮克希亚鳞片披风所需的重要技巧，将这位陨落的育母留下的遗骸转变为抵御她兄弟的必要护具。",h="此任务代表了在击败奥妮克希亚后，一位经验丰富的工匠所获得的来之不易的认可。玛丁雷少校传授了制作奥妮克希亚鳞片披风所需的重要技巧，将这位陨落的育母留下的遗骸转变为抵御她兄弟的必要护具。",kw={"黑龙军团","黑石","制皮","玛丁雷少校","奈法利安","奥妮克希亚","奥妮克希亚鳞片披风","暴风城"},ang={["faction:Alliance"]="此任务将暴风城在奥妮克希亚一役中来之不易的胜利，与即将对她在黑石山的兄弟奈法利安发起的攻势联系在了一起。"},sec={{t="稀有的大师技艺",b="虽然许多勇士都可以声称自己击败了育母奥妮克希亚，但很少有人能同时拥有强大的武艺和处理她那坚韧外皮所需的大师级制皮技能。当具备这些天赋的英雄向暴风城的玛丁雷少校报告时，这位军官会意识到这些制作技能对于未来的战斗至关重要。"},{t="抵御黑龙军团的防护",b="奥妮克希亚之死并未终结黑龙军团的威胁。玛丁雷少校教导工匠如何处理并将这位育母的鳞片缝制成奥妮克希亚鳞片披风。这件独特的装备提供了专门的防护，用来抵御奥妮克希亚的兄弟，黑石之王奈法利安那具有毁灭性的烈焰吐息。"}},faq={{q="谁提供了任务“旅程刚刚开始”？",a="暴风城的玛丁雷少校会向那些在对抗奥妮克希亚的战役中证明过自己，并且拥有大师级制皮技能的联盟英雄提供此任务。",al={"谁提供旅程刚刚开始任务","在哪里接取旅程刚刚开始","旅程刚刚开始任务发布者"}},{q="此任务传授什么？",a="完成此互动后，大师级制皮师将学会制作奥妮克希亚鳞片披风的配方，这件物品是专门使用奥妮克希亚的鳞片剪裁而成的。",al={"我能获得什么配方","奥妮克希亚鳞片披风配方","旅程刚刚开始任务奖励"}},{q="为什么需要奥妮克希亚鳞片披风？",a="这件披风经过特殊处理，可以保护穿着者抵御黑石之王奈法利安那致命的烈焰吐息，这使它成为面对黑龙军团余下首领时不可或缺的装备。",al={"为什么要用奥妮克希亚鳞片披风","奥妮克希亚鳞片披风有什么用","暗影烈焰防护"}},{q="玛丁雷少校提到的黑石之王是谁？",a="黑石之王是奈法利安，他是奥妮克希亚的兄弟，一条强大的黑龙。他统治着黑石塔，并继续执行着黑龙军团的阴谋。",al={"谁是黑石之王","奈法利安是谁","玛丁雷关于龙的警告"}},{q="为什么英雄必须是制皮师才能获得这些知识？",a="在不破坏龙鳞先天魔法防护的情况下对其进行采集、淬炼和缝制的技巧，需要经验丰富的大师级制皮师所具备的高深专业知识。",al={"为什么仅限制皮","任何人都能接这个任务吗","制皮等级要求"}},{q="奥妮克希亚之死消除了暴风城的黑龙威胁了吗？",a="没有。尽管奥妮克希亚本人已被击杀，但她的兄弟奈法利安依然掌控着黑石山，并继续策划针对联盟和凡人种族的阴谋。",al={"暴风城现在安全了吗","奥妮克希亚死了接下来做什么","奥妮克希亚之后的黑龙军团"}}},fx={b42a6800={q="玛丁雷少校为什么要传授这些知识？",a="玛丁雷少校知道，击杀奥妮克希亚只是打响了第一战。龙母虽已死去，她的同族却仍在黑石山的高处威胁着艾泽拉斯。要消灭残余的黑龙，勇士们就必须在奈法利安本人的灼热烈焰中存活下来。玛丁雷传授这门特殊技艺，让联盟的英雄能用奥妮克希亚的鳞片制作防护披风，终结这场战争。",al={"玛丁雷为何传授技艺","玛丁雷少校的动机","玛丁雷的理由"}}},fp="26,129,14.184.0,41.232.1,48.150.0,27.97.0,40.99.0,58.153.0,63.116.0,65.131.1"}
P.entries["quest:75"] = {n="斯塔文的传说",s="这次针对斯塔文·密斯曼特的调查将你带出了暮色森林，来到了艾尔文森林东南部的一处偏僻住宅。治安官哈格德是一位视力衰退、年迈的老兵，他指引你前往楼上的一个箱子，那里存放着他搬进来时遗留下来的一捆旧文件。",h="这次针对斯塔文·密斯曼特的调查将你带出了暮色森林，来到了艾尔文森林东南部的一处偏僻住宅。治安官哈格德是一位视力衰退、年迈的老兵，他指引你前往楼上的一个箱子，那里存放着他搬进来时遗留下来的一捆旧文件。",kw={"暮色森林","艾尔文森林","褪色的日记书页","弃灵","治安官哈格德","斯塔文"},ang={["faction:Alliance"]="揭开斯塔文的遗产揭露了艾尔文森林平静祥和的田园表象下所掩盖的黑暗篇章。",["race:Human"]="斯塔文的行踪穿过了普通的人类定居点，成为了一个关于隐藏在众目睽睽之下的孤立与恶意的警世故事。"},sec={{t="老兵的阁楼",b="治安官哈格德居住在艾尔文森林东南部边缘、靠近暮色森林与赤脊山交界处的偏远地带。当他搬进这处隐蔽的住所时，发现楼上藏着一个装满旧羊皮纸的箱子。由于视力衰退，他放弃了阅读这些文件的尝试，让它们一直尘封着，直到有调查者前来打听斯塔文的消息。"},{t="挥之不去的阴影",b="留在楼上箱子里的文件并非普通的家居垃圾。翻动斯塔文的遗物会扰动不安的魔法，引出一个与密斯曼特的过去息息相关的弃灵。藏在里面的日记书页提供了斯塔文私人手记的直接记录，确凿地证明了这位隐居的学者在消失前曾在艾尔文留下过痕迹。"}},faq={{q="治安官哈格德是谁？",a="治安官哈格德是一位年迈且几近失明的老兵，安静地生活在艾尔文森林东南部的一间僻静小屋里。他保存着在屋子里发现的、属于斯塔文·密斯曼特的被遗忘已久的文件。",al={"治安官哈格德","哈格德 艾尔文","哈格德是谁"}},{q="为什么线索会指向艾尔文森林？",a="在夜色镇和月溪镇收集的线索追溯了斯塔文在暴风城南部领地的游荡轨迹。哈格德的家宅中藏有斯塔文遗留下的旧文件。",al={"为什么是艾尔文森林","斯塔文 艾尔文","为什么要找哈格德"}},{q="楼上的箱子里有什么？",a="箱子里装着一张斯塔文·密斯曼特书写的褪色的日记书页，它被保存在一捆哈格德从未能仔细查阅过的羊皮纸中。",al={"楼上的箱子","褪色的日记书页","箱子里有什么"}},{q="为什么打开箱子时会有灵魂攻击？",a="一个弃灵徘徊在斯塔文往昔生活的遗物周围，当外人打扰他的私人笔记和记忆时，它便会狂暴地显现。",al={"弃灵","为什么幽灵会攻击","哈格德屋子里的幽灵"}},{q="这如何推进对斯塔文的调查？",a="这张褪色的书页提供了斯塔文亲笔写下的第一手证据，有助于拼凑出他过去的经历。",al={"斯塔文之谜","书页揭示了什么","斯塔文任务线进度"}},{q="为什么治安官哈格德自己无法阅读这些文件？",a="哈格德的视力随着年龄增长变得模糊不清，无法辨认出褪色文件上细小或风化的笔迹。",al={"哈格德 失明","为什么哈格德需要帮助"}}},fp="21,157,17.291.0,17.283.1,23.159.0,45.144.0,34.136.0,50.115.0,48.100.1,53.117.0"}
P.entries["quest:750"] = {n="继续狩猎",s="“狩猎继续”是格鲁尔·鹰风在纳拉其营地布置的一项早期的成人礼仪式。该任务要求有抱负的猎手从南部的丘陵收集山地美洲狮皮，用以缝制部落孩子们的衣服并修补他们的帐篷。",h="“狩猎继续”是格鲁尔·鹰风在纳拉其营地布置的一项早期的成人礼仪式。该任务要求有抱负的猎手从南部的丘陵收集山地美洲狮皮，用以缝制部落孩子们的衣服并修补他们的帐篷。",kw={"纳拉其营地","鹰风酋长","格鲁尔·鹰风","山地美洲狮皮","红云台地","牛头人狩猎","狩猎继续"},ang={["class:Hunter"]="这项任务强化了平原狩猎的核心哲学：以目的为导向去追踪野兽，只取所需，绝不将动物视为单纯的运动或战利品。",["race:Tauren"]="对于在红云台地成年的年轻牛头人来说，认识到野兽的每一个部分都必须服务于部落——从食物到衣物和住所——是必不可少的成人礼仪式。"},sec={{t="狩猎的目的",b="在纳拉其营地，年轻的猎手们会被教导：猎杀野兽绝非闲来无事或为了搜集战利品。格鲁尔·鹰风指示初出茅庐的冒险者前往红云台地的南部丘陵追踪山地美洲狮。这项任务强调的不仅仅是展现武艺，更是对社区的责任感，以此表明真正的猎手必须为族人提供必要的补给。"},{t="部落的庇护所",b="台地上的生活需要耐用的材料来抵御自然环境的侵袭。格鲁尔解释说，急需美洲狮皮来为部落的孩子们缝制衣服，并修补纳拉其营地各处的皮质帐篷。证明自己有能力获取这些珍贵的毛皮将赢得长者的感激，格鲁尔承诺会将猎手无私贡献的消息直接传达给他的父亲——鹰风酋长。"}},faq={{q="部落为什么需要山地美洲狮皮？",a="山地美洲狮的毛皮对纳拉其营地来说是至关重要的实用资源。格鲁尔·鹰风解释说，这些毛皮需要用来制作供部落孩子们御寒的衣物，并修补和加固村庄的帐篷。",al={"为何狩猎美洲狮","美洲狮皮的用途","山地美洲狮皮的用途"}},{q="谁发布了这个任务？",a="这项狩猎任务由格鲁尔·鹰风负责，他是纳拉其营地的一位杰出猎手，也是鹰风酋长的儿子。他指引着新手冒险者去学习支持定居点的基本职责。",al={"谁发布了狩猎继续","纳拉其营地任务发布者"}},{q="在哪里可以找到山地美洲狮？",a="山地美洲狮在纳拉其营地南部红云台地的岩石山脊和起伏的丘陵中徘徊。",al={"美洲狮在哪里","山地美洲狮位置","哪里寻找山地美洲狮"}},{q="格鲁尔·鹰风与鹰风酋长是什么关系？",a="格鲁尔·鹰风是纳拉其营地部落首领鹰风酋长的儿子。如果你能提供所需的毛皮，格鲁尔承诺会代表你向他的父亲进言，并分享你的慷慨义举。",al={"如何给鹰风酋长留下印象","鹰风酋长的儿子"}},{q="这项狩猎任务传达了什么样的牛头人传统？",a="在牛头人之中，狩猎从不被视为一项运动或获取战利品的途径。从大地上猎杀的每一只野兽都旨在维持社区的生存，通过利用毛皮、肉和骨头来延续部落，从而尊重大地。",al={"牛头人狩猎哲学","为何在莫高雷狩猎"}},{q="为什么山地美洲狮皮被认为很有价值？",a="美洲狮皮厚实、耐用，非常适合在风吹雨打的平原上抵御自然环境。因为它们能为年幼的孩子提供温暖，也是补缀居所的坚固材料，所以被村里的长者所珍视。",al={"美洲狮皮是否有价值","为何美洲狮皮很珍贵"}}},fp="18,171,23.211.0,21.244.0,46.168.0,22.161.0,37.72.0,54.165.0,49.173.0,55.171.0"}
P.entries["quest:751"] = {n="被破坏的货车",s="在莫高雷调查一辆破碎的运输车时发现，地精实业家们已经在牛头人的领地上建立了一个非法的立足点。通过从一个密封的补给箱中找回文件，斥候们确认荆棘谷地精正在系统性地剥夺这片土地的矿产财富。这一发现促使血蹄先锋们开始积极保卫他们祖先的平原。",h="在莫高雷调查一辆破碎的运输车时发现，地精实业家们已经在牛头人的领地上建立了一个非法的立足点。通过从一个密封的补给箱中找回文件，斥候们确认荆棘谷地精正在系统性地剥夺这片土地的矿产财富。这一发现促使血蹄先锋们开始积极保卫他们...",kw={"血蹄村","摩林·云行者","莫高雷","先锋","被破坏的货车","补给箱","荆棘谷地精","荆棘谷地精文件"},ang={["class:Druid"]="德鲁伊们视土地的平衡为神圣，这使得荆棘谷地精那破坏性的、烟雾缭绕的露天采矿成为必须被清除的亵渎行为。",["faction:Horde"]="部落依靠莫高雷的忠诚和稳定；任由外来的商业财团掠夺这里的山丘，将威胁到雷霆崖自身的安全。",["profession:Mining"]="箱子里装的高品位矿石证明，莫高雷的东部丘陵隐藏着丰富的地下矿脉，外来者正竞相开采这些矿脉。",["race:Tauren"]="对于牛头人来说，看到粗糙的工业机器撕裂莫高雷祖先的平原，这是对大地母亲的冒犯，也是对他们来之不易的和平发动的战争。"},sec={{t="剥削的证据",b="血蹄村以东一辆被破坏的货车的残骸诉说着令人不安的事实。在一个密封的补给箱里，存放着大量开采的矿石和矿物，旁边还有一捆扎好的荆棘谷地精文件。这些文书提供了无可辩驳的证据，证明贪婪的荆棘谷地精已经开始在莫高雷宁静的山谷深处进行未经许可的采矿作业。"},{t="先锋们的警戒",b="摩林·云行者和他的先锋同伴们一直警惕地守望着莫高雷的边界，防范着那些企图剥削他们和平家园的外来势力。递交了找回的文件证实了摩林最担心的事：东部丘陵上升起的浓烟预示着商业入侵正在升级。牛头人别无选择，只能在他们的山丘被彻底摧毁之前反击这些污染者。"}},faq={{q="密封的补给箱里有什么？",a="撬开箱子后，里面装满了开采的矿石、原材料，以及一捆列明了荆棘谷地精行动计划的文件。",al={"补给箱战利品","箱子里有什么","箱子内容物"}},{q="摩林·云行者是谁？",a="摩林·云行者是一名牛头人先锋，驻扎在血蹄村东往贫瘠之地边界的路上，负责巡逻莫高雷并追踪外来威胁。",al={"摩林是谁","摩林·云行者的职责","先锋摩林"}},{q="为什么荆棘谷地精会在莫高雷？",a="荆棘谷地精试图无情地开采莫高雷丰富的自然资源和矿脉，在不顾土地及其原住民的情况下挖掘丘陵。",al={"地精为什么在这里","荆棘谷地精在莫高雷的目标","地精想要什么"}},{q="这辆货车从哪里来？",a="这辆货车属于荆棘谷地精，负责将从山脚开采的矿石和行动文书运输出去，随后在路上被摧毁。",al={"这是谁的货车","货车来源","谁袭击了货车"}},{q="这次调查接下来会引向何处？",a="带着这些文件，摩林·云行者指引战士们直接对抗荆棘谷地精的领导层，并捣毁他们在东部丘陵的采矿作业。",al={"接下来是什么","被破坏的货车之后的下一个任务","追踪货车线索"}},{q="为什么这对牛头人构成威胁？",a="牛头人视土地为神圣，并敬畏大地母亲。荆棘谷地精鲁莽的露天开采和工业污染正在积极地玷污莫高雷原始的景观。",al={"牛头人为什么关心","荆棘谷地精威胁","莫高雷的威胁"}}},fp="19,239,24.279.0,21.389.0,39.132.0,26.162.0,38.150.0,32.175.0,40.169.1,34.170.0"}
P.entries["quest:752"] = {n="一件琐事",s="“谦卑的任务”是纳拉其营地中的鹰风酋长交给年轻勇士的一项早期义务仪式。酋长由于在红云台地忙于处理部落的紧急事务，便请求一位年轻的冒险者前往东南方，查看他在当地水井旁的老母亲。这个请求强调了集体责任、尊老敬老，以及牛头人生活中不可或缺的日常和谐。",h="“谦卑的任务”是纳拉其营地中的鹰风酋长交给年轻勇士的一项早期义务仪式。酋长由于在红云台地忙于处理部落的紧急事务，便请求一位年轻的冒险者前往东南方，查看他在当地水井旁的老母亲。这个请求强调了集体责任、尊老敬老，以及牛头人生...",kw={"谦卑的任务","纳拉其营地","鹰风酋长","鹰风酋长的母亲","莫高雷","红云台地","水井"},ang={["faction:Horde"]="纳拉其任务中宁静、田园牧歌般的性质突显了牛头人安宁的集体哲学，这与初生的部落在其他地方所展现出的严酷生存磨砺形成了鲜明对比。",["race:Tauren"]="对于年轻的牛头人勇士来说，响应酋长的号召展现了大地母亲教诲的核心原则：尊敬长者，并毫无保留地投身于维护部落共享的福祉。"},sec={{t="集体和谐与责任",b="在纳拉其营地的阴影下，部落的每一位成员都被期待着能尽一份力，共享生活的和谐。对于即将成年的年轻牛头人来说，部落的职责并不仅仅是以击败野猪人或掠食者来衡量战功；它始于基本的社会责任。鹰风酋长直接体现了这一准则：由于行政和防御上的领导职责，他无法离开岗位，因此他将照顾部落弱势长者的信任寄托在了新手冒险者身上。"},{t="纳拉其东南方的水井",b="莫高雷的红云台地依赖于散布在营地周边地区的重要天然水井。清晨时分，鹰风酋长的母亲离开村庄去东南方的泉水处取新鲜水源，却迟迟未归。在这片充满了领地意识强烈的野生动物和不断侵扰的刺鬃野猪人的土地上，一位长者长时间未归引起了小小的担忧，促使酋长派遣援助以确保她平安无事。"}},faq={{q="谁发布了这个任务，我在哪里能找到他们？",a="莫高雷红云台地纳拉其营地的首领鹰风酋长发布了该任务。他站在营地的中央亭子里，负责统筹当地事务。",al={"谁发布谦卑的任务","任务在哪里领取","鹰风酋长位置"}},{q="鹰风酋长的母亲在哪里？",a="鹰风酋长的母亲位于纳拉其营地东南方，正在台地低处照看水井。",al={"鹰风酋长的母亲位置","母亲在哪里","水井位置"}},{q="为什么鹰风酋长不亲自去查看他的母亲？",a="鹰风酋长必须留在纳拉其营地，以监督紧迫的部落事务并指导年轻的勇士。作为一名酋长，他仰仗部落的共同责任感，并信任成长中的冒险者能替他照顾村里的事务。",al={"为什么酋长不能去","为什么鹰风酋长不去查看","鹰风酋长很忙"}},{q="鹰风酋长的母亲在水井那里有危险吗？",a="虽然周围的平原上出没着好斗的山地美洲狮和陆行鸟，但鹰风酋长的母亲在水井旁安然无恙，她对有人特意前来探望一位长者感到十分惊喜。",al={"她安全吗","鹰风酋长的母亲受到攻击了吗","水井处有危险吗"}},{q="这个任务对牛头人有着怎样的文化意义？",a="牛头人文化极其重视家庭、社区凝聚力和对长者的尊敬。这个任务教导年轻的英雄，真正的力量源于谦卑的服务和保护自己的亲人，而不是追逐个人的荣耀。",al={"牛头人文化谦卑的任务","为什么这是一个谦卑的任务","牛头人长者"}},{q="找到鹰风酋长的母亲之后会发生什么？",a="一旦你与鹰风酋长的母亲交谈，她就会完成任务，并请求你进一步协助，将装满的水罐带回营地。",al={"后续任务","谦卑的任务后续","找到母亲后该做什么"}}},fx={b1d313d3={q="鹰风酋长为什么要你去看看他的母亲？",a="他的老母亲一大早就离开纳拉其营地，去东南方的水井打水，至今已经离开很久了。牛头人的生活建立在共同责任和相互照料之上。鹰风酋长虽然担心母亲的安危，但酋长的职责使他必须留守营地。",al={"鹰风酋长为什么要你做这件事","鹰风酋长的意图","为什么去看看鹰风酋长的母亲"}}},fp="13,221,25.328.0,29.371.0,47.153.0,38.101.0,55.229.0,46.204.0,64.185.0,48.116.0"}
P.entries["quest:753"] = {n="一件琐事",s="“卑微的任务”是红云台地的一项入门服务仪式，长者会在此考验初出茅庐的冒险者的谦逊与勤勉。通过将新鲜的井水跨越平原送到纳拉其营地的首领手中，年轻的牛头人将明白，为族人服务始于最简单的职责。",h="“卑微的任务”是红云台地的一项入门服务仪式，长者会在此考验初出茅庐的冒险者的谦逊与勤勉。通过将新鲜的井水跨越平原送到纳拉其营地的首领手中，年轻的牛头人将明白，为族人服务始于最简单的职责。",kw={"纳拉其营地","鹰风酋长","鹰风酋长的母亲","卑微的任务","莫高雷","红云台地","大地之母仪式","水罐"},ang={["faction:Horde"]="鹰风家族的教导说明了牛头人是如何在莫高雷维持团结与生存的，这构成了萨尔领导的部落中和平而坚定的基石。",["race:Tauren"]="为长者取水体现了牛头人社区关怀的基本美德，表明你已准备好走上大地之母的道路。"},sec={{t="年轻人的活力",b="鹰风酋长的母亲在她漫长的一生中走过许多道路，虽然她的精神依然坚定，但她的双腿已不再能像年轻时那样迅速地跨越平原。她驻守在红云台地南缘的水井旁，以耐心的决心履行着自己的职责。当有抱负的部落保卫者经过她身边时，她会将他们年轻的精力引导至实际的社区需求上，让他们有机会通过服务而非暴力来证明自己的价值。"},{t="为部落服务",b="这项任务要求初学者将一罐装满的水挑回西北方的纳拉其营地，并直接交给该定居点的首领——鹰风酋长，他恰好就是鹰风酋长的母亲的儿子。在牛头人社会中，要在莫高雷干旱的平原上生存，需要共同劳动和可靠的淡水供应。通过承担长者的负担来表现对社区长者的尊重，被认为是成为部落真正保护者的基石。"},{t="通往雷霆崖的道路",b="当年轻的旅者带着他母亲送来的水到达时，鹰风酋长看到的不仅仅是一件琐事的完成。在牛头人的习俗中，一个人准备好在更广阔的土地上捍卫族人，始于谦逊和自愿提供帮助的意愿。通过展现这种安静的纪律，初学者引起了酋长的注意，并获得了参加古老的“大地之母仪式”的推荐，这是通往雷霆崖的真正精神考验。"}},faq={{q="鹰风酋长的母亲是谁？",a="鹰风酋长的母亲是鹰风家族的一位长者，驻扎在红云台地的水井旁。她是纳拉其营地首领鹰风酋长的母亲，并引导年轻的牛头人学习谦逊和部落价值观。",al={"鹰风酋长的母亲","谁发布卑微的任务","鹰风长者"}},{q="水井在哪里？",a="水井位于纳拉其营地的东南方，坐落在红云台地的草地平原上。井边放着装满新鲜井水的“水罐”，供旅行者和营地管理员取回使用。",al={"水井位置","水井在哪里","寻找水罐"}},{q="鹰风酋长是谁？",a="鹰风酋长是负责监督红云台地纳拉其营地的酋长。他指导年轻牛头人的训练和精神仪式，为他们前往莫高雷更广阔的地区为部落服务做好准备。",al={"鹰风酋长","酋长是谁","纳拉其营地首领"}},{q="为什么这种琐事被视为一项重要的考验？",a="牛头人文化非常重视谦逊、社区支持和对长者的尊重。完成这些平淡无奇的日常职责表明，冒险者关心的是如何维持族人的生存，而不仅仅是在战斗中寻求个人的荣耀。",al={"为什么要背水","为什么是卑微的任务","这个任务重要吗"}},{q="完成“卑微的任务”后要做什么？",a="完成这项任务证明了你的纪律性，鹰风酋长随后会指引你参加“大地之母仪式”——这是所有成年牛头人必须经历的一系列传统挑战。",al={"接下来是什么","后续任务","卑微的任务之后"}},{q="这条道路最终通向哪里？",a="赢得纳拉其营地长者的尊重，将为你离开僻静的台地，踏入莫高雷更广阔的平原，并最终前往首都雷霆崖的高台地做好准备。",al={"未来目的地","我们要去哪里","雷霆崖目标"}}},fp="13,149,21.336.0,20.330.0,27.367.0,28.184.0,32.172.0,22.165.0,47.158.0,42.134.0,37.130.0"}
P.entries["quest:754"] = {n="净化冰蹄之井",s="“冰蹄净化”是血蹄村的穆尔·雷角委托给部落冒险者的一项仪式。在荆棘谷地精的非法作业污染了当地水源后，冒险者必须将一枚神圣的图腾带入荆棘谷地精的领地，以净化冰蹄水井。修复这处泉水是治愈莫高雷中部受污染水域至关重要的第一步。",h="“冰蹄净化”是血蹄村的穆尔·雷角委托给部落冒险者的一项仪式。在荆棘谷地精的非法作业污染了当地水源后，冒险者必须将一枚神圣的图腾带入荆棘谷地精的领地，以净化冰蹄水井。修复这处泉水是治愈莫高雷中部受污染水域至关重要的第一步。",kw={"血蹄村","净化","莫高雷","穆尔·雷角","毒","图腾","荆棘谷地精","水井","冰蹄"},ang={["class:Druid"]="看到口渴的野生动物立即回到净化后的泉水边，证明了在文明威胁要破坏自然的地方治愈自然是多么必要。",["class:Shaman"]="通过图腾引导灵魂来扭转不自然的工业污染，代表了萨满祭司与元素之水结合的核心目的。",["faction:Horde"]="保障莫高雷的淡水供应稳定了新定居的牛头人的心脏地带，加强了年轻部落的南方支柱。",["race:Tauren"]="莫高雷的水井是大地母亲赠予的生命之源；保卫它们免受地精贪婪的侵蚀，对每一位牛头人来说既是公民职责，也是神圣的义务。"},sec={{t="被蹂躏的土地",b="莫高雷的草原依赖于一个精巧的祖传水井网络来维持野生动物和星罗棋布的牛头人部族的生活。最近，荆棘谷地精那些冷酷无情的工业雇佣兵迁入了血蹄村东南方向的连绵丘陵。他们的作业已经污染了当地的蓄水层，导致冰蹄水井变得又脏又有毒。野生野兽避开受污染的水源，如果腐蚀进一步蔓延到大地，附近的营地将面临迫在眉睫的危机。"},{t="净化水源的仪式",b="为了对抗这些工业污垢，穆尔·雷角雕刻并附魔了一枚注入了大地母亲祝福的仪式净化图腾。然而，交付这个补救措施需要冒险者勇敢面对那些已经强占了泉水的全副武装的荆棘谷地精打手。通过将图腾直接放置在井口，冒险者可以驱散污浊的径流，让干净、充满生命力的水再次从大地深处涌出。"}},faq={{q="冰蹄水井在哪里？",a="冰蹄水井位于莫高雷血蹄村东南方向的丘陵地带。那里有荆棘谷地精的工人和雇佣兵在严密巡逻。",al={"冰蹄水井位置","冰蹄水井在哪","如何找到冰蹄水井"}},{q="为什么水井会被投毒？",a="荆棘谷地精在附近建立了采矿和挖掘作业点，导致有毒的工业径流和垃圾直接渗入蓄水层，使得当地野生动物和牛头人无法饮用这些天然泉水。",al={"谁污染了水源","为什么水井变脏了","荆棘谷地精水井"}},{q="穆尔·雷角是谁？",a="穆尔·雷角是一位驻扎在血蹄村的精神长老。他与大地的健康息息相关，通过制作仪式图腾来消除外来入侵者造成的环境破坏。",al={"穆尔是谁","穆尔·雷角的职责"}},{q="水井净化后会发生什么？",a="一旦冰蹄水井变得清澈，野生动物开始再次安全饮水，穆尔·雷角会引导你关注莫高雷的其他受损水井，首先就是雷角图腾。",al={"接下来是什么","冰蹄净化之后","穆尔下一步做什么"}},{q="水井处的守卫是谁？",a="水井被荆棘谷地精雇佣的工人和帮工占据，这是一个冷酷无情的地精领导的辛迪加组织，为了榨取自然资源而不顾当地生态系统。",al={"谁守卫着冰蹄水井","水井处有什么敌人"}},{q="净化图腾是如何运作的？",a="图腾上刻有神圣的牛头人礼仪和防御仪式，它汲取自然之灵和大地母亲的祝福，以净化泉水源头中不自然的化学污染物。",al={"净化图腾传说","穆尔图腾如何运作"}}},fx={["16ee77f0"]={q="穆尔·雷角为什么想净化冰蹄水井？",a="冰蹄水井对莫高雷的平衡与生存至关重要。井水遭到污染，威胁着当地野生生物以及依赖它的部族。穆尔·雷角已备好一根祝圣净化图腾，但必须将它带到水井所在之处，才能净化水源、恢复土地的和谐。",al={"为什么要净化冰蹄水井","穆尔·雷角的意图","为什么净化冰蹄水源"}}},fp="20,271,16.402.0,30.304.0,43.149.0,32.169.0,24.179.0,40.174.1,31.180.0,34.179.0"}
P.entries["quest:7541"] = {n="为部落效力",s="镶满珠宝的吊坠现在交给了奥格瑞玛的佐尔·孤树，这是在完成“向佐尔报告”后交付的。佐尔还有话要对你说。",h="镶满珠宝的吊坠现在交给了奥格瑞玛的佐尔·孤树，这是在完成“向佐尔报告”后交付的。佐尔还有话要对你说。",kw={"尘泥沼泽","吊坠","向佐尔报告","服务部落","佐尔·孤树"},sec={{t="奥格瑞玛的佐尔·孤树",b="你将镶满珠宝的吊坠送到了奥格瑞玛的佐尔·孤树手中，吊坠现在由佐尔保管。回到佐尔·孤树那里，听听关于你为部落所做贡献的更多评价。"},{t="佐尔的临别之言",b="佐尔说学者们需要时间来研究这枚吊坠。作为你服务部落的奖赏，佐尔提供了一点小小的谢礼，并表示你所做的一切为你自己和部落都带来了荣誉。"}},faq={{q="现在谁拿着吊坠？",a="奥格瑞玛的佐尔·孤树，在你将它从蕨墙村的纳泽尔·血矛那里送来之后。",al={"谁接收吊坠","谁给予此任务","佐尔·孤树的角色"}},{q="在此任务之前是什么任务？",a="它紧接在“向佐尔报告”之后，你当时带着镶满珠宝的吊坠去见了佐尔·孤树。",al={"之前的任务是什么","服务部落的前置条件","上一个任务"}}},fp="20,117,25.121.0,15.174.1,24.109.0,29.75.0"}
P.entries["quest:755"] = {n="大地之母仪祭",s="“大地母亲的仪式”标志着一位新人在红云台地的精神旅程的开始。在鹰风酋长的指引下，旅者们会前往纳拉其营地南部的山丘寻找灰舌先知。承担这些古老的仪式被视为牛头人成年过程中至关重要的试炼。",h="“大地母亲的仪式”标志着一位新人在红云台地的精神旅程的开始。在鹰风酋长的指引下，旅者们会前往纳拉其营地南部的山丘寻找灰舌先知。承担这些古老的仪式被视为牛头人成年过程中至关重要的试炼。",kw={"纳拉其营地","鹰风酋长","大地母亲","红云台地","大地母亲的仪式","灰舌先知","牛头人"},ang={["class:Druid"]="德鲁伊候选人通过尊重部落长者和先知的神圣指引，开启他们与自然和谐相处的道路。",["class:Shaman"]="对于有抱负的萨满祭司而言，进行由部落先知祝福的仪式是通往与元素以及莫高雷之灵沟通的重要第一步。",["faction:Horde"]="了解这些神圣的试炼可以让人深入洞察这些近期加入部落的牛头盟友的精神核心。",["race:Tauren"]="“大地母亲的仪式”代表了年轻牛头人基础性的精神旅程，考验着他们为部落服务并崇敬大地母亲的决心。"},sec={{t="试炼的开端",b="在红云台地上，鹰风酋长指引着那些渴望证明自己的年轻牛头人去寻找灰舌先知。灰舌先知居住在纳拉其营地正南方宁静的山丘中，负责监督年轻人的精神启蒙。这段简单的旅程标志着日常营地生活与部落习俗所要求的庄严承诺之间的正式门槛。"},{t="拥抱大地母亲",b="大地母亲是牛头人创世信仰和日常生活中的核心。她的仪式是关于成熟、坚韧和精神深度的神圣试炼。正如灰舌先知告诫每一位来到他居所的人那样，开启“大地母亲的仪式”绝非易事，它需要对台地的传统保持全心全意的奉献。"}},faq={{q="谁发布了“大地母亲的仪式”这个任务？",a="该任务由纳拉其营地的鹰风酋长发起，他会指引年轻的冒险者去寻找周围山丘中的灰舌先知。",al={"谁开启大地母亲的仪式","任务发布者"}},{q="我在哪里可以找到灰舌先知？",a="灰舌先知居住在位于莫高雷红云台地中，纳拉其营地正南方的山丘里。",al={"灰舌先知在哪里","灰舌位置","寻找灰舌"}},{q="什么是“大地母亲的仪式”？",a="“大地母亲的仪式”是牛头人青年为了证明他们对自己的人民和信仰的智慧、力量与奉献而进行的一项传统神圣试炼。",al={"什么是大地母亲的仪式","大地母亲试炼背景"}},{q="灰舌先知是谁？",a="灰舌先知是一位受人尊敬的精神长者，居住在纳拉其营地以南，负责监督并指引新人完成大地母亲的神圣试炼。",al={"灰舌先知是谁","灰舌职责"}},{q="鹰风酋长是谁？",a="鹰风酋长是掌管红云台地上纳拉其营地的部落领袖，他的职责是在将年轻的牛头人送往先知那里之前对其进行准备。",al={"鹰风酋长是谁","鹰风职责"}},{q="完成这项任务需要做什么？",a="你只需要从纳拉其营地向南前往山丘，与灰舌先知交谈，表明你已为试炼做好了准备。",al={"我需要做什么","如何完成任务"}}},fp="24,194,27.268.0,25.248.0,45.103.0,33.96.0,38.150.0,23.140.0,22.111.0,39.125.0"}
P.entries["quest:756"] = {n="雷角图腾",s="“雷角图腾”是血蹄村的穆尔·雷角发布的一项任务，旨在制作一个神圣的净化图腾。为了对抗正在污染莫高雷水井的荆棘谷地精，年轻的部落勇士必须从平原捕食者身上收集自然的爪子，将这片土地原始的力量束缚在仪式木桩之中。",h="“雷角图腾”是血蹄村的穆尔·雷角发布的一项任务，旨在制作一个神圣的净化图腾。为了对抗正在污染莫高雷水井的荆棘谷地精，年轻的部落勇士必须从平原捕食者身上收集自然的爪子，将这片土地原始的力量束缚在仪式木桩之中。",kw={"血蹄村","净化","平原狮的爪子","平原狮","莫高雷","穆尔·雷角","草原捕食者","草原捕食者的爪子","雷角图腾","水井"},ang={["class:Hunter"]="收集爪子需要了解平原上的原生捕猎野兽，并尊重杀戮以保护生态系统。",["class:Shaman"]="图腾的修复依赖于召唤大地的生命之灵，以净化因不自然、粗心的企业行为而受到腐蚀的水源。",["race:Tauren"]="保卫莫高雷的含水层免受外来者的剥削是神圣的部落职责，这反映了大地母亲关于平衡共存而非掠夺的训导。"},sec={{t="狩猎平原捕食者",b="随着荆棘谷地精的工业开采污染了莫高雷珍贵的水源，穆尔·雷角正急于寻找补救措施。制作雷角之井净化图腾需要平原上最专注的猎手——草原捕食者和平原狮——身上的自然精粹。通过获取这些在血蹄村东西方游荡的捕食者的爪子，仪式能够将野生动物原始且未被腐蚀的捕猎活力直接注入图腾之中。"},{t="狩猎的本质",b="牛头人的传统认为，为了维持生计或精神平衡而进行的狩猎，与地精所实行的掠夺性开采之间有着深刻的区别。穆尔强调，本土捕食者狩猎时所具备的纯粹性，对于净化被腐蚀的土地至关重要。地精的机器用石油和工业废料玷污了泉水，而这些与土地抗争的野兽所拥有的自然力量，正提供了恢复雷角水井所需的精神催化剂。"}},faq={{q="穆尔·雷角为什么需要捕食者的爪子？",a="穆尔使用草原捕食者和平原狮的爪子，将平原纯净、原始的捕猎精神灌注到净化图腾中。他相信自然猎手的纯净精神能够抵消人为的工业腐蚀。",al={"为什么需要爪子","草原捕食者爪子的用途","平原狮爪子的目的"}},{q="是谁在腐蚀莫高雷的水源？",a="在莫高雷活动的荆棘谷地精正在污染这片土地和水源。他们肆无忌惮的资源开采和采矿钻机将有毒淤泥排入了滋养部落水井的含水层中。",al={"谁污染了水井","为什么水井被下毒","什么东西毒害了莫高雷"}},{q="在哪里可以找到草原捕食者和平原狮？",a="这两种野兽都栖息在莫高雷中部的开阔平原上，主要分布在血蹄村东部和西部的连绵稀树草原中。",al={"草原捕食者位置","去哪里找平原狮","平原狮爪子掉落位置"}},{q="制作雷角图腾后会发生什么？",a="当穆尔用这些爪子雕刻并附魔图腾后，他会直接派遣你去受污染的雷角水井执行净化仪式，驱散其中的毒素。",al={"接下来做什么","雷角图腾之后","图腾任务后续"}},{q="这与之前冰蹄水井的净化有什么联系？",a="这是部落为保护莫高雷神圣水源而进行的持续努力的一部分。冰蹄水井首先得到了净化，而现在污染正威胁着北部的雷角水井。",al={"冰蹄水井的关联","上一个图腾任务"}},{q="为什么牛头人不使用草药疗法，而要使用动物爪子？",a="牛头人的仪式工艺汲取了自然界中独特的元素和物理特性。顶级捕食者那种尖锐的纯净感，提供了一种特定的、充满活力的精神力量，这是切断地精工业毒素侵蚀所必需的。",al={"为什么不用草药","萨满图腾材料"}}},fp="17,236,28.346.0,22.354.0,46.210.0,39.176.0,58.144.0,50.174.1,66.166.0,72.198.0"}
P.entries["quest:757"] = {n="力量仪祭",s="力量试炼是牛头人年轻人必须在纳拉其营地进行的传统大地之母试炼中的首项考验。为了证明自己的勇气并保卫部族，试炼者必须在刺刃峡谷清除那些不断入侵的鬃毛野猪人，并将它们的腰带呈交给鹰风酋长。",h="力量试炼是牛头人年轻人必须在纳拉其营地进行的传统大地之母试炼中的首项考验。为了证明自己的勇气并保卫部族，试炼者必须在刺刃峡谷清除那些不断入侵的鬃毛野猪人，并将它们的腰带呈交给鹰风酋长。",kw={"刺刃峡谷","鬃毛野猪人","纳拉其营地","鹰风酋长","大地之母","莫高雷","野猪人","力量试炼","灰舌先知"},ang={["faction:Horde"]="保卫台地可以确保部落的一个核心征兵基地安全，确保年轻的战士和萨满能够安全成长，为新联盟提供助力。",["race:Tauren"]="每一位牛头人年轻人都从这些古老的试炼开始他们的旅程，在离开红云台地之前，证明自己已做好准备去保护族人免受野猪人的威胁。"},sec={{t="第一项试炼",b="对于寻求部族长者认可并最终被雷霆崖接纳的牛头人年轻人来说，完成大地之母试炼是一项基本义务。由灰舌先知传授的力量试炼是这一系列试炼的起点。它要求试炼者展现出身体上的勇气，并能在保卫红云台地的战斗中果断出击，从而考验试炼者能否直面部族的致命敌人而毫无退缩。"},{t="鬃毛野猪人的威胁",b="这项试炼的选定地点是刺刃峡谷，这是一道位于纳拉其营地东侧、荆棘丛生的裂谷，被鬃毛野猪人所占据。这些极具侵略性的闯入者不断践踏部族的祖居之地，伏击狩猎队，并趁着夜色劫掠营地的补给。猎杀它们并收集其腰带，既是勇气的证明，也是保障营地安全的必要措施。"}},faq={{q="力量试炼的目的是什么？",a="这是大地之母试炼的奠基之步，旨在考验牛头人年轻人战斗中的勇气。通过清除对营地的敌对威胁，试炼者有权继续前行，向雷霆崖争取真正的尊重。",al={"为什么要进行力量试炼","力量试炼背景","力量试炼的目的"}},{q="谁负责指派并评判这项试炼？",a="灰舌先知负责向试炼者下达任务，概述试炼的精神与实践要求。当收集到十二条鬃毛野猪人腰带后，这份勇气证明必须直接呈交给纳拉其营地的鹰风酋长。",al={"谁发布力量试炼","谁负责交付力量试炼"}},{q="刺刃峡谷位于何处？",a="刺刃峡谷位于纳拉其营地正东方的红云台地上。那是一条荆棘密布的峡谷，四处潜伏着敌对的鬃毛野猪人。",al={"刺刃峡谷在哪里","刺刃峡谷位置"}},{q="为什么要针对鬃毛野猪人？",a="鬃毛野猪人正在侵占部族的祖传狩猎场。它们多次伏击牛头人猎人，并在夜间从纳拉其营地盗取补给，是部族直接的敌人。",al={"为什么要猎杀鬃毛野猪人","野猪人做了什么"}},{q="为什么要收集腰带而不是其他战利品？",a="腰带是被击败战士的实物凭证，证明试炼者在近距离与野猪人交锋，并击败了成年战士，而不是仅仅从远处进行拾荒。",al={"为什么要收集鬃毛野猪人腰带","为什么要腰带"}},{q="完成力量试炼后要做什么？",a="通过力量试炼证明了自身的勇气，使试炼者有资格进行后续的大地之母试炼，从而继续正式的成年之路，并提升在部族中的精神地位。",al={"力量试炼之后做什么","下一项大地之母试炼"}}},fp="16,165,15.312.0,22.298.0,44.205.0,34.166.0,37.131.0,40.177.0,44.137.0,49.206.0"}
P.entries["quest:758"] = {n="净化雷角之井",s="“雷角之井净化”是莫高雷一项至关重要的精神仪式，旨在委托旅行者净化遭受腐蚀的雷角水井。借助穆尔·雷角准备的仪式图腾，探险者们能够修复对当地部落至关重要的受污染泉水。净化成功将赢得雷角氏族祖先发自内心的赞许。",h="“雷角之井净化”是莫高雷一项至关重要的精神仪式，旨在委托旅行者净化遭受腐蚀的雷角水井。借助穆尔·雷角准备的仪式图腾，探险者们能够修复对当地部落至关重要的受污染泉水。净化成功将赢得雷角氏族祖先发自内心的赞许。",kw={"祖先之灵","血蹄村","净化图腾","大地母亲","莫高雷","穆尔·雷角","雷角之井净化","雷角水井"},ang={["class:Druid"]="净化受毒的水源可以阻止腐蚀在莫高雷生态系统中的蔓延，从而保护平原的自然和谐。",["class:Shaman"]="通过图腾引导祖先能量来治愈受腐蚀的天然泉水，这正是萨满教义的基础。",["faction:Horde"]="协助牛头人保护他们神圣的泉水，加强了年轻的部落与其骄傲的舒哈鲁盟友之间的纽带。",["race:Tauren"]="修复神圣的泉水是对大地母亲的敬奉，也能在你的族人于莫高雷开辟永久而宁静的家园时保护他们。"},sec={{t="受到污染的生命线",b="莫高雷广袤平原上的水井，是近期在此定居的牛头人游牧部落不可或缺的生命线。当邪恶的毒素污染了这些地下泉水，野生动物和附近的定居点都将面临灾难性的后果。位于血蹄村北部的雷角水井不幸遭到了污染，需要进行慎重的精神干预来治愈这片受困的土地。"},{t="祖先的净化",b="为了抵御腐蚀，穆尔·雷角制作了一根蕴含精神力量的神圣净化图腾。将这件圣物直接带到受污染的水源处，探险者们便能将祖先的力量注入泉水中，驱散毒素并恢复原始的自然平衡。当雷角氏族的祖先之灵在梦中拜访穆尔并表达他们永恒的感激时，穆尔便能直接确认此项善举的成功。"}},faq={{q="雷角水井位于何处？",a="雷角水井位于莫高雷血蹄村北部的平原上。它是为当地牛头人部族提供水源的几处重要水潭之一。",al={"雷角水井位置","水井在哪里","在哪里使用图腾"}},{q="谁发起了这项净化仪式？",a="穆尔·雷角发起了这项仪式。你可以在血蹄村找到他，他正在那里制作专门的图腾，以治愈莫高雷受损的环境。",al={"谁提供任务","穆尔·雷角位置","任务发布者"}},{q="为什么要净化莫高雷的水井？",a="莫高雷各地的水井都遭受了非自然的毒害和腐蚀，这威胁到了平原脆弱的平衡以及依赖净水生存的牛头人部落。",al={"为什么要净化水井","水怎么了","为什么水井被污染"}},{q="穆尔是如何得知仪式成功的？",a="在完成水井的仪式后，雷角氏族的祖先之灵会直接在梦中显现给穆尔，赞扬探险者的事迹并致以祖先的谢意。",al={"祖先梦境","穆尔如何得知","净化水井的结果"}},{q="净化雷角水井之后要做什么？",a="净化雷角水井是保护莫高雷泉水更广泛工作的一部分。接下来，穆尔会派遣旅行者前往另一个受困地区，通过制作狂鬃图腾来提供援助。",al={"接下来做什么","雷角之后的任务","狂鬃图腾后续"}},{q="什么是雷角之井净化图腾？",a="雷角之井净化图腾是由穆尔·雷角专门制作的一种经过仪式雕刻的精神焦点，旨在净化他所在部族祖传水井中受污染的水。",al={"净化图腾","什么是图腾物品","穆尔的图腾"}}},fx={da3030fe={q="穆尔·雷角为什么需要你净化水井？",a="穆尔·雷角已经制作好了仪式法器，但净化圣地是牛头人及其盟友的新晋勇士必须履行的服务与荣誉仪式。你亲自将雷角之井净化图腾带到受污染的水井，就能证明自己对大地母亲和他氏族祖灵的虔诚，并赢得守护水源的祖灵的恩宠与指引。",al={"穆尔·雷角为什么找我","穆尔为什么派你去","为什么要举行净化仪式"}}},fp="21,203,18.263.0,19.244.0,44.156.0,36.113.0,48.90.0,45.101.0,51.116.0,40.136.0"}
P.entries["quest:759"] = {n="蛮鬃图腾",s="野鬃图腾代表了穆尔·雷角为净化莫高雷被污染的水井而制作的净化图腾的第三个也是最后一个阶段。为了恢复野鬃之井，仪式需要从该地区最凶猛的天然捕食者——草原狼首领——身上获取祭品。",h="野鬃图腾代表了穆尔·雷角为净化莫高雷被污染的水井而制作的净化图腾的第三个也是最后一个阶段。为了恢复野鬃之井，仪式需要从该地区最凶猛的天然捕食者——草原狼首领——身上获取祭品。",kw={"血蹄村","莫高雷","穆尔·雷角","草原狼首领","雷霆崖","图腾","水井","野鬃"},ang={["class:Hunter"]="在高耸的悬崖周围追踪狡猾的首领狼，考验着猎人对荒野及其最敏锐捕食者的尊重。",["class:Shaman"]="萨满祭司们能够领会其中的微妙仪式，即通过调和捕食者图腾与元素之水，来清除毒害。",["race:Tauren"]="净化祖先水井强调了牛头人修复环境失衡并敬重大地母亲所要求的牺牲的义务。"},sec={{t="最后一座水井",b="在收集到制作冬蹄之井和雷角之井净化图腾所需的材料后，莫高雷中部只剩下一处受污染的水源：野鬃之井。平原上被毒化的水源正威胁着迁徙的野生动物和定居点，需要强大的原始素材来恢复大地的自然平衡。"},{t="捕食者的力量",b="为了对抗北方水域中挥之不去的强烈腐蚀，穆尔·雷角需要一份凶猛的祭品。草原狼首领潜伏在草原上，尤其是在雷霆崖下方高耸的悬崖周围。收集它们的牙齿，可以将莫高雷顶级猎手的无情动力和韧性直接注入到净化图腾的制作中。"},{t="牺牲与平衡",b="在牛头人的精神传统中，利用土地上的生物带有情感和元素上的重量。穆尔认为收集首领牙齿并非征服，而是一种沉重的必要之举，通过牺牲莫高雷的捕食者来帮助治愈大地母亲遭受重创的水域。"}},faq={{q="野鬃图腾有什么用？",a="该图腾由穆尔·雷角制作，用于净化野鬃之井，这是威胁到莫高雷牛头人的最后一处被污染的水源。",al={"为什么制作野鬃图腾","野鬃图腾的作用"}},{q="为什么特别需要草原狼首领的牙齿？",a="净化野鬃之井深层的污染需要引导顶级捕食者凶猛而坚韧的力量。狼群首领的牙齿提供了必要的原始力量。",al={"为什么需要狼牙","草原狼首领牙齿的用途"}},{q="在莫高雷哪里可以找到草原狼首领？",a="草原狼首领徘徊在莫高雷的北部平原，通常出没在雷霆崖基座周围的草原上。",al={"草原狼首领位置","去哪里找草原狼首领"}},{q="谁制作了图腾？",a="穆尔·雷角，驻守在血蹄村的一位精神长老，在试炼者收集到必要的祭品后会制作每一个净化图腾。",al={"谁制作图腾","图腾任务发布者"}},{q="制作完野鬃图腾后要做什么？",a="当穆尔·雷角用首领牙齿组装好图腾后，你将被派往北方，在野鬃之井进行实际的净化仪式。",al={"接下来是什么","野鬃图腾后续任务"}},{q="这种仪式如何体现牛头人的信仰？",a="牛头人将夺取动物的生命视为与自然之间庄严的交换。穆尔承认狼群的牺牲，既为它们的死亡感到悲伤，也为它们在治愈大地中所扮演的角色感到自豪。",al={"牛头人图腾哲学","穆尔·雷角的信仰"}}},fx={["054e923c"]={q="穆尔·雷角为什么想制作蛮鬃图腾？",a="莫高雷只剩下一口遭到污染的水井尚未净化——那就是蛮鬃氏族的水井。穆尔·雷角立志净化大地母亲的圣泉，而借助这片土地上掠食者的灵性制作最后一根净化图腾，是完成神圣仪式、为部族恢复纯净水源的关键。",al={"穆尔·雷角为什么要蛮鬃图腾","穆尔·雷角的意图","为什么制作蛮鬃图腾"}},["2aa23a29"]={q="草原狼前锋的牙齿有什么用？",a="草原狼首领的牙齿象征着莫高雷顶级掠食者的牺牲与凶猛活力。穆尔·雷角会将八颗獠牙嵌入蛮鬃图腾，使其中的灵性能安抚自然秩序，并赋予仪式所需的力量，以清除蛮鬃水井中的污秽。",al={"草原狼前锋的牙齿用途","草原狼前锋的牙齿有什么用","蛮鬃图腾所需的牙齿"}},eb5f4bd0={q="为什么要猎杀草原狼前锋？",a="你要猎杀草原狼前锋——它们是盘踞在雷霆崖山脚附近平原上的狼群首领。它们的力量与凶猛体现了平原的自然平衡，也能为穆尔·雷角最终的净水仪式提供所需的强大精华。",al={"为什么杀草原狼前锋","草原狼前锋目标","你要追捕谁"}}},fp="14,153,14.306.0,23.274.0,21.212.0,38.121.0,55.138.0,47.114.0,21.125.0,48.106.0,44.146.0"}
P.entries["quest:76"] = {n="玉石矿洞",s="在发现狗头人已经占领了法戈第矿洞后，治安官杜汉派遣侦察兵去调查更东边的玉石矿洞。到达目的地后情况得到了证实，最糟糕的预感应验了：这种入侵已经蔓延到了艾尔文森林重要的矿脉上，这让暴风城剩余的守军疲于奔命，达到了极限。",h="在发现狗头人已经占领了法戈第矿洞后，治安官杜汉派遣侦察兵去调查更东边的玉石矿洞。到达目的地后情况得到了证实，最糟糕的预感应验了：这种入侵已经蔓延到了艾尔文森林重要的矿脉上，这让暴风城剩余的守军疲于奔命，达到了极限。",kw={"阿祖拉","杜汉","艾尔文","法戈第","闪金镇","玉石矿洞","狗头人","矿洞","侦察"},ang={["faction:Alliance"]="法戈第和玉石矿洞的同时失守，暴露了在缺乏中央王权支持的情况下，暴风城的腹地是多么脆弱。",["profession:Mining"]="对于矿工来说，看到富饶的地下矿脉被害虫占领是令人苦涩的景象。玉石矿洞的隧道里蕴藏着宝贵的矿藏，但要开采它们，必须通过重重驻扎的狗头人的包围。",["race:Human"]="人类侦察兵亲眼见证了艾尔文森林农村基础设施的逐渐崩溃，边境资源就在首都的家门口不断陷落。"},sec={{t="第二次入侵",b="在确认了狗头人已经侵占了闪金镇南部的法戈第矿洞隧道后，治安官杜汉担心这并非个例。坐落在阿祖拉之塔东北方岩石丘陵中的玉石矿洞，是王国获取矿石与金属的另一个重要来源。由于无法抽调暴风城卫兵离开城镇去巡逻，杜汉不得不依靠独立冒险者向东深入，去确认这个地方是否也沦陷给了那些顶着蜡烛的地下害虫。"},{t="过度扩张的防御",b="深入调查玉石矿洞的内部发现，狗头人已经完全取代了人类矿工，它们在黑暗的通道中挖掘并修建了防御工事。对治安官杜汉来说，这份严峻的报告无异于在日益严重的危机中雪上加霜。由于瓦里安·乌瑞恩国王失踪，且皇家军队被限制在边境领土之外，当地驻军缺乏足够的人手来清理矿洞，导致王国的核心地带在经济上陷入匮乏，在地理上也陷入了困境。"}},faq={{q="玉石矿洞在哪里？",a="矿洞位于艾尔文森林东部的北部丘陵中。前往此处，需沿着闪金镇的主路向东走，到达阿祖拉之塔，然后向北进入丘陵即可。",al={"玉石矿洞在哪里","玉石矿洞位置","如何找到玉石矿洞"}},{q="为什么治安官杜汉需要侦察兵而不是派遣卫兵？",a="由于首都的政治僵局以及瓦里安·乌瑞恩国王的失踪，艾尔文森林的暴风城卫兵严重人手不足。由于当地部队兵力薄弱，又要保护农场和城镇免受强盗和豺狼人的侵害，治安官杜汉必须依赖民间的侦察兵。",al={"为什么要派遣冒险者","为什么没有暴风城卫兵","卫兵在哪里"}},{q="为什么狗头人要占领艾尔文森林的矿洞？",a="狗头人是天生的掘地者，被地下的矿脉和潮湿的洞穴所吸引。随着暴风城军事力量的削弱，这些生物变得更加大胆，大肆侵入像法戈第和玉石矿洞这样的人类矿场，以掠夺黄金、矿石和领地。",al={"为什么狗头人在玉石矿洞","狗头人想要什么","狗头人入侵原因"}},{q="侦察玉石矿洞之后会发生什么？",a="一旦你向治安官杜汉报告了玉石矿洞的沦陷，他会承认艾尔文森林正面临多线受敌的残酷现实。在确认东部矿洞失守后，他的注意力转移到了西艾尔文森林，那里的西泉要塞正面临河爪豺狼人的沉重压力。",al={"玉石矿洞之后做什么","玉石矿洞后续"}},{q="为什么玉石矿洞的丢失对暴风城意义重大？",a="艾尔文森林的矿洞提供了维持暴风城经济以及铸造武器和盔甲所需的原料矿石与石料。法戈第和玉石矿洞的双双丢失中断了矿产开采，严重损害了王国的恢复努力。",al={"为什么玉石矿洞很重要","玉石矿洞重要性"}},{q="附近的阿祖拉之塔是谁的？",a="阿祖拉之塔是一座位于艾尔文森林东部大路旁的小型法师塔，由阿祖拉大法师塞欧克瑞图斯主持，并由阿祖拉的仆从们运营。它是前往东部丘陵的旅人们的标志性地标。",al={"什么是阿祖拉之塔","谁住在阿祖拉之塔"}}},fx={a973508b={q="治安官杜汉为什么要侦察玉石矿洞？",a="在确认狗头人已经占据法戈第矿洞后，治安官杜汉担心这并非孤立的事件。他需要知道，这一威胁是否也已向东蔓延至玉石矿洞。确保艾尔文的资源供应，并摸清这股步步逼近的危险究竟有多大，对于保卫闪金镇、保护暴风城的重要贸易路线至关重要。",al={"杜汉侦察玉石矿洞的动机","为何侦察玉石矿洞","杜汉为何需要调查玉石矿洞"}}},fp="19,146,18.366.0,21.386.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="净化蛮鬃之井",s="蛮鬃之井净化是牛头人净化莫高雷重要水源的仪式努力的最高潮。在血蹄村接受穆尔·雷角的委托后，英雄们带着制作完成的蛮鬃图腾向北前往，去净化最后一座被污染的水井。击退荆棘谷地精的污染不仅恢复了平原的平衡，也保障了牛头人部落的田园生活。",h="蛮鬃之井净化是牛头人净化莫高雷重要水源的仪式努力的最高潮。在血蹄村接受穆尔·雷角的委托后，英雄们带着制作完成的蛮鬃图腾向北前往，去净化最后一座被污染的水井。击退荆棘谷地精的污染不仅恢复了平原的平衡，也保障了牛头人部落的田...",kw={"血蹄村","净化","大地母亲","莫高雷","穆尔·雷角","图腾","荆棘谷地精","水井","蛮鬃"},ang={["class:Druid"]="扭转地精对环境的破坏，直接体现了塞纳里奥议会治愈受损生态系统、保护青翠牧场的使命。",["class:Shaman"]="利用仪式图腾来消除机械污染，体现了萨满维护自然元素与生命群落之间和谐的职责。",["race:Tauren"]="修复莫高雷的三口祖传水井是一项基础的成人礼，证明了一位年轻勇士对保护大地母亲恩赐的虔诚。"},sec={{t="净化大地母亲的恩赐",b="在阳光普照的莫高雷平原上，水是神圣的生命之源，滋养着兽群、土地以及最近聚集在雷霆崖周围的游牧部落。当荆棘谷地精和入侵的地精开始用有毒的工业废料污染这些蓄水层时，牛头人长老们意识到了生存的威胁。在净化了冰蹄水井和雷角水井之后，蛮鬃水井成了第三个、也是最后一个需要进行精神干预的受污染地点。"},{t="蛮鬃图腾",b="蛮鬃之井净化图腾由在该地区收集的特定元素制成，它引导着祖先之魂和大地元素的力量进行修复。将图腾插在雷霆崖以北污浊的水边，可以驱散有害的化学物质，吸出毒素并恢复自然流动。通过完成这一仪式，牛头人保护了族人免受疾病侵害，并传达了一个明确的信息：绝不容忍对他们圣地的亵渎。"}},faq={{q="蛮鬃水井为什么会被污染？",a="在工业贪婪和伐木事业的驱使下，地精的行动将恶毒的毒药和化学废料引入了莫高雷的地下水，威胁到了当地的野生动物和部落定居点。",al={"谁污染了水井","水井为何肮脏","地精毒素"}},{q="蛮鬃水井位于哪里？",a="蛮鬃水井位于雷霆崖高耸平顶山正北方的平原上。",al={"蛮鬃水井位置","蛮鬃水井在哪里","寻找蛮鬃水井"}},{q="谁发起了这个净化仪式？",a="驻扎在血蹄村的长老穆尔·雷角会引导你制作图腾，并派你去净化水井。",al={"谁发布了蛮鬃之井净化","任务发布者","穆尔·雷角的位置"}},{q="还有哪些水井属于这项净化工作的一部分？",a="蛮鬃水井是三个重要水源中的第三个，之前还有位于南方的冰蹄水井和雷角水井。",al={"其他水井","莫高雷水井","冰蹄水井和雷角水井"}},{q="净化图腾是如何工作的？",a="图腾中注入了祖先魔法和净化的自然元素，将修复性的精神能量引导入地下水位，以中和荆棘谷地精的污染物。",al={"净化图腾机制","图腾如何净化水"}},{q="完成这个仪式对血蹄村意味着什么？",a="净化这三口水井保证了莫高雷中部所有部落的饮水安全，也履行了牛头人治愈大地母亲、使其免受工业剥削的神圣职责。",al={"任务结果","为什么要净化水井","牛头人传说的重要性"}}},fx={["119d5a48"]={q="穆尔·雷角为什么想净化蛮鬃水井？",a="穆尔·雷角守护着莫高雷的精神平衡和重要资源。荆棘谷地精的污秽作业污染了土地珍贵的水源，威胁着各部族及其畜群的生存。蛮鬃水井是三口古老水井中最后一口仍遭污染的水井。净化它对于治愈大地母亲，并确保血蹄村和雷霆崖获得安全饮用水至关重要。",al={"穆尔·雷角的意图","为什么净化蛮鬃水井","穆尔为什么关心水井"}},b4cee6a1={q="蛮鬃之井净化图腾是什么？",a="蛮鬃之井净化图腾是穆尔·雷角制作的一种经过仪式准备的器具，用来引导先祖和大地之灵。在雷霆崖北面的蛮鬃水井受到污染后，于井边激活图腾，便能驱散地精污染者留下的有毒污泥，净化含水层，使泉水恢复自然、纯净的状态。",al={"蛮鬃之井净化图腾的用途","蛮鬃图腾是什么","净化图腾的作用"}}},fp="18,219,33.421.0,18.420.0,41.180.0,41.92.0,36.115.0,54.145.0,34.155.0,60.169.0"}
P.entries["quest:761"] = {n="猎捕猛鹫",s="狩猎猛鹫是哈肯·风之图腾在血蹄村提供的一项追踪与射击仪式。为了证明自己的机敏与耐心，猎人和旅行者们受命去莫高雷的草海平原追踪这种难以捉摸的鸟类。带着完好的猛鹫的羽毛归来，既证明了对狩猎的专注，也体现了对大地母亲自然试炼的尊重。",h="狩猎猛鹫是哈肯·风之图腾在血蹄村提供的一项追踪与射击仪式。为了证明自己的机敏与耐心，猎人和旅行者们受命去莫高雷的草海平原追踪这种难以捉摸的鸟类。带着完好的猛鹫的羽毛归来，既证明了对狩猎的专注，也体现了对大地母亲自然试炼的...",kw={"血蹄村","哈肯·风之图腾","莫高雷","猛鹫","狩猎猛鹫","牛头人试炼","猛鹫的羽毛"},ang={["class:Druid"]="在风蚀台地上追踪猛鹫，能让德鲁伊与维持莫高雷天空平衡的掠食鸟类建立更紧密的联系。",["class:Hunter"]="狩猎活动提供了一堂早期的进阶课，教授如何引导空中猎物、评估行为模式，并对警觉的掠食者进行精确打击。",["race:Tauren"]="对于牛头人青年和流浪者来说，狩猎莫高雷敏捷的猛鹫是一项神圣的成年仪式，它能磨砺追踪本能，并弘扬祖先的狩猎习俗。"},sec={{t="敏锐之眼的试炼",b="莫高雷的草原上充满了野兽，但很少有生物能像本土的猛鹫那样考验追猎者的直觉。这些大型掠食鸟类能与天际和草原融为一体，在头顶盘旋或贴着高草低飞。与笨拙的平原陆行鸟或吃草的科多兽不同，猛鹫需要高度的专注和敏捷的身手才能追捕到。因此，追捕猛鹫成了年轻猎人在部落中确立地位的传统证明仪式。"},{t="狩猎的徽记",b="对于哈肯·风之图腾来说，收集猛鹫的羽毛与其说是为了捕杀野生动物，不如说是为了培养纪律。在牛头人文化中，携带战利品象征着机敏与毅力。将这些完好的羽毛呈献给血蹄村的长者，标志着冒险者有能力供养和保卫社区，也证明了他们脚步迅捷，感官敏锐，足以驾驭更广阔的世界。"}},faq={{q="哈肯·风之图腾要求狩猎猛鹫的目的是什么？",a="哈肯·风之图腾委派猎人在莫高雷追踪猛鹫，以考验他们的机敏、速度和专注力。带回完好的猛鹫的羽毛是猎人技巧的公认证明，也能为他们赢得血蹄村牛头人的荣誉。",al={"为什么要狩猎猛鹫","哈肯·风之图腾的任务目的","狩猎猛鹫的目的"}},{q="通常在哪里能遇到猛鹫？",a="猛鹫分散在莫高雷的开阔平原上，它们会在草原上空翱翔，或是在血蹄村等定居点外搜寻草丛中的猎物。",al={"猛鹫在哪里","莫高雷的猛鹫位置","寻找猛鹫"}},{q="为什么说猛鹫很难狩猎？",a="与在平原上成群结队的动物不同，猛鹫是敏捷且警觉的猛禽，分布广泛且时刻保持警惕。追踪它们需要敏锐的视力来锁定它们的飞行轨迹，还需要快速的步伐，以便在它们逃脱前将其击落。",al={"为什么猛鹫难以捕获","猛鹫的行为习性"}},{q="猛鹫的羽毛对牛头人有什么意义？",a="在牛头人的传统中，猛鹫的羽毛代表着耐心、敏锐的洞察力和成功的追猎。展示这些羽毛意味着猎人拥有供养和保卫部落所必需的本能。",al={"猛鹫的羽毛含义","羽毛的意义"}},{q="哈肯·风之图腾是谁？",a="哈肯·风之图腾是血蹄村受人尊敬的牛头人居民，他会观察新来者和有志成为猎人的人，并通过在平原上进行的传统试炼来评估他们的足智多谋。",al={"谁提供狩猎猛鹫任务","哈肯·风之图腾的背景故事"}},{q="这种狩猎会影响莫高雷的自然平衡吗？",a="牛头人将狩猎视为与大地母亲的神圣对话，而非肆意屠杀。收集羽毛是一种衡量纪律的试炼，既是对猎物机敏的尊重，也维持了部落的平衡。",al={"狩猎猛鹫是否属于过度狩猎","猛鹫与莫高雷的平衡"}}},fx={["0d785fcd"]={q="哈肯·风之图腾为什么派外人去猎杀风鹏，而不是亲自去？",a="哈肯·风之图腾派你前去，并非因为他不会狩猎，而是为了考验你的能力。对牛头人来说，在平原上追踪狡猾的风鹏需要敏锐的目光、耐心和迅捷的蹄子。哈肯让你带回它们的羽毛，是给你一个向血蹄村证明技巧和决心的机会，表明你是一名真正出色的猎手。",al={"为什么让我去猎风鹏","哈肯为什么需要我帮忙","哈肯为什么不能自己猎风鹏"}}},fp="13,157,19.324.0,18.345.0,59.197.0,39.126.0,41.144.0,48.147.0,24.179.0,55.185.0"}
P.entries["quest:76156"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem 看出你有行事隐秘的天赋，请你进入荆棘谷地精的矿洞。他想让你从矿洞的补给车上取走 Seaforium Mining Charges。",h="Boarton Shadetotem 看出你有行事隐秘的天赋，请你进入荆棘谷地精的矿洞。他想让你从矿洞的补给车上取走 Seaforium Mining Charges。",kw={"爆破物资","boarton shadetotem","面具","矿洞","seaforium mining charges","敏锐","雷霆崖","荆棘谷地精"},ang={["class:Rogue"]="Boarton 认为，身为潜行者的你有行事隐秘的天赋，因此请你进入荆棘谷地精的矿洞。"},sec={{t="隐秘的手段",b="雷霆崖的 Boarton Shadetotem 相信你能隐秘行事。他给了你一副面具，请你进入附近荆棘谷地精的矿洞。你要在那里从装有爆破物资的矿车上取走 Seaforium Mining Charges，带回来交给他。"}},faq={{q="是谁让我进入矿洞的？",a="雷霆崖的 Boarton Shadetotem 请你进入荆棘谷地精的矿洞。",al={"boarton 是谁","boarton shadetotem","谁给的任务"}},{q="我要在矿洞里找什么？",a="你受托从装有爆破物资的矿车上取走 Seaforium Mining Charges。",al={"偷什么","矿洞物资","seaforium charges"}},{q="Boarton 为什么给我面具？",a="Boarton 给你一副面具，让你用来进入附近荆棘谷地精的矿洞。",al={"面具伪装","为什么要面具","潜入矿洞"}},{q="荆棘谷地精的矿洞在哪里？",a="矿洞位于雷霆崖的东南方。",al={"矿洞位置","矿洞在哪里","荆棘谷地精矿洞"}},{q="这些物资是从谁那里取走的？",a="这些物资在荆棘谷地精的矿洞里。",al={"物资属于谁","荆棘谷地精物资","公司矿洞"}}},fp="26,172,17.257.0,30.79.0,34.79.0,32.70.0,34.39.0,32.45.0"}
P.entries["quest:76160"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem请你用雷霆崖以北的风怒球果制作药膏。他希望这种药膏能让刀刃造成的伤口产生剧烈的灼痛。",h="Boarton Shadetotem请你用雷霆崖以北的风怒球果制作药膏。他希望这种药膏能让刀刃造成的伤口产生剧烈的灼痛。",kw={"boarton shadetotem","鹰身人","研钵和研杵","药膏","stalk with the earthmother","雷霆崖","windfury cones"},sec={{t="苦痛药膏",b="雷霆崖的Boarton Shadetotem想要一种剧毒药膏，原料是从北方鹰身人巢穴附近采集的球果。你需要用研钵和研杵碾碎风怒球果，再把制成的药膏交给他。他警告说，制成的药膏即使只是沾到皮肤，也可能引起疼痛。"}},faq={{q="是谁想要这种药膏？",a="雷霆崖的Boarton Shadetotem请你用风怒球果配制药膏。",al={"谁想要药膏","boarton shadetotem的请求"}},{q="风怒球果长在哪里？",a="雷霆崖以北的鹰身人在一棵树上筑巢，这棵树会分泌有毒的树脂。掉落的球果散落在它们的巢穴周围。",al={"哪里能找到球果","风怒球果位置"}},{q="这种药膏有什么用途？",a="这种药膏涂在刀刃上，能让对手的伤口灼痛，并使其血液化为盐。",al={"药膏有什么作用","刀刃淬毒药膏"}},{q="Boarton为什么警告不要触碰药膏？",a="Boarton说，制成的药膏即使只是接触皮肤，也可能引起疼痛。",al={"药膏接触皮肤警告","药膏是否危险"}}},fp="26,156,14.271.0,28.84.0,33.117.0,30.102.0,40.72.0"}
P.entries["quest:762"] = {n="邪恶的使者",s="史学家卡尼克希望你能除掉苦痛堡垒的因弗努斯大使。你需要回到荒芜之地，并将他被击杀的证明带给铁炉堡的顾问贝尔格拉姆。",h="史学家卡尼克希望你能除掉苦痛堡垒的因弗努斯大使。你需要回到荒芜之地，并将他被击杀的证明带给铁炉堡的顾问贝尔格拉姆。",kw={"顾问贝尔格拉姆","因弗努斯大使","苦痛堡垒","荒芜之地","史学家卡尼克","铁炉堡","拉格纳罗斯","黑铁矮人","奥达曼"},sec={{t="苦痛堡垒的大使",b="炎魔拉格纳罗斯亲自派遣因弗努斯大使前往苦痛堡垒，监督黑铁矮人在奥达曼搜寻失落的神器。矮人为此付出的生命代价已经非常惨重，而且还在不断增加。卡尼克不敢想象如果让黑铁矮人找到神器并用来对付铁炉堡，后果会有多严重。你必须回到荒芜之地，消灭因弗努斯，并将你胜利的证明带给贝尔格拉姆。时间紧迫，因为拉格纳罗斯可不会等他们慢慢准备。"},{t="贝尔格拉姆的谢意",b="贝尔格拉姆称赞了你对铁炉堡和矮人同胞的贡献，并会将你成功的消息传达给卡尼克。铁炉堡也将派遣援军前往荒芜之地以夺回挖掘场。以铜须国王的名义，贝尔格拉姆还有一件事要拜托你。"}},faq={{q="因弗努斯大使是谁？",a="拉格纳罗斯亲自派遣因弗努斯前往苦痛堡垒，监督黑铁矮人在奥达曼搜寻失落的神器。",al={"因弗努斯是谁","因弗努斯背景故事","因弗努斯大使背景"}},{q="因弗努斯大使在哪里？",a="在荒芜之地的苦痛堡垒。",al={"去哪里找因弗努斯大使","因弗努斯大使位置","因弗努斯在哪里"}},{q="为什么卡尼克想消灭因弗努斯大使？",a="黑铁矮人在奥达曼的搜索行动已经导致许多矮人丧生，卡尼克担心他们找到的神器会被用来对付铁炉堡。",al={"为什么要杀因弗努斯大使","因弗努斯在奥达曼做什么","铁炉堡荒芜之地威胁"}},{q="谁发布和完成这个任务？",a="由铁炉堡的史学家卡尼克发布，你需要将胜利的证明交给铁炉堡的顾问贝尔格拉姆。",al={"谁发布邪恶大使任务","谁交付邪恶大使任务","邪恶大使任务发布者"}},{q="需要什么样的证明？",a="因弗努斯大使的护腕，将其出示给顾问贝尔格拉姆作为你胜利的证明。",al={"我需要从因弗努斯身上获得什么","因弗努斯大使的证据","因弗努斯护腕"}}},fp="21,143,32.427.0,16.241.1,27.105.0,29.58.0,51.142.0,30.115.0,21.75.0"}
P.entries["quest:76240"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem 请你在雷霆崖将一条 Raw Brilliant Smallfish 片成鱼片。他希望这项练习能显露出你在隐秘技艺方面的天赋。",h="Boarton Shadetotem 请你在雷霆崖将一条 Raw Brilliant Smallfish 片成鱼片。他希望这项练习能显露出你在隐秘技艺方面的天赋。",kw={"boarton shadetotem","knife set","raw brilliant smallfish","stalk with the earthmother","隐秘技艺","雷霆崖"},sec={{t="最后的试炼",b="雷霆崖的 Boarton Shadetotem 请你用他的 Knife Set 展示与生俱来的本领。带一条 Raw Brilliant Smallfish 给他，并当着他的面将鱼片好。他希望这项较为间接的考验能发掘出隐藏的天赋。"},{t="临别赠言",b="Boarton Shadetotem 看出你缺少他所寻求的那种潜行者般的精准。他送上一份临别赠礼，让你继续旅程，并祝愿部落能有像你这样的英雄。"}},faq={{q="是谁要我把鱼片成鱼片？",a="雷霆崖的 Boarton Shadetotem 请你用他的 Knife Set 将一条 Raw Brilliant Smallfish 片成鱼片。",al={"boarton 是谁","boarton shadetotem","鱼刀任务"}},{q="Boarton 为什么要我把鱼片成鱼片？",a="Boarton 希望这项练习能激发你在隐秘技艺方面隐藏的天赋。",al={"为什么片鱼","boarton 在考验什么","小鱼考验"}},{q="Boarton 要什么鱼？",a="Boarton 要一条 Raw Brilliant Smallfish。",al={"哪种鱼","生的小鱼","闪亮的鱼"}},{q="我该在哪里片鱼？",a="在雷霆崖的 Boarton Shadetotem 面前，将 Raw Brilliant Smallfish 片成鱼片。",al={"片鱼任务在哪里","雷霆崖的鱼","在哪里使用 knife set"}}},fp="26,141,13.214.0,13.162.1,34.100.0,42.74.0,31.43.0,27.83.0"}
P.entries["quest:763"] = {n="大地之母仪祭",s="大地母亲的仪式标志着一名年轻的牛头人离开了隐蔽的红云台地，走向莫高雷更广阔的平原。既然已经在纳拉其营地证明了自己的实力，鹰风酋长便会让你带着一根雕刻过的图腾向北前往血蹄村，在贝恩·血蹄的指导下继续进行古老的试炼。",h="大地母亲的仪式标志着一名年轻的牛头人离开了隐蔽的红云台地，走向莫高雷更广阔的平原。既然已经在纳拉其营地证明了自己的实力，鹰风酋长便会让你带着一根雕刻过的图腾向北前往血蹄村，在贝恩·血蹄的指导下继续进行古老的试炼。",kw={"贝恩·血蹄","血蹄村","凯恩·血蹄","纳拉其营地","鹰风酋长","莫高雷","大地母亲的仪式","鹰风图腾"},ang={["faction:Horde"]="传统的仪式加强了整个莫高雷的部落团结，确保了部落的新守卫者既拥有战士的勇武，也拥有深厚的精神基础。",["race:Tauren"]="每一名年轻的牛头人都必须走过大地母亲的道路，向长老们证明自己的价值，并在团结的部落中找到属于自己的位置。"},sec={{t="离开台地",b="世世代代以来，年轻的牛头人们都在红云台地上纳拉其营地这片安全的摇篮里磨练自己的力量。完成最初的试炼证明了一个人拥有生存所需的纪律和决心，但神圣的大地母亲的仪式所要求的远不止是在当地的野生动物威胁下存活下来。鹰风酋长能够看出什么时候一名初生者已经不再适合台地庇护下的猎场，必须踏入更广阔的社群之中。"},{t="给贝恩的信物",b="为了搭建起纳拉其营地与中央聚落之间的桥梁，鹰风酋长提供了一根手工雕刻的图腾作为引荐的信物。带着这枚纹章顺着蜿蜒的小路前往血蹄村，你将会见到血蹄村的年轻酋长、大酋长凯恩·血蹄之子——贝恩·血蹄。这根图腾证明了你已经为前方更深奥的精神与智慧试炼做好了准备。"}},faq={{q="这个任务的目的是什么？",a="它作为成人礼引导你离开新手区域纳拉其营地，并指向血蹄村，让你开启牛头人仪式试炼的下一个篇章。",al={"为什么进行大地母亲的仪式","这个任务有什么作用","任务目的"}},{q="贝恩·血蹄是谁？",a="贝恩·血蹄是大酋长凯恩·血蹄的儿子。他领导着血蹄村，作为一名受人尊敬的当地酋长，负责监督年轻牛头人正在进行的精神与武力试炼。",al={"贝恩是谁","贝恩背景故事","凯恩之子"}},{q="什么是鹰风图腾？",a="这是一根由纳拉其营地的鹰风酋长手工雕刻的木质图腾。它充当了一份官方的证明和认可的印记，向贝恩·血蹄证明你已经获得了鹰风酋长的祝福，可以进行后续的仪式。",al={"鹰风图腾","雕刻图腾"}},{q="这之后还有什么仪式？",a="到达血蹄村并见到贝恩之后，你将被委派进行“幻象仪式”，通过神圣的先祖幻象来考验你的精神感应。",al={"接下来的仪式","之后要做什么","下一个任务"}},{q="血蹄村在哪里？",a="血蹄村位于纳拉其营地以北，坐落在莫高雷中央的石牛湖畔。旅行者只需沿着从台地下来的主路向北走即可。",al={"血蹄村在哪里","如何找到血蹄村","通往血蹄村的路径"}},{q="为什么要完成大地母亲的仪式？",a="大地母亲的仪式是牛头人中极度神圣的传统。通过仪式的所有阶段展现了肉体的坚韧、精神的连结与智慧，从而获得雷霆崖长老们真正的认可。",al={"为什么进行大地母亲仪式","牛头人试炼目的","大地母亲的仪式背景故事"}}},fx={["4a33bb81"]={q="鹰风酋长为什么让你去血蹄村？",a="鹰风酋长引导你完成了红云台地的入门试炼，但纳拉其营地已无法再教给你更多。要完成神圣的大地母亲仪式，并获得雷霆崖长老们的认可，你必须在莫高雷更广阔的平原上积累阅历。鹰风酋长让你带着他雕刻的图腾去见贝恩·血蹄，将你身心成长的责任托付给一位能够考验你是否已准备好真正成年的领袖。",al={"为什么派我去血蹄村","鹰风酋长的目的","为什么要进行大地母亲仪式"}},["9c980781"]={q="为什么必须由你亲自送去图腾？",a="这段旅程并非简单的跑腿差事，而是你成年礼中不可或缺的一部分。走出红云台地的庇护，沿着旷野大道前往莫高雷，能证明你的独立和毅力。亲手送上鹰风图腾，贝恩·血蹄便能亲自见到你，看到木头上刻着鹰风酋长的亲笔嘉许，并当面判断你的品格。",al={"为什么要我带图腾","鹰风酋长为什么不派信使","为什么让我进行大地母亲仪式"}}},fp="24,202,16.337.0,17.388.0,34.120.0,23.170.0,30.223.0,27.128.0,35.156.0,44.193.0"}
P.entries["quest:764"] = {n="风险投资公司",s="在莫高雷调查一辆被破坏的荆棘谷地精货车时，发现大量荆棘谷地精正在东部山丘进行挖掘活动。在采矿许可申请遭到断然拒绝后，该公司仍执意开采大地母亲的土壤，促使摩林·云行者下令采取致命的回击。",h="在莫高雷调查一辆被破坏的荆棘谷地精货车时，发现大量荆棘谷地精正在东部山丘进行挖掘活动。在采矿许可申请遭到断然拒绝后，该公司仍执意开采大地母亲的土壤，促使摩林·云行者下令采取致命的回击。",kw={"地精","采矿权","摩林·云行者","莫高雷","被破坏的货车","荆棘谷地精","荆棘谷地精矿场"},ang={["faction:Horde"]="在抵御商业开发中保卫莫高雷，巩固了你保护凯恩·血蹄子民的决心，他们正努力在这片新家园中扎根。",["profession:Mining"]="荆棘谷地精纯粹通过野蛮开采进行作业，他们偷工减料，破坏土地，丝毫不顾及自然平衡或采矿安全。",["race:Tauren"]="对牛头人而言，大地母亲是神圣的。荆棘谷地精的露天采矿不仅是越界行为，更是对他们祖传家园的暴力亵渎，必须立即将其强行驱逐。"},sec={{t="工业入侵",b="莫高雷的牛头人将这片土地视为大地母亲的延伸，珍视这里原始的平原与和谐的野生动物。当荆棘谷地精为了获取原矿，前来寻求在这片连绵起伏的山丘上进行爆破和挖掘的权利时，他们的请求被断然拒绝。这些贪婪的卡特尔不顾部落法令或领土主权，将重型机械、劳工和监工直接偷运进莫高雷的东部山脊，进行非法开采。"},{t="明确的讯息",b="像摩林·云行者这样的牛头人斥候意识到，一旦镐头敲击在石头上，就无法再通过外交呼吁来化解企业的贪婪。从一辆被破坏的荆棘谷地精货车中找到的文件证实了该公司的采矿作业，摩林派遣部落勇士去消灭那些挥舞鞭子的监工和操作钻机的劳工。这场血腥的报复旨在让荆棘谷地精明白，擅自闯入的代价是极其高昂的。"}},faq={{q="为什么荆棘谷地精会出现在莫高雷？",a="荆棘谷地精在莫高雷东部山丘沿线建立了非法的哨所和矿场，以开采矿石和自然资源。在牛头人正式拒绝授予其官方采矿权后，该卡特尔无视部落权威，执意开展了作业。",al={"为什么地精会在莫高雷","荆棘谷地精在莫高雷的目的","荆棘谷地精想要什么"}},{q="是谁下令攻击矿工的？",a="摩林·云行者，一位在血蹄村附近守卫的牛头人，下达了命令。他认为该卡特尔无视部落拒绝的做法是一种直接的侵犯，需要用武力而非进一步的谈话来解决。",al={"谁发布了这个任务","摩林·云行者的角色","任务发布者"}},{q="荆棘谷地精的矿场位于何处？",a="荆棘谷地精主矿场位于被破坏的货车和血蹄村以东的山麓地带。在雷霆崖北侧升降梯东北方的悬崖边，也能发现一处规模较小的卡特尔人员据点。",al={"荆棘谷地精矿场位置","监工在哪里","在哪里可以找到荆棘谷地精"}},{q="牛头人是否尝试过与这些地精谈判？",a="是的。荆棘谷地精曾向牛头人申请莫高雷的正式采矿权。部落首领拒绝让他们开采这片祖传土地，但地精们还是选择在未获许可的情况下进行挖掘。",al={"牛头人是否允许采矿","莫高雷采矿权","地精是否请求过许可"}},{q="这些地精属于热砂港吗？",a="不属于。荆棘谷地精是一个独立且臭名昭著的掠夺性工业卡特尔，与热砂港这样的中立贸易组织不同。无论在哪里开发资源，他们都与当地居民保持敌对关系。",al={"这些是棘齿城地精吗","荆棘谷地精友好吗","荆棘谷地精阵营"}},{q="这与被破坏的货车有什么关联？",a="那辆被破坏的货车是荆棘谷地精的车队，被牛头人摧毁了。从残骸中回收的采矿部门板条箱和文件揭露了该公司在莫高雷的行动，从而引发了这次对他们矿场的打击。",al={"货车关联","荆棘谷地精袭击过货车吗","被破坏的货车的关联"}}},fx={f6df914e={q="摩林·云行者为什么想要攻击荆棘谷地精？",a="荆棘谷地精公司在莫高雷的采矿权申请遭到正式拒绝，却无视拒绝，仍然开始筹备设备和招募工人。摩林·云行者不能容忍他们肆意破坏土地、掠夺自然资源。外交斡旋和断然拒绝都未能打消他们的贪欲，因此他认为牛头人必须以明确而强硬的方式警告他们：不会容忍擅闯和盗窃。",al={"摩林·云行者的目的","为什么攻击荆棘谷地精公司","摩林为什么要杀荆棘谷地精公司的人"}},eda5096c={q="你要去矿场对付谁？",a="你要对付的是驻扎在莫高雷东部采矿作业点的荆棘谷地精公司监工和工人。这些地精和受雇劳工未经部族许可，便在神圣的山丘上深挖，掠取矿物；而唯利是图的工头则推动公司咄咄逼人且非法的扩张。",al={"荆棘谷地精公司的任务目标","荆棘谷地精公司的工人是谁","我在矿场要打谁"}}},fp="15,191,20.326.0,23.321.0,38.172.0,40.172.0,42.216.0,54.193.0,50.216.0,46.195.0"}
P.entries["quest:765"] = {n="菲兹普罗克主管",s="监工费兹斯普罗克特是驻扎在莫高雷矿洞内的一名荆棘谷地精高层主管。摩林·云行者指派部落冒险者潜入矿洞，终结该地精组织的蓄意掠夺，并除掉他，取回他那份详细的剪贴板。",h="监工费兹斯普罗克特是驻扎在莫高雷矿洞内的一名荆棘谷地精高层主管。摩林·云行者指派部落冒险者潜入矿洞，终结该地精组织的蓄意掠夺，并除掉他，取回他那份详细的剪贴板。",kw={"剪贴板","费兹斯普罗克特","矿洞","摩林·云行者","莫高雷","监工","荆棘谷地精"},ang={["faction:Horde"]="协助牛头人对抗入侵的企业掠夺者，巩固了部落对卡利姆多新宣称的核心领土的保护。",["race:Tauren"]="荆棘谷地精企图驱逐你们的部族并掠夺这片圣土的公开阴谋，使得击杀费兹斯普罗克特成为一项至关重要的领土保卫行动。"},sec={{t="针对平原的阴谋",b="从一辆被破坏的荆棘谷地精货车中寻获的文件揭示，荆棘谷地精不仅仅是在挖掘矿石，他们还在精心策划将牛头人彻底赶出莫高雷。通过驱逐当地居民，这家贪婪的企业试图获得不受限制的自由，去掠夺连绵起伏的丘陵和深层矿脉中的一切自然资源。"},{t="痛击监工",b="摩林·云行者对针对其族人策划的企业暴行感到愤怒，他指挥勇士们进入位于被破坏的货车东侧的荆棘谷地精矿洞。监工费兹斯普罗克特在右侧矿洞深处管理着运作，周围环绕着劳工和下属头目。击杀费兹斯普罗克特并夺取他的剪贴板将瓦解当地的协调能力，并获得有关该组织未来计划的关键情报。"}},faq={{q="监工费兹斯普罗克特是谁？",a="监工费兹斯普罗克特是一名荆棘谷地精头目，负责莫高雷东部矿洞内的运作。他监管着挖掘大地的劳工，并执行旨在扩大该地区业务的企业策略。",al={"费兹斯普罗克特","谁是费兹斯普罗克特","费兹斯普罗克特背景故事"}},{q="为什么摩林·云行者想要费兹斯普罗克特死？",a="摩林在一辆被突袭的货车上发现了文件，证明荆棘谷地精密谋为了利益将牛头人赶出他们的祖居地。费兹斯普罗克特正是执行这些精心策划的剥削阴谋的直接负责人。",al={"为什么要击杀费兹斯普罗克特","摩林·云行者的动机"}},{q="监工费兹斯普罗克特在哪里？",a="他位于莫高雷被破坏的货车正东方的荆棘谷地精矿洞内。进入矿洞后，沿着最右侧的隧道走到一个房间，他就在那里，周围环绕着工人和监工。",al={"费兹斯普罗克特在哪里","费兹斯普罗克特矿洞位置","费兹斯普罗克特地图"}},{q="摩林需要什么证据来证明费兹斯普罗克特已被击败？",a="摩林·云行者需要费兹斯普罗克特的个人剪贴板，其中包含的账目和记录可能揭示荆棘谷地精在莫高雷的进一步企图。",al={"击杀证明","费兹斯普罗克特的剪贴板"}},{q="为什么荆棘谷地精会在莫高雷？",a="荆棘谷地精是一个肆无忌惮的商业卡特尔，一心想要剥削原始领土上的木材、矿产和宝贵的地下财富，完全无视原住民或环境平衡。",al={"莫高雷的荆棘谷地精","为什么地精在莫高雷"}},{q="击杀费兹斯普罗克特能将荆棘谷地精彻底赶走吗？",a="不能。虽然费兹斯普罗克特的死亡破坏了他们的当地领导层，并为摩林·云行者提供了有关他们计划的重要笔记，但荆棘谷地精仍然是盘踞在莫高雷丘陵中的持续威胁。",al={"荆棘谷地精离开了吗","费兹斯普罗克特死后"}}},fp="22,216,25.239.0,21.285.1,30.187.0,50.189.0,40.158.0,54.129.0,38.156.0,67.165.0"}
P.entries["quest:766"] = {n="马兹拉纳其",s="位于血蹄村的茂尔·祈雨遭到了玛兹拉纳切的毒咬，这只传奇的平原陆行鸟曾在一代人之前恐吓过他的祖父。在发烧和谵妄梦魇的折磨下，这位牛头人急需一种用莫高雷的野生生物制成的强效药剂，以保住性命。",h="位于血蹄村的茂尔·祈雨遭到了玛兹拉纳切的毒咬，这只传奇的平原陆行鸟曾在一代人之前恐吓过他的祖父。在发烧和谵妄梦魇的折磨下，这位牛头人急需一种用莫高雷的野生生物制成的强效药剂，以保住性命。",kw={"血蹄村","平原狮","茂尔·祈雨","玛兹拉纳切","莫高雷","平原陆行鸟","草原狼","猛鹫"},ang={["class:Hunter"]="在莫高雷各地追踪草原狼、平原狮、平原陆行鸟和猛鹫，是学习解读平原环境和了解大草原独特野生生物的一门实践课。",["faction:Horde"]="保护血蹄村免受莫高雷严酷危险的侵袭，对于在牛头人家园建立和平与稳定至关重要。",["race:Tauren"]="茂尔制作的药剂反映了牛头人直接从大地母亲的植物与动物身上获取疗法的古老习俗。"},sec={{t="平原的传说",b="多年来，茂尔·祈雨一直认为玛兹拉纳切不过是祖父口中令人毛骨悚然的家族传说。这位年长的牛头人曾提到过一只不同寻常的凶猛平原陆行鸟，它长着发红光的眼睛和锋利的爪子，毒咬的习性也与大多数莫高雷的野生生物那种温顺的本性背道而驰。当茂尔在开阔的草原上与这头野兽狭路相逢时，传说被证实是真实存在的，他身受重伤，挣扎着才逃回安全地带。"},{t="与感染赛跑",b="这种生物的毒液发作极快，会导致高烧和谵妄的梦魇。为了在毒液致命前将其清除，传统的牛头人医药依赖于当地野兽的生命力。茂尔需要草原狼的心脏、平原狮的腿骨、平原陆行鸟的鳞片和猛鹫的胃。通过结合这些各异的猎食者与食腐动物的精华，他可以调制出一种能够阻止毒素蔓延并助他恢复健康的药剂。"}},faq={{q="玛兹拉纳切是什么？",a="玛兹拉纳切是一只游荡在莫高雷草原上的臭名昭著的平原陆行鸟。与普通的陆行鸟不同，它以鲜艳的羽毛、恶魔般的红眼、凶猛的利爪以及不同寻常的剧毒咬击而闻名。它已经恐吓了数代旅行者。",al={"玛兹拉纳切是谁","玛兹拉纳切是什么野兽","玛兹拉纳切背景故事"}},{q="茂尔·祈雨是谁？",a="茂尔·祈雨是一位居住在血蹄村的牛头人。在穿越莫高雷时，他遭到玛兹拉纳切的伏击并被咬伤肩膀，导致他卧床不起，深受致命的毒性感染威胁。",al={"茂尔·祈雨","任务发布者是谁","生病的牛头人是谁"}},{q="为什么茂尔需要四种不同野兽的身体部位？",a="传统的牛头人药方利用平原动物的自然力量和精神精华来中和强效毒素。狼的心脏、平原狮腿骨中浓缩的骨髓、平原陆行鸟的鳞片以及猛鹫的胃，这些组合在一起形成了解毒剂，足以抵御玛兹拉纳切的毒液。",al={"为什么需要狼心和狮腿骨","为什么需要动物材料","玛兹拉纳切药剂配方"}},{q="茂尔的祖父杀死了玛兹拉纳切吗？",a="没有。茂尔的祖父曾与这只凶猛的平原陆行鸟战斗，但未能将其击败，他幸存下来后，便将关于它鲜艳色彩和凶狠攻击的警示传给了后代。",al={"祖父击败过玛兹拉纳切吗","茂尔的祖父与玛兹拉纳切","谁曾与玛兹拉纳切战斗"}},{q="这个任务要求我亲自去猎杀玛兹拉纳切吗？",a="不。茂尔当前的头等大事是挺过高烧。任务的重点完全在于收集制作解药所需的材料，而不是去猎杀这只传奇的鸟兽。",al={"我需要杀死玛兹拉纳切吗","玛兹拉纳切在哪里","猎杀玛兹拉纳切"}},{q="血蹄村位于何处？",a="血蹄村位于莫高雷中部，雷霆崖以南，石牛湖正东。它是年轻的牛头人勇士前往广阔平原历练的主要定居点。",al={"血蹄村在哪里","血蹄村位置"}}},fx={["3b88d77e"]={q="茂尔·祈雨为什么要你做这件事？",a="茂尔的性命危在旦夕。他在莫高雷平原旅行时遇上了马兹拉纳其，一头传说中的陆行鸟，曾以凶残著称，令他的祖父饱受惊吓。那头野兽狠狠咬伤了茂尔的肩膀，毒液也侵入了伤口。他开始发起令人虚弱的高烧，噩梦连连、神志昏乱，病情还在体内不断蔓延。若没有用于调制药方的动物材料，凶猛的感染很快就会夺走他的性命。",al={"茂尔·祈雨的目的","为什么要帮茂尔·祈雨","茂尔出了什么事"}},ce37bf7e={q="茂尔为什么要找外人帮忙，而不是自己治伤？",a="茂尔伤势严重，又发着高烧，已无法亲自在莫高雷狩猎。马兹拉纳其的毒牙让他神志昏乱、精疲力竭，只能留在血蹄村。感染致命之前所剩时间不多，他只能依靠路过的旅人，去追踪迅捷的山狮、风鹏、狼和陆行鸟，为他找齐药方所需的材料。",al={"茂尔为什么不能自己找材料","茂尔为什么需要你","为什么让我对付马兹拉纳其"}}},fp="11,227,22.365.0,20.389.0,20.179.0,23.169.0,52.247.0,40.178.0,55.95.0,35.174.0"}
P.entries["quest:767"] = {n="幻象仪祭",s="幻象仪式是大地之母仪式中至关重要的成人礼，旨在考验年轻冒险者的精神成熟度。这项任务由贝恩·血蹄发起，指引寻求者前往血蹄村，从预言者扎尔曼·双月那里寻求指引。对于任何想要获得雷霆崖高地上长者们祝福与尊重的人来说，这段旅程都是必不可少的。",h="幻象仪式是大地之母仪式中至关重要的成人礼，旨在考验年轻冒险者的精神成熟度。这项任务由贝恩·血蹄发起，指引寻求者前往血蹄村，从预言者扎尔曼·双月那里寻求指引。对于任何想要获得雷霆崖高地上长者们祝福与尊重的人来说，这段旅程都...",kw={"贝恩·血蹄","血蹄村","莫高雷","幻象仪式","大地之母仪式","牛头人试炼","雷霆崖","扎尔曼·双月"},ang={["class:Druid"]="与大地之母的幻象直接沟通，进一步加强了德鲁伊倾听生活世界智慧与低语的使命。",["class:Shaman"]="寻找扎尔曼·双月并走上幻象之路，与萨满在平衡世俗事务与祖先意志方面的职责产生了深刻的共鸣。",["faction:Horde"]="进行这些传统的圣礼，证明了你对帮助指引部落的牛头人长者们的忠诚与文化敬意。",["race:Tauren"]="幻象仪式是每一位年轻牛头人不可或缺的文化里程碑，标志着你正式转变为部族中受人信赖的捍卫者和灵魂行者。"},sec={{t="神圣的基石",b="世世代代以来，游牧的牛头人一直追随大地之母，在卡利姆多的平原上指引着族人。如今，他们聚集在莫高雷的安全边界内，其精神传统依然是他们社会的基石。幻象仪式是被称为“大地之母仪式”的古老试炼之一。早期的试炼旨在考验入门者的身体力量和与狩猎的联系，而幻象仪式则要求进行内心的探索，指引年轻的牛头人以及受人尊敬的盟友直接与灵魂沟通。"},{t="预言者的指引",b="在寻求任何精神幻象之前，入门者必须先由一位深谙古老智慧的人进行准备。在血蹄村，这一职责落在了受人尊敬的萨满扎尔曼·双月身上。受贝恩·血蹄之托为旅行者提供指导，扎尔曼拥有敏锐的洞察力，能够识别出那些走在祖先道路上的人，并提供穿透物质世界面纱所需的初步仪式和神圣准备。"}},faq={{q="什么是幻象仪式？",a="幻象仪式是大地之母仪式中的一项神圣仪式。它旨在拓宽冒险者的精神视野，使他们能够与祖先之灵沟通，并向雷霆崖的长者们证明自己的精神准备。",al={"幻象仪式任务","什么是幻象仪式","幻象仪式背景故事"}},{q="谁发布了这个任务？",a="该任务由大酋长凯恩·血蹄之子贝恩·血蹄发布。贝恩守护着血蹄村，并将值得信赖的旅行者引向村中的精神长者。",al={"谁发布幻象仪式","幻象仪式任务发布者"}},{q="扎尔曼·双月是谁？",a="扎尔曼·双月是一位经验丰富的牛头人萨满，也是血蹄村的精神领袖。他负责为寻求进行幻象仪式等神圣试炼的旅行者和入门者提供准备。",al={"扎尔曼是谁","扎尔曼·双月背景故事"}},{q="为什么大地之母仪式对牛头人很重要？",a="大地之母仪式代表了牛头人成人礼的传统仪式。成功完成这些仪式证明了一个人的身体能力、精神调和以及对大地的持久尊重，从而赢得高位长者的荣耀。",al={"大地之母仪式的意义","为什么要进行大地之母仪式"}},{q="非牛头人可以进行幻象仪式吗？",a="可以。途经莫高雷并赢得血蹄部族信任的部落盟友，被允许走上大地之母的道路，以对牛头人传统的尊重换取长者们的青睐。",al={"兽人可以进行幻象仪式吗","非牛头人大地之母"}},{q="这个试炼在哪里进行？",a="试炼始于血蹄村，这是一个位于莫高雷中部、雷霆崖南面、石牛湖畔的著名牛头人定居点。",al={"幻象仪式在哪里","幻象仪式地点"}}},fx={["1fa313da"]={q="贝恩·血蹄为什么要你进行先知之水仪式？",a="贝恩·血蹄正在引导你踏上先祖之路，向牛头人证明自己的价值。你在莫高雷成年后，必须履行神圣的大地母亲仪式，与灵魂交流，学会敬重土地，最终赢得雷霆崖长老的尊重。贝恩指引你去找村中的秘术师扎尔曼·双月，让你正式开始这场灵性试炼。",al={"贝恩为什么派你进行先知之水仪式","贝恩·血蹄让你进行先知之水仪式的目的","为什么要进行先知之水仪式"}}},fp="14,235,23.398.0,19.348.0,27.208.0,22.192.0,25.171.0,61.213.0,44.187.0,33.132.0"}
P.entries["quest:768"] = {n="收集皮革",s="“收集皮革”是维尔伦·陆行者在雷霆崖的高地上发布的一项简单的贸易请求。为了维持首都的运转并考验年轻的猎人，维尔伦用手工制品交换一批鞣制过的轻皮。这凸显了牛头人将平原狩猎的成果转化为必需的衣物和护甲这一根深蒂固的传统。",h="“收集皮革”是维尔伦·陆行者在雷霆崖的高地上发布的一项简单的贸易请求。为了维持首都的运转并考验年轻的猎人，维尔伦用手工制品交换一批鞣制过的轻皮。这凸显了牛头人将平原狩猎的成果转化为必需的衣物和护甲这一根深蒂固的传统。",kw={"收集皮革","制皮","轻皮","莫高雷","牛头人狩猎","雷霆崖","维尔伦·陆行者"},ang={["class:Hunter"]="前往莫高雷平原冒险的猎人自然擅长追踪猎物并采集维尔伦所需的轻皮。",["faction:Horde"]="为雷霆崖的工匠提供原材料可以加强这座年轻的首都，巩固其防御和贸易网络。",["race:Tauren"]="对于牛头人猎人来说，通过将倒下的野兽的皮毛转化为有用的商品来纪念它们，是一项代代相传的重要文化准则。"},sec={{t="维持雷霆崖的运转",b="在莫高雷高耸的平顶山上新建立的首都里，手工艺与生存息息相关。维尔伦·陆行者将兽皮加工成雷霆崖日益增长的人口所需的衣物和防护护甲。他没有亲自去采集所有材料，而是鼓励前往平原的年轻冒险者带回他们的猎物，将平凡的狩猎转化为光荣的公民服务。"},{t="狩猎之道",b="对于牛头人来说，在草原上猎杀野兽并非体育运动，而是一种能够让部落有饭吃、有衣穿、有住所的崇高事业。维尔伦·陆行者寻找渴望为氏族带来荣誉的猎人，专门要求从当地野生动物身上剥取轻皮。作为十二张保存完好的兽皮的回报，他会用结实的商品酬谢猎人，加强了将牛头人社会凝聚在一起的相互支持。"}},faq={{q="谁是维尔伦·陆行者？",a="维尔伦·陆行者是一位居住在雷霆崖的制皮师。他为牛头人人民制作衣物和防护护甲，并将成品与从平原带回新鲜兽皮的猎人进行交易。",al={"维尔伦·陆行者","谁发布收集皮革任务","雷霆崖皮革任务发布者"}},{q="维尔伦·陆行者需要什么？",a="维尔伦需要十二张轻皮，这些轻皮是从游荡在莫高雷及周边地区的野兽身上获取的，用于为雷霆崖制作商品。",al={"收集皮革任务要求","给维尔伦带什么","收集皮革所需材料"}},{q="这个任务在哪里进行？",a="该任务在雷霆崖顶的维尔伦·陆行者处开始和结束，尽管完成它需要在大草原上的野兽身上狩猎。",al={"维尔伦·陆行者在哪里","收集皮革任务地点"}},{q="为什么牛头人如此重视狩猎野兽？",a="牛头人文化将狩猎视为与大地母亲之间的一种神圣平衡。倒下的野兽的每一个部分都会被利用：肉用来喂养部落，骨头和鞣制过的兽皮则被加工成工具、帐篷和耐用的护甲。",al={"牛头人狩猎文化","为什么要狩猎获取皮革","牛头人制皮背景故事"}},{q="任何部落冒险者都可以承担这项任务吗？",a="是的，任何效忠于部落且被维尔伦认为渴望在平原上考验自己勇气的旅行者，都可以协助他收集皮革。",al={"谁可以做收集皮革任务","收集皮革任务是否仅限部落"}},{q="皮革交付后会发生什么？",a="维尔伦会检查兽皮的质量，称赞猎人的工作，并以公平交易的方式提供一件制造的装备。",al={"收集皮革任务交付","维尔伦·陆行者奖励"}}},fx={["1249c214"]={q="维尔伦·陆行者为什么要轻皮？",a="维尔伦·陆行者是一名制皮师，为雷霆崖的居民制作衣物和护甲。为了供给城市所需并维持自己的手艺，他依靠猎人从莫高雷平原带回优质兽皮。",al={"维尔伦为什么需要皮革","维尔伦·陆行者的目的","为什么给维尔伦轻皮"}},cd30155e={q="轻皮有什么用？",a="这些皮革会被制成必需的衣物、防护护甲和实用物品，供居住在雷霆崖高台地上的牛头人使用，也会被制成装备，作为交换交给旅行中的猎人。",al={"轻皮有什么用","轻皮的用途","维尔伦如何使用轻皮"}}},fp="17,203,24.268.0,19.288.0,25.146.0,33.146.0,33.116.0,61.180.0,45.129.0,43.133.0"}
P.entries["quest:769"] = {n="科多兽皮包",s="科多兽皮包是一个由维尔伦·陆行者提供的贸易任务。维尔伦·陆行者是一位技艺精湛的牛头人制皮匠，常驻雷霆崖的高地之上。为了换取基础的制作材料，他会传授一种传统的平原技艺，用结实的兽皮缝制耐用的旅行包。这对莫高雷的制皮学徒来说，是一次早期的试炼。",h="科多兽皮包是一个由维尔伦·陆行者提供的贸易任务。维尔伦·陆行者是一位技艺精湛的牛头人制皮匠，常驻雷霆崖的高地之上。为了换取基础的制作材料，他会传授一种传统的平原技艺，用结实的兽皮缝制耐用的旅行包。这对莫高雷的制皮学徒来说...",kw={"粗线","科多兽","科多兽皮包","制皮","轻皮","莫高雷","雷霆崖","维尔伦·陆行者"},ang={["faction:Horde"]="雷霆崖的工匠提供重要的后勤物资，使部落的猎人、斥候和战士能够在卡利姆多中部保持装备精良。",["race:Tauren"]="对于舒哈鲁人来说，学习如何用强大的科多兽皮制作可靠的装备，是纪念地母的馈赠和传承祖先方式的重要一步。"},sec={{t="高地上的课程",b="维尔伦·陆行者在雷霆崖的工匠高地上，秉持着狩猎不浪费的悠久游牧传统。想要获得他的指点，有志向的制皮匠必须向他进贡经过处理的轻皮和粗线。通过展示对基础材料的掌握能力，学徒们证明自己已经准备好制造能够携带补给物资穿越卡利姆多崎岖荒野的装备了。"},{t="科多兽之魂",b="对牛头人而言，科多兽是耐力、力量和坚定信念的象征。它们厚实的皮毛可以抵御荆棘、刺骨寒风以及野兽的利爪。用科多兽皮制作背包和服饰不仅是一种实用主义的行为，更是对这种哺育了舒哈鲁族并载着他们在莫高雷平原上繁衍生息无数代生灵的崇敬。"}},faq={{q="谁提供科多兽皮包任务？",a="该任务由维尔伦·陆行者提供，他是一位位于雷霆崖的牛头人制皮训练师兼商人。",al={"任务发布者","科多兽皮包任务在哪里接","维尔伦·陆行者位置"}},{q="谁有资格承接此任务？",a="只有至少达到初级制皮技能等级10级的冒险者，才能从维尔伦·陆行者那里接到这个培训任务。",al={"谁可以接此任务","任务要求","专业技能要求"}},{q="维尔伦·陆行者需要什么材料？",a="他需要四块轻皮和四卷粗线来补充贸易物资，然后才会分享他的配方。",al={"需要什么物品","科多兽皮包材料","任务上交物品"}},{q="为什么科多兽皮对牛头人匠人很重要？",a="科多兽体现了韧性和力量，这些品质深受牛头人珍视。用它们的皮制作耐用的装备既是对生物灵魂的致敬，也为横跨平原的旅者提供了结实的用具。",al={"为什么用科多兽皮","牛头人科多兽的意义","科多兽的重要性"}},{q="完成任务后维尔伦·陆行者会教授什么？",a="在收到物资后，维尔伦会教授制皮匠缝制科多兽皮包所需的专门知识。",al={"任务奖励","我能得到什么","背包配方"}},{q="在哪里可以获得必要的材料？",a="轻皮可以通过剥皮莫高雷及周边领地的低等级野兽获得，而粗线可以直接从贸易供应商和裁缝商人处购买。",al={"轻皮哪里获得","粗线哪里获得"}}},fx={c94273ea={q="维尔伦·陆行者为什么要你做这件事？",a="维尔伦·陆行者以培养新一代牛头人制皮师为荣。莫高雷的科多兽因力量和耐力而备受敬重，用它们的皮制作传统背包是基础技艺。维尔伦让你为他的手艺收集材料，以此考验你的投入和应变能力，然后才会传授这门手艺的技巧。",al={"维尔伦·陆行者为什么要皮革","维尔伦·陆行者的目的","为什么要做科多兽皮袋任务"}},["1f62e959"]={q="轻皮有什么用？",a="轻皮是维尔伦·陆行者用来换取指导的基础材料。鞣制兽皮是牛头人制皮技艺的核心。提供优质皮革，能证明你已掌握处理兽皮的基本功，之后才能学习缝制科多兽皮袋等专用容器。",al={"轻皮有什么用途","为什么要带轻皮","轻皮的作用"}},["7d0f7d7f"]={q="粗线有什么用？",a="粗线是裁缝和制皮工艺中不可或缺的材料，用来缝合厚重的兽皮。要制作能经受莫高雷平原考验的耐用背包，工匠需要结实的绳线，确保它不会在重压或恶劣天气下断裂。",al={"为什么要粗线","粗线的作用","粗线有什么用"}}},fp="13,149,20.327.0,18.307.0,35.102.0,39.105.0,46.150.0,59.171.0,50.82.0,46.132.0"}
P.entries["quest:77"] = {n="收集蜜糖",s="基沃拉丁·猎日者拥有德兰·德罗弗斯想要的辛特兰蜜糖的原包装，并愿意在收取两瓶额外报酬的情况下帮忙打包。这些瓶子就散落在隐匿石附近废弃部落营地的板条箱里。",h="基沃拉丁·猎日者拥有德兰·德罗弗斯想要的辛特兰蜜糖的原包装，并愿意在收取两瓶额外报酬的情况下帮忙打包。这些瓶子就散落在隐匿石附近废弃部落营地的板条箱里。",kw={"德兰·德罗弗斯","基沃拉丁·猎日者","辛特兰","辛特兰蜜糖","软泥怪","隐匿石","淤泥怪"},sec={{t="包装问题",b="德兰·德罗弗斯在寻找这种酒，而基沃拉丁·猎日者拥有它的原包装。帮忙可不是免费的：基沃拉丁想要两瓶额外的酒作为辛苦费。你需要收集十瓶辛特兰蜜糖并带回营地。"},{t="隐匿石废墟",b="板条箱就放在隐匿石附近废弃的部落营地周围。肮脏的软泥怪和淤泥怪盘踞在废墟中，据传那里还有某种软泥怪首领在统领它们。"}},faq={{q="谁想要包装辛特兰蜜糖？",a="德兰·德罗弗斯是那个寻找酒的人，而基沃拉丁·猎日者拥有原包装，这是为了马尔顿的父亲准备的。",al={"谁需要这种酒","德兰·德罗弗斯的酒","包装是给谁的"}},{q="基沃拉丁打包收费多少？",a="基沃拉丁要求额外两瓶这种酒作为费用。你需要从板条箱中找回十瓶酒。",al={"为什么要10瓶","基沃拉丁的费用","为什么需要这么多酒"}},{q="辛特兰蜜糖的板条箱存放在哪里？",a="它们被存放在辛特兰隐匿石附近废弃部落营地的板条箱里。",al={"酒的位置","辛特兰蜜糖在哪里","隐匿石的板条箱"}},{q="隐匿石的废弃营地里有什么？",a="肮脏的软泥怪和淤泥怪盘踞在废墟中，据传有一只软泥怪首领在统领它们。",al={"隐匿石的怪物","隐匿石有什么","隐匿石的软泥怪"}}},fp="18,208,21.209.0,19.176.0,48.121.0,46.94.0,54.82.0,44.82.0"}
P.entries["quest:770"] = {n="恶魔之伤",s="恶魔之伤是一张从传说中的白狼鬼嚎身上获取的褴褛毛皮，它徘徊在莫高雷的草地上。这张毛皮上留下了过去与燃烧军团冲突时造成的永久性伤痕，是这只野兽从折磨中解脱的证明。将它带给血蹄村的长老，可以为一个悲剧性的当地传说画上句号。",h="恶魔之伤是一张从传说中的白狼鬼嚎身上获取的褴褛毛皮，它徘徊在莫高雷的草地上。这张毛皮上留下了过去与燃烧军团冲突时造成的永久性伤痕，是这只野兽从折磨中解脱的证明。将它带给血蹄村的长老，可以为一个悲剧性的当地传说画上句号。",kw={"燃烧军团","恶魔之伤","鬼嚎","莫高雷","斯考恩·白云","白狼"},ang={["class:Druid"]="德鲁伊将这张留有恶魔伤痕的毛皮视为一种严峻的提醒，提醒人们这片土地及其野生居民仍然承受着卡利姆多恶魔入侵留下的未愈伤口。",["class:Hunter"]="追踪像鬼嚎这样孤独、伤痕累累的头狼是一项必要的成年礼，可以获得斯考恩·白云长老的高度赞扬和一位大师级猎人的馈赠。",["race:Tauren"]="对于舒哈鲁人来说，狩猎鬼嚎并非残忍或征服的行为，而是一种庄严的仪式，旨在让受折磨的生物从燃烧军团挥之不去的污秽中解脱，获得安宁。"},sec={{t="邪能创伤的遗物",b="鬼嚎是一只难以捉摸的白狼，因其凶猛和悲伤的嚎叫而在莫高雷闻名。当这只野兽被杀后，会留下一张因邪恶的恶魔腐蚀而伤痕累累的毛皮。这些挥之不去的印记可以追溯到这只狼与燃烧军团的入侵恶魔进行的殊死搏斗，这场对峙使鬼嚎在第三次大战结束后很久，肉体和精神上都留下了创伤。"},{t="让受折磨的灵魂安息",b="莫高雷的牛头人对他们家园的野生动物保持着深深的敬意，尊崇它们为大地母亲的孩子。将恶魔之伤交给血蹄村的斯考恩·白云，证实了这只饱受折磨的掠食者的死亡。斯考恩认可追踪并击败鬼嚎所需的精湛技巧，并表达了沉重的希望，愿这只狼受尽折磨的灵魂在死后终于能获得安宁。"}},faq={{q="什么是恶魔之伤？",a="这是从莫高雷的传说白狼鬼嚎身上获取的褴褛兽皮。这张毛皮上清晰地留下了过去与燃烧军团战斗中邪能留下的伤痕。",al={"什么是恶魔之伤","恶魔之伤物品","鬼嚎毛皮"}},{q="披风上的恶魔伤痕是从哪里来的？",a="鬼嚎的伤痕是在第三次大战期间，当恶魔入侵者横扫卡利姆多时，与燃烧军团的冲突中留下的。",al={"为什么鬼嚎有伤痕","鬼嚎是如何受伤的","鬼嚎和军团"}},{q="我应该把披风带给谁？",a="把披风带给斯考恩·白云，他是一位居住在莫高雷血蹄村的牛头人老猎人。",al={"在哪里交恶魔之伤","谁需要恶魔之伤","斯考恩·白云交任务"}},{q="为什么斯考恩·白云会关心鬼嚎？",a="斯考恩·白云是一位退休的猎人，他认为鬼嚎是一只因恶魔腐蚀而深受折磨的可怕野兽。他尊重击败这样一只生物所需的技巧，并希望它的灵魂最终能安息。",al={"斯考恩·白云背景故事","为什么斯考恩想要鬼嚎"}},{q="在哪里可以找到鬼嚎？",a="鬼嚎是一只稀有的白狼，它徘徊在莫高雷的草海平原，通常出现在红云台地和雷霆崖之间的北部或中部开阔地带。",al={"哪里找到鬼嚎","鬼嚎位置","鬼嚎刷新"}},{q="为什么牛头人希望这只狼的灵魂能获得安宁？",a="牛头人文化强调与自然的和谐以及对野生灵魂的敬畏。由于恶魔的腐蚀给鬼嚎的一生带来了无尽的折磨，击败它被视为一种回归大地母亲的仁慈解脱。",al={"牛头人对鬼嚎的信仰","鬼嚎灵魂"}}},fp="23,231,21.317.0,27.329.0,32.166.0,49.129.0,28.102.0,48.185.0,26.131.0,53.181.0"}
P.entries["quest:7701"] = {n="悬赏：工头玛托留斯",s="一张悬赏令宣称，监工马托留斯，一名叛逃的瑟银兄弟会特工，同时也是大熔炉黑铁熔渣之池挖掘队新雇佣的指挥官，必须死。奉监工油拳之命，必须将其头颅带回给侦查队长洛洛尔，作为他已死亡的证明。",h="一张悬赏令宣称，监工马托留斯，一名叛逃的瑟银兄弟会特工，同时也是大熔炉黑铁熔渣之池挖掘队新雇佣的指挥官，必须死。奉监工油拳之命，必须将其头颅带回给侦查队长洛洛尔，作为他已死亡的证明。",kw={"悬赏","大熔炉","侦查队长洛洛尔","监工马托留斯","监工油拳","灼热峡谷","熔渣之池","瑟银兄弟会"},sec={{t="叛徒的代价",b="叛逃的黑铁矮人监工马托留斯就藏在大熔炉的熔渣之池深处。命令是杀掉他，取下他的头颅，并带回给侦查队长洛洛尔以领取赏金。"}},faq={{q="谁是监工马托留斯？",a="一名背叛的黑铁矮人。通告称他为叛逃的瑟银兄弟会特工，以及大熔炉黑铁熔渣之池挖掘队新雇佣的指挥官。",al={"马托留斯背景故事","谁是马托留斯","监工马托留斯背景"}},{q="在哪里可以找到监工马托留斯？",a="在属于大熔炉的熔渣之池下方。",al={"马托留斯位置","马托留斯在哪里","如何找到监工马托留斯"}},{q="是谁下令处死监工马托留斯的？",a="监工油拳，他在通告中被指名为下达该命令的人。",al={"谁发布了悬赏","谁想要马托留斯死","谁下达了处决令"}},{q="谁负责接收马托留斯死亡的证明？",a="位于灼热峡谷的侦查队长洛洛尔。马托留斯的头颅就是所要求的证明。",al={"把马托留斯的头颅交给谁","把马托留斯的头颅带到哪里","侦查队长洛洛尔位置"}}},fp="26,259,20.200.0,26.184.0,38.69.0,44.52.0,40.96.0"}
P.entries["quest:7704"] = {n="Look at the Size of It!",s="你得到了一只巨大的华丽枕头，它曾经属于女仆Pillaclencher。灼热峡谷的艾沃奈斯一定想要它。",h="你得到了一只巨大的华丽枕头，它曾经属于女仆Pillaclencher。灼热峡谷的艾沃奈斯一定想要它。",kw={"女仆 比拉凯琳","艾沃奈斯","看看这东西的尺寸","枕头","灼热峡谷"},sec={{t="给Evonice的枕头",b="你现在拥有了女仆Pillaclencher保存的枕头。艾沃奈斯肯定会迫不及待地想要得到它。把它带给灼热峡谷的她，看看她会为你这份辛苦提供什么报酬。"}},faq={{q="谁想要女仆比拉凯琳的枕头？",a="灼热峡谷的艾沃奈斯应该会非常想要它。",al={"我该把枕头带给谁","艾沃奈斯 枕头","枕头交给谁"}},{q="这个枕头是从哪来的？",a="它属于女仆比拉凯琳，又大又华丽。",al={"枕头掉落","谁掉落枕头","女仆枕头"}},{q="艾沃奈斯在哪里？",a="在灼热峡谷。",al={"艾沃奈斯 位置","艾沃奈斯 在哪里","艾沃奈斯 灼热峡谷"}}},fp="23,135,20.166.0,45.91.0,33.71.0,38.43.0"}
P.entries["quest:771"] = {n="幻象仪祭",s="幻象之礼是牛头人年轻人离开红云台地，前往更广阔的莫高雷时必须经历的一项基础性精神试炼。为了穿透帷幕并从先祖之灵那里获得指引，试炼者必须在血蹄村扎尔曼·双月的注视下，收集自然试剂来调制先知之水。",h="幻象之礼是牛头人年轻人离开红云台地，前往更广阔的莫高雷时必须经历的一项基础性精神试炼。为了穿透帷幕并从先祖之灵那里获得指引，试炼者必须在血蹄村扎尔曼·双月的注视下，收集自然试剂来调制先知之水。",kw={"琥珀玉米","血蹄村","大地母亲","莫高雷","幻象之礼","先知之水","水井石","扎尔曼·双月"},ang={["class:Druid"]="德鲁伊对琥珀玉米和水井石怀有深深的敬意，视它们为维持莫高雷平衡的植物群和生命之源的直接体现。",["class:Shaman"]="萨满会认出先知之水的调制是一种传统的稳固仪式，在与灵魂直接交流之前，先使精神能够感知到看不见的元素。",["race:Tauren"]="对于牛头人来说，幻象之礼是一个至关重要的文化里程碑，它将新晋的战士、猎人或秘法者与大地母亲和先祖的精神遗产紧密相连。"},sec={{t="大地的试剂",b="在获得任何幻象之前，试炼者必须展现出对散布在莫高雷各处的自然馈赠的深刻理解。扎尔曼·双月会指引寻求者收集神圣公用水井旁的水井石，以及落在莫高雷古树根部的琥珀玉米。这些自然元素不仅仅是物质，对于牛头人来说，它们蕴含着大地母亲的潜在魔力和生命之源，随时可以被引导用于仪式之中。"},{t="调制先知之水",b="收集齐之后，扎尔曼会将这些石头和琥珀玉米合成为强大的先知之水。在村庄的部落之火旁饮下这种仪式药剂后，思绪会变得清澈，并召唤出一名空灵的向导。跟随这道身影穿过平原是仪式的真正核心，它考验着试炼者在物质世界和大地精神低语之间行进的能力。"}},faq={{q="幻象之礼的目的是什么？",a="幻象之礼是一项针对成年且正在寻找道路的牛头人的精神测试。通过准备并饮下先知之水，试炼者学会了与灵魂交流，并跟随跨越莫高雷平原的先祖预兆前行。",al={"什么是幻象之礼","为什么要进行幻象之礼","幻象之礼的目的"}},{q="扎尔曼·双月是谁？",a="扎尔曼·双月是一位驻扎在血蹄村的牛头人萨满和先知。他负责监督年轻冒险者的精神试炼，准备诸如先知之水之类的仪式药剂，并解读大地母亲的迹象。",al={"扎尔曼是谁","扎尔曼·双月的职责","任务发布者扎尔曼"}},{q="在哪里可以找到水井石和琥珀玉米？",a="水井石可以在莫高雷各地散布的淡水水井旁的地面上收集到。琥珀玉米则散落在点缀着周围草地景观的大型蔓生树木的根部。",al={"去哪里找琥珀玉米","水井石位置","幻象之礼的试剂"}},{q="喝下先知之水后会发生什么？",a="在部落篝火旁饮下药剂会开启饮用者的灵视，显现出一名幽灵般的动物向导。寻求者必须跟随这个灵魂穿越平原，以揭开他们神圣旅程的下一阶段。",al={"幻象之礼下一步做什么","先知之水的效果","幻象任务后续"}},{q="为什么牛头人如此崇敬水井？",a="水是莫高雷的生命之源，也是大地母亲的珍贵馈赠。水井是神圣的公共中心，滋养着大地和兽群，这使得井边的石头充满了灵性。",al={"牛头人水井","为什么水井是神圣的","莫高雷的水"}},{q="这个任务会引出后续的仪式吗？",a="是的。这项任务是一个多阶段仪式的一部分。一旦扎尔曼调制好先知之水，试炼者必须饮下它，追踪出现的幻象，并向莫高雷各地的长者领袖报告。",al={"幻象之礼的下一个任务","幻象之礼是任务链吗","牛头人仪式任务链"}}},fx={["6b13f1a7"]={q="扎尔曼·双月为什么要你做这件事？",a="身为部族萨满，扎尔曼·双月有责任引导有潜力的年轻冒险者了解牛头人的神圣传统。他无法直接赐予你灵性智慧；你必须亲自参与仪式，亲手收集这片土地上的神圣元素，以此赢得大地母亲和先祖的眷顾。",al={"扎尔曼·双月的目的","扎尔曼为什么派你去","扎尔曼进行先知之水仪式的原因"}},cc7474fb={q="水井石有什么用？",a="水井石采自莫高雷各处的神圣水井。它们蕴含着大地母亲纯净泉水中的自然魔力，是扎尔曼·双月调制神秘的先知之水所需的关键材料之一。",al={"水井石的用途","为什么需要水井石","水井石的用法"}},["4efb8f2d"]={q="琥珀玉米有什么用？",a="琥珀玉米从莫高雷各处的参天树木上掉落，蕴含着这片土地植物的自然精华。它与水井石混合后，由扎尔曼·双月浸制，便能赋予先知之水所需的魔力，使你得以窥见先祖的景象。",al={"琥珀玉米的用途","琥珀玉米有什么用","为什么要找琥珀玉米"}},["761f0189"]={q="为什么要你收集材料，而不是扎尔曼·双月亲自去？",a="先知之水仪式是个人灵性成长的试炼，并非日常差事。要与灵魂交流，你必须亲自寻找大地赐予的自然恩泽，以此表明你敬重土地、与土地和谐共处。若由别人代为收集材料，便违背了这场试炼的神圣目的。",al={"为什么要我找琥珀玉米","扎尔曼为什么不自己收集水井石","为什么让我进行先知之水仪式"}}},fp="14,198,24.309.0,30.322.0,42.203.0,25.218.0,42.143.0,51.203.1,47.212.0,38.183.1"}
P.entries["quest:772"] = {n="幻象仪祭",s="幻象仪式是血蹄村年轻牛头人所进行的一项古老试炼的最高潮。通过在部落篝火旁饮用神圣的先知之水，试炼者能够召唤一位幽灵向导，指引他们走向命运。",h="幻象仪式是血蹄村年轻牛头人所进行的一项古老试炼的最高潮。通过在部落篝火旁饮用神圣的先知之水，试炼者能够召唤一位幽灵向导，指引他们走向命运。",kw={"血蹄村","幽灵狼","莫高雷","幻象仪式","先知奥萨迪·智慧行者","部落篝火","先知之水","扎尔曼·双月"},ang={["class:Druid"]="该仪式加强了对自然世界的敬畏，以及在动物形态指引面前的精神谦卑。",["class:Shaman"]="跟随先祖幽灵狼是行走于诸界之间的一门早期课程，它巩固了萨满与指引部落的灵魂之间的纽带。",["race:Tauren"]="对于年轻的牛头人来说，幻象仪式是一次神圣的成人礼，证明了他们与先祖的沟通以及对精神指引的服从。"},sec={{t="先知之水",b="在收集了必要的仪式草药并通过了最初的信仰试炼后，村庄萨满扎尔曼·双月会将先知之水赐予试炼者。这剂强力的药水必须在血蹄村中心那熊熊燃烧的部落篝火前饮用。当以专注且虔诚的心态饮用时，这神圣的水能够将饮用者的感知扩展到肉眼所见的范围之外，架起物质位面与精神领域之间的桥梁。"},{t="跟随幽灵狼",b="饮下药水后，火焰中会出现一个空灵的幻象：一只先祖幽灵狼。这灵体不会说话，也不会战斗，而是悄无声息地向西北方跑去，穿过莫高雷的草海平原。真正的试炼者必须留意它静谧的路径，追踪它远离村庄，深入岩石丘陵，那里，隐士先知奥萨迪·智慧行者正在潜心冥想。"},{t="智慧之旅",b="在山洞洞口找到先知奥萨迪·智慧行者，即标志着幻象试炼的成功完成。这段穿过草丘的旅程考验着试炼者的耐心、对先祖指引的信任以及与大地母亲的共鸣。通过这项仪式，年轻的冒险者将获得参加成人终极考验的资格：智慧仪式。"}},faq={{q="我喝下先知之水会发生什么？",a="在血蹄村的部落篝火旁饮用时，这种水会开启你的精神感知。饮用后不久，一只幽灵狼就会出现在火焰前方，指引你的道路。",al={"先知之水的作用原理","饮用先知之水","先知之水的效果"}},{q="灵魂向导会带我去哪儿？",a="幽灵狼会向西北方小跑出血蹄村，穿过莫高雷的丘陵，径直前往先知奥萨迪·智慧行者所居住的岩洞。",al={"幽灵狼去哪里","狼指引向谁","狼的目的地"}},{q="扎尔曼·双月是谁？",a="扎尔曼·双月是血蹄村一位著名的牛头人萨满，负责通过先祖仪式和神圣药剂帮助试炼者做好进入精神成年的准备。",al={"谁提供幻象仪式","扎尔曼·双月的职责"}},{q="先知奥萨迪·智慧行者是谁？",a="先知奥萨迪·智慧行者是一位年长的牛头人秘术师，在血蹄村西北方的悬崖中潜心冥想。跟随精神幻象的试炼者会找到他来完成试炼。",al={"先知奥萨迪·智慧行者是谁","莫高雷洞穴中的先知"}},{q="为什么必须在部落篝火旁饮用这种水？",a="部落篝火是血蹄村先祖之魂的神圣锚点。其受祝福的火焰与圣水相结合，使幻象得以在清醒的世界中显现。",al={"为什么要用部落篝火","篝火与幻象仪式"}},{q="幻象仪式之后是什么仪式？",a="在与先知奥萨迪·智慧行者完成幻象仪式后，试炼者将被指引去进行智慧仪式，这是他们在莫高雷早期旅程中的最后一次精神试炼。",al={"幻象仪式后的下一个任务","接下来是什么"}}},fx={["659b3713"]={q="扎尔曼·双月为什么要我进行先知之水仪式？",a="身为血蹄村的萨满，扎尔曼·双月引导年轻的牛头人踏上先祖的神圣道路。你已收集齐调制先知之水所需的材料，现在他将这剂药水交给你，让你亲自与灵魂交流、见证自己的幻象，并迈出下一步，在部族中探寻自己的命运。",al={"为什么要进行先知之水仪式","扎尔曼·双月的目的","先知之水仪式的目的"}},b8c8221c={q="为什么必须由我亲自进行这个仪式？",a="大地母亲的仪式是关乎成熟与灵性觉醒的个人试炼。没有守卫或长老能代你踏上灵魂之路；只有你自己的灵魂才能接受指引，发现自己在牛头人族群中的位置和使命。",al={"为什么必须由我进行仪式","为什么让我进行先知之水仪式","为什么不能让别人代替我进行仪式"}}},fp="14,147,22.349.0,24.288.0,16.306.0,49.162.0,36.134.0,25.152.0,23.189.0,49.160.0,41.153.0"}
P.entries["quest:7721"] = {n="压缩器的动力",s="在菲拉斯的被遗忘的海岸，索尔宾·范达瑟不顾劝阻开设了一家工程学商店，但当地的元素生物是个大麻烦。它们同时也是精炼“超级缩小器”的绝佳原始能量来源，而索尔宾想要的正是水元素核心。",h="在菲拉斯的被遗忘的海岸，索尔宾·范达瑟不顾劝阻开设了一家工程学商店，但当地的元素生物是个大麻烦。它们同时也是精炼“超级缩小器”的绝佳原始能量来源，而索尔宾想要的正是水元素核心。",kw={"菲拉斯","被遗忘的海岸","海元素","海浪","超级缩小器","水元素核心","索尔宾·范达瑟"},sec={{t="浪潮之力",b="索尔宾·范达瑟咒骂着元素魔法那不受控制的力量，并称海岸上的元素生物为害虫。但索尔宾同时也认为，它们是精炼“超级缩小器”时的绝佳原始能量来源。索尔宾要你去教训一下海岸上的海元素和海浪，收集它们的水元素核心，并带给码头边的索尔宾。"},{t="索尔宾的谢意",b="索尔宾非常高兴：这些核心足以维持一段时间的工作了，而且海岸上的元素生物也减少了。索尔宾补充说，把商店开在这个可能是世界上最糟糕的地方，让他每天晚上都想哭。索尔宾以酬金表达了谢意，尽管这让他的财政状况有些吃紧。"}},faq={{q="谁在索要水元素核心？",a="索尔宾·范达瑟，他在菲拉斯的被遗忘的海岸，靠近码头的地方开了一家工程学商店。",al={"谁发布了“浪潮之力”任务","索尔宾·范达瑟任务发布者","谁开启了“浪潮之力”"}},{q="索尔宾·范达瑟为什么需要水元素核心？",a="索尔宾认为当地的元素生物是精炼“超级缩小器”的绝佳原始能量来源，而他想要的正是水元素核心。",al={"为什么要水元素核心","核心有什么用","超级缩小器燃料"}},{q="从哪里收集这些元素核心？",a="索尔宾要你从游荡在菲拉斯被遗忘的海岸的海元素和海浪身上收集它们。",al={"哪里寻找核心","海元素位置","海浪在哪里"}}},fp="20,187,19.309.0,15.293.1,38.122.0,53.141.0,39.89.0"}
P.entries["quest:7722"] = {n="绝密配方！",s="大铁匠博恩奈特说，当马托里奥斯离开他们的氏族时，他带走了他们的炽热助熔剂配方，其价值远超一颗完美的奥术水晶。博恩奈特想要回这份秘密设计图，并确信它就在深入熔渣之池的马托里奥斯附近。",h="大铁匠博恩奈特说，当马托里奥斯离开他们的氏族时，他带走了他们的炽热助熔剂配方，其价值远超一颗完美的奥术水晶。博恩奈特想要回这份秘密设计图，并确信它就在深入熔渣之池的马托里奥斯附近。",kw={"博恩奈特","大熔炉","炽热助熔剂","马托里奥斯","设计图","灼热峡谷","熔渣之池"},sec={{t="失窃的配方",b="大铁匠博恩奈特称马托里奥斯是个叛徒，他带着炽热助熔剂的配方离开了氏族。博恩奈特敢打赌，这份配方一定随着马托里奥斯在黑铁矮人中的晋升一同被带走了，他想要回这份秘密设计图。"},{t="进入熔渣之池",b="博恩奈特确信设计图就在熔渣之池深处的马托里奥斯附近。博恩奈特想要带回的就是秘密设计图：炽热助熔剂。"}},faq={{q="是谁偷走了炽热助熔剂的配方？",a="马托里奥斯，大铁匠博恩奈特称他是氏族的叛徒。",al={"谁偷走了配方","谁拿走了设计图","炽热助熔剂叛徒"}},{q="秘密设计图在哪里？",a="博恩奈特相信它就在大熔炉的熔渣之池深处，靠近马托里奥斯的地方。",al={"设计图在哪里","秘密设计图：炽热助熔剂位置","去哪里寻找炽热助熔剂设计图"}},{q="是谁要求找回这些设计图？",a="是大铁匠博恩奈特，他想要回这些东西。",al={"谁发布了炽热助熔剂任务","炽热助熔剂任务发布者"}},{q="为什么这些设计图对博恩奈特很重要？",a="博恩奈特说，炽热助熔剂的配方价值远超一颗完美的奥术水晶，而且这是氏族自己的秘密。",al={"为什么炽热助熔剂很重要","炽热助熔剂配方的重要性"}}},fp="14,202,17.238.0,17.147.0,36.120.0,27.92.0,39.58.0,37.96.0"}
P.entries["quest:7723"] = {n="该死的手指头！",s="身处灼热峡谷的汉瑟尔·重拳由于手指浮肿，无法像以前那样挥舞拳头了。汉瑟尔请你去替他教训那些重型战争傀儡。",h="身处灼热峡谷的汉瑟尔·重拳由于手指浮肿，无法像以前那样挥舞拳头了。汉瑟尔请你去替他教训那些重型战争傀儡。",kw={"大熔炉","浮肿的手指","汉瑟尔·重拳","重型战争傀儡","灼热峡谷","塞尔萨玛血肠"},sec={{t="像香肠一样的手指",b="汉瑟尔·重拳说，峡谷的气候和稀薄的空气让他的手指肿胀起来，看起来就像巨大的塞尔萨玛血肠。结果，汉瑟尔无法像以前那样施展拳脚，只能请你代劳处理他的事务。"},{t="名单上的第一位",b="汉瑟尔议程上的第一项任务是那些峡谷里的重型战争傀儡，他要求你狠狠地教训它们。你需要摧毁二十个。它们在大熔炉周围游荡，等你消灭了足够多的傀儡后，再回到汉瑟尔那里。"}},faq={{q="谁是汉瑟尔·重拳？",a="一个身处灼热峡谷的人，由于手指浮肿无法继续战斗，所以他请你去替他打架。",al={"汉瑟尔·重拳","谁给予了该死的手指任务","谁是任务给予者"}},{q="为什么汉瑟尔不能亲自对付傀儡？",a="汉瑟尔认为是峡谷的气候和稀薄的空气导致了他的手指肿胀，他形容那肿胀的手指就像巨大的塞尔萨玛血肠。",al={"为什么汉瑟尔的手指会肿","手指浮肿背景故事","汉瑟尔浮肿的手"}},{q="需要对付哪些敌人？",a="二十个重型战争傀儡。",al={"我需要对付什么敌人","汉瑟尔想要消灭什么"}},{q="重型战争傀儡在哪里？",a="它们在大熔炉周围游荡，位于灼热峡谷内。",al={"傀儡在哪里","重型战争傀儡位置"}}},fp="23,160,21.257.0,17.177.0,25.133.0,47.130.0,29.41.0,39.77.0"}
P.entries["quest:7724"] = {n="熔岩蜘蛛的威胁！",s="汉瑟尔·重拳说，每当他想要片刻放松并反思自己的人生时，那些当权者就会派给他新的工作。大型熔岩蜘蛛在灼热峡谷制造了许多混乱，他想让你去杀掉二十只。",h="汉瑟尔·重拳说，每当他想要片刻放松并反思自己的人生时，那些当权者就会派给他新的工作。大型熔岩蜘蛛在灼热峡谷制造了许多混乱，他想让你去杀掉二十只。",kw={"烈焰威胁","大型熔岩蜘蛛","汉瑟尔·重拳","奥菲斯特","灼热峡谷","蜘蛛"},sec={{t="汉瑟尔的又一项工作",b="汉瑟尔·重拳抱怨说，当权者从来不让他清静。大型熔岩蜘蛛正在制造混乱，他宁愿由你来动手而不是他自己。"},{t="大型熔岩蜘蛛",b="奥菲斯特说这些蜘蛛从一个尴尬的地方喷出火焰，这让孩子们感到不安。汉瑟尔想要猎杀二十只大型熔岩蜘蛛，它们可以在灼热峡谷的高原和熔岩池边找到。"}},faq={{q="是谁派你去对付蜘蛛的？",a="在灼热峡谷的汉瑟尔·重拳，他本希望有一段安静的时光，却被派了又一项工作。",al={"任务发布者","谁发布任务","汉瑟尔"}},{q="为什么要杀死这些蜘蛛？",a="大型熔岩蜘蛛在制造混乱，而且奥菲斯特说它们喷火的方式让孩子们感到不安。",al={"为什么要杀蜘蛛","蜘蛛做了什么","蜘蛛问题"}},{q="是谁告诉汉瑟尔关于蜘蛛的事的？",a="奥菲斯特，他说这些蜘蛛从一个尴尬的地方喷出火焰。",al={"谁抱怨了蜘蛛","奥菲斯特"}},{q="必须杀死多少只大型熔岩蜘蛛？",a="汉瑟尔要求除掉二十只。",al={"多少只蜘蛛","蜘蛛数量"}}},fp="13,104,22.191.0,24.204.0,32.100.0,37.100.0,34.70.0,45.52.0"}
P.entries["quest:7725"] = {n="更多被缩小的巨人！",s="索尔宾·范达瑟知道你已经收集过残渣了，但他总是还需要更多。你可以再次使用索尔宾的超级压缩器去对付菲拉斯的巨人，索尔宾会在被遗忘的海岸码头等你。索尔宾这次没法给你太多的报酬，但他承诺会为你宣扬你的功绩。",h="索尔宾·范达瑟知道你已经收集过残渣了，但他总是还需要更多。你可以再次使用索尔宾的超级压缩器去对付菲拉斯的巨人，索尔宾会在被遗忘的海岸码头等你。索尔宾这次没法给你太多的报酬，但他承诺会为你宣扬你的功绩。",kw={"菲拉斯","被遗忘的海岸","巨人","微缩残渣","热砂港","超级压缩器","索尔宾·范达瑟"},sec={{t="超级压缩器的再演",b="索尔宾·范达瑟承认你已经收集过残渣，但称这次为再演，并说总是还需要更多。索尔宾请求你再次用索尔宾的超级压缩器去压缩菲拉斯的巨人，并将十份从被缩小的巨人身上得到的微缩残渣带到被遗忘的海岸码头。因为索尔宾无法提供太多的回报，他提议在他的地精朋友们中宣扬你的功绩，他们可是有很多双顺风耳呢。"},{t="索尔宾的感谢",b="索尔宾很高兴你能再次成功完成任务，即使报酬比你往常得到的要少。索尔宾坚持说，关于你为地精做出的伟大贡献的消息，已经在热砂港的权力核心中传开了。"}},faq={{q="谁需要更多的残渣？",a="索尔宾·范达瑟，他正在菲拉斯的被遗忘的海岸码头等你。",al={"任务发布者","索尔宾位置","谁发布了再次电击巨人"}},{q="之前发生了什么？",a="这是在“电击巨人”之后，即你为索尔宾·范达瑟进行的第一次残渣收集。",al={"前置条件","前置任务","我先做什么"}},{q="如何收集残渣？",a="对菲拉斯的任何一种巨人使用索尔宾的超级压缩器来将其缩小，然后就能在这些被缩小的巨人身上找到残渣。",al={"如何获取残渣","微缩残渣","如何缩小巨人"}},{q="在哪里可以找到巨人？",a="这些巨人分布在菲拉斯的西海岸。",al={"巨人位置","菲拉斯巨人在哪里","被遗忘的海岸巨人"}},{q="索尔宾以后还会要更多的残渣吗？",a="索尔宾说他永远需要更多的残渣，所以欢迎你再带十份回来。",al={"这是可重复任务吗","我可以重复再次电击巨人吗","可重复的巨人任务"}}},fp="28,224,32.327.0,15.225.1,26.93.0,22.87.0,28.119.0,27.45.0,43.88.0"}
P.entries["quest:7726"] = {n="补充动力",s="索尔宾·范达瑟需要更多的水元素之核。在被遗忘的海岸开设店铺十分困难，所以报酬会少一些，但索尔宾承诺会将你的帮助告诉周围的每一个人，并说热砂港里也有他的朋友。",h="索尔宾·范达瑟需要更多的水元素之核。在被遗忘的海岸开设店铺十分困难，所以报酬会少一些，但索尔宾承诺会将你的帮助告诉周围的每一个人，并说热砂港里也有他的朋友。",kw={"菲拉斯","被遗忘的海岸","海元素","海浪","热砂港","水元素之核","索尔宾·范达瑟"},sec={{t="如出一辙",b="索尔宾·范达瑟开玩笑说，从元素生物体内收集粘液这种英雄壮举，不知道你是不是想再来一次。抛开这些戏剧性的言论不谈，索尔宾确实需要更多的水元素之核。在这里建立店铺是一项孤注一掷的生意，所以能提供的报酬很少，但索尔宾承诺会告诉周围每一个能听到的人你是如何提供帮助的，并说你可以相信这一点，因为索尔宾在热砂港里认识不少人。需要六个核心，从被遗忘的海岸的海元素和海浪身上获取，并带给码头附近的索尔宾。"},{t="索尔宾的感谢",b="索尔宾很高兴，并承认这笔钱可能不是你从事此类工作所能获得的最丰厚的报酬。索尔宾在热砂港的同伴会知道你的努力，如果你还想找点事做，索尔宾还需要更多的核心和类似的东西。"}},faq={{q="是谁在请求水元素之核？",a="索尔宾·范达瑟，他在菲拉斯的被遗忘的海岸码头边。",al={"谁给予这个任务","索尔宾·范达瑟是谁","索尔宾在哪里"}},{q="水元素之核来自哪里？",a="它们是从菲拉斯被遗忘的海岸的海元素和海浪身上获取的。",al={"核心在哪里掉落","水元素之核位置","哪些敌人掉落核心"}},{q="为什么索尔宾·范达瑟需要更多的核心？",a="索尔宾只说需要更多的水元素之核，因为他在海岸建立店铺的过程举步维艰。",al={"为什么索尔宾想要核心","索尔宾·范达瑟的目的","核心是用来做什么的"}},{q="在此之前发生了什么？",a="这是“为充能提供燃料”的后续任务，当时你第一次为索尔宾收集了元素之核。",al={"之前的任务","前置任务","哪个任务在前"}}},fp="22,224,16.533.0,15.258.1,44.76.0,45.84.0,42.100.0,22.84.0"}
P.entries["quest:7727"] = {n="熏火龙",s="汉瑟尔·重拳说他的脚趾囊肿上又长了囊肿，以他现在这副糟糕的脚部状况根本无法去杀怪。斯克兰吉和伯纳特让他去清理熔渣之池里的灼热龙，所以他便打发你去杀掉二十只。",h="汉瑟尔·重拳说他的脚趾囊肿上又长了囊肿，以他现在这副糟糕的脚部状况根本无法去杀怪。斯克兰吉和伯纳特让他去清理熔渣之池里的灼热龙，所以他便打发你去杀掉二十只。",kw={"伯纳特","大熔炉","汉瑟尔·重拳","灼热龙","斯克兰吉","灼热峡谷","熔渣之池"},sec={{t="囊肿上的囊肿",b="汉瑟尔·重拳现在的状态根本无法战斗。斯克兰吉和伯纳特让他去杀掉灼热龙，以便考察队能够进入熔渣之池的熔岩池进行探索。汉瑟尔把这项工作推给了你。"},{t="熔岩池",b="灼热龙占据了大熔炉内熔渣之池的熔岩池。汉瑟尔要你杀掉二十只，在你完成任务之前他不想见到你。"}},faq={{q="汉瑟尔·重拳是谁？",a="他是在灼热峡谷给你指派这项任务的人。斯克兰吉和伯纳特让他去对付灼热龙，但他因为脚上的囊肿而无法行动。",al={"汉瑟尔·重拳","任务发布者是谁","谁给的任务"}},{q="为什么要清理掉灼热龙？",a="斯克兰吉和伯纳特需要考察队去探索熔渣之池的熔岩池。据说在那里的灼热龙制造了各种各样的麻烦。",al={"为什么要杀灼热龙","灼热龙的作用","为什么要清理熔渣之池"}},{q="在哪里能找到灼热龙？",a="在大熔炉内，熔渣之池的熔岩池里。",al={"灼热龙的位置","熔渣之池在哪里","熔岩池在哪里"}},{q="为什么汉瑟尔不亲自去狩猎它们？",a="他说他的脚趾囊肿上长了囊肿，他的脚太糟糕了，根本没法杀怪。",al={"为什么汉瑟尔不战斗","汉瑟尔的脚","汉瑟尔的囊肿"}}},fp="43,204,20.220.0,14.121.0,25.156.0,47.155.0,33.77.0,35.97.0"}
P.entries["quest:7728"] = {n="被盗：鼓风机和望远镜",s="一则通告列出了两件被盗物品：一个黑铁冶炼鼓风机和一副侦查员的望远镜。瑟银兄弟会确信是灼热峡谷中那些肆无忌惮、心怀嫉妒的黑铁矮人偷走了它们，无论谁找到这些物品，都应将其交给监工斯克兰格以换取报酬。",h="一则通告列出了两件被盗物品：一个黑铁冶炼鼓风机和一副侦查员的望远镜。瑟银兄弟会确信是灼热峡谷中那些肆无忌惮、心怀嫉妒的黑铁矮人偷走了它们，无论谁找到这些物品，都应将其交给监工斯克兰格以换取报酬。",kw={"黑铁","斯克兰格","灼热峡谷","冶炼","望远镜","瑟银兄弟会","鼓风机"},sec={{t="被盗货物",b="通告称这副望远镜是侦查员的精良工具，而那个鼓风机则是不可替代的冶炼工具。目前唯一确定的是黑铁矮人肯定偷走了它们。无论谁找到这些物品，都应将其归还给监工斯克兰格。"}},faq={{q="谁张贴了这份通告？",a="这份通告提到了瑟银兄弟会，他们确信是黑铁矮人偷走了这些物品。",al={"谁想要这些被盗物品","谁发布了这个任务","被盗冶炼鼓风机任务发布者"}},{q="谁偷走了这些工具？",a="瑟银兄弟会确信是灼热峡谷中那些肆无忌惮、心怀嫉妒的黑铁矮人所为。",al={"谁拿走了鼓风机","谁偷走了望远镜","谁持有这些被盗物品"}},{q="谁负责接收找回的物品？",a="灼热峡谷的监工斯克兰格。",al={"我在哪里提交任务","监工斯克兰格是谁","谁要收回望远镜"}},{q="这些被盗物品有什么用途？",a="鼓风机是一种不可替代的冶炼工具，而望远镜则是侦查员所用的贵重监控工具。",al={"什么是冶炼鼓风机","为什么兄弟会想要那个鼓风机","望远镜有什么用"}}},fp="46,261,12.299.0,22.97.0,20.112.0,33.48.0,30.89.0"}
P.entries["quest:7729"] = {n="工作机会：肃清竞争对手",s="一则告示宣布监工斯克兰格需要一些能干的人手去灼热峡谷清除竞争对手。工作内容是屠杀黑铁监工和黑铁奴役者，直到你的衣服被血染透，然后回到斯克兰格那里。",h="一则告示宣布监工斯克兰格需要一些能干的人手去灼热峡谷清除竞争对手。工作内容是屠杀黑铁监工和黑铁奴役者，直到你的衣服被血染透，然后回到斯克兰格那里。",kw={"清除竞争对手","黑铁奴役者","黑铁监工","工作机会","灼热峡谷","监工斯克兰格"},sec={{t="一个空缺职位",b="斯克兰格希望应聘者前往峡谷，屠杀他们遇到的黑铁监工和黑铁奴役者：各十五名。等你衣服上的血迹足够多时再回来。到时候你自然会知道，别问那么多。"}},faq={{q="谁提供了这份工作？",a="灼热峡谷的监工斯克兰格，他需要人手帮他清除竞争对手。",al={"谁提供这个任务","谁想要杀死监工","监工斯克兰格是谁"}},{q="必须杀死哪些敌人？",a="十五名黑铁监工和十五名黑铁奴役者。",al={"我要杀什么","工作机会的目标","谁是竞争对手"}},{q="斯克兰格如何判断工作已完成？",a="看你衣服的状态。斯克兰格会通过称量你穿衣和脱衣后的体重来确认。",al={"如何证明杀敌","血衣要求","斯克兰格如何检查"}}},fp="40,95,16.211.0,25.75.0,28.65.0,39.96.0"}
P.entries["quest:773"] = {n="智慧仪祭",s="智慧试炼是莫高雷的年轻冒险者们所要进行的传统大地母亲试炼中的最后一项。在通过幻象试炼净化了视界之后，祈求者会前往赤色石的神圣墓地，与一位先祖之魂进行沟通，并接受逝者的祝福。",h="智慧试炼是莫高雷的年轻冒险者们所要进行的传统大地母亲试炼中的最后一项。在通过幻象试炼净化了视界之后，祈求者会前往赤色石的神圣墓地，与一位先祖之魂进行沟通，并接受逝者的祝福。",kw={"先祖之魂","莫高雷","赤色石","智慧试炼","大地母亲试炼","先知奥萨迪·智慧行者","雷霆崖","先知之水"},ang={["class:Druid"]="这项试炼展示了生者世界与大地母亲所监管的永恒轮回之间的平衡，使年轻的德鲁伊们扎根于他们对这片土地的职责之中。",["class:Shaman"]="直接与先祖之魂进行沟通，强化了萨满祭司的核心职责，即尊崇逝者并坚守与守护莫高雷的灵魂之间的信仰。",["race:Tauren"]="对于舒哈鲁来说，在赤色石接受先祖赋予的传承重任，是迈向完全成年并被部落长者接纳的关键时刻。"},sec={{t="赤色石试炼",b="在通过幻象试炼清除了视界障碍后，年轻的保卫者们会被指引前往雷霆崖以东的赤色石。这片古老的墓地安葬着那些为了在莫高雷开辟和平家园而浴血奋战并牺牲者的遗骸，也留存着他们的灵魂。通过这项试炼需要以足够的敬意与沟通接近这些安息之所，并直面徘徊在山丘间的任何领地威胁，以寻求受人尊敬的先贤的指引。"},{t="传承重任",b="在赤色石之巅，与先祖之魂的沟通并非是对武力的考验，而是对精神准备和传承性的检验。安息在那里的灵魂代表着曾经与凯恩·血蹄并肩作战，建立雷霆崖并保卫部落的那一代先祖。通过接受他们的祝福，祈求者正式继承了守卫这座城市的庄严职责，从而赢得了作为一名被认可的成年人和保卫者的地位，可以自豪地进入雷霆崖。"}},faq={{q="智慧试炼的目的是什么？",a="智慧试炼完成了大地母亲试炼，将青年时代的幻象沟通与成年后的庄严责任连接了起来。通过获得先祖之魂的祝福，祈求者证明了他们尊重先辈的牺牲，并已做好保卫雷霆崖的准备。",al={"为什么进行智慧试炼","智慧试炼的作用","智慧试炼的目的"}},{q="是谁指引你进行智慧试炼的？",a="先知奥萨迪·智慧行者位于血蹄村西北方的洞穴中，他会指引那些成功完成幻象试炼并饮用了先知之水的初学者们进行这项试炼。",al={"谁提供智慧试炼","如何开始智慧试炼"}},{q="在哪里可以找到先祖之魂？",a="先祖之魂位于赤色石，那是一片坐落在雷霆崖正东方岩石峭壁中的古老牛头人墓地。",al={"先祖之魂的位置","灵魂在哪里","去哪里寻找先祖之魂"}},{q="为什么必须先进行幻象试炼？",a="只有那些饮用了先知之水并净化了灵视的人，才能感知并接受赤色石处古老灵魂的祝福。",al={"为什么先做幻象试炼","幻象试炼前提条件","先知之水要求"}},{q="完成智慧试炼后会发生什么？",a="在获得了先祖的认可后，初学者们会被指示正式踏上进入雷霆崖高地的旅程。",al={"完成智慧试炼后做什么","智慧试炼后的后续任务"}},{q="哪些生物威胁着赤色石的安宁？",a="赤色石的神圣墓地遭到了具有攻击性的苍鬃豺狼人的侵扰，它们潜伏在通往这处古老墓葬区的岩石小径上。",al={"赤色石的敌人","什么在守卫赤色石","赤色石的豺狼人"}}},fx={["740e2883"]={q="先知奥萨迪·智慧行者为何派你执行智慧仪式？",a="先知奥萨迪·智慧行者引导有前途的年轻牛头人完成大地母亲的传统仪式。他见你承受住了先知之水带来的幻象，便指引你前往赤色石，接受先祖的祝福。对智慧行者和长老们而言，这一仪式确保只有在精神上做好准备、并得到先祖认可的人，才能作为部族的守护者进入雷霆崖。",al={"先知奥萨迪·智慧行者的目的","为什么要进行智慧仪式","为什么派我执行智慧仪式"}},["8728f84f"]={q="为什么先知奥萨迪·智慧行者要你去，而不是亲自前往？",a="智慧仪式是个人的成年试炼，不是可以由别人代劳的差事。若要获得长老们的认可并赢得进入雷霆崖的资格，你必须亲自前往赤色石寻找先祖之魂，展现从先知之水中获得的精神澄明。守护这座城市的职责只能直接授予你。",al={"为什么是我执行智慧仪式","先知奥萨迪·智慧行者为什么不亲自去","为什么要我寻找先祖之魂"}}},fp="14,213,22.325.0,18.396.0,42.196.0,36.147.0,39.127.0,41.161.0,49.108.0,49.137.0"}
P.entries["quest:7730"] = {n="祖卡什的入侵",s="在莫沙彻营地，哈杜肯·迅蹄听闻在豺狼人南面出现了一些昆虫般的生物：祖卡什。如果正是它们在煽动豺狼人发狂，那么它们构成的威胁丝毫不亚于豺狼人，甚至可能更严重。你被派往它们的老巢——痛苦深渊，去削减它们的数量并带回二十个甲壳。",h="在莫沙彻营地，哈杜肯·迅蹄听闻在豺狼人南面出现了一些昆虫般的生物：祖卡什。如果正是它们在煽动豺狼人发狂，那么它们构成的威胁丝毫不亚于豺狼人，甚至可能更严重。你被派往它们的老巢——痛苦深渊，去削减它们的数量并带回二十个甲壳...",kw={"莫沙彻营地","甲壳","菲拉斯","豺狼人","哈杜肯·迅蹄","昆虫","痛苦深渊","祖卡什"},sec={{t="豺狼人南面的敌人",b="哈杜肯·迅蹄认为，在豺狼人南面的敌人是一群昆虫般的生物。至于它们是否拥有智慧，哈杜肯并不关心。如果正是它们在驱使豺狼人疯狂攻击莫沙彻营地，那么它们构成的威胁就和豺狼人一样大，甚至更大。你必须深入它们居住的地方，也就是痛苦深渊，削减它们的数量。二十个祖卡什的甲壳将作为你的战果证明，哈杜肯还想听听你的发现。"},{t="哈杜肯的结论",b="当你回来时，哈杜肯感到很高兴。如果不进行全面的入侵，祖卡什的威胁将无法根除，但你已经为营地争取到了制定适当策略的时间。这些甲壳将被送去分析，因为营地必须了解关于这些生物的一切。不幸的是，这已经变成了一个比任何人预想中都要严重得多的问题。"}},faq={{q="是谁派你去对付祖卡什的？",a="菲拉斯莫沙彻营地的哈杜肯·迅蹄。",al={"任务发布者","哈杜肯·迅蹄","谁开启了祖卡什的侵扰"}},{q="祖卡什是什么？",a="哈杜肯认为它们是位于豺狼人南面的一群昆虫般的生物。至于它们是否拥有智慧，这对哈杜肯来说并不重要，重要的是它们可能正在驱使豺狼人发狂。",al={"什么是祖卡什","祖卡什昆虫","痛苦深渊虫子"}},{q="痛苦深渊在哪里？",a="那是祖卡什昆虫居住的地方，位于豺狼人南面。",al={"痛苦深渊位置","痛苦深渊在哪里","虫子在哪里"}},{q="为什么哈杜肯需要祖卡什的甲壳？",a="哈杜肯需要这些甲壳作为你对付祖卡什的战果证明。",al={"为什么需要甲壳","祖卡什甲壳的用途","甲壳的用途"}}},fp="20,201,27.379.0,17.310.1,33.60.0,22.177.0,27.66.0,41.71.0"}
P.entries["quest:7731"] = {n="毒刺鞭笞者",s="在勘察痛苦深渊时，哈杜肯·迅蹄的一名侦察兵发现了一只巨型昆虫，它远比其他的昆虫巨大，在扭曲的地形中游荡。这只怪兽被命名为毒刺鞭笞者，哈杜肯希望你能除掉它，并将它的分泌腺带回莫沙彻营地。",h="在勘察痛苦深渊时，哈杜肯·迅蹄的一名侦察兵发现了一只巨型昆虫，它远比其他的昆虫巨大，在扭曲的地形中游荡。这只怪兽被命名为毒刺鞭笞者，哈杜肯希望你能除掉它，并将它的分泌腺带回莫沙彻营地。",kw={"莫沙彻营地","菲拉斯","腺体","哈杜肯·迅蹄","昆虫","毒刺鞭笞者","痛苦深渊","祖卡什"},sec={{t="虫群中的巨人",b="痛苦深渊里的一名侦察兵看到了一只远比其他昆虫巨大的怪兽，正在扭曲的地形中徘徊。它似乎还散发出一种与其他昆虫截然不同的光环。它被命名为毒刺鞭笞者。在哈杜肯设法应对这一新威胁时，研究它的内脏将非常有价值，因此哈杜肯希望你能切下它的分泌腺，并直接带到莫沙彻营地。"},{t="哈杜肯的感谢",b="哈杜肯印象深刻。如果毒刺鞭笞者确实是这些昆虫中最强大的存在之一，那么研究这头野兽终将证明其价值。哈杜肯的任务是确保营地能够坚持足够长的时间以从中获益。作为全营地的谢意，他为你准备了一笔赏金。"}},faq={{q="是谁派你去对付毒刺鞭笞者的？",a="哈杜肯·迅蹄，位于菲拉斯的莫沙彻营地。",al={"任务发布者","谁发布毒刺鞭笞者任务","哈杜肯·迅蹄"}},{q="毒刺鞭笞者在哪里？",a="毒刺鞭笞者在痛苦深渊的扭曲地形中游荡。",al={"毒刺鞭笞者位置","毒刺鞭笞者在哪里","痛苦深渊位置"}},{q="毒刺鞭笞者与其他昆虫有什么不同？",a="一名侦察兵报告说发现了一只体型巨大的昆虫，而且它似乎散发出一种其他昆虫所没有的光环。",al={"为什么要杀毒刺鞭笞者","毒刺鞭笞者是什么","毒刺鞭笞者光环"}},{q="为什么哈杜肯想要毒刺鞭笞者的腺体？",a="哈杜肯说，在制定应对这一新威胁的计划时，研究它的内脏将是无价之宝。",al={"为什么要收集腺体","毒刺鞭笞者腺体用途"}}},fp="11,98,25.343.0,16.250.1,32.76.0,27.61.0,56.110.0,43.116.0"}
P.entries["quest:7732"] = {n="祖卡什报告",s="哈杜肯·迅蹄说你在对抗威胁莫沙彻营地的祖卡什虫群时表现得非常出色，但危险远未结束。为部落再帮最后一个忙：将记录了关于祖卡什虫群所有情报的文件带到奥格瑞玛，交给基尔兹宾·鼓眼。",h="哈杜肯·迅蹄说你在对抗威胁莫沙彻营地的祖卡什虫群时表现得非常出色，但危险远未结束。为部落再帮最后一个忙：将记录了关于祖卡什虫群所有情报的文件带到奥格瑞玛，交给基尔兹宾·鼓眼。",kw={"莫沙彻营地","力量谷","菲拉斯","哈杜肯·迅蹄","奥格瑞玛","其拉虫人","基尔兹宾·鼓眼","祖卡什报告"},sec={{t="送往力量谷的文件",b="哈杜彻·迅蹄手里有一份文件，记录了营地对祖卡什虫群的所有了解。它们构成的威胁远未结束，哈杜肯请求你把它带到奥格瑞玛。在那里的力量谷住着基尔兹宾·鼓眼，他是这类外来生物的专家，哈杜肯希望目前收集到的情报能发挥作用。"},{t="专家的结论",b="基尔兹宾一直在等待这份报告。他称你面对的生物是一种古老的威胁，而部落却一直选择忽视它，他说哈杜肯明智地同时送来了报告和你本人。祖卡什虫群不过是被称为其拉虫人的生物而已。有些人认为它们只是无脑的害虫，但基尔兹宾向你保证，它们比联盟可能集结的任何威胁都要可怕得多。"}},faq={{q="谁把报告送往奥格瑞玛？",a="位于菲拉斯莫沙彻营地的哈杜肯·迅蹄交给你这份文件。",al={"谁给出了祖卡什报告","谁开启祖卡什报告","任务发布者"}},{q="报告送交的对象是谁？",a="送交给住在奥格瑞玛力量谷的基尔兹宾·鼓眼。",al={"报告送到哪里","谁收到祖卡什报告","鼓眼的位置"}},{q="为什么要把这份文件送到奥格瑞玛？",a="基尔兹宾·鼓眼是像祖卡什这样的外来生物的专家，哈杜肯希望营地收集到的情报能派上用场。",al={"为什么要送往奥格瑞玛","报告的目的"}},{q="在此次交付之前发生了什么？",a="这发生在你对抗祖卡什虫群的努力之后，具体是在任务“祖卡什虫害”和“刺鞭虫”之后。",al={"之前的任务","前置条件"}}},fp="15,192,23.293.0,20.336.1,34.71.0,32.80.0,39.127.0,31.103.0"}
P.entries["quest:7733"] = {n="更高的品质",s="普拉特·马克格鲁比听说了一种比上次更好的兽皮。在菲拉斯的北部，怒痕堡内游荡着另一群雪人，它们比你之前面对的那些更强壮。羽月要塞需要十张它们的皮。",h="普拉特·马克格鲁比听说了一种比上次更好的兽皮。在菲拉斯的北部，怒痕堡内游荡着另一群雪人，它们比你之前面对的那些更强壮。羽月要塞需要十张它们的皮。",kw={"羽月要塞","菲拉斯","改进的品质","普拉特·马克格鲁比","怒痕堡","瑟银","雪人皮","雪人"},sec={{t="更强壮的雪人群",b="在完成“品质的证明”之后，普拉特·马克格鲁比找到了一条关于品质更优的兽皮的线索。在菲拉斯的北部，怒痕堡内居住着另一群雪人，它们比你之前面对的那些更加强壮。普拉特·马克格鲁比愿意花重金收购十张它们的皮，带回羽月要塞即可完成这笔交易。如果它们的品质能与怒痕兽皮相媲美，那它们将拥有像瑟银一样坚韧的特质。"},{t="普拉特的感谢",b="这些兽皮甚至比预想的还要好。普拉特·马克格鲁比已经看出，经过适当的鞣制，它们会变得非常坚硬，并把其中一件最新的成品作为谢礼交给你。"}},faq={{q="谁需要怒痕雪人的皮？",a="位于菲拉斯羽月要塞的普拉特·马克格鲁比。",al={"谁给予改进的品质任务","改进的品质任务发布者","普拉特·马克格鲁比"}},{q="怒痕雪人居住在哪里？",a="在菲拉斯北部的怒痕堡内。",al={"怒痕雪人位置","怒痕堡在哪里","去哪里获取怒痕兽皮"}},{q="需要多少张兽皮？",a="普拉特·马克格鲁比需要十张怒痕雪人皮。",al={"多少张雪人皮","改进的品质所需物品"}},{q="在此之前的任务是什么？",a="这是“品质的证明”后续任务，你之前已经处理了第一群雪人。",al={"前置任务","什么任务引导至改进的品质","上一个任务"}}},fp="16,134,25.303.0,14.171.1,38.87.0,34.67.0,26.47.0,22.80.0"}
P.entries["quest:7734"] = {n="更高的品质",s="杉多尔·迅蹄听说有一种比上一次更好的皮料。在菲拉斯的北部，怒痕堡里，漫游着另一群雪人，它们比你之前面对的那些更强壮。莫沙彻营地需要十张它们的皮。",h="杉多尔·迅蹄听说有一种比上一次更好的皮料。在菲拉斯的北部，怒痕堡里，漫游着另一群雪人，它们比你之前面对的那些更强壮。莫沙彻营地需要十张它们的皮。",kw={"莫沙彻营地","菲拉斯","改进的品质","杉多尔·迅蹄","怒痕堡","怒痕雪人","雪人皮"},sec={{t="更强的雪人群",b="在完成“品质的标志”后，杉多尔·迅蹄找到了一条关于品质更好的皮料的线索。在菲拉斯的北部，怒痕堡里生活着另一群雪人，它们比你之前面对的那些更强壮。如果你能把十张它们的皮带回莫沙彻营地，杉多尔·迅蹄将给你丰厚的报酬。如果它们的品质能达到菲拉斯伤痕皮的水平，它们可能和瑟银一样坚韧。"},{t="杉多尔的谢意",b="这些皮料比预想的还要好。杉多尔·迅蹄敢肯定，经过适当的处理，它们会变得非常坚硬。为了表示感谢，他交给你一件最新的成品。"}},faq={{q="谁需要怒痕雪人的皮？",a="位于菲拉斯莫沙彻营地的杉多尔·迅蹄。",al={"谁给予改进的品质任务","改进的品质任务发布者","杉多尔·迅蹄"}},{q="怒痕雪人生活在哪里？",a="在菲拉斯北部的怒痕堡内。",al={"怒痕雪人位置","怒痕堡在哪里","在哪里获取怒痕皮"}},{q="需要多少张皮？",a="杉多尔·迅蹄需要十张怒痕雪人皮。",al={"需要多少雪人皮","改进的品质所需物品"}},{q="在此之前发生了什么？",a="这是在“品质的标志”之后，当时你处理了第一批雪人。",al={"前置任务","什么任务引导至改进的品质","上一个任务"}}},fp="16,101,25.287.0,16.172.1,38.82.0,34.68.0,26.52.0,22.78.0"}
P.entries["quest:7735"] = {n="原始雪人毛皮",s="你获得了一张异常厚实坚韧的雪人皮，甚至比你在愤怒伤痕的雪人身上见过的任何皮毛都要结实。羽月要塞的普拉特·马克格鲁比正在寻找雪人皮，这张皮他可能会感兴趣。",h="你获得了一张异常厚实坚韧的雪人皮，甚至比你在愤怒伤痕的雪人身上见过的任何皮毛都要结实。羽月要塞的普拉特·马克格鲁比正在寻找雪人皮，这张皮他可能会感兴趣。",kw={"羽月要塞","菲拉斯","普拉特·马克格鲁比","完好的雪人皮","愤怒伤痕","雪人皮"},sec={{t="非同一般的皮毛",b="这张皮毛保存完好，显然比从愤怒伤痕的雪人身上剥下的皮毛更厚、更结实。位于菲拉斯羽月要塞的普拉特·马克格鲁比想要收购雪人皮，所以这张皮值得你带给他。"},{t="普拉特的反应",b="普拉特感到十分惊讶，并大声感叹这是否就是世间最棒的雪人皮。普拉特会为你支付报酬，这比通常的雪人皮价格要高得多，他认为可以用它制作出特别的东西。"}},faq={{q="谁想要这张完好的雪人皮？",a="位于菲拉斯羽月要塞的普拉特·马克格鲁比，他正在收购雪人皮。",al={"谁收购完好的雪人皮","我该把雪人皮带去哪里","普拉特·马克格鲁比 雪人皮"}},{q="这张皮有什么特别之处？",a="它异常厚实坚韧，甚至超过了来自愤怒伤痕的雪人皮。",al={"完好的雪人皮来源","这张皮有何特别之处","菲拉斯 雪人皮"}},{q="普拉特·马克格鲁比在哪里？",a="在菲拉斯的羽月要塞。",al={"普拉特·马克格鲁比在哪里","把完好的雪人皮交给谁"}}},fp="18,147,26.188.0,16.174.1,33.82.0,29.82.0,25.56.0"}
P.entries["quest:7736"] = {n="炽热助熔剂的补给：皇血草",s="在完成“这是什么助熔剂？”之后，大铁匠博恩奈特转而着手补充灼热峡谷中日益短缺的炽热助熔剂储备。博恩奈特需要火炎龙鳞、皇血草和煤炭，而且多多益善。",h="在完成“这是什么助熔剂？”之后，大铁匠博恩奈特转而着手补充灼热峡谷中日益短缺的炽热助熔剂储备。博恩奈特需要火炎龙鳞、皇血草和煤炭，而且多多益善。",kw={"博恩奈特","煤炭","炽热助熔剂","火炎龙","皇血草","灼热峡谷","瑟银兄弟会"},sec={{t="急需炽热助熔剂",b="大铁匠博恩奈特没时间闲聊。炽热助熔剂的库存已经告急，博恩奈特需要火炎龙鳞、皇血草和煤炭：两个鳞片，四株皇血草，以及煤炭。博恩奈特要你送来尽可能多的材料。"}},faq={{q="是谁在需求这些物资？",a="位于灼热峡谷的大铁匠博恩奈特，他会亲自接收这些物资。",al={"谁发布了这个任务","博恩奈特 炽热助熔剂","在哪里交任务"}},{q="博恩奈特需要什么材料？",a="两个火炎龙鳞，四株皇血草，以及一些煤炭。",al={"我需要什么物品","炽热助熔剂所需材料","博恩奈特 提交物品"}},{q="这个请求的前置任务是什么？",a="名为“这是什么助熔剂？”的任务，这是博恩奈特之前交给你的。",al={"此任务的前置要求","炽热助熔剂之前的任务","“这是什么助熔剂？”前置条件"}},{q="为什么博恩奈特需要这些物资？",a="博恩奈特说炽热助熔剂的供应正在减少，他想要补充储备。",al={"为什么需要炽热助熔剂","博恩奈特的动机"}}},fp="44,177,17.181.0,25.91.0,35.66.0,30.70.0,36.78.0"}
P.entries["quest:7738"] = {n="完美的雪人毛皮",s="你找到了一张完美的雪人皮，它非常厚实坚韧，远胜于怒痕的雪人所产出的皮。在莫沙彻营地，杉多尔·迅蹄正在寻找雪人皮。",h="你找到了一张完美的雪人皮，它非常厚实坚韧，远胜于怒痕的雪人所产出的皮。在莫沙彻营地，杉多尔·迅蹄正在寻找雪人皮。",kw={"莫沙彻营地","菲拉斯","杉多尔·迅蹄","完美的雪人皮","怒痕","雪人毛皮"},sec={{t="值得展示的毛皮",b="这张毛皮显然比怒痕雪人的皮更厚实、更坚固。在菲拉斯的莫沙彻营地，杉多尔·迅蹄希望能收购雪人皮，所以这张皮值得带去给他。"},{t="杉多尔的评价",b="杉多尔很高兴，称这是他见过的最好的雪人皮。他决定给予一份合理的奖励，比他平时收购单张毛皮的价格更高。他确信能用这张毛皮制作出某种特别的东西。"}},faq={{q="谁对完美的雪人皮感兴趣？",a="位于菲拉斯莫沙彻营地的杉多尔·迅蹄，他希望能收购雪人皮。",al={"谁需要毛皮","谁来上交完美的雪人皮","杉多尔雪人毛皮"}},{q="为什么这张毛皮被认为是完美的？",a="它异常厚实坚韧，极有可能是完美的，比怒痕雪人的皮要好得多。",al={"为什么它是完美的","这张毛皮有何特别之处"}},{q="杉多尔·迅蹄在哪里？",a="在菲拉斯的莫沙彻营地。",al={"杉多尔·迅蹄在哪里","去哪里上交完美的雪人皮"}}},fp="17,163,20.175.0,17.177.1,43.72.0,36.92.0,30.51.0"}
P.entries["quest:775"] = {n="雷霆崖之旅",s="“前往雷霆崖之旅”是年轻英雄在莫高雷试炼终点的朝圣之旅。在先祖之魂的指引下完成了神圣的大地母亲的试炼后，The Adventurer将获得觐见牛头人大酋长凯恩·血蹄的机会。",h="“前往雷霆崖之旅”是年轻英雄在莫高雷试炼终点的朝圣之旅。在先祖之魂的指引下完成了神圣的大地母亲的试炼后，The Adventurer将获得觐见牛头人大酋长凯恩·血蹄的机会。",kw={"先祖之魂","凯恩·血蹄","高地","前往雷霆崖之旅","莫高雷","大地母亲的试炼","雷霆崖"},ang={["faction:Horde"]="牛头人愿意欢迎任何完成其神圣传统的盟友种族，这体现了将年轻的部落团结在一起的相互尊重。",["race:Tauren"]="对于年轻的牛头人来说，在完成大地母亲的试炼后站在凯恩·血蹄面前，是步入成年和部落荣誉的决定性门槛。"},sec={{t="一场试炼的终结",b="在任何旅者或雏鹰战士真正宣称自己在莫高雷证明了自己之前，他们都必须经历古老的大地母亲的试炼。这些试炼在草海平原和这片土地上的先祖遗迹中考验着他们的力量、视野和智慧。一旦先祖之魂认可了最后的试炼，修行者便被认为有资格进入雷霆崖，不再仅仅是一名访客，而是牛头人人民的一位荣耀的保卫者。"},{t="登上High Rise",b="任务指引旅者从先祖游荡的神圣土地径直前往高耸的雷霆崖。这座城市坐落在平顶山之上，是一座由红岩雕琢而成的和平灯塔，并由宽阔的绳桥和巨大的木制升降梯支撑。在那里，在High Rise上，大酋长凯恩·血蹄正等待着亲自迎接那些走过先祖之路的人们。"}},faq={{q="是谁指派你踏上这段旅程的？",a="在你完成大地母亲的试炼的最后一步——智慧试炼后，这个任务将由先祖之魂授予。",al={"谁发布任务","先祖之魂任务","任务发布者"}},{q="我在哪里可以找到凯恩·血蹄？",a="凯恩·血蹄居住在高地上，这是雷霆崖中心的高耸平顶山，俯瞰着周围的红色高原和平原。",al={"凯恩位置","凯恩在哪里","雷霆崖首领"}},{q="完成这个任务有什么意义？",a="它标志着你在莫高雷的起始冒险正式结束。觐见凯恩意味着你已得到牛头人领导层的完全认可，并准备好在更广阔的部落中承担责任。",al={"为什么要拜访凯恩","试炼的意义","前往雷霆崖之旅的意义"}},{q="只有牛头人才能完成这段旅程吗？",a="虽然这是一场根深蒂固的牛头人传统成年礼，但任何通过大地母亲的试炼证明了自己奉献精神的部落成员，都会被授予同样的荣誉，并被派遣去觐见大酋长。",al={"兽人可以完成吗","谁可以前往雷霆崖","种族"}},{q="与凯恩交谈后会发生什么？",a="凯恩会欢迎你来到他的家，认可你的功绩，并指引你前往卡利姆多，面对部落所面临的更广泛的冲突。",al={"下一个任务","找过凯恩后做什么","前往雷霆崖之旅之后"}},{q="如何抵达雷霆崖的高地？",a="乘坐从下方平原通往平顶山的巨大机械升降梯，然后穿过通往中心高地平台的绳索和木制桥梁，酋长的住所就矗立在那里。",al={"前往高地","如何找到凯恩","雷霆崖升降梯"}}},fx={["74afb15b"]={q="先祖之魂为何派你前往雷霆崖？",a="你在莫高雷经受了重重考验，并与灵魂沟通，凭借大地母亲的仪式证明了自己的智慧、力量与虔诚。先祖之魂指引你前往雷霆崖，让牛头人族群及其最高领袖凯恩·血蹄知晓你的功绩。站在大酋长面前，意味着你正式成为他们社会的一员，并获接纳为受尊崇的勇士。",al={"先祖之魂为什么派你去","先祖之魂的目的","为什么要去找凯恩"}},c86a41a9={q="为什么必须由你亲自把消息告诉凯恩·血蹄？",a="大地母亲的仪式是神圣的个人试炼。先祖之魂是超凡的向导，受莫高雷圣地所缚，既无法也无意传递尘世的消息。既然接受考验的是你的灵魂与意志，亲自拜见大酋长凯恩·血蹄的荣誉便只属于你。",al={"为什么是我去找凯恩","为什么必须拜访凯恩","为什么必须去见凯恩·血蹄"}}},fp="26,152,27.307.0,26.303.0,30.128.0,34.111.0,50.174.0,37.205.0,38.135.0,48.183.0"}
P.entries["quest:776"] = {n="大地之母仪祭",s="这项由大酋长凯恩·血蹄亲自设立的试炼，要求初露锋芒的英雄们在莫高雷平原上猎杀伟大的科多兽阿兰其亚。尽管新兵可能已经完成了传统的成人仪式，但凯恩希望他的人民能够不断重申他们的力量、追踪技巧以及对部落的忠诚。带回阿兰其亚的角，证明了一位冒险者已经准备好为台地之外更广阔的部落效力。",h="这项由大酋长凯恩·血蹄亲自设立的试炼，要求初露锋芒的英雄们在莫高雷平原上猎杀伟大的科多兽阿兰其亚。尽管新兵可能已经完成了传统的成人仪式，但凯恩希望他的人民能够不断重申他们的力量、追踪技巧以及对部落的忠诚。带回阿兰其亚的角...",kw={"阿兰其亚","血蹄","凯恩","大地母亲","角","狩猎","科多兽","莫高雷","雷霆崖"},ang={["class:Hunter"]="在金色平原上追踪像阿兰其亚这样孤独漫游的庞然大物，体现了牛头人追踪大师们代代相传的古老狩猎哲学。",["faction:Horde"]="放倒阿兰其亚为雷霆崖提供了必要的食物、皮革和材料，展现了维持初生部落生存的集体生存理念。",["race:Tauren"]="站在凯恩·血蹄面前领取阿兰其亚的角，是年轻Shu'halo的终极成人仪式，这证明了你的勇武既告慰了你的祖先，也荣耀了莫高雷的兽群。"},sec={{t="大酋长的衡量标准",b="到达雷霆崖标志着牛头人简单青春期的结束，但大酋长凯恩·血蹄并没有让年轻的猎手们止步不前。对于凯恩来说，在高耸的峭壁中赢得一席之地仅仅是承担起对联合牛头人部族责任的开始。他并不满足于派遣新兵去对付一些小害虫，而是要求他们证明真正的野外生存技巧：追踪并干净利落地猎杀莫高雷最著名的漫游野兽之一。"},{t="猎杀阿兰其亚",b="猎物是阿兰其亚，一头巨大的传奇科多兽，它的足迹横跨雷霆崖东北部的金色平原。要放倒这样的生物不仅仅需要蛮力；还需要在开阔的草原上耐心地潜行，并对平原上的巨人保持敬意。将阿兰其亚的角带回雷霆崖不仅能赢得个人荣耀，还能为城市提供物资，因为凯恩会立即派遣剥皮者和采集者，确保这头神圣野兽的任何部分都不会被浪费。"}},faq={{q="谁发布了这个任务？",a="大酋长凯恩·血蹄亲自在雷霆崖的高地顶端布置了这项任务。",al={"任务发布者","谁发布了大地母亲的仪式","凯恩的任务"}},{q="阿兰其亚是什么？",a="阿兰其亚是一头强大而著名的科多兽，它漫游在莫高雷的平原上。它巨大的角是猎人追踪能力和武艺的证明。",al={"阿兰其亚是谁","阿兰其亚是什么","阿兰其亚背景故事"}},{q="我在哪里可以找到阿兰其亚？",a="阿兰其亚通常在雷霆崖峭壁东北部的一条宽阔圆形路径上漫游，沿着草海平原顺时针缓慢绕行。",al={"阿兰其亚在哪里","阿兰其亚位置","阿兰其亚路径"}},{q="既然我已经完成了早期的仪式，为什么凯恩还要要求进行这次狩猎？",a="在牛头人文化中，获得初步的地位并不意味着责任的终结。凯恩教导说，为了维持部族的生存，力量、谦逊和狩猎技巧必须不断地展现出来。",al={"为什么要完成这个任务","为什么要猎杀阿兰其亚","仪式的意义"}},{q="取走角之后，阿兰其亚的尸体会怎样处理？",a="为了遵循牛头人尊重猎物的传统，凯恩会派遣一支采集队伍去回收这头倒下野兽的肉和皮，让这次狩猎的成果能够喂养并供给雷霆崖。",al={"阿兰其亚的肉","科多兽怎么了","尸体背景"}},{q="这和早期的起始仪式任务一样吗？",a="不。虽然纳拉其营地的早期试炼教会了新兵最基础的“大地母亲的仪式”，但雷霆崖的这项终极试炼是凯恩对你作为一名猎人持续价值的个人考验。",al={"大地母亲的仪式差异","哪一个仪式任务","纳拉其营地仪式"}}},fx={d7a516d7={q="阿兰其亚的角有什么用？",a="这只角是你成功狩猎的实物证明。牛头人传统十分尊崇追踪并猎杀强大野兽的本领。将阿兰其亚的角亲自呈给大酋长凯恩·血蹄，便能证明你拥有供养和保护族人的实力。",al={"阿兰其亚的角有什么用","为什么带阿兰其亚的角","阿兰其亚的角的用途"}},a7e696eb={q="凯恩·血蹄为什么派你去，而不派城防卫兵？",a="这场狩猎不是防务差事，也不是简单的收集物资，而是一项传统试炼。你或许已经通过最初的大地母亲仪式，抵达雷霆崖，但凯恩期望部族中的每位猎人都不断以丰功伟绩证明自己的价值与自立能力，而不是躺在过去的功绩上。",al={"为什么派我去","为什么不派卫兵去对付阿兰其亚","凯恩为什么需要我"}}},fp="24,265,21.386.0,22.362.0,21.97.0,18.127.0,27.110.0,78.161.0,57.165.0,50.188.0"}
P.entries["quest:777"] = {n="不祥的感觉",s="卢希恩·枪穗将5号齿轮交给你，让你送给鲁特维尔·沃拉图斯，然后他便躲进了掩体，并邀请你一起过去。",h="卢希恩·枪穗将5号齿轮交给你，让你送给鲁特维尔·沃拉图斯，然后他便躲进了掩体，并邀请你一起过去。",kw={"荒芜之地","5号齿轮","鲁特维尔·沃拉图斯","卢希恩·枪穗","镣铐","这将会很难"},sec={{t="掩体后",b="卢希恩交出齿轮，让你把它送给鲁特维尔·沃拉图斯。卢希恩会在掩体后等你，如果你愿意也可以加入他。当你到达仍在埋头摆弄镣铐的鲁特维尔身边时，他伸出一只手，手指不耐烦地摆动着，索要那个齿轮。"},{t="创造历史",b="鲁特维尔接过齿轮并称赞它非常完美，让你站远点，他要为创造历史做准备了。鲁特维尔继续疯狂地工作。"}},faq={{q="谁为鲁特维尔交出了齿轮？",a="卢希恩·枪穗给了你5号齿轮，让你带给鲁特维尔·沃拉图斯。",al={"谁给了齿轮","我在哪里能拿到5号齿轮","卢希恩 齿轮"}},{q="卢希恩去了哪里？",a="卢希恩去了掩体后，并说欢迎你也一起过去。",al={"为什么卢希恩要躲起来","卢希恩 掩体"}},{q="当你带来齿轮时，鲁特维尔正在做什么？",a="鲁特维尔正在摆弄一副镣铐，他头也不抬，不耐烦地伸出手索要齿轮。",al={"鲁特维尔在做什么","鲁特维尔 镣铐","鲁特维尔的进度"}}},fp="24,82,12.250.0,14.145.1,34.65.0,21.55.0,44.130.0"}
P.entries["quest:778"] = {n="不祥的感觉",s="鲁特维尔·沃拉图斯宣布枷锁已经完成，并召集Lucien、阿布和你一同见证一个强大的元素被召唤出来。",h="鲁特维尔·沃拉图斯宣布枷锁已经完成，并召集Lucien、阿布和你一同见证一个强大的元素被召唤出来。",kw={"荒芜之地","元素","法姆雷托守护者","鲁特维尔·沃拉图斯","卢森","阿布","元素束缚镣铐"},sec={{t="开创性的一天",b="鲁特维尔大喊着枷锁已经完成，时机已到，并召集Lucien和阿布以及你一同见证。鲁特维尔声称这些枷锁完美融合了炼金术、工程学和奥术力量，并打算在这被他称为开创性的一天里召唤出一个强大的元素。"},{t="召唤之后",b="结果并非鲁特维尔所料，在击败法姆雷托守护者后，他请求你把元素束缚镣铐找回来。事后，鲁特维尔虽然不清楚究竟哪里出了问题，但很庆幸手头有魔法可以将这种生物送回它原本的位面。"}},faq={{q="谁是鲁特维尔·沃拉图斯？",a="鲁特维尔·沃拉图斯是元素束缚镣铐的制造者，这种镣铐融合了炼金术、工程学和奥术。鲁希恩和阿布正与鲁特维尔一起待在荒芜之地。",al={"谁是鲁特维尔","鲁特维尔·沃拉图斯"}},{q="什么是元素束缚镣铐？",a="这是鲁特维尔刚刚完成的镣铐，融合了炼金术、工程学和奥术，用于他打算召唤的一个强大元素。",al={"什么是镣铐","元素束缚镣铐"}},{q="鲁特维尔召集了谁来见证？",a="鲁特维尔召集了鲁希恩和阿布，以及你，来见证这次召唤。",al={"谁是鲁希恩","谁是阿布"}},{q="在这一步之前发生了什么？",a="在此之前，你将5号齿轮交给了鲁特维尔。",al={"上一个任务","导致这一结果的原因"}}},fp="24,73,20.272.0,19.273.1,23.149.0,43.155.0,37.67.0,28.42.0"}
P.entries["quest:7781"] = {n="黑石之王",s="“黑石之王”是联盟的一项任务，在黑翼之巢内夺取黑龙奈法利安的断头后即可开启。将这件可怕的战利品交给暴风要塞的伯瓦尔·弗塔根公爵，宣告了黑石山主宰的覆灭。这是联盟近历史上最伟大的军事胜利之一。",h="“黑石之王”是联盟的一项任务，在黑翼之巢内夺取黑龙奈法利安的断头后即可开启。将这件可怕的战利品交给暴风要塞的伯瓦尔·弗塔根公爵，宣告了黑石山主宰的覆灭。这是联盟近历史上最伟大的军事胜利之一。",kw={"黑石山","黑翼之巢","伯瓦尔·弗塔根公爵","奈法利安的头颅","黑石之王","奈法利安","暴风要塞"},ang={["faction:Alliance"]="呈献黑龙奈法利安的头颅是联盟最顶级的军事成就之一，果断地粉碎了龙军团针对人类领土的阴谋。",["race:Human"]="暴风城遭受了无数来自黑石山的入侵和阴谋；看到它的主人被打败，让王国获得了期待已久的报复和解脱。"},sec={{t="胜利的丰碑",b="奈法利安，黑龙军团阴险的族群领袖，黑石塔上层的统治者，长期以来一直笼罩在周边人类王国的恐怖阴影之中。击杀他不仅仅是为了生存；这代表着彻底粉碎他扭曲的实验和阴谋。将他那颗巨大且伤痕累累的头颅带回暴风城，是“黑石之王”死于联盟最伟大的英雄之手的不争证明。"},{t="在暴风要塞觐见",b="这件令人毛骨悚然的战利品被直接带给了伯瓦尔·弗塔根公爵，他正在暴风要塞的王座大厅里治理王国。一颗巨龙的断头突然出现在王室法庭中，令围观者大为震惊，并引来即刻的敬畏。对于一个已经在内部政治斗争和外部威胁下苦苦挣扎的王国来说，这次胜利为王国带来了巨大的士气提振，并在联盟的历史中留下了不可磨灭的一笔。"}},faq={{q="“黑石之王”任务是关于什么的？",a="该任务始于冒险者在黑翼之巢夺取奈法利安的头颅。它指引胜利者将这座巨大的战利品带回暴风城，并代表王国将其呈献给伯瓦尔·弗塔根公爵。",al={"黑石之王任务","奈法利安的头颅任务 联盟","奈法利安的头颅 暴风城"}},{q="奈法利安是谁？",a="奈法利安是一条强大的黑龙，也是死亡之翼之子。他统治着黑石山内的黑翼之巢，指挥着黑石兽人，并进行邪恶的实验以创造多彩龙军团。",al={"奈法利安是谁","黑石之王","奈法利安背景故事"}},{q="伯瓦尔·弗塔根公爵是谁？",a="伯瓦尔·弗塔根公爵是一位圣骑士，在瓦里安·乌瑞恩国王缺席期间担任暴风城的摄政王，他在暴风要塞的王座大厅主持朝政，并照看年轻的安度因·乌瑞恩国王。",al={"伯瓦尔·弗塔根","伯瓦尔是谁","伯瓦尔公爵"}},{q="为什么要将这件战利品带到暴风要塞？",a="奈法利安在黑石山的统治对暴风城王国和整个南部大陆构成了致命威胁。将战利品直接带给王国的军事领导层，证实了这条巨龙已被消灭，并让整个王国能够围绕这一英勇壮举团结起来。",al={"为什么是暴风城","为什么要将头颅带到要塞","为什么是伯瓦尔"}},{q="将头颅交给伯瓦尔之后会发生什么？",a="伯瓦尔·弗塔根公爵对这一壮举感到震惊，宣称这一胜利将被永久载入史册。这直接导致了活动的后续阶段，即这颗头颅将被公开悬挂，供所有暴风城民众瞻仰。",al={"接下来会发生什么","黑石之王第二部分","奈法利安的头颅上交"}},{q="上交这颗头颅会影响整个城市吗？",a="是的。当奈法利安的头颅被送到首都并悬挂在城门之上时，它向所有在场的市民和士兵宣告了巨龙的覆灭，让暴风城的守卫者们充满了胜利的决心。",al={"城市增益","集结号令","奈法利安的头颅增益"}}},fx={["150c64a2"]={q="将奈法利安的头颅带到暴风城为何如此重要？",a="奈法利安是那条在黑石塔幕后策划种种威胁的黑龙，他操纵凡人的王国，就在暴风城门前打造怪物大军。将他的头颅交给伯瓦尔·弗塔根公爵，就是龙群的恐怖统治已被粉碎的铁证，让联盟能够举国庆祝并展示这场辉煌的胜利。",al={"为何将奈法利安的头颅带到暴风城","奈法利安的头颅任务的动机","为何运送奈法利安的头颅"}},["7e2ee731"]={q="为什么必须由你把头颅带到暴风城，而不是皇家卫兵？",a="是你和同伴一路杀穿黑翼之巢，亲手击倒了这位巨龙领主。作为击败他的勇士，将这件骇人的战利品带回暴风要塞是你应有的权利，也能让伯瓦尔·弗塔根公爵直接从真正斩杀巨兽的英雄口中得知消息。",al={"为何必须亲自运送奈法利安的头颅","为何不由皇家卫兵运送奈法利安的头颅","为何由自己运送奈法利安的战利品"}}},fp="21,264,21.326.0,26.287.0,42.168.0,16.211.0,33.197.0,45.214.0,45.152.0,48.190.0"}
P.entries["quest:7782"] = {n="黑石之王",s="这个任务代表了针对黑石山内敌对势力的最终战役的高潮。在向暴风要塞的杰斯·特瑞斯海军上将报告后，英雄们会被指引前往英雄谷，斯托布里奇元帅会在城门口协调举行一场公开的纪念仪式，让所有联盟成员都能看到。",h="这个任务代表了针对黑石山内敌对势力的最终战役的高潮。在向暴风要塞的杰斯·特瑞斯海军上将报告后，英雄们会被指引前往英雄谷，斯托布里奇元帅会在城门口协调举行一场公开的纪念仪式，让所有联盟成员都能看到。",kw={"黑石","屠龙者","奈法利安","屠龙者的咆哮","斯托布里奇","暴风城","英雄谷"},ang={["class:Warrior"]="屠龙者的咆哮所带来的巨大军事激励，鼓舞了前往保卫王国的战士们。",["faction:Alliance"]="在英雄谷展示奈法利安的头颅将所有联盟种族团结在一起，提醒着来自铁炉堡、达纳苏斯和诺莫瑞根的公民们，困扰着东部王国的黑暗势力是可以被粉碎的。",["race:Human"]="对于暴风城王国来说，击败黑石之王消除了边境上潜藏的龙族生存威胁。"},sec={{t="城市的凯旋",b="针对黑石氏族和黑龙军团子嗣的战役在公开的胜利展示中达到了高潮。在暴风要塞内展示过奈法利安的头颅后，伯瓦尔·弗塔根公爵会指引勇士们穿过城市前往英雄谷。在那里，斯托布里奇元帅正等待着接收这一血腥的战利品，并开启全城的庆祝活动。"},{t="集结联盟",b="当斯托布里奇元帅将奈法利安的头颅高悬于暴风城正门的巨大拱门上时，整座城市都感受到了震撼。这一展示伴随着屠龙者的咆哮，让城市守卫、到访显贵和普通公民们都备受鼓舞，因为他们知道死亡之翼的子嗣遭受了毁灭性的打击。"}},faq={{q="完成这个任务会发生什么？",a="斯托布里奇元帅会将奈法利安的头颅高悬在英雄谷的石门拱门上。这会在暴风城触发屠龙者的咆哮增益效果，强化所有友方玩家和守卫的战斗力。",al={"奈法利安头颅任务提交","斯托布里奇的作用","屠龙者的咆哮触发"}},{q="斯托布里奇元帅是谁？",a="斯托布里奇元帅是暴风城军队的一名高级军官，驻守在靠近暴风城入口的英雄谷。她负责组织重大的军事胜利的公开纪念活动，包括悬挂被击败的龙族威胁的头颅。",al={"斯托布里奇","斯托布里奇元帅"}},{q="为什么伯瓦尔·弗塔根公爵要把你送到这里？",a="在王座间确认奈法利安被击败后，伯瓦尔命令你将消息传达到城门，以便联盟军队能公开展示这一胜利，从而提振首都的士气。",al={"伯瓦尔","为什么要去英雄谷"}},{q="上交这个任务会影响全城吗？",a="是的。当斯托布里奇接过战利品时，宏大的宣言将在暴风城中回荡，屠龙者的咆哮增益效果会施加给城内所有的人。",al={"世界增益奈法利安","暴风城获得增益"}},{q="英雄谷在哪里？",a="英雄谷是进入暴风城的宏伟入口通道，两旁矗立着纪念在黑暗之门前线作战的第二次战争英雄的雕像。",al={"英雄谷位置","斯托布里奇在哪里"}},{q="谁是“黑石之王”？",a="黑石之王是黑龙奈法利安，他是死亡之翼之子，也是黑石山顶峰的统治者。",al={"谁是黑石之王","奈法利安身份"}}},fx={["3a42f3f3"]={q="伯瓦尔为什么派你去，而不是亲自前往？",a="是你和同伴勇闯黑翼之巢的高处，击败了奈法利安。作为胜利者，向暴风城的军事领袖献上巨龙头颅、让全城为之欢庆的荣耀，理应属于你。",al={"为何派遣自己","为何不由伯瓦尔前往","为何必须亲自运送头颅"}}},fp="21,261,16.338.1,21.299.0,42.221.1,33.240.0,49.213.1,40.162.1,38.164.0,32.124.2"}
P.entries["quest:7783"] = {n="黑石之王",s="此任务标志着针对黑翼之巢的突袭达到了高潮，任务要求勇士们将奈法利安的头颅带回奥格瑞玛。将这件骇人的战利品呈献给萨尔大酋长，证明了黑龙军团的子嗣已被击溃。这是部落对付其最阴险的敌人之一时，一个具有里程碑意义的伟大胜利时刻。",h="此任务标志着针对黑翼之巢的突袭达到了高潮，任务要求勇士们将奈法利安的头颅带回奥格瑞玛。将这件骇人的战利品呈献给萨尔大酋长，证明了黑龙军团的子嗣已被击溃。这是部落对付其最阴险的敌人之一时，一个具有里程碑意义的伟大胜利时刻。",kw={"黑石","黑翼之巢","死亡之翼","屠龙者","萨尔","奈法利安","奥格瑞玛","屠龙者的咆哮"},ang={["class:Warrior"]="将龙族领主的巨大头颅呈献给大酋长本人，是武勇名望的最高标志之一。",["faction:Horde"]="击杀奈法利安捍卫了部落的荣耀，并将黑石地区从一位奴役了叛变的黑铁部落的恶龙的魔爪中解放出来。",["race:Orc"]="对于兽人来说，将奈法利安的头颅呈献给萨尔，代表着对那只操纵雷德·黑手并奴役兽人氏族进行实验的野兽的复仇。"},sec={{t="毁灭的战利品",b="黑翼之巢的主谋、东部王国黑龙军团的领袖奈法利安终于倒下了。他那颗布满战斗伤痕的巨大头颅，正是他死亡的铁证。对于部落的勇士们来说，将这件举世瞩目的战利品从燃烧的黑石山顶峰运往杜隆塔尔，跨越无尽之海，这无疑是一种无上的荣耀。"},{t="大酋长的审判",b="这份战利品被直接呈献给了萨尔大酋长。萨尔比任何人都更了解黑石山内部的腐化，他曾将自己的人民从集中营中解放出来，带领他们摆脱了旧部落的恶魔嗜血诅咒。看到死亡之翼的儿子被击杀，证明了多年抗争的意义，并终结了这条黑龙对黑石氏族兽人们残酷的统治。"},{t="父亲的阴影",b="虽然奈法利安的死终结了黑龙军团扭曲的基因实验，但他的陨落并没有消除所有的危险。在看到这颗被斩下的龙头时，萨尔表示，得知自己儿子的死讯，死亡之翼本人必然会蠢蠢欲动。胜利固然真实，但这更严峻地提醒着人们，在世界表面之下还有更大的恐怖正在苏醒。"}},faq={{q="奈法利安是谁？",a="奈法利安是一条强大的黑龙，也是死亡之翼之子。他盘踞在黑石山顶端的黑翼之巢，进行着扭曲的实验以创造多彩龙军团，并操纵着各个凡人种族——特别是黑铁部落——为他效命。",al={"奈法利安背景故事","奈法利安是谁","黑龙领主"}},{q="为什么要把战利品交给萨尔？",a="萨尔是部落的大酋长。他带领兽人走出了集中营，摆脱了旧部落的恶魔嗜血诅咒，因此，奴役黑石氏族兽人和黑铁部落的恶龙已被击败的证明，理应交到他的手中。",al={"为什么是萨尔","谁接受头颅"}},{q="当龙头被上交时，奥格瑞玛会发生什么？",a="当奈法利安的头颅被带回并悬挂在奥格瑞玛时，全城都会举行庆典。整座首都会获得“屠龙者的咆哮”效果，提升附近所有部落成员的战斗能力。",al={"龙头增益","奥格瑞玛世界增益","屠龙者的咆哮"}},{q="这个任务有联盟对应的版本吗？",a="有的，联盟英雄们可以完成一个名为“黑石之王”的对应任务，将奈法利安的头颅交给位于暴风要塞的伯瓦尔·弗塔根公爵，从而为他们的城市带来同样的祝福。",al={"联盟版本","联盟对应任务"}},{q="为什么死亡之翼令人担忧？",a="死亡之翼是奈法利安的父亲，也是黑龙军团的首领。击败他的儿子并不能消除这位龙父所带来的危险。",al={"邪恶者蠢蠢欲动","邪恶者是谁"}},{q="龙头是从哪里来的？",a="该任务始于在黑翼之巢的顶峰击败奈法利安后，直接从他的尸体上拾取奈法利安的头颅。",al={"如何获得奈法利安的头颅","任务起始物品"}}},fp="21,141,16.296.0,23.303.0,21.263.1,16.248.0,38.235.0,53.181.0,44.129.0,27.147.0,30.106.0"}
P.entries["quest:7784"] = {n="黑石之王",s="此任务标志着将奈法利安的首级呈交给奥格瑞玛领袖的最后一步。在向萨尔证明了这条黑龙的死讯后，勇士们被指引前往力量谷寻找萨鲁法尔大王，在整个部落面前展示这一战利品。",h="此任务标志着将奈法利安的首级呈交给奥格瑞玛领袖的最后一步。在向萨尔证明了这条黑龙的死讯后，勇士们被指引前往力量谷寻找萨鲁法尔大王，在整个部落面前展示这一战利品。",kw={"黑翼之巢","萨尔","奈法利安的头颅","萨鲁法尔","奥格瑞玛","奈法利安","力量谷"},ang={["faction:Horde"]="公开展示奈法利安的首级巩固了萨尔的新秩序，并证明了重组后的部落对抗曾操纵黑石山兽人的黑龙的强大实力。",["race:Orc"]="对于兽人来说，见证那头曾奴役黑石氏族的巨龙的倒下，提供了一种深刻的宣泄，洗刷了笼罩在他们人民身上那段不光彩的阴影。"},sec={{t="部落的战利品",b="在黑翼之巢之巅击杀黑龙奈法利安后，他的首级被带到奥格瑞玛作为其战败的证据。大酋长萨尔确认了死亡之翼之子的陨落，随后指引获胜者前往力量谷寻找萨鲁法尔大王。在那里，这些恐怖的残骸将被准备好进行公开展示，以此作为对敌人的警告，也是对真正部落的集结号召。"},{t="宣示传承",b="奈法利安统治着黑石山的高处，让黑石兽人和黑铁部落臣服于他的意志。通过击败他并将他的首级高悬在力量谷，大酋长萨尔的部落给予了黑龙军团沉重的一击，而萨鲁法尔大王也号召整个奥格瑞玛一同享受屠龙者的咆哮。"}},faq={{q="这个任务的目的是什么？",a="这是击杀奈法利安后的总结性交接任务。在向萨尔证明战果后，你将向位于奥格瑞玛力量谷的萨鲁法尔大王报告，以获得荣誉并将这颗首级公开展示。",al={"这个任务有什么用","黑石山的领主任务交接","为什么要去找萨鲁法尔"}},{q="萨鲁法尔大王是谁？",a="萨鲁法尔大王是一位资深的兽人战士，也是部落最伟大的勇士之一，他驻扎在奥格瑞玛的力量谷，在那里他将接收首级并将其悬挂供所有人瞻仰。",al={"萨鲁法尔是谁","萨鲁法尔大王的角色"}},{q="为什么要把奈法利安的首级展示出来？",a="悬挂这头黑龙的首级无可辩驳地证明了黑石山的主人已经倒下。它增强了奥格瑞玛守卫者的士气，并且城中的每个人都会获得屠龙者的咆哮效果。",al={"为什么要悬挂奈法利安的首级","奈法利安首级展示奥格瑞玛"}},{q="奈法利安是谁？",a="奈法利安是一头伟大的黑龙，也是死亡之翼之子。在黑石山之巅的黑翼之巢中，他指挥着黑石兽人和黑铁部落，并培育了多彩龙军团。",al={"奈法利安是谁","奈法利安背景故事"}},{q="萨鲁法尔大王在哪里？",a="萨鲁法尔伫立在力量谷，那是奥格瑞玛的中心入口区域。",al={"萨鲁法尔在哪里","萨鲁法尔位置"}},{q="萨尔在其中扮演什么角色？",a="大酋长萨尔首先会接收首级。一旦他确认了奈法利安的死讯，他会派遣你去找萨鲁法尔，将这一战利品正式悬挂。",al={"为什么是萨尔","萨尔的参与"}}},fp="21,219,22.320.0,19.328.1,34.182.0,30.203.0,38.203.0,17.190.0,40.77.0,35.148.0"}
P.entries["quest:7792"] = {n="捐献毛料",s="达纳苏斯正在接受毛料捐赠，以补充库存。您的捐赠将让达纳苏斯充分认可您的慷慨之举。",h="达纳苏斯正在接受毛料捐赠，以补充库存。您的捐赠将让达纳苏斯充分认可您的慷慨之举。",kw={"达纳苏斯","捐赠","认可","库存","毛料"},sec={{t="毛料储备",b="达纳苏斯正在接受毛料捐赠。城中需要您捐赠六十块毛料，其余库存则希望从其他地方募集。您的捐赠将让达纳苏斯充分认可您的慷慨之举。"}},faq={{q="达纳苏斯需要什么？",a="达纳苏斯正在接受毛料捐赠。",al={"捐赠毛料","达纳苏斯需要什么布料"}},{q="我需要捐赠多少毛料？",a="需要捐赠六十块毛料。",al={"需要多少毛料","六十块毛料"}},{q="达纳苏斯为什么要收集毛料？",a="达纳苏斯正在收集毛料，以补充库存。",al={"为何需要毛料","募集毛料"}},{q="捐赠毛料能得到什么？",a="捐赠六十块毛料，达纳苏斯将充分认可您的慷慨之举。",al={"捐赠毛料的认可","捐赠毛料的奖励"}}},fp="18,122,11.182.0,25.49.0,34.46.0,33.56.0,32.88.0"}
P.entries["quest:78"] = {n="斯塔文的传说",s="这个差事标志着揭开斯塔文·密斯特曼托历史的一个转折点，它将调查者从艾尔文森林带回了阴影笼罩的夜色镇。在治安官哈迦德对自己服役岁月的记忆指引下，你带着找到的一张日记书页前往血鸦旅店，交给旅店老板斯密茨，以辨认那令人不寒而栗的笔迹。",h="这个差事标志着揭开斯塔文·密斯特曼托历史的一个转折点，它将调查者从艾尔文森林带回了阴影笼罩的夜色镇。在治安官哈迦德对自己服役岁月的记忆指引下，你带着找到的一张日记书页前往血鸦旅店，交给旅店老板斯密茨，以辨认那令人不寒而栗...",kw={"夜色镇","暮色森林","艾尔文","日记","治安官哈迦德","密斯特曼托","血鸦旅店","斯塔文","旅店老板斯密茨"},ang={["faction:Alliance"]="这个任务突显了王国前守卫者之间的深厚情谊，将退役的暴风城卫兵与整个暴风城王国的社区守护者联系在了一起。",["race:Human"]="这一步骤揭示了潜藏在人类聚居地中的阴暗记忆，表明艾尔文森林和夜色镇过去的悲剧并未真正尘封。"},sec={{t="来自元帅的线索",b="在艾尔文森林的治安官哈迦德的箱子里找到一张风化、破损的日记书页后，这位退役的指挥官因为视力下降而无法辨认上面褪色的字迹。意识到线索指向河对岸，哈迦德回想起了他曾经指挥暴风城卫队的往事，并记得自己曾在夜色镇的血鸦旅店度过夜晚。他指引你去找旅店老板斯密茨，这位长期在此经营的酒保已成了当地历史和传闻的非官方守护者。"},{t="回到血鸦旅店",b="穿过暮色森林阴沉的树林回到镇上，你将那张褪色的书页交给了柜台后的斯密茨。听到老熟人哈迦德的名字，斯密茨的态度立刻缓和了下来，尽管他为这位老兵日益衰弱的健康感到惋惜。当这位旅店老板看到那张羊皮纸时，他原本随和的神态瞬间转为惊恐：他毫无疑问地认出了这独特的笔迹，这也让调查进一步揭开了斯塔文疯狂背后的恐怖真相。"}},faq={{q="为什么治安官哈迦德要我回到夜色镇？",a="治安官哈迦德年事已高，几近失明，这让他无法亲自查看找到的日记书页。他记得当他在暴风城卫队服役时，夜色镇血鸦旅店的旅店老板斯密茨是当地知识和历史方面的专家，这使他成为辨认笔迹的最佳人选。",al={"为什么要前往夜色镇","哈迦德与夜色镇","为什么要找斯密茨"}},{q="旅店老板斯密茨在哪里？",a="旅店老板斯密茨在血鸦旅店内经营酒吧，该酒馆位于暮色森林的夜色镇东侧。",al={"斯密茨在哪里","斯密茨的位置","血鸦旅店的位置"}},{q="你带给旅店老板斯密茨什么物品？",a="你带来的是一张褪色的日记书页，这是斯塔文·密斯特曼托遗失日记中的一段，此前是在治安官哈迦德的箱子里找到的。",al={"什么物品","褪色的日记书页","斯塔文日记书页"}},{q="旅店老板斯密茨认出笔迹了吗？",a="是的。当斯密茨看过那张褪色的书页时，他立刻惊恐地认出了笔迹，这种确认也为寻找斯塔文提供了下一条线索。",al={"斯密茨是否认识字迹","斯密茨对日记的反应"}},{q="斯密茨怎么认识治安官哈迦德的？",a="多年前，当哈迦德率领暴风城卫队巡逻队进入暮色森林，并经常光顾血鸦旅店喝酒时，斯密茨曾接待过他。",al={"斯密茨与哈迦德的关系","斯密茨如何认识哈迦德"}},{q="寻找斯塔文的下一步是什么？",a="把那张褪色的日记书页带给血鸦旅店的斯密茨，并跟随他提供的线索继续行动。",al={"接下来做什么","斯塔文任务下一步","斯塔文任务线后续"}}},fp="21,112,23.409.0,27.374.1,51.223.0,35.110.0,44.133.0,49.131.0,37.136.0,42.99.0"}
P.entries["quest:780"] = {n="斗猪",s="“战斗野猪”是纳拉其营地的格鲁尔·鹰风发布的一项成人礼狩猎任务。年轻的牛头人被委派去猎杀刺刃峡谷中那些凶猛的战训野猪，以保卫部落领地并为营地的幼年成员提供食物。",h="“战斗野猪”是纳拉其营地的格鲁尔·鹰风发布的一项成人礼狩猎任务。年轻的牛头人被委派去猎杀刺刃峡谷中那些凶猛的战训野猪，以保卫部落领地并为营地的幼年成员提供食物。",kw={"战斗野猪","刺刃峡谷","刺背","纳拉其营地","格鲁尔·鹰风","莫高雷","野猪人","红云台地"},ang={["class:Hunter"]="面对这些被刺背野猪人训练出恶意的野兽，年轻的猎人们得以认清自然野生动物与被扭曲为战争武器的动物之间的巨大区别。",["profession:Cooking"]="对侧腹肉和猪鼻的需求凸显了牛头人基础的饮食理念：粗糙、坚韧的肉总是可以通过烹煮转化为浓郁、滋补的炖菜。",["race:Tauren"]="这项任务体现了牛头人维护大地母亲领土的平衡，同时也确保了战斗中获得的任何东西都不会被浪费，将敌人的战兽转化为营地幼崽的养分。"},sec={{t="边境威胁",b="红云台地的东侧是刺刃峡谷，这是一道布满荆棘的伤疤，被刺背野猪人所占据。随着舒哈鲁与野猪人之间的紧张局势升级为公开的战争，刺背野猪人训练了凶猛的战斗野猪来试探牛头人的边界，并恐吓他们传统的狩猎场。如果不加遏制，这些好斗的野兽不仅会威胁到兽径，还会威胁到纳拉其营地本身的安全。"},{t="供养部落",b="对于牛头人来说，狩猎既是防御的需要，也是维持社区生存的手段。格鲁尔·鹰风指示新手们带回被杀死的战斗野猪的猪鼻和侧腹肉。即使是经由野猪人之手训练出来的野兽也不会被浪费；它们的肉和软骨会被采集起来，为部落的年轻人烹制浓郁的炖肉，将野猪人的武器转化为哺育下一代牛头人守卫者的养分。"}},faq={{q="为什么战斗野猪会袭击台地？",a="这些战斗野猪是由栖息在刺刃峡谷的刺背野猪人刻意培育和训练出来的。野猪人利用它们作为冲击性动物，骚扰牛头人并侵占红云台地的部落狩猎场。",al={"战斗野猪的侵略性","为什么战斗野猪具有敌意","战斗野猪的袭击"}},{q="是谁派遣玩家执行这次狩猎任务的？",a="驻扎在纳拉其营地的杰出猎人兼长者格鲁尔·鹰风，负责指导年轻牛头人完成早期训练的最终试炼。",al={"战斗野猪任务发布者","谁发布了战斗野猪任务","格鲁尔·鹰风的角色"}},{q="在哪里可以找到这些战斗野猪？",a="它们游荡在刺刃峡谷附近及其内部，这是一个位于纳拉其营地以东、红云台地东缘的崎岖峡谷。",al={"战斗野猪位置","战斗野猪在哪里","刺刃峡谷的野猪"}},{q="从野猪身上收集来的肉会被用来做什么？",a="战斗野猪的侧腹肉和猪鼻会被带回纳拉其营地，炖煮成供给营地孩童和长者的炖肉，这体现了牛头人利用狩猎所得的传统。",al={"战斗野猪侧腹肉的用途","野猪肉有什么用","野猪肉炖菜"}},{q="这项任务在当地的野猪人冲突中起到了什么作用？",a="它作为牛头人与刺背部落之间公开战争的早期引子。猎杀它们的战兽可以减少骚扰牛头人狩猎场的野兽数量，并向刺刃峡谷的刺背野猪人发出明确的信号。",al={"牛头人与野猪人的战争","刺背部族冲突","野猪人背景知识"}},{q="“战斗野猪”的前置任务是什么？",a="它的前置任务是“狩猎继续”，那是格鲁尔·鹰风发布的一项早期任务，重点是了解红云台地的狩猎场。",al={"战斗野猪前置条件","战斗野猪之前的任务","狩猎继续任务链"}}},fx={b70ec92c={q="格鲁尔·鹰风为什么要杀死战斗野猪？",a="战斗野猪从刺刃峡谷一路闯出，侵入红云部族祖传的狩猎场。它们由野猪人荆背氏族培育并训练得凶残无比，日益增长的敌意直接威胁纳拉其营地。格鲁尔·鹰风打算削减它们的数量，给荆背氏族一个明确的警告，同时把猎获的野猪肉供给部族的年轻成员。",al={"格鲁尔·鹰风为什么要杀死战斗野猪","格鲁尔·鹰风对付战斗野猪的目的","为什么要在莫高雷杀死战斗野猪"}},["58a19c3f"]={q="什么是战斗野猪？",a="战斗野猪是由刺刃峡谷的野猪人荆背氏族饲养和训练的凶猛野兽。与红云台地本土的野生山地狮和草原徘徊者不同，这些野猪经过刻意训练，专为战争与杀戮而生，是荆背氏族对抗牛头人的活体武器。",al={"战斗野猪是什么人","什么是战斗野猪","战斗野猪的背景"}}},fp="15,95,22.329.0,17.340.0,43.182.0,31.117.0,32.113.0,50.140.0,57.224.0,36.114.0"}
P.entries["quest:7802"] = {n="A Donation of Wool",s="铁炉堡正在接受毛料捐赠，以补充储备。捐赠六十块毛料，即可获得全额嘉奖，表彰你的慷慨。",h="铁炉堡正在接受毛料捐赠，以补充储备。捐赠六十块毛料，即可获得全额嘉奖，表彰你的慷慨。",kw={"捐赠","铁炉堡","嘉奖","六十块","储备","毛料"},ang={["faction:Alliance"]="作为一名联盟旅人，捐赠毛料便能获得铁炉堡的嘉奖。"},sec={{t="毛料储备",b="铁炉堡需要你捐赠六十块毛料。它的储备只需要你提供这么多，而其他人预计会捐赠足够的毛料来支持此次募集。"}},faq={{q="铁炉堡需要我捐赠多少毛料？",a="铁炉堡向你征集六十块毛料。",al={"毛料捐赠数量","需要多少毛料","六十块毛料"}},{q="捐赠毛料能得到什么？",a="捐赠六十块毛料，铁炉堡就会全额嘉奖你的慷慨。",al={"毛料捐赠奖励","捐赠毛料有什么用","铁炉堡嘉奖"}},{q="铁炉堡为什么要募集毛料？",a="铁炉堡正在募集毛料，以补充储备。",al={"毛料募集","为何捐赠毛料","铁炉堡毛料"}}},fp="18,122,11.164.0,42.50.0,32.98.0,33.56.0"}
P.entries["quest:7807"] = {n="捐献毛料",s="“捐献毛料”是由诺莫瑞根流亡者发起的一项物资征集活动，旨在收集基本的纺织物资。由于被迫离开了他们的科技之城，这些流亡的侏儒需要来自世界各地的慷慨冒险者提供六十块毛料，以维持其社区的运转。为这项活动做出贡献将使你获得侏儒难民的正式认可。",h="“捐献毛料”是由诺莫瑞根流亡者发起的一项物资征集活动，旨在收集基本的纺织物资。由于被迫离开了他们的科技之城，这些流亡的侏儒需要来自世界各地的慷慨冒险者提供六十块毛料，以维持其社区的运转。为这项活动做出贡献将使你获得侏儒难...",kw={"布料征集","捐献毛料","侏儒","诺莫瑞根","诺莫瑞根流亡者","纺织品","毛料"},ang={["faction:Alliance"]="向流亡的侏儒捐献原材料可以加强联盟的团结，并帮助维持这一从家园山脉中流离失所的重要盟友。",["profession:Tailoring"]="收集或编织毛料的裁缝拥有充足的纺织品储备，这正是难民群体制作基本衣物和生活用品所迫切需要的。",["race:Gnome"]="对于流亡的侏儒来说，收集毛料有助于为你的流离失所的族人提供补给，帮助他们在诺莫瑞根之外努力生存和重建。"},sec={{t="流离失所者的需求",b="在诺莫瑞根沦陷于穴居人入侵和放射性污染之后，幸存的侏儒被迫离开了他们的高科技大都市。作为由铁炉堡的矮人亲戚们主要收留的难民，诺莫瑞根流亡者面临着严峻的后勤压力。常规的物资征集活动（如收集布料等基本物资）对于在祖居地之外艰难求生的他们来说，是保证族人有衣穿、有补给、能维持组织运转的关键。"},{t="纺织品征集",b="为了避免给个人的捐赠者造成过大负担，征集活动的组织者要求每位志愿者提供恰好六十块毛料。通过汇集来自世界各地的微薄捐助，流亡者们能够积攒起制造寝具、绷带和衣物所需的大量纺织品，而不会给任何单一的供应者带来无法承受的压力。作为回报，侏儒们会向任何愿意帮助他们恢复重建的人提供正式的认可。"}},faq={{q="为什么诺莫瑞根流亡者需要毛料？",a="诺莫瑞根流亡者正在进行一场资源征集活动，以建立基础的纺织品储备。在被赶出家园城市之后，他们的族人需要毛料这样的重要物资来维持难民群体的生活以及日常运作。",al={"为什么需要毛料","毛料的用途","毛料捐赠目的"}},{q="需要多少毛料？",a="这项捐赠活动要求每位捐赠者一次性贡献六十块毛料。组织者计算认为，从世界各地的个人那里获得这一特定数量的物资，将足以满足他们的整体供应需求。",al={"需要多少毛料","捐赠数量","所需毛料"}},{q="是谁在组织这场捐赠活动？",a="诺莫瑞根流亡者的代表负责协调纺织品的收集工作，并代表目前在盟友庇护下的流离失所的侏儒群体接收捐赠。",al={"谁在接收捐赠","谁在接受毛料","捐赠接收者"}},{q="你可以多次捐献毛料吗？",a="这项征集活动限制每位捐赠者只能贡献一次，即六十块毛料。流亡者们表示，他们目前的库存只需要你提供这一固定数量，因为他们依靠世界各地更广泛的捐赠者群体来完成配额。",al={"可以再次捐赠吗","是否可重复","更多毛料捐赠"}},{q="诺莫瑞根流亡者提供什么样的认可？",a="提供六十块毛料将赢得诺莫瑞根流亡者的充分认可和感激，证明你在危机时期对他们这些流离失所的人民所展现出的忠诚与帮助。",al={"诺莫瑞根流亡者声望","侏儒声望","流亡者认可"}},{q="为什么侏儒目前处于流亡状态？",a="在一场灾难性的事故和穴居人入侵之后，侏儒们被迫逃离了他们的地下家园诺莫瑞根，这使他们不得不依赖临时营地、盟友的援助和物资征集活动，过着难民般的生活。",al={"为什么侏儒会流亡","诺莫瑞根在哪里","侏儒难民危机"}}},fp="18,211,26.391.0,17.324.0,45.176.0,30.151.0,38.142.0,41.163.0,48.163.0,38.192.0"}
P.entries["quest:78091"] = {n="Earning Your Salt",s="暴风城的Ursula Deline答应替你研究一颗宝珠，但要求你为她办件事作为回报。想知道她的发现，你必须前往赤脊山，从黑石氏族手中夺取经过处理的召唤盐。",h="暴风城的Ursula Deline答应替你研究一颗宝珠，但要求你为她办件事作为回报。想知道她的发现，你必须前往赤脊山，从黑石氏族手中夺取经过处理的召唤盐。",kw={"黑石氏族","黑石召唤者","earning your salt","赤脊山","暴风城","召唤者的盐","ursula deline"},ang={["class:Warlock"]="Ursula Deline答应替你研究一颗宝珠，但你得先带给她黑石召唤者用来增强仪式的处理盐。"},sec={{t="Ritual Salt",b="盘踞在赤脊山的黑石召唤者携带着经过特殊处理的盐，用以增强他们的黑暗仪式。你得先从那些营地弄到一批盐，Ursula Deline才肯替你检查宝珠。她答应，等你带着盐回到暴风城后，就会告诉你研究所得。"}},faq={{q="Ursula Deline是谁？",a="Ursula Deline是暴风城的一名研究员。她答应替你检查宝珠，条件是你为她带来仪式材料。",al={"谁想要召唤者的盐","谁发布了earning your salt","ursula deline是谁"}},{q="Ursula为何需要召唤盐？",a="黑石氏族的术士用经过特殊处理的盐增强召唤仪式。Ursula要求你先带回一批盐，才会分享她的研究成果。",al={"ursula为何想要盐","召唤者的盐有什么用","为什么要收集盐"}},{q="在哪里能找到召唤盐？",a="赤脊山的黑石召唤者身上带着这种盐。",al={"哪里能找到召唤者的盐","黑石召唤者在哪里","去哪里弄盐"}},{q="Ursula会给什么回报？",a="Ursula答应研究一颗宝珠，并在你带回盐后分享研究所得。",al={"ursula承诺了什么","ursula研究什么","能得到什么回报"}}},fp="17,233,11.314.0,21.114.0,37.145.0,35.82.0,33.101.0"}
P.entries["quest:781"] = {n="纳拉其营地的危机",s="“纳拉其营地的袭击”是在刺刃峡谷的野猪人巢穴中发现的一项重要发现。一张沾满泥土的地图显示，咄咄逼人的刺背部族正在策划一场针对纳拉其营地的有组织围攻。将这些计划送交给鹰风酋长，便能及时让纳拉其营地发出预警，并从血蹄村召唤援军。",h="“纳拉其营地的袭击”是在刺刃峡谷的野猪人巢穴中发现的一项重要发现。一张沾满泥土的地图显示，咄咄逼人的刺背部族正在策划一场针对纳拉其营地的有组织围攻。将这些计划送交给鹰风酋长，便能及时让纳拉其营地发出预警，并从血蹄村召唤援...",kw={"进攻计划","血蹄村","刺刃峡谷","刺背野猪人","纳拉其营地","鹰风酋长","沾满泥土的地图","野猪人","红云台地"},ang={["faction:Horde"]="保住牛头人在莫高雷的立足点，确保了部落在卡利姆多中部保有至关重要的南方据点。",["race:Tauren"]="对于在台地上进行最初试炼的年轻牛头人勇士来说，截获这张地图证明了你对部族的忠诚，也保护了你的族人免受突然的屠杀。"},sec={{t="荆棘丛中的阴谋",b="当年轻的牛头人冒险者在刺刃峡谷的洞穴深处侦察时，他们会在岩石地面上发现一张粗糙、沾满泥土的地图。仔细检查后，羊皮纸上揭示了刺背野猪人精心制定的战术标记。野猪人并非在进行零星的突袭，而是在协调一场针对纳拉其营地的全面、持久的围攻。"},{t="警告酋长",b="将袭击计划带回纳拉其营地，为鹰风酋长提供了至关重要的情报。意识到防守薄弱的营地及其年轻学徒所面临的严峻威胁，鹰风酋长准备向血蹄村发出求援信号。这张被截获的地图将一场可能导致灾难的伏击转变成了有准备的防御战。"}},faq={{q="在哪里可以找到刺背野猪人的进攻计划？",a="这些计划源自一张沾满泥土的地图，位于刺刃峡谷的一个洞穴内，就在锐牙酋长的棚屋右侧的小路上去。",al={"地图位置","沾满泥土的地图在哪里","寻找进攻计划"}},{q="谁会接收刺背野猪人的进攻计划？",a="这些计划必须直接送交给纳拉其营地中心的鹰风酋长。",al={"交任务对象","谁接收地图","任务终结者"}},{q="为什么刺背野猪人要袭击纳拉其营地？",a="刺背部族试图将牛头人赶出红云台地，并夺回莫高雷的狩猎场和圣地，据为己有。",al={"为什么袭击纳拉其营地","野猪人在莫高雷的动机","刺背围攻"}},{q="鹰风酋长计划如何应对这场围攻？",a="有了截获地图所提供的提前预警，鹰风酋长打算召唤血蹄村的族人前来增援台地，以击退敌人的进攻。",al={"鹰风酋长的计划","纳拉其营地的援军"}},{q="这个任务在拾取地图之前需要与任何人交谈吗？",a="不需要。任务直接由刺刃峡谷洞穴地面上的沾满泥土的地图触发，拾取后即转变为战斗计划。",al={"任务起始物品","沾满泥土的地图起始任务","如何开始纳拉其营地的袭击"}},{q="如果纳拉其营地陷落会怎样？",a="纳拉其营地是年轻牛头人勇士进行试炼的主要避难所；失去它将危及红云台地的安全，并切断莫高雷的精神修行之地。",al={"纳拉其营地的利害关系","为什么要保卫纳拉其"}}},fp="22,166,22.212.0,21.257.0,45.146.0,42.83.0,56.143.0,50.133.0,69.125.0,35.180.0"}
P.entries["quest:7810"] = {n="竞技场高手",s="想要精通竞技场，仅仅做到这些就够了吗？古拉巴什竞技场活动的幕后黑手，海盗小个子约翰·米斯瑞尔或许知道答案，你可以在荆棘谷竞技场找到他。",h="想要精通竞技场，仅仅做到这些就够了吗？古拉巴什竞技场活动的幕后黑手，海盗小个子约翰·米斯瑞尔或许知道答案，你可以在荆棘谷竞技场找到他。",kw={"竞技场大师","古拉巴什","海盗","小个子约翰·米斯瑞尔","荆棘谷竞技场","荆棘谷"},sec={{t="寻找海盗",b="无论你在古拉巴什收获了什么，要真正精通竞技场似乎还需要付出更多。组织那里的竞赛的海盗小个子约翰·米斯瑞尔可能知道详情。去荆棘谷竞技场里面找他吧。"},{t="小个子约翰的话",b="小个子约翰·米斯瑞尔告诉你，仅仅一个饰品还不足以让你成为竞技场大师。他说，现在才是真正考验你实力的时候。"}},faq={{q="我需要和谁交谈？",a="小个子约翰·米斯瑞尔，古拉巴什活动的幕后海盗。",al={"我要和谁谈","竞技场大师任务提交","去哪里"}},{q="小个子约翰·米斯瑞尔在哪里？",a="在荆棘谷的荆棘谷竞技场，古拉巴什。",al={"古拉巴什位置","荆棘谷竞技场在哪里","竞技场位置"}},{q="关于成为竞技场大师有什么提示吗？",a="只是暗示说，精通竞技场似乎需要比你目前做得更多，而且古拉巴什活动的幕后海盗可能知道内情。",al={"如何成为竞技场大师","我成为竞技场大师了吗"}}},fp="12,98,18.190.0,17.123.1,28.69.0,28.86.0,47.158.0"}
P.entries["quest:78124"] = {n="Nar'thalas Almanac",s="Nar'thalas Almanac是一本珍稀的学术手稿，记载了古老的魔法研究，档案管理员们一直在寻找它以充实图书馆的藏书。回收这卷书册能将失传的奥术知识交到可靠的人手中，让研究者们能够钻研其中被遗忘的见解。",h="Nar'thalas Almanac是一本珍稀的学术手稿，记载了古老的魔法研究，档案管理员们一直在寻找它以充实图书馆的藏书。回收这卷书册能将失传的奥术知识交到可靠的人手中，让研究者们能够钻研其中被遗忘的见解。",kw={"年鉴","奥术","书","图书馆","魔法作品","纳萨拉斯","书籍"},ang={["class:Mage"]="法师们了解研究古代奥术传统的回收文本所具有的巨大学术价值，因此对图书馆魔法藏书的贡献尤为重要。",["faction:Alliance"]="在联盟档案馆工作的学者和馆长们依靠进取的冒险者去搜寻珍稀手稿，并扩充王国收集的知识。",["race:NightElf"]="Nar'thalas曾是大分裂摧毁旧世界之前卡多雷奥术学术的古代中心，这使得一本带有其名字的年鉴成为了与古代暗夜精灵历史之间深刻的联系。"},sec={{t="古代研究的遗物",b="Nar'thalas Almanac是一本珍稀的奥术研究书籍，源自大分裂前暗夜精灵学术的古老传统。对于大型档案馆的管理员来说，保护这样的文本能使数百年的知识免于湮没，并为书架增添一份至关重要的历史资料。发掘这些长期被忽视的著作的冒险者，有助于架起连接被遗忘的古代与现代学术认知的桥梁。"},{t="扩充档案馆",b="档案管理员和研究人员不断在艾泽拉斯各地搜寻失落的论文、实地笔记和编年史。将Nar'thalas Almanac带入专门的图书馆，可以确保它得到妥善保管、编目和研究，而不是任其在废墟中腐烂或落入漫不经心之人手中。每一本被挽救的书册都能为学者提供关于过去时代奥术艺术的新见解。"}},faq={{q="什么是纳萨拉斯年鉴？",a="纳萨拉斯年鉴是一份古代魔法学术手稿，馆长们通过搜集它来充实图书馆的历史档案。回收此类珍稀著作的冒险者将其送交学术机构保管，以便将其中的见解编目保存。",al={"什么是纳萨拉斯年鉴","纳萨拉斯年鉴任务","年鉴信息"}},{q="谁在收集纳萨拉斯年鉴？",a="这本年鉴是献给那些对古代魔法文献和历史档案感兴趣的图书馆学者的。这些馆长积极寻求新增藏品，以扩充他们对世界奥术遗产的共同机构知识。",al={"谁想要年鉴","年鉴去向","年鉴上交"}},{q="纳萨拉斯这个名字是指什么？",a="纳萨拉斯是卡多雷在大分裂前的一个学习和魔法研究中心。与这个名字相关的现存文本代表了分裂前奥术和精灵知识的残篇。",al={"什么是纳萨拉斯","纳萨拉斯传说","纳萨拉斯在哪里"}},{q="为什么要为图书馆收集魔法文本？",a="许多历史记录和魔法论文在艾泽拉斯各地流离失所、遗失或埋没在废墟中。学者们依靠回收的书稿来加深对奥术流动的理解，并保护脆弱的记录免于彻底消失。",al={"为什么要收集魔法作品","图书馆目的","书的重要性"}},{q="可以将其他魔法著作带到图书馆吗？",a="学者们欢迎任何能阐明奥术理论和古代历史的回收论文、大部头或遗失的手稿，并不断寻求增加馆藏以充实书架。",al={"更多魔法书籍","其他书籍","更多文本"}},{q="纳萨拉斯年鉴处理起来危险吗？",a="这本年鉴是一份研究记录汇编，而非不稳定的禁忌神器。它主要作为历史学家和研究历史魔法的从业者们的一份珍贵参考资料。",al={"年鉴危险吗","年鉴有黑魔法吗","阅读安全吗"}}},fp="18,153,24.370.0,22.342.0,31.226.0,41.195.0,39.191.0,54.236.0,50.157.0,46.162.0"}
P.entries["quest:78127"] = {n="The Dalaran Digest",s="一位图书管理员请你为藏书增添魔法典籍。每本书都会让图书馆的知识更加丰富。",h="一位图书管理员请你为藏书增添魔法典籍。每本书都会让图书馆的知识更加丰富。",kw={"藏书","达拉然文摘","知识","图书管理员","图书馆","魔法典籍"},sec={{t="藏书",b="图书管理员欢迎能让图书馆受益的魔法典籍。你带来一本书，将它收入藏书，你的努力也让知识不断增长。"}},faq={{q="图书管理员想要什么？",a="图书管理员请你带来可能有益于藏书的魔法典籍。",al={"该带什么","图书馆书籍","魔法典籍"}},{q="我该把书带到哪里？",a="把书交给请你将其收入藏书的图书管理员。",al={"图书管理员在哪里","图书馆位置"}},{q="图书管理员为何收集魔法典籍？",a="你的贡献让藏书中的知识不断增长。",al={"为何收集书籍","图书馆的用途"}}},fp="18,106,14.135.0,29.78.0,26.74.0,46.58.0"}
P.entries["quest:78142"] = {n="Bewitchments and Glamours",s="铁炉堡图书馆正在寻找魔法典籍，以充实馆藏。你可以带来可能对图书馆有益的书籍，帮助馆藏不断丰富。",h="铁炉堡图书馆正在寻找魔法典籍，以充实馆藏。你可以带来可能对图书馆有益的书籍，帮助馆藏不断丰富。",kw={"魔法与魅惑","书籍","馆藏","铁炉堡","图书馆","魔法典籍"},sec={{t="不断丰富的馆藏",b="图书馆请你带来可能对馆藏有益的魔法典籍。每一部新增典籍都会拓展馆员的知识。"}},faq={{q="图书馆想要什么？",a="图书馆正在寻找可能对馆藏有益的魔法典籍。",al={"他们想要什么","图书馆藏书","魔法典籍"}},{q="我该把魔法典籍送到哪里？",a="把它们送到铁炉堡的图书馆。",al={"把书送到哪里","图书馆在哪里","铁炉堡图书馆"}},{q="他们为什么要收集魔法典籍？",a="图书馆表示，这些典籍能拓展他们的知识。",al={"为何收集魔法书籍","馆藏有何用途"}}},fp="25,168,20.103.0,27.64.0,35.52.0,38.53.0"}
P.entries["quest:78143"] = {n="Secrets of the Dreamers",s="“Secrets of the Dreamers”任务要求冒险者寻回稀有的魔法文献，以充实学术档案。通过上交这些发现的论著，探索者能帮助图书馆的学者扩充他们的古代知识收藏。",h="“Secrets of the Dreamers”任务要求冒险者寻回稀有的魔法文献，以充实学术档案。通过上交这些发现的论著，探索者能帮助图书馆的学者扩充他们的古代知识收藏。",kw={"奥术","梦境者","图书馆","魔法著作","学者","梦境行者的秘密","典籍"},ang={["class:Druid"]="鉴于对“梦境者”的提及，与自然魔法和翡翠梦境相关的著作对于塞纳里奥技艺的修行者来说具有深远的意义。",["class:Mage"]="学术奥术师非常适合在艾泽拉斯各地搜寻晦涩的典籍和魔法文本，以充实机构档案库。",["faction:Alliance"]="联盟的学者，特别是那些保管大型知识库的学者，依赖于勇敢的勇士从危险的地方寻回失落的知识。"},sec={{t="寻回被遗忘的知识",b="“Secrets of the Dreamers”任务涉及从各地寻回稀有的魔法文本和历史论著。致力于记录艾泽拉斯奥术奥秘的学者们依靠四处游历的冒险者来发掘被遗忘的著作，并将它们安全带回档案库。这些收集工作确保了珍贵的知识不会在古代废墟或私人收藏中被埋没，而是能得到研究和保存，以造福后代。"},{t="扩充档案库",b="上交这些论著后，档案管理员会将它们归入永久馆藏，从而扩充知识库对魔法现象的理解。在这样的图书馆里，研究人员不断寻找晦涩的文稿，内容涵盖从翡翠梦境到奥术理论的方方面面。这项工作永远无法彻底完成，学者们始终渴望得到在野外发现的任何进一步的魔法著作。"}},faq={{q="“梦游者的秘密”任务的目的是什么？",a="“梦游者的秘密”是一个专注于寻回魔法著作和晦涩知识以扩充学术收藏的任务。冒险者在世界各地获取相关材料并将其上交，以充实研究人员的档案库。",al={"什么是梦者的秘密","梦者的秘密任务","该任务的内容"}},{q="谁在收集这些魔法文本？",a="该任务由负责管理图书馆藏书的一位学者发布和交还，他会请求四处游历的冒险者带回魔法著作。",al={"谁需要梦者的秘密","任务发布者","梦者的秘密交还地点"}},{q="寻回的著作存放在哪里？",a="寻回的文献会被直接加入机构图书馆不断增长的档案中，确保稀有的知识和魔法发现能被编目并保存下来，供联盟的学者和研究人员使用。",al={"什么是藏书","任务涉及的图书馆","书籍的去向"}},{q="标题中的“梦境者”是指什么？",a="“梦境者”通常指与翡翠梦境协调一致的德鲁伊修行者，或是与自然沉睡相连的古老沉睡实体。记载了他们秘密的魔法著作保存着神秘的原始力量。",al={"谁是梦境者","梦境者知识","为什么叫梦境者"}},{q="完成任务后还能带来更多的魔法著作吗？",a="档案管理员非常欢迎持续的贡献。在旅途中，如果您发现了对收藏有益的其他魔法著作，我们鼓励您将其带回以帮助进一步的研究。",al={"可以上交更多书籍吗","任务可重复吗","更多魔法著作"}},{q="收集这些魔法文献对学者为何重要？",a="整个联盟的图书馆和研究人员都在不断寻求扩展对奥术、自然和晦涩奥秘的理解。遗失或散落的论著中包含的见解，能帮助学者们揭开这个世界更深层的历史和谜团。",al={"为什么要收集魔法书籍","图书馆为何需要魔法典籍"}}},fp="23,186,25.278.0,22.248.0,57.121.0,33.106.0,37.165.0,47.179.0,59.151.0,63.173.0"}
P.entries["quest:78145"] = {n="《奥术系统手册》",s="《Arcanic Systems Manual》是一座图书馆希望收藏的魔法著作。将它收入馆藏，有助于扩充图书馆的知识。",h="《Arcanic Systems Manual》是一座图书馆希望收藏的魔法著作。将它收入馆藏，有助于扩充图书馆的知识。",kw={"arcanic","arcanic systems manual","馆藏","铁炉堡","图书馆","魔法著作","手册"},sec={{t="馆藏中的一席之地",b="图书馆欢迎能充实馆藏的魔法著作。你带来一部著作，将其收入馆藏，你的贡献有助于扩充图书馆的知识。"}},faq={{q="Arcanic Systems Manual是什么？",a="它是一座图书馆希望收藏的魔法著作。",al={"arcanic手册","什么手册"}},{q="谁想要这本手册？",a="一位图书管理员请你带来可能有益于馆藏的魔法著作。",al={"谁提出的请求","给谁的手册"}},{q="为什么要把手册带到图书馆？",a="人们捐赠的魔法著作扩充了图书馆的知识。",al={"为什么捐赠","有什么用途"}}},fp="22,129,22.137.0,35.55.0,21.76.0,36.69.0"}
P.entries["quest:78146"] = {n="Goaz Scrolls",s="一位图书管理员请你带来 Goaz Scrolls，以充实馆藏。你的贡献让图书馆的知识更加丰富。",h="一位图书管理员请你带来 Goaz Scrolls，以充实馆藏。你的贡献让图书馆的知识更加丰富。",kw={"馆藏","高兹卷轴","知识","图书馆","魔法典籍","卷轴"},sec={{t="不断丰富的馆藏",b="图书管理员感谢你为馆藏作出的贡献。其他魔法典籍也能为图书馆带来益处，图书管理员欢迎你带来这些典籍。"}},faq={{q="戈阿兹卷轴 有什么用？",a="戈阿兹卷轴 能充实图书馆的馆藏，增长馆藏知识。",al={"高兹卷轴 的用途","为何要带来卷轴","图书馆卷轴"}},{q="是谁在索要 戈阿兹卷轴？",a="一位图书管理员请你带来 戈阿兹卷轴，充实馆藏。",al={"谁想要 高兹卷轴","卷轴交给谁","图书馆人员"}},{q="这些卷轴要送到哪里？",a="戈阿兹卷轴 是为图书馆馆藏准备的。",al={"把卷轴带到哪里","高兹卷轴 的位置","图书馆卷轴"}},{q="还有什么能让图书馆受益？",a="图书管理员欢迎你带来其他可能有益于图书馆的魔法典籍。",al={"其他魔法典籍","更多图书馆藏书","还要带什么"}}},fp="12,117,20.135.0,26.61.0,30.62.0,28.52.0,36.74.0"}
P.entries["quest:78147"] = {n="Crimes Against Anatomy",s="图书管理员请你为图书馆增添魔法典籍。你的发现将帮助拓展图书馆的知识。",h="图书管理员请你为图书馆增添魔法典籍。你的发现将帮助拓展图书馆的知识。",kw={"馆藏","违反解剖学的罪行","铁炉堡","图书管理员","图书馆","魔法典籍"},sec={{t="丰富馆藏",b="任何可能对图书馆有用的魔法典籍都值得收集。你可以把发现带给图书管理员，这些贡献能让他增长见识。或许还有更多典籍能派上用场。"}},faq={{q="谁在征集魔法典籍？",a="图书管理员请你带来可能对馆藏有益的魔法典籍。",al={"谁想要书籍","图书馆的请求"}},{q="我该把典籍带到哪里？",a="把典籍带给图书管理员。暴风城和幽暗城的图书管理员都会收集这类典籍。",al={"图书馆在哪里","书籍该带到哪里"}},{q="为什么要收集魔法典籍？",a="这些典籍能帮助拓展图书馆的知识。",al={"为什么要书籍","魔法典籍有何用"}}},fp="22,124,18.204.0,27.78.0,27.92.0,26.48.0"}
P.entries["quest:78148"] = {n="Runes of the Sorcerer-Kings",s="一座图书馆欢迎魔法典籍加入馆藏。你的发现助它拓展知识。",h="一座图书馆欢迎魔法典籍加入馆藏。你的发现助它拓展知识。",kw={"馆藏","铁炉堡","知识","图书馆","魔法典籍","符文","sorcerer-kings"},sec={{t="馆藏",b="馆藏在你的努力下日渐丰富，图书馆的管理员向你致谢。更多魔法典籍或许能拓展它的知识，管理员欢迎你将它们带到图书馆。"}},faq={{q="图书馆想要什么？",a="图书馆欢迎可能有益于馆藏的魔法典籍。",al={"他们想要什么","图书馆书籍","魔法典籍"}},{q="图书馆在哪里？",a="图书管理员在暴风城和幽暗城收集这类典籍。",al={"图书馆位置","图书馆在哪里","ironforge 图书馆"}},{q="为什么要带来魔法典籍？",a="你的努力拓展了图书馆的知识。",al={"为什么要书籍","有什么用","帮助图书馆"}}},fp="27,96,14.168.0,27.67.0,21.63.0,24.44.0"}
P.entries["quest:78149"] = {n="Fury of the Land",s="图书馆正在为馆藏搜寻魔法典籍。你找到的典籍能帮助拓展他们的知识。",h="图书馆正在为馆藏搜寻魔法典籍。你找到的典籍能帮助拓展他们的知识。",kw={"馆藏","大地之怒","铁炉堡","知识","图书馆","魔法典籍"},sec={{t="求知之地",b="图书管理员问你是否带来了可供补充的藏品。他欣然收下你找到的东西，并邀请你发现更多时再带来。"}},faq={{q="图书馆需要什么？",a="图书馆正在寻找可能对馆藏有益的魔法典籍。",al={"他们需要什么","图书馆书籍","魔法典籍"}},{q="我该把魔法典籍送到哪里？",a="把它们交给图书管理员。暴风城和幽暗城的图书管理员都在收集这类典籍。",al={"书籍送到哪里","图书馆位置","交付典籍"}},{q="他们为什么要收集魔法典籍？",a="图书管理员说，每一份捐赠都能拓展他们的知识。",al={"为何收集魔法书籍","图书馆藏品","有什么用"}}},fp="16,90,21.153.0,27.64.0,35.92.0,38.61.0"}
P.entries["quest:7815"] = {n="钳嘴龟！",s="在辛特兰，恶齿村的钓鱼者卡图姆几乎没法好好钓鱼，因为咸水钳嘴龟总是在破坏鱼线并偷走他的鱼饵。他想要干掉十五只这样的海龟。",h="在辛特兰，恶齿村的钓鱼者卡图姆几乎没法好好钓鱼，因为咸水钳嘴龟总是在破坏鱼线并偷走他的鱼饵。他想要干掉十五只这样的海龟。",kw={"钓鱼者","鱼饵","钓鱼","辛特兰","卡图姆","恶齿","钳嘴龟","海龟"},sec={{t="线上的麻烦",b="卡图姆告诫你不要被钳嘴龟那双大眼睛给骗了，并称这些海龟是个祸害。据他说，他甚至连五分钟都钓不了鱼，这些海龟就会扯断他的鱼线，叼走他的鱼饵。他请求你帮帮他，也帮帮村里的邻居，把这群祸害全部消灭掉；数量是十五只。"}},faq={{q="是谁让你去猎杀海龟的？",a="钓鱼者卡图姆，辛特兰恶齿村的一名渔夫。",al={"谁发布了钳嘴龟任务","钳嘴龟任务发布者","钓鱼者卡图姆"}},{q="为什么卡图姆想要杀掉这些咸水钳嘴龟？",a="卡图姆说它们弄断了他的鱼线并偷走了他的鱼饵，让他甚至没法安安静静地钓上五分钟鱼。",al={"为什么要杀钳嘴龟","海龟滋扰","为什么要杀恶齿村的海龟"}},{q="需要杀掉多少只钳嘴龟？",a="十五只咸水钳嘴龟。",al={"海龟数量","钳嘴龟计数","钳嘴龟任务计数"}}},fp="14,134,19.270.0,33.98.0,51.141.0,35.51.0"}
P.entries["quest:7816"] = {n="加莫里塔！",s="来自辛特兰恶齿村的钓鱼者卡图姆，他最好的鱼饵被海水钳嘴龟的首领加摩拉抢走了。他请求你去找到它，并把它夺回来。",h="来自辛特兰恶齿村的钓鱼者卡图姆，他最好的鱼饵被海水钳嘴龟的首领加摩拉抢走了。他请求你去找到它，并把它夺回来。",kw={"钓鱼者","加摩拉","辛特兰","卡图姆","鱼饵","恶齿村","钳嘴龟","乌龟"},sec={{t="龟群中的窃贼",b="卡图姆描述说，加摩拉可不是一只普通的乌龟：她是海水钳嘴龟的首领，被卡图姆称为小偷。她从他的鱼线上咬断了他最好的鱼饵，从那以后，鱼儿们就不像以前那样上钩了。"},{t="找回鱼饵",b="卡图姆希望你找到加摩拉，并从她的肚子里取回鱼饵。加摩拉通常待在海岸边，混在其他乌龟中间。"},{t="卡图姆的希望",b="拿回鱼饵并除掉一些钳嘴龟后，卡图姆期待着鱼儿能成群结队地游来。"}},faq={{q="钓鱼者卡图姆是谁？",a="辛特兰恶齿村的一位渔夫，他请求你去猎杀加摩拉。",al={"钓鱼者卡图姆是谁","卡图姆 恶齿村","卡图姆位置"}},{q="加摩拉是什么？",a="一只与众不同的乌龟，她是海水钳嘴龟的首领，被卡图姆称为小偷。",al={"加摩拉是谁","加摩拉是什么","加摩拉 乌龟"}},{q="为什么卡图姆要杀掉加摩拉？",a="加摩拉从卡图姆的鱼线上咬断了他最好的鱼饵，从那以后，鱼儿们就没怎么上钩了。卡图姆想从她的肚子里找回鱼饵。",al={"为什么要杀加摩拉","加摩拉偷了什么","卡图姆的目的"}},{q="在哪里可以找到加摩拉？",a="在海岸边，她和其他海水钳嘴龟待在一起。",al={"加摩拉在哪里","加摩拉位置","找到加摩拉"}}},fp="15,145,25.205.0,21.130.0,14.92.1,25.102.0,18.102.0,36.138.0,29.77.0"}
P.entries["quest:782"] = {n="破碎的联盟",s="在卡加斯，高恩想要在部落与死亡之翼结盟之后恢复部落的荣誉。食人魔索格伦受雇协助获取大地印章，但他却背叛了部落并将其据为己有，你需要前往博夫营地将它夺回。",h="在卡加斯，高恩想要在部落与死亡之翼结盟之后恢复部落的荣誉。食人魔索格伦受雇协助获取大地印章，但他却背叛了部落并将其据为己有，你需要前往博夫营地将它夺回。",kw={"荒芜之地","布莱克拉什","博夫营地","死亡之翼","高恩","赫玛图斯","卡加斯","莱瑟罗峡谷","大地印章","索格伦"},sec={{t="雇佣兵的背叛",b="在第二次战争期间，部落曾与巨龙死亡之翼并肩作战。他的两名副官布莱克拉什和赫玛图斯最终被关押在远至东部的莱瑟罗峡谷中。高恩认为，若要恢复部落的荣誉，就必须让这些昔日堕落的盟友永远沉默。为了打开巨龙的囚笼，部落需要大地印章，于是雇佣了索格伦麾下的食人魔佣兵来寻找它。索格伦随后反戈一击，击败了他们并将印章据为己有。"},{t="博夫营地",b="高恩派你前往卡加斯东南部的博夫营地，杀掉索格伦并带回大地印章。高恩会很高兴看到索格伦死去，并表示食人魔已不再是部落的一员。"},{t="印章的用途",b="随着索格伦的死亡，高恩预计食人魔们将陷入混乱，这将是一场以小博大的胜利。只要大地印章回到部落手中，莱瑟罗的黑龙囚笼就能被打开，让它们从无尽的囚禁中解脱出来，迎接属于它们的末日。"}},faq={{q="高恩是谁？",a="高恩是卡加斯的部落人物，他派你去寻找大地印章，并希望通过让部落昔日堕落的盟友永远沉默来恢复部落的荣誉。",al={"谁发布了破碎的盟约任务","卡加斯的高恩","高恩背景故事"}},{q="为什么高恩想要索格伦死？",a="部落雇佣了索格伦和他的食人魔佣兵来帮助获取大地印章。索格伦背叛了他们，击败了他们并将印章据为己有。",al={"为什么要杀掉索格伦","索格伦的背叛","索格伦背景故事"}},{q="博夫营地在哪里？",a="博夫营地位于卡加斯东南部。",al={"博夫营地位置","索格伦在哪里","寻找首领 索格伦"}},{q="大地印章是什么？",a="它是打开莱瑟罗峡谷巨龙囚笼所需的钥匙。",al={"大地印章","大地印章的作用"}},{q="哪些巨龙被关押在莱瑟罗峡谷中？",a="布莱克拉什和赫玛图斯，他们在第二次战争中是死亡之翼与部落结盟时的副官。",al={"谁被关在莱瑟罗峡谷","布莱克拉什和赫玛图斯","死亡之翼的副官"}}},fp="16,220,18.455.0,9.186.0,19.300.1,12.157.0,38.151.0,19.36.0,30.85.0,47.161.0"}
P.entries["quest:7820"] = {n="捐献毛料",s="雷霆崖正在接收毛料捐赠，捐赠六十块即可获得其对你慷慨之举的充分认可。雷霆崖的仓库需要你提供这么多，其他捐赠者还会提供更多物资。",h="雷霆崖正在接收毛料捐赠，捐赠六十块即可获得其对你慷慨之举的充分认可。雷霆崖的仓库需要你提供这么多，其他捐赠者还会提供更多物资。",kw={"布料征集","捐赠","认可","六十块","雷霆崖","毛料"},sec={{t="捐赠布料",b="雷霆崖正在收集毛料。你可以捐赠六十块，满足其仓库对你的需求，并获得充分认可。此次征集预计还能从王国中的其他人那里收集到足够的毛料，以满足需求。"}},faq={{q="雷霆崖希望收到什么捐赠？",a="雷霆崖正在接收毛料捐赠。",al={"捐赠毛料","他们需要什么布料"}},{q="我应该捐赠多少毛料？",a="捐赠六十块毛料即可获得雷霆崖的充分认可。",al={"需要多少毛料","六十块布料","捐赠数量"}},{q="捐赠毛料能得到什么？",a="捐赠六十块毛料即可获得雷霆崖的充分认可。",al={"捐赠毛料的认可","能获得什么认可","捐赠奖励"}},{q="雷霆崖为什么要收集毛料？",a="此次捐赠活动正在收集毛料，雷霆崖预计还能从王国中的其他捐赠者那里获得足够的物资，以满足需求。",al={"为何征集毛料","毛料有什么用","为何收集布料"}}},fp="18,166,16.179.0,37.48.0,34.76.0,32.82.0,37.107.0"}
P.entries["quest:7826"] = {n="捐献毛料",s="奥格瑞玛正在收集毛料布料捐赠，并承诺会认可捐赠六十块布料的人。城中已有一些毛料，预计其他捐赠者也会帮忙凑足所需数量。",h="奥格瑞玛正在收集毛料布料捐赠，并承诺会认可捐赠六十块布料的人。城中已有一些毛料，预计其他捐赠者也会帮忙凑足所需数量。",kw={"捐赠毛料","捐赠","奥格瑞玛","认可","六块","毛料","毛料布料"},sec={{t="捐赠毛料给奥格瑞玛",b="奥格瑞玛邀请你捐赠六十块毛料布料，以表彰你的善举。城中已有一些毛料，也希望其他捐赠者能助力这项捐赠活动。"}},faq={{q="奥格瑞玛需要什么？",a="奥格瑞玛正在收集毛料布料捐赠。",al={"他们需要什么","毛料捐赠"}},{q="我需要捐多少毛料？",a="需要捐赠六十块毛料布料。",al={"需要多少毛料","六块毛料"}},{q="捐赠毛料能得到什么？",a="捐赠六十块毛料布料，奥格瑞玛便会充分认可你的慷慨之举。",al={"捐赠认可","毛料奖励"}},{q="奥格瑞玛为什么要收集毛料？",a="奥格瑞玛正在收集毛料，以支持这项捐赠活动。",al={"毛料捐赠活动","为何要毛料"}},{q="奥格瑞玛已经有毛料了吗？",a="有。奥格瑞玛的仓库里已有毛料，并希望其他捐赠者能捐出足够的数量，助力这项活动。",al={"毛料仓库","毛料数量"}}},fp="18,153,18.188.0,29.47.0,34.46.0,32.81.0,33.58.0,33.96.0"}
P.entries["quest:78261"] = {n="The Horn of Xelthos",s="C留下一张便条，要求你独自前往影牙城堡取回Horn of Xelthos。石爪山脉的Veenix或许能帮你通过庭院大门。",h="C留下一张便条，要求你独自前往影牙城堡取回Horn of Xelthos。石爪山脉的Veenix或许能帮你通过庭院大门。",kw={"c","秘密投递点","horn of xelthos","焚木村","影牙城堡","石爪山脉","veenix","xelthos"},sec={{t="悄然行事",b="C在焚木村附近留下便条，并指定石爪山脉的Veenix作为联络人。Horn of Xelthos就在影牙城堡内的某处，通常得有援手才能闯进去。C希望此事低调进行，所以你必须独自前往，并把号角带回秘密投递点。"}},faq={{q="是谁要你取回Horn of Xelthos？",a="C留下一张便条，要求你取回Horn of Xelthos，并将它送回焚木村附近的秘密投递点。",al={"c是谁","谁要号角","c的号角任务"}},{q="Horn of Xelthos在哪里？",a="Horn of Xelthos就在影牙城堡内的某处。",al={"号角在哪里","号角位置","寻找xelthos"}},{q="为什么我必须独自前往？",a="C说此事必须低调进行，所以你要独自进入影牙城堡。",al={"为何独自行动","为何独自前往","没有援手"}},{q="Veenix是谁？",a="Veenix是C在石爪山脉的联络人，或许能帮你通过影牙城堡的庭院大门。",al={"veenix帮忙","veenix是谁","大门联络人"}},{q="我该把号角送到哪里？",a="把号角送到焚木村附近C的秘密投递点。",al={"号角送到哪里","秘密投递点位置","交还号角"}}},fp="19,158,16.292.0,38.112.0,29.56.0,26.82.0,14.110.0,27.55.0"}
P.entries["quest:78270"] = {n="Goblin Lockpicks",s="一名风险投资公司的联络人愿意提供炸药，帮你通过暗影之牙的大门，但要你先找来一份工作单。附近另一名风险投资公司的工人应该带着一份。",h="一名风险投资公司的联络人愿意提供炸药，帮你通过暗影之牙的大门，但要你先找来一份工作单。附近另一名风险投资公司的工人应该带着一份。",kw={"炸药","大门","goblin lockpicks","暗影之牙","风险投资公司","工作单"},sec={{t="一份工作单",b="一名风险投资公司的联络人听说你打算独自进入暗影之牙。炸药可以帮你通过大门，但联络人需要一份工作单，好让这批物资在公司的账目上显得名正言顺。附近另一名风险投资公司的工人应该有这份文件。"}},faq={{q="他们为什么需要工作单？",a="风险投资公司的联络人需要一份工作单，好让炸药在公司的账目上看起来名正言顺。",al={"工作单为什么需要","为什么要文书","goblin lockpicks"}},{q="炸药是用来做什么的？",a="这些炸药是用来帮你通过暗影之牙的大门的。",al={"炸药用来做什么","暗影之牙大门","通过大门"}},{q="谁可能带着工作单？",a="附近另一名风险投资公司的工人应该带着一份工作单。",al={"谁有工作单","寻找文书","风险投资公司工作单"}},{q="我要独自进入暗影之牙吗？",a="风险投资公司的联络人知道你打算独自进入暗影之牙。",al={"独自前往暗影之牙","独自进入","进入暗影之牙"}}},fp="16,176,12.268.0,30.103.0,28.61.0,30.66.0,33.76.0"}
P.entries["quest:7828"] = {n="银鬃捕猎者",s="来自辛特兰邪枝村的猎户马克霍尔指出，银鬃狼是该村猎人面临的最严重的威胁之一。他要求你反其道而行之，去猎杀这些猎手。",h="来自辛特兰邪枝村的猎户马克霍尔指出，银鬃狼是该村猎人面临的最严重的威胁之一。他要求你反其道而行之，去猎杀这些猎手。",kw={"辛特兰的狼","猎户马克霍尔","邪枝村","恶齿村","银鬃嚎叫者","银鬃潜行者","潜伏的猎手"},sec={{t="潜伏的狼群",b="马克霍尔提到了辛特兰荒野中已经丧命的许多巨魔，并将银鬃狼列为邪枝村猎人面临的最大威胁之一。这些狼潜伏在灌木丛和地形之中，等待时机成熟便发起猛扑。马克霍尔绝不会坐视不管，他敦促你像银鬃狼一样思考，调转枪头，将它们猎杀殆尽。"},{t="马克霍尔的要求",b="马克霍尔要求杀死十五只银鬃潜行者和十五只银鬃嚎叫者。马克霍尔补充说，这些狼潜伏在辛特兰的荒野中。"},{t="邪枝的感谢",b="任务完成后，马克霍尔代表邪枝部族感谢你所做的一切。"}},faq={{q="是谁要求猎杀这些狼？",a="来自辛特兰邪枝村的猎户马克霍尔。",al={"谁发布了潜伏的猎手","潜伏的猎手任务发布者","马克霍尔任务"}},{q="为什么银鬃狼是如此大的威胁？",a="马克霍尔将它们列为邪枝村猎人面临的最大威胁：它们潜伏在灌木丛和地形中，等待机会发起攻击，许多巨魔已经在荒野中丧命。",al={"为什么要杀银鬃狼","银鬃狼的威胁","为什么要消灭辛特兰的狼"}},{q="需要消灭哪些狼？",a="十五只银鬃潜行者和十五只银鬃嚎叫者。",al={"要杀什么狼","潜伏的猎手任务目标","辛特兰的狼种类"}},{q="在哪里可以找到这些狼？",a="马克霍尔说它们潜伏在辛特兰的荒野中。",al={"银鬃狼在哪里","银鬃潜行者位置","银鬃嚎叫者位置"}}},fp="21,120,16.321.0,17.120.0,18.80.1,37.79.0,44.218.0,31.81.0,29.41.0"}
P.entries["quest:7829"] = {n="野蛮的枭兽",s="来自辛特兰恶齿村的猎户马克霍尔称那些野蛮的枭兽是该地区最暴躁的生物之一，并要求你杀死二十只。",h="来自辛特兰恶齿村的猎户马克霍尔称那些野蛮的枭兽是该地区最暴躁的生物之一，并要求你杀死二十只。",kw={"辛特兰","猎杀野蛮生物","猎户马克霍尔","枭兽","恶齿","恶齿村","野蛮枭兽"},sec={{t="利爪与尖喙",b="马克霍尔形容那些野蛮的枭兽是辛特兰最暴躁的生物之一，并声称这些野兽的利爪和尖喙已经让恶齿部族损失了许多优秀的战士。马克霍尔希望你见到一只就杀一只，直到你无法再承受这场杀戮，届时你所做的贡献将会被衡量与评判。必须有二十只枭兽倒下。"},{t="清空思绪",b="马克霍尔给出的狩猎建议是清空脑中杂念，与荒野融为一体。枭兽就出没在辛特兰的荒野中。"},{t="马克霍尔的评判",b="狩猎结束后，马克霍尔将你称为恶齿部族值得信赖的朋友。"}},faq={{q="谁发布了这项狩猎任务？",a="来自辛特兰恶齿村的猎户马克霍尔。",al={"谁发布了猎杀野蛮生物任务","猎杀野蛮生物任务发布者","猎户马克霍尔任务"}},{q="为什么马克霍尔想要杀死这些野蛮的枭兽？",a="马克霍尔称它们非常暴躁，并表示这些枭兽已经用它们的利爪和尖喙夺去了许多优秀恶齿战士的生命。",al={"为什么要杀野蛮枭兽","猎杀枭兽的原因","为什么要猎杀野蛮生物"}},{q="在哪里可以找到这些野蛮的枭兽？",a="马克霍尔说它们栖息在辛特兰的荒野中。",al={"野蛮枭兽位置","野蛮枭兽在哪里","辛特兰的枭兽"}},{q="必须杀死多少只野蛮的枭兽？",a="二十只野蛮的枭兽。",al={"要杀多少只枭兽","猎杀野蛮生物要求"}}},fp="16,106,15.300.0,17.128.0,18.76.1,21.95.0,50.100.0,40.57.0,40.34.0"}
P.entries["quest:783"] = {n="身边的危机",s="“内在的威胁”标志着响应暴风城号召的保卫者在北郡山谷服役的开始。新兵们被指引前往北郡修道院去见治安官玛克布莱德，他们会发现王国的军队在海外兵力分散，导致当地驻军在没有平民协助的情况下无法应对国内的麻烦。",h="“内在的威胁”标志着响应暴风城号召的保卫者在北郡山谷服役的开始。新兵们被指引前往北郡修道院去见治安官玛克布莱德，他们会发现王国的军队在海外兵力分散，导致当地驻军在没有平民协助的情况下无法应对国内的麻烦。",kw={"内在的威胁","修道院","艾尔文森林","治安官玛克布莱德","北郡","招募","暴风城卫兵","志愿者"},ang={["faction:Alliance"]="这个任务强调了大联盟所面临的压力：在遥远的领土上维持军事承诺，使得即使是最安全的中心地带也容易受到内部崩溃的影响。",["race:Human"]="由于北郡是人类保卫者的起始山谷，响应治安官玛克布莱德的召唤代表了你保护家园和暴风城王国的第一次正式誓约。"},sec={{t="国力吃紧的王国",b="北郡山谷曾经是一个专注于祈祷、耕作和修道研究的宁静避风港。如今，它成为了防御艾尔文森林内部动乱的第一道防线。暴风城的正规军被广泛部署在遥远的前线，导致首都中心地带兵力严重不足。由于当地驻扎的正式士兵很少，暴风城卫队必须招募任何到达修道院大门的志愿新兵。"},{t="治安官的召唤",b="在北郡修道院内，治安官玛克布莱德在日益增长的区域压力下协调着山谷的防御。当外来的威胁从远方威胁着联盟时，无法无天的强盗、成群的害虫和地下的怪物正利用权力真空，就在王国的家门口兴风作浪。响应这一召唤将使新兵立即投入军事服役，从清理修道院周边的威胁开始，进而对抗在整个艾尔文扎根的更深层的腐败。"}},faq={{q="这个任务的目的是什么？",a="它是为北郡山谷新到的新兵准备的入门召唤。你的指示是走进北郡修道院，直接向治安官玛克布莱德报告，加入当地的防御工作。",al={"内在的威胁任务","这是什么任务","北郡入门任务"}},{q="谁是治安官玛克布莱德？",a="治安官玛克布莱德是驻扎在北郡修道院的暴风城卫队的高级军官。他负责监督山谷的防御，协调新兵，并分配任务以遏制出现在周边乡村的威胁。",al={"治安官玛克布莱德","谁是玛克布莱德","修道院指挥官"}},{q="为什么暴风城要招募志愿者而不是派遣正规士兵？",a="暴风城的常备军已被部署到海外进行远征，以保护联盟的利益。这种繁重的海外任务使中心地带的驻军严重人手不足，迫使当地指挥官不得不依靠新到的冒险者和志愿者来保卫自己的家园。",al={"为什么要招募志愿者","卫兵在哪里","为什么暴风城兵力不足"}},{q="目前有什么威胁在困扰着北郡山谷？",a="山谷正面临着多重压力：侵扰附近矿山和山丘的残暴狗头人，骚扰周边葡萄园的患病或掠食性害虫，以及利用当地驻军空虚而组织起来的强盗团伙。",al={"山谷威胁","什么在攻击北郡","北郡的问题"}},{q="这个任务接下来会引向哪里？",a="向治安官玛克布莱德报告后，将在北郡周边开启几项紧迫的任务，指引新兵清除山丘中的狗头人入侵，帮助当地的农民和工人，并调查日益猖獗的有组织的强盗。",al={"下一个任务","“内在的威胁”之后是什么","玛克布莱德的后续任务"}},{q="为什么北郡修道院被用作军事指挥所？",a="虽然北郡修道院是一个专注于学习和信仰的神圣场所，但其坚固的石墙和中心位置使其成为山谷中唯一实用的行动基地。随着当地行政力量的紧张，暴风城卫队直接在其大厅内建立了行政指挥部。",al={"为什么修道院有军队","北郡教堂军队","神圣修道院士兵"}}},fx={["2039075b"]={q="维里副队长为什么派你去见治安官玛克布莱德？",a="维里副队长驻守在北郡修道院外，尽快甄选前来报到的健壮人手。王国的兵力捉襟见肘，多重危机正逼近北郡的边界，他需要让每一位有能力的志愿者正式入伍。维里没有亲自分派任务，而是让你直接去见他的上级治安官玛克布莱德，接受正式的情况简报，再被派往谷中防线最为薄弱的地方。",al={"为什么找玛克布莱德交谈","维里的动机","为什么与玛克布莱德交谈"}}},fp="15,190,24.301.0,18.295.0,34.129.0,23.170.0,75.167.0,54.175.0,37.171.0,62.230.0"}
P.entries["quest:7830"] = {n="死者的复仇",s="恶齿村的猎户马克霍尔说，蛮锤部族训练狮鹫来猎杀巨魔，因此他想要除掉该地区的狮鹫长者——天空领主。你必须杀死一只锋喙天空领主，并将它的羽毛带回来给他。",h="恶齿村的猎户马克霍尔说，蛮锤部族训练狮鹫来猎杀巨魔，因此他想要除掉该地区的狮鹫长者——天空领主。你必须杀死一只锋喙天空领主，并将它的羽毛带回来给他。",kw={"复仇之怒","狮鹫","辛特兰","猎户马克霍尔","锋喙天空领主","恶齿村","天空领主羽毛","蛮锤部族"},sec={{t="猎杀天空领主",b="辛特兰恶齿村的猎户马克霍尔对蛮锤部族训练狮鹫猎杀巨魔的行为感到愤恨。他发誓要让对方付出代价，但首先，他希望你先对该地区的狮鹫长者“天空领主”下手。杀掉一只并带回它的羽毛。锋喙天空领主是一种稀有品种，通常出没于辛特兰的荒野中，马克霍尔认为正是它们繁育了这些凶残的后代。"},{t="羽毛鉴定",b="马克霍尔仔细端详着那根羽毛，大声感叹着这头野兽在被你除掉之前，到底吞食了多少猎人。"}},faq={{q="谁提供这个任务？",a="猎户马克霍尔在辛特兰的恶齿村提供此任务。",al={"任务发布者","谁发布了复仇之怒","马克霍尔位置"}},{q="为什么猎户马克霍尔要猎杀天空领主？",a="马克霍尔说蛮锤部族训练狮鹫猎杀巨魔，所以他想要根除该地区的天空领主。他声称锋喙天空领主是一种繁育凶残后代的稀有品种。",al={"为什么要杀锋喙天空领主","为什么要杀天空领主","为什么要猎杀狮鹫"}},{q="在哪里可以找到锋喙天空领主？",a="马克霍尔说这种稀有品种通常出没于辛特兰的荒野中。",al={"天空领主位置","锋喙天空领主在哪里","天空领主羽毛位置"}},{q="必须带什么东西回给马克霍尔？",a="杀死一只锋喙天空领主，并将它的羽毛带回给马克霍尔。",al={"我需要什么物品","复仇之怒任务目标","天空领主掉落"}}},fp="19,131,20.383.0,18.110.1,21.73.0,47.190.0,39.78.0,37.64.0"}
P.entries["quest:7833"] = {n="捐献毛料",s="一名暗矛巨魔正在募集毛料。你捐出的六十块毛料，将在他人相助下帮助完成募集。",h="一名暗矛巨魔正在募集毛料。你捐出的六十块毛料，将在他人相助下帮助完成募集。",kw={"收集","暗矛","捐赠","储备","巨魔","羊毛","毛料"},sec={{t="共同募集",b="暗矛巨魔正在募集毛料，收集者现在可以接收你捐出的六十块毛料。他们的储备需要你提供这些毛料；预计还会有其他人相助，完成募集。"}},faq={{q="正在收集什么？",a="暗矛巨魔正在募集毛料。",al={"需要什么","捐赠毛料"}},{q="他们需要我提供多少毛料？",a="收集者请你提供六十块毛料。",al={"需要多少毛料","六十块毛料"}},{q="巨魔为什么要收集毛料？",a="收集这些毛料是为了补充他们的储备。",al={"为何要毛料","有何用途"}},{q="我现在可以交出毛料吗？",a="收集者现在可以接收你捐出的六十块毛料。",al={"哪里交毛料","现在捐赠"}}},fp="18,103,19.181.0,24.46.0,41.56.0,35.56.0,25.66.0"}
P.entries["quest:7839"] = {n="邪枝窃贼",s="恶齿村的铁匠斯拉提说恶齿巨魔入侵了村子并偷走了他的工具。他虽然还有备用工具，但被偷走的那套工具是一位好心的侏儒送给他的礼物，那名侏儒在他还是个年轻兽人时救过他的命，他希望能找回那套工具。",h="恶齿村的铁匠斯拉提说恶齿巨魔入侵了村子并偷走了他的工具。他虽然还有备用工具，但被偷走的那套工具是一位好心的侏儒送给他的礼物，那名侏儒在他还是个年轻兽人时救过他的命，他希望能找回那套工具。",kw={"亚戈瓦萨","辛特兰","玛戈尔","恶齿村","沙尔瓦萨","隐匿石","斯拉提丢失的工具","铁匠斯拉提","恶齿"},sec={{t="一份侏儒的礼物",b="恶齿巨魔入侵了恶齿村，偷走了铁匠斯拉提的工具。虽然他有备用工具，但被偷走的那套是曾在他年轻时救过他性命的一位好心侏儒所赠。他告诉你这套工具对他意义非凡，并请求你帮他找回来。"},{t="工具可能所在之处",b="斯拉提说玛戈尔报告说在辛特兰东北部的亚戈瓦萨和沙尔瓦萨神庙附近看到了这些工具。他还让你去隐匿石搜寻一下，并警告说该地区的恶齿巨魔凶残成性，极其危险。"}},faq={{q="为什么这些被偷的工具对铁匠斯拉提如此重要？",a="这套工具是一位好心的侏儒送给他的礼物，那名侏儒在他还是个年轻兽人时救过他的命。虽然他还有备用工具，但他表示这套对他来说意义非凡。",al={"为什么斯拉提在意他的工具","斯拉提丢失工具背景故事","为什么斯拉提的工具很特别"}},{q="是谁从恶齿村偷走了工具？",a="恶齿巨魔入侵了村子并偷走了铁匠斯拉提的工具。",al={"谁拿走了工具","谁偷了斯拉提的工具"}},{q="丢失的工具被带到了哪里？",a="玛戈尔在辛特兰东北部的亚戈瓦萨和沙尔瓦萨神庙附近看到了它们。斯拉提还让你去隐匿石搜寻一下。",al={"斯拉提的工具在哪里","去哪里寻找工具","斯拉提的工具位置"}},{q="是谁在袭击发生后报告看到了这些工具？",a="玛戈尔将工具可能所在的消息告诉了斯拉提。",al={"谁看到了工具","谁报告了被盗工具"}}},fp="20,162,19.259.0,25.201.0,58.163.0,43.90.0,35.144.0,45.58.0"}
P.entries["quest:784"] = {n="背信弃义的人类",s="“消灭背叛者”是一项由剃刀岭的加索克下达的部落军事突袭行动，旨在从人类入侵者手中夺回提拉加德城堡。本尼迪克特中尉麾下的库尔提拉斯军队重新占领了这座要塞，直接破坏了杜隆塔尔与塞拉摩之间脆弱的和平。消灭他们的驻军对于保卫兽人故乡的东海岸至关重要。",h="“消灭背叛者”是一项由剃刀岭的加索克下达的部落军事突袭行动，旨在从人类入侵者手中夺回提拉加德城堡。本尼迪克特中尉麾下的库尔提拉斯军队重新占领了这座要塞，直接破坏了杜隆塔尔与塞拉摩之间脆弱的和平。消灭他们的驻军对于保卫兽人...",kw={"戴林·普罗德摩尔","杜隆塔尔","加索克","库尔提拉斯","本尼迪克特中尉","海军陆战队","剃刀岭","水兵","提拉加德城堡","消灭背叛者"},ang={["faction:Horde"]="库尔提拉斯人对提拉加德城堡的占领是一场发生在杜隆塔尔家门口的持续战争。清除本尼迪克特的军队证明了部落有能力保卫其新建立的家园，抵御外来舰队的侵犯。",["race:Orc"]="兽人尊重在海加尔山与吉安娜达成的停战协议，但库尔提拉斯人却带来了第二次战争的苦涩回忆。击退本尼迪克特的海军陆战队关乎生存与祖先的荣耀。",["race:Troll"]="提拉加德城堡的位置距离暗矛部族的定居点森金村过近，令人不安。扫荡这些敌对的水兵可以直接保护巨魔脆弱的新家园。"},sec={{t="破碎的停战协议",b="当萨尔率领部落横跨无尽之海来到卡利姆多时，他与吉安娜·普罗德摩尔女士结成了不稳定的联盟，以在海加尔山击败燃烧军团。然而当吉安娜疏远的父亲，戴林·普罗德摩尔海军上将带着强大的库尔提拉斯舰队到来时，和平便荡然无存。海军上将将旧部落的所有暴行归咎于全体兽人，他入侵了杜隆塔尔并占领了包括提拉加德城堡在内的沿海据点。尽管戴林最终在塞拉摩被杀，但他舰队的残部拒绝履行任何条约，也不愿放弃他们的仇恨。"},{t="本尼迪克特的卷土重来",b="在海军上将陨落后，提拉加德城堡曾一度被击溃，但本尼迪克特中尉麾下的库尔提拉斯预备队此后又夺回了这座要塞。从这个位于剃刀岭和森金村之间的坚固堡垒出发，这些水兵和海军陆战队员不断袭扰过往旅人，并威胁着东部的海上航线。加索克认为他们根深蒂固的据点直接威胁到了杜隆塔尔的安全，因此号召部落勇士直接打击本尼迪克特的指挥部。"}},faq={{q="为什么库尔提拉斯人类要攻击杜隆塔尔？",a="他们是戴林·普罗德摩尔海军上将指挥的远征舰队的残部。这位上将拒绝接受人类与兽人之间的和平共存，一心想要彻底根除杜隆塔尔。即便在他死后，他的忠实拥护者们依然无视部落，继续盘踞在像提拉加德城堡这样的沿海据点中。",al={"为什么人类在杜隆塔尔","库尔提拉斯攻击","提拉加德城堡人类背景故事"}},{q="本尼迪克特中尉是谁？",a="本尼迪克特中尉是目前占据提拉加德城堡的库尔提拉斯预备队的指挥官。在普罗德摩尔海军上将战败后，本尼迪克特召集了幸存的海军陆战队员和水兵，夺回了这座沿海堡垒，并持续对兽人发动袭击。",al={"本尼迪克特是谁","本尼迪克特中尉背景故事","提拉加德城堡领袖"}},{q="吉安娜·普罗德摩尔支持这些人吗？",a="不支持。吉安娜与萨尔酋长签署了相互生存的条约，并积极反对她父亲的侵略性远征，以维护和平。占据提拉加德城堡的部队是库尔提拉斯的叛乱残部，他们拒绝塞拉摩的外交政策，并将吉安娜的停战协议视为背叛行为。",al={"吉安娜支持他们吗","塞拉摩库尔提拉斯联盟","吉安娜·普罗德摩尔提拉加德"}},{q="为什么称他们为“背叛者”？",a="加索克认为他们是背叛者，因为他们的入侵直接违背了萨尔与吉安娜·普罗德摩尔为在第三次战争中击败阿克蒙德而达成的外交共识。他们在部落领土上的持续军事存在，公然挑衅了战后在卡利姆多确立的边界。",al={"为什么是背叛者","谁背叛了谁","背叛者含义"}},{q="提拉加德城堡位于哪里？",a="提拉加德城堡位于杜隆塔尔的东海岸，剃刀岭以南，森金村的东北方。它高耸的石墙俯瞰着沿海海域，为入侵者提供了一个靠近部落定居点的战略基地。",al={"提拉加德城堡位置","提拉加德城堡在哪里","去哪里找本尼迪克特"}}},fp="22,207,17.452.0,21.420.0,43.256.0,27.249.0,43.253.0,32.259.0,32.216.0"}
P.entries["quest:7840"] = {n="拉尔德的午餐",s="住在辛特兰恶齿村的拉德又饿又怕。拉德在一次独自野餐时遭到了邪枝巨魔的袭击，惊慌中丢下午餐逃跑了。有人委托你从北边的一座岛屿上把午餐找回来。",h="住在辛特兰恶齿村的拉德又饿又怕。拉德在一次独自野餐时遭到了邪枝巨魔的袭击，惊慌中丢下午餐逃跑了。有人委托你从北边的一座岛屿上把午餐找回来。",kw={"辛特兰","岛屿","拉德","午餐","野餐","恶齿村","邪枝"},sec={{t="中断的野餐",b="拉德在一个秘密地点野餐时，被一个邪枝巨魔袭击了——按拉德的话说，那个巨魔又丑又坏，还用一根大棍子打了他。拉德落荒而逃回了恶齿村，把午餐留在了原地。现在拉德又饿又怕，不敢回去。"},{t="北方的岛屿",b="野餐地点位于北边的一座岛屿上。拉德希望你能去那里找到他的午餐并带回来，同时要小心那些邪枝巨魔。"},{t="拉德的感谢",b="这份午餐竟然是一大块肉。拉德狼吞虎咽地吃了个精光，向你表示感谢，并承诺给你一个特别的野餐篮作为回报。"}},faq={{q="谁是拉德？",a="辛特兰恶齿村的居民，因为被邪枝巨魔用大棍子袭击而又饿又怕。",al={"拉德 辛特兰","谁是拉德","拉德 恶齿村"}},{q="拉德在哪里丢了他的午餐？",a="在北边一座岛屿上的秘密野餐点。",al={"拉德的午餐在哪里","拉德的野餐点","拉德的秘密地点"}},{q="拉德为什么丢下他的食物？",a="在野餐时被一个邪枝巨魔用大棍子打了一下，拉德没带午餐就跑回了恶齿村。",al={"拉德为什么逃跑","谁攻击了拉德"}},{q="在岛上应该提防什么？",a="拉德说岛上的危险是邪枝巨魔。",al={"岛上的邪枝巨魔","拉德岛上的危险"}}},fp="19,194,20.185.0,20.144.0,13.122.1,12.125.0,30.70.0,35.106.0,44.59.0"}
P.entries["quest:7841"] = {n="给蛮锤部族的警告",s="在辛特兰的恶齿村，奥索·莫吉克声称蛮锤部族正在与巨魔的敌人做交易，而这一次，高等精灵成为了他们的伙伴。奥索想要将一条用奎尔丹尼小屋的高谷高等精灵的鲜血写成的讯息送给蛮锤矮人。",h="在辛特兰的恶齿村，奥索·莫吉克声称蛮锤部族正在与巨魔的敌人做交易，而这一次，高等精灵成为了他们的伙伴。奥索想要将一条用奎尔丹尼小屋的高谷高等精灵的鲜血写成的讯息送给蛮锤矮人。",kw={"高谷","辛特兰","给蛮锤的讯息","奥索·莫吉克","奎尔丹尼小屋","恶齿村","蛮锤"},sec={{t="血的讯息",b="蛮锤部族正在与巨魔的敌人建立新的盟约，而这一次高等精灵成为了他们的伙伴。奥索·莫吉克对这种想法嗤之以鼻。必须要给那些矮人一点颜色看看，用他们新朋友的鲜血写下讯息：杀掉你遇到的每一个高谷高等精灵，并将尸体留下作为警告。高谷先驱者、斥候、神射手和游侠都聚集在辛特兰西北部的奎尔丹尼小屋。"},{t="恶齿村的传闻",b="当你回来时，奥索宣称恶齿部族也在建立新的盟约，并称赞了你的工作。"}},faq={{q="谁提供这个任务？",a="奥索·莫吉克，他就在恶齿村。",al={"谁给予给蛮锤的讯息任务","奥索·莫吉克任务"}},{q="高谷高等精灵位于何处？",a="他们聚集在辛特兰西北部的奎尔丹尼小屋。",al={"奎尔丹尼小屋位置","高谷精灵在哪里","去哪里找高谷斥候"}},{q="为什么奥索·莫吉克想要攻击那些高等精灵？",a="奥索说蛮锤部族正在与巨魔的敌人做交易，现在他们又在与高等精灵合作。奥索想要将一条用高等精灵的鲜血写成的讯息送给蛮锤矮人。",al={"为什么要攻击奎尔丹尼","为什么要杀死辛特兰的高等精灵"}},{q="奥索想要屠杀哪些高谷精灵？",a="奎尔丹尼小屋的高谷先驱者、斥候、神射手和游侠。",al={"哪些高谷精灵","高谷神射手","高谷游侠"}}},fp="25,222,18.393.0,25.122.1,22.46.0,42.88.0,51.209.0,48.97.0"}
P.entries["quest:7842"] = {n="又一个给蛮锤部族的警告",s="在第一条信息之后，恶齿村的奥索·莫吉克说蛮锤部族和他们的狮鹫就像巨魔和他们的伴侣一样亲密。真恶心，但可以利用这一点来对付他们。奥索想要杀死辛特兰的狮鹫以获取它们的羽毛。",h="在第一条信息之后，恶齿村的奥索·莫吉克说蛮锤部族和他们的狮鹫就像巨魔和他们的伴侣一样亲密。真恶心，但可以利用这一点来对付他们。奥索想要杀死辛特兰的狮鹫以获取它们的羽毛。",kw={"狮鹫","辛特兰","修长的羽毛","奥索·莫吉克","恶齿村","蛮锤部族"},sec={{t="羽毛的讯息",b="在对付了高谷高等精灵之后，奥索·莫吉克还有另一条信息要传达。据说蛮锤部族和他们的狮鹫就像巨魔和他们的伴侣一样亲密，奥索觉得这很恶心，但很有用。杀死你在辛特兰遇到的狮鹫，并收集它们的修长的羽毛。据了解，狮鹫生活在那里的每一个地区。奥索将用这些羽毛制作出最后的信息。"},{t="奥索的乐趣",b="奥索希望最后的信息能把蛮锤部族吓跑，或者让他们变得非常非常愤怒。奥索很高兴，因为在让蛮锤部族明白巨魔不可招惹之前，只剩下最后一步了。"}},faq={{q="谁发布了这个任务？",a="奥索·莫吉克，他站在恶齿村。",al={"谁发布了致蛮锤部族的另一条讯息","另一条讯息任务发布者","奥索·莫吉克"}},{q="为什么奥索·莫吉克想要狮鹫羽毛？",a="奥索说蛮锤部族和他们的狮鹫就像巨魔和他们的伴侣一样亲密，他想利用这一点来对付他们。这些羽毛将用于最后的信息。",al={"为什么需要狮鹫羽毛","为什么要杀死辛特兰的狮鹫"}},{q="在哪里可以找到狮鹫？",a="据了解，狮鹫生活在辛特兰的每一个地区。",al={"辛特兰狮鹫位置","辛特兰的狮鹫在哪里"}},{q="在这条信息之前发生了什么？",a="它紧随“致蛮锤部族的讯息”之后，在那个任务中，奥索为了给矮人一个警告，屠杀了高谷高等精灵。",al={"致蛮锤部族的另一条讯息的前置任务","致蛮锤部族的讯息任务线"}}},fp="33,175,21.332.0,15.167.1,21.54.0,44.165.0,28.49.0,30.118.0"}
P.entries["quest:7843"] = {n="给蛮锤部族的最后警告",s="奥索·莫吉克给了你一根浸透了鲜血、系着狮鹫羽毛的长矛。你需要把它带到位于辛特兰西部的鹰巢山，并将其插在镇中心水井旁的土地上。",h="奥索·莫吉克给了你一根浸透了鲜血、系着狮鹫羽毛的长矛。你需要把它带到位于辛特兰西部的鹰巢山，并将其插在镇中心水井旁的土地上。",kw={"鹰巢山","狮鹫羽毛","辛特兰","奥索·莫吉克","恶齿村","长矛","蛮锤"},sec={{t="送给鹰巢山的矛",b="继“给蛮锤的另一个口信”之后，奥索·莫吉克给了你最后的口信：一根浸透了鲜血、系着狮鹫羽毛的长矛。带着它前往鹰巢山，把它插在城镇正中心的水井旁边，让那些矮人知道巨魔是动真格的。奥索希望你能活着回来，并警告你蛮锤矮人和喧闹的联盟成员会非常愤怒。"},{t="奥索的希望",b="奥索希望能亲眼看到那些矮人的表情，并大声猜测他们是否正在收拾行装准备离开。奥索承诺会为你完成这一壮举提供丰厚的奖励。"}},faq={{q="是谁让你去插这根长矛的？",a="奥索·莫吉克，他就在恶齿村。",al={"任务发布者","谁发布任务","奥索·莫吉克"}},{q="长矛必须插在哪里？",a="在辛特兰西部的鹰巢山，镇中心的水井旁边。",al={"长矛位置","我该把长矛放在哪里","鹰巢山水井"}},{q="这最后的口信是由什么构成的？",a="一根浸透了鲜血、系着狮鹫羽毛的长矛。",al={"长矛是什么","狮鹫羽毛长矛","最后的口信物品"}},{q="这个任务链的前序是什么？",a="它是“给蛮锤的另一个口信”的后续，在那个任务中，奥索要求收集狮鹫羽毛来制作这最后的口信。",al={"前置任务","先决条件","蛮锤口信任务链"}}},fp="35,185,22.351.0,11.208.1,33.46.0,32.91.0,34.77.0,35.106.0"}
P.entries["quest:7844"] = {n="野蛮的亲戚",s="恶齿村的秘法师雅尔金称邪枝巨魔是一群堕落之徒，他们以其他巨魔和类人生物为食。由于祖尔金不在那里消灭他们，她请求你去消灭东北偏北方向神庙附近的邪枝剥皮者和邪枝占卜师。",h="恶齿村的秘法师雅尔金称邪枝巨魔是一群堕落之徒，他们以其他巨魔和类人生物为食。由于祖尔金不在那里消灭他们，她请求你去消灭东北偏北方向神庙附近的邪枝剥皮者和邪枝占卜师。",kw={"亚戈瓦萨","同宗相食","秘法师雅尔金","恶齿村","剥皮者","沙尔瓦萨","占卜师","邪枝巨魔","祖尔金"},sec={{t="同宗相食",b="辛特兰生活着三个巨魔部族，秘法师雅尔金说，除了同在这一片土地上的巨魔之外，他们几乎没有什么共同点。她称邪枝巨魔（名字十分贴切）是一群以其他巨魔和类人生物为食的堕落之徒。祖尔金本可以轻易地将他们消灭，但祖尔金并不在那里，恶齿部族只能自谋生路。"},{t="邪枝巨魔的聚集地",b="雅尔金请求你去消灭邪枝剥皮者和邪枝占卜师，他们就在辛特兰东北偏北的沙尔瓦萨和亚戈瓦萨神庙附近。"},{t="雅尔金的赞许",b="当你回来时，雅尔金声称，即使是祖尔金也无法做得更好了。"}},faq={{q="谁提供这个任务？",a="站在恶齿村的秘法师雅尔金。",al={"同宗相食任务发布者","谁发布同宗相食","秘法师雅尔金"}},{q="为什么雅尔金想要消灭邪枝巨魔？",a="她称邪枝巨魔是一群以其他巨魔和类人生物为食的堕落之徒，并说清理该地区的污秽是你的职责。",al={"恶齿为什么与邪枝开战","邪枝巨魔的食人行为","恶齿与邪枝的冲突"}},{q="在哪里可以找到邪枝巨魔？",a="在辛特兰东北偏北的沙尔瓦萨和亚戈瓦萨神庙周围。",al={"沙尔瓦萨位置","亚戈瓦萨位置","邪枝占卜师在哪里"}},{q="雅尔金想要消灭哪些邪枝巨魔？",a="邪枝剥皮者和邪枝占卜师。",al={"同宗相食任务目标","同宗相食任务要杀谁"}},{q="祖尔金在哪里？",a="目前不在辛特兰。雅尔金说如果祖尔金在那里，他会轻易地消灭邪枝巨魔，但他并不在，所以恶齿部族只能自谋生路。",al={"祖尔金在这里吗","祖尔金在辛特兰的什么位置","祖尔金现状"}}},fp="21,226,22.242.0,27.169.0,17.71.1,22.49.0,48.137.0,41.108.0,46.76.0,17.152.0"}
P.entries["quest:7845"] = {n="被绑架的断齿长者！",s="恶齿村的断齿族长说，邪枝巨魔在深夜突袭，带走了她的配偶断齿长者。间谍报告说他还活着，被囚禁在辛萨罗之巅，她请求你去救他。",h="恶齿村的断齿族长说，邪枝巨魔在深夜突袭，带走了她的配偶断齿长者。间谍报告说他还活着，被囚禁在辛萨罗之巅，她请求你去救他。",kw={"断齿长者","哈卡","海克斯","辛特兰","辛萨罗","断齿族长","恶齿","邪枝巨魔"},sec={{t="深夜突袭",b="邪枝巨魔在午夜袭击了恶齿村，掳走了断齿长者，也就是断齿族长的配偶。她的间谍称他还活着，被关在辛萨罗，那是位于辛特兰南部的邪枝巨魔之都。断齿族长担心村子无法承受失去他的后果。"},{t="无面嗜血神",b="有消息称，邪枝祭司海克斯正准备将俘虏献祭给哈卡，那位无面嗜血神。"},{t="一旦你找到他",b="找到长者后，他会催促你快点行动，因为守卫肯定已经察觉到你的到来了。"}},faq={{q="是谁掳走了断齿长者？",a="邪枝巨魔在一次大胆的午夜袭击中掳走了他，袭击的目标是恶齿村。",al={"谁绑架了断齿长者","谁带走了断齿长者","断齿长者的绑架者"}},{q="断齿长者被关在哪里？",a="她的间谍称，他被关押在辛萨罗之巅，那是位于辛特兰南部的邪枝巨魔之都。",al={"断齿长者的位置","断齿长者在哪里","断齿长者被囚禁在哪里"}},{q="断齿长者在辛萨罗之巅面临怎样的命运？",a="有消息称，邪枝祭司海克斯正准备将他献祭给哈卡，那位无面嗜血神。",al={"为什么断齿长者被俘","邪枝巨魔想要对断齿长者做什么","海克斯献祭断齿长者"}},{q="断齿族长是谁？",a="断齿族长是断齿长者的配偶，她请求你去救他。",al={"谁是断齿族长","断齿族长的配偶"}}},fp="25,147,15.279.0,22.107.0,18.90.1,24.84.0,35.126.0,49.120.0,23.71.0"}
P.entries["quest:7846"] = {n="找回钥匙！",s="断齿长者被囚禁在辛萨罗的枷锁之中。他说看守者希塔亚持有他束缚的钥匙，就在附近守卫森严的洞穴里。他请求你杀了她，取回钥匙。",h="断齿长者被囚禁在辛萨罗的枷锁之中。他说看守者希塔亚持有他束缚的钥匙，就在附近守卫森严的洞穴里。他请求你杀了她，取回钥匙。",kw={"断齿长者","辛特兰","看守者希塔亚","辛萨罗","取回钥匙","恶齿部族","枷锁钥匙"},sec={{t="看守者的洞穴",b="在“被绑架的断齿长者！”之后，你在辛萨罗发现了被枷锁捆住的断齿长者。看守者希塔亚持有他束缚的钥匙，就在附近守卫森严的洞穴里。断齿长者请求你杀了她，取回钥匙来解开他的枷锁，只有这样他才能回家。"},{t="断齿长者的感谢",b="拿着钥匙，断齿长者站了起来。他感谢了你，并说恶齿部族会铭记你的功绩。"}},faq={{q="谁持有断齿长者枷锁的钥匙？",a="看守者希塔亚持有钥匙。断齿长者说她在附近的洞穴里，并且被严密守卫着。",al={"谁有钥匙","看守者希塔亚","枷锁钥匙在哪里"}},{q="断齿长者被关在哪里？",a="断齿长者被关在辛萨罗。",al={"断齿长者在哪里","断齿长者位置","辛萨罗断齿长者"}},{q="为什么断齿长者需要这把钥匙？",a="这把钥匙可以打开他身上的枷锁。他说，只有这样他才能重获自由并回家。",al={"为什么要枷锁钥匙","钥匙有什么用"}}},fp="16,128,17.285.0,23.108.1,47.123.0,29.38.0,37.84.0"}
P.entries["quest:7847"] = {n="向断齿族长复命",s="断齿长者请求你回到恶齿村他的配偶，断齿族长身边，告诉她他正要回家。",h="断齿长者请求你回到恶齿村他的配偶，断齿族长身边，告诉她他正要回家。",kw={"断齿长者","辛特兰","辛萨罗","断齿族长","恶齿","恶齿村"},sec={{t="给他配偶的消息",b="断齿长者已经摆脱了束缚，他请求你回到恶齿村。你必须去那里告诉他的配偶，断齿族长，他正要回家。"},{t="村庄的感激",b="断齿族长说你为恶齿巨魔做了巨大的贡献，整个村庄都对你感激不尽。"}},faq={{q="谁派你踏上这段旅程的？",a="断齿长者请求你将他获救的消息带给他的配偶。",al={"谁开启了回到断齿族长身边","断齿长者任务发布者"}},{q="断齿族长在哪里？",a="断齿族长位于辛特兰的恶齿村。",al={"断齿族长在哪里","断齿族长位置","回到断齿族长身边的交任务地点"}},{q="我该告诉断齿族长什么？",a="告诉她断齿长者正要回家。",al={"要告诉断齿族长什么","断齿消息"}},{q="这段旅程之前发生了什么？",a="这是在“取回钥匙！”之后进行的任务，而之前的努力始于“被绑架的断齿长者！”",al={"前置任务","断齿族长任务链"}}},fp="25,98,17.139.0,23.100.1,30.65.0,33.59.0,43.56.0,30.96.0"}
P.entries["quest:7849"] = {n="分离的痛苦",s="恶齿村的猎户马克霍尔失去了他的孪生兄弟马尔霍尔。那次袭击中，邪枝巨魔不仅掳走了托恩塔斯克的配偶，也抓走了马尔霍尔。马尔霍尔遭遇了残酷而迅速的死亡，他的遗骸被邪枝巨魔喂给了软泥怪和狼群。马克霍尔说他兄弟的生命已无法挽回，但他的灵魂尚可救赎，因此他请求你帮他找回遗骸。",h="恶齿村的猎户马克霍尔失去了他的孪生兄弟马尔霍尔。那次袭击中，邪枝巨魔不仅掳走了托恩塔斯克的配偶，也抓走了马尔霍尔。马尔霍尔遭遇了残酷而迅速的死亡，他的遗骸被邪枝巨魔喂给了软泥怪和狼群。马克霍尔说他兄弟的生命已无法挽回，但...",kw={"骨头","辛特兰","辛萨罗","马尔霍尔","马克霍尔","恶齿","头骨","邪枝","亚约金"},sec={{t="孪生兄弟的损失",b="马克霍尔说，村里有许多人都在荒野中失去了挚爱，他失去的亲人就是他的孪生兄弟马尔霍尔。邪枝巨魔在袭击托恩塔斯克的配偶时也带走了马尔霍尔。马尔霍尔命中注定难逃一劫，他的俘虏们残忍地杀害了他。"},{t="遗骸所在之处",b="邪枝巨魔把马尔霍尔剩下的残骸喂给了他们的软泥怪和狼群。辛萨罗神庙顶部附近有一个充斥着软泥怪的垃圾坑，还有一个狼穴。他的骨头就在顶层附近的一个淤泥坑里，而他的头骨则位于神庙的最顶层。马克霍尔打算把这些遗骸带给亚约金，由他来准备安葬事宜。"}},faq={{q="猎户马尔霍尔是谁？",a="马尔霍尔是猎户马克霍尔的孪生兄弟。邪枝巨魔在袭击托恩塔斯克的配偶时也带走了他，并残酷地杀害了他。",al={"马尔霍尔是谁","马克霍尔的兄弟","马尔霍尔背景故事"}},{q="马尔霍尔的遗骸被带到了哪里？",a="邪枝巨魔把他的遗骸喂给了软泥怪和狼群。他的头骨就在辛萨罗的最顶层，而他的骨头则在顶层附近的一个淤泥坑里。",al={"骨头在哪里","马尔霍尔的头骨在哪里","辛萨罗遗骸"}},{q="谁来为马尔霍尔准备安葬？",a="马克霍尔说他会把遗骸带给亚约金，由他来准备安葬事宜。",al={"马尔霍尔的葬礼","亚约金是谁","亚约金"}},{q="为什么马克霍尔需要找回骨头？",a="马克霍尔知道无法再挽救他兄弟的生命，但他认为兄弟的灵魂尚可救赎。为了做到这一点，他希望找回那些遗骸。",al={"为什么要找回遗骸","拯救马尔霍尔的灵魂","拯救他的灵魂"}}},fp="18,263,13.260.0,21.338.0,25.150.0,35.158.0,36.91.0,41.148.0"}
P.entries["quest:7850"] = {n="黑暗之瓶",s="恶齿村的断齿族长说邪枝巨魔拥有超自然的狂暴力量，这是邪恶的女祭司赫克斯施展邪恶魔法的结果。在辛萨罗各处散落着被污染的鲜血容器，它们散发出属于无面血神的邪恶魔法。断齿族长请求你将它们偷回来，以便消除这些污染。",h="恶齿村的断齿族长说邪枝巨魔拥有超自然的狂暴力量，这是邪恶的女祭司赫克斯施展邪恶魔法的结果。在辛萨罗各处散落着被污染的鲜血容器，它们散发出属于无面血神的邪恶魔法。断齿族长请求你将它们偷回来，以便消除这些污染。",kw={"血神","暗影容器","辛萨罗","断齿族长","恶齿村","被污染的鲜血","邪恶的女祭司赫克斯","邪枝巨魔"},sec={{t="邪枝的狂暴",b="你在辛萨罗的任何地方行走，都会发现被污染的鲜血容器。它们散发出无面血神的黑暗力量，这增强了邪枝巨魔的力量并驱使他们陷入疯狂。断齿族长相信，取走这些容器并消除其中的污染，可以减弱血神对他们的控制。"},{t="归还容器之后",b="随着容器到手，控制邪枝巨魔的黑暗能量被解除了，尽管只是暂时的。断齿族长提醒你要时刻警惕邪恶，因为倒下的女祭司很快就会被别人取代。"}},faq={{q="谁发布了“暗影容器”任务？",a="由辛特兰恶齿村的断齿族长发布。",al={"谁发布暗影容器任务","暗影容器任务发布者"}},{q="被污染的容器在哪里？",a="被污染的鲜血容器可以在辛特兰的辛萨罗各处找到。",al={"暗影容器在哪里","被污染的鲜血容器位置","寻找被污染的鲜血"}},{q="为什么邪枝巨魔如此狂暴？",a="断齿族长认为是邪恶的女祭司赫克斯施展的邪恶魔法所致。被污染的鲜血容器也带有无面血神的力量，这增强了邪枝巨魔的力量并驱使他们发疯。",al={"为什么邪枝巨魔会疯狂","邪枝巨魔的疯狂","邪枝巨魔的狂暴"}},{q="断齿族长打算如何处理这些容器？",a="断齿族长计划消除其中的污染，以减弱无面血神对邪枝巨魔的控制。",al={"为什么要收集这些容器","鲜血容器会发生什么"}}},fp="12,227,19.251.0,24.181.1,33.66.0,38.72.0,43.184.0,54.97.0"}
P.entries["quest:786"] = {n="科卡尔半人马的进攻",s="“挫败科卡尔的侵略”是一项由侦察兵拉尔·猎齿在森金村附近发布的至关重要的部落防御任务。玩家的任务是潜入科卡尔峭壁，在半人马部族袭击杜隆塔尔初建的定居点之前，摧毁三份协调一致的入侵计划。",h="“挫败科卡尔的侵略”是一项由侦察兵拉尔·猎齿在森金村附近发布的至关重要的部落防御任务。玩家的任务是潜入科卡尔峭壁，在半人马部族袭击杜隆塔尔初建的定居点之前，摧毁三份协调一致的入侵计划。",kw={"杜隆塔尔","科卡尔","科卡尔峭壁","拉尔·猎齿","奥格瑞玛","森金村","挫败科卡尔的侵略","试炼谷"},ang={["faction:Horde"]="阻止科卡尔的进攻使新生的部落免于在其新家园的门口被迫进行一场艰苦的多线领土战争。",["race:Orc"]="试炼谷是年轻兽人举行成年仪式的地方，因此在那里发生的半人马侵略是对兽人战士文化的极大侮辱。",["race:Troll"]="暗矛巨魔本已失去了古老的岛屿家园，他们无法承担让森金村被劫掠的半人马淹没的代价。"},sec={{t="迫在眉睫的入侵",b="当拉尔·猎齿在杜隆塔尔西部进行侦察时，这名巨魔追踪者潜入了科卡尔峭壁。他所发现的情况令人震惊：科卡尔半人马不仅在进行无组织的沿海突袭，还在策划一场雄心勃勃的三路入侵，目标直指兽人和暗矛巨魔的家园。半人马军阀将他们的战斗策略分派给三位不同的首领，意图袭击试炼谷、森金村以及奥格瑞玛的大门本身。"},{t="突袭峡谷",b="为了避免在杜隆塔尔干燥的红色峡谷中爆发灾难性的战斗，新兵被派往科卡尔峭壁深处，擒贼先擒王。潜入尘土飞扬的营地并烧毁三份进攻卷轴，可以破坏半人马的指挥链。尽管拉尔·猎齿坚信部落必然能击溃任何全面入侵，但摧毁这些文件能让杜隆塔尔的守军免受代价高昂的流血牺牲，毕竟这个年轻的国度才刚刚站稳脚跟。"}},faq={{q="谁提供了“挫败科卡尔的侵略”这个任务？",a="该任务由拉尔·猎齿提供，他是一位驻扎在杜隆塔尔南部悬崖边、森金村外不远处的暗矛巨魔侦察兵。",al={"任务发布者","谁给任务","拉尔·猎齿位置"}},{q="科卡尔半人马计划袭击哪些目标？",a="科卡尔的作战计划概述了一场协调一致的三层进攻，目标分别为试炼谷、森金村和部落首都奥格瑞玛。",al={"半人马攻击目标","什么是进攻计划","三个目标"}},{q="科卡尔峭壁位于哪里？",a="科卡尔峭壁是一片被太阳炙烤的峡谷群，坐落在杜隆塔尔南部，从森金村翻过岩石山脊向西即可到达。",al={"科卡尔峭壁位置","峭壁在哪里","杜隆塔尔半人马村庄"}},{q="在峭壁内哪里可以找到进攻计划？",a="载有入侵蓝图的三份卷轴分别由驻守在峭壁各处不同营地的三位科卡尔首领保管。",al={"进攻计划地点","卷轴在哪里","半人马首领"}},{q="为什么科卡尔人想要入侵杜隆塔尔？",a="科卡尔是一个极具侵略性的扩张主义半人马部族，土生土长于卡利姆多的干燥土地上。他们视新来的兽人和暗矛巨魔为入侵者，认为他们侵犯了自己的领地和狩猎场。",al={"为什么半人马要攻击","半人马动机","科卡尔背景传说"}},{q="销毁计划后会发生什么？",a="摧毁这些文件可以阻止一场协调一致的围攻，使科卡尔的战术进攻陷入混乱，保护杜隆塔尔脆弱的定居点免受突如其来的毁灭。",al={"任务后续影响","半人马进攻是否停止"}}},fp="27,194,18.307.0,20.334.0,49.118.0,55.86.0,29.86.0,49.80.0,41.174.0,43.117.0"}
P.entries["quest:7861"] = {n="通缉：邪恶祭司海克斯和她的爪牙",s="断齿族长下令必须将邪恶的女祭司海克斯和她的爪牙绳之以法，任何击杀这位女祭司及其精英阿曼扎希卫兵的人都将获得丰厚的奖赏。你可以在辛特兰的辛萨罗之巅找到他们。",h="断齿族长下令必须将邪恶的女祭司海克斯和她的爪牙绳之以法，任何击杀这位女祭司及其精英阿曼扎希卫兵的人都将获得丰厚的奖赏。你可以在辛特兰的辛萨罗之巅找到他们。",kw={"阿曼扎希","海克斯","辛特兰","辛萨罗","断齿族长","恶齿村","邪恶的女祭司海克斯","邪恶枝族"},sec={{t="突袭辛萨罗",b="断齿族长下令必须将邪恶的女祭司海克斯和她的爪牙绳之以法。目标是女祭司本人以及她的精英阿曼扎希卫兵。他们就在辛特兰的辛萨罗之巅。一旦将其击杀，就回到恶齿村向断齿族长报告。"}},faq={{q="是谁发布了针对邪恶的女祭司海克斯的悬赏？",a="这份号召令由断齿族长下达，任何击杀女祭司及其卫兵的人都将获得丰厚的奖励。",al={"谁想要海克斯死","谁发布了这个悬赏","女祭司海克斯任务发布者"}},{q="在哪里可以找到邪恶的女祭司海克斯和她的卫兵？",a="他们在辛特兰的辛萨罗之巅。",al={"海克斯在哪里","邪恶的女祭司海克斯位置","阿曼扎希卫兵位置"}},{q="必须击杀谁才能完成悬赏？",a="邪恶枝族的女祭司海克斯本人，以及她的阿曼扎希精英卫兵。",al={"海克斯悬赏目标","杀谁来完成海克斯的任务"}},{q="在哪里交付悬赏？",a="在击杀女祭司和她的卫兵后，向恶齿村的断齿族长报告。",al={"海克斯悬赏在哪里交付","断齿族长位置"}}},fp="43,172,23.223.0,46.100.0,54.75.0,40.68.0,30.90.0"}
P.entries["quest:7862"] = {n="职位空缺：恶齿村卫兵队长",s="卫兵队长马尔科尔下落不明，恶齿村的卫兵部队需要一位新队长。任何有意担任此职的人都必须消灭邪枝狂战士、暗影猎手、饮血者和噬魂者，然后将申请书提交给位于辛特兰的断齿族长。",h="卫兵队长马尔科尔下落不明，恶齿村的卫兵部队需要一位新队长。任何有意担任此职的人都必须消灭邪枝狂战士、暗影猎手、饮血者和噬魂者，然后将申请书提交给位于辛特兰的断齿族长。",kw={"狂战士","饮血者","卫兵队长","马尔科尔","恶齿","暗影猎手","噬魂者","断齿","邪枝"},sec={{t="空缺的职位",b="一份征兵公告显示，卫兵队长马尔科尔下落不明，因此恶齿村的卫兵部队再次失去了队长。任何想要领导卫兵部队的人，都需要完成公告中列出的任务，并将申请书递交给断齿族长。"},{t="证明价值",b="申请人需要消灭四种邪枝巨魔：狂战士、暗影猎手、饮血者和噬魂者。完成后，回到恶齿村找断齿族长复命。"}},faq={{q="为什么卫兵队长的职位空缺？",a="卫兵队长马尔科尔下落不明，公告称恶齿村的队长职位再次空缺。",al={"为什么卫兵队长职位空缺","马尔科尔发生了什么事","谁是上一任队长"}},{q="在消灭敌人后，应该向谁提交申请？",a="申请应提交给恶齿村的断齿族长。",al={"我应该向谁交任务","在哪里提交申请","谁来评估申请人"}},{q="为了获得资格，必须击败哪些敌人？",a="申请人必须消灭邪枝狂战士、暗影猎手、饮血者和噬魂者。",al={"要杀死哪些邪枝巨魔","职位空缺目标","为了担任卫兵队长我该杀谁"}}},fp="47,162,13.211.0,13.153.0,42.67.0,56.62.0,42.93.0"}
P.entries["quest:78676"] = {n="The Eye of Bhossca",s="C让你去寻找据说位于血色修道院内的Bhossca之眼。有人想要这件神器，并要求将它送回焚木村附近的一个秘密接头点。",h="C让你去寻找据说位于血色修道院内的Bhossca之眼。有人想要这件神器，并要求将它送回焚木村附近的一个秘密接头点。",kw={"神器","bhossca","c","秘密接头点","伪装","bhossca之眼","焚木村","血色修道院"},sec={{t="C的委托",b="焚木村附近的箱子里有一张字条，上面是C的新委托。据说Bhossca之眼就在血色修道院某处，C想让你把它带回来。和影牙城堡那次一样，你必须独自潜入。修道院内或许能找到伪装，方便你行动。"}},faq={{q="谁想要这只眼睛？",a="C让你取回Bhossca之眼，并将它带到焚木村附近的秘密接头点。",al={"谁想要它","c是谁","c索要眼睛"}},{q="Bhossca之眼在哪里？",a="C的线人称，Bhossca之眼在血色修道院内的某处。",al={"眼睛在哪","眼睛的位置","寻找bhossca"}},{q="C为什么想要这只眼睛？",a="C称Bhossca之眼是一件神器，并说它是最近令人觊觎的物品。",al={"为什么要眼睛","c想拿它做什么","为什么要取回它"}},{q="我该把眼睛带到哪里？",a="你要把Bhossca之眼送回C在焚木村附近的秘密接头点。",al={"送回哪里","秘密接头点位置","箱子在哪里"}},{q="我必须独自前往吗？",a="C要求你独自进入血色修道院，并独自完成任务。",al={"要独自行动吗","能带帮手吗","独自取眼睛"}},{q="伪装会有帮助吗？",a="C说，伪装或许能让你更方便地行动，并建议你在修道院内找找看。",al={"眼睛与伪装","需要伪装吗","伪装在哪里"}}},fp="18,145,11.282.0,26.92.0,28.76.0,24.82.0,24.65.0,22.79.0,22.105.0"}
P.entries["quest:78699"] = {n="The Eye of Bhossca",s="箱子里有一张留给你的便笺。写信人只署了首字母 C。",h="箱子里有一张留给你的便笺。写信人只署了首字母 C。",kw={"bhossca","c","箱子","eye of bhossca","留意消息","便笺"},sec={{t="便笺",b="箱子里有一张写给你的便笺。写信人说会留意你的消息，随后署上字母 C。"}},faq={{q="是谁留下了便笺？",a="便笺署名只有首字母 C，没有写出全名。",al={"c 是谁","是谁写的","c 写的便笺"}},{q="便笺上写了什么？",a="写信人告诉你会留意你的消息，并署上首字母 C。",al={"箱子里有什么","eye of bhossca 便笺","c 写了什么"}},{q="便笺在哪里？",a="便笺放在一个箱子里。",al={"便笺在哪里","箱子里的便笺"}}},fp="18,74,8.119.0,18.61.0,23.84.0,18.25.0"}
P.entries["quest:787"] = {n="新的部落",s="“新部落”是试炼谷的一项入门任务，由老兵伊崔格指派。任务引导新兵向大兽穴内的高内克报到，以开始他们的训练。通过这次简短的召集，伊崔格分享了他个人的经历，以及萨尔对于救赎后的部落所构想的愿景。",h="“新部落”是试炼谷的一项入门任务，由老兵伊崔格指派。任务引导新兵向大兽穴内的高内克报到，以开始他们的训练。通过这次简短的召集，伊崔格分享了他个人的经历，以及萨尔对于救赎后的部落所构想的愿景。",kw={"燃烧军团","杜隆塔尔","伊崔格","高内克","新部落","大兽穴","萨尔","试炼谷"},ang={["faction:Horde"]="这项任务概括了萨尔政权建立的基本精神：彻底断绝恶魔的奴役，转而追求荣誉、生存和祖先的身份认同。",["race:Orc"]="对于走进试炼谷的年轻兽人来说，伊崔格代表了他们种族悲惨过去的鲜活记忆，以及他们在萨尔领导下的救赎。",["race:Troll"]="暗矛巨魔在试炼谷与兽人并肩训练，他们已经拥抱了萨尔关于相互生存和荣誉的愿景。"},sec={{t="老兵的回归",b="伊崔格站在试炼谷，受大酋长萨尔之命负责评估和指导部落最新的希望之星。他在第二次战争后因对旧部落被燃烧军团腐蚀感到幻灭而离开，并在流亡中隐居，直到被人类俘虏。在被萨尔救出后，得知这位年轻大酋长的梦想——一个植根于萨满教义、彻底切断与恶魔主子联系的荣誉部落——他选择了回归。"},{t="向大兽穴报到",b="任何新兵在冒险走出试炼谷那崎岖的峡谷之前，都必须证明自己的实力。伊崔格会派遣新人进入被称为“大兽穴”的阴凉洞穴去见高内克。虽然高内克对新加入的应募者那粗糙的状态几乎从不委婉评价，但他的监督确保了只有那些掌握了纪律与生存之道的人，才被允许进入杜隆塔尔的更广阔天地。"}},faq={{q="谁是伊崔格？",a="伊崔格是一位年迈的兽人老兵，曾亲眼目睹了旧部落在燃烧军团影响下的堕落。心灰意冷之下，他在洛丹伦选择了自我流放。在被人类俘虏并随后被萨尔解放后，他向萨尔新改组的部落宣誓效忠，现在协助监督在试炼谷的新兵训练。",al={"谁是伊崔格","伊崔格背景故事","伊崔格背景知识"}},{q="为什么伊崔格会谈论“新部落”？",a="最初的部落曾在燃烧军团的摆布下被恶魔的嗜血冲动所操纵和奴役。萨尔建立的新部落旨在抛弃恶魔的控制，复兴传统的萨满之道，并为卡利姆多的兽人及其盟友建立一个荣耀、自主的未来。",al={"什么是新部落","新旧部落的区别","新部落的含义"}},{q="高内克在哪里？",a="高内克驻扎在大兽穴的入口处，那是试炼谷北侧岩壁上开凿出的一处显眼的洞穴。",al={"高内克在哪里","找到高内克","高内克位置"}},{q="向高内克报到后会发生什么？",a="高内克会接纳你成为伊崔格的学员之一，并交给你最初的实地任务，让你通过保卫山谷来投入工作，并测试你为部落效力的准备情况。",al={"新部落任务后的下一个任务","高内克做什么","高内克任务"}},{q="伊崔格为何被流放？",a="伊崔格离开部落是因为他对早期战争中术士侍奉燃烧军团所造成的恶魔腐蚀和毫无意义的屠杀感到厌恶。",al={"伊崔格为什么离开","伊崔格流放原因","伊崔格恶魔腐蚀"}},{q="为什么新兵要在试炼谷受训？",a="试炼谷为杜隆塔尔的年轻兽人和盟友新人提供了一个隐蔽、崎岖的环境，让他们在踏入更广阔的世界之前，能在老兵教官的注视下应对凶猛的野兽和蝎虫。",al={"为什么要试炼谷","试炼谷的目的","试炼谷训练"}}},fp="13,193,18.420.0,20.300.0,15.309.0,44.243.0,24.115.0,39.181.0,23.158.0,49.204.0"}
P.entries["quest:7881"] = {n="狂欢节长靴",s="暗月马戏团的工人向技艺精湛的工匠寻求结实耐穿的靴子。马戏团工作人员会用珍贵的马戏团奖券，换取上乘靴子。",h="暗月马戏团的工人向技艺精湛的工匠寻求结实耐穿的靴子。马戏团工作人员会用珍贵的马戏团奖券，换取上乘靴子。",kw={"马戏团","马戏团靴子","做工","暗月马戏团","暗月马戏团奖券"},sec={{t="马戏团靴子",b="采集者和工匠会把结实耐穿的马戏团靴子带到暗月马戏团，工作人员则用珍贵的奖券换取上乘靴子。每双靴子都能让巡回马戏团继续前行。"}},faq={{q="暗月马戏团为什么需要靴子？",a="暗月马戏团收购结实耐穿、做工精良的靴子，以保障工作人员和马戏团场地的运作，并以奖券作为交换。",al={"马戏团靴子的用途","暗月马戏团为什么需要靴子"}},{q="暗月马戏团奖券有什么用？",a="从马戏团获得的奖券可以收集起来，兑换暗月马戏团的各种奖品和奇珍异宝。",al={"暗月马戏团奖券能兑换什么","马戏团奖券的用途"}},{q="马戏团收购什么样的靴子？",a="马戏团工作人员会检查靴子的做工和耐用性，确认上乘后才会交付奖券。",al={"暗月马戏团靴子交易","马戏团靴子要求"}}},fp="14,153,22.199.0,39.134.0,41.110.0,44.106.0"}
P.entries["quest:78823"] = {n="Terror of the Desert Skies",s="一幅粗糙的绘画描绘了一只令人既恐惧又敬畏的大型猛禽。荆棘谷的赫米特·奈辛瓦里或许知道更多。",h="一幅粗糙的绘画描绘了一只令人既恐惧又敬畏的大型猛禽。荆棘谷的赫米特·奈辛瓦里或许知道更多。",kw={"猛禽","赫米特·奈辛瓦里","粗糙的绘画","荆棘谷","terror of the desert skies"},sec={{t="令人恐惧的影像",b="有人请你将粗糙的绘画带给荆棘谷的赫米特·奈辛瓦里。画上的粗犷笔触勾勒出一只大型猛禽，画师的恐惧与敬畏跃然纸上。赫米特受托辨认画中所绘。"}},faq={{q="这幅画描绘的是什么？",a="粗糙的绘画描绘了一只大型猛禽。",al={"猛禽绘画","画中是什么"}},{q="谁能告诉我这只鸟的情况？",a="荆棘谷的赫米特·奈辛瓦里或许能告诉你更多关于这种生物的事。",al={"谁了解它","猛禽专家"}},{q="我该把画带到哪里？",a="把粗糙的绘画交给荆棘谷的赫米特·奈辛瓦里。",al={"绘画交给谁","赫米特绘画"}}},fp="26,133,15.242.0,27.51.0,31.87.0,28.70.0"}
P.entries["quest:78830"] = {n="Terror of the Desert Skies",s="赫米特·奈辛瓦里听说过 Gharrik，那是一只在荒芜之地捕猎的大鸟。他借给你一个笼子，用来捕捉活饵，并想要她的一根翎羽。",h="赫米特·奈辛瓦里听说过 Gharrik，那是一只在荒芜之地捕猎的大鸟。他借给你一个笼子，用来捕捉活饵，并想要她的一根翎羽。",kw={"荒芜之地","卡格营地","深红色战利品翎羽","gharrik","大鸟","赫米特·奈辛瓦里","活饵"},sec={{t="沙漠猎手",b="一幅画让赫米特·奈辛瓦里想起了 Gharrik，他在另一次远征中听说过她。据说这只大鸟是荒芜之地的顶级掠食者。有人请你前往卡格营地东北方向寻找她，她最后一次在那里被发现，并用活饵将她引出来。荒芜之地的小型野生动物稀少，所以赫米特借给你一个笼子，让你去别处捕捉活饵。他希望得到 Gharrik 的一根翎羽。"}},faq={{q="Gharrik 是谁？",a="据说 Gharrik 是荒芜之地的顶级掠食者，是一只大鸟。",al={"gharrik 大鸟","沙漠大鸟","gharrik 是谁"}},{q="最后一次在哪里发现 Gharrik？",a="最后一次有人在荒芜之地的卡格营地东北方向发现 Gharrik。",al={"gharrik 位置","gharrik 在哪里","卡格营地东北方向"}},{q="赫米特为什么想要一根翎羽？",a="赫米特说，Gharrik 的一根翎羽会是很棒的战利品，还能让你成为营地里的谈资。",al={"gharrik 翎羽","翎羽战利品","为什么要翎羽"}},{q="哪里能找到活饵？",a="荒芜之地的小型野生动物稀少，所以赫米特让你去别处寻找活饵，并借给你一个笼子来捕捉一些。",al={"活饵","给 gharrik 的活饵","笼子 活饵"}},{q="是谁派我去找 Gharrik？",a="赫米特·奈辛瓦里请你去寻找 Gharrik，并带回她的一根翎羽。",al={"gharrik 任务发布者","赫米特 gharrik","谁想要翎羽"}}},fp="26,142,15.407.0,15.68.0,28.64.0,28.90.0,24.119.0,26.75.0"}
P.entries["quest:789"] = {n="工蝎的尾巴",s="“蝎尾之毒”是高内克交给试炼谷大兽穴中部落新兵的一项早期试炼。新手们需要前往营地西北方猎杀毒蝎工蜂，并带回十根尾巴，以证明他们的战斗准备已经就绪。这项任务旨在通过实战来教会新兵如何在战场险境中生存，以及无论对手多么弱小都不能轻视。",h="“蝎尾之毒”是高内克交给试炼谷大兽穴中部落新兵的一项早期试炼。新手们需要前往营地西北方猎杀毒蝎工蜂，并带回十根尾巴，以证明他们的战斗准备已经就绪。这项任务旨在通过实战来教会新兵如何在战场险境中生存，以及无论对手多么弱小都...",kw={"解药","杜隆塔尔","高内克","蝎子","蝎子工蜂","蝎尾之毒","大兽穴","试炼谷","剧毒"},ang={["class:Warrior"]="高内克将蝎子狩猎视为磨练战斗意志的基础课程，提醒战士们决断的打击可以克服坚硬的甲壳，而对弱小敌人的傲慢则会引致失败。",["race:Orc"]="对于在试炼谷成年的年轻兽人来说，猎杀剧毒蝎子是一项由高内克监督的必要试炼，旨在考验他们的耐力和战场意识。",["race:Troll"]="与部落一同在试炼谷进行训练的暗矛巨魔，也必须在深入杜隆塔尔之前证明他们对抗当地蝎子的勇武。"},sec={{t="毒刺的试炼",b="在烈日炙烤的试炼谷峡谷中，高内克通过让他们对抗当地野生生物来考验部落新兵。大兽穴西北方干旱土地上游荡的剧毒蝎子，曾让经验丰富的战士和笨拙的初学者同样吃过苦头。为了证明他们的战场能力，年轻的勇士必须深入岩石地带，击杀蝎子工蜂，并带回十根被切下的尾巴作为武艺的证明。"},{t="剧毒与警惕",b="虽然这些剧毒捕食者十分致命，但它们也为受伤的新手提供了救命良药。大兽穴储备有直接从蝎毒中提取并酿制而成的抗毒剂，专门用于救治受伤的新手。除了如何规避毒素之外，高内克还强调了一个核心的战术道理：在激烈的战场上，傲慢是致命的，即使是最小的敌人也足以用其致命的毒素放倒强大的战士。"}},faq={{q="谁发布了“蝎尾之毒”任务？",a="高内克，负责监督试炼谷大兽穴新兵训练的战歌军官，会向年轻的战士和冒险者发布此项试炼。",al={"谁发布蝎尾之毒","蝎子任务发布者","高内克任务"}},{q="蝎子在哪里？",a="蝎子工蜂大量栖息在试炼谷大兽穴的正西北方，在干旱的红色峡谷地形中游荡。",al={"哪里寻找蝎子","蝎子位置","试炼谷蝎子"}},{q="高内克要求从狩猎中带回什么？",a="高内克要求带回十根蝎子工蜂的尾巴，作为新兵已经面对过这些剧毒野兽并取得战斗胜利的确凿证据。",al={"蝎子掉落什么","蝎子任务物品","蝎子尾巴"}},{q="如何制造蝎毒解药？",a="蝎毒解药是直接从这些生物的毒刺中提取毒液酿制而成的。大兽穴储备有充足的解药，用于治疗那些低估了猎物的小看者。",al={"蝎毒治疗","解药设定","蝎毒解药如何制作"}},{q="高内克希望新兵学到什么教训？",a="高内克利用这次狩猎来教导新手战士，任何对手，无论大小，都具备致命的潜力。在面对看似弱小的生物时，战场上的过度自信很快就会导致死亡。",al={"高内克的教诲","为什么要猎杀蝎子","蝎子试炼目的"}},{q="在这场狩猎之后，高内克是否提供进一步的训练？",a="在交回尾巴后，高内克会表示他在大兽穴没什么可以再教你的了，并让你前往杜隆塔尔继续为部落效力。",al={"蝎尾之毒后要做什么","高内克的下一个任务","高内克是否教导更多内容"}}},fp="20,154,20.271.0,19.277.0,33.122.0,31.66.0,39.103.0,46.138.0,47.135.0,51.138.0"}
P.entries["quest:7890"] = {n="Heavy Grinding Stone",s="一位游园会工作人员请你带来重型磨刀石。交货后，你会获得游园会门票。",h="一位游园会工作人员请你带来重型磨刀石。交货后，你会获得游园会门票。",kw={"游园会","磨刀石","重型磨刀石","甜食","门票"},sec={{t="游园会",b="工作人员向你道谢，说这些石头已经让他们的肌肉开始变得结实。作为回报，你会得到门票。对方还提醒你别吃太多甜食，要保持强健，随时准备战斗。"}},faq={{q="工作人员想要什么？",a="工作人员想要重型磨刀石。",al={"重型磨刀石是什么","游园会用的石头"}},{q="带来石头能得到什么？",a="工作人员会给你游园会门票。",al={"石头门票","游园会门票"}},{q="工作人员为什么提到甜食？",a="工作人员提醒你别吃太多甜食，还说你需要保持战斗状态。",al={"吃太多甜食","游园会甜食"}}},fp="20,101,12.221.0,29.42.0,38.46.0,38.95.0"}
P.entries["quest:79"] = {n="斯塔文的传说",s="这个任务标志着关于斯塔文·密斯特曼托的零散传言汇聚成了无可辩驳的残酷罪证。旅店老板斯密茨交出了长期隐藏的沾满泥污的日记书页，并指引调查者直接去找夜色镇的指挥官阿尔泰娅·埃伯洛克。",h="这个任务标志着关于斯塔文·密斯特曼托的零散传言汇聚成了无可辩驳的残酷罪证。旅店老板斯密茨交出了长期隐藏的沾满泥污的日记书页，并指引调查者直接去找夜色镇的指挥官阿尔泰娅·埃伯洛克。",kw={"夜色镇","暮色森林","埃伯洛克","调查","密斯特曼托","沾满泥污的日记","夜色守夜人","斯密茨","斯塔文"},ang={["class:Paladin"]="将尘封已久的谋杀案公之于众，履行了圣骑士的使命，要求为在暮色森林阴影中惨遭杀害的无辜生命伸张正义。",["class:Rogue"]="在酒馆和布满灰尘的箱子之间拼凑笔迹样本，体现了追踪难以捉摸的猎物时通常所需的耐心侦探工作。",["faction:Alliance"]="这项调查展示了在暴风城的官方支持完全缺席时，南部地区必须依靠游荡的联盟英雄来执行正义。"},sec={{t="夜色镇的突破",b="多年来，一个来访贵族家庭的凄惨命运一直是暮色森林中一桩未解的悲剧。旅店老板斯密茨和当时担任暴风城卫队队长的哈格德警官最初调查了屠杀现场，并发现了几页撕裂且沾满泥污的日记。由于缺乏笔迹样本或佐证文件，这些记录一直未能取得进展，无法正式指控传闻中隐居在荒野里的那个人。在艾尔文森林、西部荒野和暮色森林收集到的证据最终将笔迹与斯塔文·密斯特曼托联系了起来，将镇上的流言转变成了一起证据确凿的谋杀案。"},{t="诉诸卫兵",b="夜色镇一直生活在亡灵、野兽以及潜伏在森林阴影中更可怕的威胁的持续围困之下。当城镇的生存都岌岌可危时，指挥官阿尔泰娅·埃伯洛克对于无稽之谈或毫无根据的怀疑几乎没有耐心。交出这些沾满泥污的书页，架起了冰冷的历史与即时军事正义之间的桥梁。在暮色森林的土地上看到屠杀的确凿证据后，夜色守夜人终于被迫承认斯塔文·密斯特曼托不仅仅是一个古怪的隐士或鬼故事的主角，而是一个必须绳之以法的危险逃犯。"}},faq={{q="旅店老板斯密茨一直掌握着什么证据？",a="几年前，斯密茨曾与哈格德一起调查那场来访贵族的屠杀事件。他们在现场找回了撕裂且沾满泥污的日记书页，但直到现在才缺乏匹配的笔迹样本来证明斯塔文·密斯特曼托就是作者。",al={"斯密茨 日记书页","沾满泥污的日记书页","斯密茨发现了什么"}},{q="为什么斯密茨没有早点向埃伯洛克指挥官报告这件事？",a="由于缺乏将沾满泥污的书页上的笔迹与那位隐居的家庭教师联系起来的证据，斯密茨和哈格德当时只有一些推测性的碎片。向埃伯洛克指挥官呈报未经证实的谣言，会被视为对夜色守夜人紧缺人力的无用浪费，从而被驳回。",al={"为什么等这么久","为什么要隐瞒这些书页","为什么斯密茨不告诉卫兵"}},{q="指挥官阿尔泰娅·埃伯洛克是谁？",a="指挥官阿尔泰娅·埃伯洛克是夜色守夜人的首领，这是一支负责守卫夜色镇并在暮色森林的道路上巡逻，以抵御亡灵和森林掠食者的城镇民兵组织。",al={"埃伯洛克是谁","阿尔泰娅·埃伯洛克的职责","夜色镇指挥官"}},{q="暮色森林发生了什么大屠杀？",a="几年前，一个来访的贵族家庭在暮色森林中遭到屠杀。虽然传言指向他们以前的家庭教师斯塔文·密斯特曼托，但当地调查人员最初缺乏指控他所需的决定性证据。",al={"什么屠杀","贵族被屠杀","谁被谋杀了"}},{q="这一步骤在整体调查中处于什么位置？",a="这一步代表了从私人调查向正式司法的过渡。在查阅了三个地区的登记册、学校记录和家庭箱子后，你将收集到的证据交给地方当局，以批准对斯塔文采取行动。",al={"斯塔文任务线进度","进行到哪一步了","这是任务的终点吗"}},{q="为什么夜色守夜人如此不情愿调查旧案？",a="夜色镇每天都面临着被游荡的憎恶、狼人族群和蜘蛛毁灭的直接威胁。埃伯洛克指挥官必须将所有可用的守夜人集中在生存问题上，这意味着冷案在得到无可辩驳的证据之前，她不会分出人力去调查。",al={"为什么埃伯洛克很忙","夜色镇防御优先级","夜色守夜人的优先事项"}}},fp="21,154,27.512.0,22.452.1,51.215.0,61.186.0,34.169.0,37.179.0,56.226.0,62.210.0"}
P.entries["quest:7900"] = {n="Torn Bear Pelts",s="你把撕裂的熊皮交给一位打算将它们缝成毛绒玩具的人，对方会用票券作为报酬。",h="你把撕裂的熊皮交给一位打算将它们缝成毛绒玩具的人，对方会用票券作为报酬。",kw={"熊皮","颜料","毛绒玩具","填充物","票券","撕裂的熊皮"},sec={{t="另作他用",b="收取熊皮的人打算把它们缝成毛绒玩具，再填入填充物并涂上颜料。他们会用票券作为报酬。"}},faq={{q="这些熊皮有什么用？",a="它们要被缝成毛绒玩具，再填入填充物并涂上颜料。",al={"撕裂的熊皮用途","熊皮能做什么"}},{q="熊皮能换到什么？",a="收取熊皮的人会用票券作为报酬。",al={"熊皮报酬","熊皮票券"}},{q="谁会缝制玩具？",a="收取熊皮的人说，会有人把熊皮缝成毛绒玩具。",al={"谁制作毛绒玩具","谁缝制熊皮"}}},fp="15,113,9.124.0,28.69.0,28.44.0,22.62.0"}
P.entries["quest:79007"] = {n="... and that note you found",s="“……以及你找到的那张便条”始于一个不久前废弃的营地，营火余烬尚存，补给散落一地。余烬之中躺着一张被烧焦起泡的羊皮纸，上面写着一条关于寻找“双生之地”的谜语。由于没有其他向导，这张烧焦的残片成为了追寻遗留之物的唯一线索。",h="“……以及你找到的那张便条”始于一个不久前废弃的营地，营火余烬尚存，补给散落一地。余烬之中躺着一张被烧焦起泡的羊皮纸，上面写着一条关于寻找“双生之地”的谜语。由于没有其他向导，这张烧焦的残片成为了追寻遗留之物的唯一线索。",kw={"以及你找到的那张便条","起泡的便条","烧焦的便条","余烬","最近的营火","散落的物资","双生之地"},sec={{t="荒野余烬",b="在最近的一次营火的余温和散落的物资旁，躺着一张受损且起泡的纸。曾在此处停留的人不久前刚刚离开，只留下了正在冷却的余烬和一张险些被火焰吞噬的羊皮纸残片。现场迹象显示离开时非常匆忙或突发状况导致，物资甚至未加遮蔽地暴露在外。"},{t="晦涩的谜语",b="这张幸存的羊皮纸残片上写着一条神秘的指令：“并非所有燃烧之物皆已散失。寻觅双生之地，寻觅此处。”由于在火灾中没有留下签名、坐标或更多背景信息，这张烧焦的残片成了偶然发现它的人唯一的踪迹线索。"}},faq={{q="营地里找到的便条上写着什么？",a="这张烧焦、起泡的便条上写着一条神秘的信息：“并非所有燃烧之物皆已散失。寻觅双生之地，寻觅此处。”这是废弃营地里留下的唯一线索。",al={"便条上写了什么","便条正文","起泡的便条"}},{q="是谁留下了这张便条？",a="作者尚不得而知。它是在最近一次营火的余烬旁，在散落的物资中被发现的。这表明撰写或持有此便条的人不久前刚刚离开，或是被迫匆忙离去。",al={"便条来自何处","谁写了便条","谁生起的营火"}},{q="“双生之地”指的是什么？",a="便条中神秘地提到了“双生之地”，指引读者去寻找一个匹配或镜像的地点。这张烧焦的残片没有提供进一步的解释，将其实际含义留给旅行者自行解开谜题。",al={"什么是双生之地","双生之地线索"}},{q="该如何根据便条上的线索行动？",a="由于地图上没有标记明确的目的地，便条上烧焦的残余是你的唯一向导。要解开其中的谜语，必须寻找一个与便条中神秘描述相呼应的土地或地点。",al={"如何处理便条","任务导向何处"}},{q="为什么营地会被废弃？",a="现场显示出匆忙离开或遭遇突发状况的迹象，物资被留在了正在熄灭的余烬旁。除了幸存的那张起泡的纸片外，没有留下任何可以辨识身份的装备或标记。",al={"谁废弃了物资","散落物资的营地"}},{q="营火处还有其他线索吗？",a="营火处没有留下任何完好的文字或标记。火焰摧毁了几乎所有东西，只留下了那张起泡的纸片作为曾有人在此休息的幸存证据。",al={"营火还揭示了什么","营地线索"}}},fp="27,170,18.258.0,16.233.0,45.156.0,25.202.0,35.159.0,40.148.0,31.183.0,38.169.0"}
P.entries["quest:79008"] = {n="... and that note you found",s="这张烧焦的字条在西部荒野一处即将熄灭的营火灰烬中被发现，留下了一条晦涩而孤独的线索。其灼烧的讯息暗示了世上某处等待着的目的地，敦促发现者去寻找一片“孪生之地”。",h="这张烧焦的字条在西部荒野一处即将熄灭的营火灰烬中被发现，留下了一条晦涩而孤独的线索。其灼烧的讯息暗示了世上某处等待着的目的地，敦促发现者去寻找一片“孪生之地”。",kw={"烧焦的字条","营火","灰烬","字条","孪生之地","西部荒野"},ang={["class:Rogue"]="对那些依靠低语、秘密和隐秘信件生活的人来说，解读留在隐蔽营地中的晦涩线索是他们的第二天性。",["faction:Alliance"]="对于试图恢复西部荒野秩序的冒险者来说，一个身份不明的营地和一道神秘的暗语，代表着王国边境上又一个正在展开的谜团。"},sec={{t="熄灭的营火",b="在西部荒野那荒废的田野、搜刮一空的农庄和饱经风霜的平原之间，旅行者经常会遇到流浪汉、不法之徒或绝望的流民营地。然而，这座小营地却是在匆忙或秘密中被遗弃的，补给品被弃之不顾，灰烬中仍有微光闪烁。在散乱的残骸中，留着一张在火灾中幸存下来的烧焦羊皮纸。"},{t="晦涩的讯息",b="这张烧焦的字条上只写着两句简短的话：“并非所有燃烧之物皆已遗失。寻找孪生之地，寻找那个地方。”这些话语笼罩在谜团之中，既像是一道神秘的谜题，又像是一份邀请，指引人们离开西部荒野那凄凉的田野，前往另一个在名称、地理或命运上与之相连的领域。"}},faq={{q="字条上写了什么？",a="这张烧焦的字条上写着：“并非所有燃烧之物皆已遗失。寻找孪生之地，寻找那个地方。”这是被遗弃的营地中留下的唯一线索。",al={"字条内容","字条上写了什么","烧焦字条上的话"}},{q="这张字条在哪里被发现？",a="这张字条是在西部荒野野外的一处近期营火残骸和散落的补给品中被发现的。",al={"字条位置","字条在哪里","营火位置"}},{q="是谁留下了这个营火？",a="作者身份不明。无论谁生起了这堆火，都已经离开不久，留下了散乱的补给品和灰烬中烧焦的讯息。",al={"谁留下了字条","营火主人","字条作者"}},{q="“孪生之地”指的是什么？",a="这个短语是一个谜题，指向世上另一个与发现地相互映照或有着某种联系的地区，尽管这张烧焦的字条没有提供进一步的解释。",al={"孪生之地的含义","什么是孪生之地","孪生之地在哪里"}},{q="为什么字条会被烧焦？",a="这张字条是在营火的灰烬中被烫伤和烧焦的，这表明有人要么是匆忙中试图将其销毁，要么是在火焰熄灭时漫不经心地将其丢弃。",al={"为什么它会被烧毁","有人试图烧毁字条吗","烧焦的字条"}},{q="这与迪菲亚潜行者有关吗？",a="虽然西部荒野到处都是迪菲亚潜行者和赤贫的非法定居者，但这条讯息的晦涩本质表明其含义比普通的强盗通讯更为隐晦。",al={"迪菲亚字条","是迪菲亚吗","兄弟会营火"}}},fp="27,115,12.296.0,19.240.0,23.142.0,25.97.0,22.142.0,35.146.0,24.143.0,44.163.0"}
P.entries["quest:7901"] = {n="Soft Bushy Tails",s="在暗月马戏团，收集蓬松的尾巴可以为游客准备奖品。马戏团希望开心的游客能带其他人一起来。",h="在暗月马戏团，收集蓬松的尾巴可以为游客准备奖品。马戏团希望开心的游客能带其他人一起来。",kw={"暗月马戏团","奖品","柔软蓬松的尾巴","尾巴","奖券","游客"},sec={{t="马戏团奖品",b="游客开心，暗月马戏团就能吸引更多人。你带来的尾巴会成为送给游客的奖品，满意的游客也许还会告诉朋友来这里游玩。马戏团会给你奖券，欢迎你在这里尽情游玩。"}},faq={{q="蓬松的尾巴有什么用？",a="暗月马戏团会把它们用作送给游客的奖品。",al={"尾巴的用途","蓬松尾巴的用途","马戏团用的尾巴"}},{q="马戏团为什么希望游客开心？",a="开心的游客也许会把马戏团介绍给朋友，带来更多游客。",al={"游客开心的原因","马戏团游客","更多马戏团游客"}},{q="马戏团会给你什么？",a="马戏团会给你奖券。",al={"马戏团奖券","我能得到什么","尾巴换奖券"}}},fp="16,143,12.228.0,29.60.0,39.78.0,29.28.0"}
P.entries["quest:7905"] = {n="The Darkmoon Faire",s="你带着一张Free Ticket Voucher，要交给Darkmoon Faire游乐场内的Gelvas Grimgate。这张兑换券是给他的。",h="你带着一张Free Ticket Voucher，要交给Darkmoon Faire游乐场内的Gelvas Grimgate。这张兑换券是给他的。",kw={"游乐场","darkmoon faire","free ticket voucher","gelvas grimgate","兑换券"},sec={{t="给Gelvas的兑换券",b="Gelvas Grimgate在Darkmoon Faire游乐场内，你带着一张要交给他的Free Ticket Voucher。这张兑换券尚待送达。"}},faq={{q="兑换券是给谁的？",a="Free Ticket Voucher是给Gelvas Grimgate的，他在Darkmoon Faire游乐场内。",al={"兑换券给谁","gelvas兑换券"}},{q="Gelvas Grimgate在哪里？",a="Gelvas Grimgate在Darkmoon Faire游乐场内。",al={"gelvas在哪里","gelvas位置"}},{q="我要带什么给Gelvas？",a="把Free Ticket Voucher交给Gelvas Grimgate。",al={"什么兑换券","门票兑换券"}}},fp="18,116,20.128.0,23.90.0,25.54.0,26.49.0"}
P.entries["quest:79091"] = {n="Archmage Antonidas: The Unabridged Autobiography",s="这个任务需要找回大法师安东尼达斯详尽的个人回忆录，他曾是备受尊崇的肯瑞托领袖。这本珍贵的书卷原藏于铁炉堡的宏伟档案馆中，为研究达拉然的历史和高等奥术学识提供了不可替代的洞见。",h="这个任务需要找回大法师安东尼达斯详尽的个人回忆录，他曾是备受尊崇的肯瑞托领袖。这本珍贵的书卷原藏于铁炉堡的宏伟档案馆中，为研究达拉然的历史和高等奥术学识提供了不可替代的洞见。",kw={"安东尼达斯","奥术","大法师安东尼达斯","自传","达拉然","探险者大厅","铁炉堡","肯瑞托","图书馆","法师"},ang={["class:Mage"]="大法师安东尼达斯是肯瑞托最伟大的领袖之一，也是奥术学术的典范。研究他的生平和个人著作对任何奥术练习者来说都能提供至关重要的见解。",["faction:Alliance"]="安东尼达斯曾是洛丹伦联盟对抗兽人部落和天灾军团的中流砥柱，这使得他的个人回忆录成为整个联盟领地内珍贵的历史记录。",["race:Dwarf"]="这卷书源自铁炉堡探险者大厅里的大图书馆，不过接收它的学者似乎并不在意夺走了矮人档案管理员的一本珍稀书籍。",["race:Human"]="安东尼达斯是一位受人尊敬的人类大法师，他带领肯瑞托和达拉然度过了第二次和第三次战争，这使得他的全本自传成为了一段珍贵的人类历史。"},sec={{t="大法师的箴言",b="大法师安东尼达斯是艾泽拉斯最聪慧的头脑之一，他曾担任肯瑞托的尊崇领袖及达拉然的统治者长达数十年。他的全本自传记载了他从紫罗兰城堡中不断晋升的过程、他对奥术的精通，以及在第二次和第三次战争那动荡时期中的领导经历。对于魔法学者和施法者来说，安东尼达斯的第一手回忆为深入了解达拉然的内幕和奥术艺术提供了一个绝佳窗口。"},{t="来自铁炉堡大图书馆",b="在被送往新家之前，这份珍稀的手稿一直存放于铁炉堡的大图书馆内，与探险者大厅里的古代泰坦遗物和矮人史料一同保管。矮人们拥有从艾泽拉斯各处的废墟和外邦王国中收集来的庞大藏书，这使得他们的档案馆成为了珍稀文献的宝库。然而，其他地方的奥术学者们却渴望将这些作品据为己有，他们确信忙碌的矮人档案管理员绝不会注意到少了一本书。"}},faq={{q="大法师安东尼达斯是谁？",a="大法师安东尼达斯曾是肯瑞托的长期领袖，也是魔法城市达拉然的统治者。作为一位传奇的奥术大师，他在第二次战争期间担任洛丹伦联盟的关键顾问，并在第三次战争中为了保卫达拉然而牺牲前，曾向泰瑞纳斯国王警告过瘟疫的到来。",al={"安东尼达斯是谁","大法师安东尼达斯背景故事","安东尼达斯身世"}},{q="什么是全本自传？",a="这是由大法师安东尼达斯本人撰写的详尽全本自传，详细记述了他的生平、学术研究以及在达拉然的领导生涯。鉴于他作为肯瑞托首领的地位，他的个人著作是一份极具价值的历史和魔法记录。",al={"这本书是什么","全本自传","安东尼达斯书卷"}},{q="这本书是从哪里来的？",a="这卷书是从铁炉堡的图书馆中获取的，原本存放于这座矮人要塞的探险者大厅里。矮人的探险家和档案管理员经常从东部大陆各地收集历史和魔法文献。",al={"书的来源","这书来自铁炉堡吗","铁炉堡图书馆书籍"}},{q="为什么要搜寻这本书？",a="学者和图书管理员们不断地搜寻强大或具有历史意义的魔法文献，以扩充他们的馆藏并保存奥术知识，尤其是那些由传奇法师所著、否则可能会失传或埋没在异国馆藏中的作品。",al={"为什么要收集魔法书","谁想要安东尼达斯的书","图书馆为何需要这本书"}},{q="大法师安东尼达斯遭遇了什么？",a="大法师安东尼达斯在第三次战争中，当堕落的阿尔萨斯·米奈希尔王子率领天灾军团入侵达拉然时不幸牺牲。安东尼达斯升起了一道强大的魔法结界来保卫城市及其秘密，但阿尔萨斯突破了防御，并击杀了他以夺取麦迪文之书。",al={"安东尼达斯死了吗","安东尼达斯是怎么死的","安东尼达斯发生了什么"}},{q="铁炉堡图书馆会发现书丢了吗？",a="收件人随口打消了关于矮人会察觉书本丢失的顾虑，认为铁炉堡的档案库规模宏大，少了一本书很可能根本不会被发现。",al={"铁炉堡会发现书丢了吗","从铁炉堡图书馆窃取"}}},fp="48,205,28.382.0,35.417.0,27.304.0,37.216.0,30.178.0,36.224.0,36.278.0,51.163.0"}
P.entries["quest:79092"] = {n="Archmage Theocritus' Research Journal",s="《塞欧克瑞图斯大法师的研究日志》是一卷记载了阿祖拉之塔的大法师所进行研究的奥术文献。这本日志被送往铁炉堡图书馆的学者手中，为这座伟大的矮人档案馆增添了宝贵的魔法见解。",h="《塞欧克瑞图斯大法师的研究日志》是一卷记载了阿祖拉之塔的大法师所进行研究的奥术文献。这本日志被送往铁炉堡图书馆的学者手中，为这座伟大的矮人档案馆增添了宝贵的魔法见解。",kw={"奥术知识","塞欧克瑞图斯大法师","铁炉堡","铁炉堡图书馆","研究日志","塞欧克瑞图斯","阿祖拉之塔"},ang={["class:Mage"]="奥术学者们珍视来自塞欧克瑞图斯大法师等杰出人物的笔记，他的研究有助于保护铁炉堡档案馆中的历史魔法论著。",["faction:Alliance"]="搜集稀有文本和日志丰富了铁炉堡核心地带为所有联盟学者所建立的庞大知识库。"},sec={{t="大师的实地笔记",b="塞欧克瑞图斯大法师在整个联盟中以一位受人尊敬的施法者而闻名，他驻扎在艾尔文森林东部边缘的阿祖拉之塔。经过多年的潜心研究，塞欧克瑞图斯调查了许多奇特的文物、能量线异常以及附近的魔法威胁，并将他的发现记录在详细的日志中。找回这样一卷日志，是研究一位肯瑞托资深大法师个人观察记录的难得机会。"},{t="扩充铁炉堡档案馆",b="探险者协会和铁炉堡图书馆的管理员们维护着大陆上最伟大的档案库之一。通过将《塞欧克瑞图斯大法师的研究日志》交付给他们，冒险者确保了其中的奥术见解能够被安全地保存，并与卡兹莫丹的历史卷宗一起编目收藏。图书管理员们热烈欢迎任何能进一步拓宽他们集体智慧的魔法发现。"}},faq={{q="什么是《塞欧克瑞图斯大法师的研究日志》？",a="这是一本属于塞欧克瑞图斯大法师的学术研究日志，上交至铁炉堡图书馆以保存奥术知识并扩充档案。",al={"塞欧克瑞图斯日志上交","什么是塞欧克瑞图斯日志"}},{q="塞欧克瑞图斯大法师是谁？",a="塞欧克瑞图斯大法师是一位著名的人类法师，他居住在艾尔文森林的阿祖拉之塔，研究古代魔法干扰和文物。",al={"谁是塞欧克瑞图斯","塞欧克瑞图斯大法师背景"}},{q="这本日志会被带到哪里？",a="这本日志会被带给铁炉堡图书馆的档案管理员，他们负责为馆藏收集稀有文献和魔法手稿。",al={"我在哪里上交塞欧克瑞图斯日志","谁想要塞欧克瑞图斯日志"}},{q="为什么图书馆想要这本日志？",a="铁炉堡图书馆的学者们致力于保存奥术知识，并研究来自施法大师的稀有论著，以扩充他们的历史记录。",al={"为什么收集魔法日志","塞欧克瑞图斯日志的用途"}},{q="还有更多的魔法作品可以送到图书馆吗？",a="是的，馆长们鼓励冒险者继续在世界各地寻找失落的魔法作品和历史文献，以帮助他们的档案收集工作。",al={"还有更多日志可以上交吗","还有其他书籍给图书馆吗"}},{q="日志中包含了什么样的研究？",a="这本日志包含了塞欧克瑞图斯大法师在对魔法现象和奥术知识进行广泛调查期间所编写的笔记和观察记录。",al={"塞欧克瑞图斯日志里有什么","塞欧克瑞图斯日志的内容"}}},fp="37,199,22.424.0,32.354.0,46.168.0,27.150.0,30.121.0,39.156.0,51.99.0,50.131.0"}
P.entries["quest:79093"] = {n="Rumi of Gnomeregan: The Collected Works",s="“Rumi of Gnomeregan: The Collected Works”涉及寻回并上交一卷侏儒著作汇编，以扩充图书馆的藏书。通过递交这些珍贵的文献，冒险者可以帮助学者们保护宝贵的历史和魔法知识，使其免于失传。",h="“Rumi of Gnomeregan: The Collected Works”涉及寻回并上交一卷侏儒著作汇编，以扩充图书馆的藏书。通过递交这些珍贵的文献，冒险者可以帮助学者们保护宝贵的历史和魔法知识，使其免于失传。",kw={"合集著作","诺莫瑞根背景知识","侏儒著作","图书馆","魔法著作","诺莫瑞根的卢米"},ang={["class:Mage"]="奥术学者非常重视从艾泽拉斯各地寻回的珍稀和奇特的著作，尤其是那些能扩展人们对魔法理论和历史的集体理解的作品。",["faction:Alliance"]="联盟的学者和馆长不断寻求寻回并保护珍贵的文学和魔法文献，以造福联盟的共同知识。",["race:Gnome"]="对于那些在诺莫瑞根陷落后试图保护本族文化和智力贡献的侏儒来说，确保像卢米这样思想家的著作合集被安全地归档，是关乎遗产传承的大事。"},sec={{t="保护侏儒智慧",b="“Rumi of Gnomeregan: The Collected Works”代表了保护著名的侏儒文学作品和智力成就的努力。在诺莫瑞根被穴居人侵占而惨遭沦陷后，许多侏儒的文字遗产流散、掩埋或面临毁灭的威胁。在图书馆和学术中心工作的学者与档案管理员们正积极搜寻幸存的手稿、专著和汇编，以确保侏儒思想家的智慧和创造力不会随着时间流逝而湮灭。"},{t="档案回收",b="当冒险者在野外发现这些合集卷册并将其送交档案馆时，馆长会急切地将其纳入不断增长的藏品库中。档案管理员将每一份寻回的手稿都视为对集体认知的一次扩展，并鼓励旅行者带回他们发现的任何进一步的魔法或历史文献。通过这些贡献，知识得以让那些致力于保护艾泽拉斯学术遗产的学者、法师和历史学家们查阅。"}},faq={{q="什么是“诺莫瑞根的卢米：全集”？",a="“诺莫瑞根的卢米：全集”是一项涉及寻回并贡献一份著名的侏儒著作汇编的任务。冒险者将这些文学资料交给一位正在构建图书馆藏书的学者，以确保宝贵的知识得以保存和研究。",al={"诺莫瑞根的卢米任务","什么是诺莫瑞根的卢米","谁是卢米"}},{q="这些合集应该交给谁？",a="这些合集被上交给维护图书馆藏书的馆长或学者。接收者会搜寻重要的著作和魔法专著，以扩充他们的档案馆藏。",al={"在哪里上交卢米的作品","谁接收卢米的著作","卢米合集上交"}},{q="图书馆为什么要这些合集？",a="学者和档案管理员积极从世界各地搜集珍稀文献、历史专著和魔法手稿，以确保重要的学术成果得以保存，特别是那些源自诺莫瑞根的著作。",al={"为什么要收集卢米的著作","诺莫瑞根的卢米的目的","为什么图书馆需要卢米的著作"}},{q="谁是诺莫瑞根的卢米？",a="诺莫瑞根的卢米是一位知识分子或魔法作家，其汇编的著作备受档案管理员追捧。由于诺莫瑞根大部分地区已被占领，幸存的侏儒思想和学识合集便成为了他们学术传统的珍贵记录。",al={"诺莫瑞根的卢米是谁","卢米背景知识","卢米作者"}},{q="之后还可以带更多的书去图书馆吗？",a="可以，档案管理员欢迎更多的发现。馆长鼓励冒险者继续搜寻珍稀或重要的魔法专著和历史著作，将其添加到馆藏中。",al={"还有更多的书可以找吗","我可以带更多的文献吗","更多的魔法著作图书馆"}},{q="谁能完成这项任务？",a="该任务由协助学者保护历史和奥术文献的联盟冒险者承担。任何寻回这些珍贵文献的人都可以将其呈交给档案馆，以助力学术研究。",al={"卢米任务要求","谁可以上交卢米的作品","仅限联盟卢米"}}},fp="39,157,26.247.0,17.333.0,48.182.0,42.153.0,48.189.0,26.191.0,52.147.0,27.160.0"}
P.entries["quest:79094"] = {n="The Lessons of Ta'zo",s="图书管理员请你将《Ta'zo的教诲》等魔法著作带到图书馆。每新增一部著作，都能丰富馆藏并拓展知识。",h="图书管理员请你将《Ta'zo的教诲》等魔法著作带到图书馆。每新增一部著作，都能丰富馆藏并拓展知识。",kw={"馆藏","铁炉堡","知识","教诲","图书馆","魔法著作","ta'zo"},sec={{t="图书馆的馆藏",b="图书管理员问你是否带来了可供图书馆收藏的东西。欢迎捐赠可能对图书馆有益的魔法著作，你的努力也能拓展馆藏知识。"}},faq={{q="谁在征集魔法著作？",a="图书管理员请你带来可能对图书馆有益的魔法著作。《The Lessons of Ta'zo》就是其中之一。",al={"ta'zo是谁","ta'zo图书馆","ta'zo"}},{q="图书管理员想让你带什么到图书馆？",a="图书管理员征集可能丰富图书馆馆藏的魔法著作。",al={"给ta'zo带什么","魔法书籍","图书馆馆藏"}},{q="馆藏存放在哪里？",a="图书管理员在暴风城和幽暗城收集这类著作。",al={"ta'zo在哪里","ironforge图书馆","图书馆位置"}},{q="图书管理员为什么征集魔法著作？",a="图书管理员说，你的努力能拓展图书馆的知识。",al={"为何征集魔法著作","拓展知识","帮助图书馆"}}},fp="20,145,22.183.0,32.114.0,52.81.0,29.63.0,45.72.0"}
P.entries["quest:79095"] = {n="The Apothecary's Metaphysical Primer",s="\"The Apothecary's Metaphysical Primer\" 是一本专门的魔法文献，馆长们希望能借此丰富学术档案。上交此书有助于为研究者和施法者保存珍贵的炼金术与奥术理论。",h="\"The Apothecary's Metaphysical Primer\" 是一本专门的魔法文献，馆长们希望能借此丰富学术档案。上交此书有助于为研究者和施法者保存珍贵的炼金术与奥术理论。",kw={"炼金术","药剂师","幽暗城","图书馆","魔法著作","形而上学入门书","典籍"},ang={["class:Mage"]="奥术修行者们非常看重形而上学入门书，因为它们对魔法理论、炼金相互作用以及施法基础定律有着深刻的见解。",["faction:Horde"]="部落的学者和冒险者们通过回收珍稀论著来协助幽暗城的Owen Thadd，以此充实图书馆的奥术知识储备。"},sec={{t="学者的收藏",b="\"The Apothecary's Metaphysical Primer\" 是一本涵盖深奥魔法原理的学术文献。馆长们致力于扩充档案，非常欢迎上交此类论著，并将这本入门书直接加入到他们的魔法参考资料收藏中。"},{t="扩充档案",b="对于幽暗城的Owen Thadd收藏馆等图书馆来说，保存这些专业论著至关重要。通过上交有关奥术和炼金理论的珍稀入门书，探险者们能够确保这些罕见的形而上学见解被妥善存档，供研究人员查阅，而不是遗失在荒野之中。"}},faq={{q="什么是 \"药剂师的形而上学入门\"？",a="\"药剂师的形而上学入门\" 是一本罕见的学术文献，馆长们希望借此丰富他们的魔法书库，并扩展对形而上学科学的理解。",al={"什么是 \"药剂师的形而上学入门\"","形而上学入门书任务","这是什么书"}},{q="谁需要这份入门书？",a="这本书要交给幽暗城的欧文·萨德，他正在搜寻魔法著作和奥术论著，以便为研究者和施法者保存知识。",al={"谁需要这本书","我应该在哪里上交入门书","谁会接收这本入门书"}},{q="图书馆为什么要收集这类著作？",a="图书馆和档案库收集形而上学和魔法著作，旨在系统地扩充其知识储备，帮助学者、炼金术师和奥术师研究奥术原理。",al={"图书馆为什么需要入门书","收集入门书的目的","为什么要收集魔法书"}},{q="你能给图书馆带来更多魔法著作吗？",a="负责整理魔法文献的学者们欢迎你发现并带来的任何奥术与学术研究成果，这些成果将丰富他们的档案。",al={"还有更多的书可以上交吗","我可以带来其他的书吗","更多的图书馆藏书"}},{q="形而上学入门书里包含了什么样的知识？",a="在魔法学术界，形而上学涉及魔法能量的基本本质、支配现实的无形力量，以及物理试剂如何与奥术力量相互作用。",al={"什么是形而上学","魔兽世界中的形而上学知识","什么是药剂师形而上学"}},{q="谁撰写了 \"药剂师的形而上学入门\"？",a="记录中并未提及撰写此书的具体药剂师，但药剂师和学者们经常编写入门书，总结实用的炼金术、草药混合配方和神秘公式。",al={"谁写了药剂师入门书","药剂师入门书作者","谁是那位药剂师"}}},fp="36,172,23.186.0,22.266.0,45.154.0,40.158.0,45.160.0,48.117.0,56.168.0,47.170.0"}
P.entries["quest:79096"] = {n="Ataeric: On Arcane Curiosities",s="“Ataeric: On Arcane Curiosities”涉及交付寻获的魔法文献，以扩充学术档案馆的馆藏。通过从野外收集晦涩的文本和论着，研究人员力求加深对奥术研究的理解并保存神秘学知识。",h="“Ataeric: On Arcane Curiosities”涉及交付寻获的魔法文献，以扩充学术档案馆的馆藏。通过从野外收集晦涩的文本和论着，研究人员力求加深对奥术研究的理解并保存神秘学知识。",kw={"奥术","奥术珍品","阿塔瑞克","图书馆","魔法作品","学者"},ang={["class:Mage"]="法师对奥术研究有着天生的兴趣，因此向学术图书馆捐赠和寻回魔法论着与他们的技艺直接相关。",["race:Dwarf"]="矮人学者和探险者协会非常重视积累书面记录、文物和深奥的学识。"},sec={{t="保存奥术知识",b="艾泽拉斯各地的学者和档案管理员都依赖四处游历的冒险者，从危险之地寻回稀有书籍和被遗忘的论着。在这个任务中，寻求者专门寻找魔法文献，以拓宽机构对奥术艺术的理解。每一本被寻回的卷册都有助于拼凑出那些本可能散佚或失传的神秘学实践。"},{t="不断扩充的档案馆",b="在收到这些珍品后，馆长会将其直接纳入档案馆的藏品库。图书馆并不认为收购任务已经完成，而是保持着对世界各地发现的任何进一步魔法文献的公开征集，确保其藏品随着持续的学术研究而不断增长。"}},faq={{q="这个任务的目的是什么？",a="“阿塔瑞克：论奥术奇观”代表着向寻求扩充图书馆深奥知识储备的收藏家交付学术或魔法文本。",al={"这是什么任务","阿塔瑞克任务","奥术珍品上交"}},{q="谁在收集这些奥术文献？",a="阿塔瑞克是该论着的作者。它会被交给正在收集魔法着作和稀有卷册以充实图书馆档案馆的研究员或馆长。",al={"谁想要这个","谁获得了这本书","谁是阿塔瑞克"}},{q="哪座图书馆受益于这些珍品？",a="寻求这些文本是为了增强学术收藏，并使接收该作品的学术图书馆受益。",al={"这是什么图书馆","这些书去了哪里"}},{q="还有更多的魔法作品可以收集吗？",a="学者特别鼓励冒险者在旅途中带回任何额外发现的魔法作品，以持续拓宽他们的知识储备。",al={"可以上交更多吗","可重复收集的魔法作品","图书馆需要的更多书籍"}},{q="为什么图书馆要寻求奥术珍品？",a="学者们不断寻找稀有的论着，以更好地理解奥术的细微差别，并保存历史性的神秘学知识。",al={"图书馆研究什么","为什么要收集奥术书籍"}},{q="为什么寻回奥术作品很重要？",a="奥术文本通常包含不稳定或晦涩的知识，因此在专门的图书馆内妥善保存和研究它们，远比让它们遗落在野外要好。",al={"这有危险吗","奥术魔法的风险"}}},fp="30,158,27.279.0,20.179.0,34.79.0,35.116.0,46.77.0,40.108.0,45.99.0,41.136.0"}
P.entries["quest:79097"] = {n="Baxtan: On Destructive Magics",s="《Baxtan: On Destructive Magics》是一个学术性的上交任务，冒险者需要将Baxtan关于破坏性法术的论著交给图书馆学者。寻回这些著作有助于图书馆的档案管理员加深对不稳定的奥术能量的理解。",h="《Baxtan: On Destructive Magics》是一个学术性的上交任务，冒险者需要将Baxtan关于破坏性法术的论著交给图书馆学者。寻回这些著作有助于图书馆的档案管理员加深对不稳定的奥术能量的理解。",kw={"奥术","巴克斯坦","书籍","破坏性魔法","图书馆","魔法","典籍"},ang={["class:Mage"]="关于破坏性魔法的学术论著自然会引起法师们的兴趣，他们致力于研究奥术力量与破坏性力量之间的平衡。",["class:Warlock"]="那些钻研不稳定或禁忌力量的施法者能够理解学者们在探究破坏性奥术时所展现出的学术兴趣。",["faction:Alliance"]="扩充联盟图书馆内收藏的知识，能够巩固整个联盟的学术基础。"},sec={{t="一本毁灭艺术典籍",b="这个任务代表了学者们在编纂和保存奥术知识方面所做的持续努力。当冒险者发现探讨破坏性魔法不稳定性本质的文本时，将其交由严谨的学术机构保管，可以确保这些艺术的力量与危险被理解，而不是失传。"},{t="整理图书馆的知识",b="图书馆是历史、科学和奥术的宝库。其学者负责获取稀有卷宗，并欢迎那些从世界各地危险角落寻回遗忘论著的旅者，以扩充图书馆的馆藏知识。"}},faq={{q="任务“巴克斯坦：论毁灭魔法”是什么？",a="这个任务的内容是将巴克斯坦的破坏性魔法论著交给图书馆学者，从而充实魔法著作的收藏。",al={"什么是巴克斯坦: 论毁灭魔法","这是一个什么任务","巴克斯坦任务"}},{q="巴克斯坦是谁？",a="巴克斯坦是《论毁灭魔法》的作者。接收这本著作的学者正负责为图书馆收集重要的书籍和魔法论著。",al={"巴克斯坦是谁","巴克斯坦 非玩家角色","巴克斯坦在哪里"}},{q="巴克斯坦在寻找什么样的书籍？",a="图书馆的学者寻求对馆藏有益的学术和魔法著作，并欢迎在世界各地发现的任何进一步的魔法论著。",al={"巴克斯坦想要什么样的书","巴克斯坦书籍收藏","给巴克斯坦的更多书籍"}},{q="这些魔法知识最终会被送到哪里？",a="收集到的文本会被纳入接收它们的图书馆的馆藏中，从而将奥术和危险艺术的知识保存下来以供研究。",al={"书会被送到哪里","哪个图书馆","铁炉堡图书馆藏书"}},{q="图书馆为什么要收集关于破坏性魔法的著作？",a="学者们编纂破坏性魔法，是为了更好地理解强大奥术能量所带来的危害、理论机制以及表现形式。",al={"为什么要研究破坏性魔法","破坏性魔法知识"}},{q="你还能给巴克斯坦带来更多的魔法著作吗？",a="可以。学者鼓励冒险者继续带来他们发现的任何额外魔法著作，这表明收集知识的工作仍在持续进行。",al={"巴克斯坦还有更多任务吗","我可以上交更多书吗"}}},fp="29,115,22.202.0,27.205.0,50.113.0,14.126.0,42.122.0,41.120.0,56.108.0,43.101.0"}
P.entries["quest:791"] = {n="新的背包",s="“各尽其责”是由弗恩·凝眉在俯瞰剃刀岭的瞭望塔顶端提供的一项入门任务。这位伤痕累累的老兵已无法再上前线作战，他请求年轻的部落冒险者从当地的敌对人类和半人马身上搜集帆布，好让他制作出能助力他们旅途的补给品。",h="“各尽其责”是由弗恩·凝眉在俯瞰剃刀岭的瞭望塔顶端提供的一项入门任务。这位伤痕累累的老兵已无法再上前线作战，他请求年轻的部落冒险者从当地的敌对人类和半人马身上搜集帆布，好让他制作出能助力他们旅途的补给品。",kw={"帆布脚料","各尽其责","杜隆塔尔","弗恩·凝眉","诺克-卡隆","剃刀岭","剃刀岭哨塔","提拉加德"},ang={["faction:Horde"]="杜隆塔尔的每一位年轻士兵都依赖像弗恩·凝眉这样经验丰富的老兵，他们时刻提醒新兵：荣耀部落意味着履行家园要求的任何职责，无论是守卫前哨站还是缝制帆布。",["profession:Tailoring"]="弗恩展示了实用且硬朗的边境裁缝手艺，将从人类入侵者和半人马掠夺者那里剥下的废弃厚帆布变成了耐用的荒野生存装备。",["race:Orc"]="弗恩代表了那一代兽人：他们摆脱了恶魔的腐化，随萨尔跨越海洋，现在正将他们的余生奉献给培育他们初建国家的未来。"},sec={{t="老兵的召唤",b="弗恩·凝眉是第三次战争的老兵，他曾追随萨尔大酋长在杜隆塔尔的拓荒时期并肩作战，也参与了海加尔山的生死保卫战。如今，因年事已高且旧伤缠身，他已无法再挥舞战斧上阵。相反，他时刻在剃刀岭的瞭望塔上保持警惕，在防范外敌入侵的同时，也尽力为下一代守卫者提供支持。"},{t="搜集的帆布",b="随着部落对该地区的掌控日益稳固，警戒号角的鸣响声也随之减少，弗恩便将空闲时间用于制作实用的装备。在杜隆塔尔干旱的峡谷中，坚韧的帆布很难获得，但东岸的库尔提拉斯入侵者以及游荡在平原上的诺克-卡隆半人马身上却携带着大量这种材料。从这些敌对势力手中搜集脚料，让弗恩有了足够的布料，可以为活跃的侦察兵缝制多功能背包。"}},faq={{q="弗恩·凝眉是谁？",a="弗恩·凝眉是一位年迈的兽人老兵，驻守在剃刀岭上方的瞭望塔中。他曾在杜隆塔尔的奠基时期与萨尔并肩作战，也曾站在击败阿克蒙德的海加尔山联军阵列中。他已无法再上前线作战，现在担任瞭望员，并利用空闲时间为年轻的部落战士制作战地装备。",al={"弗恩是谁","弗恩·凝眉背景故事","谁发布各尽其责任务"}},{q="在杜隆塔尔哪里可以找到帆布脚料？",a="帆布脚料可以从杜隆塔尔沿岸占据提拉加德城堡的库尔提拉斯人身上，以及在平原上扎营的诺克-卡隆半人马身上获得。这两个势力都携带着大量结实的编织材料，可以从他们的营地和随身物品中搜集到。",al={"哪里获得帆布脚料","谁掉落帆布脚料","帆布脚料位置"}},{q="弗恩所在的瞭望塔在哪里？",a="弗恩的瞭望塔坐落在剃刀岭正西北方的高耸岩崖上。定居点后方的一条蜿蜒小路直通山顶，那座木制瞭望建筑就立在那里。",al={"弗恩·凝眉在哪里","剃刀岭瞭望塔位置","找到剃刀岭瞭望塔"}},{q="弗恩用帆布脚料制作什么？",a="弗恩将搜集到的帆布脚料缝制成结实的多功能背包。对于在杜隆塔尔各地旅行的年轻冒险者来说，增加携带补给品、口粮和缴获武器的容量，对于在残酷的荒野中生存至关重要。",al={"弗恩制作什么","帆布有什么用","帆布脚料奖励"}},{q="为什么一位老战士要在制作背包而不是去战斗？",a="几十年的残酷战斗让弗恩的身体不堪重负，他已无法再满足战场对速度和力量的要求。他并没有哀叹自己的退役，而是以守望剃刀岭并制造能直接增强年轻战士防卫能力的装备为荣。",al={"为什么弗恩在制作物品","为什么弗恩待在塔里","为什么弗恩不战斗"}},{q="弗恩参加过哪场战争？",a="弗恩在萨尔大酋长麾下参加了第三次战争，参与了杜隆塔尔的定居过程，以及对抗燃烧军团的海加尔山决战。他自豪地回忆起在部落、暗夜精灵和联盟为了击败阿克蒙德而达成临时且必要的停战协议时，他所响应的战吼。",al={"弗恩战斗历史","弗恩以前做过什么","阿克蒙德与弗恩"}}},fp="17,233,19.360.0,16.407.0,22.324.0,44.217.0,46.165.0,44.199.0,56.218.0,27.241.0"}
P.entries["quest:79192"] = {n="Stepping Stones",s="Stepping Stones 是一项调查任务，源于在贫瘠之地崎岖荒野中贴着的一张饱经风霜的便条。潦草的字迹写着有两名信使一直在为新的瘟疫运送货物，并将发生在他们身上的事称为简单的药剂师事故。神秘的作者敦促任何找到它的人前往凄凉之地边界的一处隐秘山间避难所。",h="Stepping Stones...",kw={"凄凉之地","雇佣兵","山脉","新的瘟疫","便条","皇家药剂师协会","垫脚石","贫瘠之地"},ang={["class:Rogue"]="追踪匿名线人并审查凄凉之地和贫瘠之地之间隐秘的偏远地区补给点，对于那些从事匕首与情报交易的人来说是第二天性。",["faction:Horde"]="在贫瘠之地游荡的部落成员必须决定，关于卡利姆多土地上致命瘟疫运输的传闻是否对他们的领土和联盟构成了威胁。",["race:Undead"]="对于被遗忘者的旅行者来说，任何关于皇家药剂师协会及其枯萎病研究的零星提及都是紧迫的安全问题，或者说是来自内部的危险阴谋。"},sec={{t="荒野中的便条",b="这张信息随意地钉在偏远营地的一块木板上，在贫瘠之地严酷的环境中格外显眼。这里的营地常有雇佣兵、亡命之徒和流浪者出没，他们寻求远离十字路口或棘齿城窥探目光的临时住所。这张撕碎的便条立刻打破了荒野中平淡的闲谈，发出了一个充满阴谋和黑暗基调的邀请。"},{t="关于新的瘟疫的私语",b="便条作者报告说，两名特工一直在为新的瘟疫运送货物，并将发生在他们身上的事称为简单的药剂师事故。在卡利姆多各地运送挥发性瘟疫药剂的信使承担着巨大的风险，作者提供了一个位于贫瘠之地和凄凉之地之间的山中舒适地点，作为一个安全的谈话场所。"}},faq={{q="在 垫脚石 中找到的便条说了些什么？",a="该便条透露，运送与被遗忘者的新的瘟疫有关材料的信使遭遇了突然死亡。作者称这些为简单的药剂师事故，但提供了一个山中的会面点来安全地讨论此事。",al={"踏脚石 便条","便条的内容","踏脚石 任务文本"}},{q="便条告诉你去哪里？",a="作者邀请读者前往一个隐藏在贫瘠之地和凄凉之地之间的高山上的营地，这里远离常规巡逻路线和贸易通道。",al={"踏脚石 前往何处","山间舒适地点","踏脚石 地点"}},{q="信中提到的新的瘟疫是什么？",a="新的瘟疫是被遗忘者的皇家药剂师协会在幽暗城研发的致命混合药剂。它旨在根除天灾军团和活着的敌人，其在各大陆的测试和信使任务都充满了秘密和致命的危险。",al={"什么是 新的瘟疫","皇家药剂师瘟疫","药剂师运送"}},{q="是谁写了钉在木板上的便条？",a="该信息是匿名留在偏远营地的一块粗糙木板上的。作者没有署名，只提供了一个位于贫瘠之地和凄凉之地之间的山中舒适地点作为安全的谈话场所。",al={"谁写了便条","踏脚石 作者","谁在山中等待"}},{q="被遗忘者的信使为什么会出现在卡利姆多？",a="被遗忘者的药剂师经常从卡利姆多各地的严酷动植物身上采集奇异的毒液、孢子和试剂，并通过部落哨所和荒野路线协调运输。",al={"贫瘠之地的被遗忘者","为什么 新的瘟疫 出现在卡利姆多","贫瘠之地的药剂师"}},{q="为什么偏远营地会被用于此类便条？",a="贫瘠之地地域辽阔，在主要定居点之外的管理较为松散。中立的中转站、雇佣兵休息点和流浪者营地让旅行者、走私者和线人能够留下隐秘的消息，而不会引起部落或地区岗哨的注意。",al={"偏远营地背景知识","贫瘠之地的雇佣兵营地"}}},fp="15,232,19.313.0,26.258.1,56.201.0,35.94.0,47.247.0,39.156.0,51.169.0,51.247.0"}
P.entries["quest:792"] = {n="邪灵劣魔",s="“邪恶的魔仆”是祖雷萨在试炼谷向刚抵达的勇士下达的早期任务之一。在监视山谷内的试炼时，祖雷萨发现附近的一处洞穴中隐藏着一个阴险的火刃集会所。为了遏制他们突如其来的扩张，新兵们被派遣去猎杀那些潜入杜隆塔尔红土地上的恶魔仆从。",h="“邪恶的魔仆”是祖雷萨在试炼谷向刚抵达的勇士下达的早期任务之一。在监视山谷内的试炼时，祖雷萨发现附近的一处洞穴中隐藏着一个阴险的火刃集会所。为了遏制他们突如其来的扩张，新兵们被派遣去猎杀那些潜入杜隆塔尔红土地上的恶魔仆从...",kw={"火刃氏族","火刃集会所","杜隆塔尔","小鬼","大兽穴","试炼谷","邪恶的魔仆","祖雷萨"},ang={["class:Warlock"]="兽人和巨魔术士必须正视那些滥用恶魔契约进行破坏，而非将邪能用于部落生存的堕落施法者所带来的现实。",["faction:Horde"]="火刃氏族是杜隆塔尔目前面临的最迫切的内部威胁之一，他们试图在年轻的部落巩固主权之前从内部将其腐蚀。",["race:Orc"]="对于那些努力践行萨尔关于拒绝恶魔奴役理念的兽人来说，在他们神圣的训练场中遇到邪能污染，这是一个苦涩的提醒，表明暗影议会的遗产依然在发酵。"},sec={{t="山谷中的阴影",b="试炼谷旨在成为年轻的兽人和暗矛巨魔展示他们对萨尔领导的部落的忠诚、纪律和力量的试炼场。它原本是用来测试新兵对抗蝎虫和野猪这类本土掠食者的能力，而非对抗恶魔腐蚀。然而，在东北方的一处洞穴中，自称为火刃氏族的特工们在山谷监工的眼皮底下建立了一个秘密集会所。"},{t="扑杀小鬼",b="祖雷萨在指引大兽穴附近的新手时，在这些恶魔污染蔓延至整个峡谷之前就察觉到了异常。被称为“邪恶的魔仆”的次级恶魔生物开始从洞口蜂拥而出，向任何靠近的冒险者投掷火焰并进行威胁。在部落能够铲除隐藏在阴影中的幕后主使之前，年轻的新兵们肩负着斩杀这些低级仆从以保卫山谷的任务。"}},faq={{q="谁发布了“邪恶的魔仆”这个任务？",a="该任务由祖雷萨发布。她驻扎在试炼谷中心的大兽穴入口外。",al={"邪恶的魔仆任务发布者","谁发布邪恶的魔仆","在哪里接取邪恶的魔仆"}},{q="什么是邪恶的魔仆？",a="邪恶的魔仆是由火刃氏族术士召唤并束缚的小鬼状恶魔生物。它们作为次级爪牙和宠物，使用火焰骚扰闯入者。",al={"什么是邪恶的魔仆","邪恶的魔仆背景故事","邪恶的魔仆怪物类型"}},{q="火刃集会所位于何处？",a="该集会所坐落在试炼谷东北部尽头的一处洞穴内，穿过四处游荡的杂斑野猪和蝎虫工兵即可到达。",al={"火刃集会所位置","火刃集会所在哪","试炼谷洞穴"}},{q="为什么火刃氏族会在试炼谷中？",a="火刃氏族是一个致力于破坏萨尔新部落并传播恶魔腐蚀的秘密邪教。渗透进试炼谷让他们能够潜伏在暗处，并威胁到部落最新一代的战士。",al={"为什么火刃氏族在这里","火刃氏族动机","火刃氏族想要什么"}},{q="完成“邪恶的魔仆”之后会发生什么？",a="当洞穴外的魔仆被清除后，祖雷萨会指引你深入洞穴去面对邪教头目，并取回一枚火刃奖章。",al={"邪恶的魔仆后续任务","邪恶的魔仆之后是什么","火刃奖章任务"}},{q="我必须进入洞穴深处才能找到这些魔仆吗？",a="不需要。虽然它们栖息在洞穴内，但大量的邪恶的魔仆也在洞穴入口周围和洞口外的峡谷地面上游荡。",al={"邪恶的魔仆在洞穴里吗","在哪里击杀邪恶的魔仆","刷邪恶的魔仆"}}},fp="14,220,22.318.0,16.332.0,35.113.0,24.147.0,41.137.0,49.243.0,45.170.1,57.130.0"}
P.entries["quest:79229"] = {n="Highway Robbery",s="在凄凉之地，一处遭劫的营地留下了暴力袭击的线索。你要寻找能解释事发经过的人。",h="在凄凉之地，一处遭劫的营地留下了暴力袭击的线索。你要寻找能解释事发经过的人。",kw={"袭击","营地","半人马","凄凉之地","矮人","劫掠","人类","遭劫的营地","拾荒者"},sec={{t="遭劫的营地",b="凄凉之地的一处营地里，两名人类和一名矮人的遗骸散落在营地废墟间。他们骨骼上的痕迹表明，他们遭到了残暴袭击；被盗的物资则说明，袭击者不是野兽。他们身上的伤口也不像半人马武器造成的。有人请你在凄凉之地寻找熟悉这片土地、能够解释这些迹象的人。"}},faq={{q="营地里遇害的是谁？",a="遗骸表明，两名人类和一名矮人遭到了袭击。",al={"营地遇害者","营地受害者","人类和矮人"}},{q="营地里发生了什么？",a="营地遭到劫掠，遗骸上也有残暴袭击的迹象。",al={"这里发生了什么","遭劫的营地","营地袭击"}},{q="袭击是野兽所为吗？",a="被劫走的物资表明，袭击并非野兽所为。",al={"野兽袭击","是野兽干的吗","谁袭击了他们"}},{q="伤口是半人马造成的吗？",a="这些伤口不像是半人马武器造成的。",al={"半人马袭击","半人马武器","是半人马干的吗"}},{q="谁能解释这场袭击？",a="有人请你在凄凉之地寻找熟悉在这片土地上搜寻残骸的人。",al={"谁了解营地情况","询问拾荒者","该找谁"}}},fp="15,119,16.330.0,33.63.0,30.73.0,26.65.0,33.41.0,27.80.0"}
P.entries["quest:79235"] = {n="On the Lam",s="一则商队传闻指向了袭击凄凉之地人类与矮人营地后逃离的部落劫掠者。你将前往藏宝海湾寻找其中一人。",h="一则商队传闻指向了袭击凄凉之地人类与矮人营地后逃离的部落劫掠者。你将前往藏宝海湾寻找其中一人。",kw={"联盟元帅","藏宝海湾","商队","凄凉之地","部落","劫掠者","逃亡"},sec={{t="通往藏宝海湾的线索",b="一名商队联系人提到凄凉之地的人类与矮人营地遭到袭击，随后指引你前往藏宝海湾。受害者和这场暴行让商队怀疑是部落劫掠者所为。一名联盟元帅追捕过这伙匪徒，他们已离开凄凉之地。现在，你受命寻找其中一人。"}},faq={{q="是谁袭击了营地？",a="商队传闻将凄凉之地人类与矮人营地遭袭归咎于一伙部落劫掠者。",al={"是谁干的","袭击营地的人"}},{q="劫掠者去了哪里？",a="联盟元帅追捕后，这伙匪徒逃离了凄凉之地。据说可以去藏宝海湾寻找其中一人。",al={"他们逃往何处","劫掠者的位置"}},{q="为什么要去藏宝海湾寻找？",a="联系人建议前往藏宝海湾，因为品行可疑之人常常经过那里的港口，而劫掠者或许正在寻找船只。",al={"为何去藏宝海湾","去哪里找劫掠者"}},{q="我要找什么？",a="你要寻找一名来自凄凉之地的劫掠者。",al={"逃亡目标","寻找其中一人"}}},fp="10,150,20.286.0,23.97.0,27.116.0,22.130.0,22.55.0"}
P.entries["quest:79236"] = {n="Cherry for Your Thoughts?",s="在藏宝海湾，一名叫托卡尔的雇佣兵想要一杯酒，作为交换，她愿意透露近期人类和矮人哨所遇袭背后的真相。虽然有流言指责部落是幕后黑手，但托卡尔坚称她的团队是在受私人雇佣合约的约束下行事。",h="在藏宝海湾，一名叫托卡尔的雇佣兵想要一杯酒，作为交换，她愿意透露近期人类和矮人哨所遇袭背后的真相。虽然有流言指责部落是幕后黑手，但托卡尔坚称她的团队是在受私人雇佣合约的约束下行事。",kw={"藏宝海湾","樱桃酒的代价","樱桃酒","治安官","雇佣兵","劫掠","私人合同","托卡尔"},ang={["faction:Alliance"]="联盟成员会很有兴趣了解，袭击人类和矮人定居点的劫掠者并非受部落指使，而是受雇于一位私人资助者。",["faction:Horde"]="部落冒险者可以在托卡尔的供述中找到辩护的理由，这澄清了针对联盟营地的袭击是私人雇佣合约，而非部落的官方侵略行为。"},sec={{t="藏宝海湾的低语",b="在热闹的藏宝海湾港口，一个叫托卡尔的人正保持着低调，同时警惕着执法者的动向。近期发生的一系列激进劫掠事件重创了人类和矮人营地，助长了部落策划了这些袭击的传言。当那些显然不为调查此事的治安官工作的旅者接近她时，托卡尔立刻反驳了这些广为流传的说法，并提出只要请她喝杯酒，就愿意讲述另一版本的真相。"},{t="私人雇佣兵",b="托卡尔坦承参与了对人类和矮人哨所的劫掠，但坚决否认这些袭击是受部落指使的。相反，她声称她的团伙是受某个未透露身份的第三方私下雇佣。在披露究竟是谁资助了这次行动以及动机之前，她坚持要求对方先请她喝杯清爽的樱桃酒。"}},faq={{q="托卡尔是谁？",a="托卡尔是一名藏身于海盗避风港藏宝海湾的特工或雇佣兵。由于近期对人类和矮人定居点的劫掠受到审查，她向任何愿意为她买一杯樱桃酒的人提出，会讲述她为谁工作的完整故事。",al={"托卡尔是谁","托卡尔 藏宝海湾","樱桃酒任务提供者"}},{q="为什么托卡尔想要樱桃酒？",a="托卡尔在清醒时不愿意分享她过往合同的敏感细节。给她买一杯樱桃酒能让她卸下心防，从而说明是谁私下资助了针对联盟营地的劫掠。",al={"为什么要买樱桃酒","樱桃酒 托卡尔","托卡尔想要什么"}},{q="是部落负责劫掠人类和矮人营地的吗？",a="根据托卡尔的说法，针对人类和矮人营地的袭击并非部落下令。虽然传言称部落是始作俑者，但她坚称她的团队是在私人雇佣合约下工作的。",al={"谁雇佣了托卡尔","部落攻击了联盟营地吗","部落是幕后黑手吗"}},{q="为什么托卡尔担心治安官？",a="托卡尔害怕遭到正在调查劫掠人类和矮人定居点事件的治安官的追捕。她非常小心，确保在藏宝海湾接近她的人不是被派来将她绳之以法的代理人。",al={"治安官是谁","托卡尔在躲避治安官吗","治安官寻找托卡尔"}},{q="在哪里可以为托卡尔弄到樱桃酒？",a="樱桃酒是一种可以从藏宝海湾的旅店老板和酒保处买到的饮料。给托卡尔送上一杯这种酒，就能满足她的要求，并促使她说出她的故事。",al={"哪里可以得到樱桃酒","樱桃酒位置","藏宝海湾的酒"}},{q="为什么托卡尔待在藏宝海湾？",a="藏宝海湾是一个中立的自由港，不受联盟和部落的严格管辖。对于一名在劫掠了人类和矮人定居点后想要避风头的雇佣兵来说，这里是一个理想的藏身处。",al={"为什么托卡尔在藏宝海湾","托卡尔的藏身处"}}},fp="25,167,25.301.0,19.269.1,13.166.0,34.135.0,68.153.0,37.173.0,39.133.0,34.175.0"}
P.entries["quest:79242"] = {n="No Honor Among Thieves",s="一名昔日盗贼指出，带领帮派后又抛下他们的暗夜精灵是 Illari Duskfeather。你得知她在阿拉希高地海岸的藏身处，以及那里藏着的赃物。",h="一名昔日盗贼指出，带领帮派后又抛下他们的暗夜精灵是 Illari Duskfeather。你得知她在阿拉希高地海岸的藏身处，以及那里藏着的赃物。",kw={"阿拉希高地","藏匿物","藏身处","illari duskfeather","元帅","暗夜精灵","盗贼之间毫无道义","赃物","盗贼"},ang={["race:NightElf"]="作为一名暗夜精灵，你得知 Illari Duskfeather 曾带领一伙盗贼，并在元帅追捕他们时抛下了他们。"},sec={{t="遭背叛的帮派",b="Illari Duskfeather 抛下帮派时，元帅正沿着他们的踪迹追查。一名幸存的盗贼觉得他们被当成了替罪羊，却说不出缘由。他把追查的事交给任何愿意接手的人。Illari 曾提起阿拉希高地海岸的一处藏身处，她的赃物还留在那里。"}},faq={{q="Illari Duskfeather 是谁？",a="Illari Duskfeather 是一名带领盗贼帮派的暗夜精灵。她向他们提供营地的情报，只留下其中一些较为稀有的战利品。",al={"illari","illari 是谁","illari duskfeather 的身世"}},{q="Illari 为什么离开帮派？",a="元帅追查帮派时，幸存的盗贼并不知道 Illari 为什么抛下他们。",al={"她为什么离开","illari 的动机","为何抛下盗贼"}},{q="我在哪里能找到 Illari？",a="Illari 曾提到阿拉希高地海岸的一处藏身处。",al={"illari 的位置","illari 在哪里","阿拉希藏身处"}},{q="帮派想从 Illari 那里得到什么？",a="帮派的一名前成员指引你前往 Illari 的藏身处，那里有她藏匿的赃物。",al={"illari 的藏匿物","赃物","她的藏身处里有什么"}},{q="帮派的头目是谁？",a="Illari Duskfeather 是帮派头目，她是一名暗夜精灵。",al={"盗贼头目","帮派首领","谁带领盗贼"}}},fp="22,194,15.303.0,26.140.0,30.100.0,24.65.0,36.90.0,24.53.0"}
P.entries["quest:793"] = {n="破碎的联盟",s="高恩派遣你去荒芜之地最东端的莱瑟罗峡谷，黑龙BossBlacklash和赫玛图斯正被大地印章束缚在那里。这是“破碎的联盟”任务之后的后续。",h="高恩派遣你去荒芜之地最东端的莱瑟罗峡谷，黑龙BossBlacklash和赫玛图斯正被大地印章束缚在那里。这是“破碎的联盟”任务之后的后续。",kw={"黑龙军团","布莱克拉什","黑石兽人","高恩","赫玛图斯","莱瑟罗峡谷","大地印章"},sec={{t="三块符文石",b="三块符文石封印着大地印章。它们分别位于莱瑟罗峡谷的几根石柱中：钻石、猫眼石和紫水晶。高恩交给你的大地印章可以抽出这些石头并解开封印。峡谷里栖息着无数龙类，布莱克拉什和赫玛图斯非常强大。高恩希望杀掉它们，并带回它们的束缚物。"},{t="高恩的意图",b="高恩称黑龙军团依然与黑石氏族的叛徒兽人结盟，无论龙类还是兽人都必须受到约束或被铲除。一旦布莱克拉什和赫玛图斯伏诛，部落就可以将目光投向西边的黑石塔了。"}},faq={{q="谁发布了这个任务？",a="由高恩发布，作为“破碎的联盟”之后的下一步。",al={"破碎的联盟任务发布者","高恩位置","谁发布破碎的联盟"}},{q="莱瑟罗峡谷在哪里？",a="前往荒芜之地的最东端。峡谷中栖息着无数龙类。",al={"莱瑟罗峡谷位置","如何前往莱瑟罗峡谷","莱瑟罗峡谷在哪里"}},{q="如何释放布莱克拉什和赫玛图斯？",a="大地印章可以从三根石柱中分别抽出一块符文石。将这些石头嵌入大地印章中，就能解开两头龙的束缚。",al={"如何召唤布莱克拉什","大地印章","钻石猫眼石紫水晶石柱"}},{q="必须带回给高恩什么东西？",a="在两头龙死亡后，带回布莱克拉什的束缚物、赫玛图斯的锁链以及大地印章。",al={"破碎的联盟任务交付物品","高恩想要回什么","布莱克拉什的束缚物"}}},fp="16,137,16.354.0,21.228.1,21.86.0,32.99.0,38.140.0,34.113.0"}
P.entries["quest:79358"] = {n="Storm, Earth, and Fire",s="Veyric Thunderhame请你在阿拉希高地收集扭曲的元素图腾。他希望了解其他族群如何施展萨满教义，并找到应对quilboar元素法术的方法。",h="Veyric Thunderhame请你在阿拉希高地收集扭曲的元素图腾。他希望了解其他族群如何施展萨满教义，并找到应对quilboar元素法术的方法。",kw={"阿拉希高地","反制仪式","quilboar","萨满教义","风暴、大地与火焰","千针石林","扭曲的图腾","veyric thunderhame"},ang={["class:Shaman"]="作为一名萨满祭司，你受托帮助Veyric了解艾泽拉斯各族群施展萨满教义的方式，并理解扭曲的元素。"},sec={{t="反制仪式",b="quilboar淹没千针石林后，阿拉希高地的Veyric Thunderhame需要你的帮助。他说，他们对元素的运用引发了众怒，而要举行反制仪式，就必须更深入地了解这些扭曲的力量。一本书介绍了艾泽拉斯各族群施展萨满教义的方式。Veyric请你带给他扭曲的火焰、土、水和空气图腾，以便从中学习。"}},faq={{q="谁在索要这些图腾？",a="阿拉希高地的Veyric Thunderhame请你收集扭曲的火焰、土、水和空气图腾。",al={"谁要这些图腾","veyric的请求"}},{q="Veyric为什么需要这些图腾？",a="Veyric想要了解扭曲的元素，并以此为基础，设法用反制仪式对抗quilboar的元素法术。",al={"为什么要图腾","图腾有什么用"}},{q="千针石林发生了什么？",a="quilboar淹没了千针石林，Veyric说，他们对元素的运用引发了众怒。",al={"千针石林被淹","quilboar做了什么"}},{q="书中介绍了什么？",a="书中介绍了艾泽拉斯的各个族群，以及他们施展萨满教义的方式。",al={"萨满教义之书","书里写了什么"}},{q="Veyric要哪些图腾？",a="他要扭曲的火焰、土、水和空气图腾。",al={"图腾种类","火土气水"}}},fp="22,198,16.393.0,29.102.0,32.125.0,34.101.0,28.79.0,33.55.0"}
P.entries["quest:79360"] = {n="Elemental Aid",s="为了报答元素的援助，你受命前往剃刀沼泽。野猪人正在扭曲元素之力，他们的图谋威胁着这片土地。",h="为了报答元素的援助，你受命前往剃刀沼泽。野猪人正在扭曲元素之力，他们的图谋威胁着这片土地。",kw={"卡尔加·刺肋","elemental aid","元素","野猪人","野猪人计划","剃刀沼泽"},ang={["class:Shaman"]="作为一名萨满祭司，你已掌握元素之力。如今有人请你报答元素的援助，保护它们免受野猪人阴谋的侵害。"},sec={{t="向元素发出的召唤",b="元素曾助你一臂之力，如今有人请你回报这份恩情。野猪人正将元素之力据为己用，似乎还在不断扩大势力范围。你受命前往剃刀沼泽，阻止他们的阴谋，守护这片土地。"}},faq={{q="我为什么要去剃刀沼泽？",a="野猪人正将元素之力据为己用，似乎还在扩大势力范围。有人请你阻止他们的阴谋，守护这片土地。",al={"剃刀沼泽原因","为什么去剃刀沼泽","元素援助原因"}},{q="卡尔加·刺肋是谁？",a="卡尔加·刺肋是你受命前往剃刀沼泽击败的野猪人。",al={"卡尔加是谁","卡尔加·刺肋","刺肋"}},{q="我要收集什么情报？",a="有人请你收集野猪人的计划情报。",al={"野猪人计划","什么情报","计划情报"}},{q="我为什么要帮助元素？",a="你曾得到元素的援助，如今有人请你回报这份恩情，保护这片土地免受野猪人阴谋的侵害。",al={"元素援助为何","帮助元素","报答元素"}}},fp="13,154,22.256.0,35.154.0,26.76.0,39.61.0,31.128.0"}
P.entries["quest:79361"] = {n="Storm, Earth, and Fire",s="普拉特·白云请你阻止 Quilboar 施展邪恶萨满法术，淹没千针石林。一本供你修习的典籍或许能驱散即将到来的风暴。",h="普拉特·白云请你阻止 Quilboar 施展邪恶萨满法术，淹没千针石林。一本供你修习的典籍或许能驱散即将到来的风暴。",kw={"普拉特·白云","quilboar","storm, earth, and fire","千针石林","典籍","邪恶的萨满法术","被扭曲的图腾"},sec={{t="风暴将至",b="普拉特·白云原本打算继续指导你修行，但千针石林的威胁刻不容缓。你已经见识过 Quilboar 不容小觑。普拉特交给你一本供研习的典籍，并请你收集被扭曲的火焰、大地、空气和水之图腾。这本典籍或许藏有驱散他们即将引发的风暴之法。"}},faq={{q="谁在寻求帮助？",a="普拉特·白云请你在千针石林收集被扭曲的图腾。",al={"普拉特·白云是谁","普拉特·白云"}},{q="Quilboar 想做什么？",a="普拉特说，Quilboar 想通过邪恶的萨满法术淹没千针石林。",al={"quilboar 的计划","图腾的用途","quilboar 引发的风暴"}},{q="普拉特给了我什么？",a="普拉特给了你一本原本供研习的典籍，或许能驱散即将到来的风暴。",al={"典籍","这本书是什么","研习典籍"}},{q="普拉特需要哪些图腾？",a="普拉特请你收集被扭曲的火焰、大地、空气和水之图腾。",al={"图腾种类","火焰、大地、空气、水","需要哪些图腾"}}},fp="22,175,18.334.0,23.70.0,35.81.0,24.87.0,29.68.0"}
P.entries["quest:79362"] = {n="Grant's Shield",s="Sirra Von’Indie正在寻找Grant Valor留在乌鸦岭墓地的钉锤，他的灵魂仍在那里与亡灵战斗。这些武器或许能帮助她进一步了解这位骄傲的英雄。",h="Sirra Von’Indie正在寻找Grant Valor留在乌鸦岭墓地的钉锤，他的灵魂仍在那里与亡灵战斗。这些武器或许能帮助她进一步了解这位骄傲的英雄。",kw={"夜色镇","grant valor","grant的钉锤","grant的盾牌","乌鸦岭墓地","sirra von'indie","亡灵","the valor family"},sec={{t="部落英雄的灵魂",b="夜色镇的Sirra Von’Indie请你在乌鸦岭墓地的骷髅中寻找Grant Valor的钉锤。Grant的幽灵留下了他的盾牌，而他的灵魂仍在那里与亡灵战斗。这把钉锤或许能提供线索，找出打伤他的生物，Sirra想研究这些武器。"},{t="武器",b="在夜色镇，Sirra Von’Indie感叹，一个普通的生物竟然让Grant Valor落得如此下场。她说，一次失足就可能让人终身残疾。她相信，武器能透露许多主人的往事，因此花时间仔细研究它们。"}},faq={{q="Grant Valor是谁？",a="Grant Valor是The Valor Family的父亲，也是乌鸦岭的英雄。他的幽灵仍在与亡灵战斗。",al={"grant valor","grant是谁","grant的往事"}},{q="Grant的钉锤在哪里？",a="Grant的钉锤在乌鸦岭墓地的一具骷髅身上。",al={"grant的钉锤","寻找grant的钉锤","钉锤位置"}},{q="我为什么要寻找Grant的钉锤？",a="Sirra Von’Indie请你找到钉锤，以便从Grant的武器中了解更多。",al={"为什么寻找钉锤","grant的盾牌任务","sirra想要什么"}},{q="我该把钉锤带到哪里？",a="把Grant的钉锤交还给夜色镇的Sirra Von’Indie。",al={"归还钉锤","sirra的位置","von'indie在哪里"}},{q="Grant遭遇了什么？",a="Grant在乌鸦岭墓地被一个生物打伤。他的灵魂仍在那里与亡灵战斗。",al={"grant受伤","grant是怎么受伤的","grant valor的盾牌"}}},fp="14,169,13.298.0,11.234.1,20.110.0,22.65.0,34.89.0,25.56.0,23.98.0"}
P.entries["quest:79363"] = {n="西尔维娅的剑",s="Silvia Valor的灵魂留下的剑，指引你前去寻找乌鸦岭附近的迪菲亚。这把剑的主人曾是一名守卫，保护着平民和他们的家园。",h="Silvia Valor的灵魂留下的剑，指引你前去寻找乌鸦岭附近的迪菲亚。这把剑的主人曾是一名守卫，保护着平民和他们的家园。",kw={"腐草农场","夜色镇","迪菲亚","守卫","乌鸦岭","silvia valor","silvia的剑","希拉·沃宁迪","未了的心愿"},sec={{t="守卫之剑",b="乌鸦岭的守卫Silvia Valor的灵魂留下了她的剑。Silvia一生都在保护平民和他们的家园。她的灵魂仍会造访各处农庄，而迪菲亚已在乌鸦岭以南的腐草农场盘踞下来。赶走他们或许就是她未了的心愿，夜色镇的希拉·沃宁迪正等着听取此事的结果。"},{t="研究佩剑",b="在腐草农场，迪菲亚是查明Silvia Valor未了心愿的第一条线索。当你回到夜色镇的希拉·沃宁迪身边时，她承认Silvia是一名出色的战士和守护者，只是对于谁值得保护，她的看法颇为狭隘。Sirra无法判断Silvia想借这把剑达成什么心愿，于是继续研究这把剑。"}},faq={{q="Silvia Valor是谁？",a="Silvia Valor曾是乌鸦岭的一名守卫，一生都在保护平民和他们的家园。",al={"silvia valor的身世","silvia是谁","乌鸦岭守卫silvia"}},{q="Silvia的灵魂为什么在各处农庄徘徊？",a="Silvia的灵魂仍会造访各处农庄，她未了的心愿或许与腐草农场的迪菲亚有关。",al={"silvia的幽灵为何徘徊","她为何在农场徘徊","silvia未了的心愿"}},{q="谁在询问Silvia的剑？",a="夜色镇的希拉·沃宁迪接着讲述这把剑的故事。解决腐草农场的迪菲亚之后，你回到她那里，进一步了解Silvia Valor的往事。",al={"谁给了silvia的剑","希拉·沃宁迪的剑","夜色镇给剑的人"}},{q="迪菲亚盘踞在哪里？",a="迪菲亚已经盘踞在乌鸦岭以南的腐草农场。",al={"迪菲亚腐草农场","迪菲亚在哪里","乌鸦岭迪菲亚"}},{q="Sirra如何评价Silvia？",a="Sirra称Silvia是一名出色的战士和守护者，但也说她对于谁值得保护的看法颇为狭隘。",al={"sirra对silvia的评价","战士silvia","silvia是怎样的守卫"}},{q="Sirra如何处理这把剑？",a="Sirra继续研究Silvia Valor的剑。",al={"这把剑的后续","sirra研究佩剑","silvia的剑后续"}}},fp="14,154,15.360.0,17.332.1,21.95.0,43.109.0,30.150.0,41.73.0,32.116.0,34.43.0"}
P.entries["quest:79364"] = {n="Eyes on the Sky",s="一张纸条警告，钢鬃正在千针石林举行一场隐秘仪式。你受托查明风暴与潮水上涨带来的威胁。",h="一张纸条警告，钢鬃正在千针石林举行一场隐秘仪式。你受托查明风暴与潮水上涨带来的威胁。",kw={"元素巫术","仰望天空","hirzek","普拉特·白云","quilboar","钢鬃","上涨的潮水","仪式","风暴","千针石林"},sec={{t="迫近的威胁",b="你找到的纸条指向千针石林的钢鬃，那里正在举行一场隐秘仪式。狂暴的风暴和不断上涨的潮水令人担心峡谷可能被淹没。Quilboar或许正运用从萨满Hirzek那里学来的元素之力。回到盟友身边，与普拉特·白云交谈。"}},faq={{q="纸条上写了什么？",a="纸条上说，钢鬃已钻入千针石林举行一场隐秘仪式，那里风暴狂暴，潮水不断上涨。",al={"千针石林的纸条","纸条内容","钢鬃纸条"}},{q="Hirzek是谁？",a="Hirzek是一名萨满，他教会Quilboar扭曲元素的巫术。",al={"hirzek","hirzek萨满","hirzek是谁"}},{q="Quilboar构成什么威胁？",a="令人担忧的是，Quilboar可能会运用元素之力淹没峡谷。",al={"quilboar的威胁","钢鬃仪式","quilboar在做什么"}},{q="我应该和谁交谈？",a="你受托前往千针石林，与普拉特·白云交谈。",al={"前往何处","寻找谁","普拉特·白云"}}},fp="15,160,18.309.0,23.116.0,14.76.0,33.85.0,24.64.0"}
P.entries["quest:79365"] = {n="With Wind Beneath Your Wings",s="Squall-breakers Potion可在短时间内保护你免受风暴侵袭。你被派回千针石林的乱风岗，去找劳恩·峭壁行者。",h="Squall-breakers Potion可在短时间内保护你免受风暴侵袭。你被派回千针石林的乱风岗，去找劳恩·峭壁行者。",kw={"乱风岗","劳恩·峭壁行者","squall-breakers potion","风暴","千针石林"},sec={{t="返回乱风岗",b="风暴仍在威胁你的朋友，而药剂的保护只能持续片刻。返回千针石林的乱风岗，去找劳恩·峭壁行者；你的朋友正等着你去帮助他们。"}},faq={{q="药剂有什么作用？",a="Squall-breakers Potion可在短时间内保护你免受风暴侵袭。",al={"药剂防护","squall-breakers potion"}},{q="我该回去找谁？",a="返回千针石林的乱风岗，去找劳恩·峭壁行者。",al={"去哪里","劳恩·峭壁行者"}},{q="我为什么要回去？",a="你被派回去帮助身陷困境的朋友。",al={"需要帮助的朋友","回去找朋友"}}},fp="28,152,16.197.0,24.92.0,23.63.0,20.48.0"}
P.entries["quest:79366"] = {n="Heed My Call",s="你用 Twisted Totems 对付钢鬃的仪式，随后向劳恩·峭壁行者报告。受腐化的元素生物可能会让这片土地无法恢复洁净。",h="你用 Twisted Totems 对付钢鬃的仪式，随后向劳恩·峭壁行者报告。受腐化的元素生物可能会让这片土地无法恢复洁净。",kw={"受腐化的元素生物","大地之环","听从我的召唤","quilboar","劳恩·峭壁行者","钢鬃","仪式","steam pools","twisted totems"},sec={{t="在 Steam Pools",b="手持 Twisted Totems，你已准备好打断钢鬃的仪式。有人告诉你，先去西边的 Steam Pools，那里各种元素都很充沛。quilboar 会抵抗你的行动。用图腾对付仪式及其受腐化的元素生物。"},{t="劳恩的感谢",b="劳恩·峭壁行者问你是否带来了风暴的消息。你回来时，他得知隆隆作响的大地已经归于沉寂，并感谢你为大地之环争得了荣誉。"}},faq={{q="劳恩·峭壁行者要我做什么？",a="劳恩·峭壁行者要你用 Twisted Totems 终结 quilboar 的仪式，然后回来向他报告成功的消息。",al={"劳恩·峭壁行者的任务","劳恩要什么"}},{q="我该从哪里开始？",a="从西边的 Steam Pools 开始，那里各种元素都很充沛。",al={"从哪里开始","steam pools"}},{q="Twisted Totems 有什么用？",a="Twisted Totems 用来召唤 quilboar 所依仗的受腐化元素生物。",al={"twisted totems","图腾的用途"}},{q="谁在举行仪式？",a="钢鬃 quilboar 正在举行仪式，召唤受腐化的元素生物。",al={"谁在举行仪式","钢鬃仪式"}},{q="quilboar 为什么会抵抗？",a="有人警告你，quilboar 不会坐视你打断他们的计划。",al={"quilboar 抵抗","为什么攻击我"}}},fp="12,155,18.271.0,12.170.1,40.122.0,21.70.0,32.87.0,29.84.0,30.83.0"}
P.entries["quest:794"] = {n="火刃奖章",s="这项任务由术士祖雷萨指派，要求年轻的部落新兵深入试炼谷的火刃集会所洞穴。在那里，玩家必须直面一名潜藏的邪教徒，并找回一件名为火刃奖章的黑暗魔法神器。这项任务揭示了恶魔的腐化正在部落的眼皮底下生根发芽。",h="这项任务由术士祖雷萨指派，要求年轻的部落新兵深入试炼谷的火刃集会所洞穴。在那里，玩家必须直面一名潜藏的邪教徒，并找回一件名为火刃奖章的黑暗魔法神器。这项任务揭示了恶魔的腐化正在部落的眼皮底下生根发芽。",kw={"火刃氏族","集会所","杜隆塔尔","奖章","大兽穴","试炼谷","术士","亚罗格·刺影","祖雷萨"},ang={["class:Shaman"]="找回受污染的圣物有助于祖雷萨揭露那些玷污杜隆塔尔大地的恶魔腐化。",["class:Warlock"]="直面亚罗格是一个严酷的提醒，警示着在萨尔统治下所制定的受认可、经过仔细隐藏的契约之外，进行堕落的恶魔崇拜所带来的危险。",["faction:Horde"]="这项任务代表了年轻新兵的最终试炼，标志着他们已准备好前往杜隆塔尔更广阔的荒野，以保卫这个年轻的国家。",["race:Orc"]="追捕亚罗格·刺影凸显了新部落在训练场内清除旧时代残留恶魔污秽的内部斗争。"},sec={{t="谷中的隐藏威胁",b="当年轻的兽人和巨魔在试炼谷进行基础的战斗与生存试炼时，一股阴险的威胁正潜伏在阴影中。通过占卜，术士祖雷萨感觉到那些盘踞在北部峭壁上的邪恶魔仆只不过是更黑暗势力的先遣队。在附近的一个洞穴深处，火刃氏族建立了一个隐秘的集会所，他们在那练习黑暗魔法，并窝藏着危险的恶魔力量圣物。"},{t="直面亚罗格·刺影",b="这枚奖章正掌握在亚罗格·刺影手中，这是一名充当火刃氏族代理人的兽人术士。亚罗格躲藏在地下大兽穴深处的一处高台上，指挥着邪能野兽并施展黑暗魔法，避开了谷中监视者的目光。击败他并夺取奖章，可以在该邪教的仪式进一步蔓延到杜隆塔尔腹地之前，扰乱其当地的领导层。"},{t="挥之不去的阴影",b="获得这枚护身符证实了祖雷萨最担心的事。虽然试炼谷中的集会所已被拆除，但奖章证明了火刃氏族是有组织、有目的地在行动。该邪教的触角已远超试炼场，预示着羽翼未丰的部落将在整个杜隆塔尔面临更广泛的恶魔阴谋。"}},faq={{q="我在哪里可以找到火刃集会所？",a="火刃集会所位于试炼谷大兽穴西北方峭壁内的一个洞穴中，周围环绕着类似小鬼的邪恶魔仆。",al={"集会所洞穴位置","洞穴在哪里","试炼谷火刃氏族洞穴"}},{q="谁持有火刃奖章？",a="奖章由亚罗格·刺影持有，这名堕落的兽人邪教徒位于洞穴深处，处于浅水池后方的一处凸起的岩石平台上。",al={"谁掉落奖章","亚罗格·刺影","奖章持有者"}},{q="火刃氏族是什么？",a="火刃氏族是一个背叛的邪教组织，由受到邪能腐蚀的兽人和术士组成，他们沉迷于恶魔力量，并从隐藏的巢穴和营地中积极策划对抗萨尔的新部落。",al={"火刃氏族是什么","火刃邪教"}},{q="为什么这枚奖章对祖雷萨如此重要？",a="祖雷萨通过她的占卜发现了这枚奖章。它是一件能够助长邪教黑暗仪式的力量物品，并提供了无可辩驳的证据，证明恶魔特工正在渗透试炼谷。",al={"为什么祖雷萨想要它","什么是奖章","祖雷萨奖章"}},{q="击败 亚罗格 能彻底铲除杜隆塔尔的邪教吗？",a="不能。虽然 亚罗格 的死亡净化了试炼谷的洞穴，但祖雷萨警告说，这个集会所只是一个小组织，火刃氏族在整个杜隆塔尔还有更大的野心。",al={"火刃氏族被消灭了吗","他们消失了吗","火刃奖章之后"}},{q="上交奖章后会发生什么？",a="在击杀 亚罗格 并找回圣物证明了你的价值后，你被认为已经准备好离开试炼谷，并被指引前往杜隆塔尔南海岸的森金村报到。",al={"下一个任务","接下来是什么","完成此任务后"}}},fp="23,237,29.405.0,29.348.1,20.290.1,40.143.0,44.124.0,26.183.0,54.170.0,53.177.0,44.191.0"}
P.entries["quest:79442"] = {n="The Tempest's Weapons",s="奥特兰克山脉的一位老萨满或许知道如何使用 Eye of the Tempest。你把这件神器带给他，好让他借助其中的风暴魔法进行打造。",h="奥特兰克山脉的一位老萨满或许知道如何使用 Eye of the Tempest。你把这件神器带给他，好让他借助其中的风暴魔法进行打造。",kw={"奥特兰克山脉","巴斯拉","捕风者巴斯拉","eye of the tempest","萨满","风暴元素魔法","the tempest's weapons"},ang={["class:Shaman"]="身为萨满，你把一件蕴含强大风暴元素魔法的神器带给巴斯拉。他是一位精通这种魔法的老萨满。"},sec={{t="一位老萨满",b="与元素生物交战后，你把 Eye of the Tempest 带给奥特兰克山脉的捕风者巴斯拉。他对风暴元素魔法颇有见识，也看出了这件神器蕴藏的力量。巴斯拉说，他已经很久没接触过类似的东西了，并叮嘱你要好好保管。"}},faq={{q="巴斯拉是谁？",a="捕风者巴斯拉是奥特兰克山脉的一位老萨满，对风暴元素魔法颇有见识。",al={"捕风者巴斯拉","老萨满","巴斯拉是谁"}},{q="Eye of the Tempest 是什么？",a="Eye of the Tempest 是一件与风暴元素魔法有关的强大神器。",al={"tempest之眼","之眼神器","这只眼睛是什么"}},{q="为什么要把 Eye of the Tempest 带给巴斯拉？",a="巴斯拉了解风暴元素魔法，或许能用 Eye of the Tempest 打造出某种物品。",al={"为何找巴斯拉","tempest之眼武器任务","该把 eye of the tempest 带到哪里"}},{q="巴斯拉对这件神器怎么说？",a="巴斯拉称 Eye of the Tempest 威力强大，还说自己已经很久没用类似的东西打造物品了。",al={"巴斯拉的反应","他说了什么","eye of the tempest 完成情况"}}},fp="21,147,13.305.0,16.105.0,31.84.0,30.113.0,42.112.0"}
P.entries["quest:79535"] = {n="Basilisks: Should Petrification be Feared?",s="图书管理员请你带来能丰富馆藏的魔法典籍。你的发现能拓展图书馆的知识。",h="图书管理员请你带来能丰富馆藏的魔法典籍。你的发现能拓展图书馆的知识。",kw={"蛇怪","馆藏","知识","图书馆","魔法典籍","石化"},sec={{t="不断丰富的馆藏",b="图书管理员感谢你为馆藏添入新作。你的努力为图书馆带来了新知识，那里或许还需要更多魔法典籍。"}},faq={{q="图书管理员想要什么？",a="图书管理员欢迎能充实馆藏的魔法典籍。",al={"图书馆委托","该带什么"}},{q="为什么需要魔法典籍？",a="图书管理员说，这些典籍能充实图书馆，拓展馆藏知识。",al={"为什么要书","这些书有何用"}},{q="我带来东西后会怎样？",a="图书管理员向你道谢，说你的努力拓展了图书馆的知识。",al={"馆藏更新","我添了什么"}}},fp="42,133,20.151.0,29.71.0,29.73.0,36.79.0"}
P.entries["quest:79624"] = {n="Anyone Can Cook",s="一份难以辨认的食谱似乎描述了一道肉菜，你猜那是食人魔文字。找一位能读懂它的食人魔。",h="一份难以辨认的食谱似乎描述了一道肉菜，你猜那是食人魔文字。找一位能读懂它的食人魔。",kw={"人人都能做菜","难以辨认的食谱","肉菜","食人魔","食谱","skonk","翻译"},ang={["profession:Cooking"]="作为一名厨师，你自然会好奇这份难以辨认的食谱描述了什么肉菜。"},sec={{t="奇怪的食谱",b="这份食谱写在一种你看不懂的语言里，内容似乎是一道肉菜。考虑到它的来历和描述的内容，你猜最有可能是食人魔语。你希望能找到一位食人魔帮忙翻译。"}},faq={{q="这份食谱写的是什么？",a="看起来像是某种肉菜的做法。",al={"食谱用途","什么菜","肉菜食谱"}},{q="这份食谱是用什么语言写的？",a="你看不懂这种语言。你猜最有可能是食人魔语。",al={"食谱语言","什么文字","看不懂食谱"}},{q="谁能读懂这份食谱？",a="你正在寻找一位能读懂它的食人魔。",al={"翻译食谱","谁能读懂","食人魔读者"}},{q="Skonk是谁？",a="Skonk是一名食人魔，正在打听这份食谱。",al={"skonk","skonk是谁","食人魔skonk"}}},fp="15,112,16.213.0,23.44.0,39.60.0,24.44.0,13.49.0"}
P.entries["quest:79677"] = {n="A Quick Grocery Run",s="Skonk请你在阿拉希高地收集烹制一道菜所需的食材。其他食人魔嘲笑他的体型和战斗能力后，他学会了烹饪。",h="Skonk请你在阿拉希高地收集烹制一道菜所需的食材。其他食人魔嘲笑他的体型和战斗能力后，他学会了烹饪。",kw={"阿拉希高地","烹饪","菜肴","食材","食人魔","skonk","嘲笑"},ang={["profession:Cooking"]="作为一名厨师，你可以帮Skonk收集烹制一道他会做的菜所需的食材。"},sec={{t="Skonk的食材",b="Skonk是阿拉希高地的一名食人魔，需要烹制一道他会做的菜所需的食材。其他食人魔嘲笑他个头小，还说他软弱，于是他转而学习烹饪。你收集食材后把它们交给他。"}},faq={{q="Skonk是谁？",a="Skonk是一名食人魔，其他食人魔嘲笑他的体型和战斗能力后，他学会了烹饪。",al={"skonk","谁是skonk"}},{q="Skonk为什么烹饪？",a="其他食人魔嘲笑Skonk个头小，还说他软弱，于是他学会了烹饪，而不是战斗。",al={"为何烹饪","skonk烹饪"}},{q="Skonk需要什么？",a="Skonk需要烹制一道他会做的菜所需的食材。",al={"食材","需要什么食材"}},{q="我该把食材交给谁？",a="把食材交给阿拉希高地的Skonk。",al={"skonk在哪","交付食材"}}},fp="19,143,19.214.0,13.92.0,20.107.0,21.47.0,33.51.0"}
P.entries["quest:79678"] = {n="Taste Testing",s="Skonk请你品尝一道在旺火上烹制的新菜。这是他与新朋友分享的方式，而你曾帮助过他。",h="Skonk请你品尝一道在旺火上烹制的新菜。这是他与新朋友分享的方式，而你曾帮助过他。",kw={"菜肴","火","食物","菜谱","skonk","品尝新菜","品尝"},sec={{t="一道新菜",b="Skonk在火上备好了一道新菜，想与你分享。你帮了他不少忙，他觉得你也该尝尝。这道菜已经做好，等你品尝。"}},faq={{q="Skonk是谁？",a="Skonk做了一道新菜，邀请你品尝。",al={"skonk","skonk是谁"}},{q="Skonk想让我做什么？",a="Skonk想和你一起品尝这道菜。",al={"品尝","skonk想要什么"}},{q="Skonk为什么要分享这道菜？",a="Skonk说你帮了他很多忙，所以想让你尝尝他的新菜。",al={"为什么要吃东西","为什么分享"}},{q="Skonk觉得这道菜怎么样？",a="品尝之后，Skonk说这道菜很美味。",al={"好吃吗","品尝菜谱"}}},fp="13,131,10.189.0,13.55.0,30.45.0,30.78.0,36.54.0"}
P.entries["quest:79947"] = {n="Geomancy: The Stone-Cold Truth",s="一位图书管理员正在为图书馆搜寻魔法典籍。你也能为扩充馆藏、增长知识出一份力。",h="一位图书管理员正在为图书馆搜寻魔法典籍。你也能为扩充馆藏、增长知识出一份力。",kw={"馆藏","地脉学","图书馆","魔法典籍","石冷的真相"},sec={{t="不断扩充的馆藏",b="你找到的任何魔法典籍，都可能被收入图书馆的书架。在你的帮助下，馆藏不断增加，图书管理员也欢迎你带来更多发现。"}},faq={{q="图书管理员想要什么？",a="图书管理员请你带来有益于图书馆馆藏的魔法典籍。",al={"他们想要什么","图书馆请求"}},{q="这项请求来自哪里？",a="请求来自一位图书管理员：联盟的 Garion Wendell 位于暴风城，部落的 Owen Thadd 位于幽暗城。",al={"图书馆在哪里","铁炉堡图书馆"}},{q="为什么要带来魔法典籍？",a="图书管理员说，你的努力能让图书馆的知识不断增长。",al={"为什么要魔法书","这些书有什么用"}}},fp="30,110,20.159.0,29.90.0,27.118.0,24.72.0"}
P.entries["quest:79948"] = {n="Defensive Magics 101",s="图书馆正在为馆藏搜寻魔法典籍。你可以带来可能有益于馆藏的著作，帮助拓展图书馆的知识。",h="图书馆正在为馆藏搜寻魔法典籍。你可以带来可能有益于馆藏的著作，帮助拓展图书馆的知识。",kw={"馆藏","防护魔法","知识","图书馆","魔法典籍"},sec={{t="不断丰富的馆藏",b="图书馆的馆藏可以在你的帮助下不断丰富。把可能适合入藏的魔法典籍交给馆员，图书馆的知识便会随之扩展。"}},faq={{q="图书馆需要什么？",a="图书馆正在征集可能适合入藏的魔法典籍。",al={"图书馆需要什么","带什么来","魔法书籍"}},{q="这项请求来自哪里？",a="这项请求来自一位图书管理员。联盟方面是暴风城的 Garion Wendell，部落方面则是幽暗城的 Owen Thadd。",al={"是谁提出的","图书馆的请求","哪座图书馆"}},{q="为什么要带来魔法典籍？",a="带到图书馆的魔法典籍能拓展图书馆的知识。",al={"为何收集魔法典籍","有什么帮助","图书馆馆藏"}}},fp="20,137,20.153.0,27.66.0,27.135.0,24.58.0"}
P.entries["quest:79949"] = {n="A Web of Lies: Debunking Myths and Legends",s="一位图书管理员想搜集魔法典籍，充实图书馆的藏书。你可以带来有益于馆藏的著作。",h="一位图书管理员想搜集魔法典籍，充实图书馆的藏书。你可以带来有益于馆藏的著作。",kw={"书籍","馆藏","知识","图书管理员","图书馆","魔法典籍"},sec={{t="不断扩充的藏书",b="每一本新书都值得珍藏在这些书架上。魔法著述或许能丰富图书馆的知识，而你的发现也能助其增长。"}},faq={{q="图书管理员想要什么？",a="图书管理员想搜集可能有益于馆藏的魔法典籍。",al={"图书管理员需要什么","图书馆的需求","该带什么去图书馆"}},{q="我该把书带到哪里？",a="请将魔法典籍交给暴风城的图书管理员 Garion Wendell；如果你属于部落，也可以交给幽暗城的 Owen Thadd。",al={"图书馆在哪里","铁炉堡图书馆","魔法典籍该带到哪里"}},{q="为什么要搜集魔法典籍？",a="图书管理员说，馆藏能丰富图书馆的知识。",al={"为什么要带书","馆藏有何用途","图书馆的用途"}}},fp="42,122,20.145.0,29.68.0,31.117.0,26.68.0"}
P.entries["quest:79950"] = {n="Demons and You",s="图书管理员请你为馆藏增添一部魔法典籍。你的努力让图书馆的知识更加丰富。",h="图书管理员请你为馆藏增添一部魔法典籍。你的努力让图书馆的知识更加丰富。",kw={"馆藏","恶魔与你","知识","图书馆","魔法典籍"},sec={{t="图书馆藏书",b="你带来的任何魔法著作都可上架收藏。藏书因你的努力而日渐丰富，管理员也欢迎你继续带来有益于图书馆的著作。"}},faq={{q="图书管理员想要什么？",a="管理员请你带来一部魔法典籍，加入图书馆的馆藏。",al={"该带什么","图书馆的请求","恶魔与你任务"}},{q="馆藏在哪里？",a="管理员是一位图书管理员。联盟方面是暴风城的 Garion Wendell，部落方面则是幽暗城的 Owen Thadd。",al={"这里在哪里","图书馆位置","哪座图书馆"}},{q="为什么要把魔法典籍带到图书馆？",a="管理员说，你的努力能丰富图书馆的知识。",al={"为什么捐赠书籍","这是做什么用的","图书馆的用途"}}},fp="14,118,20.166.0,34.81.0,24.126.0,39.62.0"}
P.entries["quest:79951"] = {n="Mummies: A Guide to the Unsavory Undead",s="一位图书管理员正在为馆藏搜集有关木乃伊与令人厌恶的亡灵的魔法典籍。你的捐赠能丰富图书馆的知识。",h="一位图书管理员正在为馆藏搜集有关木乃伊与令人厌恶的亡灵的魔法典籍。你的捐赠能丰富图书馆的知识。",kw={"书籍","藏书","图书馆","魔法典籍","木乃伊","令人厌恶的亡灵"},sec={{t="不断扩充的藏书",b="图书馆的藏书依靠访客带来的书籍不断充实。你受托带来一些有关木乃伊与令人厌恶的亡灵的内容，其他魔法书籍或许也能派上用场。每一本这样的书都能拓展图书馆的知识。"}},faq={{q="图书管理员在收集什么？",a="图书管理员正在寻找有关木乃伊与令人厌恶的亡灵的书籍，以及其他可能对图书馆有益的魔法书籍。",al={"木乃伊书籍","亡灵指南","他们想要什么书"}},{q="为什么要把书带到图书馆？",a="带给图书管理员的书籍能丰富图书馆的知识。",al={"为什么要送书","图书馆能获得什么","帮助图书馆"}},{q="我可以带其他魔法书吗？",a="可以。图书管理员欢迎其他可能对图书馆有益的魔法典籍。",al={"其他魔法书","更多魔法典籍","我还能带什么"}}},fp="39,144,20.229.0,33.127.0,32.64.0,32.79.0"}
P.entries["quest:79952"] = {n="RwlRwlRwlRwl!",s="图书管理员欢迎您将魔法著作捐赠给图书馆馆藏。您的捐赠有助于增长馆藏知识。",h="图书管理员欢迎您将魔法著作捐赠给图书馆馆藏。您的捐赠有助于增长馆藏知识。",kw={"馆藏","知识","图书馆","魔法典籍","rwl"},sec={{t="日渐丰富的馆藏",b="每一份新增藏书都能拓展馆藏知识，管理员也为此向您致谢。欢迎继续捐赠可能对馆藏有益的著作。"}},faq={{q="图书馆管理员想要什么？",a="管理员欢迎捐献有益于图书馆馆藏的魔法典籍。",al={"图书馆书籍","魔法典籍","需要带什么"}},{q="这批馆藏在哪里？",a="此处未提及城市。像这样的书可以交给暴风城的 Garion Wendell，或幽暗城的 Owen Thadd。",al={"图书馆位置","铁炉堡图书馆","图书馆在哪里"}},{q="为什么要带来魔法典籍？",a="你的捐献能让图书馆的知识更加丰富。",al={"为什么要捐书","帮助图书馆","有何意义"}}},fp="13,113,20.138.0,34.76.0,25.99.0,24.53.0"}
P.entries["quest:79974"] = {n="Wet Job",s="Wet Job是一个任务，其核心在于寻找一个遗留在高耸山腰上的应急补给箱。为了应对突发撤离的情况，这个补给箱被隐藏在风景秀丽的悬崖边，其中存放的物资通过精巧的矮人工艺得到了妥善保护。",h="Wet Job是一个任务，其核心在于寻找一个遗留在高耸山腰上的应急补给箱。为了应对突发撤离的情况，这个补给箱被隐藏在风景秀丽的悬崖边，其中存放的物资通过精巧的矮人工艺得到了妥善保护。",kw={"矮人工程","鹰巢","邮差包","山腰","羊皮纸","储备物资","补给品","脏活"},ang={["class:Rogue"]="对于生活在阴影中的人来说，将隐藏的应急补给箱藏好以备匆忙撤离，是他们的第二天性。",["profession:Engineering"]="该补给箱展示了矮人工程的独创性，作为隐藏在崎岖地形中的可靠应急库存。",["race:Dwarf"]="在找回补给箱的过程中，矮人工艺受到了赞誉，突显了他们山地手工制品持久的品质。"},sec={{t="应急补给箱",b="那些在危险条件下行动的人深知，不准备备用计划绝不能贸然行动。Wet Job要求定位一个隐藏在崎岖高地上的储备物资。作为紧急情况下的备用措施，万一需要快速撤离，这个补给箱便可以在计划出错时随时取用。"},{t="鹰巢",b="线索直接指向一处风景优美的山地制高点，诗意地描述为从时间的瀑布中雕刻而成。在这面岩壁的高处坐落着所谓的“鹰巢”。在那里，半埋在地下的一个风化邮差包，利用可靠的矮人工艺保护着里面的物资和羊皮纸，使其免受自然环境的侵蚀。"}},faq={{q="湿活是什么任务？",a="湿活是一个涉及找回隐藏在地貌中的应急储备物资的任务。准备这个补给箱的人确保了在需要紧急撤离时，物资能够得到保障。",al={"什么是水下工作","水下工作任务","水下工作是什么类型的任务"}},{q="是谁留下了这个储备物资？",a="这个物资是由一个为防万一需要匆忙撤离而准备应急储备的人所留下的。找回的邮差包中藏有羊皮纸和通过卓越矮人工程制造的物资。",al={"是谁留下了储备物资","这些物资是谁的","谁隐藏了应急补给"}},{q="补给箱藏在哪里？",a="线索指向一处风景如画的山腰，那里被描述为从时间的瀑布中雕刻而成，具体指引寻找者前往岩壁高处的一处鹰巢，在那里邮差包从泥土中显露出来。",al={"补给箱在哪里","水下工作位置","鹰巢位置"}},{q="邮差包里有什么？",a="打开埋藏的邮差包，会发现里面有必需的补给品和一张隐藏的羊皮纸，它们受到坚固耐用的矮人工艺的保护。",al={"补给箱里有什么","水下工作物品","你会发现什么"}},{q="为什么这个任务被称为湿活？",a="虽然这个标题通常暗示隐秘或混乱的现场行动，但在这里它直接联系到山地的地标，周围是迷雾、时间的瀑布以及隐藏包裹的潮湿泥土。",al={"为什么叫水下工作","水下工作名字含义"}},{q="矮人工程是如何参与的？",a="在发现并打开补给箱后，该补给箱的结构和可靠性被赞誉为矮人工程的奇迹，足以承受户外埋藏环境。",al={"与矮人工程的联系","这是矮人制造的吗"}}},fp="7,154,18.194.0,16.273.0,32.80.0,27.162.0,26.163.0,35.84.0,31.103.0,36.101.0"}
P.entries["quest:79975"] = {n="Eagle's Fist",s="Eagle's Fist围绕着一封在迷雾缭绕的高海拔制高点工具箱中发现的神秘信件展开。信中揭示了一名孤独的哨兵，出于对旧王国以及“鹰与拳”的忠诚，守护着一座风化的路障。尽管篝火刚添过柴，但守望者已匆忙离开。",h="Eagle's Fist围绕着一封在迷雾缭绕的高海拔制高点工具箱中发现的神秘信件展开。信中揭示了一名孤独的哨兵，出于对旧王国以及“鹰与拳”的忠诚，守护着一座风化的路障。尽管篝火刚添过柴，但守望者已匆忙离开。",kw={"路障","篝火","鹰之拳","折叠的信","瞭望点","旧王国","降落伞滑翔机","工具箱"},ang={["profession:Engineering"]="这名瞭望者的笔记强调了此地是部署降落伞滑翔机的理想出发点，吸引了那些青睐空中侦察和机械飞行的工程学爱好者的注意。"},sec={{t="一处隐蔽的栖身之所",b="在一处风景优美的制高点，一个不起眼的工具箱里藏着一封折叠整齐的信。作者反思了这个高处瞭望台居高临下的位置，感叹这里既可以掌控全局，也能发射降落伞滑翔机飞越地貌。在这片被水雾浸湿的孤独哨位上，可以将历史悠久的土地尽收眼底。"},{t="对旧王国的忠诚",b="写信人声称对“鹰与拳”怀有深厚而持久的忠诚，并指出要妥善效忠于这一事业，需要保持适当的距离。虽然承认当地的路障已经年久失修——正如它曾经抵御危险的旧王国一样——但这位坚定的守望者发誓绝不会真正放弃这个岗位。"},{t="匆忙离去",b="不论是谁负责这个瞭望点，他们离开时都十分匆忙。发现该岗位的游客会看到一堆刚添过新柴的篝火，但哨兵却消失得无影无踪，只留下了工具、燃烧的余烬和那封神秘的信。"}},faq={{q="什么是鹰拳？",a="鹰拳是一次围绕着一个隐藏工具箱的遭遇，箱内装有一封折叠整齐的信，位于俯瞰一座旧路障、风景优美且雾气缭绕的制高点。它标志着一位最近逃离的神秘斥候的营地。",al={"什么是鹰之拳","鹰之拳任务","这是什么任务"}},{q="工具箱里的信是谁写的？",a="作者是一位身份不明的斥候或哨兵，忠于旧王国以及一个被称为“鹰与拳”的实体或联盟。他们在这座破败的路障处进行着孤独的守望。",al={"谁写的便条","谁留下的信","工具箱信件作者"}},{q="“鹰与拳”指的是什么？",a="信中提到了对“鹰与拳”的忠诚，并指出只有保持距离才能更好地效忠。虽然确切的组织情况仍是个谜，但它与保卫旧王国的残余势力有关。",al={"什么是鹰与拳","鹰与拳的含义","鹰与拳是谁"}},{q="营地为何被废弃了？",a="这名斥候匆匆离开，留下了一堆刚添过新柴的篝火。他们的去向仍然未知，不过这个地点被赞誉为部署降落伞滑翔机的绝佳场所。",al={"斥候去哪了","他们为何离开","谁添加的篝火燃料"}},{q="正在防守的是什么路障？",a="作者感叹该路障已不复往昔，将其破损的状态比作它曾经守护的、已陨落的人类旧王国，但却誓言绝不放弃对它的守卫。",al={"什么路障","哪些旧王国","路障背景故事"}},{q="这是一个什么样的瞭望点？",a="这个岗哨拥有绝佳的全景视野，空气中弥漫着水雾，表明它位于大型瀑布或湍流河道附近的高耸悬崖或制高点上。",al={"地点位置","为什么有水雾","鹰之拳位置"}}},fp="12,190,14.236.0,27.295.0,17.175.1,21.129.0,42.145.0,40.167.0,30.161.0,33.151.0,34.147.0"}
P.entries["quest:79976"] = {n="This Must Be The Place",s="This Must Be The Place标记了一个刚刚废弃的营地，其主人就在不久前刚刚消失。留下来的一张字条碎片揭示了这位神秘的作者为了防止研究成果落入不轨之徒手中，已转入地下继续工作。",h="This Must Be The Place标记了一个刚刚废弃的营地，其主人就在不久前刚刚消失。留下来的一张字条碎片揭示了这位神秘的作者为了防止研究成果落入不轨之徒手中，已转入地下继续工作。",kw={"废弃营地","装备包","藏身处","睡袋","一定就是这里","字条碎片","地下"},sec={{t="匆忙离开",b="在这个偏僻的地方，一位身份不明的旅者刚刚匆忙撤离营地。现场只留下一只摊开在脚下的睡袋、捆扎着各类装备的沉重帆布，以及一张撕得刚好写下一句匆忙告别的字条。无论谁曾在这里露营，都在别人赶到之前就已不见踪影。"},{t="转入地下",b="留下的字条揭示了作者决定将他们的工作带回地下，以确保其不会落入不轨之徒的手中。这张字条究竟是最后的告别，还是暗示研究者下一个隐秘据点的线索，目前还不得而知，只留下一堆废弃的设备给偶然发现此地的人。"}},faq={{q="那张字条是谁写的？",a="字条中并未提及作者的身份。作者只是解释说，为了防止研究成果落入不轨之徒手中，他们决定转入地下，留下了废弃的营地和装备。",al={"谁写的字条","字条作者","谁留下了信息"}},{q="什么样的工作被带到了地下？",a="作者工作的具体性质尚未揭晓。他们提到转入地下仅仅是为了保护他们的研究或成果，使其免受可能滥用这些成果的不明敌人的侵害。",al={"什么地下工作","为什么要带入地下","什么工作"}},{q="营地的主人去了哪里？",a="无论占据此地的人是谁，他们都匆忙打包并在有人抵达前不久溜走了。他们的去向不明，尽管字条暗示他们可能转移到了另一个隐蔽的藏身处。",al={"我是不是错过了他们","他们去了哪里","作者在哪里"}},{q="营地里留下了什么？",a="这位旅者留下了一只未能收好、散落在地上的睡袋、包着各种装备的沉重帆布，以及一个装有杂物的背包。",al={"留下了什么","营地的补给品","背包里有什么"}},{q="这是否通往另一个藏身处的线索？",a="这张字条碎片含义模糊，无法确定这究竟是道别的话语，还是指引作者下一个地下避难所的有意留下的线索。",al={"还有其他的藏身处吗","下一个营地","更多线索"}},{q="字条中提到的“不轨之徒”是谁？",a="字条中并未具体说明谁是“不轨之徒”。作者显然担心被追捕或失窃，因此在成果可能泄露前匆忙撤离。",al={"谁是不轨之徒","不轨之徒的含义","谁在追赶作者"}}},fp="22,180,17.289.0,20.253.1,24.175.0,37.140.0,37.143.0,37.175.0,42.106.0,48.127.0"}
P.entries["quest:79980"] = {n="Scramble",s="“攀爬”是一场隐藏的寻宝游戏，指引冒险者沿着陡峭的悬崖向下寻找坐标。在寻宝者便条的引导下，旅行者们挖掘出了一个埋藏的信使袋，里面装有生存物资和一张肮脏的羊皮纸。",h="“攀爬”是一场隐藏的寻宝游戏，指引冒险者沿着陡峭的悬崖向下寻找坐标。在寻宝者便条的引导下，旅行者们挖掘出了一个埋藏的信使袋，里面装有生存物资和一张肮脏的羊皮纸。",kw={"藏匿点","悬崖边","信使袋","羊皮纸","攀爬","补给品"},sec={{t="向北的小径",b="一则神秘的信息指引着任何足够聪明的旅行者找到一个隐藏的补给藏匿点。作者在留下精确方向的同时，还留下了非正式的鼓励：向正北方向沿着险峻的悬崖行进一百步，就能找到为了让旅行者继续前行而留下的物资。"},{t="挖掘信使袋",b="沿着指示走下陡峭的悬崖面，可以发现一个埋藏的信使袋。从泥土中挖出袋子后，里面装着实用的生存物资，还有一张塞在里面的肮脏羊皮纸，暗示这次简短的“攀爬”只是更大路径的一部分。"}},faq={{q="“攀爬”任务是什么？",a="“攀爬”是一个寻宝路径任务，引导冒险者前往一个隐藏的生存物资藏匿点。一张写好的便条指引找到它的人向北沿着险峻的悬崖行进，去回收埋藏的补给。",al={"攀爬任务","什么是攀爬","攀爬藏匿点"}},{q="隐藏的藏匿点在哪里？",a="根据说明，藏匿点埋在正北方向大约一百步处，位于陡峭的悬崖下方。需要小心落脚，以免从岩壁上跌落。",al={"藏匿点在哪里","如何找到藏匿点","藏匿点位置"}},{q="是谁留下了便条和藏匿点？",a="作者的确切身份不明。写信人留下了一些非正式的实用笔记，意在让探险者定位他们的应急物资，并确认藏匿点保持完好。",al={"谁写了攀爬便条","谁留下了藏匿点","攀爬任务作者"}},{q="埋藏的藏匿点里有什么？",a="挖出藏匿点后，会发现一个埋藏的信使袋，里面装有生存物资和一张夹在装备中的肮脏羊皮纸。",al={"攀爬任务奖励","攀爬藏匿点里有什么","袋中物品"}},{q="与物资一起发现的肮脏羊皮纸是什么？",a="肮脏的羊皮纸与补给品一起塞在埋藏的信使袋里，是在将袋子从地下拉出来时被发现的。",al={"攀爬肮脏羊皮纸","羊皮纸上写了什么","攀爬便条"}},{q="到达藏匿点有什么危险？",a="主要的危险在于从北面的悬崖向下进行陡峭的下降，任何失足都可能导致脚踝骨折或严重的坠落。",al={"攀爬危险","悬崖攀爬","攀爬悬崖边"}}},fp="8,163,19.246.0,28.196.1,27.156.0,34.127.0,32.143.0,32.89.0,52.133.0,48.99.0"}
P.entries["quest:8"] = {n="潜行者的交易",s="卡尔文·蒙泰古在丧钟镇请求的一件看似随意的差事，将一名旅行者送上了前往布瑞尔恐惧之末旅店的道路。这项差事涉及以普通信使的名义，向旅店老板瑞尼递送一封神秘且没有收件人地址的信件。",h="卡尔文·蒙泰古在丧钟镇请求的一件看似随意的差事，将一名旅行者送上了前往布瑞尔恐惧之末旅店的道路。这项差事涉及以普通信使的名义，向旅店老板瑞尼递送一封神秘且没有收件人地址的信件。",kw={"布瑞尔","卡尔文·蒙泰古","丧钟镇","恐惧之末","旅店老板瑞尼","笔迹潦草的信件","潜行者","提瑞斯法林地"},ang={["class:Rogue"]="卡尔文·蒙泰古的私人信使差事让人们得以一窥丧钟镇和布瑞尔周围进行的非正式交易。",["faction:Horde"]="这次投递直接通向布瑞尔，将刚到达的盟友引向提瑞斯法林地被遗忘者行政和休整的区域中心。",["race:Undead"]="对于刚复活的被遗忘者来说，这项差事标志着他们第一次离开丧钟镇墓地的安全范围，前往熙熙攘攘的布瑞尔中心。"},sec={{t="友好的信使",b="卡尔文·蒙泰古在丧钟镇那庄严肃穆的墓地和破败的礼拜堂间徘徊，表现得像个被天灾僵尸和爬行的蜘蛛折磨得精疲力竭的战士。他声称自己只是需要人手帮忙把一封信送到布瑞尔，并将一封未标记的信件托付给路过的冒险者。他轻松的态度和丰厚报酬的承诺，让这项任务看起来不过是件为了引导刚觉醒的被遗忘者前往该地区主要城镇而进行的无害之举。"},{t="恐惧之末旅店",b="道路向东延伸，穿过提瑞斯法林地那枯萎的树木，经过炉灰庄园，最终到达布瑞尔定居点。在当地旅店的柜台后，旅店老板瑞尼最初以一种令人不安的阳光态度迎接新人，对客人的舒适度关怀备至。然而，在收到蒙泰古的信件后，她的热情立刻土崩瓦解。她抛弃了伪装出来的亲切，佯称自己收到了来自慈母的消息，随后责骂信使多管闲事，并要求他们买点东西或者立刻离开。事后回到卡尔文那里又会出现另一个惊喜：他并没有和平地支付承诺的报酬，而是向信使发起了决斗。"}},faq={{q="卡尔文·蒙泰古是谁？",a="卡尔文·蒙泰古是丧钟镇的一名潜行者，他请求刚觉醒的旅行者帮他把一封信送到布瑞尔的旅店老板瑞尼手中。他将此描述为一个简单的恩惠，并承诺给予丰厚的回报。",al={"卡尔文·蒙泰古","谁发布潜行者的交易","任务发布者"}},{q="笔迹潦草的信件里写了什么？",a="这封信的具体内容并未被记录。卡尔文交给信使一封未标记的信件，要求送给布瑞尔的旅店老板瑞尼。",al={"笔迹潦草的信件内容","信里有什么","卡尔文的信"}},{q="为什么旅店老板瑞尼表现得如此奇怪？",a="瑞尼经营着布瑞尔的旅店，并坚称她的信件是私人的。将蒙泰古的信件带给她，就能揭晓她对这次投递的反应。",al={"旅店老板瑞尼的态度","为什么瑞尼在演戏","瑞尼母亲的借口"}},{q="卡尔文·蒙泰古真的会为这次投递支付报酬吗？",a="蒙泰古承诺会为投递支付高额报酬。当信件送达时，瑞尼会提供食物或水；事后请回到卡尔文那里，继续就他承诺的报酬进行交涉。",al={"卡尔文是不是骗我","我的钱在哪里","蒙泰古的奖励"}},{q="布瑞尔在哪里？",a="布瑞尔位于丧钟镇的东北方。旅行者沿着起始山谷的主要道路向东走，向右拐过炉灰庄园，穿过一座廊桥即可到达该定居点。",al={"如何前往布瑞尔","去布瑞尔的路","布瑞尔路线指引"}},{q="把信交给瑞尼之后会发生什么？",a="后续任务名为“潜行者的交易”。回到丧钟镇的卡尔文·蒙泰古那里，继续与他进行交易。",al={"下一个任务","潜行者的交易后续","交给瑞尼后做什么"}}},fx={df83fdd9={q="卡尔文·蒙泰古为什么要送出这封信？",a="卡尔文·蒙泰古声称，自己在丧钟镇附近对付过不少毫无理智的僵尸和蜘蛛，现在只需要有人替他跑一趟腿。他不愿亲自沿路走到布瑞尔，便提出付给你一大笔钱，让你把他封好的、笔迹潦草的信件直接送给旅店老板瑞尼。",al={"卡尔文·蒙泰古的动机","为什么要把信送给瑞尼","卡尔文为什么要我做这件事"}}},fp="14,136,18.299.0,23.469.1,23.175.0,38.112.0,40.147.0,51.194.0,23.161.0,46.100.1"}
P.entries["quest:80"] = {n="斯塔文的传说",s="调查斯塔文·密斯曼托的关键一步是将收集到的证据提交给夜色镇的当局。指挥官阿尔泰娅·埃伯洛克手中拿着一张染血的日记书页，指示调查员去找书记员达尔塔，以便彻底鉴定笔迹的真伪。",h="调查斯塔文·密斯曼托的关键一步是将收集到的证据提交给夜色镇的当局。指挥官阿尔泰娅·埃伯洛克手中拿着一张染血的日记书页，指示调查员去找书记员达尔塔，以便彻底鉴定笔迹的真伪。",kw={"阿尔泰娅·埃伯洛克","染血的日记书页","书记员达尔塔","夜色镇","暮色森林","斯塔文的传说","夜色守夜人","斯塔文·密斯曼托"},ang={["faction:Alliance"]="这次调查突显了像夜色镇这样的边境城镇尽管受到亡灵和暗影野兽的围困，却依然努力维持法律、秩序和民事记录。",["race:Human"]="对于南方王国的人类来说，这个任务触及了将暴风城贵族、暮色森林定居者和艾尔文森林散落的庄园联系在一起的各种悲剧。"},sec={{t="收网",b="随着在暮色森林及周边人类领地搜寻到的日记书页留下的线索，夜色守夜人终于掌握了似乎能证实那个难以捉摸的导师——斯塔文·密斯曼托罪行的确凿证据。指挥官阿尔泰娅·埃伯洛克对这个人抱有怀疑已经有一段时间了，但要进行正式宣判，就需要绝对的确定性。在能够毫无疑问地证明这些恐怖的文字确实出自斯塔文之手前，单单一页染血的日记还不足以定罪。"},{t="书记员的慧眼",b="为了弥合怀疑与确定性之间的差距，夜色守夜人求助于夜色镇的镇档案管理员，书记员达尔塔。由于多年来一直负责镇上的登记工作，达尔塔检查过无数的账簿和签名，这使他成为了笔迹鉴定方面的权威。将新发现的日记书页与镇档案中斯塔文过去的签名直接进行对比，提供了确认其堕落和罪行所需的最后且无可辩驳的证据。"}},faq={{q="为什么埃伯洛克指挥官需要达尔塔书记员的确认？",a="指挥官阿尔泰娅·埃伯洛克希望在采取最终行动之前，确保斯塔文的罪行得到毫无疑问的证实。书记员达尔塔负责管理夜色镇的镇登记册，并且在检查签名方面经验丰富，这使他有独特的资格来验证那页染血的日记是否与镇档案中斯塔文的笔迹相符。",al={"为什么要找达尔塔","为什么要核对笔迹","书记员达尔塔的作用"}},{q="这一步在“斯塔文的传说”故事线中处于什么位置？",a="这是这项漫长调查的第十一章。它发生在找回染血的日记书页之后，是夜色守夜人对斯塔文采取果断行动之前进行的最后证据核实。",al={"这是任务的哪一部分","任务链进度","斯塔文任务链顺序"}},{q="书记员达尔塔在夜色镇的什么位置？",a="书记员达尔塔可以在夜色镇的市政厅内找到，他负责为社区管理当地的记录和财产登记册。",al={"达尔塔的位置","书记员达尔塔在哪里","寻找达尔塔"}},{q="调查员带给夜色镇什么证据？",a="调查员携带了一页在持续搜寻斯塔文下落的过程中找回的染血的日记书页。书页上的文字描述了他阴暗的思想和经历，但需要与官方记录进行笔迹比对。",al={"证据是什么","这是哪一页","染血的日记书页背景"}},{q="书记员达尔塔确认那是斯塔文的笔迹吗？",a="是的。通过将染血的书页与镇登记册中的签名进行比对，达尔塔确认笔迹相符，这让埃伯洛克在采取最终行动前获得了她所需要的确定性。",al={"笔迹匹配吗","是斯塔文吗","是斯塔文写的吗"}},{q="为什么夜色守夜人对指控斯塔文如此谨慎？",a="即使在暮色森林这片饱受困扰、与世隔绝的土地上，夜色守夜人也在努力维持合法的秩序。指控一位前学者犯下骇人听闻的罪行需要具体的、可验证的证据，而不是仅仅依靠传闻或推测。",al={"为什么要证据","为什么不直接杀了斯塔文","埃伯洛克的怀疑"}}},fp="21,201,15.372.0,15.329.1,62.286.0,62.202.0,43.119.0,54.194.0,55.183.1,58.219.0"}
P.entries["quest:80001"] = {n="Rekindle",s="熄灭的火坑里备有干柴，随时可以点燃。你将侦察技能派上用场。",h="熄灭的火坑里备有干柴，随时可以点燃。你将侦察技能派上用场。",kw={"干柴","熄灭的火","火坑","rekindle","侦察技能"},sec={{t="火坑旁",b="木柴干燥，足以点燃。你在熄灭的火坑旁将侦察技能派上用场。"}},faq={{q="Rekindle 讲的是什么？",a="熄灭的火坑里备有干柴，随时可以点燃，而你将侦察技能派上用场。",al={"rekindle 任务","rekindle 火焰","火坑"}},{q="火坑出了什么问题？",a="火坑已经熄灭，不过木柴干燥，足以点燃。",al={"火坑问题","为何没有火","熄灭的火"}},{q="完成时的描述说了什么？",a="完成时的描述说，你将侦察技能派上用场。",al={"rekindle 结局","完成时会发生什么","侦察技能"}}},fp="8,96,15.107.0,23.98.0,32.75.0,29.54.0"}
P.entries["quest:804"] = {n="萨科斯",s="在为受伤的暗矛巨魔哈纳祖报仇，击杀了恐怖的蝎虫萨科斯之后，冒险者必须将他的困境传达回大兽穴。必须立刻通知高内克，这样救援才能及时抵达，在剧毒夺去这位侦察兵的性命之前将他救回。",h="在为受伤的暗矛巨魔哈纳祖报仇，击杀了恐怖的蝎虫萨科斯之后，冒险者必须将他的困境传达回大兽穴。必须立刻通知高内克，这样救援才能及时抵达，在剧毒夺去这位侦察兵的性命之前将他救回。",kw={"暗矛","杜隆塔尔","高内克","哈纳祖","萨科斯","蝎虫","大兽穴","试炼谷"},ang={["faction:Horde"]="新部落建立在严酷无情的土地上，强调共同生存；不抛弃任何一名同伴是学徒从迈出第一步起就被教导的基本原则。",["race:Orc"]="兽人文化重视个人的力量，但挺身而出捍卫一名失去行动能力的盟友的荣誉，这证明了一个真正战士的内心。",["race:Troll"]="暗矛部族与萨尔的兽人之间萌芽的联盟，正是通过诸如从缓慢的剧毒死亡中拯救哈纳祖这类兄弟情谊的行为而得以加强。"},sec={{t="侦察兵的困境",b="暗矛侦察兵哈纳祖被困在试炼谷的高耸峭壁上，他身中剧毒，无法独自走下险峻的山路。虽然他击败了将他打倒的恐怖蝎虫萨科斯并完成了复仇，但仅凭骄傲无法支撑一位中毒的战士穿越这片贫瘠的乱石之地。他被困在岩石上，只能寄希望于路过的学徒将消息带回训练营地。"},{t="大兽穴的荣誉",b="回到大兽穴向高内克复命即可完成试炼。高内克立刻意识到了萨科斯的威胁，并迅速组织人手营救哈纳祖。在部落指挥官眼中，暂时放下个人的训练去伸张正义并营救一名落难的陌生人，体现了真正的荣誉。这证明了学徒在真正踏入杜隆塔尔之前就已经具备了应有的价值。"}},faq={{q="哈纳祖是谁，他为什么会被困住？",a="哈纳祖是一位年轻的暗矛巨魔侦察兵，他在前往试炼谷高处时遭到恐怖蝎虫萨科斯的伏击并中毒。由于虚弱无法独自爬下山崖，他需要救援。",al={"哈纳祖","哈纳祖是谁","为什么巨魔受伤了"}},{q="高内克是谁？",a="高内克是一位驻扎在试炼谷大兽穴的兽人监工。他负责评估新兵、分配生存任务，并在学徒在峡谷中遭遇致命威胁时协调救援。",al={"高内克","高内克在哪里","大兽穴领导者"}},{q="萨科斯是什么？",a="萨科斯是一只臭名昭著的巨型蝎虫，栖息在试炼谷上方的岩石峭壁中。它的剧毒和凶猛使它成为年轻兽人和巨魔试炼中的一个传说级威胁。",al={"野兽萨科斯","萨科斯是什么样的怪物"}},{q="哈纳祖的伤势能痊愈吗？",a="高内克承诺在收到你的报告后会立即派遣救援前往哈纳祖所在的地方。至于这位侦察兵后来如何，文中并未提及。",al={"巨魔活下来了吗","哈纳祖还好吗","哈纳祖获救"}},{q="为什么高内克如此高度赞扬这一行为？",a="人们期望你能从试炼中存活下来，但将你自己的任务搁置一旁，为了一个陌生人的荣誉而战并确保他们能活下去，这才是新部落试图在战士身上培养的核心价值观。",al={"为什么高内克在意","高内克的荣誉演讲"}},{q="大兽穴在哪里？",a="大兽穴是位于杜隆塔尔西南部试炼谷中心地带的中央训练洞穴和集结地。",al={"大兽穴在哪里","杜隆塔尔大兽穴位置"}}},fp="7,210,16.336.0,16.328.0,39.166.0,14.182.0,16.184.0,33.121.1,43.179.0,25.117.0"}
P.entries["quest:805"] = {n="去森金村报到",s="“向森金村报告”标志着年轻的部落新兵离开了与世隔绝的试炼谷，去警告暗矛巨魔有关恶魔邪教活动的时刻。在祖雷萨的委托下，信使将火刃氏族的消息带给了加德林大师，并发现暗影魔法已经威胁到了附近的海岸。",h="“向森金村报告”标志着年轻的部落新兵离开了与世隔绝的试炼谷，去警告暗矛巨魔有关恶魔邪教活动的时刻。在祖雷萨的委托下，信使将火刃氏族的消息带给了加德林大师，并发现暗影魔法已经威胁到了附近的海岸。",kw={"火刃氏族","暗矛","杜隆塔尔","回音群岛","加德林大师","森金村","试炼谷","祖雷萨"},ang={["faction:Horde"]="这项任务展示了萨尔领导的部落各大创始种族之间至关重要的合作，他们通过交换情报来保护彼此年轻的定居点。",["race:Orc"]="对于年轻的兽人来说，离开试炼谷去帮助暗矛部族是考验荣誉和团结的一项早期试炼，也是对那些在无尽之海彼岸与萨尔并肩作战的盟友展现支持的契机。",["race:Troll"]="回到森金村，暗矛冒险者们将直面族人流离失所的现状，以及收复回音群岛的持续斗争。"},sec={{t="离开大兽穴",b="在证明了自己的战斗实力并从试炼谷内的火刃集会所夺回黑暗勋章后，新手们被认为已做好准备迎接更广阔的世界。祖雷萨意识到，这些神圣试炼场中的恶魔存在并非孤立的骚乱，而是杜隆塔尔蔓延开来的枯萎症的征兆。她引导年轻的冒险者们向东穿过峡谷出口，并向南前往海岸，以警告暗矛部族。"},{t="海岸之上的阴影",b="当旅行者抵达沿海定居点森金村时，他们将警告传达给了流亡中的暗矛部族领袖、年长的巫医加德林大师。虽然加德林证实火刃氏族本身并未袭击村庄的沙滩，但他透露黑暗魔法已在附近的回音群岛生根。这份报告揭示了年轻部落的立足点依然是多么脆弱：即使盟友们竞相保卫彼此，古老的部落背叛和邪能腐蚀也在同时打击着他们的侧翼。"}},faq={{q="祖雷萨为什么派人离开试炼谷？",a="在揭露了试炼谷内的恶魔活动后，祖雷萨担心火刃集会所对整个杜隆塔尔构成了有组织的威胁。她派遣久经考验的新兵走出山谷，去警告盟友的定居点，并查明邪教的影响范围有多广。",al={"为什么要离开山谷","为什么要前往森金","祖雷萨的任务"}},{q="加德林大师是谁？",a="加德林大师是一位年长的巫医，也是居住在森金村的暗矛巨魔的精神领袖。他担任沃金酋长的顾问，在处理笼罩着他们临时沿海避难所的威胁的同时，监督部落事务。",al={"加德林大师的背景","谁是加德林"}},{q="火刃氏族袭击过森金村吗？",a="没有，火刃氏族并未直接袭击过森金村。然而，加德林大师指出，类似的黑暗魔法和背叛已经在附近的回音群岛生根，这意味着巨魔们正面临着属于他们自己的迫在眉睫的危险。",al={"火刃氏族在森金村吗","森金村的邪教"}},{q="森金村在哪里？",a="森金村位于试炼谷主峡谷出口向东的方向，在路口处向南转，沿着杜隆塔尔的东南海岸即可到达。",al={"如何前往森金村","森金村的方向"}},{q="加德林大师提到了回音群岛的什么威胁？",a="加德林大师担心扎拉赞的黑暗背叛，这名巨魔巫医同僚利用阴险的妖术奴役了他的族人并夺取了回音群岛的控制权，迫使幸存的暗矛部族逃往大陆海岸。",al={"回音群岛的麻烦","回音群岛发生了什么"}},{q="向加德林大师报告后会发生什么？",a="在听取了你的报告并详细说明了巨魔们自己的困境后，加德林请求你协助应对威胁海岸线的危险，随后的命令会将你派往西北方向，去寻找剃刀岭的奥戈尼尔·魂痕。",al={"向森金报告后的下一个任务","加德林之后做什么"}}},fp="25,237,15.395.0,22.434.1,70.235.0,21.202.0,47.176.0,33.144.0,57.235.0,46.204.0"}
P.entries["quest:806"] = {n="黑暗风暴",s="“黑暗风暴”是剃刀岭的奥戈尼尔·魂痕委派的一项重要任务，旨在铲除一名正在腐化这片土地的邪恶术士。一个名叫费索·暗风的哥布林代表阴险的火刃氏族在雷霆山扎下了根。在他进一步扩散其邪教势力之前消灭他，对于保护杜隆塔尔免受恶魔复苏的威胁至关重要。",h="“黑暗风暴”是剃刀岭的奥戈尼尔·魂痕委派的一项重要任务，旨在铲除一名正在腐化这片土地的邪恶术士。一个名叫费索·暗风的哥布林代表阴险的火刃氏族在雷霆山扎下了根。在他进一步扩散其邪教势力之前消灭他，对于保护杜隆塔尔免受恶魔复...",kw={"火刃氏族","黑暗风暴","杜隆塔尔","费索·暗风","费索的爪子","奥戈尼尔·魂痕","剃刀岭","雷霆山"},ang={["class:Shaman"]="费索及其爪牙所施行的黑暗仪式扰乱了雷霆山的自然之灵，激怒了这里的野兽，迫切需要恢复元素平衡。",["class:Warlock"]="费索·暗风展示了对邪能盲目崇拜所带来的鲁莽危险，这使他成为了一个令部落严守纪律的施法者们无法容忍的污点和隐患。",["faction:Horde"]="确保杜隆塔尔的核心区域免受恶魔的颠覆，这能让初生的部落将防御力量集中于对外，而不是从内部瓦解。",["race:Orc"]="火刃氏族代表着兽人们每天都在努力克服的黑暗过去。消灭像费索这样的邪教潜入者，对于维护萨尔建立的自由国度至关重要。"},sec={{t="岭中的威胁",b="正当年轻的部落保卫者巡视杜隆塔尔边境时，内部的腐化正在他们的眼皮底下滋生。奥戈尼尔·魂痕在剃刀岭进行调查时发现，西北方的雷霆山已陷入黑暗魔法的掌控。那片峡谷里爬满了火刃氏族的邪教徒，他们给当地的野生生物和土地带来了毁灭与混乱。"},{t="费索·暗风",b="统领峡谷内邪教活动的正是费索·暗风，一个与火刃氏族结盟的投机主义哥布林术士。费索并非为了商业或财阀利益服务，而是直接运用邪能来推动该邪教的颠覆性议程。杀掉他并取回他的扭曲爪子，向奥戈尼尔证明该峡谷内邪教的直接领导层已被瓦解。"},{t="铲除邪教",b="火刃氏族代表着萨尔的新部落竭力摒弃的一切：恶魔奴役、鲁莽的腐化以及嗜血的疯狂。铲除费索不仅从杜隆塔尔的腹地清除了一名活跃的阴谋家，也预示着笼罩在兽人故乡上的阴影远比一些孤立的营地要深远得多。"}},faq={{q="谁是费索·暗风？",a="费索·暗风是一名代表火刃氏族行事的哥布林术士。他和他的邪教追随者躲藏在雷霆山，在峡谷中散布恶魔带来的混乱，直到奥戈尼尔·魂痕下令将他处决。",al={"谁是费索","费索·暗风背景故事","费索哥布林"}},{q="雷霆山位于何处？",a="雷霆山是一条崎岖的峡谷，位于杜隆塔尔西北部，剃刀岭以北，奥格瑞玛西南方。这里以充斥着带有闪电能量的野兽和火刃氏族邪教营地而闻名。",al={"雷霆山在哪里","雷霆山位置","如何找到雷霆山"}},{q="为什么火刃氏族会出现在杜隆塔尔？",a="火刃氏族试图破坏萨尔的部落，并重建恶魔对兽人的统治。他们在杜隆塔尔各处的隐秘峡谷、洞穴和山涧中秘密活动，试图从内部散布腐化。",al={"杜隆塔尔的火刃氏族","为什么邪教徒在杜隆塔尔","火刃氏族的目的"}},{q="为什么奥戈尼尔·魂痕特别需要费索的爪子？",a="奥戈尼尔需要确凿的证据来证明该术士已被终结。带回费索的爪子可以确认，雷霆山邪教团伙的首领已无法继续指挥行动。",al={"为什么需要费索的爪子","费索的爪子的含义","费索死亡证明"}},{q="击杀费索后会发生什么？",a="击败费索扫清了雷霆山的直接威胁，奥戈尼尔·魂痕会指引你去找萨满祭司玛戈兹，他了解更多关于火刃氏族腐化的信息，以铲除更多火刃氏族的阴谋。",al={"黑暗风暴之后的任务","黑暗风暴后续","黑暗风暴的下一个任务"}},{q="为什么哥布林会为火刃氏族效力？",a="虽然许多哥布林通过贸易财阀追求黄金，但也有一些哥布林被暗影魔法所带来的原始力量、影响力和黑暗技艺所诱惑。费索拥抱了邪能巫术，并将他那冷酷的狡诈直接贡献给了邪教徒。",al={"哥布林与火刃氏族","费索为何加入邪教","术士费索"}}},fp="11,179,21.246.0,16.291.0,20.284.1,24.204.0,31.169.0,36.193.0,57.166.0,35.182.1,46.167.0"}
P.entries["quest:808"] = {n="明希纳的颅骨",s="森金村的加德林大师一直被他已故兄弟明希纳绝望的哭喊声所困扰。明希纳在回音群岛被邪恶的巫医扎拉赞杀害并施以黑暗魔法，他的灵魂被禁锢在自己破碎的颅骨之中。想要解救这位倒下的巨魔，必须潜入扎拉赞的仪式场地，夺回这件圣物，并使他的灵魂从永恒的折磨中解脱出来。",h="森金村的加德林大师一直被他已故兄弟明希纳绝望的哭喊声所困扰。明希纳在回音群岛被邪恶的巫医扎拉赞杀害并施以黑暗魔法，他的灵魂被禁锢在自己破碎的颅骨之中。想要解救这位倒下的巨魔，必须潜入扎拉赞的仪式场地，夺回这件圣物，并使他...",kw={"能量之环","暗矛","回音群岛","加德林","明希纳","森金村","颅骨","巫毒","扎拉赞"},ang={["class:Priest"]="牧师理解已故灵魂的神圣性，也明白那种将倒下的兄弟禁锢在永恒安宁之外的死灵仪式的恐怖。",["class:Shaman"]="萨满崇敬祖先的灵魂；打破扎拉赞的圆环来释放一个被折磨的灵魂，能够恢复精神世界与现实世界之间的平衡。",["faction:Horde"]="协助加德林大师是对新部落与暗矛巨魔之间纽带的尊重，证明了盟友的悲痛是大家共同承担的。",["race:Troll"]="对于一名暗矛巨魔来说，取回明希纳的颅骨是对家庭和部落的神圣职责，这沉重打击了扎拉赞对祖先巫毒传统的扭曲。"},sec={{t="来自阴影的恳求",b="加德林大师是森金村暗矛巨魔部落的精神支柱之一，但他此刻正深受黑暗幻象的折磨。他的兄弟明希纳在疯狂的术士扎拉赞夺取回音群岛控制权时，成为了这场背叛的受害者。明希纳在那场冲突中丧生，但在巨魔的传统和巫毒秘术中，肉体的死亡并不意味着真正的安宁。明希纳受尽折磨的声音不断在加德林的梦境中响起，恳求着从这比死亡更糟糕的命运中获得救赎。"},{t="扎拉赞的能量之环",b="扎拉赞不仅仅是杀害了他的同胞，他还捕获了他们的灵魂，以此为自己的黑暗巫术提供力量。明希纳的灵魂被仪式性地禁锢在他自己的颅骨上，现在这颗颅骨正安放在回音群岛中最大的一座岛屿上的邪恶能量之环中。在被施了妖术的巨魔守卫下，浸泡在烛光仪式之中，这颗颅骨成为了那个叛徒扭曲巫术的焦点。只要它还留在那个圆环中，明希纳就将永远受制于扎拉赞的意志。"},{t="死亡中的自由",b="为了拯救明希纳，一位勇敢的勇士必须横渡森金村东侧的水域，抵达回音群岛的南端，闯入仪式圆环，并将颅骨从那位巫医的控制中解救出来。将遗骸带回给加德林大师可以切断黑暗的束缚，让明希纳感恩的灵魂短暂现身，鞠躬致敬，最终前往祖先的国度。"}},faq={{q="明希纳是谁？",a="明希纳是加德林大师的兄弟，加德林是居住在森金村的一位杰出的巫医兼长者。他在回音群岛的叛乱中被扎拉赞杀害，扎拉赞随后利用黑暗巫术亵渎了他的遗骸。",al={"明希纳身份","明希纳是谁","加德林的兄弟"}},{q="为什么明希纳的灵魂会被困在他的颅骨里？",a="扎拉赞利用黑暗巫毒和术士魔法来奴役被杀害的暗矛巨魔的灵魂。通过将明希纳的灵魂直接禁锢在他的颅骨上，并将其放置在一个仪式的能量之环中，扎拉赞剥夺了他前往来世的通道，并奴役了他的灵魂。",al={"为何禁锢颅骨","扎拉赞灵魂陷阱","明希纳灵魂"}},{q="能量之环在哪里？",a="这个仪式地点位于杜隆塔尔东南海岸外，回音群岛中最靠南、也是最大的一座岛屿山顶之上。那里有仪式蜡烛、跳舞的受控巨魔和展示的颅骨，非常容易辨认。",al={"颅骨在哪里","能量之环位置","明希纳颅骨位置"}},{q="当颅骨被带回森金村时会发生什么？",a="加德林大师收到颅骨后，死灵束缚将会破碎。明希纳的鬼魂将出现在他的兄弟和探险者面前，感激地鞠躬，然后消失，去与祖先们安息在一起。",al={"任务交还","明希纳发生了什么","明希纳会出现吗"}},{q="扎拉赞是谁？他为什么要这么做？",a="扎拉赞曾是暗矛巨魔部落里备受尊敬的巫医。由于对力量的渴望而陷入疯狂，他背叛了部落，使用妖术控制了族人的心智，并将剩余的暗矛难民驱赶到了杜隆塔尔的大陆上。",al={"谁是扎拉赞","为什么扎拉赞是邪恶的","扎拉赞背景故事"}},{q="为什么加德林自己不去取回颅骨？",a="加德林大师对于维持森金村的稳定至关重要。他既要指导年轻的暗矛领导层，又要为酋长沃金提供建议，还要积极应对扎拉赞在海岸沿线不断蔓延的妖术，因此他无法离开村庄，使其陷入无人保护的境地。",al={"为什么加德林不亲自去","加德林的职责"}}},fp="16,254,23.468.0,26.384.0,16.345.1,17.142.0,46.259.0,37.197.0,63.199.1,39.230.0,44.220.0"}
P.entries["quest:809"] = {n="雅克塞罗斯",s="雅克塞罗斯是一个早期部落任务，由术士尼尔鲁·火刃在奥格瑞玛深处的暗影裂口中发布。由于发现了残留的恶魔腐蚀证据，尼尔鲁派遣冒险者前往贫瘠之地，与他驻扎在边界附近的现场联络人会合。",h="雅克塞罗斯是一个早期部落任务，由术士尼尔鲁·火刃在奥格瑞玛深处的暗影裂口中发布。由于发现了残留的恶魔腐蚀证据，尼尔鲁派遣冒险者前往贫瘠之地，与他驻扎在边界附近的现场联络人会合。",kw={"雅克塞罗斯","贫瘠之地","火刃氏族","暗影裂口","恶魔之种","鬼雾峰","前沿哨所","尼尔鲁·火刃"},ang={["class:Warlock"]="熟悉尼尔鲁·火刃教导的术士可能会注意到，当他自己的助手质疑摧毁恶魔圣物的命令时，其中必有蹊跷。",["faction:Horde"]="确保前沿哨所的安全并清除鬼雾峰对于保护连接杜隆塔尔与贫瘠之地的早期贸易和交通路线至关重要。",["race:Orc"]="兽人们曾为摆脱燃烧军团的掌控而进行过艰苦的战斗，因此在他们的家门口出现火刃氏族和恶魔圣物的任何迹象都是一种迫在眉睫的威胁。"},sec={{t="暗影的踪迹",b="在杜隆塔尔发现一条火刃氏族的徽记项圈后，尼尔鲁·火刃声称要追捕威胁这个新定居部落的恶魔残党。尼尔鲁自诩为对抗邪能腐蚀的守门人，他将冒险者指引向贫瘠之地的干旱平原，并警告说一个邪恶的教派正在围绕一件名为恶魔之种的邪恶神器集结。"},{t="前沿哨所的联络人",b="为了协调针对该教派的打击行动，冒险者必须寻找雅克塞罗斯，他是尼尔鲁的助手，驻扎在杜隆塔尔与贫瘠之地交界处的前沿哨所附近。然而在抵达时，雅克塞罗斯对这项任务表现出了一种沉默的怀疑，他公开揣测他的主人为何会真心想要销毁这件神器，随后才提供了关于如何处理鬼雾峰上恶魔之种的指示。"}},faq={{q="谁发布了这个任务？",a="该任务由尼尔鲁·火刃发布，他是一名居住在奥格瑞玛下方暗影裂口阴暗洞穴中的术士。在你向他出示火刃氏族项圈后，他便会发布此任务。",al={"任务发布者","如何找到雅克塞罗斯","尼尔鲁·火刃任务"}},{q="雅克塞罗斯在哪里？",a="雅克塞罗斯位于前沿哨所外，就在贫瘠之地东部边界、杜隆塔尔桥梁过处的地方。",al={"雅克塞罗斯位置","雅克塞罗斯在哪里","寻找雅克塞罗斯"}},{q="什么是恶魔之种？",a="恶魔之种是一件拥有恶魔之力的污秽神器，被火刃氏族教派保存在贫瘠之地北部的险峻山峰鬼雾峰之上。",al={"恶魔之种背景","什么是恶魔之种"}},{q="为什么雅克塞罗斯觉得尼尔鲁的命令很奇怪？",a="雅克塞罗斯没有解释原因。他只是评论说尼尔鲁想要销毁恶魔之种令人感到奇怪，然后才同意告诉你如何移除它。",al={"为什么雅克塞罗斯感到惊讶","雅克塞罗斯的奇怪反应"}},{q="这个任务之后是什么任务？",a="与雅克塞罗斯交谈会直接引导至任务“恶魔之种”，该任务要求你登上鬼雾峰来清除这件具有腐蚀性的圣物。",al={"雅克塞罗斯后的下一个任务","雅克塞罗斯后续"}},{q="这个任务是火刃氏族剧情线的一部分吗？",a="是的。它起到了关键的连接作用，将杜隆塔尔发现的当地教派阴谋与贫瘠之地中更广泛、更有组织的教派活动联系了起来。",al={"火刃氏族任务线","奥格瑞玛教派任务"}}},fp="9,122,17.313.0,19.224.1,21.126.0,27.120.0,23.122.0,47.116.1,28.105.0,50.111.0"}
P.entries["quest:812"] = {n="救命如救火",s="暗矛巨魔林纳格被困在杜隆塔尔西北部崎岖的峭壁上，身中尾蝎毒素，生命垂危。在毒素发作之前的时间所剩无几，他只能寄希望于一名信使，请求其飞奔前往奥格瑞玛，从考格汉那里取回解药。",h="暗矛巨魔林纳格被困在杜隆塔尔西北部崎岖的峭壁上，身中尾蝎毒素，生命垂危。在毒素发作之前的时间所剩无几，他只能寄希望于一名信使，请求其飞奔前往奥格瑞玛，从考格汉那里取回解药。",kw={"解毒剂","暗影裂口","杜隆塔尔","考格汉","寻求治疗","奥格瑞玛","林纳格","蝎子","尾蝎"},ang={["faction:Horde"]="杜隆塔尔的岩石地形严酷无情，对于新抵达萨尔年轻王国的保卫者而言，这是一场永无止境的烈火试炼。",["race:Troll"]="林纳格对返回森金村的恐惧，凸显了暗矛部族那严苛的自尊心，在荒野生存中表现出的粗心大意会招致同族的严厉嘲讽。"},sec={{t="蝎子的毒刺",b="杜隆塔尔干旱的峡谷中到处都是尾蝎，这些侵略性极强的掠食者尾刺中带有迅速且令人虚弱的神经毒素。林纳格在边境附近与这些野兽战斗时一时大意，不幸中毒。深知毒素蔓延下他活不过一小时，身体也无法支撑他自己走到城门，他只能将生存的希望托付给每一个经过他营地的人。"},{t="阴影中的秘密",b="林纳格没有去寻找普通的药剂师或萨满，而是指引旅人深入奥格瑞玛地底的暗影裂口——大断崖。那里住着考格汉，一位对杜隆塔尔荒野剧毒了如指掌的神秘修行者。考格汉拥有配制强效解毒剂的知识，但他很少轻易向那些尚未证明自己实力的人提供帮助。"}},faq={{q="林纳格是谁？",a="林纳格是一名暗矛巨魔冒险者，在杜隆塔尔西北部的峭壁上奄奄一息。他被尾蝎刺伤，不仅担心即将到来的死亡，更害怕如果以如此狼狈的状态回到森金村，会招致族人的嘲笑。",al={"林纳格背景故事","林纳格是谁","巨魔林纳格"}},{q="为什么考格汉在大断崖？",a="考格汉住在大断崖，这是奥格瑞玛地下的阴暗洞穴，术士、潜行者和其他黑魔法修行者都在这里避开萨尔荣誉卫士的目光进行活动。他对毒药配方和残酷试炼的理解与大断崖的地下环境非常契合。",al={"考格汉在哪里","谁是考格汉","考格汉位置"}},{q="为什么林纳格不直接去森金村找萨满或治疗者？",a="林纳格承认是自己的自尊心在作祟。他担心以如此大意且身中剧毒的状态回到森金村只会遭到同族巨魔的嘲笑，因此更愿意从考格汉那里寻求隐秘的治疗。",al={"为什么不去森金村","林纳格为何避开森金村"}},{q="林纳格服下解药后会发生什么？",a="林纳格喝下解药后恢复了健康，但他的麻烦并未就此结束。以他对考格汉的了解，这位施药者会要求林纳格通过更艰苦的试炼——猎杀野猪并收集蝎尾——以此来证明自己，直到他完全获得这位修行者的认可。",al={"林纳格活下来了吗","林纳格的后续"}},{q="林纳格在哪里？",a="他位于杜隆塔尔西北部崎岖的峭壁上，靠近通往西方贫瘠之地的边境关口附近。",al={"林纳格位置","林纳格在哪里"}},{q="为什么这剂解药这么紧急？",a="尾蝎的毒素极其猛烈，受害者若不及时治疗，不到一小时内毒素就会蔓延至重要器官，导致死亡。",al={"为什么会有时间限制","林纳格中毒倒计时"}}},fp="15,218,17.239.0,22.216.0,14.215.0,39.260.0,67.197.0,48.222.1,26.121.0,47.113.0"}
P.entries["quest:813"] = {n="寻找解毒剂",s="“寻找解药”是一项为了在奥格瑞玛的考格汉而进行的紧急任务，目的是为中毒的猎人林纳格酿制解药。由于必须在毒液致命前完成，冒险者必须在城墙外从蝎尾毒虫身上收集蝎尾毒囊。这突显了杜隆塔尔野生动物的残酷本性以及野外生存准备的必要性。",h="“寻找解药”是一项为了在奥格瑞玛的考格汉而进行的紧急任务，目的是为中毒的猎人林纳格酿制解药。由于必须在毒液致命前完成，冒险者必须在城墙外从蝎尾毒虫身上收集蝎尾毒囊。这突显了杜隆塔尔野生动物的残酷本性以及野外生存准备的必要...",kw={"解药","杜隆塔尔","考格汉","奥格瑞玛","毒液","林纳格","蝎尾毒虫"},ang={["class:Hunter"]="考格汉对所有猎人提出了严厉的提醒：了解野兽的毒液并携带适当的药物与你的弓箭和追踪技能一样至关重要。",["faction:Horde"]="杜隆塔尔的部落照顾着自己的人民，确保边境上孤立的游侠和侦察兵可以依靠奥格瑞玛的堡垒获得援助。",["race:Orc"]="在杜隆塔尔的生存考验着新定居的兽人的耐力，这表明即使是经验丰富的侦察兵，如果粗心大意，也可能倒在当地的危险之下。"},sec={{t="与毒液赛跑",b="在杜隆塔尔各地狩猎时，一名名叫林纳格的暗矛巨魔犯了一个危险的错误：在没有携带解药的情况下与当地的蝎尾毒虫交战。他被蜇伤并迅速屈服于它们强效的毒素之下，被迫求援。这项任务落在了居住在奥格瑞玛的经验丰富的猎人考格汉身上，他必须在毒素发作前调配出修复药剂。"},{t="制作解药",b="制作解药需要采集痛苦的源头：潜伏在奥格瑞玛大门外的成熟蝎尾毒虫的毒囊。考格汉指出，现在不是责备林纳格缺乏准备的时候，因为每一刻都至关重要。一旦迅速取回毒囊并带回城里，考格汉就会合成药剂，以便能立刻送往垂死的猎人手中。"}},faq={{q="林纳格是谁？",a="林纳格是杜隆塔尔的一名暗矛巨魔猎人，他在追踪野兽时被当地的蝎尾毒虫严重蜇伤。由于在野外缺乏解药，他丧失了行动能力，只能依靠信使从奥格瑞玛取回药物，以免死于中毒。",al={"林纳格背景故事","谁中毒了","谁需要解药"}},{q="考格汉是谁？",a="考格汉是一位经验丰富的暗矛巨魔猎人，常驻于奥格瑞玛的暗影裂口。他深谙杜隆塔尔的野生动物，并拥有使用原始蝎尾毒虫毒囊酿制有效解毒剂所需的炼金知识。",al={"考格汉","考格汉是谁","考格汉 奥格瑞玛"}},{q="所需的毒囊来自哪里？",a="毒囊直接从在奥格瑞玛入口附近多岩石的干旱地面上游荡的蝎尾毒虫身上采集。",al={"蝎尾毒虫在哪里","毒囊位置","蝎尾毒虫毒囊"}},{q="为什么这个任务有时间限制？",a="紧迫性源于林纳格在野外恶化的健康状况。由于蝎尾毒虫的毒素极其猛烈且作用迅速，考格汉必须在猎人因全身中毒而死亡前收到原料并蒸馏出解药。",al={"为什么有计时","治愈的需求计时","限时任务"}},{q="考格汉在这次狩猎中强调了什么教训？",a="考格汉警告说，每一位猎人在与猎物交战前，都必须仔细研究它们的习性和致命危险。在没有做好充分准备或没有应对措施的情况下进入荒野，是一个很容易让战士付出生命代价的疏忽。",al={"考格汉的教训","狩猎教训","考格汉的建议"}},{q="这个任务如何与“治愈的需求”相衔接？",a="“治愈的需求”是引发紧急情况并启动计时的基础差事。“寻找解药”是中间步骤，玩家在此收集原始成分，供考格汉酿制成品药剂。",al={"治愈的需求关联","前置任务","它如何衔接"}}},fp="20,262,24.232.0,17.282.0,14.180.0,16.164.0,43.114.0,47.160.0,53.181.0,46.202.0"}
P.entries["quest:815"] = {n="恐龙蛋大餐",s="“打碎几个蛋”是一项跑腿任务，旨在协助一位忙得不可开交的厨师，他必须跟上无休止的餐点准备工作。搜集新鲜且易碎的食材而不将其弄碎，是维持厨房正常运转和烹饪进度按时进行的关键。",h="“打碎几个蛋”是一项跑腿任务，旨在协助一位忙得不可开交的厨师，他必须跟上无休止的餐点准备工作。搜集新鲜且易碎的食材而不将其弄碎，是维持厨房正常运转和烹饪进度按时进行的关键。",kw={"打碎几个蛋","早餐","厨师","烹饪","蛋","厨房","餐点"},ang={["profession:Cooking"]="每一位在职的厨师都知道让人们吃饱饭所带来的巨大压力。在任何厨房里，搜集易碎食材而不把它们打碎，这本身就是挑战的一半。"},sec={{t="无休止的餐点",b="供养一群人是一项精疲力竭、永无止境的工作。在早餐、午餐和晚餐之间，几乎没有时间离开炉灶，更不用说离开厨房去寻找原材料了。在“打碎几个蛋”中，一位焦头烂额的厨师求助于路过的冒险者，请他们赶在下一顿餐点服务延误之前找来新鲜的蛋。"},{t="厨师的感激",b="运输蛋需要一种蛮力无法替代的轻柔触碰。厨师可能会出言不逊，很少给予夸奖，但完好无损的食材本身就是最好的证明。一旦蛋被安全地送达且没有碎裂，厨师就会立刻打发采集者离开，直接回到火炉前继续工作。"}},faq={{q="“打碎几个蛋”是什么任务？",a="“打碎几个蛋”是一项烹饪任务，冒险者在此协助一位忙碌的厨师，他被准备餐点的持续需求压得喘不过气来。这项任务包括将蛋完好无损地送到，以确保烹饪进度不会滞后。",al={"打碎几个蛋任务","什么是打碎几个蛋","蛋任务"}},{q="“打碎几个蛋”里的厨师是谁？",a="这位厨师是杜隆塔尔剃刀岭的厨师托尔卡，他全天候都在准备餐点。虽然态度生硬且匆忙，但托尔卡依靠能干的帮手从回音群岛取回断尾龙虾的蛋，并确保在开饭前不把它们弄碎。",al={"谁发布打碎几个蛋","蛋任务厨师","谁在做饭"}},{q="厨师为什么需要蛋？",a="厨师需要它们进行持续的餐点准备，无论是早餐、午餐还是晚餐。供养人们是一项无休止的琐事，而新鲜的蛋是炉灶上迫切需要的厨房必需品。",al={"为什么需要蛋","蛋有什么用"}},{q="为什么厨师会评论说不要笨手笨脚？",a="蛋很脆弱，在运输过程中很容易损坏。厨师明确表示看重那些不笨手笨脚的人，因为蛋壳碎裂和蛋黄流失会毁掉餐点服务所需的食材。",al={"为什么拿蛋要小心","不要打破蛋","为什么不要笨手笨脚"}},{q="任务标题“打碎几个蛋”是指什么？",a="这个名字引用了一句常见的谚语：不打碎几个蛋就做不成煎蛋卷。这非常符合这项为繁忙的餐点服务收集易碎厨房食材的任务。",al={"打碎几个蛋含义","短语含义","为什么叫打碎几个蛋"}},{q="为什么厨师这么不耐烦？",a="厨师忙于应付早餐、午餐和晚餐的连轴转，根本没有时间停歇。还有这么多烹饪工作要做，厨师对闲聊毫无耐心，只想赶快回到炉灶前。",al={"厨师态度","为什么厨师很粗鲁","脾气暴躁的厨师"}}},fp="16,147,13.350.0,18.256.0,35.121.0,36.209.0,28.139.0,46.105.0,46.139.0,29.163.0"}
P.entries["quest:816"] = {n="丢失的孩子",s="“失踪但未被遗忘”是一个由米莎·托克伦发布的忧伤任务，她的家园位于剃刀岭西北方。为了寻求一个了结，她恳求旅者在危机四伏的怒水河岸搜寻她那倔强的儿子克鲁恩的下落。",h="“失踪但未被遗忘”是一个由米莎·托克伦发布的忧伤任务，她的家园位于剃刀岭西北方。为了寻求一个了结，她恳求旅者在危机四伏的怒水河岸搜寻她那倔强的儿子克鲁恩的下落。",kw={"护身符","鳄鱼","恐鳄","克鲁恩","米沙","剃刀岭","怒水河","托克伦"},ang={["class:Hunter"]="对于猎人来说，克鲁恩是一个警示故事，讲述了一名未能评估猎物凶猛程度的追踪者最终成为了它们的盘中餐。",["faction:Horde"]="杜隆塔尔早期的生活艰苦而严酷，平凡的家庭必须在无情的荒野和在其边界徘徊的致命掠食者之间挣扎求生。",["race:Orc"]="克鲁恩的命运是一个悲剧性的提醒：虽然自尊和尚武荣耀是兽人文化的核心，但缺乏对危险野兽的敬畏的鲁莽傲慢只会导致毫无英雄气概的死亡。"},sec={{t="母亲的恐惧",b="在剃刀岭西北方，隐匿于杜隆塔尔干旱的红色荒原之中，坐落着简朴的托克伦农场。米莎·托克伦住在这里，这是一位被悲伤和焦虑所麻痹的兽人母亲。几天前，她的儿子克鲁恩声称他要前往西边靠近贫瘠之地边界的怒水河，去猎杀河中凶猛的鳄鱼。尽管她警告过那些致命的野兽，但克鲁恩倔强的自尊心驱使他冲了出去，想要证明自己的勇气。从那以后，他就再也没有出现过。"},{t="残酷的确认",b="米莎请求路过的探险者仔细搜寻怒水河岸，寻找任何关于克鲁恩命运的线索，甚至建议他们去搜查那些鳄鱼的肚子。悲剧的是，她最坏的预感成真了。在水边屠宰凶恶的巨齿鳄鱼时，可以发现克鲁恩被吞下的护身符。将这件遗物带回给米莎虽然熄灭了她儿子幸存的最后希望，但终于让这位悲痛的母亲得到了她开始哀悼所需的结果。"}},faq={{q="谁是米莎·托克伦？",a="米莎·托克伦是一位兽人农场母亲，居住在杜隆塔尔剃刀岭西北方的一处偏僻家园。她饱受悲伤和忧虑的折磨，请求流浪者们搜寻她失踪的儿子克鲁恩的下落。",al={"米莎·托克伦","谁发布失踪但未被遗忘任务","克鲁恩的母亲"}},{q="克鲁恩是谁？",a="克鲁恩是米莎·托克伦那倔强的儿子。为了证明自己的力量，他无视了母亲的警告，离开家去怒水河附近猎杀危险的鳄鱼，并在那里遭遇了不测。",al={"谁是克鲁恩","克鲁恩发生了什么","米莎的儿子"}},{q="克鲁恩是在哪里失踪的？",a="克鲁恩向西穿过杜隆塔尔，前往贫瘠之地的边界，在怒水河岸进行狩猎时失踪的。",al={"克鲁恩在哪里","去哪里寻找克鲁恩","克鲁恩的位置"}},{q="你如何向米莎证明克鲁恩的命运？",a="你在徘徊于怒水河水域的恐齿鳄鱼遗骸中找到了克鲁恩被吞下的护身符。将这件找回的传家宝带回给米莎就确认了他的死亡。",al={"克鲁恩的护身符","克鲁恩命运的线索","鳄鱼的肚子"}},{q="米莎会给予什么奖励？",a="米莎把她原本准备给克鲁恩庆祝狩猎凯旋的礼物送给了你。在得知他的死讯后，她无法忍受再看这件东西，于是把它转交给了带给她结果的探险者。",al={"失踪但未被遗忘奖励","米莎的礼物"}},{q="克鲁恩当初为什么要离开？",a="克鲁恩的离去源于他倔强的自尊心和想要证明自己狩猎本领的渴望。当他的母亲警告他这些鳄鱼太过凶恶危险时，他大发雷霆，执意冲出去进行狩猎。",al={"克鲁恩为什么要打猎","克鲁恩的自尊"}}},fp="22,156,16.286.0,19.323.1,22.177.0,13.150.1,26.104.0,38.141.1,28.201.1,38.172.0"}
P.entries["quest:817"] = {n="生活所需的虎皮",s="“实用的猎物”是由森金村的制皮师维尔林·长牙发布的一项狩猎任务。面对不断增长的人口和日渐枯竭的库存，暗矛巨魔必须从邻近的回音群岛采集耐用的虎皮，以制作必要的住所、衣物和装备。",h="“实用的猎物”是由森金村的制皮师维尔林·长牙发布的一项狩猎任务。面对不断增长的人口和日渐枯竭的库存，暗矛巨魔必须从邻近的回音群岛采集耐用的虎皮，以制作必要的住所、衣物和装备。",kw={"暗矛","杜隆塔尔猛虎","回音群岛","狩猎","制皮","实用的猎物","森金村","虎皮","维尔林·长牙"},ang={["class:Hunter"]="维尔林讲述的关于在出击前坚持静默追踪一整天的故事，正是暗矛巨魔教导所有年轻猎手耐心与精准这些核心美德的直接体现。",["faction:Horde"]="支持这处暗矛巨魔的新生飞地，并提供必要的贸易物资，有助于稳固部落在无尽之海沿岸的南方侧翼。",["race:Troll"]="对于流亡的暗矛巨魔来说，前往回音群岛狩猎是一种苦涩的提醒，让他们想起失去的家园，在那里，为了供养族人，他们必须踏上被扎拉赞窃取的土地。"},sec={{t="生存之道",b="杜隆塔尔干旱海岸上的生活十分艰苦，流亡到森金村的暗矛巨魔必须充分利用每一份资源。虎皮是现有的用途最广泛的材料之一，是缝制帐篷、厚毯子和加固护甲的必需品。随着定居点里难民和归来斥候人数的增加，储备物资已经捉襟见肘，迫使像维尔林·长牙这样的工匠不得不委托进行新的狩猎。"},{t="平衡与狩猎",b="暗矛巨魔与他们领地内的掠食者保持着一种审慎的关系。巨魔通常不会过度狩猎杜隆塔尔本土的猛虎，而是任由这些徘徊者自由繁衍，只在部落物资需要补充时才会进行捕杀。冒险渡水前往回音群岛去跟踪这些掠食者，既是出于实际需要，也是对耐心、纪律和野外生存技巧的一种传统考验。"}},faq={{q="谁是维尔林·长牙？",a="维尔林·长牙是一位在森金村工作的暗矛巨魔工匠，专门处理兽皮和皮革。他负责引导猎手采集必要的毛皮，以保障部落的衣物、住所和装备供应。",al={"维尔林·长牙","谁发布了实用的猎物"}},{q="为什么森金村需要虎皮？",a="森金村不断增长的人口已经让现有的储备不堪重负。虎皮可以提供耐用的材料，制作保暖的毯子、结实的帐篷以及皮革护甲，以保护村民免受恶劣环境的侵袭。",al={"为什么需要虎皮","实用的猎物目标","毛皮的用途"}},{q="杜隆塔尔的猛虎在哪里可以找到？",a="这些猛虎在回音群岛的荒野中徘徊，该群岛位于杜隆塔尔东南部海岸外。",al={"老虎在哪里","老虎位置","回音群岛的老虎"}},{q="为什么巨魔不捕杀附近所有的老虎？",a="维尔林解释说，暗矛巨魔特意在自身需求与当地生态之间保持平衡。他们让掠食者繁衍壮大以保持种群的可持续性，只在村庄的物资需求超过储备时才会介入进行捕杀。",al={"为什么要让老虎繁衍","捕杀"}},{q="狩猎老虎对暗矛巨魔的文化重要吗？",a="是的。跟踪老虎被视为一种考验耐心和狡黠的仪式。维尔林曾深情地讲述过他在回音群岛的枝叶间一动不动地等待了近一天时间，才最终完成了他第一次重大狩猎胜利的故事。",al={"狩虎传统","第一次狩虎"}},{q="如果回音群岛被扎拉赞控制，为什么猎手们必须前往那里？",a="虽然叛变的巫医扎拉赞和他被施了巫术的爪牙占据了群岛的大部分地区，但岛上的野生猛兽依然繁多。在群岛外围海岸进行搜寻和狩猎，对暗矛巨魔来说依然是一项必要的冒险。",al={"回音群岛的老虎","为什么去回音群岛"}}},fp="14,137,20.267.0,20.236.0,20.144.0,41.131.0,35.79.0,48.138.0,51.171.0,65.182.0"}
P.entries["quest:818"] = {n="沃纳尔大师",s="森金村的沃纳尔大师通过索要试剂来测试初出茅庐的冒险者，以弥补他日益衰退的视力。他会派遣未来的学生前往杜隆塔尔沿岸收集龙虾人的眼睛和甲壳虫的粘液。虽然他对收徒弟的想法嗤之以鼻，但这项任务实际上是对耐心和决心的刻意考验。",h="森金村的沃纳尔大师通过索要试剂来测试初出茅庐的冒险者，以弥补他日益衰退的视力。他会派遣未来的学生前往杜隆塔尔沿岸收集龙虾人的眼睛和甲壳虫的粘液。虽然他对收徒弟的想法嗤之以鼻，但这项任务实际上是对耐心和决心的刻意考验。",kw={"炼金术","甲壳虫粘液","暗矛海滩","杜隆塔尔","完好的龙虾人眼睛","龙虾人","沃纳尔大师","森金村"},ang={["faction:Horde"]="杜隆塔尔海岸对初出茅庐的部落来说依然危机四伏；清理具有攻击性的龙虾人和冲浪甲壳虫可以保障森金村周围渔场的安全。",["race:Orc"]="沃纳尔公开怀疑兽人是否具备炼金术所需的安静纪律，这使得这项任务成为了证明部落团结可以延伸至学术耐心的机会。",["race:Troll"]="对于在森金村重建的暗矛部族来说，向沃纳尔大师这样的长者证明自己，对于传承部落的神秘和炼金传统至关重要。"},sec={{t="大师衰退的视力",b="沃纳尔大师坐在森金村里，背负着岁月的沉重和日益模糊的视力。曾经信手拈来的原始魔法，如今他不得不更多地依赖炼金术来强化感知并编织法术。尽管身体状况每况愈下，这位固执的巨魔却拒绝收徒，声称暗矛部族和杜隆塔尔的兽人中还没出现过有资格接受他教导的人。"},{t="考验未受证明者",b="沃纳尔并不进行直接的教导，而是要求从严酷的海岸线获取原材料：完好的龙虾人眼睛和甲壳虫粘液瓶。从披甲且善于夹击的龙虾人身上获取未受损的眼睛需要精准的打击，而收集足够的粘液则是对冒险者是否愿意忍受枯燥杂务的考验。在沃纳尔看来，狩猎这些沿海野兽与其说是为了试剂，不如说是为了剔除那些缺乏专注力的人。"},{t="意志的衡量",b="对于沃纳尔大师来说，时间和耐心是衡量强度的终极标准。他预料鲁莽的年轻人会因挫折而放弃，或者彻底抛弃这项苦差事。带着纯净的原料回到森金村，不仅证明了在回音群岛海峡危险礁石区的生存技能，也证明了掌握炼金术微妙艺术所必需的纪律。"}},faq={{q="沃纳尔大师是谁？",a="沃纳尔大师是一位居住在森金村的老年巨魔炼金术士和施法者。随着年龄的增长，他的视力正在衰退，这迫使他不得不转而依靠炼金溶剂和药剂来施展曾经轻而易举的魔法。",al={"沃纳尔大师","沃纳尔是谁","沃纳尔背景故事"}},{q="为什么沃纳尔需要龙虾人的眼睛和甲壳虫粘液？",a="沃纳尔依靠炼金合剂来辅助他的魔法，并弥补他衰退的视力。粘液和完好的龙虾人眼睛既是他的药剂试剂，也充当了对他未来学徒的入门测试。",al={"为什么需要甲壳虫粘液","为什么需要龙虾人眼睛","沃纳尔制造什么"}},{q="为什么沃纳尔如此不愿收徒？",a="沃纳尔有着极高的标准，对傲慢毫无容忍度。他认为没有哪个巨魔或兽人展现出了向他学习所需的真正奉献精神和耐心，他眼中的大多数求学者都过于自负且容易气馁。",al={"沃纳尔学徒","为什么不收学徒","沃纳尔在找学生吗"}},{q="这些生物在森金村附近哪里可以找到？",a="甲壳虫和龙虾人在暗矛海滩沿岸的浅滩游荡，并栖息在离岸将大陆与回音群岛隔开的水道中。",al={"龙虾人在哪里","甲壳虫在哪里","暗矛海滩野兽"}},{q="为什么龙虾人的眼睛需要完好无损？",a="用于强化感知的炼金药剂需要未受损的感觉器官。战斗中的蛮力打击有压碎龙虾人脆弱眼睛的风险，因此需要狩猎者具备精准度和克制力。",al={"完好的眼睛","完好的龙虾人眼睛","为什么需要完好的眼睛"}},{q="沃纳尔试图传授什么课程？",a="沃纳尔认为耐心是品格的真正试金石。通过布置在岸边重复且肮脏的采集任务，他旨在观察新手是会屈服于软弱和急躁，还是能保持炼金术士那种冷静的专注。",al={"沃纳尔的教导","任务的意义","耐心测试"}}},fp="16,194,23.343.0,20.348.0,17.315.0,21.196.0,52.200.0,50.212.0,55.127.0,42.180.0,38.161.0"}
P.entries["quest:819"] = {n="老陈的空酒桶",s="在贫瘠之地的荒野中，遗落着一只刻有陈·风暴烈酒名字的空酒桶。找到它将开启一段旅程，追溯这位著名的游历酿酒师往日的功绩，他曾为杜隆塔尔的建立贡献了自己的战斗技艺。",h="在贫瘠之地的荒野中，遗落着一只刻有陈·风暴烈酒名字的空酒桶。找到它将开启一段旅程，追溯这位著名的游历酿酒师往日的功绩，他曾为杜隆塔尔的建立贡献了自己的战斗技艺。",kw={"贫瘠之地","酿酒","酿酒师德罗恩","陈·风暴烈酒","空酒桶","熊猫人","棘齿城","雷克萨"},ang={["faction:Horde"]="陈·风暴烈酒被铭记为一位受人尊敬的盟友，他曾与雷克萨和洛克汗并肩作战，建立杜隆塔尔，并在部落最初的日子里保卫了它。",["profession:Cooking"]="这只酒桶代表了一位技艺精湛的酿酒师的传承，他那传奇般的品味和对稀有原料的追求激励了整个卡利姆多的工匠。"},sec={{t="一件游历者的遗物",b="在贫瘠之地那片干旱广袤的土地上，旅人们偶尔会发现一只被遗弃的木桶。不同于剃刀鬃毛野猪人或科卡尔半人马留下的常见货色，这只木桶制作精良，上面还刻有一块独特的铭牌：“陈·风暴烈酒——愿你的灵魂得到升华，也愿你永远兴致高昂。”在卡利姆多的烈日炙烤下，这真是一件不同寻常的遗物，促使任何好奇心旺盛的人去寻找一位精通酿酒之道的人，以了解它为何会出现在这里。"},{t="杜隆塔尔奠基的回响",b="将这只木桶带给棘齿城的酿酒师德罗恩，就能揭开它的起源。德罗恩一眼就认出了这精湛的工艺：它属于陈·风暴烈酒，那位在萨尔的部落确保杜隆塔尔安全的关键战役中与雷克萨并肩作战的传奇熊猫人游历者。尽管陈行走在卡利姆多红土地上的日子已过去多年，但他那传奇的酿酒配方和游历精神在艾泽拉斯的资深酿酒师心中依然记忆犹新。"}},faq={{q="什么是陈的空酒桶？",a="它是在贫瘠之地发现的一只废弃酿酒桶。上面刻有题词，将其献给游历的熊猫人酿酒师，陈·风暴烈酒。",al={"空酒桶","陈的酒桶","这个木桶是什么"}},{q="陈·风暴烈酒是谁？",a="陈·风暴烈酒是一位行踪不定的熊猫人酿酒师，他曾广泛游历卡利姆多。他最出名的事迹是在杜隆塔尔的防御和早期建设过程中协助半食人魔兽王雷克萨。",al={"谁是陈","陈的背景故事","熊猫人酿酒师"}},{q="我应该把这只酒桶交给谁？",a="这只酒桶可以交给酿酒师德罗恩，他是一位驻扎在棘齿城附近路边的兽人酿酒师，认得陈的标记，也知道如何重现他的配方。",al={"酒桶交给谁","谁想要陈的酒桶","酒桶交付"}},{q="为什么陈的酒桶会丢在贫瘠之地？",a="多年前，陈曾游历卡利姆多，为他的佳酿寻找奇异的原料，特别是在他帮助新兴的部落保卫新家园、抵御普罗德摩尔上将的军队时。",al={"为什么酒桶在贫瘠之地","酒桶是怎么到这里的"}},{q="陈·风暴烈酒会亲自出现吗？",a="不。陈已经离开了该地区，很久没有在卡利姆多露面了。留下的只有他旧时的木桶、配方，以及像德罗恩和雷克萨这样的盟友对他的美好回忆。",al={"我能找到陈吗","陈·风暴烈酒在哪里","陈在经典旧世里吗"}},{q="酿酒师德罗恩会用这只酒桶做什么？",a="德罗恩看到这件遗物非常兴奋，并借此机会向冒险的游历者发起挑战，收集当地野兽的原料，以便他能重现陈那烈性十足的传奇佳酿。",al={"德罗恩任务线","酒桶后续"}}},fp="16,124,17.383.0,28.343.0,25.129.0,23.172.0,29.153.0,43.172.0,38.167.0,43.163.0"}
P.entries["quest:81924"] = {n="Wisdom of the Guardians",s="在菲拉斯破碎的遗迹间，Tyrisius正努力寻回古老的Kaldorei教诲，以免它们就此失传。尽管古老的石碑已然破碎，那份失落智慧的精神精髓仍留存于遥远的神殿之中。",h="在菲拉斯破碎的遗迹间，Tyrisius正努力寻回古老的Kaldorei教诲，以免它们就此失传。尽管古老的石碑已然破碎，那份失落智慧的精神精髓仍留存于遥远的神殿之中。",kw={"艾萨拉","菲拉斯","守护者之灵","辛特兰","kaldorei","圣殿","tyrisius","wisdom of the guardians"},ang={["race:NightElf"]="Kaldorei的古老传说并未留存于石碑之上，而是存续在荒野圣殿中不灭的灵魂里。"},sec={{t="古老智慧的回响",b="Tyrisius警告说，菲拉斯石碑上的Kaldorei知识记载早已消失。石碑虽会风化，古代暗夜精灵的精神传承却仍留存于卡利姆多和东部王国的古老圣地。\n\n若要寻回那些被认为早已遗忘的知识，你必须前往散布在菲拉斯、艾萨拉和辛特兰各处的圣殿。Tyrisius请你前去拜见守望这些地方的守护者之灵，证明自己的价值，并在古老教诲永远消逝之前将其领受。"}},faq={{q="Tyrisius是谁？",a="Tyrisius看守着菲拉斯的古老Kaldorei遗迹，并指引寻求者找到留存至今的古老知识。",al={"tyrisius是谁","tyrisius在哪里"}},{q="守护者之灵在哪里？",a="守护者之灵守望着菲拉斯、艾萨拉和辛特兰的圣殿。",al={"灵魂在哪里","守护者之灵的位置","要去哪些区域"}},{q="为何必须寻找守护者之灵？",a="Tyrisius希望通过活生生的记忆保存古老的Kaldorei智慧，以免它永远从世间消逝。",al={"为何前往圣殿","目标是什么"}},{q="如何找到守护者之灵？",a="每个守护者之灵都栖居在古老土地上的一座圣殿中。",al={"如何辨认灵魂","寻找圣殿"}},{q="Tyrisius看守着哪些遗迹？",a="Tyrisius身处坍塌的Kaldorei遗迹之间，古代精灵知识的实体记载早已在此化为尘土。",al={"这些是什么遗迹","菲拉斯遗迹"}},{q="与灵魂交谈后该回到哪里？",a="证明自己配得上每个灵魂的认可后，Tyrisius会在菲拉斯等你回来。",al={"圣殿之后去哪里","该回去找谁"}}},fp="23,221,24.533.0,16.110.0,40.81.0,40.112.0,37.70.0,36.117.0,52.85.0"}
P.entries["quest:8193"] = {n="Master Angler",s="每逢星期日，都会举行钓鱼大赛，选出最出色的钓手。率先带来荆棘谷海岸鱼群中的Tastyfish，前五十名可获Master Angler称号。",h="每逢星期日，都会举行钓鱼大赛，选出最出色的钓手。率先带来荆棘谷海岸鱼群中的Tastyfish，前五十名可获Master Angler称号。",kw={"钓鱼大赛","钓鱼","鱼群","master angler","荆棘谷","星期日","tastyfish"},sec={{t="周日大赛",b="大赛每逢星期日举行。率先将Tastyfish交给组织者的前五十名钓手，可获得Master Angler称号。Tastyfish来自荆棘谷沿岸的鱼群，而且很快就会变质。"},{t="另一种报酬",b="如果你来晚了，没能排进前五十名，组织者的学徒仍会收购你的Tastyfish。这些鱼无法保存到下个星期日。"}},faq={{q="钓鱼大赛什么时候举行？",a="大赛每逢星期日举行。",al={"master angler 日期","钓鱼大赛是哪天"}},{q="在哪里能找到Tastyfish？",a="荆棘谷沿岸的鱼群中可以钓到Tastyfish。",al={"tastyfish 位置","哪里有tastyfish"}},{q="怎样才能成为Master Angler？",a="在前五十名之内，将Tastyfish交给大赛组织者。",al={"master angler 条件","赢得钓鱼大赛"}},{q="如果我来晚了怎么办？",a="如果你来晚了，没能排进前五十名，组织者的学徒会收购你的Tastyfish。",al={"错过大赛","钓鱼太慢"}},{q="我能把Tastyfish留到下周吗？",a="不能。Tastyfish很快就会变质，无法保存到下个星期日。",al={"tastyfish 会变质吗","鱼能留到星期日吗"}}},fp="13,169,18.231.0,14.157.0,28.37.0,26.62.0,32.70.0,26.104.0,35.73.0"}
P.entries["quest:81947"] = {n="Sanguine Sorcery",s="图书管理员正在为图书馆搜寻魔法典籍。你的贡献将丰富馆藏，增进知识。",h="图书管理员正在为图书馆搜寻魔法典籍。你的贡献将丰富馆藏，增进知识。",kw={"馆藏","知识","图书馆","魔法典籍","sanguine sorcery"},sec={{t="不断扩大的馆藏",b="图书管理员请你为书架带来些新藏品。你的贡献有助于拓展图书馆的知识。"}},faq={{q="图书管理员想要什么？",a="图书管理员请你带些东西来充实馆藏。",al={"他们想要什么","图书馆请求","sanguine sorcery"}},{q="这项请求来自哪里？",a="这项任务由暴风城的图书管理员 Garion Wendell 发布；如果你属于部落，则由幽暗城的 Owen Thadd 发布。",al={"图书管理员在哪里","铁炉堡图书馆","图书馆位置"}},{q="为什么要把魔法典籍带到图书馆？",a="图书管理员说，魔法典籍或许能让图书馆受益，并拓展其知识。",al={"为什么要魔法书","用途是什么","图书馆馆藏"}}},fp="16,104,20.123.0,29.67.0,27.106.0,39.82.0"}
P.entries["quest:81949"] = {n="《海潮贤者的传说》",s="一本鲜为人知的典籍被送到了暴风城或幽暗城的图书管理员手中。那里的学者乐于将它收入馆藏，借此拓展奥术知识的收藏。",h="一本鲜为人知的典籍被送到了暴风城或幽暗城的图书管理员手中。那里的学者乐于将它收入馆藏，借此拓展奥术知识的收藏。",kw={"馆藏","legends of the tidesages","图书馆","魔法典籍","暴风城","tidesages","典籍","幽暗城"},sec={{t="搜集知识",b="暴风城和幽暗城的图书管理员希望加深对奥术与历史典籍的了解。每一本从世界各地寻回的书卷，都保存着可能就此湮没的知识。"}},faq={{q="《Legends of the Tidesages》是什么？",a="这是一本魔法典籍，送来扩充暴风城Garion Wendell或幽暗城Owen Thadd管理的图书馆馆藏。",al={"legends of the tidesages是什么","这本书是什么","tidesages书籍"}},{q="谁想要这本书？",a="图书管理员会收下这本书，保存其中的知识并将其收入馆藏：联盟的书交给暴风城的Garion Wendell，部落的书交给幽暗城的Owen Thadd。",al={"谁想要legends of the tidesages","legends of the tidesages交到哪里","谁收这本书"}},{q="还能把更多书带到图书馆吗？",a="学者们希望你把寻回的其他魔法书卷也带给他们，或许这些书卷能派上用场。",al={"legends of the tidesages之后会怎样","图书馆 更多书籍","可以带来更多书吗"}}},fp="24,183,19.210.0,33.120.0,19.180.0,41.105.0"}
P.entries["quest:81952"] = {n="Everyday Etiquette",s="一位图书馆管理员正在寻找魔法典籍，充实馆藏。你的贡献能帮助拓展图书馆的知识。",h="一位图书馆管理员正在寻找魔法典籍，充实馆藏。你的贡献能帮助拓展图书馆的知识。",kw={"馆藏","日常礼仪","知识","图书馆","魔法典籍"},sec={{t="不断扩充的馆藏",b="你找到的任何魔法典籍，都可能被收入图书馆的书架。你的努力能帮助图书馆增长知识。"}},faq={{q="图书馆管理员想要什么？",a="管理员正在寻找可能对图书馆有益的魔法典籍。",al={"图书馆书籍","魔法典籍","需要带什么"}},{q="事情发生在哪里？",a="这段经历来自一位图书馆管理员：联盟的暴风城管理员是 Garion Wendell，部落的幽暗城管理员是 Owen Thadd。",al={"图书馆位置","图书馆在哪里","铁炉堡图书馆"}},{q="为什么要收集魔法典籍？",a="管理员说，每一份贡献都能拓展图书馆的知识。",al={"为什么收集书籍","图书馆藏书目的","用途"}}},fp="18,120,20.120.0,34.62.0,27.123.0,38.68.0"}
P.entries["quest:82"] = {n="腐化之巢",s="高级勘探员菲兹杜瑟想要弄清楚敌人到底是什么。虫子们一直在抽干腐化之巢所在的水池，关于它们的资料少之又少。你被要求从腐化之巢的蜈蚣身上收集五份虫壳，并将它们交给加基森的炼金师匹斯特苏格。",h="高级勘探员菲兹杜瑟想要弄清楚敌人到底是什么。虫子们一直在抽干腐化之巢所在的水池，关于它们的资料少之又少。你被要求从腐化之巢的蜈蚣身上收集五份虫壳，并将它们交给加基森的炼金师匹斯特苏格。",kw={"蜈蚣","菲兹杜瑟","加基森","昆虫","腐化之巢","匹斯特苏格","塔纳利斯"},sec={{t="来自巢穴的碎片",b="在完成加基森水质调查之后，高级勘探员菲兹杜瑟开始关注关于那些虫子的报告。目前已知的信息很少，只知道它们正在抽干曾经位于腐化之巢所在地的水池。菲兹杜瑟想先搞清楚敌人是谁，所以他请求你进入巢穴，从那里的蜈蚣身上收集五份样本，并将它们带回加基森交给炼金师匹斯特苏格进行检验。"},{t="匹斯特苏格的发现",b="匹斯特苏格立刻开始研究这些样本，并断言它们与之前见过的任何昆虫形态都不匹配，看起来就像是有某种外部力量在控制着这些虫子。随后，匹斯特苏格让你回去找菲兹杜瑟，因为有一个紧急情况需要你的帮助，这可能涉及塔纳利斯更多的虫子。"}},faq={{q="为什么高级勘探员菲兹杜瑟需要虫子样本？",a="虫子们正在抽干腐化之巢曾经所在的水池，人们对它们知之甚少。收集蜈蚣的碎片是为了帮助匹斯特苏格研究它们到底是什么。",al={"为什么收集虫子碎片","菲兹杜瑟 昆虫样本","腐化之巢的目的"}},{q="蜈蚣在哪里可以找到？",a="蜈蚣位于腐化之巢，也就是曾经的水池所在地。",al={"腐化之巢在哪里","蜈蚣位置","哪里能找到蜈蚣"}},{q="在加基森是谁负责接收这些虫子样本？",a="加基森的炼金师匹斯特苏格，他将对样本进行检验。",al={"向谁交付任务","匹斯特苏格位置","谁需要虫子样本"}},{q="这一步之前是什么？",a="它是加基森水质调查的后续任务。",al={"前置任务","任务前提","引导任务"}}},fp="26,219,19.364.0,21.280.1,56.176.0,30.72.0,43.76.0,28.38.0"}
P.entries["quest:82084"] = {n="A Lesson in Literacy",s="图书管理员认为你已准备好撰写自己的法术书。收集羽毛笔、墨水和莎草纸，用来制作书页。",h="图书管理员认为你已准备好撰写自己的法术书。收集羽毛笔、墨水和莎草纸，用来制作书页。",kw={"法拉基莎草纸","辛特兰","墨水","图书管理员","读写","枭兽羽毛笔","异种虫树脂","法术书"},sec={{t="法术书材料",b="图书管理员看好你在奥术研究上的前途，请你收集法术书所需的材料：来自辛特兰枭兽的羽毛笔、用异种虫树脂制成的墨水，以及用来制作书页的法拉基莎草纸。"}},faq={{q="图书管理员要我收集什么？",a="图书管理员要你收集来自辛特兰枭兽的羽毛笔、用异种虫树脂制成的墨水，以及法拉基莎草纸。",al={"法术书材料","读写材料","所需材料"}},{q="我为什么要收集这些材料？",a="图书管理员认为你已准备好撰写自己的法术书。",al={"为何收集这些","法术书用途","材料有何用途"}},{q="羽毛笔来自哪里？",a="图书管理员要你收集一支来自辛特兰枭兽的羽毛笔。",al={"枭兽羽毛笔","羽毛笔来源","羽毛笔在哪里"}},{q="墨水是用什么制成的？",a="所需的墨水由异种虫树脂制成。",al={"异种虫墨水","墨水原料","墨水成分"}},{q="法术书的书页是什么做的？",a="图书管理员要你用法拉基莎草纸制作书页。",al={"莎草纸书页","法拉基纸张","书页材料"}}},fp="20,111,19.229.0,43.127.0,35.68.0,31.69.0,26.49.0,37.53.0"}
P.entries["quest:821"] = {n="老陈的空酒桶",s="这个任务延续了贫瘠之地中熊猫人酿酒的传奇血统。棘齿城的酿酒师德罗恩提出，只要你从游荡在草原上的野生野兽身上收集野外原料，他就愿意为你重现老陈那久负盛名的烈性佳酿。",h="这个任务延续了贫瘠之地中熊猫人酿酒的传奇血统。棘齿城的酿酒师德罗恩提出，只要你从游荡在草原上的野生野兽身上收集野外原料，他就愿意为你重现老陈那久负盛名的烈性佳酿。",kw={"酿酒师德罗恩","老陈","酒桶","平原陆行鸟的肾脏","棘齿城","草原狮的獠牙","贫瘠之地","雷霆蜥蜴的角","穴居人啤酒"},ang={["faction:Horde"]="老陈曾与雷克萨并肩作战，帮助建立了杜隆塔尔，这使得他旅途中的任何遗留物都对部落有着特殊的文化共鸣。",["profession:Cooking"]="烹饪冒险家们会欣赏边境屠宰与精湛酿造之间那种大胆——尽管有些令人不安——的结合，正是这种结合打造出了传奇的卡利姆多烈酒。",["race:Orc"]="德罗恩体现了兽人是如何拥抱那些直接从曾与早期部落一同在这片土地上行走的旅行者那里传下来的古老酿酒师传统的。"},sec={{t="桶中的传奇",b="当一个刻有熊猫人文字的废弃酒桶最终落入棘齿城的酿酒师德罗恩手中时，这唤起了他对那位传奇流浪者老陈的美好回忆。老陈将他同名佳酿的秘诀传授给了德罗恩的导师，而导师又将其托付给了德罗恩。虽然对非酿酒师来说这很罕见，但这份配方需要直接取自贫瘠之地凶猛野生动物身上的原始且强劲的材料。"},{t="收获草原",b="酿造老陈的烈性酒需要一系列不同寻常的成分：平原陆行鸟的肾脏、草原狮的獠牙，以及雷霆蜥蜴的角。寻找这些物品需要在尘土飞扬的平原上狩猎，这证明了只有最强韧的野兽才能提供真正熊猫人风格酿造所需的劲道。一旦收集齐，德罗恩便会充满怀旧之情，感叹重现这个古老的配方让他胃里感到的温暖，几乎不亚于他过去酿造的穴居人啤酒。"}},faq={{q="酿酒师德罗恩是谁？",a="酿酒师德罗恩是驻扎在棘齿城港口的一名兽人酿酒师。他从一位曾亲自从传奇流浪者老陈那里获得配方的导师身上学到了酿酒艺术。",al={"酿酒师德罗恩","谁是德罗恩","棘齿城的德罗恩"}},{q="为什么啤酒配方需要动物肾脏和角？",a="熊猫人的酿酒传统——以及粗犷的边境酿酒师所做的调整——往往依赖于当地野生动物身上强大而神秘的成分，以便为他们的烈酒注入活力、劲道和独特的自然精华。",al={"为什么需要动物部位","平原陆行鸟肾脏啤酒","狮牙啤酒"}},{q="可以在哪里找到所需的原料？",a="这三种成分都采自贫瘠之地的本土动物。平原陆行鸟和草原狮在开阔的草原上游荡，而雷霆蜥蜴通常可以在平原上更干旱或多岩石的区域找到。",al={"在哪里可以找到獠牙","雷霆蜥蜴在哪里","寻找酿酒原料"}},{q="老陈是谁？",a="老陈是一位流浪的熊猫人酿酒师，他在杜隆塔尔建国期间游历了卡利姆多，在寻找珍稀原料来完善他那烈性啤酒的同时，也为部落提供了帮助。",al={"谁是老陈","老陈的背景故事","老陈"}},{q="把原料带给德罗恩后会发生什么？",a="交出狮牙、平原陆行鸟肾脏和雷霆蜥蜴的角会让德罗恩感到高兴，这提醒了他早期的酿酒岁月，并直接进入了重现那传奇烈酒的最后阶段。",al={"陈的空酒桶之后的下一个任务","德罗恩的奖励","接下来是什么"}},{q="德罗恩提到的穴居人啤酒是什么？",a="看到这些野生原料，德罗恩深情地回忆起了一种早期的混合酒，即穴居人啤酒，这证明了他过去在边境发酵那些口感浓烈、不同寻常的混合酒的古怪历史。",al={"穴居人啤酒","德罗恩的穴居人啤酒"}}},fp="16,109,17.301.0,23.360.1,24.167.0,56.181.0,44.124.0,24.198.0,53.205.0,38.169.0"}
P.entries["quest:822"] = {n="老陈的空酒桶",s="在成功酿造出强力的风暴烈酒之后，位于棘齿城的酿酒师德罗恩提出可以制作另一种从神秘的熊猫人流浪者陈·风暴烈酒那里学到的秘方。这种名为“穴居人麦酒”的烈性混合饮料，需要从贫瘠之地的本土野兽身上获取稀有的器官和腺体。",h="在成功酿造出强力的风暴烈酒之后，位于棘齿城的酿酒师德罗恩提出可以制作另一种从神秘的熊猫人流浪者陈·风暴烈酒那里学到的秘方。这种名为“穴居人麦酒”的烈性混合饮料，需要从贫瘠之地的本土野兽身上获取稀有的器官和腺体。",kw={"贫瘠之地","酿酒师德罗恩","陈·风暴烈酒","陈的空酒桶","科多兽的肝脏","棘齿城","风暴兽","雷鹰","穴居人麦酒"},ang={["faction:Horde"]="陈·风暴烈酒曾在杜隆塔尔保卫战期间与部落并肩作战，给德罗恩等在早期遇到他的兽人们留下了深刻的印象。",["profession:Cooking"]="烹饪纯粹主义者或许会排斥穴居人麦酒，但提取丰富的脏器肉和强力腺体，体现了边境烹饪传统中“猎物绝不浪费”的精髓。",["race:Orc"]="酿酒师德罗恩代表了兽人中少见的职业，他摒弃了传统的战士之路，拥抱了陈的异域酿酒法，并在棘齿城经营着自己的生意。"},sec={{t="第二个熊猫人配方",b="在帮助酿酒师德罗恩复刻了传奇人物陈·风暴烈酒的最初配方后，这位兽人酿酒师透露，那位流浪的熊猫人分享的秘密远不止一个。德罗恩掌握着一种名为“穴居人麦酒”的奇特饮料的配方。与用谷物蒸馏而成的普通烈酒不同，这种奇怪的麦酒完全依赖于从卡利姆多中部最凶猛的野生动物身上搜集而来的强力有机试剂。"},{t="穴居人麦酒的配料",b="为了酿造这种味道浓烈、令人振奋的饮料，德罗恩需要一些雷霆般的成分：风暴兽的闪电腺、巨型雷鹰的唾液腺，以及平原上游荡的科多兽的肝脏。蒸馏后，这种混合物便成为了一种专为在荒野生存而设计的强力刺激饮品。"},{t="持久的合作",b="德罗恩的技艺并不仅限于酿造一批。他意识到穿梭于棘齿城这一中立港口的旅行冒险者和雇佣兵对此有需求，因此他愿意保持长期合作，只要有探险者带来新鲜的兽类器官，他就愿意酿造新的穴居人麦酒。"}},faq={{q="陈·风暴烈酒是谁？",a="陈·风暴烈酒是一位神秘的流浪熊猫人酿酒师，他在杜隆塔尔建立期间游历了卡利姆多。在旅途中，他在棘齿城向德罗恩分享了一些强力的酿酒技术，随后继续了他的流浪之旅。",al={"陈是谁","陈的背景故事","熊猫人陈"}},{q="酿酒师德罗恩在哪里？",a="酿酒师德罗恩居住在棘齿城的中立港口城镇，该城镇位于贫瘠之地的东海岸。他终日沉浸在钻研与陈相遇时学到的奇特酿酒技艺中。",al={"德罗恩位置","酿酒师德罗恩在哪里","德罗恩非玩家角色"}},{q="什么是穴居人麦酒？",a="穴居人麦酒是陈教给德罗恩的一种非传统且强力的混合饮料。它不使用标准的酿酒啤酒花，而是加入了兽类腺体和内脏，这使其具有一种备受硬派冒险者青睐的劲头。",al={"穴居人麦酒","这是什么饮料","德罗恩酿什么"}},{q="去哪里收集闪电腺？",a="闪电腺可以从潜伏在贫瘠之地干旱荒原上的风暴兽身上获取，它们的体内蕴含着天然的电荷。",al={"闪电腺来源","风暴兽位置","去哪里获得闪电腺"}},{q="哪些野兽会掉落雷鹰的唾液腺？",a="这些腺体专门从巨型雷鹰身上采集。巨型雷鹰是掠食性鸟类，体型雄伟，能够施放电击，狩猎于贫瘠之地广阔的天空之上。",al={"雷鹰的唾液腺","巨型雷鹰在哪里","雷鹰位置"}},{q="我可以多次酿造穴居人麦酒吗？",a="可以。只要冒险者为他提供新鲜的腺体和科多兽的肝脏，酿酒师德罗恩就愿意随时调制更多的麦酒。",al={"可以重复吗","我可以再做一次吗","重复穴居人麦酒"}}},fp="16,154,25.261.0,28.252.0,23.181.1,23.209.0,34.145.0,18.176.0,37.133.0,43.124.0,36.104.0"}
P.entries["quest:8225"] = {n="Rare Fish - Brownell's Blue Striped Racer",s="一条钓鱼纪录标记 Brownell's Blue Striped Racer 已辨认。辨认已完成。",h="一条钓鱼纪录标记 Brownell's Blue Striped Racer 已辨认。辨认已完成。",kw={"brownell's blue striped racer","brownell's racer","鱼类辨认","稀有鱼","奖励"},sec={{t="纪录",b="辨认后响起一声简短提示。Brownell's Blue Striped Racer 已标记为完成，并且可领取奖励。"}},faq={{q="什么是 Brownell's Blue Striped Racer？",a="Brownell's Blue Striped Racer 是一条已标记为辨认完成的鱼。",al={"brownell's racer","蓝条纹鱼"}},{q="辨认完成了吗？",a="是的。Brownell's Racer 的辨认已完成。",al={"鱼类辨认","racer 已辨认"}},{q="有奖励可领吗？",a="是的，辨认完成后即可领取奖励。",al={"鱼类奖励","能得到什么"}}},fp="41,99,10.139.0,38.82.0,31.56.0,22.64.0"}
P.entries["quest:8228"] = {n="Could I get a Fishing Flier?",s="本周日将在藏宝海湾举办钓鱼大赛。传单上写有赛事规则，供你参赛前了解。",h="本周日将在藏宝海湾举办钓鱼大赛。传单上写有赛事规则，供你参赛前了解。",kw={"藏宝海湾","钓鱼大赛","钓鱼传单","钓鱼规则","赛事"},sec={{t="赛事规则",b="告示上写有藏宝海湾钓鱼大赛的规则。比赛定于本周日举行，你可以先通过传单了解赛事安排，再决定是否参加。"}},faq={{q="钓鱼大赛什么时候举行？",a="藏宝海湾钓鱼大赛将在本周日举行。",al={"钓鱼大赛时间","比赛日期"}},{q="钓鱼大赛在哪里举行？",a="钓鱼大赛在藏宝海湾举行。",al={"钓鱼大赛地点","比赛在哪里"}},{q="钓鱼传单上写了什么？",a="传单上写有钓鱼大赛的规则。",al={"钓鱼传单信息","传单内容"}},{q="我可以参加这场比赛吗？",a="如果你想参加钓鱼大赛，告示上提供了赛事规则。",al={"参加钓鱼大赛","报名参赛"}}},fp="28,124,16.195.0,28.48.0,29.36.0,36.53.0,36.78.0"}
P.entries["quest:823"] = {n="向奥戈尼尔报告",s="“向奥戈尼尔报告”是部落早期的一项任务，由森金村的加德林大师派遣。它指引初出茅庐的冒险者向北前往剃刀岭，向奥戈尼尔·魂痕发出警告，告知其火刃氏族邪教那阴险的触角。这次派遣有助于协调杜隆塔尔各地分散的防御力量，对抗在兽人故乡酝酿的恶魔腐蚀。",h="“向奥戈尼尔报告”是部落早期的一项任务，由森金村的加德林大师派遣。它指引初出茅庐的冒险者向北前往剃刀岭，向奥戈尼尔·魂痕发出警告，告知其火刃氏族邪教那阴险的触角。这次派遣有助于协调杜隆塔尔各地分散的防御力量，对抗在兽人故...",kw={"火刃氏族","杜隆塔尔","加德林大师","奥戈尼尔·魂痕","剃刀岭","向奥戈尼尔报告","森金村"},ang={["faction:Horde"]="这项任务标志着新结盟的暗矛巨魔与杜隆塔尔的兽人在面对共同威胁时，进行了至关重要的沟通与合作。",["race:Orc"]="奥戈尼尔·魂痕代表了你新家园的前线防御，确保恶魔的污染不会在杜隆塔尔境内扎根。",["race:Troll"]="尽管暗矛部族正忙于与扎拉赞的战斗，加德林大师仍通过向兽人领导人通报区域性危险，展现了巨魔对部落的忠诚。"},sec={{t="协调防御",b="当森金村正忙于应对自身的当地困境——尤其是回音群岛上扎拉赞的背叛——时，加德林大师意识到有关火刃氏族邪教的报告代表着一种更为广泛的危险。在试炼谷发现了恶魔腐蚀的流言，这位暗矛巫医深知这些威胁不能孤立处理。他派遣远道而来的英雄沿着尘土飞扬的道路向北前往剃刀岭，那里的当地兽人官员负责对杜隆塔尔进行更广泛的监视。"},{t="奥戈尼尔·魂痕",b="奥戈尼尔·魂痕驻扎在剃刀岭的军事营地中，他是一位负责铲除内部邪恶并保卫中部腹地的兽人。当冒险者传达加德林大师的警告时，奥戈尼尔毫不迟疑地整合了来自试炼谷和森金村的报告。他意识到火刃氏族的阴影正危险地逼近，随即迅速动员部队，试图在邪教徒的黑暗仪式动摇这个年轻国家之前将他们瓦解。"}},faq={{q="谁发布了“向奥戈尼尔报告”这个任务？",a="加德林大师，即居住在森金村的暗矛巫医兼精神领袖，会在你协助巨魔解决了当地的初步困难后将此任务交给你。",al={"谁发布向奥戈尼尔报告","在哪里接向奥戈尼尔报告","向奥戈尼尔报告任务发布者"}},{q="奥戈尼尔·魂痕在哪里？",a="奥戈尼尔·魂痕位于剃刀岭，那是位于森金村以北、杜隆塔尔中部的一个防御定居点。",al={"奥戈尼尔·魂痕在哪里","奥戈尼尔·魂痕位置","寻找奥戈尼尔·魂痕"}},{q="为什么加德林大师要派你去剃刀岭？",a="加德林大师意识到在试炼谷及杜隆塔尔周边发现的恶魔邪教活动对所有人构成威胁，而不仅仅是针对巨魔。他指引你去找奥戈尼尔·魂痕，这位兽人负责在该地区执行针对火刃氏族的治安任务。",al={"为什么要向奥戈尼尔报告","为什么要前往剃刀岭","向奥戈尼尔报告的目的"}},{q="任务中提到的火刃氏族是什么？",a="火刃氏族是一个在杜隆塔尔及更广阔区域的阴影中活动的背叛性恶魔崇拜邪教。他们在附近峡谷和洞穴中的秘密存在威胁着新部落的安全与稳定。",al={"谁是火刃氏族","火刃氏族邪教","什么是火刃氏族"}},{q="“向奥戈尼尔报告”之后是什么任务？",a="当你向剃刀岭的奥戈尼尔·魂痕提交报告后，他会立即指派你执行“黑暗风暴”任务，以调查并对抗正在集结的邪教徒威胁。",al={"向奥戈尼尔报告后的下一个任务","向奥戈尼尔报告后续","向奥戈尼尔报告之后是什么"}},{q="在接受此任务之前必须完成什么前置条件？",a="它自然而然地衔接在你通过“向森金村报告”任务抵达森金村之后，将试炼谷早期的发现与更广泛的杜隆塔尔战役联系起来。",al={"向奥戈尼尔报告前置任务","如何解锁向奥戈尼尔报告","向奥戈尼尔报告的前置任务"}}},fp="16,138,21.361.0,15.375.0,37.151.0,33.103.0,46.230.0,49.194.0,36.156.0,64.158.0"}
P.entries["quest:8234"] = {n="密封的蓝袋子",s="在艾萨拉，你受托从一名木喉萨满手中取回一个密封的袋子，并将它交给大法师克希雷姆。这个请求借由袋子将萨满与法师联系起来。",h="在艾萨拉，你受托从一名木喉萨满手中取回一个密封的袋子，并将它交给大法师克希雷姆。这个请求借由袋子将萨满与法师联系起来。",kw={"大法师克希雷姆","艾萨拉","袋子","密封的蓝袋子","木喉萨满"},sec={{t="密封的袋子",b="艾萨拉的一名木喉萨满拿着密封的蓝袋子，大法师克希雷姆正在同一片土地上等着收取它。你受托将袋子从萨满手中送到法师那里。"}},faq={{q="谁拿着密封的蓝袋子？",a="艾萨拉的一名木喉萨满拿着密封的蓝袋子。",al={"谁拿着袋子","木喉的袋子"}},{q="谁想要这个袋子？",a="密封的蓝袋子要交给艾萨拉的大法师克希雷姆。",al={"谁收取袋子","把袋子送到哪里"}},{q="我在哪里能找到袋子？",a="密封的蓝袋子在艾萨拉的一名木喉萨满那里。",al={"袋子的位置","密封的蓝袋子在哪里"}},{q="大法师克希雷姆在哪里？",a="大法师克希雷姆在艾萨拉。",al={"克希雷姆的位置","克希雷姆在哪里"}}},fp="16,164,12.164.0,29.55.0,18.61.0,24.59.0,24.29.0"}
P.entries["quest:824"] = {n="大地之环的耶努萨克雷",s="这个任务指引部落冒险者将从灰谷的元素生物身上找到的被污染的水球交给大地之环的耶努萨克雷。作为一名致力于元素和谐的萨满祭司，耶努萨克雷试图了解佐拉姆海岸和黑暗深渊内蔓延的腐蚀。研究这个圣物有望制止这种正在毒害该地区水域的非自然枯萎。",h="这个任务指引部落冒险者将从灰谷的元素生物身上找到的被污染的水球交给大地之环的耶努萨克雷。作为一名致力于元素和谐的萨满祭司，耶努萨克雷试图了解佐拉姆海岸和黑暗深渊内蔓延的腐蚀。研究这个圣物有望制止这种正在毒害该地区水域的非...",kw={"被污染的水球","黑暗深渊","大地之环","元素生物","耶努萨克雷","马斯托克·维尔西斯","佐拉姆海岸","佐拉姆加前哨站"},ang={["class:Shaman"]="这项任务直接涉及维护元素平衡的萨满职责。运送被污染的球体有助于大地之环的成员诊断一种危险的精神疾病。",["faction:Horde"]="随着部落在灰谷建立像佐拉姆加前哨站这样的防御营地，挖掘当地元素敌意背后的黑暗起源对于确保海岸线的安全至关重要。",["race:Troll"]="耶努萨克雷展现了暗矛部族深厚的精神智慧，代表大地之环运用他与灵魂的祖传羁绊。"},sec={{t="元素的信使",b="当奇怪且受到污染的元素生物开始在灰谷各处出现时，斥候们注意到了驱动它们的那股非自然力量。在残留物中躺着一颗被污染的水球，这是一个跳动着腐蚀魔法的完整容器。由于知道普通士兵和斥候缺乏诊断这种异常现象所需的精神洞察力，马斯托克·维尔西斯指引部落旅行者去寻找一位拥有深厚古代传说和元素知识的人：耶努萨克雷。"},{t="大地之环的注视",b="耶努萨克雷隶属于大地之环，这是一个致力于维护艾泽拉斯原始力量平衡的萨满教团。当部落军队在佐拉姆海岸沿线守卫边疆时，耶努萨克雷则专注于在附近的黑暗深渊神庙遗迹中溃烂的精神创伤。对他而言，一个从受污染的容器中汲取力量的元素生物不仅仅是一个孤立的威胁，更是一个令人警觉的预兆，表明未知的古老力量正在扭曲自然秩序。"}},faq={{q="耶努萨克雷是谁？",a="耶努萨克雷是一位代表卡利姆多北部大地之环的巨魔萨满祭司。他毕生致力于与元素沟通并进行研究，他驻扎在佐拉姆海岸附近，调查从黑暗深渊升起的黑暗骚乱。",al={"耶努萨克雷是谁","耶努萨克雷背景故事","耶努萨克雷在这里做什么"}},{q="什么是大地之环？",a="大地之环是一个致力于保持艾泽拉斯原始元素和谐的萨满组织。他们钻研古代传说、被遗忘的灵魂和旧日轶事，以修复元素混乱并治愈世界各地的精神腐蚀。",al={"什么是大地之环","大地之环是什么组织","大地之环背景故事"}},{q="在哪里可以找到耶努萨克雷？",a="耶努萨克雷位于灰谷佐拉姆海岸的佐拉姆加前哨站，他在那里研究从附近黑暗深渊升起的元素骚乱。",al={"耶努萨克雷在哪里","耶努萨克雷位置","寻找耶努萨克雷"}},{q="什么是被污染的水球？",a="这个球体是一个魔法导管，强大的水元素通过它引导自己的力量。发现一个被污染且完整的球体表明该地区的黑暗力量正在蓄意扭曲并奴役当地的灵魂。",al={"什么是被污染的水球","被污染的水球背景故事","水球"}},{q="是谁派你去和耶努萨克雷交谈的？",a="马斯托克·维尔西斯，一位驻扎在灰谷的部落军官，在意识到军队无法解读这种奇怪的魔法本质后，指引冒险者将这个被污染的圣物交给耶努萨克雷。",al={"谁开启了这个任务","马斯托克任务"}},{q="耶努萨克雷会怎么处理这个球体？",a="耶努萨克雷会保管这个容器，以便大地之环能够检查其枯萎的本质，希望研究结果能揭示一种净化水域并恢复该地区受困元素平静的方法。",al={"这个球体会怎么样","治愈腐蚀"}}},fp="26,308,28.440.0,28.407.0,22.235.0,25.234.0,34.173.0,33.220.0,35.168.0,35.188.0"}
P.entries["quest:8241"] = {n="炽热助熔剂的补给：铁锭",s="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而开始补充灼热峡谷中日益减少的炽热助熔剂供应。博恩奈特需要炽火龙鳞、铁锭和煤块，而且他有多少要多少。",h="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而开始补充灼热峡谷中日益减少的炽热助熔剂供应。博恩奈特需要炽火龙鳞、铁锭和煤块，而且他有多少要多少。",kw={"煤块","炽热助熔剂","炽火龙鳞","铁锭","大铁匠博恩奈特","通过铁补给恢复炽热助熔剂","灼热峡谷","瑟银兄弟会"},sec={{t="急需炽热助熔剂",b="大铁匠博恩奈特没时间闲聊。炽热助熔剂快用完了，博恩奈特需要炽火龙鳞、铁锭和煤块：两块龙鳞、四块铁锭以及煤块。他有多少要多少。"}},faq={{q="谁需要这些物资？",a="位于灼热峡谷的大铁匠博恩奈特，他会亲自接收这些物资。",al={"谁发布此任务","博恩奈特 炽热助熔剂","在哪里交任务"}},{q="博恩奈特需要什么材料？",a="两块炽火龙鳞、四块铁锭和一些煤块。",al={"我需要什么物品","炽热助熔剂的材料","博恩奈特上交物品"}},{q="这个任务的前置任务是什么？",a="名为“助熔剂怎么了？”的任务步骤，博恩奈特在这之前给你的任务。",al={"此任务的前置任务","炽热助熔剂的上一个任务","助熔剂怎么了的前置条件"}},{q="博恩奈特为什么需要这些物资？",a="博恩奈特说炽热助熔剂的供应正在减少，他想要补充库存。",al={"为什么要炽热助熔剂","博恩奈特的动机"}}},fp="38,190,17.196.0,25.91.0,35.65.0,30.70.0,36.88.0"}
P.entries["quest:8242"] = {n="炽热助熔剂的补给：重皮",s="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而致力于补充灼热峡谷内日渐减少的炽热助熔剂储备。博恩奈特需要焚火龙鳞、重皮和煤块，并且有多少收多少。",h="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而致力于补充灼热峡谷内日渐减少的炽热助熔剂储备。博恩奈特需要焚火龙鳞、重皮和煤块，并且有多少收多少。",kw={"大铁匠博恩奈特","煤块","炽热助熔剂","重皮","焚火龙鳞","灼热峡谷","瑟银兄弟会"},sec={{t="急需炽热助熔剂",b="大铁匠博恩奈特没时间闲聊。炽热助熔剂快用完了，博恩奈特需要焚火龙鳞、重皮和煤块：两片鳞片、十张重皮和一些煤块。博恩奈特有多少就会收多少。"}},faq={{q="谁需要这些物资？",a="位于灼热峡谷的大铁匠博恩奈特，他会亲自接收这些物资。",al={"谁发布此任务","博恩奈特炽热助熔剂","在哪里交任务"}},{q="博恩奈特需要什么材料？",a="两片焚火龙鳞、十张重皮和一些煤块。",al={"我需要什么物品","炽热助熔剂材料","博恩奈特上交物品"}},{q="在这个任务之前有什么前置任务？",a="名为“助熔剂怎么了？”的任务步骤，这是博恩奈特在此之前交给你的任务。",al={"此任务的前置要求","炽热助熔剂的前置任务","助熔剂怎么了的前置条件"}},{q="博恩奈特为什么要这些物资？",a="博恩奈特说炽热助熔剂的储备正在减少，因此需要进行补充。",al={"为什么需要炽热助熔剂","博恩奈特的动机"}}},fp="47,202,17.200.0,25.91.0,35.78.0,30.55.0,36.75.0"}
P.entries["quest:8249"] = {n="垃圾箱",s="在拉文霍德庄园，法拉德对坚固的锁闭容器有着源源不断的需求，以训练公会中冉冉升起的潜行者。由于庄园内部工匠提供的练习锁对于高阶学员来说太过简单，法拉德愿意用特制的飞刀与任何愿意提供真正重垃圾箱的人进行交易。",h="在拉文霍德庄园，法拉德对坚固的锁闭容器有着源源不断的需求，以训练公会中冉冉升起的潜行者。由于庄园内部工匠提供的练习锁对于高阶学员来说太过简单，法拉德愿意用特制的飞刀与任何愿意提供真正重垃圾箱的人进行交易。",kw={"重垃圾箱","希尔斯布莱德","垃圾箱","开锁","偷窃","拉文霍德","法拉德","赞"},ang={["class:Rogue"]="搜集这些重箱子完全依赖于偷窃老练对手的技艺，这使得拉文霍德成为潜行者非法技能的终极集散地。",["faction:Alliance"]="虽然隐藏在洛丹伦的争议领土中，但拉文霍德独立运作，接受来自联盟流浪者的契约，不考虑阵营界限。",["faction:Horde"]="勇敢踏入希尔斯布莱德山脉的部落特工会发现，拉文霍德对阵营忠诚度漠不关心，他们视有用的非法货物高于一切。"},sec={{t="磨砺拉文霍德之爪",b="在希尔斯布莱德丘陵上方群山中隐藏的拉文霍德庄园内，训练从未停止。盗贼大师法拉德负责指导公会特工的训练，非常看重实战开锁的精通程度。虽然赞为新兵提供练习装置，但法拉德认为那种粗糙的工艺完全不适合需要应付野外真实、顽固锁具的资深特工。"},{t="奇怪的开放式安排",b="为了让庄园获得真正的实战开锁装置，法拉德外包了从艾泽拉斯各处危险目标身上偷来的重垃圾箱。虽然只有熟练的盗贼才能从野外的目标身上偷窃这些箱子，但法拉德并不将业务仅限于潜行者。任何人只要送来一批这些锁闭的箱子——即使已经清空了里面的主要贵重物品——都能赢得法拉德的好感，并获得庄园精心制造的致命飞刀，前提是箱子里还要留有一枚代币，以激励学员。"}},faq={{q="为什么法拉德需要这些垃圾箱？",a="拉文霍德的潜行者学徒需要真实的装置来练习开锁。法拉德认为庄园驻地工匠赞制作的练习箱对于初学者以外的任何人来说都太基础了，他们需要从危险的目标身上收集真正的锁箱。",al={"为什么需要垃圾箱","垃圾箱的用途","为什么法拉德想要箱子"}},{q="这个任务在哪里进行？",a="交换地点位于拉文霍德庄园，这是隐藏在希尔斯布莱德丘陵以北山脉中的盗贼公会秘密避难所。",al={"垃圾箱任务地点","法拉德在哪里","拉文霍德位置"}},{q="只有潜行者才能交付这个任务吗？",a="虽然重垃圾箱最初是通过潜行者的偷窃艺术获得的，但法拉德接受任何有能力将其带到庄园的人的交付。",al={"这是潜行者专属任务吗","任何人都可以做垃圾箱任务吗","其他职业垃圾箱任务"}},{q="为什么箱子里必须保留硬币？",a="法拉德坚持每个箱子里都要留几枚硬币，因为即使是训练中的潜行者也需要实实在在的激励和奖励来鞭策他们的开锁训练。",al={"为什么要在箱子里留硬币","箱子里需要有战利品吗","空的垃圾箱"}},{q="拉文霍德提供什么作为交换？",a="法拉德会用公会声望和精心制作的飞刀奖励贡献者，他讽刺地希望这些飞刀能直接扎进某人的心脏。",al={"垃圾箱任务奖励","法拉德给什么","拉文霍德飞刀"}},{q="法拉德抱怨的赞是谁？",a="赞是拉文霍德内部的锁具供应商。法拉德认为赞制作的练习装置太粗糙，只适合最原始的新手，而不是严肃的特工。",al={"赞是谁","赞和拉文霍德","赞的锁具"}}},fp="16,166,30.335.0,28.382.0,37.257.0,32.131.0,35.136.0,52.128.0,39.138.0,39.148.0"}
P.entries["quest:825"] = {n="海底沉船",s="剃刀岭的加索克指挥部落侦察兵去流亡海岸搜寻戴林·普罗德摩尔海军上将舰队的沉船残骸。通过从水下的残骸中回收先进的侏儒的工具，部落希望能够拆解联盟的工程学技术，并将这种技术优势转化为自己的利益。",h="剃刀岭的加索克指挥部落侦察兵去流亡海岸搜寻戴林·普罗德摩尔海军上将舰队的沉船残骸。通过从水下的残骸中回收先进的侏儒的工具，部落希望能够拆解联盟的工程学技术，并将这种技术优势转化为自己的利益。",kw={"杜隆塔尔","加索克","侏儒的工具","普罗德摩尔","剃刀岭","打捞","流亡海岸","提拉加德城堡","残骸"},ang={["faction:Horde"]="加索克将每一片联盟的金属残片视为双重奖赏：既是击败未来入侵的知识，又是帮助建设杜隆塔尔这个新生国家的材料。",["profession:Engineering"]="对于工匠来说，侏儒的工具的回收凸显了联盟机械精度与部落蓬勃发展的工艺产业之间早期的技术摩擦。",["race:Gnome"]="虽然身材矮小，但侏儒在联盟航行的每一个地方都留下了他们的印记；他们精密的装备受到了部落足够的尊重，值得专门进行回收任务。"},sec={{t="舰队的回响",b="当戴林·普罗德摩尔海军上将将库尔提拉斯的海军力量带到卡利姆多时，他的船只挤满了提拉加德城堡附近的海岸线。在他战败后，破碎的船体散落在流亡海岸。虽然幸存的库尔提拉斯人士兵加固了城堡本身，但他们舰队的残骸却破碎地躺在浅滩上，在潮汐下慢慢腐烂。"},{t="侏儒的装置",b="兽人的战争传统上依靠蛮力、钢铁和鲜血，但部落也意识到了联盟的独创性所带来的危险优势。侏儒技术人员曾随远征舰队同行，为联盟的船只配备了复杂的机械和精密齿轮。加索克试图回收这些沉没的工具，以便部落能够解开它们背后的机械原理。"},{t="运往奥格瑞玛",b="这些回收的工具并非要在剃刀岭落满灰尘。加索克安排将它们通过大篷车直接运往奥格瑞玛。通过对侏儒仪器进行逆向工程，部落的工匠和战术家旨在在未来的冲突中更好地应对联盟的装置，同时增强自己新兴的工业。"}},faq={{q="为什么部落要从这些沉船中回收工具？",a="部落想要了解联盟所使用的先进技术。侏儒为人类军队制造精密的机械，通过研究这些工具，部落的战术家可以找到对抗联盟装置的方法，同时为自己的工匠采用有用的机械原理。",al={"为什么要获取侏儒的工具","为什么要打捞沉船","加索克对工具的意图"}},{q="流亡海岸外沉没的是谁的船？",a="这些沉没的船只属于戴林·普罗德摩尔海军上将的库尔提拉斯舰队。在登陆杜隆塔尔的海岸并向萨尔新建立的国家发动战争后，几艘船只在提拉加德城堡以东的海岸线沿线被摧毁。",al={"这些是谁的船","谁在杜隆塔尔摧毁了船只","普罗德摩尔舰队残骸"}},{q="回收的工具在离开剃刀岭后会被运往哪里？",a="加索克会将回收的侏儒的工具通过下一支前往奥格瑞玛的大篷车运走。在那里，工程师和工匠可以彻底研究这些装置，以帮助加强首都的防御和工业。",al={"工具会怎么样","侏儒的工具去哪里","谁获得了打捞物"}},{q="为什么人类的战舰上会有侏儒工具？",a="侏儒是联盟中人类的亲密盟友，经常为海军远征队提供机械专业知识、攻城装备和精密维护工具，以保持作战舰队的正常运转。",al={"为什么侏儒与人类在一起","普罗德摩尔船上的侏儒","联盟的侏儒科技"}},{q="什么是流亡海岸？",a="流亡海岸是杜隆塔尔东部的海岸线，经过提拉加德城堡。它的得名是因为在与普罗德摩尔的远征军战斗后，这里浅水区遍布半沉和沉没的船只。",al={"流亡海岸在哪里","流亡海岸的位置","杜隆塔尔沉船区域"}},{q="这项任务与提拉加德城堡的威胁有什么联系？",a="在对提拉加德城堡的突袭中扫清了库尔提拉斯海军陆战队之后，加索克利用这个机会搜刮了剩余的联盟资源。剥离附近的沉船残骸可以确保在拾荒者或潮汐带走一切之前，部落能从敌人的失败中获利。",al={"提拉加德城堡的联系","战胜背叛者任务链接","为什么在提拉加德之后做这个"}}},fp="21,158,19.294.0,20.317.0,22.254.0,51.247.0,46.219.0,49.182.0,46.159.0,26.186.0,58.246.0"}
P.entries["quest:826"] = {n="扎拉赞恩",s="森金村的加德林大师派遣部落的勇士前往回音群岛，终结巫医扎拉赞恩的背叛。受黑魔法蛊惑而疯狂的扎拉赞恩奴役了自己的族人，并占领了暗矛巨魔原本的家园，迫使他们流亡至杜隆塔尔的海岸。",h="森金村的加德林大师派遣部落的勇士前往回音群岛，终结巫医扎拉赞恩的背叛。受黑魔法蛊惑而疯狂的扎拉赞恩奴役了自己的族人，并占领了暗矛巨魔原本的家园，迫使他们流亡至杜隆塔尔的海岸。",kw={"暗矛","杜隆塔尔","回音群岛","被施法的巨魔","加德林大师","森金村","沃金","巫毒巨魔","扎拉赞恩"},ang={["class:Shaman"]="扎拉赞恩扭曲了巨魔萨满和巫医所修习的灵性技艺与原始力量，将禁锢魔法用于攻击自己的同胞。",["faction:Horde"]="这场冲突代表了年轻部落面临的第一次重大团结考验，证明了来自杜隆塔尔各地的盟友会团结起来，保卫流离失所的暗矛巨魔部落。",["race:Troll"]="对于暗矛巨魔来说，击杀扎拉赞恩是一场极其私人的复仇与职责履行，是对那个窃取了你们民族的真正家园并奴役你们兄弟的叛徒的惩罚。"},sec={{t="群岛上的背叛",b="当暗矛巨魔逃离他们沉没的岛屿家园，跟随萨尔跨越无尽之海后，他们在杜隆塔尔东南海岸外的回音群岛建立了一个定居点。扎拉赞恩，这位部落中受人尊敬且力量强大的巫医，屈服于权力欲望。他利用奴役心智的妖术，控制了许多族人并掀起了一场暴乱。幸存的自由暗矛巨魔在沃金的带领下被驱逐出祖传的营地，被迫在森金村建立了一个临时避难所。"},{t="部落的磨难",b="扎拉赞恩并不满足于仅仅将族人赶走。他在回音群岛最大的岛屿上的山顶堡垒中，不断派突袭队穿过海峡，抓捕更多的暗矛巨魔并将其变成奴隶。那些受害者变成了毫无思想的巫毒奴隶，对部落而言已彻底失去。加德林大师认为这不仅仅是领土的占领，更是一种生存威胁：除非将扎拉赞恩的首级带到长老面前，否则没有任何暗矛巨魔能真正安全。"}},faq={{q="扎拉赞恩是谁？",a="扎拉赞恩曾是暗矛巨魔中一位杰出的巫医。他因对黑暗力量的渴望而堕落，转而攻击同胞，利用控制心智的巫毒术奴役族人，并为自己占领了回音群岛。",al={"扎拉赞恩传说","回音群岛的首领是谁","巫医扎拉赞恩"}},{q="为什么暗矛巨魔会逃离回音群岛？",a="扎拉赞恩在岛上发动了突袭政变，通过邪恶的巫术将兄弟姐妹变成了毫无思想的奴隶。沃金和幸存的自由暗矛巨魔因人数不足无法对抗被施了法的同胞，于是撤退到杜隆塔尔大陆，建立了森金村作为临时避难所。",al={"为什么巨魔在森金村","回音群岛背景故事","巨魔是如何失去回音群岛的"}},{q="在扎拉赞恩控制下的巨魔会怎样？",a="在扎拉赞恩控制下的巨魔，其心智已被强大的妖术完全摧毁。他们完全沦为扎拉赞恩毫无思想的仆从，在岛上巡逻并对大陆发起突袭以捕获更多受害者。加德林大师认为他们对部落而言已彻底沦丧，执行处决是唯一的仁慈。",al={"被施法的巨魔","巫毒巨魔","扎拉赞恩的奴隶能治愈吗"}},{q="扎拉赞恩在哪里？",a="扎拉赞恩将巢穴设在回音群岛链中最大的岛屿上，位于杜隆塔尔南海岸的正东方。他在中央山丘的高峰和下方那一群巨魔小屋之间巡逻。",al={"扎拉赞恩位置","寻找扎拉赞恩","扎拉赞恩在哪里"}},{q="是谁发布了杀死扎拉赞恩的任务？",a="加德林大师，即位于杜隆塔尔南岸森金村的部落长老，会在你完成处理当地威胁的入门任务并从试炼谷来到这里后提供该任务。",al={"谁发布扎拉赞恩的任务","在哪里接扎拉赞恩任务"}},{q="为什么沃金不亲自领导进攻？",a="虽然沃金统领着部落，并在奥格瑞玛与萨尔大酋长一同协调暗矛巨魔的防御工作，但森金村仍由像加德林大师这样的当地长老负责引导。加德林负责协调日常生存，并招募有能力的冒险者反击这位背叛的巫医。",al={"沃金在哪里","为什么沃金不打扎拉赞恩"}}},fp="8,304,21.444.0,17.430.0,16.205.0,42.291.0,52.233.0,26.186.0,37.186.0,46.241.0"}
P.entries["quest:827"] = {n="骷髅石",s="此项任务由隐士玛高兹委派，指引部落冒险者前往位于奥格瑞玛正东方的骷髅石洞穴。该洞穴已被火刃氏族邪教所占据，他们使用痛苦的恶魔装置将自己与黑暗魔法绑定。收缴这些被诅咒的神器可以让玛高兹研究在这个首都家门口出现的邪教动向。",h="此项任务由隐士玛高兹委派，指引部落冒险者前往位于奥格瑞玛正东方的骷髅石洞穴。该洞穴已被火刃氏族邪教所占据，他们使用痛苦的恶魔装置将自己与黑暗魔法绑定。收缴这些被诅咒的神器可以让玛高兹研究在这个首都家门口出现的邪教动向。",kw={"火刃氏族","邪教徒","恶魔","杜隆塔尔","邪能","玛高兹","奥格瑞玛","灼热项圈","骷髅石"},ang={["class:Warlock"]="灼热项圈展示了粗糙但强大的邪能绑定，让黑暗践行者得以一窥该邪教如何将恶魔祭品转化为原始力量。",["faction:Horde"]="一个在奥格瑞玛城墙外滋生的恶魔邪教威胁着年轻部落的核心与安全。",["race:Orc"]="火刃氏族代表了兽人们每天都在努力摆脱的黑暗过去；将他们从杜隆塔尔的岩石中清除出去，不仅关乎生存，也关乎荣誉。"},sec={{t="阴影巢穴",b="骷髅石是位于杜隆塔尔东北部崎岖山丘中的一座险恶洞穴。虽然看似偏僻，但它距离奥格瑞玛大门却近得令人不安。这些洞穴里没有野兽或普通的亡命之徒，而是盘踞着火刃氏族的一个分支——长期以来一直困扰着兽人社会的阴暗恶魔邪教。在这些昏暗的隧道中，邪教徒在大酋长的斥候眼皮底下进行着邪恶的仪式。"},{t="恶魔协调",b="在骷髅石内活动的邪教徒佩戴着灼热项圈，这是一种旨在灼烧和烙印他们自身血肉的颈圈。据玛高兹说，这种自残行为远非单纯的残忍；金属中嵌入的灼热痛苦和邪能魔法有助于使佩戴者与恶魔力量达成协调。通过回收这些神器，玛高兹打算解开赋予火刃氏族力量的具体咒语和绑定。"},{t="迫在眉睫的威胁",b="揭开项圈背后的秘密证实了该邪教在杜隆塔尔的活动是蓄意且有组织的。火刃氏族并非仅仅以分散的强盗形式活动；他们的魔法根深蒂固，对新建立的部落领地构成了直接而阴险的威胁。分析这些项圈引发了一连串的调查，并将线索直接指向了奥格瑞玛阴影中的圈子。"}},faq={{q="骷髅石位于何处？",a="骷髅石是一座位于杜隆塔尔东北部的海岸洞穴，坐落在奥格瑞玛以东、森金村以北的海岸线上。其入口处有险峻的悬崖作为标记。",al={"骷髅石位置","骷髅石在哪里","杜隆塔尔骷髅石洞穴"}},{q="火刃氏族是什么？",a="火刃氏族是一个危险的兽人与邪能崇拜者邪教，致力于崇拜恶魔实体和黑暗魔法。虽然现代部落已经脱离了恶魔的奴役，但像火刃氏族这样的分裂团体仍在继续进行禁忌仪式，试图从阴影中腐化部落。",al={"火刃氏族是什么","火刃氏族邪教徒是谁","火刃氏族背景"}},{q="邪教徒使用灼热项圈做什么？",a="邪教徒将灼热的金属带戴在脖子上以灼烧自己的血肉。玛高兹怀疑这种仪式性的痛苦和恶魔附魔使他们能够引导并协调自己以获取黑暗的邪能。",al={"灼热项圈用途","为什么要佩戴灼热项圈","什么是灼热项圈"}},{q="玛高兹是谁？",a="玛高兹是一位兽人隐士，居住在杜隆塔尔悬崖顶上的一个小营地里，靠近骷髅石。他密切关注着沿海地区的邪教活动，并致力于瓦解火刃氏族的黑暗行动。",al={"玛高兹是谁","杜隆塔尔玛高兹","玛高兹任务给予者"}},{q="为什么部落允许邪教在奥格瑞玛附近存在？",a="他们并非知情并容忍。该邪教在极度保密的情况下运作，隐藏在常规巡逻队很少到达的洞穴和荒凉的峡谷中。冒险者之所以被派去调查，正是因为这些邪教徒在黑暗仪式开始前，成功地掩盖了他们的立足点。",al={"为什么骷髅石在奥格瑞玛附近","奥格瑞玛火刃氏族"}},{q="玛高兹检查项圈后会发生什么？",a="玛高兹打算检查灼热项圈。调查将随着奥格瑞玛的尼尔鲁·火刃任务继续进行。",al={"骷髅石之后的任务","项圈线索","玛高兹法术"}}},fp="10,216,16.308.0,18.283.0,18.239.1,28.145.0,25.257.0,49.201.0,14.192.0,56.219.0,47.107.1"}
P.entries["quest:8273"] = {n="奥兰的感谢",s="在“林吉的秘密”任务之后，始于“林吉被困！”的任务线，随着你将一块石板带给奥兰·斯内克威瑟而宣告终结。",h="在“林吉的秘密”任务之后，始于“林吉被困！”的任务线，随着你将一块石板带给奥兰·斯内克威瑟而宣告终结。",kw={"黑暗女王","辛特兰","奥兰·斯内克威瑟","眺望台悬崖","林吉","石板"},sec={{t="给奥兰的石板",b="“林吉被困！”开启了这条任务线，而“林吉的秘密”是紧接在这一步之前的任务。奥兰·斯内克威瑟是你所携带石板的交付对象。"},{t="奥兰的回答",b="奥兰询问石板是在哪里发现的，你告诉他是在眺望台悬崖边的一座荒废小岛上。奥兰觉得这非常有趣，小心地收好了石板，并说黑暗女王会对这个发现感到非常高兴。"}},faq={{q="奥兰·斯内克威瑟是谁？",a="奥兰·斯内克威瑟是结束了那条始于“林吉被困！”并贯穿了“林吉的秘密”的任务线的人。",al={"奥兰","奥兰是谁","奥兰·斯内克威瑟背景故事"}},{q="任务线中这一步之前是什么？",a="在这之前是“林吉的秘密”，而在那之前是“林吉被困！”。",al={"前序任务","奥兰的感激的前置任务","如何开始奥兰的感激"}}},fp="16,72,17.91.0,13.220.1,24.134.0,36.66.0"}
P.entries["quest:828"] = {n="玛高兹",s="玛高兹是一个部落任务，要求冒险者寻找一位守望在杜隆塔尔北部的隐居兽人萨满。在枯水谷遭遇邪能腐蚀后，奥戈尼尔·魂痕会指引勇士们在袭击附近的邪教据点前先去咨询玛高兹。这位睿智的隐士对火刃氏族投下的日益增长的阴影提供了关键建议。",h="玛高兹是一个部落任务，要求冒险者寻找一位守望在杜隆塔尔北部的隐居兽人萨满。在枯水谷遭遇邪能腐蚀后，奥戈尼尔·魂痕会指引勇士们在袭击附近的邪教据点前先去咨询玛高兹。这位睿智的隐士对火刃氏族投下的日益增长的阴影提供了关键建议...",kw={"火刃氏族","枯水谷","杜隆塔尔","玛高兹","奥戈尼尔·魂痕","奥格瑞玛","萨满","骷髅石"},ang={["class:Shaman"]="玛高兹代表了萨满教古老而耐心的智慧，他在荒野边缘守望，以便在精神腐蚀演变成战争之前就察觉到它。",["faction:Horde"]="玛高兹的警告突显了奥格瑞玛的脆弱性，证明了恶魔邪教潜伏在部落心脏的打击距离之内。",["race:Orc"]="拜访玛高兹提醒了兽人战士们邪能力量挥之不去的诱惑，敦促新一代人走上一条纯洁而光荣的道路。"},sec={{t="隐士的守望",b="在发现雷霆山的邪能腐蚀深度后，奥戈尼尔·魂痕认识到仅靠蛮力不足以净化杜隆塔尔。他指引他的勇士们去找玛高兹，一位经验丰富的兽人萨满，在剃刀岭东北部的岩石地带独自扎营。玛高兹位于枯水谷的崎岖高地与东海之间，时刻监视着奥格瑞玛那些忙碌的战士们往往会忽略的黑暗预兆。"},{t="骷髅石的威胁",b="玛高兹掌握着有关火刃氏族在杜隆塔尔北部真正权力基地的关键情报：一个被称为骷髅石的隐藏洞穴系统，就开凿在奥格瑞玛南门外的山崖上。通过与玛高兹商议，旅行者们了解到这些邪教徒在萨尔的首都附近的活动，远比酋长的卫兵们所意识到的要近得多。这位萨满确保任何被派去清除该集会所的人都不会盲目地陷入恶魔的伏击。"}},faq={{q="玛高兹是谁？",a="玛高兹是一位效忠于部落的睿智兽人萨满，住在杜隆塔尔东北部的一个隐蔽营地里。他研究黑暗魔法的动向，并监视着在该地区蔓延的恶魔腐蚀。",al={"玛高兹背景故事","玛高兹是谁","玛高兹 非玩家角色"}},{q="我在哪里可以找到玛高兹？",a="玛高兹在杜隆塔尔东北部的崎岖山丘中扎营，位于枯水谷和东海岸线之间，就在奥格瑞玛的东南部。",al={"玛高兹位置","寻找玛高兹","玛高兹在哪里"}},{q="为什么奥戈尼尔·魂痕要派我去找玛高兹？",a="奥戈尼尔认识到玛高兹花了大量时间研究当地的火刃氏族邪教徒。在派你去袭击他们的据点之前，奥戈尼尔希望你能得到玛高兹的精神智慧和实践建议。",al={"为什么要与玛高兹交谈","奥戈尼尔·魂痕 玛高兹"}},{q="什么是骷髅石？",a="骷髅石是一个位于奥格瑞玛东墙南侧的隐藏山洞。它作为火刃氏族的一个防御森严的集会所，崇拜恶魔的邪教徒们就在部落的眼皮底下进行仪式。",al={"骷髅石背景故事","什么是骷髅石"}},{q="找到玛高兹之后会发生什么？",a="一旦你向玛高兹报告，他会认可你不断增长的实力，并立即指派你进入骷髅石，杀死邪教徒并取回他们受腐蚀的徽记。",al={"玛高兹之后的后续任务","玛高兹后续"}},{q="玛高兹是火刃氏族的一员吗？",a="不。玛高兹是一位忠诚的部落萨满，致力于清除恶魔的影响，并让年轻的勇士们保持在一条光荣且未受腐蚀的道路上。",al={"玛高兹是邪恶的吗","玛高兹是邪教徒吗"}}},fp="6,333,16.370.0,24.392.0,14.189.0,23.151.0,43.211.0,19.186.0,34.153.1,36.137.0"}
P.entries["quest:829"] = {n="尼尔鲁·火刃",s="这个任务将杜隆塔尔的玛高兹指引部落冒险者前往奥格瑞玛那阴影笼罩的腹地。你带着从火刃氏族邪教徒手中缴获的恶魔灼热项圈，被指引去寻找尼尔鲁·火刃。他是一位居住在暗影裂口的著名术士，声称自己研究黑暗魔法仅仅是为了保护部落。",h="这个任务将杜隆塔尔的玛高兹指引部落冒险者前往奥格瑞玛那阴影笼罩的腹地。你带着从火刃氏族邪教徒手中缴获的恶魔灼热项圈，被指引去寻找尼尔鲁·火刃。他是一位居住在暗影裂口的著名术士，声称自己研究黑暗魔法仅仅是为了保护部落。",kw={"火刃氏族","暗影裂口","杜隆塔尔","玛高兹","尼尔鲁·火刃","奥格瑞玛","灼热项圈","骷髅石","术士"},ang={["class:Shaman"]="玛高兹的坦白标志着萨满教义与恶魔魔法之间有着清晰的界限：元素不会与邪能神器沟通，因此需要术士的协助。",["class:Warlock"]="进入暗影裂口咨询尼尔鲁·火刃，让你直接接触到了奥格瑞玛最著名的术士，验证了你的禁忌技艺对部落的现实价值。",["faction:Horde"]="这项任务展示了奥格瑞玛内部脆弱的休战状态，大酋长的萨满们有时必须求助于暗影裂口中的阴影流放者，以保护杜隆塔尔免于灭亡。"},sec={{t="萨满的极限",b="在从潜伏于骷髅石的邪教徒手中回收了灼热项圈后，萨满玛高兹发现，解开这些邪恶魔法的奥秘已超出了他先祖技艺的能力范围。萨满与元素之灵和大地沟通，而这些神器却散发着原始的恶魔腐蚀气息。玛高兹意识到，若要了解火刃氏族的装置，就需要找一位精通神秘学的人，因此他派你去寻找居住在首都的一位术士。"},{t="进入暗影裂口",b="在奥格瑞玛的红色峭壁之下，坐落着暗影裂口，这是一个光线昏暗的洞穴，禁忌魔法的修行者们在萨尔警惕的注视下在此施展技艺。兽人术士尼尔鲁·火刃居住于此，他是一位极具影响力的人物，坚称自己对邪能的掌握完全是为了挫败恶魔的威胁。将项圈样本交给他引起了他极大的好奇心，将杜隆塔尔对邪教的调查直接带入了术士聚集地的核心。"}},faq={{q="为什么玛高兹要我去找术士？",a="玛高兹是一位萨满，他的力量源自元素和先祖之灵。从骷髅石回收的灼热项圈本质上纯粹是恶魔之物，而要探明其附魔和起源，需要精通邪能魔法和黑暗艺术的人。",al={"为什么需要术士","为什么是尼尔鲁","玛高兹 术士"}},{q="我在哪里可以找到尼尔鲁·火刃？",a="尼尔鲁·火刃位于暗影裂口，这是奥格瑞玛下方的一个地下洞穴群，术士、潜行者和暗影施法者们聚集于此。",al={"尼尔鲁位置","尼尔鲁·火刃在哪","暗影裂口 尼尔鲁"}},{q="尼尔鲁·火刃值得信任吗？",a="玛高兹本人也抱有怀疑。他指出，虽然尼尔鲁声称他的神秘学研究是无害的，仅用于对抗恶魔，但这究竟是真是假还有待观察。萨尔允许术士在奥格瑞玛活动，但会对他们进行严格的监督，建议保持警惕。",al={"尼尔鲁是邪恶的吗","尼尔鲁值得信任吗","我可以信任火刃吗"}},{q="什么是项圈样本？",a="项圈样本是从骷髅石的火刃氏族邪教徒身上缴获的灼热项圈之一。玛高兹把它交给你，让你直接送交给尼尔鲁·火刃进行魔法分析。",al={"项圈样本","什么是项圈","灼热项圈任务物品"}},{q="把项圈交给尼尔鲁之后会发生什么？",a="尼尔鲁会仔细检查这个项圈，随后引出任务“雅克塞罗斯”，他会派你深入调查该邪教在杜隆塔尔的阴影存在。",al={"尼尔鲁之后的后续任务","尼尔鲁做什么","尼尔鲁的任务线"}},{q="为什么部落允许术士留在奥格瑞玛？",a="大酋长萨尔出于现实的需要容忍了术士的存在，将他们限制在暗影裂口的地下，以便对其危险的研究进行监视和控制，并偶尔利用他们的知识来了解恶魔敌人。",al={"为什么允许术士存在","暗影裂口里的术士","萨尔 术士"}}},fp="15,210,17.276.0,24.342.0,37.237.0,33.121.0,31.198.0,27.167.0,46.147.0,47.205.0"}
P.entries["quest:83"] = {n="红色亚麻布",s="“红色亚麻面罩”是东谷伐木场的一位裁缝萨拉·迪博雷恩提供的一项艾尔文森林任务。由于布料短缺，她请求过往的冒险者去猎杀当地的迪菲亚强盗，并夺取他们身上的亚麻面罩。作为交换，她会利用回收来的布料为旅行者制作有用的商品。",h="“红色亚麻面罩”是东谷伐木场的一位裁缝萨拉·迪博雷恩提供的一项艾尔文森林任务。由于布料短缺，她请求过往的冒险者去猎杀当地的迪菲亚强盗，并夺取他们身上的亚麻面罩。作为交换，她会利用回收来的布料为旅行者制作有用的商品。",kw={"粗麻布","迪菲亚潜行者","东谷伐木场","艾尔文森林","红色亚麻面罩","萨拉·迪博雷恩","裁缝"},ang={["faction:Alliance"]="清理侵扰艾尔文森林树林的迪菲亚强盗不仅能为东谷带来有用的回收品，还能积极削弱兄弟会对王国腹地的控制。",["profession:Tailoring"]="萨拉·迪博雷恩的生意展示了乡村裁缝业的严酷现实，由于布料极其匮乏，当地裁缝不得不直接从地区强盗的背上收割布料。"},sec={{t="强盗与粗麻布",b="虽然在北郡山谷游荡的低等级迪菲亚强盗们只会用廉价的粗麻布面罩凑合，但在广阔的艾尔文森林出没的有组织的不法之徒们佩戴的却是更精细的绯红色亚麻面罩。对于缺乏原材料的当地工匠来说，这些帮派标识代表着一种极其务实且可用的布料来源。"},{t="营地回收",b="萨拉·迪博雷恩在艾尔文森林东部边缘繁忙的东谷伐木场工作，她总是在寻找可用的纺织品。通过鼓励冒险者清理隐藏在森林各处的迪菲亚营地，她既能维持自己的裁缝生意，又能帮助遏制兄弟会日益猖獗的侵扰。"}},faq={{q="是谁提供了“红色亚麻面罩”任务？",a="这项任务是由位于艾尔文森林东部东谷伐木场的裁缝萨拉·迪博雷恩提供的。",al={"谁提供红色亚麻面罩任务","红色亚麻面罩任务发布者","萨拉·迪博雷恩任务"}},{q="完成“红色亚麻面罩”任务需要哪些物品？",a="你需要收集6个红色亚麻面罩，它们可以从散布在艾尔文森林各处的迪菲亚帮派成员身上拾取。",al={"红色亚麻面罩需要收集什么","红色亚麻面罩所需物品","需要的面罩"}},{q="我在哪里可以在艾尔文森林找到迪菲亚强盗？",a="迪菲亚不法之徒栖息在艾尔文森林各处的小型营地中，包括布莱克威尔南瓜田、斯通菲尔德农场以及杰罗德码头周围的森林区域。",al={"艾尔文森林迪菲亚位置","迪菲亚营地在哪里","去哪里获取红色面罩"}},{q="为什么艾尔文森林的迪菲亚成员戴的是亚麻布而不是粗麻布？",a="根据萨拉·迪博雷恩的说法，北郡的低阶迪菲亚成员佩戴的是简陋的粗麻布面罩，而活跃在更广阔的艾尔文森林区域的成员装备更好，佩戴的是红色亚麻布，这标志着他们在兄弟会内部拥有更高的组织和补给层级。",al={"为什么要红色亚麻布","迪菲亚粗麻布对比亚麻布","迪菲亚面罩材质"}},{q="为什么萨拉·迪博雷恩想要强盗的面罩？",a="萨拉的裁缝生意正面临布料短缺。她会对从迪菲亚面罩上回收的干净亚麻布进行再利用，为伐木工和旅行者缝制实用的物品。",al={"为什么要收集面罩","萨拉如何处理面罩"}},{q="东谷伐木场位于哪里？",a="东谷伐木场位于艾尔文森林的最东端，就在通往赤脊山桥梁的主路北侧。",al={"东谷位置","东谷在哪里","如何找到萨拉·迪博雷恩"}}},fx={["18a4a024"]={q="红色亚麻面罩有什么用？",a="在艾尔文森林各处游荡的迪菲亚潜行者匪徒用这些红色亚麻面罩遮面。北郡的恶徒只能将就着使用粗麻布，而森林其他地方的盗贼用的布料更好。萨拉·迪博雷恩会将缴获的面罩拆开，重新织成实用的亚麻衣物。",al={"红色亚麻面罩有什么用","红色亚麻面罩用途","为什么要红色亚麻面罩"}},["8ac6c8ef"]={q="为什么艾尔文森林里会有迪菲亚匪徒？",a="迪菲亚潜行者在艾尔文森林各处设立营地，骚扰旅人，劫掠补给线，削弱暴风城的统治。他们的势力日益壮大，威胁着东谷伐木场等当地聚居地，趁着王国卫兵人手不足，在都城近旁扩大不法活动。",al={"艾尔文的迪菲亚","迪菲亚为什么在这里","迪菲亚潜行者 艾尔文森林"}},fea06053={q="萨拉·迪博雷恩为什么需要你帮忙，而不找卫兵？",a="萨拉·迪博雷恩是东谷伐木场的一名裁缝，并非士兵，也没有能力亲自对抗匪徒。暴风城的卫兵和当地驻军为了遏制四处发生的迪菲亚侵袭和豺狼人劫掠，早已不堪重负，普通工匠只能依靠路过的冒险者获取材料和保护。",al={"萨拉为什么找我","为什么不找艾尔文卫兵","迪博雷恩为什么需要帮助"}}},fp="15,169,18.181.0,19.200.0,37.109.0,42.92.0,49.138.0,54.180.0,46.153.0,43.127.0"}
P.entries["quest:830"] = {n="将军的命令",s="这些饱经风霜的文件是从提拉加德城堡顶层的一个锁着的保险箱里回收的，上面印有已故海军上将戴林·普罗德摩尔的个人印章。这些回收的命令揭示出，杜隆塔尔海岸沿线的库尔提拉斯人驻军绝非简单的海难幸存者，而是更加根深蒂固、组织严密的军队。将这些文件交给剃刀岭的加索克，便暴露了威胁着这个新生兽人国度的残余军事计划。",h="这些饱经风霜的文件是从提拉加德城堡顶层的一个锁着的保险箱里回收的，上面印有已故海军上将戴林·普罗德摩尔的个人印章。这些回收的命令揭示出，杜隆塔尔海岸沿线的库尔提拉斯人驻军绝非简单的海难幸存者，而是更加根深蒂固、组织严密的...",kw={"海军上将的命令","旧信封","戴林·普罗德摩尔","加索克","库尔提拉斯","本尼迪克特中尉","剃刀岭","提拉加德城堡"},ang={["faction:Horde"]="发掘普罗德摩尔的命令证明，联盟在杜隆塔尔海岸的存在是一场蓄谋已久的灭绝行动，这更加强调了部落为何必须时刻警惕地保卫其新家园。",["race:Orc"]="对于在杜隆塔尔为建立未来而奋斗的兽人来说，这些文件无情地提醒着他们戴林·普罗德摩尔那不懈的仇恨，以及那些仍试图毁灭他们的残余势力。"},sec={{t="一份尘封的遗赠",b="在提拉加德城堡上层的一个沉重箱子里，藏着一个旧信封，由本尼迪克特中尉看守。这份羊皮纸上盖着海军上将戴林·普罗德摩尔的徽章，概述了库尔提拉斯在血腥入侵杜隆塔尔期间发布的直接海军命令。即使在海军上将倒在塞拉摩之后，他的军官们仍坚守着防御工事，紧紧地执行着消灭部落定居点的任务。"},{t="剃刀岭的警报",b="将回收的文件交给剃刀岭的指挥官加索克，证实了当地防御部队最担心的事。沿东海岸扎根的人类部队并非漫无目的的落难者，而是一处等待增援的稳固滩头阵地。加索克立刻意识到，瓦解提拉加德的指挥体系对于杜隆塔尔的生存来说是当务之急。"}},faq={{q="在哪里可以找到海军上将的命令？",a="这些命令位于杜隆塔尔提拉加德城堡三楼一个锁着的箱子里，装在一个旧信封中。要打开这个箱子，你必须先击败二楼的本尼迪克特中尉，夺取他的钥匙。",al={"命令位置","旧信封在哪里","寻找海军上将的命令"}},{q="普罗德摩尔上将是谁？",a="海军上将戴林·普罗德摩尔是库尔提拉斯的统治者，也是第二次战争期间联盟海军舰队的最高指挥官。他拒绝相信兽人可以和平生活，于是航行至卡利姆多，对杜隆塔尔发动了一场灭绝战争，最终在塞拉摩陨落。",al={"海军上将是谁","戴林·普罗德摩尔的背景故事","谁发布了这些命令"}},{q="为什么库尔提拉斯的士兵仍留在提拉加德城堡？",a="当戴林·普罗德摩尔入侵杜隆塔尔时，他建立了像提拉加德城堡这样加固的沿海立足点。在他战败后，本尼迪克特中尉领导的残存军官和海军陆战队依然坚守岗位，决心继续他针对部落的战役。",al={"人类为什么在杜隆塔尔","提拉加德城堡的士兵","杜隆塔尔的库尔提拉斯人"}},{q="为什么加索克对这些命令如此担忧？",a="作为剃刀岭的军事指挥官，加索克的职责是保卫杜隆塔尔中部。发现组织严密的海军命令证明了提拉加德城堡对兽人家园构成了主动且经过计算的军事威胁，而非仅仅是无组织的落难幸存者。",al={"加索克的反应","为什么加索克关心这件事"}},{q="谁持有海军上将箱子的钥匙？",a="本尼迪克特中尉是位于提拉加德城堡二层的库尔提拉斯指挥官，他携带着打开装有旧信封的保险箱所需的钥匙。",al={"本尼迪克特之钥","谁掉落钥匙"}},{q="把命令交给加索克后会发生什么？",a="在检查了这些命令后，加索克认识到了危险：普罗德摩尔的计划在他死前就已经制定好了，而且可能会有更多波次的军队登陆杜隆塔尔海岸。他立即将命令送往奥格瑞玛，以便让大酋长的议会发出警报。",al={"海军上将的命令后续","下一个任务"}}},fp="20,262,15.398.0,19.327.1,37.156.0,27.252.0,51.244.0,48.191.0,41.146.0,49.204.0"}
P.entries["quest:831"] = {n="The Admiral's Orders",s="加索克派你将普罗德摩尔将军的命令送给奥格瑞玛的纳兹格雷尔。这些命令令人担忧，人类可能再次登陆部落的海岸。",h="加索克派你将普罗德摩尔将军的命令送给奥格瑞玛的纳兹格雷尔。这些命令令人担忧，人类可能再次登陆部落的海岸。",kw={"普罗德摩尔将军","加索克","部落","人类登陆","纳兹格雷尔","命令","奥格瑞玛","萨尔"},ang={["faction:Horde"]="作为部落的一员，你带来了一则警告；加索克认为，这关系到部落海岸的安危。"},sec={{t="给纳兹格雷尔的警告",b="杜隆塔尔的加索克担心，普罗德摩尔将军的计划仍在威胁部落。他派你带着海军上将的命令，前往奥格瑞玛萨尔的大厅交给纳兹格雷尔。"},{t="萨尔的大厅",b="纳兹格雷尔接过命令，说酋长必须立刻得知此事。他感谢你为部落尽忠效力，随后转身去向萨尔进言。"}},faq={{q="是谁派我去奥格瑞玛？",a="加索克派你从杜隆塔尔出发，将普罗德摩尔将军的命令送给纳兹格雷尔。",al={"是谁给了我这个","加索克的命令"}},{q="这些命令应该交给谁？",a="普罗德摩尔将军的命令应交给奥格瑞玛萨尔的大厅里的纳兹格雷尔。",al={"交给谁","纳兹格雷尔的命令"}},{q="为什么这些命令如此紧急？",a="加索克担心，普罗德摩尔将军的计划可能会让更多手下登陆部落的海岸。",al={"为何紧急","人类威胁"}},{q="纳兹格雷尔会如何处理这则警告？",a="纳兹格雷尔说，他必须就此事向萨尔进言。",al={"纳兹格雷尔会怎么做","向萨尔进言"}}},fp="20,145,21.167.0,19.159.1,26.82.0,30.83.0,26.89.0,38.53.0"}
P.entries["quest:8311"] = {n="耶斯帕尔的万圣节糖果！",s="在万圣节期间，一个名叫耶斯帕尔的孤儿因病躺在暴风城的孤儿院里，他渴望能参加节日庆典。由于病重无法外出，他请求联盟的冒险者代他去世界各地进行不给糖就捣蛋的活动。",h="在万圣节期间，一个名叫耶斯帕尔的孤儿因病躺在暴风城的孤儿院里，他渴望能参加节日庆典。由于病重无法外出，他请求联盟的冒险者代他去世界各地进行不给糖就捣蛋的活动。",kw={"达纳苏斯","橡皮糖","万圣节","铁炉堡","耶斯帕尔","水果糖","夜莺","杏仁糖","暴风城","塔瓦斯德","不给糖就捣蛋"},ang={["faction:Alliance"]="这项节日任务将遥远的首都联系在一起，要求英雄们从暴风城的大街，前往铁炉堡的山中大厅和达纳苏斯的树枝上，为一名孤儿带来欢乐。",["race:Gnome"]="由于他们的家园被穴居人和辐射摧毁，侏儒对节日的参与落到了铁炉堡的塔瓦斯德·基瑟尔身上，他确保了诺莫瑞根橡皮糖仍然可以被分享。"},sec={{t="一个受庇护的孩子",b="耶斯帕尔住在暴风城教堂广场的孤儿院里，这个万圣节他生病了。无法享受从艾泽拉斯各地收集糖果这种简单的童年乐趣，耶斯帕尔只能待在室内，希望路过的冒险者能分享节日精神，代他收集这些糖果。"},{t="联盟各地的糖果戏法",b="为了收集耶斯帕尔梦寐以求的节日糖果，冒险者必须前往艾尔文森林之外的远方。任务要求拜访暴风城、铁炉堡和达纳苏斯的旅店老板，以及流亡的侏儒塔瓦斯德·基瑟尔。每个成年人都要求你在交出奖品前进行表演——迫使旅行者模仿小鸡打鸣、跳舞、展示肌肉或像火车一样鸣笛，以换取暴风城杏仁糖和诺莫瑞根橡皮糖等地区特产。"}},faq={{q="耶斯帕尔是谁？",a="耶斯帕尔是住在暴风城孤儿院的一名年轻孤儿。在万圣节期间，他渴望得到节日糖果，但因病无法外出亲自收集。",al={"耶斯帕尔 暴风城","孤儿 耶斯帕尔","谁是耶斯帕尔"}},{q="为什么耶斯帕尔不能亲自去进行不给糖就捣蛋？",a="耶斯帕尔生病了，当城市其他地方都在庆祝万圣节时，他的病情使他不得不留在孤儿院里。",al={"为什么耶斯帕尔不能离开","耶斯帕尔生病了吗","耶斯帕尔 不给糖就捣蛋"}},{q="耶斯帕尔想要哪些糖果？",a="他请求四种不同的地区特产糖果：暴风城杏仁糖、铁炉堡薄荷糖、达纳苏斯水果糖和诺莫瑞根橡皮糖。",al={"耶斯帕尔 糖果","万圣节 糖果列表","耶斯帕尔 需要的糖果"}},{q="你在哪里可以获得诺莫瑞根橡皮糖？",a="由于诺莫瑞根仍然受到辐射且被占领，这种橡皮糖由目前待在铁炉堡秘法区的侏儒难民塔瓦斯德·基瑟尔分发。",al={"诺莫瑞根橡皮糖 位置","谁提供橡皮糖","塔瓦斯德 糖果"}},{q="旅店老板让你表演什么戏法？",a="旅店老板要求你表演滑稽的动作来换取糖果：在暴风城展示肌肉，在达纳苏斯跳舞，在铁炉堡模仿小鸡打鸣，并为塔瓦斯德发出火车鸣笛声。",al={"万圣节 戏法","旅店老板 戏法","糖果戏法 联盟"}},{q="耶斯帕尔会给你什么作为糖果的回报？",a="在收到四种节日糖果后，耶斯帕尔会很高兴地用他积攒的一些南瓜糖果与旅行者交换。",al={"耶斯帕尔 奖励","给耶斯帕尔的糖果 完成"}}},fx={["103fae29"]={q="耶斯帕尔为什么想要收集万圣节糖果？",a="耶斯帕尔是个患病的孤儿，只能待在暴风城孤儿院里，由护士长南丁格尔悉心照料，无法参加联盟各主城的万圣节庆典。为了像其他孩子一样感受节日，他希望尝尝各个盟友主城特有的节庆糖果，并愿意拿自己的南瓜糖果交换，好让自己不至于完全错过节日。",al={"耶斯帕尔为什么想要糖果","耶斯帕尔要糖果的动机","耶斯帕尔为什么要万圣节糖果"}},["423b280b"]={q="暴风城杏仁糖有什么用？",a="暴风城杏仁糖是当地的传统糖果，由贸易区的旅店老板在万圣节期间分发。它是耶斯帕尔托你收集的节庆糖果中代表人类王国的一种，向旅店老板展示你的力量就能得到。",al={"暴风城杏仁糖用途","暴风城杏仁糖是什么","谁想要暴风城杏仁糖"}},["37e1df8a"]={q="诺莫瑞根橡皮糖有什么用？",a="诺莫瑞根橡皮糖是一种特色糖果，由铁炉堡的塔瓦斯德·基瑟尔代表流亡侏儒分发。耶斯帕尔托你收集四种特色糖果，它就是其中之一，好让他尝遍联盟各族的节庆美味。",al={"诺莫瑞根橡皮糖用途","诺莫瑞根橡皮糖是什么","谁想要诺莫瑞根橡皮糖"}},e8e502ad={q="铁炉堡薄荷糖有什么用？",a="铁炉堡薄荷糖是矮人的特色糖果，由铁炉堡的旅店老板在这个秋季节日期间赠送。耶斯帕尔需要它来凑齐四座城市的万圣节糖果，只要活灵活现地模仿小鸡，逗旅店老板开心，就能得到。",al={"铁炉堡薄荷糖用途","铁炉堡薄荷糖是什么","谁想要铁炉堡薄荷糖"}},["61787ad3"]={q="达纳苏斯水果糖有什么用？",a="达纳苏斯水果糖是暗夜精灵的精致糖果，由达纳苏斯工匠区的旅店老板分发。有了它，就能凑齐各地的万圣节特色美食，让困在暴风城孤儿院里的耶斯帕尔如愿品尝。",al={"达纳苏斯水果糖用途","达纳苏斯水果糖是什么","谁想要达纳苏斯水果糖"}}},fp="31,175,17.236.0,37.367.0,14.135.0,46.101.0,30.117.0,43.90.0,47.135.0,50.92.0"}
P.entries["quest:8312"] = {n="斯波普斯的万圣节糖果！",s="“给斯普普的万圣节糖果！”是一个节日任务，冒险者需要替生病无法出门进行“不给糖就捣蛋”的斯普普收集节日糖果。作为回报，斯普普会提供一些神奇的糖果，食用后可以将你变身为各种滑稽又可怕的形态。你需要在各大主城的旅店老板和森金村的卡利·雷米克处收集这些糖果。",h="“给斯普普的万圣节糖果！”是一个节日任务，冒险者需要替生病无法出门进行“不给糖就捣蛋”的斯普普收集节日糖果。作为回报，斯普普会提供一些神奇的糖果，食用后可以将你变身为各种滑稽又可怕的形态。你需要在各大主城的旅店老板和森金...",kw={"糖果","万圣节","旅店老板","卡利·雷米克","森金村","斯普普","不给糖就捣蛋"},ang={["faction:Horde"]="这个任务让部落冒险者们为了一个生病的孩子，在各大主城以及森金村的暗矛巨魔聚落进行“不给糖就捣蛋”的活动。",["race:Troll"]="杜隆塔尔的暗矛巨魔也参与了庆祝活动，卡利·雷米克就在森金村分发节日糖果。"},sec={{t="卧床的节日",b="万圣节带来了庆祝、恶作剧和遍布各地的节日糖果，但并不是每个人都能参与户外的欢庆活动。当世界各地沉浸在节日的狂欢中时，斯普普却因病被困在室内。无法出门走动，斯普普便委托过往的旅行者代为收集糖果，并以一袋奇特的变形糖果作为回报。"},{t="遍布各地的“不给糖就捣蛋”",b="想要收集糖果，需要走遍各地的定居点。各大主城的旅店老板都存有节日糖果，但他们会要求访客在交出糖果前先展示一下节日精神，表演一些戏法。除了繁华的主城旅店，这一传统也延伸到了杜隆塔尔的海岸，那里的森金村的卡利·雷米克也会为前往那里的旅行者分发糖果。"}},faq={{q="谁是斯普普？",a="斯普普是一个生病的孩子，无法在万圣节期间出门进行“不给糖就捣蛋”。为了能参与这个节日，斯普普请求旅行者代为向世界各地的旅店老板和商贩收集节日糖果。",al={"谁是斯普普","斯普普","斯普普是什么人"}},{q="为什么斯普普不能去“不给糖就捣蛋”？",a="斯普普身体不适，病得太重，无法外出庆祝万圣节。由于疾病使他卧床不起，他只能依靠热心的冒险者去拜访各地的旅店老板，收集节日糖果。",al={"为什么斯普普不能去不给糖就捣蛋","为什么斯普普要待在家里","斯普普生病"}},{q="斯普普会交换什么糖果？",a="作为从旅店老板那里收集到的节日糖果的回报，斯普普承诺提供具有神奇变形效果的特殊糖果。食用它们可以将你变成各种既滑稽又可怕的生物和形态。",al={"斯普普给什么糖果","斯普普的糖果奖励","特殊糖果"}},{q="去哪里找给斯普普的糖果？",a="节日糖果由分布在各个主城的旅店老板发放，他们会要求旅行者表演戏法来交换糖果。除了城市旅店外，杜隆塔尔森金村的巨魔卡利·雷米克也会分发节日糖果。",al={"去哪里拿糖果","谁给糖果","糖果位置"}},{q="谁是卡利·雷米克？",a="卡利·雷米克是居住在杜隆塔尔森金村的一名巨魔，他通过向到访的欢乐旅行者发放节日糖果来参与万圣节活动。",al={"谁是卡利·雷米克","卡利·雷米克糖果","森金村糖果"}},{q="为什么旅店老板会要求表演戏法？",a="万圣节期间，主要定居点的旅店老板会要求访客通过表演各种滑稽的戏法或动作来展示他们的节日精神，然后才会分享他们的节日糖果。",al={"旅店老板想要什么","旅店老板戏法","如何获得旅店老板的糖果"}}},fp="31,209,19.201.0,34.230.0,14.198.0,38.150.0,41.130.0,40.137.0,18.128.0,33.153.0"}
P.entries["quest:832"] = {n="燃影之眼",s="这个神秘的炽光坠饰是在骷髅石深处从火刃氏族邪教徒加祖兹身上收缴的，它不断在持有者的脑海中低语着紧急警告。那个声音特别提到要让奥格瑞玛的兽人术士尼尔鲁·火刃去惩罚加祖兹。",h="这个神秘的炽光坠饰是在骷髅石深处从火刃氏族邪教徒加祖兹身上收缴的，它不断在持有者的脑海中低语着紧急警告。那个声音特别提到要让奥格瑞玛的兽人术士尼尔鲁·火刃去惩罚加祖兹。",kw={"火刃氏族","灼热之影","暗影裂口","杜隆塔尔","燃影之眼","加祖兹","尼尔鲁·火刃","奥格瑞玛","骷髅石"},ang={["class:Warlock"]="对于在暗影裂口中修行的术士来说，看到另一个修行者的名字被火刃氏族引用，这严酷地提醒着人们：国家准许的邪能研究与公开叛国之间的界限是多么薄弱。",["faction:Horde"]="在首都大门外发现邪教徒之间的低语，揭示了旧部落的恶魔腐化仍然在离杜隆塔尔中心非常近的地方令人不安地滋生着。",["race:Orc"]="与萨尔并肩作战净化燃烧军团腐化的兽人们，将火刃氏族在杜隆塔尔的存在视为对他们新家园不可容忍的亵渎。"},sec={{t="石中的声音",b="在骷髅石深处击杀加祖兹后，从他的遗骸中可以拾取到一个名为“燃影之眼”的不祥坠饰。这颗石头并非只是一个惰性的魔法饰品，它还会通过心灵感应发出震动。任何持有它的人都能直接听到一个严厉的声音在脑海中响起，向加祖兹索要报告，并警告他，他在奥格瑞玛以东的秘密行动已经暴露了。"},{t="奇怪的威胁",b="任何忠诚的部落侦察兵都会被这个声音发出的孤注一掷的最后通牒所震惊：如果不回应，尼尔鲁·火刃就会接到通知，以迅猛且残暴的手段猎杀加祖兹。尼尔鲁·火刃公开居住在奥格瑞玛的暗影裂口中，表面上是在萨尔的严格监督下研习黑暗魔法。将这个护身符交给尼尔鲁，他会表现出假装的惊讶和好奇，并对自己的名字被当作恐吓邪教徒的“鬼怪”而感到诧异。"}},faq={{q="什么是燃影之眼？",a="燃影之眼是火刃氏族首领加祖兹在骷髅石内掉落的一枚附魔坠饰。它充当了邪教特工与其幕后神秘主人之间的双向心灵感应中继器。",al={"燃影之眼","这个坠饰是什么","加祖兹之眼"}},{q="谁在通过坠饰说话？",a="暗影议会或火刃氏族内部的一位身份不明的上级正试图联系加祖兹，但他并不知道这个邪教徒已经在骷髅石被杀死了。",al={"谁在和我说话","坠饰里的声音","谁在通过眼睛说话"}},{q="为什么那个声音要用尼尔鲁·火刃来威胁加祖兹？",a="那个声音声称，如果加祖兹不提交报告，尼尔鲁·火刃就会以残酷的手段对他进行惩罚。尼尔鲁本人表示，他确实以猎杀大酋长的敌人而闻名，但他觉得因为自己的名字被单独点出来而感到奇怪。",al={"为什么要提到尼尔鲁","尼尔鲁·火刃的威胁","尼尔鲁的联系"}},{q="我应该把燃影之眼交给谁？",a="把坠饰带给尼尔鲁·火刃，他就在奥格瑞玛的暗影裂口深处，盘旋在坩埚和书籍旁边。",al={"灼热之影任务去哪里交","尼尔鲁·火刃在哪里"}},{q="尼尔鲁·火刃在收到燃影之眼时有什么反应？",a="尼尔鲁对那个声音点出他的名字感到十分好奇，更让他觉得奇怪的是，火刃氏族的邪教徒名字竟然与他如此相近。他留下了坠饰，打算对其进行研究，并思考其中传达的信息含义。",al={"尼尔鲁的反应","尼尔鲁说了什么"}},{q="加祖兹在哪里？",a="加祖兹潜伏在骷髅石的最深处，那是一个隐藏在杜隆塔尔东海岸岩壁中的洞穴，就在奥格瑞玛以东。",al={"加祖兹在哪里","加祖兹的位置","骷髅石首领"}}},fx={["286b7c01"]={q="燃影之眼中的声音为什么想要一份报告？",a="在吊坠中低语的声音正试图联系骷髅石的火刃氏族首领加兹乌兹。邪教高层已获悉他们的隐秘据点被部落发现，这位隐秘的指挥官急于召集加兹乌兹做好防御准备，以免他们的立足之地在不可避免的进攻中被摧毁。",al={"吊坠为什么会说话","燃影之眼为什么要报告","燃影之眼中的声音有何目的"}}},fp="15,139,20.260.0,16.347.1,34.212.0,36.152.0,57.213.0,42.109.0,50.205.1,25.137.0"}
P.entries["quest:833"] = {n="神圣的墓地",s="“神圣的安葬”是由博学者诺拉·暴雨图腾委托的一项任务，要求部落的冒险者们保护位于莫高雷东部的赤色石。这片神圣的先祖埋骨地正遭受刺鬃野猪人的劫掠，这些野猪人正在亵渎受人尊敬的牛头人战士的坟墓。驱逐这些闯入者，将为那些为了建立和保卫雷霆崖而献出生命的先烈恢复荣耀与安宁。",h="“神圣的安葬”是由博学者诺拉·暴雨图腾委托的一项任务，要求部落的冒险者们保护位于莫高雷东部的赤色石。这片神圣的先祖埋骨地正遭受刺鬃野猪人的劫掠，这些野猪人正在亵渎受人尊敬的牛头人战士的坟墓。驱逐这些闯入者，将为那些为了建...",kw={"神圣的安葬","先祖","刺鬃闯入者","博学者诺拉·暴雨图腾","莫高雷","野猪人","赤色石","雷霆崖"},ang={["class:Shaman"]="对圣地的亵渎惊扰了受尊崇先祖的灵魂，因此你必须介入以恢复大地的平衡。",["faction:Horde"]="协助牛头人长者守卫他们的神圣遗迹，巩固了部落与盟友共同保卫莫高雷的誓约。",["race:Tauren"]="保卫赤色石是一项深重的先祖荣耀，确保那些为你们族人的统一家园做出贡献的战士们能够不受干扰地安息。"},sec={{t="舒哈鲁的圣地",b="赤色石是整个莫高雷最受尊崇的圣地之一。它坐落在东部山脉下方的岩架中，是专门为最英勇的牛头人预留的最后安息之所。安葬在这里的英雄们都是传说中的战士，他们曾为保护族群、支持酋长以及在雷霆崖的高原上开辟永久家园而浴血奋战。对于舒哈鲁人来说，打扰他们的安息不仅是对传统的冒犯，更是对大地母亲本人的亵渎。"},{t="刺鬃氏族的亵渎",b="游牧的刺鬃氏族野猪人一直以来都在挑战牛头人对卡利姆多中部地区的控制，但他们最近向赤色石的推进标志着事态的严重升级。成群的刺鬃闯入者已经潜入了这片圣地，蹂躏大地并扰动安息之所。由于守护者博学者诺拉·暴雨图腾年事已高，无法独自一人驱逐入侵者，部落的年轻勇士们必须拿起武器，清除此地的闯入者，保卫那些受尊崇的逝者。"}},faq={{q="什么是赤色石？",a="赤色石是一处神圣的先祖墓地，位于莫高雷的东部山脉沿线。它专门为最英勇的牛头人战士预留，特别是那些为了保卫族群和建立雷霆崖而牺牲的战士。",al={"赤色石在哪里","莫高雷赤色石","牛头人墓地"}},{q="博学者诺拉·暴雨图腾是谁？",a="博学者诺拉·暴雨图腾是一位年长的牛头人，负责照料和守护神圣的赤色石。他意识到自己已过壮年，无法凭一己之力抵御入侵的刺鬃野猪人，因此他呼唤有能力的冒险者前来保卫逝者。",al={"暴雨图腾","博学者诺拉·暴雨图腾","谁发布神圣的安葬任务"}},{q="为什么刺鬃野猪人会出现在赤色石？",a="刺鬃氏族不断向莫高雷和贫瘠之地的牛头人领地施压。由于对领土和资源的渴望，成群的闯入者闯进了赤色石的岩架，在此过程中亵渎了坟墓。",al={"为什么野猪人在赤色石","刺鬃闯入者","野猪人入侵"}},{q="为什么这种亵渎行为对牛头人来说如此不可原谅？",a="牛头人文化极其推崇对先祖的敬意，并主张与逝者的灵魂和谐共存。任由野蛮的野猪人践踏大地，惊扰那些为雷霆崖献身的英雄们的骸骨，是对精神层面的极大侮辱。",al={"牛头人丧葬习俗","牛头人为何重视墓地"}},{q="这个任务接下来会导向哪里？",a="“神圣的安葬”是一项由博学者诺拉·暴雨图腾提供的独立防御任务。一旦刺鬃闯入者被解决，眼前的亵渎行为便会停止。",al={"神圣的安葬后续","神圣的安葬之后是什么"}},{q="谁被安葬在赤色石？",a="此地是为那些为了种族生存和酋长荣耀而战的牛头人勇士所预留的，尤其是那些因他们的牺牲才使得雷霆崖得以建立和保卫的英雄们。",al={"谁被埋葬在这里","赤色石坟墓"}}},fx={e11b84bd={q="博学者诺拉·暴雨图腾为什么请你帮忙，而不自己赶走他们？",a="博学者诺拉·暴雨图腾是一位长者，年事已高，早已不复当年，无法拿起武器对抗凶暴的战团。他的职责是照料并尊崇赤色石的灵魂，而非在前线作战，因此只能依靠你这样的能干旅人，去承担驱逐刺背入侵者的危险任务。",al={"诺拉·暴雨图腾为什么不能自己处理","诺拉·暴雨图腾为什么需要帮忙","诺拉·暴雨图腾为什么不战斗"}}},fp="15,241,31.385.0,27.398.0,18.206.0,28.186.0,46.201.0,51.200.0,32.154.0,27.180.0"}
P.entries["quest:834"] = {n="沙漠之风",s="雷兹拉克是加兹鲁维手下的一名承包工程师，他急需帮助来找回被杜隆塔尔的鹰身人偷走的建筑材料。一队开往奥格瑞玛的商队在烈风峡谷遭到伏击，货物被散落在悬崖各处。",h="雷兹拉克是加兹鲁维手下的一名承包工程师，他急需帮助来找回被杜隆塔尔的鹰身人偷走的建筑材料。一队开往奥格瑞玛的商队在烈风峡谷遭到伏击，货物被散落在悬崖各处。",kw={"商队","杜隆塔尔","尘风鹰身人","加兹鲁维","奥格瑞玛","棘齿城","烈风峡谷","雷兹拉克","物资"},ang={["faction:Horde"]="每一批在峡谷中损失的货物都威胁着部落在杜隆塔尔的据点的快速扩张和防御加固。",["profession:Engineering"]="雷兹拉克代表了热砂港工程师务实的精明，他们更关心的是让蓝图和交付如期进行，而不是当地的野外麻烦。",["race:Orc"]="兽人依靠地精的专业知识和外来物资，将杜隆塔尔贫瘠干燥的土地变成了防御稳固的家园。"},sec={{t="有期限的地精",b="雷兹拉克是由棘齿城的总工程师加兹鲁维直接派遣的，旨在协助部落在杜隆塔尔进行庞大的建筑工程。在贫瘠严酷的地形上修建防御工事本身就已经困难重重，如果再加上后勤灾难，情况就更糟了，但雷兹拉克的货物总是在运抵工地前就消失不见。没有了必要的货物，所有工作都陷入了停滞，这让这位脾气暴躁的地精主管陷入了无米下锅的窘境。"},{t="峡谷伏击",b="雷兹拉克原本期待的一批重要物资在烈风峡谷被尘风鹰身人拦截了。这些长着翅膀的食腐动物在剃刀岭和奥格瑞玛之间的道路两侧高耸的峡谷缝隙中筑巢，并会俯冲袭击毫无防备的货车。鹰身人们并没有吃掉或毁坏货物，而是将这些板条箱和麻袋囤积在巢穴周围，这使得任何有勇气杀入它们领地的人都可以完好地找回这些物资。"}},faq={{q="雷兹拉克是谁？",a="雷兹拉克是一名地精工人，受雇于棘齿城的头目加兹鲁维。加兹鲁维派他前往杜隆塔尔，协助兽人在奥格瑞玛大门外进行持续的建设工作。",al={"雷兹拉克","雷兹拉克是谁","谁给的任务"}},{q="为什么地精要帮助在杜隆塔尔进行建设？",a="加兹鲁维和热砂港与萨尔大酋长之间有着长期的商业和工程合作关系。地精工程师和机器帮助打下了奥格瑞玛的基石，而加兹鲁维也继续为部落提供承包劳动力和材料。",al={"为什么地精帮助兽人","加兹鲁维 杜隆塔尔","地精与部落合作"}},{q="物资从哪里来？",a="雷兹拉克并没有说明这些物资的来源。他只说是为了协助他在杜隆塔尔为兽人工作而运送的货物。",al={"物资来源","商队来源"}},{q="鹰身人在杜隆塔尔做什么？",a="尘风鹰身人是一种好斗的掠夺性食腐生物，它们盘踞在杜隆塔尔中部的悬崖和峡谷中。它们骚扰过往的旅行者，抢劫穿过烈风峡谷的贸易路线，并搜集任何发光或有用的东西来装饰巢穴。",al={"为什么杜隆塔尔有鹰身人","尘风鹰身人背景故事","烈风峡谷鹰身人"}},{q="烈风峡谷在哪里？",a="烈风峡谷直接从连接奥格瑞玛和剃刀岭的主要南部峡谷分支出来。峡谷切割了东侧和西侧的悬崖壁，形成了高耸的栖息地，尘风鹰身人就将偷来的货物藏在那里。",al={"烈风峡谷位置","在哪里寻找物资","补给袋位置"}},{q="为什么兽人守卫没有保护商队？",a="雷兹拉克说商队一直难以保持安全，并且这批货物原本承诺过会顺利送达。他没有解释随行了什么样的护卫，也没有解释为什么其防御在尘风鹰身人面前失败了。",al={"商队为什么失败","杜隆塔尔安全","兽人商队"}}},fp="19,156,22.315.0,20.349.0,14.145.0,41.237.0,33.129.0,38.220.0,34.190.0,46.182.0"}
P.entries["quest:835"] = {n="保卫商路",s="“维护补给线”是雷兹拉克在烈风峡谷附近发布的一项任务，旨在保护途经杜隆塔尔的重要地精补给路线。盘踞在枯水谷的鹰身人不断拦截并洗劫补给商队，这让这位地精感到十分恼火，于是雇佣人手来清理它们。",h="“维护补给线”是雷兹拉克在烈风峡谷附近发布的一项任务，旨在保护途经杜隆塔尔的重要地精补给路线。盘踞在枯水谷的鹰身人不断拦截并洗劫补给商队，这让这位地精感到十分恼火，于是雇佣人手来清理它们。",kw={"枯水谷","尘风野蛮人","尘风风暴女巫","加兹鲁维","棘齿城","烈风峡谷","雷兹拉克","维护补给线"},ang={["faction:Horde"]="清除烈风峡谷东部的鹰身人威胁，有助于维持杜隆塔尔前哨站与沿海贸易枢纽之间货物和增援的流动。",["profession:Engineering"]="守护雷兹拉克的货物能确保尖端地精组件从棘齿城源源不断地运送到当地工匠手中。"},sec={{t="鹰身人肆虐的路线",b="杜隆塔尔干旱的峡谷本身就已经够恶劣了，更不用说还有那些会俯冲袭击毫无防备的旅行者的凶猛鹰身人。地精雷兹拉克代表他的老板加兹鲁维负责监管区域内的补给作业。不幸的是，居住在枯水谷的尘风鹰身人将烈风峡谷变成了一处险地，它们经常袭击商队，在货物运抵目的地之前就将其掠夺一空。"},{t="生意与杀戮",b="雷兹拉克的座右铭是：只要出得起价，没有办不成的事。与其亲自进入峡谷，他更愿意雇佣冒险者来消灭尘风野蛮人和尘风风暴女巫，从而摧毁它们的巢穴。清除这些鹰身人可以保持贸易通道畅通，确保工程小玩意的补给安全，并为热心的旅行者指明前往棘齿城获取更多机遇的道路。"}},faq={{q="雷兹拉克为谁效力？",a="雷兹拉克为加兹鲁维效力，加兹鲁维是中立地精港口城镇棘齿城的首席工程师兼镇长。加兹鲁维监管着杜隆塔尔和贫瘠之地各地的大量商业与基础设施项目。",al={"雷兹拉克的上司","雷兹拉克为谁工作","雷兹拉克的雇主"}},{q="为什么鹰身人要袭击商队？",a="尘风鹰身人在枯水谷建立了庞大的巢穴，而枯水谷正好直接横跨烈风峡谷的主要交通路线。它们会疯狂攻击任何入侵者，并洗劫过往的货车和货物。",al={"鹰身人为什么袭击","尘风鹰身人的动机","为什么是枯水谷"}},{q="枯水谷位于哪里？",a="枯水谷位于杜隆塔尔北部烈风峡谷的深处，在干旱的赤色丘陵中开凿而成。",al={"枯水谷的位置","枯水谷在哪里","如何找到枯水谷"}},{q="帮助雷兹拉克之后会发生什么？",a="随着尘风鹰身人被肃清，补给路线也变得安全了。雷兹拉克会建议冒险者前往边界另一侧贫瘠之地的棘齿城，寻找加兹鲁维以获得更多有利可图的合同。",al={"维护补给线之后","雷兹拉克的后续任务","雷兹拉克任务之后做什么"}},{q="为什么是地精而不是部落来对付这些鹰身人？",a="虽然部落在杜隆塔尔设有哨所，但他们的资源很有限，还要忙于应对半人马、野猪人和定居点内部的需求。像雷兹拉克这样的地精商人通常认为，直接雇佣独立的冒险者来保护他们的私人企业既快捷又划算。",al={"为什么地精会雇人","为什么奥格瑞玛不处理此事","部落与鹰身人"}},{q="枯水谷里有哪些种类的鹰身人？",a="这里的巢穴主要由进行近战攻击的尘风野蛮人，以及能操控风暴与闪电攻击过往商队的尘风风暴女巫组成。",al={"鹰身人类型","尘风鹰身人类型","枯水谷的敌人"}}},fp="18,182,26.278.0,22.363.0,26.191.0,39.168.0,33.125.0,34.209.0,60.259.0,48.172.0"}
P.entries["quest:8353"] = {n="学小鸡，换糖果",s="“学鸡叫换薄荷糖”是万圣节期间在铁炉堡提供的一个轻松愉快的联盟节日任务。为了替年幼的孤儿耶斯帕尔换取传统的铁炉堡薄荷糖，冒险者们必须放下久经沙场的尊严，在酒馆里像小鸡一样拍打双臂并咯咯叫，以此博取大家一乐。旅店老板洛雷·火酒非常乐意奖励那些愿意放下身段，为孩子带去节日欢乐的人。",h="“学鸡叫换薄荷糖”是万圣节期间在铁炉堡提供的一个轻松愉快的联盟节日任务。为了替年幼的孤儿耶斯帕尔换取传统的铁炉堡薄荷糖，冒险者们必须放下久经沙场的尊严，在酒馆里像小鸡一样拍打双臂并咯咯叫，以此博取大家一乐。旅店老板洛雷·...",kw={"小鸡","咯咯叫","火酒","万圣节","旅店老板","铁炉堡薄荷糖","耶斯帕尔","糖果"},ang={["faction:Alliance"]="这个季节性的差事突显了联盟各主城之间的情谊，将铁炉堡的矮人好客之道与为暴风城的孤儿带去欢乐直接联系了起来。",["race:Dwarf"]="矮人们欣赏幽默、豪饮和节日传统，火酒的要求表明，没有哪个铁炉堡的顾客会把自己看得太过严肃。"},sec={{t="万圣节的传统",b="在万圣节期间，艾泽拉斯各地都沉浸在节日的喜悦中，人们通过变装狂欢和享用节日美食，庆祝丰收与冬季之间的这段时光。虽然经验丰富的英雄通常觉得自己年纪太大，不适合挨家挨户讨要糖果，但病重或孤儿的困境提供了一个体面的借口。在暴风城，年幼的耶斯帕尔渴望着节日糖果，这促使前往各地的联盟勇士们从联盟各主城的旅店老板那里收集具有代表性的地方特产。"},{t="旅店老板洛雷·火酒的条件",b="在铁炉堡热闹非凡的酒馆柜台后面，站着旅店老板洛雷·火酒，他正是著名的铁炉堡薄荷糖的守护者。火酒可不是那种轻易就会让冒险者如愿的人，他拒绝直接交出糖果。他坚持要一点“娱乐表演”，要求身经百战的战士和深沉冷静的施法者在拿到奖品前，必须像农家禽类一样拍打翅膀并咯咯叫。这一切都是为了节日欢乐，也让酒馆的客人们能以英雄的滑稽表现为乐。"}},faq={{q="为什么旅店老板洛雷·火酒要我学鸡叫？",a="旅店老板洛雷·火酒正在融入万圣节那爱玩的节日精神。由于久经沙场的冒险者们年纪太大，没法像小孩子那样去不给糖就捣蛋，他便要求用一段滑稽的“捣蛋”来换取糖果。他认为看一位强大的勇士拍打双臂并学鸡叫是一种不错的酒馆娱乐，于是便愉快地用一份铁炉堡薄荷糖来换取这小小的公众出丑。",al={"为什么要学鸡叫","火酒要我学鸡叫的原因","为什么我必须学鸡叫"}},{q="耶斯帕尔是谁，我为什么要为他弄薄荷糖？",a="耶斯帕尔是一位住在暴风城的患病孤儿，他自己无法参与城里的万圣节庆典。为了让他开心，联盟冒险者们要在世界各地奔波，从联盟的各个主要城市收集四种特殊的节日糖果，其中包括来自丹莫罗的爽脆的铁炉堡薄荷糖。",al={"耶斯帕尔是谁","为什么获取薄荷糖","耶斯帕尔 孤儿"}},{q="这个任务在万圣节假期中处于什么位置？",a="这个任务是与大型季节性任务“万圣节的礼物，给耶斯帕尔的糖果！”相关的四个地区性任务之一，除此之外还有来自暴风城和达纳苏斯的旅店老板，以及铁炉堡的塔瓦斯德·基瑟尔的任务。他们在交出各自城市的招牌糖果前，都要求冒险者进行特定的羞耻或戏剧性的表情动作。",al={"万圣节任务线","耶斯帕尔 糖果任务线","任务顺序"}},{q="我在哪里可以找到旅店老板洛雷·火酒？",a="旅店老板洛雷·火酒驻守在铁炉堡平民区石火旅店内部的吧台后面，在这个矮人主城的核心地带为游客提供饮品和住宿。",al={"火酒在哪里","火酒位置","铁炉堡旅店老板"}},{q="学鸡叫能得到什么奖励？",a="在完成学鸡叫后，旅店老板洛雷·火酒会交给你一份铁炉堡薄荷糖，这是一种活动限定的节日糖果，需要带回暴风城以凑齐耶斯帕尔的万圣节糖果礼盒。",al={"任务奖励","什么是薄荷糖","铁炉堡薄荷糖"}},{q="部落玩家可以完成这个任务吗？",a="不能，这个任务是联盟专属的。部落冒险者有他们自己的对应任务，孤儿斯波普斯会派遣勇士前往各个部落主城，从奥格瑞玛、幽暗城和雷霆崖的旅店老板那里收集糖果。",al={"这是联盟专属吗","部落的学鸡叫任务","部落可以做这个吗"}}},fp="27,193,24.246.0,26.296.0,60.230.0,49.232.0,56.254.0,36.124.0,31.127.0,37.160.0"}
P.entries["quest:8354"] = {n="学小鸡，换糖果",s="在万圣节的节日期间，幽暗城的旅店老板诺曼会向帮助生病儿童的旅行者提供糖果。为了获得幽暗城薄荷糖，冒险者们必须放下尊严，像只小鸡一样扑腾。",h="在万圣节的节日期间，幽暗城的旅店老板诺曼会向帮助生病儿童的旅行者提供糖果。为了获得幽暗城薄荷糖，冒险者们必须放下尊严，像只小鸡一样扑腾。",kw={"小鸡","咯咯叫","万圣节","旅店老板诺曼","斯波普斯","贸易区","幽暗城","幽暗城薄荷糖"},ang={["faction:Horde"]="在万圣节期间，部落的冒险者们会奔波于各个主城之间，在每一处都忍受愚蠢的屈辱，只为给一个孤儿带去快乐。",["race:Undead"]="在幽暗城腐烂的大厅里找到这种愚蠢的幽默感是很少见的，这使得诺曼的节日要求成为日常死灵实用主义中一种奇异的调剂。"},sec={{t="难得的欢乐",b="幽暗城因其是被遗忘者在洛丹伦废墟之下建立的，所以很少有人会将它与欢笑或温暖联系起来。然而，当万圣节到来时，即使是贸易区阴沉的居民们也会加入到节日的狂欢中。旅店老板诺曼手里有一批幽暗城薄荷糖，是专门留给那些为了帮助生病孤儿斯波普斯收集糖果的人准备的，那个孩子需要节日的快乐。"},{t="赢得糖果",b="诺曼并没有直接把糖果交给经验丰富的冒险者，而是要求他们进行一点令人尴尬的表演。他认为成年的战士和施法者应该靠自己的努力赢得糖果，因此，在请愿者在他的柜台前模仿农场里的鸡之前，他拒绝交出薄荷糖。"}},faq={{q="为什么旅店老板诺曼要我像小鸡一样咯咯叫？",a="旅店老板诺曼认为，成熟的勇士如果想讨糖果，就必须先表演一番。为了活跃万圣节的气氛，他要求在交出节日糖果之前，冒险者必须先进行一场滑稽的表演——像小鸡一样扑腾翅膀并咯咯叫。",al={"为什么要做小鸡表情","为什么诺曼要我咯咯叫","诺曼小鸡舞"}},{q="这份糖果是给谁的？",a="幽暗城薄荷糖是为斯波普斯收集的，他是一名在奥格瑞玛休养的生病孤儿，无法在万圣节期间亲自去讨糖果。",al={"谁会得到薄荷糖","薄荷糖是做什么用的","为什么要获取幽暗城薄荷糖"}},{q="旅店老板诺曼在哪里？",a="旅店老板诺曼经营着幽暗城贸易区内的中央旅店，为被遗忘者顾客和来访的部落旅行者提供服务。",al={"诺曼的位置","幽暗城旅店老板在哪里"}},{q="这是一个节日任务吗？",a="是的。这个任务是艾泽拉斯部落和联盟共同庆祝的年度万圣节庆典的一部分。",al={"这是万圣节吗","这个任务何时可用"}},{q="被遗忘者通常会庆祝万圣节吗？",a="被遗忘者非常热情地庆祝万圣节，他们在洛丹伦废墟外焚烧一个巨大的柳条人，以纪念他们的解放并与他们曾经的凡人生活彻底决裂。",al={"被遗忘者的万圣节","亡灵节日"}},{q="拿到幽暗城薄荷糖后会怎样？",a="薄荷糖会与从部落各个种族主城收集来的其他招牌糖果组合在一起，为年幼的斯波普斯拼凑出一份完整的节日礼物。",al={"下一个任务","我该如何处理薄荷糖"}}},fp="27,181,19.303.0,17.222.0,58.201.0,30.121.0,34.130.0,34.105.0,44.183.0,46.129.0"}
P.entries["quest:8355"] = {n="学火车，换糖果",s="“橡皮糖来了”是万圣节期间在铁炉堡接到的一项节日任务，任务发布者是侏儒工匠塔瓦斯德·基瑟尔。为了给暴风城的一名生病儿童获取节日糖果，冒险者必须先为这位乐在其中的侏儒表演一段有趣的火车模仿秀。",h="“橡皮糖来了”是万圣节期间在铁炉堡接到的一项节日任务，任务发布者是侏儒工匠塔瓦斯德·基瑟尔。为了给暴风城的一名生病儿童获取节日糖果，冒险者必须先为这位乐在其中的侏儒表演一段有趣的火车模仿秀。",kw={"诺莫瑞根橡皮糖","万圣节","橡皮糖来了","铁炉堡","耶斯帕尔","塔瓦斯德·基瑟尔","侏儒区","火车表情动作"},ang={["faction:Alliance"]="寻找节日橡皮糖的过程会促使联盟英雄们奔波于各个王国之间，以确保暴风城的一名患病儿童也能分享节日的快乐。",["race:Gnome"]="对于侏儒区的流亡侏儒来说，在万圣节期间提供诺莫瑞根橡皮糖是对家园和机械独创性的一种欢快的提醒，即便他们正流离失所。"},sec={{t="异想天开的代价",b="在万圣节的秋季庆典期间，不给糖就捣蛋的人们会搜寻联盟的各大据点，收集各具特色的地区糖果。在铁炉堡的秘法区，侏儒塔瓦斯德·基瑟尔手中就有令人垂涎的诺莫瑞根橡皮糖。虽然他也很同情那位渴望糖果的孤儿，但塔瓦斯德坚持要维护万圣节的恶作剧精神，在交出糖果前，他要求任何寻求施舍的人模仿火车的鸣笛声。"},{t="节日善举",b="该任务是一项宏大的季节性事业的一部分，旨在为暴风城的孤儿院里一位名叫耶斯帕尔的患病孤儿带来欢乐。耶斯帕尔渴望得到联盟领地各处的四种特产糖果：暴风城的牛轧糖、铁炉堡的薄荷糖、达纳苏斯的杏仁糖和诺莫瑞根的橡皮糖。通过模仿呼啸的火车头来取悦塔瓦斯德，勇士们可以获得这种侏儒糖果，以满足这位小男孩的节日愿望。"}},faq={{q="我需要做什么才能完成“橡皮糖来了”？",a="你必须选中塔瓦斯德·基瑟尔并对他使用火车表情动作，以此为他表演一段火车模仿秀。一旦他听到了火车的鸣笛声，就会乐意交出诺莫瑞根橡皮糖。",al={"如何完成橡皮糖来了","橡皮糖来了任务目标","塔瓦斯德的橡皮糖恶作剧"}},{q="塔瓦斯德·基瑟尔是谁？",a="塔瓦斯德·基瑟尔是一位来自诺莫瑞根的侏儒珠宝匠，现居于矮人山城铁炉堡的秘法区。在万圣节期间，他担任诺莫瑞根招牌橡皮糖的联盟经销商。",al={"塔瓦斯德是谁","塔瓦斯德·基瑟尔背景故事"}},{q="诺莫瑞根橡皮糖有什么用？",a="诺莫瑞根橡皮糖是为满足暴风城孤儿院里患病孤儿耶斯帕尔的万圣节请求而收集的四种节日糖果之一。",al={"诺莫瑞根橡皮糖用途","橡皮糖是干什么用的"}},{q="在哪里可以找到塔瓦斯德·基瑟尔？",a="你可以在铁炉堡的秘法区找到塔瓦斯德。",al={"塔瓦斯德在哪里","塔瓦斯德位置"}},{q="为什么塔瓦斯德要让人模仿火车？",a="万圣节植根于“不给糖就捣蛋”的传统。塔瓦斯德调皮地要求对方进行一个小小的无伤大雅的恶作剧——模仿火车头——才会愿意交出他的节日糖果。",al={"为什么是火车鸣笛","为什么要为塔瓦斯德表演火车"}},{q="这个任务全年都可以做吗？",a="不，该任务仅在每年秋季的万圣节期间开放。",al={"可以随时做橡皮糖来了吗","这是季节性任务吗"}}},fp="16,150,16.308.0,15.323.0,50.116.0,26.176.0,40.135.0,38.61.0,42.143.0,35.75.0"}
P.entries["quest:8356"] = {n="显肌肉，换糖果",s="在万圣节的秋季庆典期间，造访暴风城的冒险者们可以帮助当地的孤儿收集节日糖果。想要从闪金镇旅店的旅店老板奥里森那里获得一块暴风城杏仁糖，访客们必须配合地展示一下强健的肌肉，博得老板一笑，她才会交出糖果。",h="在万圣节的秋季庆典期间，造访暴风城的冒险者们可以帮助当地的孤儿收集节日糖果。想要从闪金镇旅店的旅店老板奥里森那里获得一块暴风城杏仁糖，访客们必须配合地展示一下强健的肌肉，博得老板一笑，她才会交出糖果。",kw={"为了杏仁糖展示肌肉","闪金镇","万圣节","旅店老板奥里森","耶斯帕尔","暴风城","暴风城杏仁糖","不给糖就捣蛋"},ang={["class:Warrior"]="对于习惯了血腥战场的强壮战士来说，在旅店老板的要求下展示手臂肌肉，虽然有些不够庄重，却是一种无伤大雅的力量展示。",["faction:Alliance"]="这种有趣的互动突显了暴风城在万圣节等节日期间蓬勃发展的轻松社区精神，让市民和四处漂泊的英雄们聚在一起开怀大笑。",["race:Human"]="对于暴风城的人类来说，宠溺孩子并用恶作剧交换糖果是一项珍贵的节日习俗，它让人们从王国面临的黑暗危机中得到片刻解脱。"},sec={{t="万圣节的传统",b="万圣节为暴风城的街道带来了一种难得的轻松氛围。虽然这个节日有着古老的渊源，象征着季节更替和驱除黑暗幽灵，但平民百姓还是通过化装、狂欢和不给糖就捣蛋来庆祝它。联盟各地的旅店老板们都会参与进来，发放传统的糖果，前提是寻求节日乐趣的人们愿意表演一个无伤大雅的恶作剧来换取糖果。"},{t="取悦旅店老板",b="在热闹的商业区的闪金镇旅店里，旅店老板奥里森坚持不让任何人免费得到节日糖果——即使他们是在为像耶斯帕尔这样的孤儿跑腿。奥里森会观察冒险者身上穿的装备或服饰，打趣地评价一番他们的身材，并坚持让他们展示肌肉以供消遣。只有当冒险者展示过力量后，她才会奖励他们一块耐嚼的暴风城杏仁糖。"}},faq={{q="为什么旅店老板奥里森要让人们展示肌肉？",a="万圣节的核心就是不给糖就捣蛋的传统。因为冒险者是代表一位寻求糖果的孤儿前来的，旅店老板奥里森坚持让他们用一个有趣的恶作剧来换取糖果——也就是展示他们的肌肉。",al={"为什么为了杏仁糖展示肌肉","奥里森想要什么","为什么要做展示肌肉的表情"}},{q="这个任务是在哪里进行的？",a="这个请求是在位于暴风城商业区中心的闪金镇旅店里提出并完成的，旅店老板奥里森就在那里照看酒馆柜台。",al={"为了杏仁糖展示肌肉在哪里","奥里森的位置","闪金镇旅店老板"}},{q="暴风城杏仁糖是给谁准备的？",a="这块杏仁糖是给耶斯帕尔准备的，他是一个住在暴风城的孤儿。他希望在万圣节期间尝遍联盟各大主城的传统节日糖果。",al={"谁得到了杏仁糖","谁想要暴风城杏仁糖","耶斯帕尔的糖果"}},{q="什么是暴风城杏仁糖？",a="暴风城杏仁糖是暴风城的旅店老板在万圣节期间发放的一种地方特产糖果，在节日参与者中被誉为人类王国的经典糖果之一。",al={"暴风城杏仁糖传说","万圣节杏仁糖","暴风城糖果"}},{q="部落玩家能从奥里森那里获得这种糖果吗？",a="不能。旅店老板奥里森身处联盟控制的暴风城深处，只接待联盟成员。部落冒险者需要在他们自己的主城里为旅店老板表演各自的节日节目。",al={"部落能为了杏仁糖展示肌肉吗","部落版的杏仁糖"}},{q="这个任务是全年都有吗？",a="不是。旅店老板奥里森只在万圣节的节日期间提供这个请求，那时不给糖就捣蛋的风俗会在各个城市流行开来。",al={"为了杏仁糖展示肌肉何时开放","这是节日任务吗","万圣节时间"}}},fp="18,176,24.276.0,26.304.0,44.116.0,33.112.0,38.158.0,25.165.0,49.179.0,34.114.0"}
P.entries["quest:8357"] = {n="跳跳舞，换糖果",s="在万圣节期间，旅行至达纳苏斯的冒险者们肩负着为暴风城的一名生病孤儿收集节日糖果的任务。旅店老板塞琳尼完全秉承了“不给糖就捣蛋”的传统，她要求冒险者在交出宝贵的达纳苏斯水果糖之前，必须即兴表演一段舞蹈。",h="在万圣节期间，旅行至达纳苏斯的冒险者们肩负着为暴风城的一名生病孤儿收集节日糖果的任务。旅店老板塞琳尼完全秉承了“不给糖就捣蛋”的传统，她要求冒险者在交出宝贵的达纳苏斯水果糖之前，必须即兴表演一段舞蹈。",kw={"跳舞","达纳苏斯","万圣节","旅店老板","耶斯帕尔","水果糖","塞琳尼","泰达希尔"},ang={["faction:Alliance"]="这项节日任务展示了联盟各主城之间共享的团结与轻松友谊，将来自遥远泰达希尔的糖果一直送到了暴风城的一名年轻孤儿手中。",["race:NightElf"]="对于暗夜精灵来说，参与万圣节是对联盟节日习俗的一种亲切采纳，将他们宁静的林地生活方式与俏皮的狂欢融合在了一起。"},sec={{t="延续的传统",b="即使在神圣的森林之城达纳苏斯，万圣节的狂欢也为长寿的暗夜精灵们带来了更为轻松的精神面貌。当旅行者们为了耶斯帕尔——一名在暴风城养病的患儿——前来收集节日糖果时，旅店老板塞琳尼坚持要遵守节日规则。无论是否出于慈善目的，想要得到糖果，必须先完成一次捣蛋。"},{t="水果糖的代价",b="为了获得精致的达纳苏斯水果糖，冒险者们必须放下尊严，在旅店地板上表演一场节目。塞琳尼只接受一段舞蹈作为交换，并乐于将这种完成跨大陆节日爱心包裹所需的糖果，奖励给那些愿意放下骄傲、拥抱节日欢乐的人。"}},faq={{q="“为水果糖而舞”的目的是什么？",a="该任务是联盟万圣节节日庆典的一部分。你需要为达纳苏斯的旅店老板塞琳尼跳一支舞，以获得达纳苏斯水果糖，这是让暴风城的患儿耶斯帕尔开心起来所需的几种节日糖果之一。",al={"为什么为了水果糖跳舞","这是什么任务","水果糖任务"}},{q="旅店老板塞琳尼是谁？",a="旅店老板塞琳尼管理着达纳苏斯内的旅店，为泰达希尔枝叶下的旅行者们提供庇护和休息。在万圣节期间，她负责向那些愿意遵循传统的旅行者分发当地的节日糖果。",al={"塞琳尼是谁","塞琳尼背景故事"}},{q="为什么塞琳尼坚持要跳舞？",a="塞琳尼严格遵守万圣节的精神。尽管这些糖果是给患儿准备的，但她依然坚守“不给糖就捣蛋”的习俗，俏皮地要求对方展示一下舞技作为“捣蛋”项目，之后才会交出糖果。",al={"为什么跳舞","为什么塞琳尼要我跳舞"}},{q="水果糖之后会去哪？",a="收到达纳苏斯水果糖后，它会被与其他从铁炉堡和暴风城的旅店以及铁炉堡的塔瓦斯德·基瑟尔处收集来的节日糖果打包在一起，以完成为暴风城的年轻孤儿耶斯帕尔带来节日欢乐的任务。",al={"谁得到了水果糖","水果糖怎么用"}},{q="什么是达纳苏斯水果糖？",a="达纳苏斯水果糖是一种在暗夜精灵主城制作的含糖甜点。它是达纳苏斯在万圣节期间为来访的“不给糖就捣蛋”者提供的标志性节日糖果。",al={"达纳苏斯水果糖背景故事","这是什么样的糖果"}},{q="部落玩家可以完成这个任务吗？",a="不可以。为水果糖而舞是联盟专属的节日任务。达纳苏斯是联盟的据点，且水果糖是专为在暴风城养病的联盟孤儿收集的。",al={"这个任务是联盟专属吗","部落水果糖任务"}}},fp="20,206,18.289.0,21.165.0,44.162.0,27.197.0,37.130.0,38.214.0,27.132.0,38.155.0"}
P.entries["quest:8359"] = {n="显肌肉，换糖果",s="在万圣节这个秋季庆典期间，奥格瑞玛的旅店老板格雷什卡会向那些乐于配合的人提供美味的节日糖果。为了给一个卧病在床的孩子弄到一块奥格瑞玛软糖，部落的勇士们必须抛下作为战士的骄傲，按要求展示他们的肌肉。",h="在万圣节这个秋季庆典期间，奥格瑞玛的旅店老板格雷什卡会向那些乐于配合的人提供美味的节日糖果。为了给一个卧病在床的孩子弄到一块奥格瑞玛软糖，部落的勇士们必须抛下作为战士的骄傲，按要求展示他们的肌肉。",kw={"糖果","展示肌肉","格雷什卡","万圣节","软糖","奥格瑞玛","斯波普斯","不给糖就捣蛋"},ang={["class:Warrior"]="那些以毁灭性的前线功绩为傲的战士们可能会发现，为了方块状的节日糖果而像舞台表演者一样摆姿势，是一件有趣——或者说略显谦卑的事情。",["faction:Horde"]="即使是面对致命军阀的资深勇士，最终也不得不为了给部落的孩子们收集节日糖果，而向旅店老板展示肱二头肌。",["race:Orc"]="奥格瑞玛的旅店老板期待着令人印象深刻的肌肉展示，这是一种典型的兽人式骄傲考验，变成了轻松愉快的节日戏码。"},sec={{t="不给糖就捣蛋",b="万圣节带来了欢快的气氛、恶作剧以及在艾泽拉斯各大主城收集糖果的活动。虽然冒险的英雄们经常要面对巨龙和黑暗魔法，但秋季节日的传统却需要轻松得多的方式。在奥格瑞玛旅店大厅主持工作的旅店老板格雷什卡很乐意分享她的节日糖果，但前提是顾客必须遵守这个节日最古老的规则：表演一个戏法，否则就空手而归。"},{t="展示肌肉",b="无论冒险者穿着什么伪装或护甲，格雷什卡都觉得很有趣，她要求展示原始的兽人力量。在交出给小斯波普斯准备的奥格瑞玛软糖之前，她坚持要看到这位强大的旅者摆出一个展示肌肉的姿势。这是一个轻松的提醒，即使是部落中最令人畏惧的战士，也可以为了糖果而娱乐大众。"}},faq={{q="是谁要求展示肌肉的？",a="旅店老板格雷什卡，奥格瑞玛力量谷内主旅店的经营者，在交出节日糖果之前要求表演戏法。",al={"谁给予任务","格雷什卡","旅店老板格雷什卡"}},{q="为什么为了糖果我需要展示肌肉？",a="万圣节习俗规定，不给糖就捣蛋的人必须表演一个小戏法来换取糖果。格雷什卡决定逗弄一下冒险者，要求在奖励他们之前展示一下纯粹的体能。",al={"为什么要展示肌肉","戏法是什么","软糖获取条件"}},{q="奥格瑞玛软糖有什么用？",a="这种软糖是在部落各大主城收集的四种特色糖果之一，用来安慰生病的孤儿斯波普斯，他自己无法去参加不给糖就捣蛋的活动。",al={"为什么需要软糖","软糖用途","斯波普斯的糖果"}},{q="旅店老板格雷什卡住在哪里？",a="你可以在奥格瑞玛力量谷的主旅店柜台后面找到她，她正在那里为疲惫的旅人和当地人服务。",al={"格雷什卡在哪里","奥格瑞玛旅店老板位置"}},{q="所有部落成员都能参与吗？",a="是的，任何部落成员都可以在万圣节期间拜访旅店老板格雷什卡，摆个姿势来领取节日糖果。",al={"谁能展示肌肉","阵营限制","仅限部落"}},{q="这是什么节日的一部分？",a="这个任务是万圣节的一部分，这是一个庆祝丰收结束，并通过服装、恶作剧和糖果来蔑视死亡的秋季节日。",al={"什么活动","什么节日","万圣节任务"}}},fp="18,148,17.282.0,17.237.0,27.143.0,32.161.0,38.159.0,36.131.0,41.122.0,31.136.0"}
P.entries["quest:836"] = {n="拯救OOX-09/HL！",s="当信号标激活了坠毁的寻路机器人后，奥格索普·奥布诺提斯的声音便从机器人身上传了出来。OOX-09/HL需要一个开阔、安全的地方来开始它的起飞程序，因此必须护送它前往眺望崖彼岸的海岸，然后奥格索普会在藏宝海湾等待。",h="当信号标激活了坠毁的寻路机器人后，奥格索普·奥布诺提斯的声音便从机器人身上传了出来。OOX-09/HL需要一个开阔、安全的地方来开始它的起飞程序，因此必须护送它前往眺望崖彼岸的海岸，然后奥格索普会在藏宝海湾等待。",kw={"藏宝海湾","隐形","寻路机器人","奥格索普·奥布诺提斯","眺望崖","机械小鸡-09/辛特兰"},sec={{t="前往海岸",b="奥格索普的声音再次从机器人身上传出，伴随着一阵杂音。这台机器需要一个开阔、安全的地方来开始漫长的起飞程序，眺望崖彼岸的海岸再合适不过了。它内置的隐形装置还无法使用，奥格索普需要时间让它恢复正常运作。"},{t="藏宝海湾的消息",b="一旦机器人被安全护送到海岸，奥格索普·奥布诺提斯会要求你去藏宝海湾找他谈话。"}},faq={{q="机器人需要被护送到哪里？",a="机械小鸡09号需要被带到眺望崖彼岸的海岸，那是一个开阔的地方，它可以在那里开始起飞。",al={"机械小鸡-09去哪里","辛特兰机械鸡护送目的地","眺望崖海岸"}},{q="是谁制造了这个寻路机器人？",a="这个机器人是侏儒奥格索普·奥布诺提斯的作品，他就在藏宝海湾。",al={"谁制造了机械小鸡-09","机械小鸡制造者","谁建造了机械鸡"}},{q="为什么机器人不能直接在被发现的地方起飞？",a="它的起飞程序非常漫长，需要一个开阔、安全的地方。与此同时，奥格索普需要时间让它的隐形装置恢复运作。",al={"为什么机械鸡要走路","为什么要护送机械小鸡-09"}},{q="护送到达海岸后你应该去哪儿？",a="一旦机器人安全抵达海岸，奥格索普·奥布诺提斯要求你去藏宝海湾见他。",al={"救援机械小鸡-09去哪交付","我向谁汇报","奥格索普位置"}},{q="在这个护送任务之前发生了什么？",a="在此之前是“寻找机械小鸡09号！”任务，你需要将求救信号标带到坠毁的机器人身边。",al={"机械小鸡-09前置任务","救援机械小鸡-09的前置条件"}}},fp="17,187,19.257.0,17.102.0,41.96.0,50.69.0,55.115.0,50.94.0,29.88.0"}
P.entries["quest:8360"] = {n="跳跳舞，换糖果",s="“为奶糖跳舞”是万圣节期间在雷霆崖由旅店老板帕拉提供的一个节日任务。为了给一名生病的孤儿收集甜点，冒险者必须放下久经沙场的尊严，为旅店老板跳一支欢快的舞蹈。即使在莫高雷那风吹的高原之上，这一任务也突显了节日中那种充满乐趣、社区至上的精神。",h="“为奶糖跳舞”是万圣节期间在雷霆崖由旅店老板帕拉提供的一个节日任务。为了给一名生病的孤儿收集甜点，冒险者必须放下久经沙场的尊严，为旅店老板跳一支欢快的舞蹈。即使在莫高雷那风吹的高原之上，这一任务也突显了节日中那种充满乐趣...",kw={"为奶糖跳舞","万圣节","旅店老板帕拉","奶糖","莫高雷","雷霆崖","不给糖就捣乱"},ang={["faction:Horde"]="这是部落艰苦日常中的轻松一刻，展现了当旅行者穿梭于各个主城为孤儿带来节日欢乐时，这个阵营所拥有的温情。",["race:Tauren"]="旅店老板帕拉将传统的节日欢愉直接带到了莫高雷，证明了即使是高大、坚毅的牛头人，也能为了一个甜蜜的事业而跳上一支欢快的舞蹈。"},sec={{t="崖上的舞蹈",b="在万圣节的秋季庆典期间，艾泽拉斯到处都洋溢着高昂的情绪，即便是雷霆崖宁静的高原上也不例外。负责照看高地旅店的旅店老板帕拉，在分发任何糖果之前，会要求对方先表演一个戏法，以此来感受节日气氛。即使冒险者是代表一名生病的孩子而来，传统依然不可动摇：帕拉坚持要看到一段节日舞蹈，才会交出她那珍贵的雷霆崖奶糖。"},{t="不给糖就捣乱",b="以娱乐换取糖果的节日习俗，展现了部落文化中罕见而轻松的一面。帕拉的要求并不复杂，只需上前一步，抖落一身的旅途疲惫，跳出你最棒的舞步即可。在被逗乐之后，这位旅店老板会很高兴地交出奶糖，并对等待这份甜点的那名生病的孩子表达她温暖的祝福。"}},faq={{q="“为奶糖跳舞”的任务目的是什么？",a="该任务要求你为雷霆崖的旅店老板帕拉表演一个跳舞表情。作为回报，她会给你一块雷霆崖奶糖，这是万圣节期间为生病孤儿收集的一系列节日糖果中的一部分。",al={"为什么要为奶糖跳舞","奶糖任务目标","为奶糖跳舞的任务目标"}},{q="是谁发布了这个任务？",a="旅店老板帕拉，这位在雷霆崖为游客和当地人提供服务的牛头人旅店老板，会在万圣节期间发布此任务。",al={"谁发布了为奶糖跳舞任务","帕拉的任务","旅店老板帕拉雷霆崖"}},{q="既然糖果是给生病的孩子吃的，为什么帕拉坚持要跳舞？",a="帕拉强调，即使是执行高尚的差事，也必须尊重节日传统。秉承着“不给糖就捣乱”的精神，必须表演一个戏法才能赢得甜蜜的奖励，以确保万圣节保持欢乐和活跃的氛围。",al={"为什么我必须跳舞","为什么帕拉想要看舞蹈"}},{q="跳舞能获得什么奖励？",a="你将获得一块雷霆崖奶糖，这是一种当地的节日甜点，是完成万圣节为生病的孩子收集糖果这一宏大任务所必需的物品。",al={"奶糖奖励","为奶糖跳舞任务物品"}},{q="联盟玩家可以完成这个任务吗？",a="不能。旅店老板帕拉是常驻雷霆崖中心的一名部落商人，这意味着节日糖果收集之旅中的这一特定环节仅限于部落成员参与。",al={"这是部落专属任务吗","联盟为奶糖跳舞"}},{q="这个任务什么时候可以完成？",a="该任务仅在每年的秋季节日“万圣节”期间开放，届时艾泽拉斯各地的旅店老板都会提供特殊的糖果和节日游戏。",al={"什么时候可以获得奶糖","万圣节奶糖任务"}}},fp="20,185,20.215.0,17.180.0,44.168.0,21.123.0,65.123.0,39.138.0,41.125.0,29.133.0"}
P.entries["quest:8367"] = {n="无上的荣耀",s="一名部落 Warbringer 要你带回来自四处战场的奖章。这项请求汇集了部落各场竞赛中的荣誉。",h="一名部落 Warbringer 要你带回来自四处战场的奖章。这项请求汇集了部落各场竞赛中的荣誉。",kw={"奥特兰克山谷","阿拉希盆地","暗矛群岛","为了至高荣誉","部落 warbringer","marks of honor","战歌峡谷"},sec={{t="献给 Warbringer 的奖章",b="一名部落 Warbringer 在战场之外向你索要来自奥特兰克山谷、阿拉希盆地、战歌峡谷和暗矛群岛的奖章。你从每处带回三枚 Marks of Honor，将各地的荣誉带给 Warbringer。"}},faq={{q="Warbringer 要求你带回什么？",a="部落 Warbringer 要求你带回来自奥特兰克山谷、阿拉希盆地、战歌峡谷和暗矛群岛的三枚 Marks of Honor。",al={"需要哪些奖章","warbringer 奖章"}},{q="Warbringer 在哪里？",a="部落 Warbringer 在战场之外。",al={"warbringer 在哪里","部落 warbringer 位置"}},{q="每处需要多少枚奖章？",a="你要从四处各带回三枚 Marks of Honor。",al={"每个战场需要的奖章","需要多少荣誉"}}},fp="15,128,24.229.0,33.127.0,24.50.0,42.60.0"}
P.entries["quest:837"] = {n="野猪人的进犯",s="“入侵”是部落的一项任务，由位于杜隆塔尔中部的剃刀岭的加索克委派。该任务要求勇士深入西部的荆棘窝，消灭那些盘踞在此、威胁着年轻兽人国家边境的剃刀鬃毛野猪人。",h="“入侵”是部落的一项任务，由位于杜隆塔尔中部的剃刀岭的加索克委派。该任务要求勇士深入西部的荆棘窝，消灭那些盘踞在此、威胁着年轻兽人国家边境的剃刀鬃毛野猪人。",kw={"荆棘","杜隆塔尔","入侵","加索克","野猪人","剃刀岭","剃刀鬃毛"},ang={["faction:Horde"]="清除来自本地剃刀鬃毛野猪人的威胁，对为新兴部落建立一个安全、永久的家园至关重要。",["race:Orc"]="兽人已将杜隆塔尔作为他们新的主权领土，他们将残存的剃刀鬃毛荆棘窝视为对定居点不可接受的威胁。"},sec={{t="杜隆塔尔的芒刺",b="当萨尔带领兽人来到卡利姆多并建立杜隆塔尔时，他们发现这片严酷干旱的土地上早已居住着剃刀鬃毛野猪人。这些好斗的野猪状生物成了新定居点的心腹大患。通过持续的军事努力，部落击退了他们大部分的兵力，但剃刀鬃毛野猪人的顽固据点仍然死守在剃刀岭以西的荆棘堡垒中。"},{t="加索克的攻势",b="加索克，一位驻扎在剃刀岭的军官，正在监督旨在彻底清除残余的剃刀鬃毛威胁的行动。他委派经验丰富的保卫者直接深入西部的荆棘营地，去消灭他们的侦察兵、战士和尘暴奔袭者。对加索克和部落领导层来说，让野猪人在剃刀岭附近有任何立足之地都会招致灾难，在这里打击他们被视为确保卡利姆多安全的第一步。"},{t="清除荆棘",b="消灭野猪人防卫者为部落军队焚烧荆棘窝扫清了道路，从而阻止了剃刀鬃毛野猪人重新夺回西部丘陵。通过将这些建筑彻底烧毁，部落消除了一个长期的威胁，并保卫了杜隆塔尔的西部边界，确保了剃刀岭与更广阔地区之间补给道路的安全。"}},faq={{q="谁会发布“入侵”任务？",a="该任务由驻扎在杜隆塔尔中部剃刀岭的兽人军官加索克发布。",al={"谁给予入侵任务","在哪儿接取入侵任务","入侵任务发布者"}},{q="为什么部落要在杜隆塔尔与剃刀鬃毛野猪人作战？",a="当兽人到达杜隆塔尔时，剃刀鬃毛野猪人占据了该地区的大部分领土。虽然部落击退了他们中的大多数，但仍有一些坚固的据点保留在剃刀岭以西，威胁着这个新兴兽人家园的安全和边境。",al={"为什么要在杜隆塔尔打野猪人","为什么要攻击剃刀鬃毛","杜隆塔尔的野猪人冲突"}},{q="剃刀鬃毛的营地在哪里？",a="剃刀鬃毛的营地位于剃刀岭以西。你只需寻找茂密的荆棘丛，就能轻松找到他们的领地。",al={"野猪人营地在哪里","如何找到剃刀鬃毛营地","入侵任务地点"}},{q="谁是剃刀鬃毛？",a="剃刀鬃毛是卡利姆多干旱平原上土生土长的一个敌对野猪人部族。他们建造防御性的荆棘窝，并激烈反抗部落在杜隆塔尔和贫瘠之地的定居。",al={"谁是剃刀鬃毛","剃刀鬃毛背景知识","什么是剃刀鬃毛"}},{q="野猪人被击败后会发生什么？",a="在完成该任务后，加索克会下令烧毁被清理过的野猪人荆棘窝和建筑，巩固部落对该地区的控制，并确保杜隆塔尔边境的安全。",al={"入侵任务之后会发生什么","入侵任务交接","野猪人营地的命运"}},{q="剃刀岭在这场冲突中扮演什么角色？",a="剃刀岭是杜隆塔尔中部的一个兽人要塞，它是试炼谷和奥格瑞玛之间的军事和后勤枢纽。",al={"剃刀岭在哪里","什么是剃刀岭"}}},fp="12,142,25.351.0,20.359.0,21.296.0,33.85.0,60.213.0,38.83.0,22.184.0,44.173.0,43.140.0"}
P.entries["quest:8370"] = {n="Conquering Arathi Basin",s="一名部落 Warbringer 要求你带来三枚阿拉希盆地 Marks of Honor。这些是完成这项请求所需的凭证。",h="一名部落 Warbringer 要求你带来三枚阿拉希盆地 Marks of Honor。这些是完成这项请求所需的凭证。",kw={"阿拉希盆地","战场","征服阿拉希盆地","部落 warbringer","荣誉徽记"},faq={{q="部落 Warbringer 要求什么？",a="部落 Warbringer 要求你带来三枚阿拉希盆地 Marks of Honor。",al={"需要什么","warbringer 请求"}},{q="我该把徽记交到哪里？",a="把徽记交给战场外的一名部落 Warbringer。",al={"交付地点","warbringer 位置"}},{q="需要多少枚荣誉徽记？",a="你需要三枚阿拉希盆地 Marks of Honor。",al={"需要多少枚徽记","三枚徽记"}}},fp="23,118,39.73.0,27.64.0,35.43.0"}
P.entries["quest:8372"] = {n="Fight for Warsong Gulch",s="一名联盟准将请你带来战歌峡谷 Marks of Honor。这些奖章要带到战场之外。",h="一名联盟准将请你带来战歌峡谷 Marks of Honor。这些奖章要带到战场之外。",kw={"联盟","战场","准将","荣誉奖章","战歌峡谷"},ang={["faction:Alliance"]="作为联盟成员，你可以把战歌峡谷 Marks of Honor 带给一名联盟准将。"},sec={{t="奖章",b="在战歌峡谷战斗后，你可以把三枚 Marks of Honor 带给战场外的一名联盟准将。将军索要这些奖章，你知道该带什么给他。"}},faq={{q="准将想要什么？",a="一名联盟准将请你带来三枚战歌峡谷 Marks of Honor。",al={"他们要什么奖章","准将的要求"}},{q="我该把奖章带到哪里？",a="把奖章带给战场外的一名联盟准将。",al={"在哪里交奖章","准将在哪里"}},{q="需要多少枚 Marks of Honor？",a="将军要三枚战歌峡谷 Marks of Honor。",al={"需要多少枚奖章","荣誉的数量"}}},fp="23,125,9.202.0,37.83.0,27.75.0,35.56.0"}
P.entries["quest:8373"] = {n="松木的力量",s="万圣节期间，哈特曼中士请你清除南海镇的被遗忘者臭气弹。松木香清洁剂能让村庄保持洁净。",h="万圣节期间，哈特曼中士请你清除南海镇的被遗忘者臭气弹。松木香清洁剂能让村庄保持洁净。",kw={"被遗忘者","万圣节","松木清洁剂","哈特曼中士","南海镇","臭气弹清洁剂","臭气弹"},ang={["faction:Alliance"]="作为一名联盟旅人，你可以帮助哈特曼中士清除南海镇的被遗忘者臭气弹，让这里保持洁净。"},sec={{t="南海镇的臭气",b="万圣节期间，被遗忘者用臭气弹袭击南海镇，把解放的庆典弄得臭气熏天。哈特曼中士请你用臭气弹清洁剂清除落在村里的臭气弹。"}},faq={{q="是谁让我清理臭气弹？",a="南海镇的哈特曼中士请你清除被遗忘者的臭气弹。",al={"谁给了我这个","哈特曼中士"}},{q="臭气弹在哪里？",a="臭气弹在南海镇。",al={"臭气弹位置","清理地点"}},{q="谁在南海镇使用臭气弹？",a="万圣节期间，被遗忘者在南海镇使用臭气弹。",al={"谁使用臭气弹","被遗忘者臭气弹"}},{q="清洁剂有什么作用？",a="臭气弹清洁剂借助松木的力量对抗恶臭。",al={"松木清洁剂","臭气弹清洁剂"}},{q="为什么要清理南海镇？",a="被遗忘者的臭气弹把南海镇的万圣节庆典弄得臭气熏天、一片狼藉。",al={"为何清理南海镇","万圣节臭气"}}},fp="17,148,20.213.0,40.74.0,26.34.0,35.65.0,25.54.0,32.93.0"}
P.entries["quest:8374"] = {n="Claiming Arathi Basin",s="阿拉希盆地外的一名联盟准将请你带来三枚 Arathi Basin Marks of Honor。这些奖章正是将军向你索要的物品。",h="阿拉希盆地外的一名联盟准将请你带来三枚 Arathi Basin Marks of Honor。这些奖章正是将军向你索要的物品。",kw={"联盟","联盟准将","阿拉希盆地","争夺阿拉希盆地","荣誉奖章"},ang={["faction:Alliance"]="作为联盟成员，你受命将三枚 Arathi Basin Marks of Honor 带给一名联盟准将。"},faq={{q="谁在索要这些奖章？",a="战场外的一名联盟准将请你带来三枚 Arathi Basin Marks of Honor。",al={"谁要奖章","准将"}},{q="需要多少枚荣誉奖章？",a="将军请你带来三枚 Arathi Basin Marks of Honor。",al={"需要多少枚奖章","三枚奖章"}},{q="我该把奖章交到哪里？",a="把奖章交给战场外的一名联盟准将。",al={"奖章交到哪里","交付奖章"}}},fp="21,153,23.108.0,35.64.0,27.75.0"}
P.entries["quest:8386"] = {n="Fight for Warsong Gulch",s="响应为战歌峡谷而战的号召，有助于保护灰谷的天然防线。你的努力让这些防线又能完好地维持一天。",h="响应为战歌峡谷而战的号召，有助于保护灰谷的天然防线。你的努力让这些防线又能完好地维持一天。",kw={"灰谷","防线","为战歌峡谷而战","天然防线","战歌峡谷"},sec={{t="灰谷的防线",b="在灰谷，你受命为战歌峡谷而战。你的行动让这片地区的天然防线又能完好地维持一天。"}},faq={{q="为什么要为战歌峡谷而战？",a="你的努力让灰谷的天然防线又能维持一天。",al={"战歌峡谷战斗","为何为战歌而战"}},{q="这有助于保护什么？",a="这场战斗让灰谷的天然防线又能完好地维持一天。",al={"什么防线","保护灰谷"}},{q="战歌峡谷在哪里？",a="战歌峡谷是一片战场，在灰谷与贫瘠之地之间形成了一道天然屏障。",al={"战歌位置","战歌峡谷在哪"}}},fp="23,125,20.128.0,28.72.0,28.73.0,23.96.0"}
P.entries["quest:8389"] = {n="战歌峡谷之战",s="部落请求你协助确保其对战歌峡谷的所有权。你的援助关系到部落在那里的主张。",h="部落请求你协助确保其对战歌峡谷的所有权。你的援助关系到部落在那里的主张。",kw={"战斗","主张","部落","所有权","战歌峡谷"},ang={["faction:Horde"]="作为部落的一员，你的援助有助于确保部落对战歌峡谷的所有权。"},sec={{t="部落的主张",b="部落对战歌峡谷的主张需要你的援助。你的帮助将支持部落对峡谷的所有权。"}},faq={{q="部落在这里想要什么？",a="部落希望确保其对战歌峡谷的所有权。",al={"战歌峡谷部落","部落主张","战歌峡谷归谁所有"}},{q="我该如何帮忙？",a="你的援助有助于确保部落对战歌峡谷的所有权。",al={"帮助部落","我在做什么","战歌峡谷之战"}},{q="部落为什么想要战歌峡谷？",a="现有记载称，部落希望确保其对战歌峡谷的所有权。",al={"为何要战歌峡谷","部落为何想要它","战歌峡谷的缘由"}}},fp="23,112,11.116.0,30.57.0,15.63.0,38.84.0"}
P.entries["quest:8393"] = {n="Claiming Arathi Basin",s="阿拉希盆地外的一名联盟准将请你带来三枚阿拉希盆地 Marks of Honor。这项请求中只提到了这些牌子。",h="阿拉希盆地外的一名联盟准将请你带来三枚阿拉希盆地 Marks of Honor。这项请求中只提到了这些牌子。",kw={"联盟","阿拉希盆地","准将","争夺阿拉希盆地","marks of honor"},ang={["faction:Alliance"]="作为联盟成员，你需要把三枚阿拉希盆地 Marks of Honor交给一名联盟准将。"},faq={{q="这位准将要你带来什么？",a="这位联盟准将请你带来三枚阿拉希盆地 Marks of Honor。",al={"阿拉希牌子","三枚牌子","要带什么"}},{q="我该把牌子交到哪里？",a="把牌子交给战场外的一名联盟准将。",al={"交到哪里","准将位置","在哪里交牌子"}},{q="谁在索要这些牌子？",a="战场外的一名联盟准将在索要这些牌子。",al={"谁要这些牌子","阿拉希将军","谁发布这个任务"}}},fp="21,155,40.83.0,27.75.0,28.75.0"}
P.entries["quest:83934"] = {n="Show Me the Money!",s="Pix Xizzix请你追回他和兄弟们在藏宝海湾被盗的钱币。这笔钱关系到他们从Kezan前来创办的事业。",h="Pix Xizzix请你追回他和兄弟们在藏宝海湾被盗的钱币。这笔钱关系到他们从Kezan前来创办的事业。",kw={"藏宝海湾","创业事业","钱币","kezan","海盗","pix xizzix","褪色的安德麦雷亚尔","undermine real"},sec={{t="被盗的创业资金",b="藏宝海湾的Pix Xizzix遭海盗劫掠，他和兄弟们从Kezan带来的创业资金被盗，因此前来求助。家乡的资助者期望这项事业成功，所以他愿为你找回的任何钱币付酬。他请你带给他一枚褪色的安德麦雷亚尔。"}},faq={{q="Pix Xizzix是谁？",a="Pix Xizzix是来自Kezan的一群兄弟中的一员，他们来到这里创办一项事业。",al={"pix xizzix","pix是谁","xizzix"}},{q="Pix为什么想找回钱币？",a="海盗偷走了Pix和兄弟们为创业带来的资金。他们家乡的资助者并不通情达理。",al={"为何找回钱币","被盗的钱","pix的钱"}},{q="Pix在找什么钱币？",a="Pix请你带给他一枚褪色的安德麦雷亚尔。",al={"褪色的雷亚尔","undermine钱币","哪种钱币"}},{q="我该把钱币带到哪里？",a="把褪色的安德麦雷亚尔带给藏宝海湾的Pix Xizzix。",al={"把钱币带到哪里","pix的位置","藏宝海湾钱币"}},{q="Pix愿意为钱币提供什么？",a="Pix说，他和兄弟们会让你觉得这趟值得，还会拿出货物与你交换。",al={"pix的报酬","交换的货物","钱币的报酬"}}},fp="18,138,14.272.0,18.89.0,32.133.0,29.53.0,30.62.0,33.84.0"}
P.entries["quest:8399"] = {n="Fight for Warsong Gulch",s="战场之外的一名联盟准将请你带来三枚 Marks of Honor。要响应号召，前往那里作战，就需要这些印记。",h="战场之外的一名联盟准将请你带来三枚 Marks of Honor。要响应号召，前往那里作战，就需要这些印记。",kw={"联盟","联盟准将","战斗","marks of honor","战歌峡谷"},ang={["faction:Alliance"]="作为一名联盟战士，你受命将 Marks of Honor 带给战场之外的一名联盟准将。"},sec={{t="准将的请求",b="战歌峡谷的印记正是战场之外的联盟准将向你索要之物。将三枚 Marks of Honor 交给准将，你在战歌峡谷的战斗便可计入联盟的战事。"}},faq={{q="联盟准将想要什么？",a="战场之外的联盟准将请你带来三枚 Marks of Honor。",al={"准将印记","需要什么印记"}},{q="我该把 Marks of Honor 交给谁？",a="将 Marks of Honor 交给战场之外的一名联盟准将。",al={"在哪里交印记","战歌峡谷印记位置"}},{q="需要多少枚 Marks of Honor？",a="你需要三枚战歌峡谷 Marks of Honor。",al={"需要多少枚印记","三枚印记"}}},fp="23,151,23.219.0,46.96.0,36.84.0,35.44.0"}
P.entries["quest:84"] = {n="比利的馅饼",s="“回到比利身边”是艾尔文森林中部斯通菲尔德家族与马科伦家族持续争斗中的一个环节。你已经收集齐了制作猪肉馅饼的配料，现在要将刚出炉的馅饼送回给年轻的比利·马科伦，以便套出关于波尼斯·斯通菲尔德姑妈丢失项链的消息。",h="“回到比利身边”是艾尔文森林中部斯通菲尔德家族与马科伦家族持续争斗中的一个环节。你已经收集齐了制作猪肉馅饼的配料，现在要将刚出炉的馅饼送回给年轻的比利·马科伦，以便套出关于波尼斯·斯通菲尔德姑妈丢失项链的消息。",kw={"回到比利身边","波尼斯·斯通菲尔德","比利·马科伦","艾尔文森林","马科伦农场","猪肉馅饼","斯通菲尔德农场","斯通菲尔德的项链"},ang={["faction:Alliance"]="即便是宁静的艾尔文森林也深受琐碎纠纷的困扰；处理那些互相争吵的人类农场主之间的矛盾，是旅行者帮助当地民众时的家常便饭。",["profession:Cooking"]="猪肉馅饼是艾尔文森林典型的农家舒适美食，是用森林里漫游的野猪肉制成的。"},sec={{t="苦涩的馅饼",b="斯通菲尔德家族与马科伦家族之间几代人的争吵让邻里间几乎没有任何温情可言。波尼斯·斯通菲尔德姑妈极不情愿地烤了这块猪肉馅饼，仅仅是因为如果不给年轻的比利·马科伦，他就拒绝透露关于她家传宝物的消息。即便在交出温热的馅饼时，她依然毫不掩饰自己的恼怒，叮嘱送信人告诉那个马科伦家的小子，她希望他每吃一口都会被噎住。"},{t="男孩的贿赂",b="马路对面的马科伦农场，比利·马科伦正饿着肚子等着，而且他的记忆力也恰到好处地“出了点问题”。这次交易凸显了分裂这两个农场的那种顽固而琐碎的争执，甚至连孩子们都学会了拿流言蜚语和偷来的小玩意儿来换取农场的美食。馅饼送到后，比利那模糊的记忆顿时清晰起来，这也引出了寻找项链下落的线索。"}},faq={{q="这次派送的目的是什么？",a="比利·马科伦声称知道波尼斯·斯通菲尔德姑妈丢失的项链在哪里，但在得到一块家常猪肉馅饼之前拒绝透露。派送馅饼满足了他的要求，以便他揭示传家宝的去向。",al={"为什么要送馅饼","比利想要什么","回到比利身边任务目标"}},{q="波尼斯姑妈为什么那么生比利的火？",a="斯通菲尔德家族和马科伦家族多年来一直陷入痛苦的农村争端之中。波尼斯很反感为了找回在他们两家边界丢失的传家宝，还得给一个令人头疼的马科伦小孩做点心吃。",al={"波尼斯为什么讨厌比利","斯通菲尔德和马科伦的争斗","为什么要让他被噎住"}},{q="比利说项链到底在哪里？",a="当比利狼吞虎咽地吃完馅饼后，他透露项链并不在他手里。相反，它落入了一个名为金牙的臭名昭著的狗头人手中，那个家伙正潜伏在法戈第矿洞里。",al={"项链在哪里","谁拿走了项链","金牙的关联"}},{q="比利·马科伦在哪里？",a="比利·马科伦位于马科伦农场，就在艾尔文森林中部马路的南侧，斯通菲尔德农场的对面。",al={"比利·马科伦的位置","比利在哪里","找到比利"}},{q="是谁烤了猪肉馅饼？",a="波尼斯·斯通菲尔德姑妈在斯通菲尔德农场烤了这块馅饼，在此之前你从附近的荒野收集了新鲜的野猪肉块。",al={"谁做了馅饼","馅饼厨师"}},{q="这个任务能解决两个家族之间的世仇吗？",a="不能。派送馅饼仅仅满足了比利个人的勒索。斯通菲尔德家族和马科伦家族成年人之间根深蒂固的敌意依然如故。",al={"世仇是否结束","斯通菲尔德和马科伦的和平"}}},fx={["6d42dc77"]={q="波尼斯老太太为什么派一个外人去应付比利？",a="斯通菲尔德家族和马科伦家族积怨已深，几乎不可能直接往来。波尼斯老太太根本不愿踏上马科伦家的土地，更别说亲自去伺候一个拿赃物索要食物的讨厌孩子了。路过的旅人正好可以充当中立的信使，穿过道路，送去馅饼，再从小比利嘴里问出真相，而不至于让这两户邻居大打出手。",al={"为什么派我回去找比利","波尼斯为什么不亲自去","波尼斯老太太为什么需要冒险者"}}},fp="13,218,12.304.0,13.343.1,37.224.0,42.209.0,46.131.1,31.124.0,29.135.0,54.122.0"}
P.entries["quest:840"] = {n="部落的新兵",s="“部落征召”是一项引导性的过渡任务，指引年轻的部落冒险者走出杜隆塔尔，进入贫瘠之地那广袤的荒野。该任务由剃刀岭西侧道路上的斥候塔克林·寻路者发起，指引新兵穿过怒水河，前往卡加尔·战痕的边境哨所。",h="“部落征召”是一项引导性的过渡任务，指引年轻的部落冒险者走出杜隆塔尔，进入贫瘠之地那广袤的荒野。该任务由剃刀岭西侧道路上的斥候塔克林·寻路者发起，指引新兵穿过怒水河，前往卡加尔·战痕的边境哨所。",kw={"贫瘠之地","部落征召","十字路口","卡加尔·战痕","剃刀岭","募兵信","怒水河","塔克林·寻路者"},ang={["faction:Horde"]="这次征召标志着一名战士从杜隆塔尔的本土守护者，转变成为卡利姆多各地部落领土的正式捍卫者。",["race:Orc"]="对于离开试炼谷和剃刀岭训练场的年轻兽人来说，响应卡加尔·战痕的号召是效忠大酋长过程中必不可少的成人礼。",["race:Troll"]="与兽人盟友并肩作战的暗矛巨魔利用这次部署来协助部落的扩张，并保卫濒临无尽之海的领土。"},sec={{t="跨越怒水河",b="一旦有志向的部落士兵在剃刀岭附近证明了自己的实力，整个国家的局势便需要他们向西进发。塔克林·寻路者驻守在离开杜隆塔尔的土路上，代表他的老友——老兵卡加尔·战痕考察过往的旅人。接受塔克林的募兵信，标志着新兵接到了在兽人新家园杜隆塔尔之外的第一个正式任务。"},{t="边境防御",b="桥那头的边境哨所横跨在杜隆塔尔的红色峡谷与贫瘠之地的干旱平原之间。卡加尔·战痕肩负着召集新兵守卫边疆的重任，但边境守卫工作仅仅是个开始。随着半人马、野猪人和联盟的远征军不断试探边境，急需人力被调往十字路口定居点。"}},faq={{q="我要把募兵信交给谁？",a="沿着杜隆塔尔剃刀岭外的西侧道路前行，穿过横跨怒水河的木桥。卡加尔·战痕就驻守在刚刚跨过边境、位于贫瘠之地一侧的部落哨塔上。",al={"我要去哪","卡加尔·战痕位置","任务交付位置"}},{q="塔克林·寻路者是谁？",a="塔克林·寻路者是一名驻扎在剃刀岭外西侧道路上的部落斥候。他充当着路上的耳目，负责发掘有能力的战士并将他们向西送往他的战友卡加尔·战痕处。",al={"塔克林的职责","谁给予任务","任务发布者"}},{q="卡加尔·战痕是谁？",a="卡加尔·战痕是一位粗犷的资深军官，负责管理贫瘠之地东部的岗哨。他会检查到来的志愿者，签署他们的征召文书，并将他们指引至大草原更深处，以支援十字路口。",al={"卡加尔是谁","战痕背景故事"}},{q="卡加尔签署信件后会发生什么？",a="卡加尔会收下信件，并立即通过任务“十字路口的征召”让你继续服役，指示你沿着主路向西进发，向十字路口的塞格拉·黑棘报到。",al={"下一个任务","完成“部落征召”后做什么","下一步去哪"}},{q="为什么部落要在贫瘠之地招募士兵？",a="贫瘠之地是连接奥格瑞玛与莫高雷的重要边境。随着凶猛的野猪人部落、半人马掠夺者以及趁机入侵的联盟威胁着补给线，部落需要每一双能战斗的手来确保道路的安全。",al={"为什么要征召","贫瘠之地的危险","为什么要招募"}},{q="联盟玩家可以接取这个任务吗？",a="不可以。该任务仅供从杜隆塔尔早期任务线过渡到贫瘠之地的部落成员接取。",al={"联盟能接吗","是否仅限部落"}}},fp="22,229,22.363.0,14.326.0,39.186.0,25.160.0,25.208.0,43.155.0,53.221.0,44.96.0"}
P.entries["quest:8400"] = {n="战歌峡谷之战",s="联盟要在战歌峡谷的前线见证你的英勇。驻扎在战场外的一名联盟准将要求你带回三枚对抗部落时获得的 Marks of Honor。",h="联盟要在战歌峡谷的前线见证你的英勇。驻扎在战场外的一名联盟准将要求你带回三枚对抗部落时获得的 Marks of Honor。",kw={"联盟","灰谷","战场","准将","marks of honor","战歌峡谷"},ang={["faction:Alliance"]="作为一名联盟士兵，将你的战斗凭证交给联盟准将，就能证明你在战歌峡谷持续对抗部落的战斗中尽了职责。"},sec={{t="将军的召唤",b="一名驻扎在战场附近的联盟准将召集从前线归来的士兵。如果你曾在战歌峡谷作战，三枚 Marks of Honor 就能证明你的地位，以及你对抗部落时立下的功绩。将这些信物带回高层指挥部，便能表明联盟仍在这座争议峡谷中坚守阵地。"}},faq={{q="谁会收取战歌峡谷的 Marks of Honor？",a="一名驻扎在战场外的联盟准将收集这些 Marks，以追踪战况。",al={"谁要 marks of honor","准将 marks"}},{q="你需要带回多少枚？",a="你需要三枚战歌峡谷的 Marks of Honor，来证明自己在战场上的功绩。",al={"战歌峡谷需要几枚 marks","战歌峡谷所需 marks"}},{q="联盟准将在哪里？",a="这位准将在战场外等候，联盟在那里协调部队。",al={"准将在哪里","联盟将军位置"}}},fp="23,198,18.327.0,43.107.0,36.85.0,40.96.0"}
P.entries["quest:841"] = {n="另一个能量源？",s="加基森的首席工程师沙克斯·比格维兹还有更多的能源，如果你愿意支付十个废土游民水袋，他会再卖给你一个。",h="加基森的首席工程师沙克斯·比格维兹还有更多的能源，如果你愿意支付十个废土游民水袋，他会再卖给你一个。",kw={"比格维兹","加基森","能源","塔纳利斯","废土游民","水袋"},sec={{t="昂贵的替代品",b="首席工程师沙克斯·比格维兹推测在“止渴”任务中获得的第一块能源已经耗尽，或者可能遗失在了沙子里。不管原因如何，沙克斯·比格维兹手头还有更多的能源可以出售。这次的价格是十个废土游民水袋，因为现在世道艰难，能源又不是长在树上的。"}},faq={{q="为什么首席工程师沙克斯·比格维兹想要废土游民水袋？",a="沙克斯·比格维兹以十个废土游民水袋的价格出售另一块能源，并声称现在世道艰难。",al={"比格维兹 水袋","为什么需要水袋"}},{q="谁提供这个交换？",a="首席工程师沙克斯·比格维兹，他手头还有更多的能源可以出售。",al={"谁开启了又一个能源任务","能源任务提供者"}},{q="在需要另一块能源之前发生了什么？",a="这紧随“止渴”任务之后，你在该任务中首次为你的工具包获得了一块能源。",al={"又一个能源前置任务","之前的能源任务"}}},fp="21,108,20.225.0,68.132.0,25.83.0,52.84.0"}
P.entries["quest:84147"] = {n="An Earnest Proposition",s="铁炉堡的德莉亚娜愿以更好的护腕换取你的帮助。她要冬泉谷的血、金币和你平常佩戴的护腕。",h="铁炉堡的德莉亚娜愿以更好的护腕换取你的帮助。她要冬泉谷的血、金币和你平常佩戴的护腕。",kw={"an earnest proposition","护甲交换","熊血","德莉亚娜","霜刃豹之血","铁炉堡","wildheart bracers","冬泉谷"},sec={{t="德莉亚娜的提议",b="德莉亚娜在铁炉堡备有一套更精良的护腕，愿意用它们交换你的 Wildheart Bracers。她要你带来冬泉谷霜刃豹和熊的血，还要金币。这次交易只换一件，不过德莉亚娜说，只要你愿意多帮她做些事，她也许会把这套护甲的其余部分交给你。"}},faq={{q="谁想要这些护腕？",a="铁炉堡的德莉亚娜愿用更精良的护腕交换你的 Wildheart Bracers。",al={"德莉亚娜是谁","护腕交换"}},{q="德莉亚娜想要我带什么？",a="德莉亚娜要冬泉谷霜刃豹和熊的血、你的 Wildheart Bracers，以及金币。",al={"她需要什么","德莉亚娜的请求"}},{q="她为什么要冬泉谷的血？",a="德莉亚娜说，她需要冬泉谷霜刃豹和熊的血。",al={"霜刃豹之血","熊血"}},{q="德莉亚娜要给我什么护甲？",a="她提供一套与你的职业所穿相似、但品质更高的护腕。",al={"什么护腕","更好的护甲"}},{q="德莉亚娜还能交换其他护甲吗？",a="德莉亚娜说，如果你愿意为她做更多事，她也许会把护甲的其余部分交给你。",al={"套装其余部分","更多差事"}}},fp="22,145,15.305.0,30.82.0,31.97.0,37.73.0,31.92.0,36.107.0"}
P.entries["quest:842"] = {n="十字路口征兵",s="“十字路口征兵”将刚入伍的部落新兵从边境哨所直接派往贫瘠之地的腹地。冒险者带着卡加尔·战痕签过字的信，直接向位于关键战略枢纽“十字路口”的塞尔格拉·黑刺报到。",h="“十字路口征兵”将刚入伍的部落新兵从边境哨所直接派往贫瘠之地的腹地。冒险者带着卡加尔·战痕签过字的信，直接向位于关键战略枢纽“十字路口”的塞尔格拉·黑刺报到。",kw={"贫瘠之地","战痕","征兵","十字路口","黑刺","前沿哨所","卡加尔","塞尔格拉","萨尔"},ang={["class:Shaman"]="塞尔格拉·黑刺证明了萨尔领导下的部落中的萨满祭司不仅仅是神秘的顾问，还是关键战略哨所的直接军事指挥官和管理者。",["faction:Horde"]="这项任务是年轻的部落战士从家乡的安全港湾步入贫瘠之地充满争端的荒野时，所要经历的标准成人礼。",["race:Orc"]="卡加尔与塞尔格拉之间的交流凸显了萨尔重组后的部落中不断演变的社会动态，在这里，功绩和精神洞察力正在挑战传统的氏族观念和旧式的苦工模式。"},sec={{t="报到",b="在杜隆塔尔边界的前沿哨所向卡加尔·战痕证明了自己的价值后，新兵会收到一封签过字的募兵信并被派往西方。旅程沿着贫瘠之地干旱灌木丛中的土路前行，直至抵达中央路口。在这处被烈日炙烤的交叉路口坐落着十字路口，这是部落连接卡利姆多北部与南方荒野的关键后勤枢纽。"},{t="十字路口的萨满祭司",b="等待新兵到来的是塞尔格拉·黑刺，一位言辞犀利的兽人萨满祭司，她是大酋长萨尔亲自挑选出来负责管理十字路口事务的。尽管像卡加尔·战痕这样的老兵抱怨她很难相处且过于啰嗦，但萨尔对塞尔格拉评价极高。她性格刚烈、毫不妥协，经常提醒新兵，特别是那些傲慢的男性，在萨尔领导的部落中，女性战士和领袖拥有完全平等的地位，她绝不容忍任何无礼的行为。"}},faq={{q="谁指派我执行这个任务？",a="卡加尔·战痕，一位驻扎在杜隆塔尔与贫瘠之地交界桥梁以西前沿哨所的兽人老兵，他会指派给你这项任务。",al={"谁发布十字路口征兵任务","十字路口征兵任务发布者","卡加尔的任务"}},{q="塞尔格拉·黑刺在哪里？",a="塞尔格拉·黑刺驻扎在十字路口的中心，站在商队和信使汇聚的路口附近。",al={"塞尔格拉·黑刺位置","塞尔格拉在哪里","寻找塞尔格拉·黑刺"}},{q="为什么卡加尔会抱怨塞尔格拉？",a="卡加尔觉得塞尔格拉很烦人，称她是个令人讨厌的萨满祭司，总是在让人干活前啰嗦一大堆。尽管他个人对此感到恼火，但他还是尊重并执行大酋长萨尔派遣新兵向她报到的命令。",al={"为什么卡加尔不喜欢塞尔格拉","卡加尔与塞尔格拉","诅咒她"}},{q="为什么塞尔格拉对男性和女性角色的对话内容不同？",a="塞尔格拉·黑刺对萨尔在大酋长领导下的新部落中建立女性战士完全平等地位的法令深感自豪。她会热情地鼓励主动参军的女性新兵，同时警告男性新兵，她绝不容忍任何不敬或无礼的行为。",al={"塞尔格拉男女对话差异","塞尔格拉·黑刺对话","塞尔格拉平等地位"}},{q="我该走哪条路去十字路口？",a="从前沿哨所沿主路向西走，直到遇到一个丁字路口，然后左转并沿着南面的路直行，即可到达十字路口的定居点。",al={"如何前往十字路口","十字路口路线指引","前往十字路口的道路"}},{q="向塞尔格拉·黑刺报到后会发生什么？",a="一旦被塞尔格拉接纳，她就会征召你为十字路口效力，派你去协助处理当地的威胁、狩猎任务，以及贫瘠之地中部的哨所安保工作。",al={"十字路口征兵之后做什么","塞尔格拉的后续任务","贫瘠之地新兵后续"}}},fp="23,184,18.318.0,28.425.0,27.153.0,34.111.0,38.185.0,64.193.0,49.130.0,49.145.0"}
P.entries["quest:8426"] = {n="战歌峡谷之战",s="一名部落 Warbringer 要你带来三枚战歌峡谷荣誉奖章。这些奖章就是这项委托所需的凭证。",h="一名部落 Warbringer 要你带来三枚战歌峡谷荣誉奖章。这些奖章就是这项委托所需的凭证。",kw={"战场","部落","荣誉奖章","warbringer","战歌峡谷"},ang={["faction:Horde"]="作为部落的一员，你可以把战歌峡谷荣誉奖章交给一名部落 Warbringer。"},sec={{t="归还奖章",b="你将三枚战歌峡谷荣誉奖章带给战场外的一名部落 Warbringer。Warbringer 要的就是这些奖章，这项委托只需交付它们。"}},faq={{q="Warbringer 要什么？",a="部落 Warbringer 要你带来三枚战歌峡谷荣誉奖章。",al={"要什么奖章","warbringer想要什么","要带什么"}},{q="我该把奖章交给谁？",a="把奖章交给战场外的一名部落 Warbringer。",al={"warbringer在哪里","交还奖章","交到哪里"}},{q="需要几枚奖章？",a="Warbringer 要三枚战歌峡谷荣誉奖章。",al={"需要几枚奖章","奖章数量","三枚奖章"}}},fp="23,121,15.170.0,33.74.0,27.64.0,26.59.0"}
P.entries["quest:8427"] = {n="战歌峡谷之战",s="战歌峡谷外的一名部落 Warbringer 要你带来三枚 Warsong Gulch Marks of Honor。这些徽记是进行这项兑换所必需的。",h="战歌峡谷外的一名部落 Warbringer 要你带来三枚 Warsong Gulch Marks of Honor。这些徽记是进行这项兑换所必需的。",kw={"战斗","战场","部落","荣誉徽记","warbringer","战歌峡谷"},faq={{q="Warbringer 要求带来什么？",a="部落 Warbringer 要你带来三枚 Warsong Gulch Marks of Honor。",al={"战歌峡谷徽记","荣誉徽记","需要带什么"}},{q="我该把徽记交到哪里？",a="把徽记交给战场外的一名部落 Warbringer。",al={"warbringer 在哪里","交付徽记","战歌峡谷 warbringer"}},{q="需要多少枚徽记？",a="Warbringer 要求三枚 Warsong Gulch Marks of Honor。",al={"需要多少枚徽记","三枚徽记","徽记数量"}}},fp="23,136,33.74.0,27.64.0,26.59.0"}
P.entries["quest:843"] = {n="加恩的报复",s="“加恩的复仇”是一个部落任务，由流浪的牛头人流亡者加恩·石塔在南贫瘠之地发布。加恩对巴尔莫丹的矮人考古挖掘驱逐了他的部落深感愤慨，他招募旅行者进行反击，屠杀该地点的工人并取回他们领袖的日记。",h="“加恩的复仇”是一个部落任务，由流浪的牛头人流亡者加恩·石塔在南贫瘠之地发布。加恩对巴尔莫丹的矮人考古挖掘驱逐了他的部落深感愤慨，他招募旅行者进行反击，屠杀该地点的工人并取回他们领袖的日记。",kw={"巴尔莫丹","贝尔丹","矮人挖掘场","加恩·石塔","卡兹戈姆","南贫瘠之地"},ang={["class:Shaman"]="巴尔莫丹的爆破和深层开沟伤害了周围的土元素，使加恩的行动成为清除元素动乱的必要手段。",["faction:Horde"]="巴尔莫丹代表了卡利姆多领地深处的一个防御森严的联盟据点，这使得保卫加恩的领地既是一种荣誉行为，也是一种战略遏制。",["race:Tauren"]="对于舒哈鲁来说，加恩的困境令人愤怒地提醒着人们：联盟是多么不尊重大地母亲，竟然使用炸药和铁齿轮来撕裂祖先的墓地。"},sec={{t="流离失所的部落",b="在勘探员的火炮和镐头破坏这片土地之前，贫瘠之地南部的红色断崖曾是加恩·石塔部族的祖居地和狩猎场。当矮人从铁炉堡赶来建立巴尔莫丹时，牛头人遭到暴力驱逐或杀害，以便为巨大的采石场和沟渠腾出空间。在和平抗议被无视、外交手段用尽的情况下，加恩现在独自走在南部的道路上，为他阵亡的族人策划一场血腥的报复。"},{t="巴尔莫丹的废墟",b="巴尔莫丹的矮人行动对这片土地及其守护者毫无怜悯。在勘探员卡兹戈姆的领导下，探险队用蒸汽机和重型炸药炸开山坡，深入地下挖掘。加恩的任务简单而坚定：削减正在破坏神圣土地的贝尔丹挖掘者和工头的数量，杀死卡兹戈姆本人，并夺取勘探员的个人挖掘笔记，以查明这些联盟入侵者到底在寻找什么。"}},faq={{q="谁是加恩·石塔？",a="加恩·石塔是一位孤独的牛头人幸存者，他的部落曾经居住在南贫瘠之地。在矮人挖掘者驱逐了他的族人并杀害反抗者后，加恩开始徘徊在南部公路上，寻求正义并对入侵的联盟挖掘场进行报复。",al={"加恩","谁发布加恩的复仇","加恩·石塔背景故事"}},{q="为什么矮人在贫瘠之地？",a="这些矮人是来自铁炉堡的贝尔丹探险队，他们在南贫瘠之地的巴尔莫丹建立了一座堡垒和一个挖掘场。他们的爆破和嘈杂的挖掘机器撕裂了山丘，完全无视当地的牛头人居民。",al={"为什么矮人在巴尔莫丹","巴尔莫丹的目的","贫瘠之地的铁炉堡"}},{q="谁是勘探员卡兹戈姆？",a="勘探员卡兹戈姆是负责指导巴尔莫丹堡垒以南挖掘场行动的矮人领袖。加恩认为他对亵渎祖居地负有直接责任，并要求获得他的日记作为他死亡的证据。",al={"卡兹戈姆","勘探员卡兹戈姆","巴尔莫丹领袖"}},{q="在哪里可以找到加恩·石塔？",a="加恩·石塔在远南贫瘠之地的道路上徘徊，位于巴尔莫丹堡垒以西，通往升降梯和千针石林的道路以北。",al={"加恩的位置","寻找加恩","加恩在哪里"}},{q="加恩是否尝试过和平解决此事？",a="是的。加恩明确表示，他曾尝试通过外交途径阻止对其祖居地的破坏，但矮人无视了这些努力，继续炸开山丘，迫使他诉诸暴力。",al={"牛头人尝试过外交吗","加恩的外交"}},{q="完成这个任务后会发生什么？",a="在收到卡兹戈姆的日记后，加恩会研究其中的笔记以了解矮人的技术和计划，从而直接引出旨在破坏其重型机械的任务链“加恩的复仇”。",al={"加恩的复仇后的下一个任务","加恩的后续任务"}}},fp="18,202,17.379.0,23.355.0,23.270.0,35.238.0,27.190.0,35.163.0,40.195.0,30.158.1"}
P.entries["quest:8431"] = {n="战歌峡谷之战",s="部落力求确保自己对战歌峡谷的所有权。你的帮助将助其巩固这一主张。",h="部落力求确保自己对战歌峡谷的所有权。你的帮助将助其巩固这一主张。",kw={"战斗","峡谷","部落","所有权","战歌峡谷"},ang={["faction:Horde"]="你帮助部落确保其对战歌峡谷的所有权。"},sec={{t="峡谷归属之争",b="部落对战歌峡谷的所有权岌岌可危，你正贡献力量，帮助部落巩固所有权。你的努力有助于确保部落继续拥有这片峡谷。"}},faq={{q="战歌峡谷发生了什么？",a="部落正努力确保自己对战歌峡谷的所有权。",al={"战歌峡谷之战","峡谷里发生了什么"}},{q="我在帮助谁？",a="你正在帮助部落确保其对战歌峡谷的所有权。",al={"谁在寻求帮助","这是在帮助哪一方"}},{q="部落想要什么？",a="部落力求继续拥有战歌峡谷。",al={"部落的目标","为何在战歌峡谷作战"}}},fp="23,88,20.153.0,35.62.0,17.64.0,25.55.0"}
P.entries["quest:8436"] = {n="Conquering Arathi Basin",s="一名部落战争使者向你索要三枚阿拉希盆地 Marks of Honor。把它们从战场带给战场外的战争使者。",h="一名部落战争使者向你索要三枚阿拉希盆地 Marks of Honor。把它们从战场带给战场外的战争使者。",kw={"阿拉希盆地","战场","部落战争使者","荣誉奖章"},sec={{t="战争使者的请求",b="战争使者在战场外等候，你可以把奖章带给他。部落要求你带来三枚阿拉希盆地 Marks of Honor。"}},faq={{q="部落战争使者想要什么？",a="部落战争使者要求你带来三枚阿拉希盆地 Marks of Honor。",al={"战争使者想要什么","要带什么","阿拉希盆地奖章"}},{q="我该把奖章带到哪里？",a="把奖章带给战场外的一名部落战争使者。",al={"奖章交到哪里","战争使者的位置","战场外"}},{q="需要多少枚 Marks of Honor？",a="你需要带来三枚阿拉希盆地 Marks of Honor。",al={"需要多少枚奖章","三枚奖章","奖章数量"}},{q="战争使者要的是哪种奖章？",a="他要的是阿拉希盆地 Marks of Honor。",al={"哪种奖章","阿拉希盆地奖章","荣誉奖章"}}},fp="23,129,22.149.0,36.73.0,27.64.0,35.57.0,40.47.0"}
P.entries["quest:8437"] = {n="资源竞赛",s="一名位于战场外的部落 Warbringer 要求你带来三枚阿拉希盆地 Marks of Honor。",h="一名位于战场外的部落 Warbringer 要求你带来三枚阿拉希盆地 Marks of Honor。",kw={"阿拉希盆地","战场","征服阿拉希盆地","部落 warbringer","mark of honor"},faq={{q="部落 Warbringer 想要什么？",a="部落 Warbringer 要求你带来三枚阿拉希盆地 Marks of Honor。",al={"warbringer 的要求","需要带什么"}},{q="我该把这些 Marks of Honor 交到哪里？",a="把 Marks of Honor 交给一名位于战场外的部落 Warbringer。",al={"marks of honor 交到哪里","warbringer 的位置"}},{q="需要多少枚 Marks of Honor？",a="你需要三枚阿拉希盆地 Marks of Honor。",al={"需要多少枚 marks of honor","三枚 marks of honor"}}},fp="23,97,36.73.0,27.64.0,35.43.0"}
P.entries["quest:84396"] = {n="《岩浆还是熔岩？》",s="詹妮亚·坎农正在收集魔法典籍，以扩充暴风城法师区的图书馆藏书。将新的著作收入馆藏，能丰富这座城市的奥术知识。",h="詹妮亚·坎农正在收集魔法典籍，以扩充暴风城法师区的图书馆藏书。将新的著作收入馆藏，能丰富这座城市的奥术知识。",kw={"奥术","馆藏","詹妮亚·坎农","图书馆","法师区","魔法典籍","岩浆或熔岩","暴风城"},sec={{t="书架上的新藏书",b="在暴风城法师区的巫师圣殿，詹妮亚·坎农正逐步建立奥术研究档案。旅行途中若发现魔法典籍，她便会请你将这些著作带到图书馆。每一部新典籍都能增进圣殿学者对世界的了解。"}},faq={{q="谁想要图书馆里的魔法典籍？",a="暴风城法师区的詹妮亚·坎农正在收集魔法典籍，以扩充图书馆的馆藏。",al={"图书馆的岩浆或熔岩","魔法典籍交到哪里","暴风城图书馆书籍"}},{q="馆藏需要收集什么？",a="旅人每次将魔法典籍和记录送到图书馆，馆藏都会有所增加。",al={"图书馆需要什么","他们收集什么"}},{q="图书馆为何需要这些典籍？",a="詹妮亚·坎农欢迎旅人带来魔法典籍，让圣殿的知识不断增长。",al={"为何把书带到图书馆","岩浆或熔岩的用途"}}},fp="14,171,21.280.0,39.99.0,42.92.0,41.100.0"}
P.entries["quest:84399"] = {n="Ka-Boom!",s="詹妮亚·坎农请你带回旅途中发现的魔法典籍。每一份捐赠都能充实暴风城法师区图书馆的藏书。",h="詹妮亚·坎农请你带回旅途中发现的魔法典籍。每一份捐赠都能充实暴风城法师区图书馆的藏书。",kw={"藏书","詹妮亚·坎农","ka-boom!","图书馆","法师区","魔法典籍","暴风城"},sec={{t="充实藏书",b="在暴风城的巫师圣殿中，詹妮亚·坎农致力于充实图书馆的奥术知识藏书。她请你把旅途中发现的魔法典籍带给她，让藏书不断丰富。"}},faq={{q="图书馆在寻找什么？",a="詹妮亚·坎农正在寻找魔法典籍，以充实图书馆的知识藏书。",al={"图书馆需要什么","带什么给图书馆","图书馆收集什么典籍"}},{q="谁在征集这些魔法典籍？",a="暴风城法师区的詹妮亚·坎农欢迎你为图书馆增添藏书，并请旅人将发现的魔法典籍送来。",al={"谁在征集魔法典籍","魔法典籍要送到哪里","谁在暴风城收集知识"}},{q="以后还能带来更多魔法典籍吗？",a="詹妮亚欢迎你把之后发现的魔法典籍带回法师区交给她，继续充实图书馆的藏书。",al={"要留下魔法书吗","还能带来更多书吗","发现魔法典籍后该怎么办"}}},fp="8,166,24.232.0,32.82.0,33.136.0,39.141.0"}
P.entries["quest:844"] = {n="平原陆行鸟的威胁",s="“陆行鸟的威胁”是十字路口的一项新手狩猎任务，由塞尔格拉·黑棘指派。刚抵达的部落冒险者会被派去捕杀那些翻找补给路线物资的本土陆行鸟，这既是为了除害，也是对狩猎技巧的初步考验。",h="“陆行鸟的威胁”是十字路口的一项新手狩猎任务，由塞尔格拉·黑棘指派。刚抵达的部落冒险者会被派去捕杀那些翻找补给路线物资的本土陆行鸟，这既是为了除害，也是对狩猎技巧的初步考验。",kw={"贫瘠之地","喙","十字路口","黑棘","狩猎","陆行鸟","塞尔格拉","补给"},ang={["class:Hunter"]="对于年轻的猎人来说，塞尔格拉的试炼是在广阔的草原上进行跟踪、追踪和击倒猎物的一项基本准则。",["faction:Horde"]="十字路口是一个重要的后勤枢纽，确保其食品补给不受野生动物的侵害，能保证部落在卡利姆多保持立足点。",["race:Orc"]="兽人崇尚狩猎纪律，塞尔格拉希望每一位新人在承担更重要的职责之前，都能在当地野兽身上证明自己的勇气。"},sec={{t="保卫十字路口",b="十字路口位于卡利姆多的后勤中心，协调着穿梭于贫瘠之地艰苦环境下的补给大篷车。然而，干旱的地形使得当地野生动物极度缺乏食物。成群高大、不会飞行的陆行鸟在哨所东侧游荡，开始啄食食品板条箱，威胁着定居点的生命线。为了保护这些脆弱的补给，萨满祭司塞尔格拉·黑棘派遣旅行者在这些凶猛的鸟类对哨所物资造成严重损害前将它们除掉。"},{t="初次狩猎",b="虽然害虫治理是一个直接的实际目标，但塞尔格拉认为陆行鸟是衡量新手的标尺。她认为这些鸟只是简单的猎物，旨在教导年轻的猎人如何在恶劣环境中生存，以及如何在被太阳炙烤的平原上追踪猎物。带回它们的陆行鸟的喙证明了猎人拥有面对贫瘠之地更凶猛野兽所需的耐心和基本的武力技巧。"}},faq={{q="为什么要针对陆行鸟？",a="十字路口东侧成群的陆行鸟变得胆大妄为，开始袭击食物补给并骚扰过往的补给线。塞尔格拉·黑棘下令捕杀它们，以保护定居点至关重要的补给。",al={"为什么要杀陆行鸟","陆行鸟问题","陆行鸟做了什么"}},{q="塞尔格拉·黑棘是谁？",a="塞尔格拉·黑棘是一位驻扎在十字路口的资深兽人萨满祭司。她负责监督定居点的狩猎试炼，训练新来的冒险者，并指挥他们对付威胁部落行动的野生猛兽。",al={"塞尔格拉是谁","塞尔格拉·黑棘的职责","十字路口任务发布者"}},{q="为什么塞尔格拉特别想要它们的喙？",a="坚硬锋利的陆行鸟的喙是陆行鸟的主要武器和觅食工具。取走它们的喙可以作为这些食腐鸟类已被杀死的无可辩驳的证据。",al={"为什么要陆行鸟的喙","陆行鸟的喙作为证明"}},{q="这次狩猎之后有什么？",a="一旦处理了陆行鸟，塞尔格拉就会让你去猎杀在平原上游荡的斑马，以此来测试你对付更敏捷、更具活力的猎物的能力。",al={"接下来是什么","陆行鸟任务后的下一个任务","狩猎顺序"}},{q="这些陆行鸟在哪里？",a="它们在十字路口正东和东南方向的稀树草原上游荡，沿着贸易路线觅食。",al={"陆行鸟在哪里","陆行鸟位置","狩猎场"}},{q="这是更大狩猎系列的一部分吗？",a="是的。这项任务标志着塞尔格拉·黑棘在贫瘠之地的狩猎试炼的起点，试炼难度将随着在草原上挑战越来越危险的野兽而逐渐升级。",al={"贫瘠之地狩猎链","塞尔格拉任务链"}}},fp="19,188,23.286.0,14.345.0,35.186.0,24.201.0,46.142.0,27.107.0,38.111.0,40.150.0"}
P.entries["quest:84400"] = {n="《骑士与女士》",s="铁炉堡的一位管理员请你带来可能有益于图书馆的魔法典籍。你的努力让馆藏不断丰富。",h="铁炉堡的一位管理员请你带来可能有益于图书馆的魔法典籍。你的努力让馆藏不断丰富。",kw={"馆藏","铁炉堡","管理员","知识","图书馆","魔法典籍"},sec={{t="不断丰富的馆藏",b="铁炉堡图书馆的一位管理员正在为馆藏搜寻魔法典籍。你可以带来可能有益于图书馆的典籍。随着知识不断增长，管理员也欢迎你继续添置藏品。"}},faq={{q="管理员想要什么？",a="管理员请你带来可能有益于图书馆馆藏的魔法典籍。",al={"他们想要什么","图书馆的请求","带来什么"}},{q="馆藏在哪里？",a="馆藏位于铁炉堡图书馆。",al={"图书馆在哪里","图书馆位置","铁炉堡图书馆"}},{q="为什么要带来魔法典籍？",a="管理员说，你的努力能扩充图书馆的知识。",al={"为什么要书籍","有什么用","帮助图书馆"}}},fp="23,122,20.192.0,26.87.0,24.46.0,24.60.0"}
P.entries["quest:845"] = {n="斑马的威胁",s="斑马是十字路口的一位叫塞尔格拉·黑刺的NPC发布的一项早期狩猎试炼。作为在贫瘠之地的草原上进行武技磨练的一部分，年轻的猎手们需要追踪敏捷的斑马跑者，并取回它们强有力的斑马蹄。",h="斑马是十字路口的一位叫塞尔格拉·黑刺的NPC发布的一项早期狩猎试炼。作为在贫瘠之地的草原上进行武技磨练的一部分，年轻的猎手们需要追踪敏捷的斑马跑者，并取回它们强有力的斑马蹄。",kw={"贫瘠之地","十字路口","斑马蹄","狩猎试炼","塞尔格拉·黑刺","斑马","斑马跑者"},ang={["class:Hunter"]="对于刚在贫瘠之地开始历练的射手和追踪者来说，潜行靠近敏捷的斑马群是进行追踪和精准射击的必要实地练习。",["faction:Horde"]="十字路口依赖来往的冒险者来控制周边的野生动物数量，以确保定居点的补给路线畅通无阻。",["race:Tauren"]="塞尔格拉特别指出，斑马的一踢就能将一头成年牛头人踢倒，这让这项试炼成为一个恰当的提醒：即使是草原上的食草动物也需要保持敬畏。"},sec={{t="草原上的进阶之路",b="在初步清理了贫瘠之地中那些泛滥的平原陆行鸟之后，塞尔格拉·黑刺会将新晋的部落勇士引向难度稍高的猎物。条纹斑马成群结队地游荡在北部和南部的平原上。虽然它们并非草原上的顶级掠食者，但这些奔跑迅速的群居野兽以其顽强的耐力和能踢碎骨头的强力踢击而闻名。"},{t="黑刺的试炼",b="对塞尔格拉来说，这次狩猎与其说是为了获取贸易物资，不如说是为了考验冒险者不断增长的实力。她要求取回四只完整的斑马蹄作为猎杀的实物证明，并警告说这种野兽的后踢力足以将一头成年牛头人踢翻在地。在这些敏捷的奔跑者面前证明自己，能让猎手获得参与后续挑战那些平原掠食者任务的资格。"}},faq={{q="谁发布了这次狩猎任务？",a="塞尔格拉·黑刺，一位驻扎在贫瘠之地中部十字路口的资深兽人萨满，发布了这项试炼来考验日益强大的部落勇士。",al={"谁发布斑马任务","斑马任务发布者","塞尔格拉·黑刺任务"}},{q="在哪里可以找到斑马？",a="斑马跑者在贫瘠之地中部的十字路口南北两侧的开阔平原上游荡。",al={"斑马跑者在哪里","斑马位置","贫瘠之地斑马地图"}},{q="塞尔格拉为什么要斑马蹄？",a="斑马蹄是干净利落完成狩猎的战利品证明。它们的腿部力量惊人，带回四只蹄子证明猎手可以制服一头足以击倒强壮牛头人的野兽。",al={"为什么需要斑马蹄","斑马蹄证明","为什么狩猎斑马"}},{q="这个任务之后是什么？",a="在证明了你对抗斑马的能力后，塞尔格拉会让你在“贫瘠之地的掠食者”任务中挑战真正的掠食者。",al={"斑马任务后的下一个任务","斑马任务后续","黑刺的下一个任务"}},{q="斑马危险吗？",a="虽然通常是温顺的食草动物，但斑马拥有惊人的腿部力量。塞尔格拉警告说，受到惊吓或走投无路的斑马跑者踢出的一脚，足以将一头强壮的牛头人踢翻在地。",al={"斑马有多危险","斑马危险性","斑马踢击"}},{q="为什么之前要猎杀平原陆行鸟？",a="塞尔格拉将她的试炼安排为难度循序渐进的过程。平原陆行鸟作为最初的打靶练习，而斑马则要求在进阶到好斗的草原掠食者之前，应对更快速、更强壮的猎物。",al={"上一个任务","平原陆行鸟的威胁关联"}}},fp="10,144,24.232.0,23.248.0,22.129.0,27.93.0,35.145.0,28.116.0,22.164.0,42.169.0"}
P.entries["quest:846"] = {n="加恩的报复",s="加恩的复仇是南贫瘠之地的一个部落任务，在那儿，悲痛的牛头人流亡者加恩·石塔正计划向巴尔莫丹探险队进行报复。在除掉勘探员卡兹格姆后，加恩指引旅行者潜入这座矮人要塞，收集挥发性的弹药，准备进行一场爆炸性的反击。",h="加恩的复仇是南贫瘠之地的一个部落任务，在那儿，悲痛的牛头人流亡者加恩·石塔正计划向巴尔莫丹探险队进行报复。在除掉勘探员卡兹格姆后，加恩指引旅行者潜入这座矮人要塞，收集挥发性的弹药，准备进行一场爆炸性的反击。",kw={"巴尔莫丹","贫瘠之地","炸药","爆炸物","加恩·石塔","铁炉堡","卡兹格姆","硝化甘油","硝酸钠","木浆"},ang={["faction:Horde"]="消除南贫瘠之地的矮人行动，可以防止联盟建立军事滩头阵地，切断莫高雷、十字路口和南部边境之间的交通。",["profession:Engineering"]="硝化甘油、硝酸钠和木浆的组合展示了典型的矮人工业炸药配方，并被临时改装用于非对称作战。",["race:Tauren"]="对牛头人来说，巴尔莫丹代表了对地母神的严重伤害，这使得破坏矮人的机器成为了一项精神和领土上的职责。"},sec={{t="以其人之道还治其人之身",b="勘探员卡兹格姆的死让巴尔莫丹挖掘场遭受了挫折，但加恩·石塔知道这只是暂时的。矮人的行动很少会长期停滞，很快就会有新的工头到来，继续监管那些正在摧毁他祖辈领地的机器。加恩拒绝坐视大地继续遭受挖掘，他决心利用侵略者自己的技术进行反击。他计划将他们的爆破装备变成破坏工具，从内部摧毁他们的堡垒。"},{t="突袭要塞",b="巴尔莫丹要塞既是挖掘基地，也是加固的驻军营地，配备了士兵、火枪手和军官，以保卫矮人在贫瘠之地的利益。加恩发现，守军储存了适合工业爆破的材料：硝化甘油、木浆和硝酸钠。他派遣部落盟友潜入外围，直接从矮人守军手中夺取这些挥发性成分，收集足够的原材料来组装一个毁灭性的炸药包。"}},faq={{q="加恩·石塔为什么要寻求复仇？",a="巴尔莫丹的铁炉堡矮人占领了加恩祖辈的家园，玷污了土地，并将他的族人驱逐出去，从而建立了他们的挖掘场。在杀死了首席勘探员并找回他的日志后，加恩旨在永久停止他们持续的破坏行为。",al={"加恩愤怒的原因","加恩·石塔的动机","矮人对加恩做了什么"}},{q="在哪里可以找到爆炸材料？",a="这些配料由保卫巴尔莫丹的矮人人员携带。南贫瘠之地加固挖掘场内外的火枪手、士兵和军官都携带着硝化甘油药剂瓶、木浆包和硝酸钠样本。",al={"哪里可以获得硝化甘油","如何获得木浆","硝酸钠在哪里"}},{q="为什么加恩需要木浆和化学品？",a="矮人的挖掘图纸显示，用木浆稳定不稳定的硝化甘油，并将其与硝酸钠混合，可以产生一种可靠的工业炸药。加恩打算制作一种定制的爆破装药，用以炸毁矮人的关键设施。",al={"为什么要木浆","加恩在制造什么","加恩的炸弹原料"}},{q="收集完补给品后会发生什么？",a="一旦你带回了原材料，加恩就会组装一个爆炸装药，并指派你去用它炸毁巴尔莫丹挖掘场里的矮人飞行器，那是该设施基础设施的关键部分。",al={"加恩的复仇之后是什么","收集完材料之后"}},{q="为什么杀了卡兹格姆并不能终结矮人的威胁？",a="卡兹格姆只是首席勘探员。巴尔莫丹的矮人军事存在已经根深蒂固，有防御墙和补给线加固。除非整个基地遭受毁灭性打击，否则铁炉堡只会派另一个工头来继续挖掘。",al={"为什么杀掉卡兹格姆没用","巴尔莫丹被阻止了吗"}},{q="巴尔莫丹对部落构成了怎样的战略威胁？",a="虽然其要塞最初是为保卫挖掘场而建，但巴尔莫丹已经扩张成了一个拥有重兵把守的联盟堡垒。它位于南贫瘠之地的贸易路线旁，对附近的卡利姆多部落定居点构成了活跃的军事威胁。",al={"部落为什么要关心巴尔莫丹","巴尔莫丹的威胁"}}},fp="15,210,29.372.0,16.376.0,39.259.0,40.216.0,43.251.0,42.200.1,52.222.0,51.231.0"}
P.entries["quest:8462"] = {n="与纳菲恩交谈",s="Nafien在费伍德森林的木喉要塞外站岗。你需要沿主路向北，找到他并与他交谈。",h="Nafien在费伍德森林的木喉要塞外站岗。你需要沿主路向北，找到他并与他交谈。",kw={"费伍德森林","熊怪","主路","nafien","木喉要塞"},sec={{t="北行之路",b="在费伍德森林，Nafien在木喉要塞入口外守望。你需要沿主路向北找到他。"}},faq={{q="Nafien是谁？",a="Nafien是一名熊怪，驻守在木喉要塞入口外。",al={"nafien","nafien是谁"}},{q="我在哪里能找到Nafien？",a="Nafien在费伍德森林的木喉要塞入口外，沿着北面的主路即可找到。",al={"nafien的位置","nafien在哪里"}},{q="我需要做什么？",a="沿费伍德森林的主路向北，与Nafien交谈。",al={"与nafien交谈","nafien任务"}}},fp="15,124,10.136.0,14.76.0,24.98.0,22.61.0"}
P.entries["quest:8465"] = {n="Speak to Salfa",s="Salfa在木喉要塞外守望。你受托穿过要塞，在冬泉谷与他交谈。",h="Salfa在木喉要塞外守望。你受托穿过要塞，在冬泉谷与他交谈。",kw={"入口","守卫","salfa","交谈","木喉要塞","冬泉谷"},sec={{t="要塞外",b="Salfa在木喉要塞外站岗等候。你受托穿过要塞，进入冬泉谷后与他交谈。"}},faq={{q="Salfa是谁？",a="Salfa在木喉要塞入口外站岗。",al={"salfa是谁"}},{q="我在哪里能找到Salfa？",a="Salfa在冬泉谷的木喉要塞入口外站岗。",al={"salfa的位置","salfa在哪里"}},{q="Salfa要我做什么？",a="你受托穿过木喉要塞，进入冬泉谷后与Salfa交谈。",al={"与salfa交谈的任务","salfa要做什么"}}},fp="14,116,11.139.0,13.58.0,23.75.0,30.93.0"}
P.entries["quest:8467"] = {n="给纳菲恩的羽毛",s="Nafien正在收集羽毛，你找到的每一根羽毛他都欣然接受。作为回报，他承诺会在族人中传扬你的善举。",h="Nafien正在收集羽毛，你找到的每一根羽毛他都欣然接受。作为回报，他承诺会在族人中传扬你的善举。",kw={"善举","羽毛","nafien","献礼","声望"},sec={{t="羽毛献礼",b="Nafien在野外寻找羽毛，并以族人的好感作为回报。每当你找到这些羽毛，他都会欣然收下，并承诺你的援助很快就会传遍族群。"}},faq={{q="Nafien是谁？",a="Nafien是个生物，他承诺以羽毛为交换，在族人中传扬你的善举。",al={"nafien是谁","nafien的身份"}},{q="Nafien为什么要羽毛？",a="Nafien需要羽毛，并承诺每当你带来一捆，就会向族人传扬你提供的援助。",al={"为何收集羽毛","羽毛的用途","羽毛有什么用"}},{q="Nafien还会收下更多羽毛吗？",a="只要他的族人仍然需要羽毛，Nafien就会收下你能找到的所有羽毛。",al={"更多羽毛","能否再带羽毛来","重复交羽毛"}}},fp="19,177,20.220.0,14.101.0,30.117.0,39.88.0"}
P.entries["quest:847"] = {n="迅猛龙的狡诈",s="在托尔甘的宝珠赋予了戈穆尔迅猛龙的精华后，他所感受到的力量让他开始思考萨满祭司的魔法。他让你去告诉托尔甘，他暂时被说服了，并且愿意听听看。",h="在托尔甘的宝珠赋予了戈穆尔迅猛龙的精华后，他所感受到的力量让他开始思考萨满祭司的魔法。他让你去告诉托尔甘，他暂时被说服了，并且愿意听听看。",kw={"阿拉希高地","戈穆尔","迅猛龙的狡诈","落锤镇","萨满祭司","托尔甘"},sec={{t="被说服的战士",b="戈穆尔大声思索着在他体内奔涌的力量是否就是托尔甘试图展示给他的萨满祭司之力。他觉得这很有意思。他让你去告诉托尔甘，他暂时被说服了，并且愿意听听托尔甘要说什么。"},{t="托尔甘的答复",b="托尔甘说一旦附魔效果消失，他就会与戈穆尔交谈。他感谢你帮助戈穆尔重获新生，并相信戈穆尔也会心存感激。"}},faq={{q="是谁派你去和托尔甘交谈的？",a="是戈穆尔。在感受到宝珠的力量后，他让你去告诉托尔甘，他暂时被说服了。",al={"谁开启了迅猛龙的狡诈3","谁发布了这个任务","任务起始地点"}},{q="为什么戈穆尔改变了对托尔甘的看法？",a="他想知道自己感受到的力量是否就是托尔甘试图展示给他的萨满祭司之力，他觉得这很有趣。他暂时被说服了，愿意听听托尔甘的说法。",al={"为什么戈穆尔改变了主意","戈穆尔萨满魔法","戈穆尔被说服了吗"}},{q="这一步之前发生了什么？",a="这是在你将托尔甘的宝珠带给戈穆尔之后进行的步骤。",al={"前置任务","迅猛龙的狡诈先决条件"}}},fp="19,142,19.218.0,15.169.1,36.115.0,47.176.0,27.57.0"}
P.entries["quest:848"] = {n="菌类孢子",s="皇家药剂师学会的药剂师赫布瑞姆派遣部落冒险者在贫瘠之地的各处绿洲收集菌类孢子。这些泉水中流动的奇异变异能量将当地植物转化为了强效试剂。赫布瑞姆试图收集这些独特的样本，为他在雷霆崖的同事酿制药剂。",h="皇家药剂师学会的药剂师赫布瑞姆派遣部落冒险者在贫瘠之地的各处绿洲收集菌类孢子。这些泉水中流动的奇异变异能量将当地植物转化为了强效试剂。赫布瑞姆试图收集这些独特的样本，为他在雷霆崖的同事酿制药剂。",kw={"药剂师赫布瑞姆","药剂师扎玛","贫瘠之地","十字路口","遗忘之池","菌类孢子","甜水绿洲","皇家药剂师学会","死水绿洲"},ang={["class:Druid"]="这些绿洲蕴含着一股极不寻常的狂暴自然魔法，导致周围的生态系统发生了剧烈的变异。",["faction:Horde"]="调查贫瘠之地受干扰的水域有助于保护连接奥格瑞玛、十字路口和雷霆崖的重要路线。",["profession:Herbalism"]="生长在贫瘠之地绿洲周围的多产蘑菇展示了环境能量的突然注入是如何将普通植物转化为强效试剂的。",["race:Undead"]="即使远离洛丹伦，被遗忘者的研究人员依然在继续他们的炼金工作，利用卡利姆多的自然异常现象来实现皇家药剂师学会的目标。"},sec={{t="充满活力且变异的植物",b="贫瘠之地通常是一片干旱、被烈日炙烤的热带草原，但其绿洲——例如遗忘之池、甜水绿洲和死水绿洲——却充满了非自然的活力。一股奇异的生命能量从这些水中流出，扭曲并增强了饮用这些水的植物和野兽。生长在泥泞岸边的多产蘑菇吸收了这些强烈的能量流，使它们的孢子充满了稀有的特性，引起了路过炼金术士的好奇。"},{t="卡利姆多的皇家药剂师学会",b="尽管药剂师赫布瑞姆驻扎在远离幽暗城的十字路口，但他依然致力于皇家药剂师学会的研究。他认识到了卡利姆多本土试剂的奇异效力，于是收集这些变异孢子来调制强力混合剂。这里收集的样本将送往雷霆崖的药剂师扎玛手中，这展现了被遗忘者在盟友领地中进行的深远而隐秘的科学研究。"}},faq={{q="这些菌类孢子生长在哪里？",a="这些孢子可以从贫瘠之地各绿洲水边生长的多产蘑菇上采集，包括遗忘之池、甜水绿洲和死水绿洲。",al={"菌类孢子位置","菌类孢子获取地点","多产蘑菇位置"}},{q="为什么绿洲附近的蘑菇发生了变异？",a="一股强大的生命能量流经贫瘠之地的绿洲水域。这种能量并非维持正常的植物生长，而是强力地刺激并改变了周围的野生动物和植物。",al={"蘑菇为何变异","绿洲生命能量","绿洲异常原因"}},{q="药剂师赫布瑞姆是谁？",a="药剂师赫布瑞姆是被遗忘者皇家药剂师学会的一名成员，驻扎在贫瘠之地的十字路口。他研究该地区不寻常的生物学特性，并采集当地材料用于炼金研究。",al={"赫布瑞姆背景故事","赫布瑞姆是谁","十字路口的药剂师"}},{q="赫布瑞姆打算用这些孢子做什么？",a="赫布瑞姆利用这些强效孢子调制一种特定的混合剂，并打算将其送给他在牛头人城市雷霆崖的研究伙伴——药剂师扎玛。",al={"孢子的用途","菌类孢子的目的"}},{q="为什么被遗忘者的药剂师会在贫瘠之地活动？",a="作为部落联盟的一部分，被遗忘者的研究人员会研究卡利姆多各地的陌生环境和独特植物，以发现用于药物、毒药和混合剂的新试剂。",al={"亡灵为何在贫瘠之地","卡利姆多的皇家药剂师学会"}},{q="从哪个绿洲采集孢子最安全？",a="位于十字路口西北方向的遗忘之池，相比南边的甜水绿洲或死水绿洲，其野生生物等级较低，因此是采集蘑菇最安全的地方。",al={"最简单的孢子采集地","贫瘠之地最安全的绿洲"}}},fp="13,297,25.365.0,40.385.0,34.129.0,45.170.0,26.205.0,45.124.0,55.155.0,49.175.0"}
P.entries["quest:849"] = {n="加恩的报复",s="“加恩的复仇”标志着加恩·石塔对巴尔莫丹的矮人实施的最后一次打击。部落的一名特工带着一份根据窃取的矮人图纸制造的定制炸药，被委派去炸毁探险队引以为傲的飞行器，以此为覆灭的石塔部族复仇。",h="“加恩的复仇”标志着加恩·石塔对巴尔莫丹的矮人实施的最后一次打击。部落的一名特工带着一份根据窃取的矮人图纸制造的定制炸药，被委派去炸毁探险队引以为傲的飞行器，以此为覆灭的石塔部族复仇。",kw={"巴尔莫丹","加恩的雷管","飞行器","加恩·石塔","卡兹格姆","石塔部族","贫瘠之地","雷霆崖"},ang={["faction:Horde"]="破坏巴尔莫丹的飞行器可以解除联盟一种能够深入侦察和打击南贫瘠之地的空中武器。",["profession:Engineering"]="用于飞行器的炸药是利用铁炉堡的蓝图针对旋翼机制造的，这是一次充满讽刺意味的战地破坏杰作。",["race:Tauren"]="通过摧毁矮人的战争机器来为石塔氏族复仇，这能引起任何保卫祖传家园免遭亵渎的牛头人的深刻共鸣。"},sec={{t="统治的象征",b="巴尔莫丹的挖掘行动不仅仅是一次侵入性的采矿作业，它还是一座武装堡垒，直接建立在流离失所的石塔牛头人祖传的土地之上。对于探矿者们的作战范围和军事实力而言，他们的旋翼机飞行器是关键所在。这架机械飞行器驻扎在挖掘场上方的哨塔上，负责监视周围的贫瘠之地，保护补给线，并作为联盟悍然入侵卡利姆多土地的空中象征。"},{t="以彼之道，还施彼身",b="在找回了探矿者卡兹格姆的图纸后，加恩·石塔制作了一种名为“加恩的雷管”的特殊炸药。通过将这种易爆的弹药安放在飞行器上，加恩确保了矮人的技术傲慢将成为导致他们失败的原因。随之而来的爆炸摧毁了一个重要的军事资产，给巴尔邓小队造成了羞辱性的打击，并告慰了覆灭部族的英灵。"}},faq={{q="为什么加恩专门要摧毁那架飞行器？",a="这架飞行器既是战争武器，也是巴尔莫丹基础设施的关键部分，为矮人提供了空中侦察能力。对于加恩来说更重要的是，它是矮人权力的鲜明标志，更是高耸在屠戮他部族的故土之上的羞辱性存在。",al={"为什么要摧毁旋翼机","飞行器的用途","为什么要以飞行器为目标"}},{q="飞行器位于巴尔莫丹的什么位置？",a="飞行器停在通往主要挖掘坑的坡道中途的一个木制塔台上，而不是位于矮人的主要堡垒内部或旁边。",al={"飞行器在哪里","飞行器的位置","巴尔莫丹旋翼机的位置"}},{q="加恩是如何制造这个爆炸装置的？",a="加恩利用最近从探矿者卡兹格姆那里找回的技术图纸和工程规划，制造了加恩的雷管，将矮人自己的设计转而用来对付他们。",al={"炸药是如何制造的","加恩的雷管的来源","卡兹格姆的爆炸图纸"}},{q="加恩属于哪个部族？",a="加恩属于石塔部族，这是一个历史上居住在南贫瘠之地的牛头人氏族，直到铁炉堡的矮人挖掘队暴力驱逐了他们并摧毁了他们的定居点。",al={"加恩所属部族","石塔部族是什么","石塔牛头人是谁"}},{q="摧毁这架机器能永久停止挖掘吗？",a="这严重削弱了巴尔莫丹的空中优势和基础设施，同时也让加恩完成了个人复仇，但那些盘踞在此的矮人挖掘者和他们的堡垒仍然是联盟在该地区的一个活跃据点。",al={"巴尔莫丹停止挖掘了吗","巴尔莫丹会陷落吗","加恩成功了吗"}},{q="完成这个任务后，加恩会给予什么认可？",a="加恩宣称，摧毁了飞行器的英雄将在雷霆崖受到崇敬，被视为神圣的牛头人土地的捍卫者和他覆灭部族的永恒勇士。",al={"加恩任务完成","加恩任务结束","加恩说了什么"}}},fp="15,139,22.352.0,22.343.1,62.197.0,50.143.0,41.172.0,31.181.0,60.216.0,61.156.1"}
P.entries["quest:85"] = {n="丢失的项链",s="“丢失的项链”是艾尔文森林南部的一个入门级任务，由波尼斯·斯通菲尔德姑妈发布。波尼斯怀疑是对头的那个淘气的孩子偷走了她的项链，于是派遣冒险者穿过马路去质问比利·马科伦，并找回她遗失的传家宝。",h="“丢失的项链”是艾尔文森林南部的一个入门级任务，由波尼斯·斯通菲尔德姑妈发布。波尼斯怀疑是对头的那个淘气的孩子偷走了她的项链，于是派遣冒险者穿过马路去质问比利·马科伦，并找回她遗失的传家宝。",kw={"波尼斯","比利","艾尔文","农场","马科伦","项链","斯通菲尔德","葡萄园"},ang={["faction:Alliance"]="对于在艾尔文森林开始职业生涯的联盟新手来说，调解斯通菲尔德和马科伦这两家吵架不断的邻居之间的琐事，是体验当地边境生活的一个缩影。",["race:Human"]="斯通菲尔德和马科伦之间的积怨表明，暴风城的冲突并非都来自迪菲亚盗贼或豺狼人战团；老派的乡村邻里纠纷同样根深蒂固。"},sec={{t="邻里的指责",b="斯通菲尔德和马科伦两家在艾尔文森林南部毗邻而居，但两家之间的关系十分冷淡。当波尼斯·斯通菲尔德姑妈发现她珍贵的项链不见了时，她毫不犹豫地指责是对头家的那个小儿子干的。这位满腹怨气的寡妇坚信是小比利·马科伦溜进她的农场偷走了首饰，于是请求过路的旅行者去葡萄园找到那个男孩，并要求他交还物品。"},{t="贪吃的男孩",b="在隔壁的葡萄园找到比利·马科伦后，事情很快变得复杂起来。比利愤愤不平地否认他偷了项链，声称自己不是小偷。不过，他露出了狡黠的笑容，暗示他可能知道这件首饰的下落——前提是得先有人能填饱他那咕咕叫的肚子，送来一个新鲜的猪肉馅饼。"}},faq={{q="波尼斯·斯通菲尔德姑妈是谁？",a="波尼斯·斯通菲尔德姑妈是一位住在艾尔文森林南部斯通菲尔德农场的老寡妇。她对邻居马科伦一家深表怀疑，尤其是他们那个爱惹麻烦的小儿子比利。",al={"波尼斯姑妈是谁","波尼斯·斯通菲尔德","谁发布丢失的项链任务"}},{q="比利·马科伦真的偷了项链吗？",a="当被质问时，比利断然否认自己是个小偷。他暗示自己可能知道是谁拿走了项链，但他拒绝在吃饱之前透露这个秘密。",al={"比利是小偷吗","是比利偷的吗","比利拿走项链了吗"}},{q="我在哪里能找到比利·马科伦？",a="比利·马科伦通常在马科伦农场的葡萄藤间游荡，那里就在斯通菲尔德农场穿过马路往东一点的地方。",al={"比利·马科伦位置","比利在哪里","寻找比利·马科伦"}},{q="为什么斯通菲尔德一家和马科伦一家互相厌恶？",a="这两家邻居多年来一直陷入一场激烈的乡村世仇之中。双方因财产、自尊和长期积怨而关系紧张，导致彼此总是第一时间把对方往坏处想。",al={"家庭世仇","斯通菲尔德和马科伦的积怨","他们为什么互相讨厌"}},{q="与比利·马科伦交谈后会发生什么？",a="比利坚持说他饿得想不起来项链去哪儿了，这会让你回去找波尼斯姑妈做一个猪肉馅饼来交换情报。",al={"接下来做什么","丢失的项链后续","下一个任务"}},{q="这个任务发生在哪里？",a="任务完全发生在艾尔文森林南部，需要在斯通菲尔德农场和邻近的马科伦农场之间往返。",al={"任务区域","丢失的项链在哪里"}}},fx={b7900c48={q="波尼斯老太太为什么想找回项链？",a="波尼斯老太太是一位年迈的寡妇，那条项链是她极为珍视的私人物品。项链丢失让她十分苦恼，她立刻怀疑是隔壁仇家的小比利·马科伦偷走了它。找回这件传家宝，能让一位年迈的寡妇重获安心，心中得到些许温暖。",al={"波尼斯为什么要项链","波尼斯要项链的动机","斯通菲尔德项链的重要性"}},["27b02d6f"]={q="波尼斯老太太为什么不亲自找比利·马科伦对质？",a="斯通菲尔德和马科伦家族两家的积怨极深，双方几乎无法心平气和地交谈，稍一开口就可能引发斗殴。波尼斯无法直接亲自前往马科伦农场，而暴风城的卫兵忙于应付豺狼人和迪菲亚匪徒，根本无暇调解相邻农户间的琐碎争执。一位路过的冒险者正好可以作为中立者，直接询问那个男孩。",al={"波尼斯为什么需要我","为什么派冒险者去找比利","为什么不找暴风城卫兵"}}},fp="13,169,23.376.0,22.225.1,33.196.0,46.144.1,31.117.0,55.206.0,44.156.1,33.102.0"}
P.entries["quest:850"] = {n="科卡尔首领",s="“半人马领袖”任务开启了一场由兽人雷加·死门领导的战役，旨在粉碎贫瘠之地日益猖獗的半人马督军。游牧的考卡尔部族世代困扰着牛头人，但新崛起的酋长们正在将这些松散的部族组织成真正的军事威胁。雷加派遣部落的勇士在遗忘之池铲除巴拉克·科多班，以防他的影响力继续扩张。",h="“半人马领袖”任务开启了一场由兽人雷加·死门领导的战役，旨在粉碎贫瘠之地日益猖獗的半人马督军。游牧的考卡尔部族世代困扰着牛头人，但新崛起的酋长们正在将这些松散的部族组织成真正的军事威胁。雷加派遣部落的勇士在遗忘之池铲除巴...",kw={"巴拉克","贫瘠之地","半人马","十字路口","死门","遗忘之池","科多班","考卡尔","雷加"},ang={["faction:Horde"]="贫瘠之地的十字路口是连接莫高雷、杜隆塔尔以及更远处的部落据点的生命线。消灭考卡尔的首领可以保护脆弱的补给商队免受毁灭性的伏击。",["race:Orc"]="萨尔曾承诺部落会保卫牛头人，而像雷加·死门这样的老兵严肃地对待这一血誓，将半人马好战者视为对兽人在贫瘠之地统治权的直接战略威胁。",["race:Tauren"]="对牛头人来说，击杀考卡尔的指挥官是关乎生存与复仇的问题。在部落于卡利姆多建立据点之前，半人马部族屠杀了无数牛头人部落，并将舒哈鲁人从他们祖传的牧场上驱逐了数十年。"},sec={{t="旱地上的威胁",b="多年来，马身的半人马一直恐吓着卡利姆多，在萨尔的部落到来扭转战局之前，他们几乎将游牧的牛头人逼入绝境。在贫瘠之地，占据统治地位的考卡尔部族通常以分散的劫掠小队形式活动。然而近来，好战的酋长们开始联合这些分散的队伍，将简单的劫掠小队变成了一股有组织的军事力量，足以威胁到部落的坚固据点。"},{t="斩首行动",b="驻扎在十字路口以西营地的兽人战士雷加·死门意识到，考卡尔部族非常依赖虚张声势和蛮力来维持凝聚力。如果没有强有力的指挥官，他们的袭击者就会陷入内斗。为了挫败他们的推进，雷加指示部落的冒险者“擒贼先擒王”，从巴拉克·科多班开始。这个野心勃勃的领袖正驻扎在遗忘之池那郁郁葱葱的水源附近。"},{t="众人的首领",b="击杀巴拉克·科多班对北部的考卡尔营地是一个重大打击，但雷加知道巴拉克只是更大规模运动的先锋。他的死仅仅是拆解考卡尔高层指挥体系这一协同战役的开端，也为后续在贫瘠之地追猎其他酋长——苦行者沃罗格和赫兹鲁·血印铺平了道路。"}},faq={{q="谁是巴拉克·科多班？",a="巴拉克·科多班是一位凶猛的考卡尔半人马领袖，他在十字路口北部的遗忘之池聚集了一群劫掠者。他以狡诈和残忍著称，通过将零散的部族组织起来对部落构成进攻威胁，这使他比普通的游牧掠夺者危险得多。",al={"巴拉克","谁是巴拉克","巴拉克·科多班背景"}},{q="我在哪里可以找到巴拉克·科多班？",a="巴拉克·科多班在遗忘之池建立了一个营地。遗忘之池是一片绿洲，位于贫瘠之地中部的十字路口以北。他的周围通常有忠诚的考卡尔卫兵守护。",al={"巴拉克位置","巴拉克在哪里","遗忘之池巴拉克"}},{q="谁是雷加·死门？",a="雷加·死门是一位驻扎在十字路口以西的一个小型地堡营地的兽人老兵。他负责监视贫瘠之地内半人马的动向，并策划先发制人的打击，以保护部落定居点免受有组织的突袭。",al={"雷加","谁发布半人马领袖任务","雷加·死门背景"}},{q="为什么考卡尔部族对部落来说是个大问题？",a="半人马世代对牛头人进行着冷酷的、近乎种族灭绝的战争。作为部落的正式成员，牛头人依赖他们的盟友来协助保卫他们祖祖辈辈的狩猎场和横跨贫瘠之地的贸易路线，以防止半人马的持续扩张。",al={"为什么要与考卡尔战斗","考卡尔威胁","半人马与部落的敌对关系"}},{q="巴拉克死后会发生什么？",a="击败巴拉克·科多班后显示，其他酋长正在贫瘠之地的其他地方集结部队。雷加会立即派遣你去死水绿洲暗杀苦行者沃罗格，随后去甜水绿洲暗杀赫兹鲁·血印，最终抵御一场来自考卡尔部族的直接突袭。",al={"巴拉克之后的下一个任务","半人马领袖后续","接下来是什么"}},{q="为什么考卡尔部族聚集在绿洲周围？",a="在贫瘠之地干旱的气候下，水和肥沃的土地是珍贵的宝藏。通过占领遗忘之池这样的天然泉水，考卡尔部族不仅获得了必需的水源，还能剥夺旅行者和牛头人猎手这些具有战略意义的休息点。",al={"为什么半人马在绿洲","考卡尔水源","遗忘之池半人马"}}},fx={["55ee765d"]={q="雷戈萨·死门为什么要杀死科卡尔酋长？",a="半人马部族世世代代都在骚扰牛头人，但贫瘠之地的科卡尔人通常各自为战，组织松散。最近，几位颇具魅力的酋长开始召集四散的战团，联合起来威胁部落的定居点。雷戈萨知道，如果任由这些新兴指挥官组织起来，部落在贫瘠之地建立的据点就可能土崩瓦解。除掉科多班恩·巴拉克这样的人物，便能在起义席卷地方防线之前打击其首领。",al={"为什么杀死科卡尔首领","雷戈萨·死门的动机","雷戈萨为什么要办这件事"}},["4347847a"]={q="巴拉克的头颅有什么用？",a="雷戈萨需要无可辩驳的证据，证明半人马指挥官已经倒下。在贫瘠之地这片严酷的边境，传闻和口头说法不足以确保安全。带回巴拉克被割下的头颅，便能确认驻扎在遗忘之池附近的科卡尔战团确实失去了首领，也无力再协调后续袭击。",al={"为什么要巴拉克的头颅","巴拉克头颅的用途","巴拉克的头颅要怎么处理"}}},fp="14,323,31.376.0,22.400.0,17.282.1,22.270.0,32.143.0,25.212.0,48.271.0,35.253.1,42.224.0"}
P.entries["quest:851"] = {n="狂热的维罗戈",s="维罗戈·德维什是一位行踪诡秘的考尔克半人马领袖，游荡在贫瘠之地的南部平原。为了终结他的突袭，雷加尔·死亡之门指示部落勇士突袭死水绿洲的半人马指挥帐篷，迫使这位游牧指挥官现身。",h="维罗戈·德维什是一位行踪诡秘的考尔克半人马领袖，游荡在贫瘠之地的南部平原。为了终结他的突袭，雷加尔·死亡之门指示部落勇士突袭死水绿洲的半人马指挥帐篷，迫使这位游牧指挥官现身。",kw={"贫瘠之地","半人马","十字路口","德维什","考尔克","雷加尔·死亡之门","死水绿洲","维罗戈"},ang={["faction:Horde"]="控制绿洲对于在干旱的贫瘠之地生存至关重要；清除半人马指挥官可以确保补给商队的水路畅通。",["race:Orc"]="雷加尔·死亡之门认为，消灭考尔克战帅对于保障杜隆塔尔旅行者往返十字路口与石爪山脉之间的道路安全至关重要。",["race:Tauren"]="考尔克人在这片平原上猎杀并骚扰游牧的牛头人已有数代之久，因此，像处决维罗戈这样的领袖早已成为众人期盼已久的复仇。"},sec={{t="引诱德维什",b="在巴拉克·科多班倒台后，兽人战士雷加尔·死亡之门将目标对准了考尔克部族剩余的战帅。与在遗忘之池北部水域附近徘徊的巴拉克不同，维罗戈·德维什游荡在被烈日炙烤的广袤平原上，很少在同一个营地停留太久。在广袤的土地上追踪他纯属徒劳，这使得部落侦察兵只剩下一种可行的策略：强迫这位指挥官主动现身。"},{t="死水绿洲",b="维罗戈坐镇在十字路口东南方死水绿洲的半人马指挥所。雷加尔指示冒险者直接突袭该营地，斩杀指挥帐篷附近的考尔克战士，直到恐慌促使他们吹响号角。这一战术利用了半人马的傲慢——只要在他们的领地上屠杀足够多的维罗戈下属，这位德维什就会赶回支援他的哨所，自投罗网，撞进部落早已准备好的利刃之中。"}},faq={{q="维罗戈·德维什是谁？",a="维罗戈·德维什是贫瘠之地考尔克半人马的一名游荡战帅。他负责指挥死水绿洲的行动，但大部分时间都在南部的荒野中徘徊，这让他很难被直接围困。",al={"谁是维罗戈","维罗戈背景故事","维罗戈·德维什"}},{q="为什么维罗戈不待在营地里？",a="正如他“德维什”的称号一样，维罗戈是一位游牧领袖，他频繁往来于贫瘠之地的荒凉地带，而不是无所事事地坐在某个营地里。这种机动的特性使他免受部落有组织围剿的威胁，迫使他的敌人必须激怒他才能看到他的真身。",al={"维罗戈在哪里","为什么维罗戈要游荡","维罗戈失踪"}},{q="如何召唤维罗戈？",a="当他的族群受到威胁时，维罗戈会被引回指挥所。通过攻击死水绿洲那座醒目的指挥帐篷周围聚集的半人马，冒险者可以制造足够的混乱，迫使幸存的考尔克发出警报，从而促使维罗戈飞奔回防他的帐篷。",al={"如何刷新维罗戈","寻找维罗戈","维罗戈没出现"}},{q="是谁下令处死维罗戈的？",a="雷加尔·死亡之门，一位驻扎在十字路口西侧、通往石爪山脉主路旁的兽人老兵，下令处决维罗戈。他试图通过有条不紊地猎杀每一位区域指挥官来击溃考尔克部族的脊梁。",al={"谁发布的任务","雷加尔·死亡之门"}},{q="维罗戈倒下后会发生什么？",a="将维罗戈的断头带回给雷加尔，兽人会将它与巴拉克·科多班的头颅放在一起收藏。随后，雷加尔会将目标锁定在南方甜水绿洲的半人马战帅——赫兹鲁尔·血印。",al={"接下来是什么","维罗戈之后"}},{q="为什么考尔克半人马在贫瘠之地是个大问题？",a="考尔克是极具侵略性的领土掠食者，他们占据了贫瘠之地各处至关重要的水源。他们频繁突袭商队、哨所和当地的牛头人兽群，对卡利姆多中部羽翼未丰的部落势力构成了直接的生存威胁。",al={"为什么要对抗考尔克","考尔克威胁"}}},fp="17,236,23.334.0,18.273.0,25.141.0,35.159.0,24.147.0,25.187.0,31.193.1,57.195.0"}
P.entries["quest:852"] = {n="赫兹鲁尔·血印",s="“赫兹鲁尔”是兽人老兵雷戈萨·死门委派的一项任务，旨在消灭贫瘠之地考尔克半人马的总军阀。部落希望通过在甜水绿洲取下赫兹鲁尔的头颅，一举粉碎这些入侵者的指挥体系。",h="“赫兹鲁尔”是兽人老兵雷戈萨·死门委派的一项任务，旨在消灭贫瘠之地考尔克半人马的总军阀。部落希望通过在甜水绿洲取下赫兹鲁尔的头颅，一举粉碎这些入侵者的指挥体系。",kw={"血印","半人马","十字路口","死门","赫兹鲁尔","考尔克","甜水","绿洲","雷戈萨"},ang={["faction:Horde"]="保障十字路口和贫瘠之地的安全，需要打破半人马对维持地区旅行的三大主要绿洲的控制。",["race:Orc"]="雷戈萨·死门以兽人的战争观审视这场对抗考尔克的战斗，他指出，虽然半人马凶猛异常，但他们野蛮的狂怒缺乏部落历练出的钢铁纪律。",["race:Tauren"]="世世代代以来，游牧的牛头人饱受半人马带来的流离失所和血腥杀戮之苦；终结赫兹鲁尔这样的军阀，是他们用艰辛换来的复仇。"},sec={{t="斩首考尔克",b="在巴拉克·科多班和维罗戈·德维什死后，贫瘠之地的考尔克半人马中只剩下一位最高酋长：赫兹鲁尔。雷戈萨·死门认为，赫兹鲁尔正是策划半人马在热带草原上肆虐的凶残而狡诈的急先锋。击杀赫兹鲁尔旨在制造混乱，并从根本上瓦解他们的阵型，在他们威胁到部落定居点之前，就将这头暴躁野兽的头颅斩下。"},{t="甜水据点",b="赫兹鲁尔在位于十字路口以南的甜水绿洲指挥着他的战团。控制贫瘠之地为数不多的水源是生存的关键，这使得该绿洲成为考尔克劫掠小队的战略枢纽和集结地。在赫兹鲁尔的领地上与他正面对抗，部落勇士不仅能够拔掉半人马最关键的据点，还能切断他们对该地区南部路线的控制。"},{t="危险的余波",b="虽然雷戈萨称赞了战胜赫兹鲁尔的胜利，并指出半人马缺乏兽人那种专注的纪律，但这次刺杀行动并未让部族平息下来。愤怒的考尔克人没有安静地四散奔逃，而是集结了剩余的兵力，直接对雷戈萨的营地发动了一场孤注一掷的全面进攻，以寻求血腥的复仇。"}},faq={{q="赫兹鲁尔是谁？",a="赫兹鲁尔是活跃在贫瘠之地的考尔克半人马的最高酋长。他被部落公认为凶猛、狡诈且残忍，在甜水绿洲的据点里指挥着各个部族和劫掠者。",al={"赫兹鲁尔是谁","赫兹鲁尔剧情","贫瘠之地半人马领袖"}},{q="在哪里可以找到赫兹鲁尔？",a="赫兹鲁尔在南贫瘠之地的甜水绿洲（十字路口以南）周围巡逻，身边有他的考尔克保镖护卫。",al={"赫兹鲁尔在哪","赫兹鲁尔位置","赫兹鲁尔坐标"}},{q="是谁发布了击杀赫兹鲁尔的任务？",a="雷戈萨·死门，一位驻扎在十字路口以西、通往石爪山脉道路上的小营地里的兽人战士，负责分派此任务。",al={"谁发布赫兹鲁尔任务","雷戈萨·死门任务","赫兹鲁尔任务发布者"}},{q="部落为什么要除掉赫兹鲁尔？",a="考尔克半人马不断威胁着部落的贸易路线和定居点。雷戈萨认为，消灭他们的最高酋长将瓦解部族的团结，并大大削弱他们进行协调作战的能力。",al={"为什么要杀赫兹鲁尔","赫兹鲁尔任务目的","贫瘠之地考尔克威胁"}},{q="赫兹鲁尔被杀后会发生什么？",a="幸存的考尔克人并没有投降，而是陷入了盲目的愤怒之中，联合起来对十字路口以西的雷戈萨·死门的前哨站发动了即时的反击。",al={"赫兹鲁尔死后的反击","接下来会发生什么","杀死赫兹鲁尔的后果"}},{q="赫兹鲁尔与巴拉克和维罗戈有何关系？",a="巴拉克·科多班和维罗戈·德维什是考尔克的中层领导，分别管理着各自的绿洲和战团，而赫兹鲁尔则是统领整个贫瘠之地部族的最高领袖。",al={"巴拉克 维罗戈 赫兹鲁尔","考尔克酋长","三位半人马领袖"}}},fp="16,177,23.354.0,24.339.0,21.276.1,24.147.0,36.133.0,35.135.0,36.193.0,35.158.1,42.157.0"}
P.entries["quest:853"] = {n="药剂师扎玛",s="这项差事需要冒险者从干旱的贫瘠之地奔向雷霆崖，运送一种不稳定的、提炼过的真菌乳剂。药剂师赫布瑞姆需要将这种强效混合物迅速送到他位于灵魂高地阴影深处的同事，药剂师扎玛手中。",h="这项差事需要冒险者从干旱的贫瘠之地奔向雷霆崖，运送一种不稳定的、提炼过的真菌乳剂。药剂师赫布瑞姆需要将这种强效混合物迅速送到他位于灵魂高地阴影深处的同事，药剂师扎玛手中。",kw={"药剂师赫布瑞姆","药剂师扎玛","菌类孢子","预见之池","提炼过的孢子","皇家药剂师学会","灵魂高地","贫瘠之地","雷霆崖"},ang={["faction:Horde"]="贫瘠之地的哨所与雷霆崖高地之间的快速通讯确保了区域供应链保持畅通。",["race:Tauren"]="虽然欢迎他们的新盟友，但传统的牛头人通常对被遗忘者在神圣的预见之池深处酿造的那些冒着泡的奇怪药剂持怀疑态度。",["race:Undead"]="将赫布瑞姆的研究成果送到扎玛手中，加强了皇家药剂师学会在卡利姆多中部尘土飞扬的边境地区所维持的秘密研究网络。"},sec={{t="脆弱的货物",b="在研究了在贫瘠之地的绿洲中茂盛生长的奇特真菌花朵后，药剂师赫布瑞姆将其熬制成了一种精细的乳剂。这种不稳定的药剂在制备后会迅速降解。由于没有时间亲自前往莫高雷，赫布瑞姆将药瓶托付给一名可靠的跑腿，要求其在溶液失去化学效力之前爬上峭壁。"},{t="在萨满的注视下",b="药剂师扎玛的实验室远离莫高雷广阔的平原，隐藏在预见之池内。这个地下洞穴位于灵魂高地神圣高地的深处，与被遗忘者法师和牧师共享。在这里，在牛头人圣殿的地板之下，皇家药剂师学会利用从整个大陆收集的原材料秘密地进行研究。"}},faq={{q="为什么这次运送有时间限制？",a="赫布瑞姆的提炼过的真菌乳剂具有化学不稳定性。如果暴露在外或放置太久，化合物会分解并失去效力，使这种混合物无法用于扎玛的研究工作。",al={"为什么有时间限制","任务计时器","提炼过的孢子计时器"}},{q="我在哪里可以找到药剂师扎玛？",a="药剂师扎玛位于雷霆崖的预见之池内。通往这个洞穴的入口在灵魂高地上有些隐蔽，它通向萨满帐篷的下方。",al={"扎玛在哪里","扎玛的位置","找到扎玛"}},{q="药剂师赫布瑞姆是谁？",a="药剂师赫布瑞姆是一位代表皇家药剂师学会的炼金术师，驻扎在贫瘠之地的十字路口。他分析当地的动植物，以研究卡利姆多的原生生物如何为被遗忘者所用。",al={"赫布瑞姆是谁","赫布瑞姆 十字路口"}},{q="皇家药剂师学会在雷霆崖做什么？",a="作为部落内的盟友，被遗忘者在雷霆崖驻扎了像扎玛这样的代表。他们在预见之池的地下默默运作，分析在卡利姆多各地收集的样本，并维持与其他哨所的补给联系。",al={"为什么被遗忘者在雷霆崖","预见之池的药剂师"}},{q="这些菌类孢子最初是用来做什么的？",a="这些孢子生长在贫瘠之地茂密的绿洲周围，在沙漠中非自然地繁茂生长。赫布瑞姆将它们提炼出来，以研究它们的生物特性和炼金术应用，然后才转交给扎玛。",al={"为什么需要孢子","贫瘠之地真菌的用途"}},{q="如果计时结束会发生什么？",a="如果计时结束，乳剂就会降解变质。你必须回到十字路口找药剂师赫布瑞姆，获取新的一批乳剂运送到雷霆崖。",al={"计时失败","孢子过期"}}},fp="16,153,15.241.0,30.269.0,43.165.0,34.139.0,26.209.0,60.238.0,48.184.0,35.165.0"}
P.entries["quest:854"] = {n="十字路口之旅",s="“十字路口之旅”对于离开莫高雷宁静草场、初出茅庐的部落冒险者来说，是一次关键的成人礼。在陶拉祖营地，牛头人神秘主义者基尔格·锐角会将旅行者派往北方的十字路口，去协助兽人监工索克。这标志着一位新手正式踏上了卡利姆多广阔的前线舞台。",h="“十字路口之旅”对于离开莫高雷宁静草场、初出茅庐的部落冒险者来说，是一次关键的成人礼。在陶拉祖营地，牛头人神秘主义者基尔格·锐角会将旅行者派往北方的十字路口，去协助兽人监工索克。这标志着一位新手正式踏上了卡利姆多广阔的前...",kw={"贫瘠之地","陶拉祖营地","十字路口","大地母亲","基尔格·锐角","索克","雷霆崖"},ang={["faction:Horde"]="该任务突显了雷霆崖各部族与大酋长在卡利姆多中部的先锋部队之间日益加深的合作。",["race:Orc"]="索克急需来自南方的增援，以维持萨尔的斥候在贫瘠之地好不容易建立起来的脆弱防线。",["race:Tauren"]="对于牛头人冒险者来说，这趟旅程标志着他们真正离开了大地母亲神圣台地的庇护，投身于部落更广阔的斗争中。"},sec={{t="离开摇篮",b="对于许多离开故土莫高雷的牛头人来说，陶拉祖营地是他们对贫瘠之地那严酷而多风的平原的第一次真正体验。在穿过莫高雷的山隘后，神秘主义者基尔格·锐角正注视着那些进入干旱草原的旅行者。他察觉到了他们与日俱增的能力，于是指引这些前途无量的勇士沿着尘土飞扬的贸易路线继续向北进发，而不是停留在边缘地带。"},{t="共同的纽带",b="这个任务强调了雷霆崖的牛头人与萨尔建立的新部落之间密不可分的纽带。基尔格指出，两族人民的命运如今已交织在一起，而在十字路口奋力开辟前哨站的兽人们迫切需要增援。当旅行者抵达哨站时，索克会热情地迎接来自高地远方的来客，并急切地想要考验他们的实力，让他们去对抗大草原上的重重险境。"}},faq={{q="谁开启了“十字路口之旅”？",a="该任务由基尔格·锐角提供，他是一位位于南贫瘠之地陶拉祖营地的牛头人，就在通往莫高雷的山隘以东。",al={"谁给予这个任务","任务发布者","基尔格·锐角任务"}},{q="索克在哪里？",a="索克站在十字路口的栅栏墙内，这是部落在贫瘠之地的核心定居点，位于陶拉祖营地沿主路向北的方向。",al={"索克在哪里","索克位置","寻找索克"}},{q="为什么基尔格·锐角会派遣旅行者前往十字路口？",a="基尔格感觉到冒险者已经准备好接受更大的考验，并意识到牛头人和兽人如今共享着交织在一起的命运。十字路口的兽人驻军正承受着来自当地威胁的持续压力，急需有能力的盟友协助。",al={"为什么要去十字路口","十字路口的目的","为什么派我去找兽人"}},{q="十字路口是什么地方？",a="十字路口是部落在卡利姆多中部主要的战略枢纽和贸易站。它建在南北和东西主干道的交汇处，是稳定这片荒蛮前线的集结地。",al={"十字路口是什么","十字路口定居点","贫瘠之地中心"}},{q="只有牛头人能接到这个任务吗？",a="是的。基尔格·锐角只向牛头人提供这次旅程，他欢迎从遥远的雷霆崖远道而来的族人，并派遣他们前去向索克报到。",al={"这是牛头人专属任务吗","部落引导任务"}},{q="通往十字路口的道路上有什么威胁？",a="向北的道路横穿干旱平原，那里居住着具有攻击性的平原陆行鸟、徘徊的草原狮和游荡的刺鬃野猪人部落。沿着踏实的道路走，可以帮助旅行者避开大草原中部那些更有领地意识的捕食者。",al={"路危险吗","从陶拉祖到十字路口的路线"}}},fp="25,171,18.279.0,13.352.0,37.156.0,23.149.0,58.220.0,23.203.0,33.137.0,52.239.0"}
P.entries["quest:855"] = {n="半人马护腕",s="半人马护腕是雷格萨·死亡之门在十字路口以西发布的一项军事悬赏。这项任务要求部落的勇士们削减那些争夺贫瘠之地中部控制权的、极具侵略性的考卡尔半人马的数量。",h="半人马护腕是雷格萨·死亡之门在十字路口以西发布的一项军事悬赏。这项任务要求部落的勇士们削减那些争夺贫瘠之地中部控制权的、极具侵略性的考卡尔半人马的数量。",kw={"贫瘠之地","悬赏","护腕","半人马","十字路口","部落","考卡尔","雷格萨·死亡之门"},ang={["faction:Horde"]="清理考卡尔人可以保护连接奥格瑞玛和雷霆崖的重要补给线。",["race:Orc"]="对于兽人来说，确保杜隆塔尔周边地区免受游牧掠夺者的侵扰，对于建立一个永久且稳定的新家园至关重要。",["race:Tauren"]="半人马给牛头人部落带来了数百年的破坏和种族灭绝；削减他们在贫瘠之地的人数是对他们的一种私人报复。"},sec={{t="平定平原",b="初生的部落正致力于在卡利姆多各处开辟安全领地，而贫瘠之地是连接杜隆塔尔和莫高雷的重要枢纽。然而，狂暴的考卡尔半人马游牧部落争夺着每一处水源和每一片平原，频繁袭击补给车队和侦察小队。兽人战士雷格萨·死亡之门在他位于十字路口以西的掩体中，指挥着防御行动，试图遏制他们无休止的进犯。"},{t="血腥的结算",b="雷格萨要求通过实际行动来证明战果，而不是仅仅依靠空洞的报告。冒险进入考卡尔领地的士兵们被要求带回直接从被杀死的半人马战士身上剥下的护腕。这种残酷的计算方式既是为了核实部落悬赏任务的完成情况，也是为了通过这种计算出的手段警告幸存的考卡尔掠夺者。"}},faq={{q="雷格萨·死亡之门是谁？",a="雷格萨·死亡之门是一位兽人军事指挥官，驻扎在十字路口以西的一处加固掩体中。他负责领导部落在贫瘠之地当地的行动，以压制半人马掠夺团伙。",al={"雷格萨是谁","雷格萨·死亡之门背景故事","谁发布半人马护腕任务"}},{q="为什么部落想要半人马护腕？",a="半人马护腕是战场上杀死敌方战士的无可辩驳的实物证据。收集这些护腕可以确保悬赏奖励只支付给那些对敌对的考卡尔部落造成了实际伤亡的行动。",al={"为什么需要护腕","半人马护腕的作用","收集护腕的原因"}},{q="为什么考卡尔半人马要攻击部落？",a="考卡尔是一个残暴的扩张主义半人马氏族，原产于卡利姆多中部。他们将贫瘠之地视为自己的狩猎场，并强烈反对兽人和牛头人建立的新定居点、营地和联盟。",al={"为什么半人马仇视部落","半人马冲突","考卡尔侵略行为"}},{q="考卡尔半人马在贫瘠之地的什么位置？",a="考卡尔掠夺营地聚集在贫瘠之地中部和南部的各个重要绿洲和崎岖的山脊周围，经常争夺对水源和交通路线的控制权。",al={"在哪寻找半人马","考卡尔分布地点","半人马营地"}},{q="收集这些护腕能阻止考卡尔的袭击吗？",a="不能。虽然雷格萨希望这种杀戮能给幸存的掠夺者以震慑，但他公开怀疑凶残的考卡尔人是否会自愿停止他们嗜血的进攻。",al={"半人马护腕有效吗","半人马会停止进攻吗"}},{q="十字路口的战略价值是什么？",a="十字路口是连接兽人故乡杜隆塔尔、牛头人的莫高雷平原以及通往灰谷的北部路线的中心交通枢纽。中和附近半人马战争团伙的威胁对于保持部落补给线的畅通至关重要。",al={"为什么要保卫十字路口","十字路口的重要性"}}},fp="15,132,19.328.0,21.249.0,25.157.0,40.169.0,39.210.0,53.170.0,54.125.0,46.170.0"}
P.entries["quest:8551"] = {n="船长的箱子",s="海克拜瑞·斯莫特船长过去常往返于藏宝海湾和卡利姆多的棘齿城之间，直到海巨人摧毁了他的船，杀死了船员，并将斯莫特抛弃在救生艇上，让他漂回藏宝海湾。巨人戈拉什抢走了斯莫特的船长宝箱，斯莫特想要把它夺回来。",h="海克拜瑞·斯莫特船长过去常往返于藏宝海湾和卡利姆多的棘齿城之间，直到海巨人摧毁了他的船，杀死了船员，并将斯莫特抛弃在救生艇上，让他漂回藏宝海湾。巨人戈拉什抢走了斯莫特的船长宝箱，斯莫特想要把它夺回来。",kw={"藏宝海湾","戈拉什","棘齿城","海巨人","斯莫特","鼻烟盒","荆棘谷"},sec={{t="落魄船长",b="斯莫特说，往返于卡利姆多棘齿城的航程曾为他带来了成功的事业和良好的声誉。但海巨人终结了一切：他们撞碎了船只，杀害了船员，并把斯莫特扔进一艘救生艇，让他独自飘向藏宝海湾。"},{t="被窃的宝箱",b="巨人戈拉什拿走了斯莫特的船长宝箱，声称他想把它当鼻烟盒用。这个宝箱是斯莫特的最爱，里面有个存着最珍贵宝物的暗格。斯莫特听说戈拉什就在藏宝海湾以东的海岸一带游荡。"},{t="斯莫特的谢意",b="斯莫特对找回宝箱感到欣喜若狂，这在一定程度上平息了他的怒火，但复仇尚未结束。"}},faq={{q="谁是海克拜瑞·斯莫特船长？",a="斯莫特是藏宝海湾的一位船长，曾经往返于此地和卡利姆多的棘齿城，直到海巨人撞碎了他的船并杀死了船员。",al={"斯莫特船长","斯莫特是谁","海克拜瑞·斯莫特"}},{q="是谁拿走了宝箱？",a="海巨人之一的戈拉什拿走了宝箱，并声称他想把它当成鼻烟盒。",al={"谁偷了宝箱","谁有斯莫特的宝箱","戈拉什"}},{q="在哪里可以找到戈拉什？",a="在藏宝海湾以东的海岸沿线。斯莫特听说那个巨人经常在那里出没。",al={"戈拉什在哪里","戈拉什位置","寻找戈拉什"}},{q="为什么斯莫特想要找回宝箱？",a="那是斯莫特最心爱的宝箱，其暗格中存放着他最珍贵的宝藏。",al={"宝箱里有什么","为什么斯莫特想要宝箱"}}},fp="19,310,16.259.0,16.224.0,14.125.1,33.170.0,19.87.0,27.55.0,36.112.0"}
P.entries["quest:8552"] = {n="刺着字母的腰带",s="一条精致的饰带上绣着名字缩写，暗示了其主人就在荆棘谷的某处。找到那位遗失了饰带的海员，就会引出任务“船长的弯刀”。",h="一条精致的饰带上绣着名字缩写，暗示了其主人就在荆棘谷的某处。找到那位遗失了饰带的海员，就会引出任务“船长的弯刀”。",kw={"海克拜瑞·斯莫特","hs","摩卡什","绣字饰带","海巨人","荆棘谷"},sec={{t="有标记的服饰",b="这条精致的饰带下摆绣着“HS”两个字母。只有通过这两个字母，才能追踪到失主。"},{t="斯莫特的线索",b="将服饰归还给海克拜瑞·斯莫特船长，确认它确实属于他。收回饰带揭示了海巨人摩卡什已被击杀，这个残暴的家伙曾多次摧毁船长的船只和船员，他的死让船长感到如释重负。"}},faq={{q="饰带上缝着什么字母？",a="这条精致饰带的下摆绣着“HS”这两个缩写字母。",al={"饰带上的缩写是什么","绣字饰带上的缩写","饰带上的字母"}},{q="下一步任务是什么？",a="当饰带归还给主人后，下一步就是“船长的弯刀”。",al={"绣字饰带之后是什么任务","绣字饰带后续任务","下一步"}}},fp="20,145,16.120.0,21.255.1,40.49.0,26.85.0"}
P.entries["quest:8553"] = {n="船长的弯刀",s="海克拜瑞·斯莫特船长买下了一艘名为“斯莫特复仇号”的新船，想要去猎杀那些夺走他第一艘船的海巨人，结果却再次惨败。巨人们击碎了他的船并杀死了船员，其中一个名叫奈古拉什的巨人还偷走了船长的弯刀。斯莫特船长让你去咨询他以前的船上厨师斯普罗格，以便追踪那个庞然大物。",h="海克拜瑞·斯莫特船长买下了一艘名为“斯莫特复仇号”的新船，想要去猎杀那些夺走他第一艘船的海巨人，结果却再次惨败。巨人们击碎了他的船并杀死了船员，其中一个名叫奈古拉什的巨人还偷走了船长的弯刀。斯莫特船长让你去咨询他以前的船...",kw={"弯刀","海克拜瑞·斯莫特","奈古拉什","海巨人","斯莫特复仇号","斯普罗格","荆棘谷"},sec={{t="第二次灾难",b="在失去第一艘船后，海克拜瑞·斯莫特船长又弄来了一艘名为“斯莫特复仇号”的船，召集了新的船员和补给，发誓要向海巨人复仇。这次行动以灾难告终，巨人们击碎了船只并杀光了船员，只留下斯莫特再次在救生艇上漂流。在那次袭击中，巨人奈古拉什夺走了船长的弯刀。"},{t="咨询厨师",b="为了夺回被偷的佩刀，斯莫特求助于他的厨师。斯普罗格曾在“斯莫特复仇号”上服役，他在那次袭击中幸存了下来，可以帮助找到奈古拉什。"}},faq={{q="海克拜瑞·斯莫特船长在这次袭击中失去了哪艘船？",a="斯莫特买下并装备了一艘名为“斯莫特复仇号”的船，想要猎杀摧毁他第一艘船的巨人们，但那艘船也被巨人们摧毁了。",al={"第二艘船叫什么名字","斯莫特的第二艘船","哪艘船被砸碎了"}},{q="谁偷了船长的弯刀？",a="奈古拉什，那个击碎“斯莫特复仇号”并杀害船员的海巨人之一，夺走了这把武器。",al={"谁有弯刀","哪个巨人拿走了弯刀","谁拿走了斯莫特的弯刀"}},{q="斯普罗格是谁？",a="斯普罗格曾在“斯莫特复仇号”上担任厨师，并在那次摧毁船只的袭击中幸存了下来。斯莫特船长让旅行者去找他，以寻求寻找奈古拉什的帮助。",al={"斯普罗格是谁","斯普罗格的职责","谁是厨师"}},{q="这一步在猎杀海巨人的过程中处于什么位置？",a="这一步紧随“绣字腰带”任务之后，并直接引向“面对奈古拉什”。",al={"之前的任务是什么","下一个任务是什么","弯刀任务线"}}},fp="21,216,17.330.0,19.188.0,60.148.0,32.120.0,16.170.0,58.77.0"}
P.entries["quest:8555"] = {n="守护之龙",s="来自青铜龙军团的阿纳克洛斯会在塔纳利斯与你会面，以结束“流沙节杖”的第一部分任务。那条任务线通往安其拉之门开启之路。",h="来自青铜龙军团的阿纳克洛斯会在塔纳利斯与你会面，以结束“流沙节杖”的第一部分任务。那条任务线通往安其拉之门开启之路。",kw={"阿纳克洛斯","艾索雷葛斯","伊兰尼库斯","安其拉之门","流沙节杖","塔纳利斯","瓦拉斯塔兹"},sec={{t="开始的终结",b="这次会面结束了“流沙节杖”的开篇任务，即通往安其拉之门开启之路的任务线。阿纳克洛斯将与你一起完成这第一部分的收尾工作。"},{t="三位守望者",b="阿纳克洛斯提到了三条巨龙：伊兰尼库斯、瓦拉斯塔兹和艾索雷葛斯，他们作为世界的守望者发挥了举足轻重的作用。阿纳克洛斯说，这些守护者每一位都遭遇了悲剧，无论是死于上古之神的爪牙之手，还是惨遭朋友背叛。阿纳克洛斯承认由于自己的天真，也应承担部分责任，并表示整件事加剧了他对凡人的不信任。他要求你去寻找这三位巨龙，并为最坏的情况做好准备。"}},faq={{q="阿纳克洛斯是谁？",a="阿纳克洛斯是青铜龙军团的一员，你可以在塔纳利斯见到他。",al={"阿纳克洛斯是谁","阿纳克洛斯 塔纳利斯","青铜龙"}},{q="什么是流沙节杖？",a="这是一条通往安其拉之门开启之路的漫长任务线。这次会面结束了它的第一部分。",al={"节杖任务线","流沙节杖","安其拉之门任务线"}}},fp="31,167,24.155.0,18.387.1,18.75.0,42.155.0"}
P.entries["quest:8569"] = {n="往日的贡献：战歌峡谷",s="“战歌峡谷的过往功绩”是一项提交给主城军官的军事嘉奖，旨在表彰在前线服役的士兵。它并非为了庆祝彻底的征服，而是为了向那些在灰谷冲突不断的森林中浴血奋战并做出牺牲的老兵致敬。主城指挥官接收这些徽章是为了提振战争士气，并奖励双方阵营战士的奉献精神。",h="“战歌峡谷的过往功绩”是一项提交给主城军官的军事嘉奖，旨在表彰在前线服役的士兵。它并非为了庆祝彻底的征服，而是为了向那些在灰谷冲突不断的森林中浴血奋战并做出牺牲的老兵致敬。主城指挥官接收这些徽章是为了提振战争士气，并奖励...",kw={"灰谷","准将","奥格瑞玛","过往功绩","牺牲勋带","暴风城","战争使者","战歌峡谷"},ang={["class:Warrior"]="亲历过峡谷残酷肉搏战的前线战斗人员比任何人都更明白，真正的纪律在于即便胜负难料，依然能奋勇作战。",["faction:Alliance"]="对于联盟军队而言，将勋带交给准将重申了他们保卫古老森林并支持暗夜精灵盟友抵抗战歌氏族侵略的誓言。",["faction:Horde"]="对于部落而言，将徽章交给城市的战争使者证明了他们在灰谷为获取木材和生存而流下的鲜血并非白流。"},sec={{t="向阵亡与英勇者致敬",b="银翼要塞与战歌氏族之间的战争很少能带来干净利落、毫不费力的胜利。在灰谷南部边境，冲突总是残酷而血腥的，而且往往无法以决定性的胜利告终。指挥官们认识到，士气不能完全建立在完美的战绩上，因此暴风城、奥格瑞玛以及其他主城的指挥官们设立了旨在表彰坚定服役的荣誉。牺牲勋带正是为了纪念那些不顾胜算、奋勇投身战场的战士。"},{t="后方的战争努力",b="联盟准将和部落战争使者等主城官员负责管理远离前线的动员工作。虽然征兵人员将新鲜血液引向战歌峡谷这样的战场，但军需官和战术家必须照顾好那些经历过残酷战役归来的战士。通过承认在僵局或失败中展现出的个人勇气和牺牲精神，领导层确保了前线士兵始终致力于守住灰谷。"}},faq={{q="这项嘉奖的目的是什么？",a="这项嘉奖旨在表彰在战歌峡谷交战期间竭尽全力的前线战斗人员。主城指挥官接收英勇抗争的证明，以奖励他们的坚韧不拔并提振整个王国的战争士气。",al={"为什么会有过往功绩","过往功绩的目的","过往功绩的含义"}},{q="谁会接收这些牺牲的象征？",a="驻扎在主要城市的高级军事联络官会接收这些物品，包括暴风城等地的联盟准将，以及奥格瑞玛等城市的部落战争使者。",al={"谁接收过往功绩","在哪里提交过往功绩","谁是准将"}},{q="为什么军方要奖励那些没有带来胜利的努力？",a="指挥官们明白，在灰谷森林中的无休止战斗需要付出巨大的代价。奖励奉献和勇气提醒着战斗人员，即使战斗结果并未达到完全的胜利，他们的鲜血和牺牲也是有价值的。",al={"为什么要奖励牺牲勋带","为什么要奖励失败的战斗","英勇抗争的含义"}},{q="战歌峡谷的冲突发生在哪里？",a="战歌峡谷位于灰谷南部边境，兽人的战歌氏族在此采集木材，并与暗夜精灵的银翼要塞的顽强抵抗展开激烈交锋。",al={"战歌峡谷在哪里","战歌峡谷位置","什么是战歌峡谷"}},{q="联盟和部落的成员都可以参与这项工作吗？",a="是的。双方阵营都在各自的主城中维持着相应的军事领导机构，以表彰那些从灰谷血腥伐木冲突中归来的士兵。",al={"这是双方阵营的任务吗","部落或联盟的过往功绩","部落可以提交吗"}},{q="牺牲勋带代表什么？",a="牺牲勋带是授予或佩戴在那些在战歌峡谷经历了激烈冲突的战斗人员身上的徽记，证明了他们为了自己的人民而奋战的坚定意愿。",al={"牺牲勋带背景故事","什么是牺牲勋带","牺牲勋带"}}},fp="29,193,35.318.0,22.329.0,41.158.0,38.119.0,66.147.0,52.141.0,58.104.0,44.131.0"}
P.entries["quest:857"] = {n="众月之泪",s="在南贫瘠之地的群山高处，一个名叫被流放的费格雷的疯狂矮人要求拿回一件在巴尔莫丹发掘出的神秘遗物。这件被称为众月之泪的文物让费格雷陷入了疯狂和偏执，直到双辫将军将其作为不祥的诅咒封存起来。",h="在南贫瘠之地的群山高处，一个名叫被流放的费格雷的疯狂矮人要求拿回一件在巴尔莫丹发掘出的神秘遗物。这件被称为众月之泪的文物让费格雷陷入了疯狂和偏执，直到双辫将军将其作为不祥的诅咒封存起来。",kw={"巴尔莫丹","贫瘠之地","矮人诅咒","费格雷","被流放的费格雷","双辫将军","众月之泪"},ang={["faction:Horde"]="突袭巴尔莫丹以夺回遗物，让部落有机会干扰那些直接侵犯贫瘠之地的矮人行动。"},sec={{t="在巴尔莫丹发掘",b="当矮人们开始开凿南卡利姆多的山脉以建立巴尔莫丹时，众月之泪是他们的第一个重大发现。这件奇异的文物立即对探险队的一名工人费格雷产生了强大而令人不安的影响。"},{t="双辫的隔离措施",b="费格雷声称这件泪滴状遗物赋予了他强大的个人力量，为了保护他的奖品，他甚至对同伴大打出手。双辫将军察觉到了该遗物的腐蚀性影响，将其斥为诅咒之物，从费格雷手中夺走并锁在要塞内。费格雷被驱逐出挖掘营地，只能在悬崖间避难，在痛苦的偏执中发酵，并哀求路过的旅行者帮他偷回来。"},{t="可怕的代价",b="事实证明，双辫的警告比费格雷意识到的要更加直白。在找回众月之泪后，费格雷的喜悦并没有持续多久，因为遗物中潜藏的转化魔法吞噬了他。这件神器并没有让他飞升荣光，反而暴力地将这个矮人变异成了一只野蛮的穴居怪，在他重获奖品的几秒钟后就终结了他的生命。"}},faq={{q="什么是众月之泪？",a="它是一件古老而强大的遗物，由矮人挖掘者在南贫瘠之地的巴尔莫丹早期挖掘工作中发现。它对接触它的人产生一种令人陶醉、腐蚀心智的效果。",al={"什么是众月之泪","众月之泪遗物","巴尔莫丹神器"}},{q="谁是被流放的费格雷？",a="费格雷曾是双辫将军在巴尔莫丹探险队的一名挖掘者。在众月之泪被发现后，费格雷变得偏执且暴力，导致双辫将军将他驱逐出了要塞。",al={"费格雷是谁","费格雷背景故事","矮人费格雷"}},{q="为什么双辫将军要封锁众月之泪？",a="双辫将军认为该文物是一个危险的诅咒，而不是无害的历史发现。在目睹了费格雷对挖掘队同伴施暴后，双辫将这件遗物牢牢地锁在了巴尔莫丹的要塞内。",al={"为什么双辫锁住泪滴","双辫诅咒","巴尔莫丹要塞遗物"}},{q="把众月之泪还给费格雷会发生什么？",a="归还遗物会将费格雷的偏执推向高潮。当他拿到遗物时，后续的结局就会揭晓。",al={"费格雷发生了什么","费格雷结局","归还泪滴"}},{q="众月之泪的魔法被完全理解了吗？",a="双辫将军称其为诅咒，而费格雷则渴望它所赋予的力量。任务中并未解释该遗物魔法的运作机理。",al={"泪滴魔法","众月之泪诅咒","泪滴如何运作"}},{q="如果费格雷是矮人，为什么这是一个部落任务？",a="费格雷是一个躲在贫瘠之地的流放者，他厌恶占领巴尔莫丹的联盟军队。因为部落冒险者天生敌视双辫的挖掘行动，费格雷便请求他们突袭要塞并夺回遗物。",al={"为什么是部落任务","费格雷是部落吗","巴尔莫丹部落"}}},fp="21,100,23.213.0,22.360.0,17.221.1,30.216.0,25.192.0,46.187.0,48.82.1,37.124.1,47.213.0"}
P.entries["quest:8576"] = {n="翻译龙语",s="你把艾索雷葛斯的账本带给了纳瑞安，他必须解读上面写的内容。这是开启安其拉之门道路上的一步。",h="你把艾索雷葛斯的账本带给了纳瑞安，他必须解读上面写的内容。这是开启安其拉之门道路上的一步。",kw={"奥金浮标","艾索雷葛斯","龙语","账本","纳瑞安","塔纳利斯"},sec={{t="将账本交给纳瑞安",b="你把艾索雷葛斯的账本带给了纳瑞安。总得有人解读艾索雷葛斯在上面写了什么，这个任务就落到了纳瑞安头上。"},{t="纳瑞安的解读",b="纳瑞安听说艾索雷葛斯让你制作一个奥金浮标，而账本里就有它的设计图。纳瑞安觉得奇怪，艾索雷葛斯竟然用龙语写下了这些内容，而纳瑞安看不懂龙语。为了搞定它，纳瑞安需要龙语护目镜、一只五百磅的鸡和《龙语傻瓜教程》第二卷，顺序不限。"}},faq={{q="这本账本是谁的？",a="这是艾索雷葛斯的账本。你是把它带给纳瑞安的。",al={"账本的主人","艾索雷葛斯的账本","谁写了账本"}},{q="谁在解读账本？",a="纳瑞安，他必须解读艾索雷葛斯在上面写了什么。",al={"谁翻译账本","纳瑞安","账本交给谁"}}},fp="22,150,26.140.0,23.326.1,19.64.0,21.66.0"}
P.entries["quest:8577"] = {n="斯图沃尔，前任死党",s="在完成“翻译账本”任务后，纳瑞安说如果没有占卜护目镜，什么也翻译不了。纳瑞安的前死党斯图沃尔偷走了它们，你必须找到斯图沃尔并将护目镜拿回来。",h="在完成“翻译账本”任务后，纳瑞安说如果没有占卜护目镜，什么也翻译不了。纳瑞安的前死党斯图沃尔偷走了它们，你必须找到斯图沃尔并将护目镜拿回来。",kw={"格雷迈恩之墙","不起眼的板条箱","账本","纳瑞安","占卜护目镜","银松森林","斯图沃尔","塔纳利斯"},sec={{t="被偷走的护目镜",b="纳瑞安在翻译任何东西之前都需要占卜护目镜。它们很久以前被纳瑞安的前死党斯图沃尔偷走了，那个家伙伤透了纳瑞安的心，然后把纳瑞安遗弃在了这个地方。"},{t="去哪里寻找",b="在一个可靠的水晶球帮助下，纳瑞安已经将斯图沃尔的藏身之处缩小到了两个地方。一个是银松森林的格雷迈恩之墙，另一个是传送门背后的世界。你必须找到斯图沃尔并拿回护目镜。"},{t="斯图沃尔说了什么",b="斯图沃尔无法相信纳瑞安竟然找到了他们。斯图沃尔不会回去的，而且也不想再继续做那种有时候是朋友，有时候是奴隶的关系了。"}},faq={{q="纳瑞安为什么需要占卜护目镜？",a="纳瑞安说没有它们，什么也翻译不了。",al={"为什么需要护目镜","纳瑞安护目镜用途","占卜护目镜用法"}},{q="斯图沃尔是谁？",a="斯图沃尔是纳瑞安的前死党。斯图沃尔偷走了占卜护目镜，伤透了纳瑞安的心，然后把纳瑞安遗弃在了这里。",al={"斯图沃尔是谁","斯图沃尔背景故事","纳瑞安的朋友"}},{q="纳瑞安认为斯图沃尔在哪里？",a="纳瑞安的水晶球将范围缩小到了两个地方：银松森林的格雷迈恩之墙，或是一个遥远的传送门世界。",al={"斯图沃尔在哪里","斯图沃尔位置","格雷迈恩之墙"}},{q="之前要做什么？",a="“翻译账本”，你需要把艾索雷葛斯的账本带给纳瑞安。",al={"前置任务","前置条件","任务前因"}}},fp="18,124,18.223.0,13.191.0,17.140.1,41.66.0,15.154.0,35.112.0,23.79.0"}
P.entries["quest:858"] = {n="打火钥匙",s="“打火”任务始于一位冒险者在北部贫瘠之地发现一名被困在荆棘谷地精伐木机里的特工。由于冲动地劫持了这台机器却没拿启动钥匙，飞行员需要有人从现场主管那里取回打火钥匙，以免身份暴露。",h="“打火”任务始于一位冒险者在北部贫瘠之地发现一名被困在荆棘谷地精伐木机里的特工。由于冲动地劫持了这台机器却没拿启动钥匙，飞行员需要有人从现场主管那里取回打火钥匙，以免身份暴露。",kw={"井架","打火","打火钥匙","棘齿城","伐木机","斯布特瓦夫","贫瘠之地","荆棘谷地精","维兹克兰克"},ang={["faction:Horde"]="荆棘谷地精鲁莽的滥砍滥伐威胁到了贫瘠之地的北部边界，因此任何针对其重型机械的破坏或窃取行为都是令人乐见的干扰。",["profession:Engineering"]="荆棘谷地精的伐木机机械结构显示出惊人的复杂性，利用精细的手臂操纵控制和灵敏的旋转调节器，胜过棘齿城常见的修补技术。"},sec={{t="搞砸的抢劫",b="在北部贫瘠之地繁忙的荆棘谷地精钻探场深处，一场雄心勃勃的抢劫遭遇了尴尬的阻碍。一名受斯布特瓦夫指派的特工成功潜入该公司一台尖端伐木机内，意图劫持机器并研究其内部构造。然而，这个窃贼忽略了一个基本细节：如果没有专用的打火钥匙，转向和移动操纵杆是锁死的。"},{t="高压下的虚张声势",b="当一位心生怀疑的哥布林同事询问这台刚被登上的伐木机为何静止不动时，闯入者惊慌失措，谎称引擎突然故障。被困在玻璃舱盖内，周围又有好奇的工人游荡，劫持者引导前来的冒险者潜入中央井架。现场主管将备用的打火钥匙存放在上层的控制室里，这是在谎言拆穿前唯一的脱身机会。"},{t="企业嫉妒",b="一旦主管被解决，钥匙插入仪表盘转动，窃贼便深深着迷，而非感到羞愧。荆棘谷地精的伐木机控制系统——配备精密手臂运动杠杆、旋转控制器和稳定减震器——远胜于目前在棘齿城运作的笨重机器。回收这台伐木机不再仅仅是为了生存；它是工业间谍活动中无价的战利品。"}},faq={{q="谁在伐木机里？",a="驾驶这台伐木机的是与斯布特瓦夫有关联的一名特工，斯布特瓦夫是驻扎在中立港口城市棘齿城的一名工程师。这名飞行员潜入了荆棘谷地精的营地，意图窃取他们先进的伐木机器之一。",al={"伐木机驾驶员","谁在维兹克兰克伐木机里","维兹克兰克"}},{q="为什么伐木机不能直接开走？",a="没有打火钥匙，伐木机的操纵柱处于机械锁定状态。尽管劫持者成功进入了驾驶舱，但除非钥匙解锁驱动控制装置，否则车辆无法移动或逃离。",al={"为什么需要钥匙","为什么被困住","伐木机被锁住了"}},{q="在哪里可以找到打火钥匙？",a="打火钥匙由负责监督钻探作业的荆棘谷地精主管持有。主管常驻在附近大型木制井架顶端的控制室里。",al={"打火钥匙位置","主管在哪里","如何找到钥匙"}},{q="棘齿城为什么要荆棘谷地精的伐木机？",a="荆棘谷地精拥有远超棘齿城工程师所用标准型号的工程设计。捕获一台完好的机器，可以让当地工匠反向研究其精细的手臂控制装置、速度调节器和稳定系统。",al={"为什么要偷伐木机","棘齿城伐木机","斯布特瓦夫的伐木机"}},{q="斯布特瓦夫是谁？",a="斯布特瓦夫是一名以棘齿城为基地的哥布林工程师兼特工，他监视着荆棘谷地精的掠夺性扩张，并试图获取他们的机械创新成果。",al={"斯布特瓦夫是谁","谁派出了维兹克兰克","棘齿城的斯布特瓦夫"}},{q="伐木机启动后会发生什么？",a="转动钥匙会解锁移动系统，随之立即引发一场疯狂的护送行动，飞行员试图驾驶劫持来的机器冲出敌对的钻探营地，返回安全地带。",al={"打火任务后续","拿到打火钥匙后"}}},fp="8,200,21.239.0,23.341.0,18.277.1,27.188.0,41.172.0,32.122.0,49.215.0,20.152.0,43.201.1"}
P.entries["quest:8584"] = {n="少管闲事",s="纳瑞安有个计划，但他拒绝解释，而且这个计划需要一只五百磅重的鸡。你前往加基森与迪尔格·奎克里弗谈谈，他能帮你开始寻找一只合适的鸟。",h="纳瑞安有个计划，但他拒绝解释，而且这个计划需要一只五百磅重的鸡。你前往加基森与迪尔格·奎克里弗谈谈，他能帮你开始寻找一只合适的鸟。",kw={"五百磅鸡","死亡黑鸡","迪尔格·奎克里弗","加基森","纳瑞安","塔纳利斯"},sec={{t="计划与搜寻",b="纳瑞安不想再让人问起他的生意，那是你永远无法理解的事。计划由他来定，搜寻则交给你。正如他之前所说，计划需要一只五百磅重的鸡，而加基森旅店里的迪尔格·奎克里弗可以为你指明方向。"},{t="迪尔格的回答",b="迪尔格·奎克里弗挠了挠头。他说，那种重量的鸡已经找不到了，虽然他以前确实知道一只，那就是“死亡黑鸡”，而且见过那只鸟的人没一个活下来的。然后他说他有个主意，可能对你们俩都有好处。"}},faq={{q="为什么纳瑞安需要一只五百磅重的鸡？",a="纳瑞安不肯说。他的生意涉及你无法理解的事物，比如心理电子口嚼装置，而且他把计划留给自己，把搜寻任务交给你。",al={"为什么五百磅鸡","纳瑞安的鸡生意","为什么纳瑞安要鸡"}},{q="你需要去加基森找谁谈话？",a="纳瑞安让你去找加基森旅店里的迪尔格·奎克里弗，他会帮你开始寻找合适的鸡。",al={"去哪里","在加基森找谁","迪尔格·奎克里弗在哪里"}},{q="这个任务之前有什么任务？",a="首先要完成“翻译账本”。纳瑞安是在那之后才提出鸡的事情的。",al={"前置任务","先做什么任务","上一步"}},{q="纳瑞安在哪里？",a="纳瑞安在塔纳利斯。",al={"纳瑞安在哪里","纳瑞安位置","纳瑞安在塔纳利斯的位置"}}},fp="30,143,21.284.0,14.214.1,61.175.0,40.98.0,29.86.0,35.32.0"}
P.entries["quest:8586"] = {n="迪尔格的超美味奇美拉肉片",s="加基森的迪尔格·奎克里弗已经完成了他的食谱研究。他还需要你提供二十份地精火箭燃油和二十份石中盐，他要求尽快送达，以免你带给他的肉变质。",h="加基森的迪尔格·奎克里弗已经完成了他的食谱研究。他还需要你提供二十份地精火箭燃油和二十份石中盐，他要求尽快送达，以免你带给他的肉变质。",kw={"奇美拉","肉串","石中盐","迪尔格","加基森","纳瑞安","奎克里弗","火箭燃油"},sec={{t="迪尔格还需要什么",b="迪尔格·奎克里弗亲自准备香料，而你带给他的肉构成了这道菜的主要部分。他现在只缺二十份地精火箭燃油和二十份石中盐。只要有了这些东西，这道禽肉料理就可以送回给纳瑞安了。迪尔格催促你不要拖延，因为他不想让肉变坏。"}},faq={{q="谁需要这些补给品？",a="加基森的迪尔格·奎克里弗要求提供这些材料，以完成他的食谱。",al={"谁开启此任务","谁给予迪尔格的极品奇美拉肉串任务","迪尔格·奎克里弗任务"}},{q="迪尔格·奎克里弗需要什么配料？",a="迪尔格需要二十份地精火箭燃油和二十份石中盐。香料由他自己负责，你提供的肉补齐了剩余的部分。",al={"我需要什么物品","迪尔格肉串的配料","迪尔格的肉串所需物品"}},{q="这道成品菜是给谁的？",a="迪尔格说，一旦你带回了他所要求的材料，这道禽肉料理就可以送回给纳瑞安了。",al={"谁吃这些肉串","谁得到这道禽肉料理","这食物是给谁的"}},{q="交付这些材料后接下来要做什么？",a="接下来的任务是回到纳瑞安那里。",al={"后续任务","做完迪尔格肉串后我该做什么","此任务之后是什么"}}},fp="31,172,22.289.0,28.77.0,44.132.0,38.78.0,46.63.0"}
P.entries["quest:8587"] = {n="向纳瑞安回复",s="迪尔格·奎克里弗信守诺言，交出了那只五百磅重的鸡。你将它带给塔纳利斯的纳瑞安。这是在完成迪尔格的“美味奇美拉肉片”之后进行的。",h="迪尔格·奎克里弗信守诺言，交出了那只五百磅重的鸡。你将它带给塔纳利斯的纳瑞安。这是在完成迪尔格的“美味奇美拉肉片”之后进行的。",kw={"500磅重的鸡","奇美拉","迪尔格·奎克里弗","纳瑞安","塔纳利斯"},sec={{t="信守诺言",b="迪尔格·奎克里弗给了你他承诺的那只鸡，并声称他是个说话算话的地精。他无法想象一个侏儒为什么要一只那么大的鸟，并嘟囔着那一定是为了用来睡觉。从这里开始，你要把它带给塔纳利斯的纳瑞安。"},{t="纳瑞安的欢迎",b="鸡的香味引起了纳瑞安的注意。他用双拳猛击这只鸟，然后大口吃着迪尔格烹饪的食物，声称这是他吃过最美味的鸡。"}},faq={{q="这次运送之前发生了什么？",a="首先是“美味奇美拉肉片”，迪尔格·奎克里弗在那时要求获得火箭燃油和盐来完成他的食谱。",al={"上一个任务","在此之前我做了什么","前置条件"}},{q="谁收到了这只巨大的鸡？",a="塔纳利斯的纳瑞安。",al={"谁接收那只鸡","我把这个交给谁","交任务地点"}},{q="迪尔格为什么要准备一只五百磅重的鸡？",a="迪尔格是在信守诺言，把鸡交出来。他说他永远也不会知道一个侏儒要那么大的鸟做什么。",al={"为什么是500磅重的鸡","那只鸡有什么用","迪尔格的鸡"}},{q="运送鸡之后会发生什么？",a="接下来是“好消息和坏消息”，尽管纳瑞安只有在任务的其他两个部分，即“纳瑞安的占卜眼镜”和“龙语傻瓜教程：第二卷”也完成后，才会提供该任务。",al={"下一个任务","接下来是什么","接下来去哪里"}}},fp="16,169,14.251.0,16.190.1,31.113.0,33.58.0,51.148.0,40.142.0"}
P.entries["quest:8597"] = {n="龙语傻瓜教程",s="纳瑞安记得他把一本书藏在了一个安全的地方。要找到它，你需要先去天涯海滩寻找他坠毁的直升机，然后从那里向南游，前往南海的一座小岛。这是继“翻译账本”之后的任务。",h="纳瑞安记得他把一本书藏在了一个安全的地方。要找到它，你需要先去天涯海滩寻找他坠毁的直升机，然后从那里向南游，前往南海的一座小岛。这是继“翻译账本”之后的任务。",kw={"龙语傻瓜教程","新鲜的泥土堆","直升机","天涯海滩","纳瑞安","南海","塔纳利斯"},sec={{t="藏起来的书",b="纳瑞安说这本书一定会派上用场，而且他把它藏在了一个没有人能找到的地方。他第一次去那里时用的是直升机，但在回来的路上坠毁在了海滩上。他说，正是那次坠机事件给了他超凡的侏儒灵能。残骸就在天涯海滩的某处，从那里向南游就可以了。纳瑞安确信你一眼就能认出那个地方。这本书埋在南海的一座小岛上。"},{t="在岛上",b="在岛上你发现了一堆泥土，但书不见了。泥土堆上放着一张纸条。"}},faq={{q="是谁让你去找这本书的？",a="在你帮他完成“翻译账本”后，纳瑞安会派你去寻找这本书。",al={"谁给予龙语傻瓜教程","纳瑞安任务起始","谁给予此任务"}},{q="纳瑞安在哪里坠毁了他的直升机？",a="纳瑞安说他在藏好书回来的路上坠毁在了一片海滩上。你会在天涯海滩的某处找到残骸。",al={"直升机在哪里","坠毁的直升机位置","天涯海滩坠机"}},{q="书被藏在哪里？",a="纳瑞安说书被埋在南海的一座小岛上。你需要从天涯海滩的残骸处向南游，他说当你看到那个地方时，一切都会显而易见。",al={"书的位置","岛在哪里","往哪里游"}},{q="纳瑞安是如何获得灵能的？",a="纳瑞安说，在海滩上的直升机坠毁事件给了他灵能。",al={"纳瑞安灵能","纳瑞安如何获得灵能"}}},fp="20,193,18.441.0,13.101.1,32.90.0,38.120.0,40.172.0,38.74.0"}
P.entries["quest:8598"] = {n="敲诈",s="在纳瑞安的书本原本应该埋藏的那个新挖开的土堆处，留着一封勒索信。你把这封信带回塔纳利斯交给了纳瑞安。此任务紧接在《龙语傻瓜教程》之后。",h="在纳瑞安的书本原本应该埋藏的那个新挖开的土堆处，留着一封勒索信。你把这封信带回塔纳利斯交给了纳瑞安。此任务紧接在《龙语傻瓜教程》之后。",kw={"龙语傻瓜教程","新挖开的土堆","纳瑞安","勒索","勒索信","塔纳利斯"},sec={{t="拼凑的便条",b="这封信是由许多不同字体的碎纸片拼贴在羊皮纸上组成的。它称呼纳瑞安为侏儒，并告诉他，他的珍贵书籍现在落在了写信者的手中，只有严格按照信上的指示去做，他才能重新见到这本书。详细的说明写满了三页纸，结尾要求带上钱并独自前来。你把这封信带给了塔纳利斯的纳瑞安。"},{t="纳瑞安的回答",b="纳瑞安询问出了什么事，然后读了这封信，他的脸色变得通红。他非常愤怒，竟然有人敢抢走他的书，他发誓要让那些罪魁祸首知道得罪一位灵能侏儒会有什么后果。"}},faq={{q="勒索信提出了什么要求？",a="写信的人声称他们拿到了纳瑞安的书，只有当他完全按照他们的要求去做时，他才能再次见到它。说明长达三页，最后要求支付金钱并让他独自赴约。信中没有说明是谁写的。",al={"便条上写了什么","勒索信内容","是谁拿走了书"}},{q="这一步接下来会导向哪里？",a="一旦将这封信交给塔纳利斯的纳瑞安，任务线就会继续进行到“诱饵！”",al={"勒索之后是什么","勒索后续","勒索之后的下一个任务"}},{q="在找到勒索信之前发生了什么？",a="《龙语傻瓜教程》排在它之前，那是对纳瑞安埋藏的书籍的搜寻，最终止步于那个新挖开的土堆。",al={"前置任务","勒索的前置条件"}}},fp="6,199,21.346.0,15.198.1,34.234.0,31.91.0,41.103.0"}
